$doc->addScriptDeclaration(<<<'JS'
(function(){
  'use strict';
  if (window.__MLE_V64_SNAPSHOT_HISTORY__) { return; }
  window.__MLE_V64_SNAPSHOT_HISTORY__ = true;
  function qsa(sel, root){ return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function toInt(v, fallback){ var n = parseInt(String(v || ''), 10); return isFinite(n) ? n : fallback; }
  function sync(shell){
    if (!shell) { return; }
    var step = toInt(shell.getAttribute('data-mle-snapshot-history-step'), 9);
    var visible = toInt(shell.getAttribute('data-mle-snapshot-history-visible'), step);
    var rows = qsa('[data-mle-snapshot-history-row]', shell);
    var collapsed = String(shell.getAttribute('data-mle-snapshot-history-collapsed') || '') === '1';
    var list = shell.querySelector('.mle-snapshot-history__list');
    var pager = shell.querySelector('[data-mle-snapshot-history-pager]');
    var toggle = shell.querySelector('[data-mle-v29-snapshot-toggle]');
    if (collapsed) {
      rows.forEach(function(row){ row.setAttribute('hidden','hidden'); row.setAttribute('aria-hidden','true'); });
      if (list) { list.setAttribute('hidden','hidden'); list.setAttribute('aria-hidden','true'); }
      if (pager) { pager.setAttribute('hidden','hidden'); pager.setAttribute('aria-hidden','true'); }
      if (toggle) { toggle.setAttribute('aria-expanded','false'); var label = toggle.querySelector('span'); if (label) { label.textContent = 'Open Completed Prediction Browser'; } }
      var collapsedCount = shell.querySelector('[data-mle-snapshot-history-count]');
      if (collapsedCount) { collapsedCount.textContent = '0'; }
      return;
    }
    if (list) { list.removeAttribute('hidden'); list.setAttribute('aria-hidden','false'); }
    if (pager) { pager.removeAttribute('hidden'); pager.setAttribute('aria-hidden','false'); }
    if (toggle) { toggle.setAttribute('aria-expanded','true'); var openLabel = toggle.querySelector('span'); if (openLabel) { openLabel.textContent = 'Collapse Completed Prediction Browser'; } }
    rows.forEach(function(row, idx){
      var show = idx < visible;
      if (show) { row.removeAttribute('hidden'); row.setAttribute('aria-hidden','false'); }
      else { row.setAttribute('hidden','hidden'); row.setAttribute('aria-hidden','true'); }
    });
    var count = shell.querySelector('[data-mle-snapshot-history-count]');
    if (count) { count.textContent = String(Math.min(visible, rows.length)); }
    var more = shell.querySelector('[data-mle-snapshot-history-action="more"]');
    var less = shell.querySelector('[data-mle-snapshot-history-action="less"]');
    if (more) { if (visible >= rows.length) { more.setAttribute('hidden','hidden'); } else { more.removeAttribute('hidden'); } }
    if (less) { if (visible > step) { less.removeAttribute('hidden'); } else { less.setAttribute('hidden','hidden'); } }
  }
  function init(){ qsa('[data-mle-snapshot-history-shell]').forEach(sync); }
  document.addEventListener('click', function(ev){
    var btn = ev.target && ev.target.closest ? ev.target.closest('[data-mle-snapshot-history-action]') : null;
    if (!btn) { return; }
    var shell = btn.closest ? btn.closest('[data-mle-snapshot-history-shell]') : null;
    if (!shell) { return; }
    ev.preventDefault();
    var action = String(btn.getAttribute('data-mle-snapshot-history-action') || '');
    shell.setAttribute('data-mle-snapshot-history-collapsed', '0');
    var step = toInt(shell.getAttribute('data-mle-snapshot-history-step'), 9);
    var visible = toInt(shell.getAttribute('data-mle-snapshot-history-visible'), step);
    var total = qsa('[data-mle-snapshot-history-row]', shell).length;
    if (action === 'more') { visible = Math.min(total, visible + step); }
    if (action === 'less') { visible = step; }
    shell.setAttribute('data-mle-snapshot-history-visible', String(visible));
    sync(shell);
  }, false);
  document.addEventListener('click', function(ev){
    var toggle = ev.target && ev.target.closest ? ev.target.closest('[data-mle-v29-snapshot-toggle]') : null;
    if (!toggle) { return; }
    var shell = toggle.closest ? toggle.closest('[data-mle-snapshot-history-shell]') : null;
    if (!shell) { return; }
    ev.preventDefault();
    var collapsed = String(shell.getAttribute('data-mle-snapshot-history-collapsed') || '') === '1';
    shell.setAttribute('data-mle-snapshot-history-collapsed', collapsed ? '0' : '1');
    sync(shell);
  }, false);
  function syncRunGroupBrowser(shell){
    if (!shell) { return; }
    var step = toInt(shell.getAttribute('data-mle-run-group-step'), 3);
    var visible = toInt(shell.getAttribute('data-mle-run-group-visible'), step);
    var groups = qsa('[data-mle-run-group-row]', shell);
    groups.forEach(function(group, idx){
      var show = idx < visible;
      if (show) { group.removeAttribute('hidden'); group.setAttribute('aria-hidden','false'); }
      else { group.setAttribute('hidden','hidden'); group.setAttribute('aria-hidden','true'); }
    });
    var count = shell.querySelector('[data-mle-run-group-count]');
    if (count) { count.textContent = String(Math.min(visible, groups.length)); }
    var more = shell.querySelector('[data-mle-run-group-action="more"]');
    var less = shell.querySelector('[data-mle-run-group-action="less"]');
    if (more) { if (visible >= groups.length) { more.setAttribute('hidden','hidden'); } else { more.removeAttribute('hidden'); } }
    if (less) { if (visible > step) { less.removeAttribute('hidden'); } else { less.setAttribute('hidden','hidden'); } }
    var shown = groups.filter(function(group){ return group.getAttribute('hidden') === null; });
    var anyOpen = shown.some(function(group){ return !!group.open; });
    var collapseAll = shell.querySelector('[data-mle-run-group-action="collapse-all"]');
    var expandAll = shell.querySelector('[data-mle-run-group-action="expand-all"]');
    if (collapseAll) { collapseAll.disabled = !anyOpen; collapseAll.setAttribute('aria-disabled', anyOpen ? 'false' : 'true'); }
    if (expandAll) { expandAll.disabled = shown.length === 0; expandAll.setAttribute('aria-disabled', shown.length === 0 ? 'true' : 'false'); }
  }
  function initRunGroups(){ qsa('[data-mle-run-group-browser]').forEach(syncRunGroupBrowser); }
  document.addEventListener('click', function(ev){
    var btn = ev.target && ev.target.closest ? ev.target.closest('[data-mle-run-group-action]') : null;
    if (!btn) { return; }
    var shell = btn.closest ? btn.closest('[data-mle-run-group-browser]') : null;
    if (!shell) { return; }
    ev.preventDefault();
    var action = String(btn.getAttribute('data-mle-run-group-action') || '');
    var step = toInt(shell.getAttribute('data-mle-run-group-step'), 3);
    var visible = toInt(shell.getAttribute('data-mle-run-group-visible'), step);
    var groups = qsa('[data-mle-run-group-row]', shell);
    if (action === 'more') { visible = Math.min(groups.length, visible + step); }
    if (action === 'less') { visible = step; }
    if (action === 'collapse-all') { groups.forEach(function(group){ if (group.getAttribute('hidden') === null) { group.open = false; } }); }
    if (action === 'expand-all') { groups.forEach(function(group){ if (group.getAttribute('hidden') === null) { group.open = true; } }); }
    shell.setAttribute('data-mle-run-group-visible', String(visible));
    syncRunGroupBrowser(shell);
  }, false);
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initRunGroups); } else { initRunGroups(); }
}());
JS);

