  window.__MLE_V80_WORLD_CLASS_COMPACT_PRINT__ = true;
  function qsa(sel, root){ return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function closest(el, sel){ while (el && el !== document) { if (el.matches && el.matches(sel)) { return el; } el = el.parentNode; } return null; }
  function text(el){ return el ? String(el.textContent || '').replace(/\s+/g, ' ').trim() : ''; }
  function cleanTitle(value){ return String(value || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim(); }
  function removeForPrint(root){
    qsa('script, style, form, button, input, select, textarea, nav, iframe, .settings-toggle, .settings-panel, .btn-print, .mle-print-all-btn, .mle-print-header-btn, .mle-pending-prediction-row__delete-form, .sdi-delete-form, .mle-admin-only, .mle-debug, .mle-support-reference, .mle-work-notice-admin, .mle-work-notice-admin-link', root).forEach(function(n){ if(n && n.parentNode){ n.parentNode.removeChild(n); } });
    qsa('[hidden]', root).forEach(function(n){ if (n && n.classList && n.classList.contains('mle-print-settings-reference')) { n.removeAttribute('hidden'); } });
  }
  function forceCompactPrintReference(root){
    qsa('[data-mle-print-settings-reference], .mle-print-settings-reference', root).forEach(function(n){
      try { n.removeAttribute('hidden'); n.setAttribute('aria-hidden','false'); n.style.display = 'block'; n.style.visibility = 'visible'; n.style.opacity = '1'; n.style.height = 'auto'; n.style.maxHeight = 'none'; n.style.overflow = 'visible'; } catch(e) {}
    });
  }
  function cleanClone(node){
    var clone = node.cloneNode(true);
    removeForPrint(clone);
    forceCompactPrintReference(clone);
    return clone;
  }
  function countLabel(count){ return String(count || 0) + ((count || 0) === 1 ? ' prediction' : ' predictions'); }
  function buildSubtitle(title, count){
    var clean = cleanTitle(title || 'LottoExpert Predictions');
    return countLabel(count) + ' | Pre-draw reference | Printed ' + (new Date()).toLocaleString();
