    try {
      d.title = safeTitle;
      if (d.head) { while (d.head.firstChild) { d.head.removeChild(d.head.firstChild); } }
      if (d.body) { while (d.body.firstChild) { d.body.removeChild(d.body.firstChild); } }
      var head = d.head || d.getElementsByTagName('head')[0];
      if (!head) { head = d.createElement('head'); d.documentElement.insertBefore(head, d.body || null); }
      var bodyEl = d.body || d.getElementsByTagName('body')[0];
      if (!bodyEl) { bodyEl = d.createElement('body'); d.documentElement.appendChild(bodyEl); }
      var meta = d.createElement('meta');
      meta.setAttribute('charset', 'utf-8');
      head.appendChild(meta);
      var style = d.createElement('style');
      style.type = 'text/css';
      style.textContent = [
        '@page{size:auto;margin:7mm;}',
        'body{font-family:Arial,Helvetica,sans-serif;color:#0f172a;margin:0;background:#fff;font-size:9.4px;line-height:1.22;}',
        '.mle-v80-print-shell{padding:0;}',
        '.mle-v80-print-header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;border-bottom:2px solid #0A1A33;padding:0 0 6px;margin:0 0 7px;}',
        '.mle-v80-print-brand{font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#1C66FF;margin:0 0 2px;}',
