        '.extra,.mle-ball--extra{border-color:#ef4444!important;color:#991b1b!important;}',
        '.mle-daily-digit-pills,.mle-ball-list,.mle-snapshot-history__balls{display:flex!important;flex-wrap:wrap!important;gap:2px!important;margin:2px 0!important;}',
        'p,ul,ol{margin:2px 0!important;} small{font-size:8px!important;color:#64748b!important;} ',
        'form,button,input,select,textarea,.settings-toggle,.btn-print,.mle-print-all-btn,.mle-print-header-btn,.mle-v27-section-toggle-label{display:none!important;}',
        '.mle-v80-print-footer{margin-top:6px;border-top:1px solid #e2e8f0;padding-top:4px;font-size:7.8px;color:#64748b;}',
        '@media print{body{margin:0}.mle-v80-print-section{break-inside:avoid-page;page-break-inside:avoid}.mle-v80-print-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;}}'
      ].join('');
      head.appendChild(style);
      var shell = d.createElement('div');
      shell.className = 'mle-v80-print-shell';
      bodyEl.appendChild(shell);
      var header = d.createElement('header');
      header.className = 'mle-v80-print-header';
      shell.appendChild(header);
      var left = d.createElement('div');
      header.appendChild(left);
      var brand = d.createElement('div');
      brand.className = 'mle-v80-print-brand';
      brand.textContent = 'LottoExpert.net';
      left.appendChild(brand);
      var h1 = d.createElement('h1');
      h1.className = 'mle-v80-print-title';
      h1.textContent = safeTitle;
      left.appendChild(h1);
      var sub = d.createElement('div');
      sub.className = 'mle-v80-print-subtitle';
      sub.textContent = safeMeta;
      left.appendChild(sub);
      var badge = d.createElement('div');
      badge.className = 'mle-v80-print-count';
      badge.textContent = countLabel(nodes.length);
      header.appendChild(badge);
      var grid = d.createElement('div');
      grid.className = 'mle-v80-print-grid';
      shell.appendChild(grid);
      nodes.forEach(function(node){
        var section = d.createElement('section');
        section.className = 'mle-v80-print-section';
        section.appendChild(d.importNode(node, true));
        grid.appendChild(section);
      });
      var footer = d.createElement('footer');
      footer.className = 'mle-v80-print-footer';
      footer.textContent = 'Pre-draw prediction sheet. Run setup shows the key blend, window, draw count, confidence rank, confidence score, method, and original batch/run reference saved with each prediction.';
      shell.appendChild(footer);
      w.focus();
      setTimeout(function(){ try { w.print(); } catch(e) {} }, 250);
      return true;
    } catch (ex) {
      try { w.close(); } catch(e2) {}
      return false;
    }
  }
  function printCard(btn){
    var card = closest(btn, '.prediction-card');
    if (!card) { return false; }
    var group = closest(card, '.lottery-group');
    var title = text(group && group.querySelector('h2')) || text(card.querySelector('.card-title,.prediction-card-title,strong')) || 'LottoExpert Pre-Draw Prediction Sheet';
    return printHtml(title, [cleanClone(card)], buildSubtitle(title, 1));
  }
  function printGroup(btn){
    var group = closest(btn, '.lottery-group');
    if (!group) { return false; }
    var cards = qsa('.prediction-card:not(.prediction-placeholder)', group).filter(function(card){ return text(card) !== ''; });
    if (!cards.length) { return false; }
    var title = text(group.querySelector('h2')) || 'LottoExpert Pre-Draw Prediction Sheet';
    return printHtml(title, cards.map(cleanClone), buildSubtitle(title, cards.length));
  }
  function printPending(btn){
    var shell = closest(btn, 'details, .mle-pending-predictions-dropdown, .mle-advisory-card') || document;
    var rows = qsa('.mle-pending-prediction-row', shell).filter(function(row){ return row.offsetParent !== null || row.getAttribute('hidden') === null; });
    if (!rows.length) { rows = qsa('.mle-pending-prediction-row', shell); }
    if (!rows.length) { return false; }
