(function(){
  'use strict';
  if (window.__MLE_V27_PREDICTION_SECTION_TOGGLE_MEMORY__) { return; }
  window.__MLE_V27_PREDICTION_SECTION_TOGGLE_MEMORY__ = true;
  var PREFIX = 'mle:v27:predictionOrderSection:';
  var TARGET_SELECTORS = [
    'details.mle-pending-recommendations',
    'details.mle-pending-predictions-dropdown',
    'details.mle-results-detail',
    'details.mle-run-group-browser__group',
    'details.mle-prediction-order-section',
    'details[data-mle-prediction-order-section]'
  ].join(',');
  function qsa(sel, root){ return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function closest(el, sel){ while (el && el !== document) { if (el.matches && el.matches(sel)) { return el; } el = el.parentNode; } return null; }
  function clean(v){ return String(v || '').replace(/\s+/g, ' ').replace(/[^a-zA-Z0-9:_ -]/g, '').trim().slice(0, 90); }
  function summaryText(d){ var sm = d ? d.querySelector(':scope > summary') : null; return clean(sm ? sm.textContent : ''); }
  function isPredictionOrderDetails(d){
    if (!d || String(d.tagName || '').toLowerCase() !== 'details') { return false; }
    if (d.matches && d.matches(TARGET_SELECTORS)) { return true; }
    var text = summaryText(d).toLowerCase();
    return text.indexOf('pre-draw') !== -1 || text.indexOf('post-draw') !== -1 || text.indexOf('performance order') !== -1 || text.indexOf('recommendation order') !== -1 || text.indexOf('pending prediction') !== -1;
  }
  function sectionKey(d){
    var card = closest(d, '[data-mle-lottery-id], [data-mle-advisory-card], .mle-advisory-card, .mle-optimization-card, [id^="mle-lottery-card-"]');
    var cardKey = card ? clean(card.getAttribute('data-mle-lottery-id') || card.getAttribute('data-lottery-id') || card.id || card.getAttribute('aria-label') || 'card') : 'page';
    var ownKey = clean(d.getAttribute('data-mle-prediction-order-section') || d.id || d.getAttribute('data-mle-run-group-index') || d.getAttribute('data-mle-run-group-row') || summaryText(d));
    if (!ownKey) { ownKey = String(qsa('details', card || document).indexOf(d)); }
    return PREFIX + cardKey + ':' + ownKey;
  }
  function getStored(d){ try { return window.localStorage.getItem(sectionKey(d)); } catch(e) { return null; } }
  function setStored(d, value){ try { window.localStorage.setItem(sectionKey(d), value); } catch(e) {} }
  function setOpen(d, open){
    if (!d || !isPredictionOrderDetails(d)) { return; }
    try { d.open = !!open; } catch(e1) {}
    if (open) { try { d.setAttribute('open', 'open'); } catch(e2) {} }
    else { try { d.removeAttribute('open'); } catch(e3) {} }
    try { d.setAttribute('aria-expanded', open ? 'true' : 'false'); } catch(e4) {}
    try { d.setAttribute('data-mle-prediction-section-state', open ? 'open' : 'closed'); } catch(e5) {}
  }
  function decorate(d){
    if (!d || d.getAttribute('data-mle-v27-toggle-ready') === '1') { return; }
    d.setAttribute('data-mle-v27-toggle-ready', '1');
    d.setAttribute('data-mle-prediction-order-section', d.getAttribute('data-mle-prediction-order-section') || summaryText(d) || 'prediction-section');
    var sm = d.querySelector(':scope > summary');
    if (sm && !sm.querySelector('.mle-v27-section-toggle-label')) {
      var label = document.createElement('span');
      label.className = 'mle-v27-section-toggle-label';
      label.setAttribute('aria-hidden', 'true');
      label.textContent = d.open ? 'Collapse' : 'Expand';
      sm.appendChild(label);
    }
  }
  function syncLabel(d){
    var label = d && d.querySelector ? d.querySelector(':scope > summary .mle-v27-section-toggle-label') : null;
    if (label) { label.textContent = d.open ? 'Collapse' : 'Expand'; }
  }
  // [[MLE_V118_PRE_CONFIDENCE_OPEN_DEFAULT]]
  // Keep the current pre-draw confidence recommendation panel open by default.
  // Keep all other prediction-order panels closed on page load.
  function shouldDefaultOpen(d){
    var key = clean(d && d.getAttribute ? d.getAttribute('data-mle-prediction-order-section') : '');
    return key === 'pending-confidence-order';
  }
  function apply(root){
    qsa('details', root).forEach(function(d){
      if (!isPredictionOrderDetails(d)) { return; }
      decorate(d);
      setOpen(d, shouldDefaultOpen(d));
      syncLabel(d);
    });
  }
  document.addEventListener('toggle', function(ev){
    var d = ev.target;
    if (!isPredictionOrderDetails(d)) { return; }
    decorate(d);
    setStored(d, d.open ? 'open' : 'closed');
    syncLabel(d);
  }, true);
  document.addEventListener('click', function(ev){
    var summary = closest(ev.target, 'summary');
    var d = summary && summary.parentNode && String(summary.parentNode.tagName || '').toLowerCase() === 'details' ? summary.parentNode : null;
    if (!isPredictionOrderDetails(d)) { return; }
    window.setTimeout(function(){ setStored(d, d.open ? 'open' : 'closed'); syncLabel(d); }, 40);
  }, true);
  var style = document.createElement('style');
  style.textContent = 'details[data-mle-prediction-order-section]>summary{display:flex!important;align-items:center!important;justify-content:space-between!important;gap:10px!important;} .mle-v27-section-toggle-label{display:inline-flex!important;align-items:center!important;justify-content:center!important;padding:5px 10px!important;border-radius:999px!important;border:1px solid currentColor!important;font-size:11px!important;font-weight:900!important;text-transform:uppercase!important;letter-spacing:.04em!important;white-space:nowrap!important;opacity:.9!important;}';
  try { (document.head || document.documentElement).appendChild(style); } catch(e) {}
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', function(){ apply(document); window.setTimeout(function(){ apply(document); }, 500); }); }
  else { apply(document); window.setTimeout(function(){ apply(document); }, 500); }
  window.addEventListener('load', function(){ apply(document); }, false);
}());
JS);



