$doc->addScriptDeclaration(<<<'JS'
(function(){
  'use strict';
  if (window.__MLE_V76_DEFAULT_COLLAPSED_WORKSPACE__) { return; }
  window.__MLE_V76_DEFAULT_COLLAPSED_WORKSPACE__ = true;
  var PREFIX = 'mle:v76:lotteryCollapsed:';
  function qsa(sel, root){ return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function closest(el, sel){ while (el && el !== document) { if (el.matches && el.matches(sel)) { return el; } el = el.parentNode; } return null; }
  function keyFor(outer){
    var id = outer ? (outer.getAttribute('data-outer-lottery-id') || outer.id || '') : '';
    return PREFIX + String(id || 'unknown');
  }
  function oldKeyFor(outer){
    var id = outer ? (outer.getAttribute('data-outer-lottery-id') || '') : '';
    return id ? ('mle_outer_collapsed_' + id) : '';
  }
  function storedState(outer){
    try {
      var modern = window.localStorage.getItem(keyFor(outer));
      if (modern === 'open' || modern === 'closed') { return modern; }
      var oldKey = oldKeyFor(outer);
      if (oldKey) {
        var oldVal = window.localStorage.getItem(oldKey);
        if (oldVal === '0' || oldVal === 'open') { return 'open'; }
        if (oldVal === '1' || oldVal === 'closed') { return 'closed'; }
      }
    } catch(e) {}
    return '';
  }
  function persistState(outer, state){
    try {
      window.localStorage.setItem(keyFor(outer), state);
      var oldKey = oldKeyFor(outer);
      if (oldKey) { window.localStorage.setItem(oldKey, state === 'closed' ? '1' : '0'); }
    } catch(e) {}
  }
  function setOuterCollapsed(outer, collapsed, persist){
    if (!outer) { return; }
    var closed = !!collapsed;
    try { outer.classList.toggle('mle-lottery-outer--collapsed', closed); } catch(e1) {}
    try { outer.setAttribute('data-mle-collapse-state', closed ? 'closed' : 'open'); } catch(e2) {}
    var header = outer.querySelector('.mle-lottery-outer-header');
    if (header) {
      try { header.setAttribute('aria-expanded', closed ? 'false' : 'true'); } catch(e3) {}
    }
    if (persist) { persistState(outer, closed ? 'closed' : 'open'); }
  }
  function hashTargetOuter(){
    var hash = String(window.location.hash || '');
    if (hash.length < 2) { return null; }
    var target = null;
    try { target = document.getElementById(decodeURIComponent(hash.substring(1))); } catch(e) { target = document.getElementById(hash.substring(1)); }
    return target ? closest(target, '.mle-lottery-outer') : null;
  }
  function initOuterState(){
    var hashOuter = hashTargetOuter();
    qsa('.mle-lottery-outer[data-outer-lottery-id]').forEach(function(outer){
      var stored = storedState(outer);
      if (hashOuter && hashOuter === outer) { setOuterCollapsed(outer, false, false); return; }
      if (stored === 'open') { setOuterCollapsed(outer, false, false); return; }
      setOuterCollapsed(outer, true, false);
    });
  }
  function collapseAll(collapsed){
    qsa('.mle-lottery-outer[data-outer-lottery-id]').forEach(function(outer){ setOuterCollapsed(outer, !!collapsed, true); });
    if (collapsed) {
      qsa('details.mle-pending-recommendations,details.mle-pending-predictions-dropdown,details.mle-results-detail,details.mle-run-group-browser__group,details.mle-prediction-order-section,details[data-mle-prediction-order-section],details.mle-v53-shared-skai-current__audit,details.mle-v53-shared-skai-current__meaning,details.mle-evidence-status-legend-v65h,details.mle-v56-history-verify__details,details.mle-evidence-explain,details.mle-rs-guide,details.mle-sp-settings-detail').forEach(function(d){ try { d.open = false; d.removeAttribute('open'); } catch(e) {} });
    }
    return false;
  }
  document.addEventListener('click', function(ev){
    var header = ev.target && ev.target.closest ? ev.target.closest('.mle-lottery-outer-header') : null;
    if (!header) { return; }
    if (ev.target && ev.target.closest && ev.target.closest('a,button,input,select,textarea,label,form')) { return; }
    var outer = closest(header, '.mle-lottery-outer');
    if (!outer) { return; }
    ev.preventDefault();
    setOuterCollapsed(outer, !outer.classList.contains('mle-lottery-outer--collapsed'), true);
  }, true);
  document.addEventListener('click', function(ev){
    var link = ev.target && ev.target.closest ? ev.target.closest('a[href^="#"]') : null;
    if (!link) { return; }
    var href = String(link.getAttribute('href') || '');
    if (href.length < 2) { return; }
    window.setTimeout(function(){
      var target = null;
      try { target = document.getElementById(decodeURIComponent(href.substring(1))); } catch(e) { target = document.getElementById(href.substring(1)); }
      var outer = target ? closest(target, '.mle-lottery-outer') : null;
      if (outer) { setOuterCollapsed(outer, false, false); }
    }, 0);
  }, true);
  window.skaiLotteryCollapseAll = collapseAll;
  window.mleVisibleCollapseAll = collapseAll;
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initOuterState); }
  else { initOuterState(); }
  window.addEventListener('hashchange', function(){ var outer = hashTargetOuter(); if (outer) { setOuterCollapsed(outer, false, false); } }, false);
}());
JS);

