if (!function_exists('mylottoexpertWorkNoticePath')) {
    function mylottoexpertWorkNoticePath()
    {
        return JPATH_ADMINISTRATOR . '/logs/mylottoexpert_work_notice.json';
    }
}
if (!function_exists('mylottoexpertWorkNoticeDefaultState')) {
    function mylottoexpertWorkNoticeDefaultState()
    {
        return array(
            'enabled' => 0,
            'message' => 'We are currently improving the MyLottoExpert workspace. You may notice some sections changing, refreshing, or being adjusted while we complete updates. Your saved predictions, results, and history remain intact.',
            'updated_at' => '',
            'updated_by' => 0
        );
    }
}
if (!function_exists('mylottoexpertWorkNoticeRead')) {
    function mylottoexpertWorkNoticeRead()
    {
        $state = mylottoexpertWorkNoticeDefaultState();
        $path = mylottoexpertWorkNoticePath();
        if (is_file($path)) {
            $raw = (string)@file_get_contents($path);
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                $state = array_merge($state, $decoded);
            }
        }
        $state['enabled'] = !empty($state['enabled']) ? 1 : 0;
        $state['message'] = trim((string)($state['message'] ?? ''));
        if ($state['message'] === '') {
            $state['message'] = mylottoexpertWorkNoticeDefaultState()['message'];
        }
        return $state;
    }
}
if (!function_exists('mylottoexpertWorkNoticeWrite')) {
    function mylottoexpertWorkNoticeWrite(array $state)
    {
        $path = mylottoexpertWorkNoticePath();
        $dir = dirname($path);
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        $payload = json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if ($payload === false) {
            return false;
        }
        return @file_put_contents($path, $payload, LOCK_EX) !== false;
    }
}

if (!function_exists('mylottoexpertResearchRoutingPath')) {
    function mylottoexpertResearchRoutingPath()
    {
        return JPATH_ADMINISTRATOR . '/logs/mylottoexpert_research_routing.json';
    }
}
if (!function_exists('mylottoexpertResearchRoutingDefaultState')) {
    function mylottoexpertResearchRoutingDefaultState()
    {
        return array(
            'mode' => 'prediction_first',
            'updated_at' => '',
            'updated_by' => 0
        );
    }
}
if (!function_exists('mylottoexpertResearchRoutingAllowedModes')) {
    function mylottoexpertResearchRoutingAllowedModes()
    {
        return array('prediction_first', 'balanced_research', 'deep_research');
    }
}
if (!function_exists('mylottoexpertResearchRoutingRead')) {
    function mylottoexpertResearchRoutingRead()
    {
        $state = mylottoexpertResearchRoutingDefaultState();
        $path = mylottoexpertResearchRoutingPath();
        if (is_file($path)) {
            $raw = (string)@file_get_contents($path);
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) { $state = array_merge($state, $decoded); }
        }
        $mode = strtolower(trim((string)($state['mode'] ?? 'prediction_first')));
        if (!in_array($mode, mylottoexpertResearchRoutingAllowedModes(), true)) { $mode = 'prediction_first'; }
        $state['mode'] = $mode;
        return $state;
    }
}
if (!function_exists('mylottoexpertResearchRoutingWrite')) {
    function mylottoexpertResearchRoutingWrite(array $state)
    {
        $mode = strtolower(trim((string)($state['mode'] ?? 'prediction_first')));
        if (!in_array($mode, mylottoexpertResearchRoutingAllowedModes(), true)) { $mode = 'prediction_first'; }
        $state['mode'] = $mode;
        $path = mylottoexpertResearchRoutingPath();
        $dir = dirname($path);
        if (!is_dir($dir)) { @mkdir($dir, 0755, true); }
        $payload = json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if ($payload === false) { return false; }
        return @file_put_contents($path, $payload, LOCK_EX) !== false;
    }
}
if (!function_exists('mylottoexpertResearchRoutingMode')) {
    function mylottoexpertResearchRoutingMode()
    {
        $state = mylottoexpertResearchRoutingRead();
        return (string)($state['mode'] ?? 'prediction_first');
    }
}
if (!function_exists('mylottoexpertResearchRoutingLabel')) {
    function mylottoexpertResearchRoutingLabel($mode)
    {
        $mode = strtolower(trim((string)$mode));
        if ($mode === 'deep_research') { return 'Deep research mode'; }
        if ($mode === 'balanced_research') { return 'Balanced research mode'; }
        return 'Prediction-first mode';
    }
}

$__mleResearchRoutingAction = '';
if (strtoupper((string)$app->input->getMethod()) === 'POST') {
    $__mleResearchRoutingAction = strtolower(trim((string)$app->input->post->getString('mle_research_routing_action', '')));
}
if ($__mleResearchRoutingAction !== '') {
    $__mleResearchRoutingIsAdmin = (!$user->guest && $user->authorise('core.admin'));
    if (!$__mleResearchRoutingIsAdmin) {
        $app->enqueueMessage('You are not authorized to change AI Testing Prediction Method.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        exit;
    }
    if (!\Joomla\CMS\Session\Session::checkToken('post')) {
        $app->enqueueMessage('Your session expired. Please refresh and try again.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        exit;
    }
    $mode = strtolower(trim((string)$app->input->post->getString('mle_research_routing_mode', 'prediction_first')));
    if (!in_array($mode, mylottoexpertResearchRoutingAllowedModes(), true)) { $mode = 'prediction_first'; }
    $state = mylottoexpertResearchRoutingRead();
    $state['mode'] = $mode;
    $state['updated_at'] = gmdate('Y-m-d H:i:s');
    $state['updated_by'] = (int)$user->id;
    if (mylottoexpertResearchRoutingWrite($state)) {
        $app->enqueueMessage('AI Testing Prediction Method changed to ' . mylottoexpertResearchRoutingLabel($mode) . '.', 'message');
    } else {
        $app->enqueueMessage('AI Testing Prediction Method could not be saved. Check administrator/logs folder permissions.', 'error');
    }
    $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
    exit;
}

$__mleWorkNoticeIsAdmin = (!$user->guest && $user->authorise('core.admin'));
$__mleWorkNoticeState = mylottoexpertWorkNoticeRead();
$__mleWorkNoticeAction = '';
if (strtoupper((string)$app->input->getMethod()) === 'POST') {
    $__mleWorkNoticeAction = strtolower(trim((string)$app->input->post->getString('mle_work_notice_action', '')));
}

if ($__mleWorkNoticeAction !== '') {
    if (!$__mleWorkNoticeIsAdmin) {
        $app->enqueueMessage('You are not authorized to change the MyLottoExpert work notice.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        exit;
    }
    if (!\Joomla\CMS\Session\Session::checkToken('post')) {
        $app->enqueueMessage('Your session expired. Please refresh and try again.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        exit;
    }

    // [[MLE_V66_LONG_WORK_NOTICE]] Allow longer admin notices and preserve paragraph breaks for clearer user updates.
    $msg = trim((string)$app->input->post->get('mle_work_notice_message', '', 'RAW'));
    $msg = str_replace(array("\r\n", "\r"), "\n", $msg);
    $msg = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]+/', ' ', $msg);
    $msg = preg_replace('/[ \t]+/', ' ', $msg);
    $msg = preg_replace('/\n{3,}/', "\n\n", $msg);
    if (function_exists('mb_substr')) {
        $msg = mb_substr($msg, 0, 2000, 'UTF-8');
    } else {
        $msg = substr($msg, 0, 2000);
    }
    $msg = trim($msg);
    if ($msg === '') {
        $msg = mylottoexpertWorkNoticeDefaultState()['message'];
    }

    if ($__mleWorkNoticeAction === 'enable') {
        $__mleWorkNoticeState['enabled'] = 1;
        $__mleWorkNoticeState['message'] = $msg;
    } elseif ($__mleWorkNoticeAction === 'disable') {
        $__mleWorkNoticeState['enabled'] = 0;
        $__mleWorkNoticeState['message'] = $msg;
    }
    $__mleWorkNoticeState['updated_at'] = gmdate('Y-m-d H:i:s');
    $__mleWorkNoticeState['updated_by'] = (int)$user->id;

    if (mylottoexpertWorkNoticeWrite($__mleWorkNoticeState)) {
        $app->enqueueMessage($__mleWorkNoticeAction === 'enable' ? 'MyLottoExpert work notice is ON.' : 'MyLottoExpert work notice is OFF.', 'message');
    } else {
        $app->enqueueMessage('MyLottoExpert work notice could not be saved. Check administrator/logs folder permissions.', 'error');
    }
    $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
    exit;
}

if (!empty($__mleWorkNoticeState['enabled'])) {
    echo '<div class="mle-work-notice-banner" role="status" aria-live="polite">';
    echo '<strong>MyLottoExpert workspace update in progress</strong>';
    echo '<span>' . nl2br(htmlspecialchars((string)$__mleWorkNoticeState['message'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'), false) . '</span>';
    echo '</div>';
}

if ($__mleWorkNoticeIsAdmin && $__mleAdminToolsRequested) {
    echo '<details class="mle-work-notice-admin">';
    echo '<summary>Admin Only - MyLottoExpert Work Notice</summary>';
    echo '<p>This notice is informational only. It does not disable MyLottoExpert buttons, predictions, saved runs, review tools, or AI bridge actions.</p>';
    echo '<form method="post" action="' . htmlspecialchars(\Joomla\CMS\Uri\Uri::getInstance()->toString(), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '">';
