function mylottoexpertV99NormalizeDate($value)
{
    $value = trim((string)$value);
    if ($value === '') { return ''; }
    if (function_exists('mylottoexpertSharedSkaiNormalizeDateValue')) {
        $value = mylottoexpertSharedSkaiNormalizeDateValue($value);
    }
    if ($value === '') { return ''; }
    $ts = strtotime($value);
    return ($ts !== false && $ts > 0) ? date('Y-m-d', $ts) : '';
}

function mylottoexpertV99IsScoredSavedRow(array $row)
{
    if (function_exists('mylottoexpertSharedSkaiRowIsScoredEvaluated') && mylottoexpertSharedSkaiRowIsScoredEvaluated($row)) {
        return true;
    }
    $status = strtolower(trim((string)($row['evaluation_status'] ?? $row['status'] ?? '')));
    if (in_array($status, array('scored','evaluated','complete','completed','learned','final','finished'), true)) { return true; }
    if (mylottoexpertV99NormalizeDate($row['actual_draw_date'] ?? '') !== '') { return true; }
    if (trim((string)($row['evaluated_at'] ?? '')) !== '') { return true; }
    if (array_key_exists('main_hits_count', $row) && trim((string)$row['main_hits_count']) !== '') { return true; }
    if (array_key_exists('extra_hits_count', $row) && trim((string)$row['extra_hits_count']) !== '') { return true; }
    if (array_key_exists('learning_score', $row) && trim((string)$row['learning_score']) !== '') { return true; }
    return false;
}

function mylottoexpertV99ScoreSavedRow(array $row)
{
    $mainHits = 0;
    foreach (array('main_hits_count','main_hit_count','main_matches','main_hits','hit_count','hits','total_hits') as $k) {
        if (isset($row[$k]) && is_numeric($row[$k])) { $mainHits = max($mainHits, (int)$row[$k]); }
    }
    $extraHits = 0;
    foreach (array('extra_hits_count','extra_hit_count','bonus_matches','extra_hits','bonus_hits') as $k) {
        if (isset($row[$k]) && is_numeric($row[$k])) { $extraHits = max($extraHits, (int)$row[$k]); }
    }
    $top20 = 0;
    foreach (array('top20_hits','top_20_hits','top20_main_hits','top_20_main_hits') as $k) {
        if (isset($row[$k]) && is_numeric($row[$k])) { $top20 = max($top20, (int)$row[$k]); }
    }
    $top10 = 0;
    foreach (array('top10_hits','top_10_hits','top10_main_hits','top_10_main_hits') as $k) {
        if (isset($row[$k]) && is_numeric($row[$k])) { $top10 = max($top10, (int)$row[$k]); }
    }
    $learning = 0.0;
    foreach (array('learning_score','weighted_quality_score','quality_score','score','final_score') as $k) {
        if (isset($row[$k]) && is_numeric($row[$k])) { $learning = max($learning, (float)$row[$k]); }
    }
    $totalHits = $mainHits + $extraHits;
    $score = ($mainHits * 100.0) + ($extraHits * 35.0) + ($top10 * 8.0) + ($top20 * 3.0) + min(50.0, max(0.0, $learning));
    if ($score <= 0.0 && $totalHits > 0) { $score = $totalHits * 100.0; }
    return array(
        'saved_id' => (int)($row['id'] ?? 0),
        'source_batch_run_id' => (int)($row['source_batch_run_id'] ?? 0),
        'source_batch_run_order' => (int)($row['source_batch_run_order'] ?? 0),
        'is_control' => ((int)($row['batch_control_flag'] ?? 0) === 1) ? 1 : 0,
        'main_hits' => $mainHits,
        'extra_hits' => $extraHits,
        'total_hits' => $totalHits,
        'top10' => $top10,
        'top20' => $top20,
        'learning_score' => $learning,
        'score' => $score,
        'actual_draw_date' => mylottoexpertV99NormalizeDate($row['actual_draw_date'] ?? $row['target_draw_date'] ?? ''),
        'evaluation_status' => (string)($row['evaluation_status'] ?? '')
    );
}

function mylottoexpertV99LoadSavedRowsForBatchAssignment($db, array $assignment)
{
    $batchHeaderId = (int)($assignment['batch_header_id'] ?? 0);
    $userId = (int)($assignment['user_id'] ?? 0);
    $lotteryId = (int)($assignment['lottery_id'] ?? 0);
    if ($batchHeaderId <= 0 || $userId <= 0 || $lotteryId <= 0) { return array(); }
    try {
        if (!function_exists('mylottoexpertTableExistsSafe') || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'user_saved_numbers')) { return array(); }
        $cols = function_exists('mylottoexpertGetTableColumnNames') ? mylottoexpertGetTableColumnNames($db, '#__user_saved_numbers') : array();
        if (!in_array('source_batch_id', $cols, true)) { return array(); }
        $q = $db->getQuery(true)
            ->select('*')
            ->from($db->quoteName('#__user_saved_numbers'))
            ->where($db->quoteName('user_id') . ' = ' . $userId)
            ->where($db->quoteName('lottery_id') . ' = ' . $lotteryId)
            ->where($db->quoteName('source_batch_id') . ' = ' . $batchHeaderId);
        if (in_array('source_batch_run_order', $cols, true)) { $q->order($db->quoteName('source_batch_run_order') . ' ASC'); }
        else { $q->order($db->quoteName('id') . ' ASC'); }
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        return is_array($rows) ? $rows : array();
    } catch (\Throwable $e) { return array(); }
}

function mylottoexpertV99ClassifyResearchOutcome(array $savedRows)
{
    $savedCount = count($savedRows);
    $scored = array();
    $missingSettings = 0;
    foreach ($savedRows as $row) {
        if (!is_array($row)) { continue; }
        $settingsRaw = trim((string)($row['settings_json'] ?? $row['settings'] ?? ''));
        if ($settingsRaw === '') { $missingSettings++; }
        if (mylottoexpertV99IsScoredSavedRow($row)) { $scored[] = mylottoexpertV99ScoreSavedRow($row); }
    }
    $scoredCount = count($scored);
    $out = array(
        'result_status' => 'waiting_for_draw',
        'saved_count' => $savedCount,
        'scored_count' => $scoredCount,
        'missing_settings_count' => $missingSettings,
        'control' => array(),
        'best_run' => array(),
        'best_test_run' => array(),
        'score_delta_vs_control' => 0,
        'summary' => '',
        'scored_runs' => $scored
    );
    if ($savedCount <= 0) {
        $out['result_status'] = 'assigned_not_saved';
        $out['summary'] = 'Scheduled prediction exists, but no saved prediction rows are linked yet.';
        return $out;
    }
    if ($missingSettings >= $savedCount) {
        $out['result_status'] = 'invalid_missing_settings';
        $out['summary'] = 'Saved rows exist but settings snapshots are missing, so this assignment cannot teach the shared AI learning reliably.';
        return $out;
    }
    if ($scoredCount <= 0) {
        $out['result_status'] = 'waiting_for_draw';
        $out['summary'] = 'Saved rows are linked, but the official draw has not been scored yet.';
        return $out;
    }
    usort($scored, function($a, $b) {
        if ((float)$b['score'] == (float)$a['score']) { return ((int)$b['total_hits'] > (int)$a['total_hits']) ? 1 : -1; }
        return ((float)$b['score'] > (float)$a['score']) ? 1 : -1;
    });
    $best = $scored[0];
    $control = array();
    foreach ($scored as $rowScore) {
        if (!empty($rowScore['is_control']) || (int)($rowScore['source_batch_run_order'] ?? 0) === 1) { $control = $rowScore; break; }
    }
    if (empty($control)) { $control = end($scored); if (!is_array($control)) { $control = array(); } }
    $bestTest = array();
    foreach ($scored as $rowScore) {
        if ((int)($rowScore['source_batch_run_order'] ?? 0) !== 1 && empty($rowScore['is_control'])) { $bestTest = $rowScore; break; }
    }
    if (empty($bestTest)) { $bestTest = $best; }
    $delta = (float)($bestTest['score'] ?? 0) - (float)($control['score'] ?? 0);
    $out['control'] = $control;
    $out['best_run'] = $best;
    $out['best_test_run'] = $bestTest;
    $out['score_delta_vs_control'] = round($delta, 6);
    if ($scoredCount < max(1, $savedCount)) {
        $out['result_status'] = 'partial_scored';
        $out['summary'] = 'Some linked rows are scored, but the full batch is not complete yet.';
        return $out;
    }
    if ($delta >= 25.0 || (int)($bestTest['total_hits'] ?? 0) > (int)($control['total_hits'] ?? 0)) {
        $out['result_status'] = 'improved';
        $out['summary'] = 'A tested setting outperformed the control run. Promote carefully or replicate before locking.';
    } elseif ($delta <= -25.0 || (int)($control['total_hits'] ?? 0) > (int)($bestTest['total_hits'] ?? 0)) {
        $out['result_status'] = 'weakened';
        $out['summary'] = 'The control run beat the tested settings. Treat the tested direction as weak unless future prediction history improves it.';
    } else {
        $out['result_status'] = 'neutral';
        $out['summary'] = 'The tested setting was close to the control. Keep collecting or test a nearby setting.';
    }
    if ($out['result_status'] === 'improved' && $savedCount < 9) {
        $out['result_status'] = 'needs_replication';
        $out['summary'] = 'The tested setting improved, but the batch support is incomplete. Replication is needed.';
    }
    return $out;
}

function mylottoexpertV99UpdateAssignmentAndQueueFeedback($db, array $assignment, array $outcome, $now)
{
    $assignmentId = (int)($assignment['id'] ?? 0);
    $queueId = (int)($assignment['queue_id'] ?? 0);
    if ($assignmentId <= 0) { return false; }
    $savedCount = (int)($outcome['saved_count'] ?? 0);
    $scoredCount = (int)($outcome['scored_count'] ?? 0);
    $resultStatus = preg_replace('/[^a-z0-9_\-]/', '', strtolower((string)($outcome['result_status'] ?? '')));
    if ($resultStatus === '') { $resultStatus = 'waiting_for_draw'; }
    $assignedStatus = 'assigned';
    if ($resultStatus === 'assigned_not_saved') { $assignedStatus = 'assigned'; }
    elseif ($resultStatus === 'waiting_for_draw') { $assignedStatus = 'waiting_for_draw'; }
    elseif ($resultStatus === 'partial_scored') { $assignedStatus = 'partial_scored'; }
    elseif (in_array($resultStatus, array('improved','neutral','weakened','needs_replication','invalid_missing_settings','inconclusive'), true)) { $assignedStatus = 'completed'; }
    $resultJson = json_encode($outcome, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    try {
        $sets = array(
            $db->quoteName('assigned_status') . ' = ' . $db->quote($assignedStatus),
            $db->quoteName('saved_count') . ' = ' . $savedCount,
            $db->quoteName('scored_count') . ' = ' . $scoredCount
        );
        if (mylottoexpertV99ColumnExists($db, '#__mle_lottery_research_assignments', 'last_reconciled_at')) { $sets[] = $db->quoteName('last_reconciled_at') . ' = ' . $db->quote((string)$now); }
        if (mylottoexpertV99ColumnExists($db, '#__mle_lottery_research_assignments', 'result_status')) { $sets[] = $db->quoteName('result_status') . ' = ' . $db->quote($resultStatus); }
        if (mylottoexpertV99ColumnExists($db, '#__mle_lottery_research_assignments', 'result_json')) { $sets[] = $db->quoteName('result_json') . ' = ' . $db->quote((string)$resultJson); }
        if ($assignedStatus === 'completed') { $sets[] = $db->quoteName('completed_at') . ' = COALESCE(' . $db->quoteName('completed_at') . ', ' . $db->quote((string)$now) . ')'; }
        $db->setQuery('UPDATE ' . $db->quoteName('#__mle_lottery_research_assignments') . ' SET ' . implode(',', $sets) . ' WHERE ' . $db->quoteName('id') . ' = ' . $assignmentId);
        $db->execute();
    } catch (\Throwable $e) { return false; }
    if ($queueId > 0) {
        try {
            $queueStatus = $assignedStatus;
            if ($assignedStatus === 'completed') { $queueStatus = 'scored'; }
            elseif ($assignedStatus === 'waiting_for_draw') { $queueStatus = 'saved'; }
            $sets = array(
                $db->quoteName('research_status') . ' = ' . $db->quote($queueStatus),
                $db->quoteName('result_status') . ' = ' . $db->quote($resultStatus),
                $db->quoteName('result_json') . ' = ' . $db->quote((string)$resultJson)
            );
            if ($scoredCount > 0) { $sets[] = $db->quoteName('scored_at') . ' = COALESCE(' . $db->quoteName('scored_at') . ', ' . $db->quote((string)$now) . ')'; }
            if (mylottoexpertV99ColumnExists($db, '#__mle_lottery_research_queue', 'last_reconciled_at')) { $sets[] = $db->quoteName('last_reconciled_at') . ' = ' . $db->quote((string)$now); }
            if (mylottoexpertV99ColumnExists($db, '#__mle_lottery_research_queue', 'feedback_version')) { $sets[] = $db->quoteName('feedback_version') . ' = ' . $db->quote('v99'); }
            $db->setQuery('UPDATE ' . $db->quoteName('#__mle_lottery_research_queue') . ' SET ' . implode(',', $sets) . ' WHERE ' . $db->quoteName('id') . ' = ' . $queueId);
            $db->execute();
        } catch (\Throwable $e) {   }
    }
    return true;
}

function mylottoexpertV99ReconcileResearchQueueFeedback($db, $limit = 60)
{
    $limit = max(5, min(200, (int)$limit));
    if (!mylottoexpertV99EnsureFeedbackSchema($db)) { return array('checked'=>0,'updated'=>0,'error'=>'schema_unavailable'); }
    $now = date('Y-m-d H:i:s');
    $checked = 0;
    $updated = 0;
    try {
        $q = $db->getQuery(true)
            ->select('*')
            ->from($db->quoteName('#__mle_lottery_research_assignments'))
            ->where($db->quoteName('batch_header_id') . ' > 0')
            ->where($db->quoteName('assigned_status') . ' NOT IN (' . $db->quote('archived') . ',' . $db->quote('cancelled') . ')')
            ->order($db->quoteName('id') . ' DESC')
            ->setLimit($limit);
        $db->setQuery($q);
        $assignments = $db->loadAssocList();
        if (!is_array($assignments)) { $assignments = array(); }
    } catch (\Throwable $e) {
        return array('checked'=>0,'updated'=>0,'error'=>'assignment_read_failed');
    }
    foreach ($assignments as $assignment) {
        if (!is_array($assignment)) { continue; }
        $checked++;
        $savedRows = mylottoexpertV99LoadSavedRowsForBatchAssignment($db, $assignment);
        $outcome = mylottoexpertV99ClassifyResearchOutcome($savedRows);
        if (mylottoexpertV99UpdateAssignmentAndQueueFeedback($db, $assignment, $outcome, $now)) { $updated++; }
    }
    return array('checked'=>$checked,'updated'=>$updated,'error'=>'');
}

function mylottoexpertSharedSkaiTextContainsAny($value, array $needles)
{
    $text = strtolower((string)$value);
    if ($text === '') { return false; }
    foreach ($needles as $needle) {
        $needle = strtolower((string)$needle);
        if ($needle !== '' && strpos($text, $needle) !== false) { return true; }
    }
    return false;
}

function mylottoexpertSharedSkaiRowHasSettingsEvidence(array $row)
{
    foreach (array('settings_json','settings','params_json','parameter_json','best_params_json','full_settings_json','batch_full_settings_json','batch_settings_json') as $key) {
        if (isset($row[$key]) && trim((string)$row[$key]) !== '') { return true; }
    }
    foreach (array(
        'skai_window_size','skai_window','skip_window','draws_used','draws_analyzed','best_window','tuned_window','skai_blend_ai_pct','skai_blend_skip_pct','signal_blend_ai_pct','signal_blend_skip_pct','sampling_temperature','diversity_penalty','gap_scale','laplace_k','epochs','batch_size','risk_profile','strategy','strategy_profile','focus_profile','model_family','batch_type','skai_run_mode','skai_top_n_numbers','skai_top_n_combos','source_batch_test_variable','source_batch_test_value','batch_run_test_variable','batch_run_test_value','batch_header_test_variable','batch_header_recommended_value','range_min','range_max','batch_header_range_min','batch_header_range_max'
    ) as $key) {
        if (array_key_exists($key, $row) && $row[$key] !== null && trim((string)$row[$key]) !== '') { return true; }
    }
    return false;
}

function mylottoexpertSharedSkaiRowIsScoredEvaluated(array $row)
{
    $status = strtolower(trim((string)mylottoexpertSharedSkaiFirstValue($row, array('evaluation_status','score_status','status','play_status'), '')));
    if (in_array($status, array('scored','evaluated','complete','completed','learned','final','finished'), true)) { return true; }
    if (isset($row['evaluated_at']) && mylottoexpertSharedSkaiNormalizeDateValue($row['evaluated_at']) !== '') { return true; }
    if (isset($row['actual_draw_date']) && mylottoexpertSharedSkaiNormalizeDateValue($row['actual_draw_date']) !== '') { return true; }
    if (array_key_exists('main_hits_count', $row) && $row['main_hits_count'] !== null && $row['main_hits_count'] !== '') { return true; }
    if (array_key_exists('extra_hits_count', $row) && $row['extra_hits_count'] !== null && $row['extra_hits_count'] !== '') { return true; }
    if (isset($row['evaluation_json']) && trim((string)$row['evaluation_json']) !== '') { return true; }
    if (array_key_exists('learning_score', $row) && $row['learning_score'] !== null && $row['learning_score'] !== '') { return true; }
    return false;
}

function mylottoexpertSharedSkaiRowHasPredictionNumbers(array $row)
{
    foreach (array('main_numbers','regular_main_numbers_json','ranked_main_numbers_json','canonical_main_display','main_display_json','top_combos_json','daily_primary_prediction','daily_primary_prediction_json','daily_top_picks_json','daily_set_predictions_json') as $key) {
        if (isset($row[$key]) && trim((string)$row[$key]) !== '') { return true; }
    }
    return false;
}

function mylottoexpertSharedSkaiRowIsExcluded(array $row)
{
    foreach (array('advice_status','play_status','status_explicit','save_intent') as $key) {
        $value = strtolower(trim((string)($row[$key] ?? '')));
        if ($value === '') { continue; }
        if (in_array($value, array('deleted','delete','excluded','exclude','exclude_from_advice','do_not_use','trash','trashed','archived_bad','bad_prediction'), true)) { return true; }
    }
    return false;
}

function mylottoexpertSharedSkaiRowHasRunOrBatchIdentity(array $row)
{
    foreach (array('run_uuid','snapshot_run_uuid','analysis_run_uuid','batch_uuid','source_batch_id','source_batch_run_id','prediction_uid','client_hash','result_hash') as $key) {
        if (isset($row[$key]) && trim((string)$row[$key]) !== '') { return true; }
    }
    return false;
}

function mylottoexpertSharedSkaiBuildSkipDrilldownRow(array $row, $table, $rowId, $reason)
{
    $settingsJson = isset($row['settings_json']) ? trim((string)$row['settings_json']) : '';
    $settingsRaw  = isset($row['settings']) ? trim((string)$row['settings']) : '';
    $methodText = trim(implode(' | ', array_filter(array(
        (string)($row['source'] ?? ''),
        (string)($row['origin_source'] ?? ''),
        (string)($row['analysis_method_key'] ?? ''),
        (string)($row['analysis_engine_label'] ?? ''),
        (string)($row['skai_run_mode'] ?? '')
    ), static function($v){ return trim((string)$v) !== ''; })));
    $runId = (string)mylottoexpertSharedSkaiFirstValue($row, array('run_uuid','snapshot_run_uuid','analysis_run_uuid','batch_uuid','source_batch_id','source_batch_run_id','prediction_uid'), '');
    return array(
        'table' => (string)$table,
        'row_id' => (int)$rowId,
        'reason' => (string)$reason,
        'user_id' => (int)($row['user_id'] ?? 0),
        'game_id' => (string)($row['game_id'] ?? ''),
        'target_game_id' => (string)($row['target_game_id'] ?? ''),
        'lottery_id' => (string)($row['lottery_id'] ?? ''),
        'target_lottery_id' => (string)($row['target_lottery_id'] ?? ''),
        'target_draw_date' => (string)($row['target_draw_date'] ?? ''),
        'actual_draw_date' => (string)($row['actual_draw_date'] ?? ''),
        'evaluation_status' => (string)($row['evaluation_status'] ?? ''),
        'evaluated_at' => (string)($row['evaluated_at'] ?? ''),
        'main_hits_count' => (string)($row['main_hits_count'] ?? ''),
        'extra_hits_count' => (string)($row['extra_hits_count'] ?? ''),
        'learning_score' => (string)($row['learning_score'] ?? ''),
        'method_text' => $methodText,
        'run_or_batch_identity' => $runId,
        'has_settings_json' => $settingsJson !== '' ? 1 : 0,
        'has_settings' => $settingsRaw !== '' ? 1 : 0,
        'has_prediction_numbers' => mylottoexpertSharedSkaiRowHasPredictionNumbers($row) ? 1 : 0,
        'is_skai_detected' => mylottoexpertSharedSkaiIsSkaiRow($row) ? 1 : 0,
        'is_scored_or_evaluated' => mylottoexpertSharedSkaiRowIsScoredEvaluated($row) ? 1 : 0,
        'is_excluded' => mylottoexpertSharedSkaiRowIsExcluded($row) ? 1 : 0,
        'skai_window_size' => (string)($row['skai_window_size'] ?? ''),
        'skip_window' => (string)($row['skip_window'] ?? ''),
        'best_window' => (string)($row['best_window'] ?? ''),
        'tuned_window' => (string)($row['tuned_window'] ?? ''),
        'source_batch_test_variable' => (string)($row['source_batch_test_variable'] ?? ''),
        'source_batch_test_value' => (string)($row['source_batch_test_value'] ?? ''),
        'latest_draw_date' => (string)($row['latest_draw_date'] ?? '')
    );
}

function mylottoexpertSharedSkaiFetchUserSavedNumbersPrimaryRows($db, $lotteryId, $gameId, &$audit)
{
    $rows = array();
    $existsSaved = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'user_saved_numbers');
    if (!$existsSaved) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'user_saved_numbers_primary', false, 0, true, false, 'Primary scored saved prediction table is missing.');
        return $rows;
    }
    $cols = mylottoexpertSharedSkaiSafeTableColumns($db, 'user_saved_numbers');
    $colSet = array();
    foreach ($cols as $c) { $colSet[$c] = true; }
    // [[MLE_V70_USER_SAVED_NUMBERS_QUERY_FIX_2026_06_24]]
    // Keep the lookup index-friendly. Do not wrap game_id / target_game_id in
    // TRIM(COALESCE(...)) because that prevents MariaDB from using the compound
    // game/evaluated_at indexes and can trigger Creating sort index under load.
    $identity = array();
    foreach (array('lottery_id', 'target_lottery_id') as $col) {
        if (isset($colSet[$col]) && (int)$lotteryId > 0) {
            $identity[] = $db->quoteName($col) . ' = ' . (int)$lotteryId;
        }
    }

    $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr(trim((string)$gameId), 0, 50));
    if ($gameId !== '') {
        foreach (array('target_game_id', 'game_id') as $col) {
            if (isset($colSet[$col])) {
                $identity[] = $db->quoteName($col) . ' = ' . $db->quote($gameId);
            }
        }
    }

    $orderCol = 'id';
    foreach (array('evaluated_at', 'actual_draw_date', 'target_draw_date', 'date_saved', 'generated_at', 'updated_at', 'created_at', 'id') as $candidate) {
        if (isset($colSet[$candidate])) { $orderCol = $candidate; break; }
    }
    try {
        $q = $db->getQuery(true)
            ->select('*')
            ->from($db->quoteName('#__user_saved_numbers'))
            ->setLimit(500)
            ->order($db->quoteName($orderCol) . ' DESC');
        if (!empty($identity)) { $q->where('(' . implode(' OR ', $identity) . ')'); }
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        if (!is_array($rows)) { $rows = array(); }

        try {
            $batchRunMap = array();
            $batchHeaderMap = array();
            $runIds = array();
            $batchIds = array();
            foreach ($rows as $er) {
                if (!is_array($er)) { continue; }
                $rid = (int)($er['source_batch_run_id'] ?? 0);
                $bid = (int)($er['source_batch_id'] ?? 0);
                if ($rid > 0) { $runIds[$rid] = $rid; }
                if ($bid > 0) { $batchIds[$bid] = $bid; }
            }
            $hasBatchRun = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'mle_skai_batch_run');
            $hasBatchHeader = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'mle_skai_batch_header');
            if ($hasBatchRun && !empty($runIds)) {
                $brq = $db->getQuery(true)
                    ->select('*')
                    ->from($db->quoteName('#__mle_skai_batch_run'))
                    ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', array_values($runIds))) . ')');
                $db->setQuery($brq);
                $brRows = $db->loadAssocList() ?: array();
                foreach ($brRows as $br) {
                    $brid = (int)($br['id'] ?? 0);
                    if ($brid > 0) { $batchRunMap[$brid] = $br; }
                    $bbid = (int)($br['batch_id'] ?? 0);
                    if ($bbid > 0) { $batchIds[$bbid] = $bbid; }
                }
            }
            if ($hasBatchHeader && !empty($batchIds)) {
                $bhq = $db->getQuery(true)
                    ->select('*')
                    ->from($db->quoteName('#__mle_skai_batch_header'))
                    ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', array_values($batchIds))) . ')');
                $db->setQuery($bhq);
                $bhRows = $db->loadAssocList() ?: array();
                foreach ($bhRows as $bh) {
                    $bhid = (int)($bh['id'] ?? 0);
                    if ($bhid > 0) { $batchHeaderMap[$bhid] = $bh; }
                }
            }
            foreach ($rows as &$erow) {
                if (!is_array($erow)) { continue; }
                $rid = (int)($erow['source_batch_run_id'] ?? 0);
                $bid = (int)($erow['source_batch_id'] ?? 0);
                if ($rid > 0 && isset($batchRunMap[$rid])) {
                    $br = $batchRunMap[$rid];
                    if ($bid <= 0) { $bid = (int)($br['batch_id'] ?? 0); }
                    $erow['_mle_batch_run_found'] = 1;
                    foreach (array(
                        'full_settings_json' => 'batch_run_full_settings_json',
                        'test_variable' => 'batch_run_test_variable',
                        'test_value' => 'batch_run_test_value',
                        'run_order' => 'batch_run_order',
                        'run_name' => 'batch_run_name',
                        'is_control' => 'batch_run_is_control',
                        'source' => 'batch_run_source'
                    ) as $srcKey => $dstKey) {
                        if (isset($br[$srcKey]) && trim((string)$br[$srcKey]) !== '' && empty($erow[$dstKey])) { $erow[$dstKey] = $br[$srcKey]; }
                    }
                    if (empty($erow['source_batch_test_variable']) && !empty($br['test_variable'])) { $erow['source_batch_test_variable'] = $br['test_variable']; }
                    if (empty($erow['source_batch_test_value']) && !empty($br['test_value'])) { $erow['source_batch_test_value'] = $br['test_value']; }
                }
                if ($bid > 0 && isset($batchHeaderMap[$bid])) {
                    $bh = $batchHeaderMap[$bid];
                    $erow['_mle_batch_header_found'] = 1;
                    foreach (array(
                        'test_variable' => 'batch_header_test_variable',
                        'range_min' => 'batch_header_range_min',
                        'range_max' => 'batch_header_range_max',
                        'recommended_value' => 'batch_header_recommended_value',
                        'batch_type' => 'batch_header_batch_type',
                        'evidence_summary' => 'batch_header_evidence_summary',
                        'precision_lock_stage' => 'batch_header_precision_lock_stage',
                        'recommendation_level' => 'batch_header_recommendation_level',
                        'precision_progress_level' => 'batch_header_precision_progress_level'
                    ) as $srcKey => $dstKey) {
                        if (isset($bh[$srcKey]) && trim((string)$bh[$srcKey]) !== '' && empty($erow[$dstKey])) { $erow[$dstKey] = $bh[$srcKey]; }
                    }
                    if (empty($erow['source_batch_test_variable']) && !empty($bh['test_variable'])) { $erow['source_batch_test_variable'] = $bh['test_variable']; }
                    if (empty($erow['recommended_value']) && !empty($bh['recommended_value'])) { $erow['recommended_value'] = $bh['recommended_value']; }
                    if (empty($erow['range_min']) && !empty($bh['range_min'])) { $erow['range_min'] = $bh['range_min']; }
                    if (empty($erow['range_max']) && !empty($bh['range_max'])) { $erow['range_max'] = $bh['range_max']; }
                }
            }
            unset($erow);
            $audit['batch_join_reality'] = array(
                'batch_run_rows_found' => count($batchRunMap),
                'batch_header_rows_found' => count($batchHeaderMap),
                'source_batch_run_ids_seen' => count($runIds),
                'source_batch_ids_seen' => count($batchIds)
            );
        } catch (\Throwable $e) {
            $audit['batch_join_reality'] = array('read_error' => true, 'message' => 'Settings test group details could not be loaded safely.');
        }
        $reality = array(
            'scanned' => count($rows),
            'identity_filter_used' => !empty($identity),
            'skai_detected_rows' => 0,
            'scored_or_evaluated_rows' => 0,
            'settings_rows' => 0,
            'prediction_number_rows' => 0,
            'run_or_batch_identity_rows' => 0,
            'excluded_rows' => 0,
            'eligible_if_window_present_rows' => 0,
            'all_settings_eligible_rows' => 0,
            'history_window_eligible_rows' => 0,
            'all_settings_missing_window_rows' => 0,
            'missing_target_identity_rows' => 0,
            'missing_draw_identity_rows' => 0,
            'missing_window_rows' => 0,
            'skip_reason_counts' => array(
                'excluded_or_deleted' => 0,
                'missing_target_identity' => 0,
                'missing_draw_identity' => 0,
                'not_scored_or_evaluated' => 0,
                'missing_prediction_numbers' => 0,
                'not_skai' => 0,
                'missing_settings' => 0,
                'missing_window' => 0
            ),
            'latest_samples' => array(),
            'latest_skipped_samples' => array()
        );
        foreach ($rows as &$row) {
            if (!is_array($row)) { continue; }
            $row['_mle_shared_source_table'] = 'user_saved_numbers_primary';
            $row['_mle_shared_identity_filter_used'] = !empty($identity) ? 1 : 0;
            $isSkai = mylottoexpertSharedSkaiIsSkaiRow($row);
            $isChecked = mylottoexpertSharedSkaiRowIsScoredEvaluated($row);
            $isScored = $isChecked;
            $hasSettings = mylottoexpertSharedSkaiRowHasSettingsEvidence($row);
            $hasNumbers = mylottoexpertSharedSkaiRowHasPredictionNumbers($row);
            $hasRun = mylottoexpertSharedSkaiRowHasRunOrBatchIdentity($row);
            $isExcluded = mylottoexpertSharedSkaiRowIsExcluded($row);
            $hasTargetIdentity = (trim((string)($row['target_game_id'] ?? '')) !== '' || trim((string)($row['game_id'] ?? '')) !== '' || (int)($row['target_lottery_id'] ?? 0) > 0 || (int)($row['lottery_id'] ?? 0) > 0);
            $hasDrawIdentity = (mylottoexpertSharedSkaiExtractDrawDateFromRow($row) !== '');
            $tmpSettings = array();
            if ($hasSettings) { $tmpSettings = mylottoexpertMergeSharedLearningSettings(mylottoexpertDecodeSettingsFromSharedLearningRow($row), $row); }
            $tmpWindowInfo = !empty($tmpSettings) ? mylottoexpertExtractSkaiWindowInfo($tmpSettings) : array();
            $hasWindow = ((int)($tmpWindowInfo['window'] ?? 0) > 0);
            $allSettingsEligible = (!$isExcluded && $hasTargetIdentity && $hasDrawIdentity && $isChecked && $hasNumbers && $isSkai && $hasSettings);
            if ($allSettingsEligible) {
                $reality['all_settings_eligible_rows']++;
                if ($hasWindow) { $reality['history_window_eligible_rows']++; }
                else { $reality['all_settings_missing_window_rows']++; }
            }
            if (!$hasTargetIdentity) { $reality['missing_target_identity_rows']++; }
            if (!$hasDrawIdentity) { $reality['missing_draw_identity_rows']++; }
            if (!$hasWindow) { $reality['missing_window_rows']++; }
            $primarySkipReason = '';
            if ($isExcluded) { $primarySkipReason = 'excluded_or_deleted'; }
            elseif (!$hasTargetIdentity) { $primarySkipReason = 'missing_target_identity'; }
            elseif (!$hasDrawIdentity) { $primarySkipReason = 'missing_draw_identity'; }
            elseif (!$isScored) { $primarySkipReason = 'not_scored_or_evaluated'; }
            elseif (!$hasNumbers) { $primarySkipReason = 'missing_prediction_numbers'; }
            elseif (!$isSkai) { $primarySkipReason = 'not_skai'; }
            elseif (!$hasSettings) { $primarySkipReason = 'missing_settings'; }
            elseif (!$hasWindow) { $primarySkipReason = 'missing_window'; }
            if ($primarySkipReason !== '') {
                if (!isset($reality['skip_reason_counts'][$primarySkipReason])) { $reality['skip_reason_counts'][$primarySkipReason] = 0; }
                $reality['skip_reason_counts'][$primarySkipReason]++;
                if (count($reality['latest_skipped_samples']) < 25) {
                    $reality['latest_skipped_samples'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, 'user_saved_numbers_primary', (int)($row['id'] ?? 0), $primarySkipReason);
                }
            }
            if ($isSkai) { $reality['skai_detected_rows']++; }
            if ($isScored) { $reality['scored_or_evaluated_rows']++; }
            if ($hasSettings) { $reality['settings_rows']++; }
            if ($hasNumbers) { $reality['prediction_number_rows']++; }
            if ($hasRun) { $reality['run_or_batch_identity_rows']++; }
            if ($isExcluded) { $reality['excluded_rows']++; }
            if ($isSkai && $isChecked && $hasSettings && $hasNumbers && !$isExcluded) { $reality['eligible_if_window_present_rows']++; }
            if (count($reality['latest_samples']) < 12) {
                $reality['latest_samples'][] = array(
                    'id' => (int)($row['id'] ?? 0),
                    'user_id' => (int)($row['user_id'] ?? 0),
                    'game_id' => (string)($row['game_id'] ?? ''),
                    'target_game_id' => (string)($row['target_game_id'] ?? ''),
                    'target_draw_date' => (string)($row['target_draw_date'] ?? ''),
                    'actual_draw_date' => (string)($row['actual_draw_date'] ?? ''),
                    'evaluation_status' => (string)($row['evaluation_status'] ?? ''),
                    'evaluated_at' => (string)($row['evaluated_at'] ?? ''),
                    'main_hits_count' => (string)($row['main_hits_count'] ?? ''),
                    'source' => (string)($row['source'] ?? ''),
                    'analysis_method_key' => (string)($row['analysis_method_key'] ?? ''),
                    'has_settings' => $hasSettings ? 1 : 0,
                    'has_numbers' => $hasNumbers ? 1 : 0,
                    'has_run_or_batch_identity' => $hasRun ? 1 : 0,
                    'is_skai' => $isSkai ? 1 : 0,
                    'is_scored' => $isChecked ? 1 : 0,
                    'is_excluded' => $isExcluded ? 1 : 0,
                    'has_window' => $hasWindow ? 1 : 0,
                    'all_settings_eligible' => $allSettingsEligible ? 1 : 0
                );
            }
        }
        unset($row);
        $audit['reality_audit']['user_saved_numbers_primary'] = $reality;
        mylottoexpertSharedSkaiAddAuditTable($audit, 'user_saved_numbers_primary', true, count($rows), !empty($identity), false, 'Primary real-schema source: saved prediction rows with target identity, AI settings, settings test/run identity, and evaluation/scoring columns.');
        return $rows;
    } catch (\Throwable $e) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'user_saved_numbers_primary', true, 0, !empty($identity), true, 'Read failed while scanning real-schema saved prediction rows.');
        return array();
    }
}

function mylottoexpertSharedSkaiAddAuditTable(&$audit, $table, $exists, $scanned, $identityFilterUsed, $readError, $note = '')
{
    $audit['tables_checked'][$table] = array(
        'exists' => (bool)$exists,
        'scanned' => (int)$scanned,
        'identity_filter_used' => (bool)$identityFilterUsed,
        'read_error' => (bool)$readError,
        'note' => (string)$note
    );
}

function mylottoexpertSharedSkaiSafeTableColumns($db, $tableName)
{
    try {
        $cols = $db->getTableColumns('#__' . $tableName, false);
        if (!is_array($cols)) { return array(); }
        $out = array();
        foreach ($cols as $key => $meta) {
            if (is_string($key) && $key !== '') { $out[] = $key; }
            elseif (is_object($meta) && isset($meta->Field)) { $out[] = (string)$meta->Field; }
        }
        return array_values(array_unique($out));
    } catch (\Throwable $e) {
        return array();
    }
}

function mylottoexpertSharedSkaiColumnSql($db, array $cols, $alias, $column, $as)
{
    if (!in_array($column, $cols, true)) { return ''; }
    return $alias . '.' . $db->quoteName($column) . ' AS ' . $db->quoteName($as);
}


/* [[MLE_ELITE_LEARNING_GATES_V20260626]]
   Evidence-backed gate added after live audit showed:
   - ready shared profiles with baseline_lift=0 and near-zero stability
   - runtime audit rows with fallback/domain verification failures
   This function does not manufacture confidence. It caps profile status downward unless the
   live evidence passes minimum statistical and runtime-integrity requirements.
*/
function mylottoexpertEliteSharedSkaiRuntimeHealth($db, $gameId)
{
    $out = array(
        'table_exists' => false,
        'checked' => false,
        'game_id' => (string)$gameId,
        'total_rows' => 0,
        'domain_not_verified' => 0,
        'mode_not_verified' => 0,
        'metrics_incomplete' => 0,
        'display_engine_mismatch' => 0,
        'snapshot_engine_mismatch' => 0,
        'fallback_triggered_total' => 0,
        'passing_rows' => 0,
        'elite_runtime_ok' => false,
        'reason' => 'runtime_audit_not_checked'
    );
    $gameId = trim((string)$gameId);
    if ($gameId === '') { $out['reason'] = 'missing_game_id'; return $out; }
    if (!function_exists('mylottoexpertTableExistsSafe') || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_runtime_audit')) {
        $out['reason'] = 'runtime_audit_table_missing';
        return $out;
    }
    $out['table_exists'] = true;
    try {
        // [[MLE_ELITE4_RUNTIME_WINDOW]] Use the latest audit sample for this game instead of all historical rows.
        // Old pre-fix audit rows are kept for traceability but should not permanently block future readiness.
        $runtimeTable = $db->quoteName('#__skai_runtime_audit');
        $subSql = 'SELECT * FROM ' . $runtimeTable
            . ' WHERE TRIM(COALESCE(' . $db->quoteName('game_id') . ',' . $db->quote('') . ')) = ' . $db->quote($gameId)
            . ' ORDER BY ' . $db->quoteName('created_at') . ' DESC LIMIT 100';
        $q = $db->getQuery(true)
            ->select(array(
                'COUNT(*) AS total_rows',
                'SUM(CASE WHEN ' . $db->quoteName('domain_verified') . ' = 0 THEN 1 ELSE 0 END) AS domain_not_verified',
                'SUM(CASE WHEN ' . $db->quoteName('mode_verified') . ' = 0 THEN 1 ELSE 0 END) AS mode_not_verified',
                'SUM(CASE WHEN ' . $db->quoteName('metrics_complete') . ' = 0 THEN 1 ELSE 0 END) AS metrics_incomplete',
                'SUM(CASE WHEN ' . $db->quoteName('display_matches_engine') . ' = 0 THEN 1 ELSE 0 END) AS display_engine_mismatch',
                'SUM(CASE WHEN ' . $db->quoteName('snapshot_matches_engine') . ' = 0 THEN 1 ELSE 0 END) AS snapshot_engine_mismatch',
                'SUM(CASE WHEN ' . $db->quoteName('fallback_triggered') . ' = 1 THEN 1 ELSE 0 END) AS fallback_triggered_total',
                'SUM(CASE WHEN ' . $db->quoteName('domain_verified') . ' = 1 AND ' . $db->quoteName('mode_verified') . ' = 1 AND ' . $db->quoteName('metrics_complete') . ' = 1 AND ' . $db->quoteName('display_matches_engine') . ' = 1 AND ' . $db->quoteName('snapshot_matches_engine') . ' = 1 AND ' . $db->quoteName('fallback_triggered') . ' = 0 THEN 1 ELSE 0 END) AS passing_rows'
            ))
            ->from('(' . $subSql . ') AS recent_runtime_audit');
        $db->setQuery($q);
        $row = (array)$db->loadAssoc();
        $out['checked'] = true;
        foreach (array('total_rows','domain_not_verified','mode_not_verified','metrics_incomplete','display_engine_mismatch','snapshot_engine_mismatch','fallback_triggered_total','passing_rows') as $k) {
            $out[$k] = (int)($row[$k] ?? 0);
        }
        if ($out['total_rows'] <= 0) {
            $out['reason'] = 'no_runtime_audit_rows_for_game';
            return $out;
        }
        if ($out['passing_rows'] <= 0) {
            $out['reason'] = 'no_clean_runtime_audit_rows_for_game';
            return $out;
        }
        if ($out['domain_not_verified'] > 0 || $out['mode_not_verified'] > 0 || $out['metrics_incomplete'] > 0 || $out['display_engine_mismatch'] > 0 || $out['snapshot_engine_mismatch'] > 0 || $out['fallback_triggered_total'] > 0) {
            $out['reason'] = 'runtime_audit_has_failures_or_fallbacks';
            return $out;
        }
        $out['elite_runtime_ok'] = true;
        $out['reason'] = 'runtime_audit_clean';
    } catch (\Throwable $e) {
        $out['checked'] = true;
        $out['reason'] = 'runtime_audit_query_failed';
    }
    return $out;
}

function mylottoexpertEliteSharedSkaiStatusGate(array $metrics)
{
    $users = (int)($metrics['evidence_users'] ?? 0);
    $runs = (int)($metrics['evidence_runs'] ?? 0);
    $draws = (int)($metrics['evidence_draws'] ?? 0);
    $confidence = (float)($metrics['confidence_score'] ?? 0.0);
    $stability = (float)($metrics['stability_score'] ?? 0.0);
    $baselineLift = (float)($metrics['baseline_lift'] ?? 0.0);
    $runtimeOk = !empty($metrics['runtime_ok']);
    $reasons = array();
    if ($users < 3) { $reasons[] = 'evidence_users_below_3'; }
    if ($runs < 30) { $reasons[] = 'evidence_runs_below_30'; }
    if ($draws < 8) { $reasons[] = 'evidence_draws_below_8'; }
    if ($confidence < 0.65) { $reasons[] = 'confidence_below_0_65'; }
    if ($stability < 0.20) { $reasons[] = 'stability_below_0_20'; }
    if ($baselineLift <= 0.0) { $reasons[] = 'baseline_lift_not_positive'; }
    if (!$runtimeOk) { $reasons[] = 'runtime_audit_not_clean'; }
    if (!empty($reasons)) {
        return array('status' => 'collecting', 'gate_level' => 'blocked', 'reasons' => $reasons);
    }
    $status = 'ready';
    $level = 'ready';
    if ($users >= 5 && $runs >= 80 && $draws >= 15 && $confidence >= 0.75 && $stability >= 0.35 && $baselineLift >= 0.05) {
        $status = 'strong';
        $level = 'strong';
    }
    if ($users >= 8 && $runs >= 150 && $draws >= 25 && $confidence >= 0.85 && $stability >= 0.50 && $baselineLift >= 0.10) {
        $status = 'elite';
        $level = 'elite';
    }
    return array('status' => $status, 'gate_level' => $level, 'reasons' => array());
}


/* [[MLE_ELITE6B_CANONICAL_LEARNING_ID_RECOVERY_V20260626]]
   Rebuilds shared-learning profile evidence from historical scored prediction rows.
   Adds daily/Pick-game rule awareness from dailylotteries.json, detects linked
   Fireball/Wild/SB bonus games such as FLB -> FLBF, avoids regular top-20
   baseline math for digit games, and keeps bonus-linked daily games collecting
   until bonus-aware learning evidence exists. It does not rewrite old predictions
   or old audit rows and never promotes historical recovery directly to elite.
*/
function mylottoexpertElite6DailyConfigPathCandidates()
{
    $paths = array();
    if (defined('JPATH_ROOT')) { $paths[] = rtrim((string)JPATH_ROOT, '/\\') . '/dailylotteries.json'; }
    $paths[] = __DIR__ . '/dailylotteries.json';
    $paths[] = dirname(__DIR__) . '/dailylotteries.json';
    $paths[] = '/home/oscara/web/lottoexpert.net/public_html/dailylotteries.json';
    return array_values(array_unique($paths));
}

function mylottoexpertElite6LoadDailyRules()
{
    static $rules = null;
    if (is_array($rules)) { return $rules; }
    $rules = array('by_game_id' => array(), 'source_path' => '');
    foreach (mylottoexpertElite6DailyConfigPathCandidates() as $path) {
        if (!is_string($path) || $path === '' || !is_readable($path)) { continue; }
        $raw = @file_get_contents($path);
        if (!is_string($raw) || trim($raw) === '') { continue; }
        $json = json_decode($raw, true);
        if (!is_array($json) || empty($json['dailylotteries']) || !is_array($json['dailylotteries'])) { continue; }
        foreach ($json['dailylotteries'] as $entry) {
            if (!is_array($entry)) { continue; }
            $gid = trim((string)($entry['gameId'] ?? ''));
            if ($gid === '') { continue; }
            $rules['by_game_id'][$gid] = $entry;
        }
        $rules['source_path'] = $path;
        break;
    }
    return $rules;
}

function mylottoexpertElite6DailyRuleForGame($gameId)
{
    $gameId = trim((string)$gameId);
    if ($gameId === '') { return array(); }
    $rules = mylottoexpertElite6LoadDailyRules();
    return isset($rules['by_game_id'][$gameId]) && is_array($rules['by_game_id'][$gameId]) ? $rules['by_game_id'][$gameId] : array();
}

function mylottoexpertElite6LinkedBonusGameId($gameId, $rule = array())
{
    $gameId = trim((string)$gameId);
    if ($gameId === '') { return ''; }
    if (substr($gameId, -1) === 'F' || substr($gameId, -1) === 'W') { return ''; }
    $rules = mylottoexpertElite6LoadDailyRules();
    $state = trim((string)($rule['state'] ?? ''));
    $label = trim((string)($rule['label'] ?? ''));
    $candidates = array($gameId . 'F', $gameId . 'W');
    foreach ($candidates as $candidate) {
        if (!isset($rules['by_game_id'][$candidate])) { continue; }
        $linked = $rules['by_game_id'][$candidate];
        if ($state !== '' && trim((string)($linked['state'] ?? '')) !== $state) { continue; }
        return $candidate;
    }
    foreach ($rules['by_game_id'] as $candidate => $linked) {
        if ($state !== '' && trim((string)($linked['state'] ?? '')) !== $state) { continue; }
        $linkedLabel = trim((string)($linked['label'] ?? ''));
        if ($label !== '' && stripos($linkedLabel, $label) === 0 && preg_match('/\b(FB|Fireball|Wild|SB)\b/i', $linkedLabel)) { return (string)$candidate; }
    }
    return '';
}


/* [[MLE_ELITE8C_DAILY_TARGET_EXTRA_COUNT_FIX_V20260626]]
   Daily games can display several ranked bonus candidates, but the canonical
   target extra count must come from dailylotteries.json extraBallCount. For
   FLB this is 1, even when daily_bonus_digits_json stores the top 3 bonus
   candidate digits for display/recommendation ranking.
*/
function mylottoexpertElite8cConfiguredDailyExtraCount($gameId, $fallback = 0)
{
    $gameId = trim((string)$gameId);
    $fallback = (int)$fallback;
    if ($gameId === '') { return max(0, $fallback); }
    $rule = mylottoexpertElite6DailyRuleForGame($gameId);
    if (is_array($rule) && !empty($rule)) {
        if (array_key_exists('extraBallCount', $rule)) {
            return max(0, (int)$rule['extraBallCount']);
        }
        if (array_key_exists('rangeExtra', $rule) && (int)$rule['rangeExtra'] > 0) {
            return max(1, $fallback);
        }
    }
    return max(0, $fallback);
}


/* [[MLE_ELITE8E_STRATEGY_SET_DAILY_EXTRA_COUNT_FIX_V20260626]]
   Fixes the confirmed strategy-set saved-play path. The canonical target extra
   count now uses the official daily extra count resolver instead of counting
   ranked/displayed bonus candidates such as FLB's top 3 Fireball digits.
*/

/* [[MLE_ELITE8D_DAILY_TARGET_EXTRA_COUNT_DB_BACKSTOP_V20260626]]
   Backstop for daily saved-number target identity. If dailylotteries.json is not
   found in the executing path, or if the save path receives a blank display game
   id, resolve the official extra draw count from jos9d_skai_lottery_settings.
   This prevents ranked display candidates, such as FLB's top 3 Fireball digits,
   from being stored as the canonical official extra-ball count.
*/
/* [[MLE_ELITE8G_CANONICAL_EXTRA_COUNT_RESOLVER_ID_FIX_V20260626]]
   Corrects the ELITE8D/8E resolver. The previous resolver mixed
   #__skai_lottery_settings.game_id with #__skai_lottery_settings.id using OR,
   while the caller passes the canonical lottery_id from #__lotteries. For FLB,
   lottery_id=76 and the SKAI settings row id is different, so the OR could
   select an unrelated settings row and preserve the fallback display count 3.
   This resolver now resolves by canonical game_id first, maps lottery_id through
   #__lotteries only when game_id is blank, and never compares lottery_id to
   #__skai_lottery_settings.id.
*/
function mylottoexpertElite8dCanonicalDailyExtraCount($db, $gameId, $lotteryId = 0, $fallback = 0)
{
    $gameId = strtoupper(trim((string)$gameId));
    $lotteryId = (int)$lotteryId;
    $fallback = (int)$fallback;

    try {
        if ($gameId === '' && $lotteryId > 0 && is_object($db)) {
            $qGame = $db->getQuery(true)
                ->select($db->quoteName('game_id'))
                ->from($db->quoteName('#__lotteries'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->setLimit(1);
            $db->setQuery($qGame);
            $resolvedGameId = strtoupper(trim((string)$db->loadResult()));
            if ($resolvedGameId !== '') {
                $gameId = $resolvedGameId;
            }
        }
    } catch (\Throwable $__) { }

    if (function_exists('mylottoexpertElite8cConfiguredDailyExtraCount') && $gameId !== '') {
        $fromConfig = (int)mylottoexpertElite8cConfiguredDailyExtraCount($gameId, -1);
        if ($fromConfig >= 0) {
            return max(0, $fromConfig);
        }
    }

    try {
        if (is_object($db) && $gameId !== '') {
            $q = $db->getQuery(true)
                ->select(array(
                    $db->quoteName('draw_count_bonus'),
                    $db->quoteName('supports_bonus'),
                    $db->quoteName('bonus_pool_size')
                ))
                ->from($db->quoteName('#__skai_lottery_settings'))
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->order($db->quoteName('updated_at') . ' DESC')
                ->setLimit(1);
            $db->setQuery($q);
            $row = $db->loadAssoc();
            if (is_array($row) && !empty($row)) {
                $drawCountBonus = (int)($row['draw_count_bonus'] ?? 0);
                if ($drawCountBonus > 0) { return $drawCountBonus; }
                if ((int)($row['supports_bonus'] ?? 0) > 0 || (int)($row['bonus_pool_size'] ?? 0) > 0) { return 1; }
            }
        }
    } catch (\Throwable $__) { }

    if ($gameId !== '' && preg_match('/^[A-Z]{2,3}[A-Z0-9]?$/', $gameId) && substr($gameId, -1) !== 'F' && substr($gameId, -1) !== 'W') {
        $linked = function_exists('mylottoexpertElite6LinkedBonusGameId') ? mylottoexpertElite6LinkedBonusGameId($gameId) : '';
        if ($linked !== '') { return 1; }
    }

    return max(0, $fallback);
}

function mylottoexpertElite6IsDigitDailyRule($rule)
{
    if (!is_array($rule) || empty($rule)) { return false; }
    $pickSize = (int)($rule['pickSize'] ?? 0);
    $rangeMain = (int)($rule['rangeMain'] ?? 0);
    return ($pickSize >= 2 && $pickSize <= 5 && $rangeMain > 0 && $rangeMain <= 10);
}

function mylottoexpertElite6NormalizeHistoricalRecoveryMetrics($row, $rule, $settings)
{
    $runs = (int)($row['evidence_runs'] ?? 0);
    $draws = (int)($row['evidence_draws'] ?? 0);
    $users = (int)($row['evidence_users'] ?? 0);
    $avgActual = (float)($row['avg_actual_main_count'] ?? 0.0);
    $avgTop20 = (float)($row['avg_top20_hits'] ?? 0.0);
    $avgTop10 = (float)($row['avg_top10_hits'] ?? $avgTop20);
    $mainPool = (int)($settings['main_pool_size'] ?? ($row['main_pool_size'] ?? 0));
    $supportsBonus = (int)($settings['supports_bonus'] ?? ($row['supports_bonus'] ?? 0));
    $drawCountBonus = (int)($settings['draw_count_bonus'] ?? ($row['draw_count_bonus'] ?? 0));
    $bonusPool = (int)($settings['bonus_pool_size'] ?? ($row['bonus_pool_size'] ?? 0));
    $isDigitDaily = mylottoexpertElite6IsDigitDailyRule($rule) || ($mainPool > 0 && $mainPool <= 10 && $avgActual > 0 && $avgActual <= 5);
    $ruleExtraCount = (int)($rule['extraBallCount'] ?? 0);
    $ruleRangeExtra = (int)($rule['rangeExtra'] ?? 0);
    $linkedBonusGameId = mylottoexpertElite6LinkedBonusGameId((string)($row['target_game_id'] ?? ''), $rule);
    $requiresLinkedBonus = $isDigitDaily && ($ruleExtraCount > 0 || $ruleRangeExtra > 0 || $supportsBonus > 0 || $drawCountBonus > 0 || $bonusPool > 0 || $linkedBonusGameId !== '');
    $expected = 0.0;
    $liftRaw = 0.0;
    $liftPct = 0.0;
    $metric = 'regular_top20';
    $promotionBlocked = false;
    $blockedReason = '';
    if ($isDigitDaily) {
        $metric = 'digit_top10_capped';
        $pool = $mainPool > 0 ? $mainPool : (int)($rule['rangeMain'] ?? 10);
        if ($pool <= 0) { $pool = 10; }
        $expected = $avgActual * (min(10, $pool) / max(1, $pool));
        $expected = min(max(0.0, $expected), max(0.0, $avgActual));
        $liftRaw = $avgTop10 - $expected;
        $liftPct = ($expected > 0.0) ? ($liftRaw / $expected) : 0.0;
        if ($requiresLinkedBonus) {
            $promotionBlocked = true;
            $blockedReason = 'linked_bonus_result_required_before_daily_bonus_promotion';
            // Do not store an extreme negative from incomplete main-only rows as if it were full-game evidence.
            $liftRaw = 0.0;
            $liftPct = 0.0;
        }
    } else {
        $expected = $avgActual * (20 / max(1, $mainPool));
        $liftRaw = $avgTop20 - $expected;
        $liftPct = ($expected > 0.0) ? ($liftRaw / $expected) : 0.0;
    }
    $status = $promotionBlocked ? 'collecting' : mylottoexpertElite5HistoricalRecoveryStatus($runs, $draws, $users, $liftRaw, $liftPct);
    return array(
        'is_digit_daily' => $isDigitDaily ? 1 : 0,
        'requires_linked_bonus' => $requiresLinkedBonus ? 1 : 0,
        'linked_bonus_game_id' => $linkedBonusGameId,
        'promotion_blocked' => $promotionBlocked ? 1 : 0,
        'blocked_reason' => $blockedReason,
        'baseline_metric' => $metric,
        'random_expected_hits' => round($expected, 6),
        'baseline_lift_raw' => round($liftRaw, 6),
        'baseline_lift_pct' => round($liftPct, 6),
        'status' => $status
    );
}
function mylottoexpertElite5HistoricalRecoveryStatus($runs, $draws, $users, $baselineLiftRaw, $baselineLiftPct)
{
    $runs = (int)$runs;
    $draws = (int)$draws;
    $users = (int)$users;
    $baselineLiftRaw = (float)$baselineLiftRaw;
    $baselineLiftPct = (float)$baselineLiftPct;
    if ($runs >= 80 && $draws >= 15 && $users >= 2 && $baselineLiftPct >= 0.05) {
        return 'strong';
    }
    if ($runs >= 25 && $draws >= 8 && $users >= 2 && $baselineLiftRaw > 0.0) {
        return 'ready';
    }
    return 'collecting';
}

function mylottoexpertElite5HistoricalRecoveryConfidence($runs, $draws, $users, $baselineLiftPct)
{
    $runs = max(0, (int)$runs);
    $draws = max(0, (int)$draws);
    $users = max(0, (int)$users);
    $lift = max(0.0, (float)$baselineLiftPct);
    $score = (min(1.0, $runs / 150.0) * 0.35)
        + (min(1.0, $draws / 25.0) * 0.25)
        + (min(1.0, $users / 5.0) * 0.20)
        + (min(1.0, $lift / 0.10) * 0.20);
    return max(0.0, min(0.84, $score));
}

function mylottoexpertElite5HistoricalRecoveryStability($runs, $draws, $users, $baselineLiftPct)
{
    $runs = max(0, (int)$runs);
    $draws = max(0, (int)$draws);
    $users = max(0, (int)$users);
    $lift = max(0.0, (float)$baselineLiftPct);
    $score = (min(1.0, $draws / 50.0) * 0.35)
        + (min(1.0, $users / 5.0) * 0.25)
        + (min(1.0, $lift / 0.10) * 0.25)
        + (min(1.0, $runs / 300.0) * 0.15);
    return max(0.0, min(0.75, $score));
}

function mylottoexpertElite5RecalculateHistoricalRecoveryProfilesForGame($db, $lotteryId, $gameId)
{
    $lotteryId = (int)$lotteryId;
    $gameId = trim((string)$gameId);
    $out = array(
        'version' => 'ELITE6B_CANONICAL_LEARNING_ID_RECOVERY_V20260626',
        'game_id' => $gameId,
        'lottery_id' => $lotteryId,
        'checked' => false,
        'updated_profiles' => 0,
        'candidates' => array(),
        'reason' => 'not_started'
    );
    if ($lotteryId <= 0 || $gameId === '') { $out['reason'] = 'missing_identity'; return $out; }
    if (!function_exists('mylottoexpertTableExistsSafe')) { $out['reason'] = 'table_helper_missing'; return $out; }
    if (!mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_learning_performance') || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_lottery_settings') || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_shared_learning_profiles')) {
        $out['reason'] = 'required_table_missing';
        return $out;
    }
    $cols = function_exists('mylottoexpertSharedSkaiSafeTableColumns') ? mylottoexpertSharedSkaiSafeTableColumns($db, 'skai_learning_performance') : array();
    foreach (array('target_game_id','analysis_method_key','target_draw_date','user_id','target_lottery_id','actual_numbers_json','top20_hits','trend_bucket') as $required) {
        if (!in_array($required, $cols, true)) { $out['reason'] = 'missing_learning_performance_column_' . $required; return $out; }
    }
    try {
        $q = $db->getQuery(true)
            ->select(array(
                'lp.' . $db->quoteName('target_game_id'),
                'lp.' . $db->quoteName('analysis_method_key'),
                'COUNT(*) AS evidence_runs',
                'COUNT(DISTINCT lp.' . $db->quoteName('target_draw_date') . ') AS evidence_draws',
                'COUNT(DISTINCT lp.' . $db->quoteName('user_id') . ') AS evidence_users',
                'MIN(lp.' . $db->quoteName('target_lottery_id') . ') AS min_lottery_id',
                'MAX(lp.' . $db->quoteName('target_lottery_id') . ') AS max_lottery_id',
                'lp.' . $db->quoteName('target_lottery_id') . ' AS evidence_lottery_id',
                'ls.' . $db->quoteName('main_pool_size'),
                'ls.' . $db->quoteName('bonus_pool_size'),
                'ls.' . $db->quoteName('draw_count_bonus'),
                'ls.' . $db->quoteName('supports_bonus'),
                'ls.' . $db->quoteName('supports_pairs'),
                'ROUND(AVG(JSON_LENGTH(lp.' . $db->quoteName('actual_numbers_json') . ')), 6) AS avg_actual_main_count',
                'ROUND(AVG(lp.' . $db->quoteName('top20_hits') . '), 6) AS avg_top20_hits',
                'ROUND(AVG(lp.' . $db->quoteName('top10_hits') . '), 6) AS avg_top10_hits',
                'ROUND(AVG(JSON_LENGTH(lp.' . $db->quoteName('actual_numbers_json') . ')) * (20 / NULLIF(ls.' . $db->quoteName('main_pool_size') . ',0)), 6) AS random_expected_top20_hits',
                'ROUND(AVG(lp.' . $db->quoteName('top20_hits') . ') - (AVG(JSON_LENGTH(lp.' . $db->quoteName('actual_numbers_json') . ')) * (20 / NULLIF(ls.' . $db->quoteName('main_pool_size') . ',0))), 6) AS baseline_lift_raw',
                'ROUND((AVG(lp.' . $db->quoteName('top20_hits') . ') - (AVG(JSON_LENGTH(lp.' . $db->quoteName('actual_numbers_json') . ')) * (20 / NULLIF(ls.' . $db->quoteName('main_pool_size') . ',0)))) / NULLIF((AVG(JSON_LENGTH(lp.' . $db->quoteName('actual_numbers_json') . ')) * (20 / NULLIF(ls.' . $db->quoteName('main_pool_size') . ',0))),0), 6) AS baseline_lift_pct',
                'MIN(lp.' . $db->quoteName('created_at') . ') AS oldest_learning_row',
                'MAX(lp.' . $db->quoteName('created_at') . ') AS newest_learning_row',
                'MAX(lp.' . $db->quoteName('target_draw_date') . ') AS last_scored_draw_date'
            ))
            ->from($db->quoteName('#__skai_learning_performance', 'lp'))
            ->join('INNER', $db->quoteName('#__skai_lottery_settings', 'ls') . ' ON ls.' . $db->quoteName('game_id') . ' = lp.' . $db->quoteName('target_game_id'))
            ->where('lp.' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameId))
            ->where('lp.' . $db->quoteName('target_draw_date') . ' IS NOT NULL')
            ->where('lp.' . $db->quoteName('actual_numbers_json') . ' IS NOT NULL')
            ->where('lp.' . $db->quoteName('actual_numbers_json') . ' <> ' . $db->quote(''))
            ->where('JSON_VALID(lp.' . $db->quoteName('actual_numbers_json') . ')')
            ->where('lp.' . $db->quoteName('trend_bucket') . ' IN (' . $db->quote('auto_scored_exact_draw') . ',' . $db->quote('pending') . ')')
            ->where('lp.' . $db->quoteName('analysis_method_key') . ' IN (' . $db->quote('skai') . ',' . $db->quote('core_ai') . ',' . $db->quote('mcmc') . ',' . $db->quote('frequency') . ',' . $db->quote('skip_hit') . ')')
            ->group(array('lp.' . $db->quoteName('target_game_id'), 'lp.' . $db->quoteName('target_lottery_id'), 'lp.' . $db->quoteName('analysis_method_key'), 'ls.' . $db->quoteName('main_pool_size'), 'ls.' . $db->quoteName('bonus_pool_size'), 'ls.' . $db->quoteName('draw_count_bonus'), 'ls.' . $db->quoteName('supports_bonus'), 'ls.' . $db->quoteName('supports_pairs')))
            ->having('evidence_runs >= 25')
            ->having('evidence_draws >= 5')
            ->order('baseline_lift_pct DESC');
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        if (!is_array($rows)) { $rows = array(); }
        $out['checked'] = true;
        $out['reason'] = 'ok';
        $rawName = $db->getPrefix() . 'skai_shared_learning_profiles';
        $now = date('Y-m-d H:i:s');
        foreach ($rows as $r) {
            $method = trim((string)($r['analysis_method_key'] ?? ''));
            if ($method === '') { continue; }
            $minLottery = (int)($r['min_lottery_id'] ?? 0);
            $maxLottery = (int)($r['max_lottery_id'] ?? 0);
            $evidenceLotteryId = (int)($r['evidence_lottery_id'] ?? 0);
            // ELITE6B: learning_performance.target_lottery_id is the canonical saved-prediction identity.
            // Some daily settings rows use a different internal settings id, so do not skip valid
            // historical evidence merely because the current settings/card id differs.
            if ($minLottery <= 0 || $maxLottery <= 0 || $minLottery !== $maxLottery) { continue; }
            $profileLotteryId = $evidenceLotteryId > 0 ? $evidenceLotteryId : $minLottery;
            $runs = (int)($r['evidence_runs'] ?? 0);
            $draws = (int)($r['evidence_draws'] ?? 0);
            $users = (int)($r['evidence_users'] ?? 0);
            $rule = mylottoexpertElite6DailyRuleForGame($gameId);
            $settings = array(
                'main_pool_size' => (int)($r['main_pool_size'] ?? 0),
                'bonus_pool_size' => (int)($r['bonus_pool_size'] ?? 0),
                'draw_count_bonus' => (int)($r['draw_count_bonus'] ?? 0),
                'supports_bonus' => (int)($r['supports_bonus'] ?? 0),
                'supports_pairs' => (int)($r['supports_pairs'] ?? 0)
            );
            $normalized = mylottoexpertElite6NormalizeHistoricalRecoveryMetrics($r, $rule, $settings);
            $liftRaw = (float)($normalized['baseline_lift_raw'] ?? 0.0);
            $liftPct = (float)($normalized['baseline_lift_pct'] ?? 0.0);
            $status = (string)($normalized['status'] ?? 'collecting');
            $confidence = mylottoexpertElite5HistoricalRecoveryConfidence($runs, $draws, $users, $liftPct);
            $stability = mylottoexpertElite5HistoricalRecoveryStability($runs, $draws, $users, $liftPct);
            if (!empty($normalized['promotion_blocked'])) {
                $confidence = min($confidence, 0.76);
                $stability = min($stability, 0.61);
            }
            $profileJson = array(
                'version' => 'ELITE6B_CANONICAL_LEARNING_ID_RECOVERY_V20260626',
                'source' => 'skai_learning_performance_comparable_scored_rows',
                'trend_buckets_used' => array('auto_scored_exact_draw','pending'),
                'trend_buckets_excluded_from_promotion_math' => array('post_draw_cron'),
                'status_policy' => 'collecting_ready_strong_only_never_elite',
                'evidence_runs' => $runs,
                'evidence_draws' => $draws,
                'evidence_users' => $users,
                'main_pool_size' => (int)($r['main_pool_size'] ?? 0),
                'input_lottery_id' => $lotteryId,
                'canonical_learning_lottery_id' => $profileLotteryId,
                'identity_policy' => 'elite6b_use_learning_performance_target_lottery_id_when_settings_id_differs',
                'avg_actual_main_count' => (float)($r['avg_actual_main_count'] ?? 0.0),
                'avg_top20_hits' => (float)($r['avg_top20_hits'] ?? 0.0),
                'avg_top10_hits' => (float)($r['avg_top10_hits'] ?? 0.0),
                'random_expected_top20_hits' => (float)($r['random_expected_top20_hits'] ?? 0.0),
                'elite6_daily_rule' => $rule,
                'elite6_baseline_policy' => $normalized,
                'baseline_lift_raw' => $liftRaw,
                'baseline_lift_pct' => $liftPct,
                'oldest_learning_row' => (string)($r['oldest_learning_row'] ?? ''),
                'newest_learning_row' => (string)($r['newest_learning_row'] ?? ''),
                'updated_by' => 'mylottoexpert_elite6b_canonical_learning_id_recovery'
            );
            $lastDate = trim((string)($r['last_scored_draw_date'] ?? ''));
            $lastSql = $lastDate !== '' ? $db->quote($lastDate) : 'NULL';
            $jsonSql = $db->quote(json_encode($profileJson, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $sql = "INSERT INTO `{$rawName}` "
                 . "(`game_id`,`lottery_id`,`method_key`,`profile_type`,`recommended_window_min`,`recommended_window_max`,`recommended_window_center`,`sweet_window_min`,`sweet_window_max`,`evidence_users`,`evidence_runs`,`evidence_draws`,`confidence_score`,`stability_score`,`baseline_lift`,`status`,`last_scored_draw_date`,`profile_json`,`is_active`,`created_at`,`updated_at`) VALUES ("
                 . $db->quote($gameId) . "," . (int)$profileLotteryId . "," . $db->quote($method) . "," . $db->quote('history_window') . ","
                 . "0,0,0,0,0," . $users . "," . $runs . "," . $draws . "," . number_format($confidence, 6, '.', '') . "," . number_format($stability, 6, '.', '') . "," . number_format($liftPct, 6, '.', '') . ","
                 . $db->quote($status) . "," . $lastSql . "," . $jsonSql . ",1," . $db->quote($now) . "," . $db->quote($now) . ") "
                 . "ON DUPLICATE KEY UPDATE `evidence_users`=VALUES(`evidence_users`),`evidence_runs`=VALUES(`evidence_runs`),`evidence_draws`=VALUES(`evidence_draws`),`confidence_score`=VALUES(`confidence_score`),`stability_score`=VALUES(`stability_score`),`baseline_lift`=VALUES(`baseline_lift`),`status`=CASE WHEN `status`=" . $db->quote('elite') . " THEN `status` ELSE VALUES(`status`) END,`last_scored_draw_date`=VALUES(`last_scored_draw_date`),`profile_json`=VALUES(`profile_json`),`is_active`=1,`updated_at`=VALUES(`updated_at`)";
            $db->setQuery($sql);
            $db->execute();
            $out['updated_profiles']++;
            $out['candidates'][] = array(
                'game_id' => $gameId,
                'lottery_id' => $profileLotteryId,
                'input_lottery_id' => $lotteryId,
                'method_key' => $method,
                'evidence_users' => $users,
                'evidence_runs' => $runs,
                'evidence_draws' => $draws,
                'baseline_lift' => $liftPct,
                'confidence_score' => $confidence,
                'stability_score' => $stability,
                'status' => $status
            );
        }
    } catch (\Throwable $e) {
        $out['checked'] = true;
        $out['reason'] = 'query_or_upsert_failed';
    }
    return $out;
}


/* [[MLE_ELITE8B_DAILY_BONUS_STALE_PROFILE_SWEEP_V20260626]]
   Runs a small, bounded recovery sweep for daily/Pick bonus profiles that are
   not necessarily the current admin card. This closes the FLB case where the
   profile has canonical learning evidence under lottery_id 76, the settings row
   is stable/correct, but the generic admin pass is rebuilding other games only.
*/
function mylottoexpertElite8DailyBonusStaleProfileSweep($db, $limit = 12)
{
    $limit = max(1, min(25, (int)$limit));
    $out = array(
        'version' => 'ELITE8B_DAILY_BONUS_STALE_PROFILE_SWEEP_V20260626',
        'checked' => false,
        'attempted' => 0,
        'updated_profiles' => 0,
        'items' => array(),
        'reason' => 'not_started'
    );
    if (!function_exists('mylottoexpertTableExistsSafe') || !function_exists('mylottoexpertElite5RecalculateHistoricalRecoveryProfilesForGame')) {
        $out['reason'] = 'required_helper_missing';
        return $out;
    }
    if (!mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_shared_learning_profiles') || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_lottery_settings')) {
        $out['reason'] = 'required_table_missing';
        return $out;
    }
    try {
        $q = $db->getQuery(true)
            ->select(array(
                'p.' . $db->quoteName('game_id'),
                'p.' . $db->quoteName('lottery_id'),
                'p.' . $db->quoteName('method_key'),
                'p.' . $db->quoteName('profile_type'),
                'p.' . $db->quoteName('updated_at'),
                'p.' . $db->quoteName('baseline_lift'),
                's.' . $db->quoteName('main_pool_size'),
                's.' . $db->quoteName('bonus_pool_size'),
                's.' . $db->quoteName('draw_count_bonus'),
                's.' . $db->quoteName('supports_bonus'),
                's.' . $db->quoteName('supports_pairs')
            ))
            ->from($db->quoteName('#__skai_shared_learning_profiles', 'p'))
            ->join('INNER', $db->quoteName('#__skai_lottery_settings', 's') . ' ON s.' . $db->quoteName('game_id') . ' = p.' . $db->quoteName('game_id'))
            ->where('p.' . $db->quoteName('profile_type') . ' = ' . $db->quote('history_window'))
            ->where('p.' . $db->quoteName('method_key') . ' IN (' . $db->quote('skai') . ',' . $db->quote('core_ai') . ',' . $db->quote('mcmc') . ',' . $db->quote('frequency') . ',' . $db->quote('skip_hit') . ')')
            ->where('(s.' . $db->quoteName('supports_bonus') . ' = 1 OR s.' . $db->quoteName('draw_count_bonus') . ' > 0 OR s.' . $db->quoteName('bonus_pool_size') . ' > 0)')
            ->where('s.' . $db->quoteName('main_pool_size') . ' > 0')
            ->where('s.' . $db->quoteName('main_pool_size') . ' <= 10')
            ->order('p.' . $db->quoteName('updated_at') . ' ASC')
            ->setLimit($limit);
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        if (!is_array($rows)) { $rows = array(); }
        $out['checked'] = true;
        $out['reason'] = 'ok';
        foreach ($rows as $row) {
            $gid = trim((string)($row['game_id'] ?? ''));
            $lid = (int)($row['lottery_id'] ?? 0);
            if ($gid === '' || $lid <= 0) { continue; }
            $rule = function_exists('mylottoexpertElite6DailyRuleForGame') ? mylottoexpertElite6DailyRuleForGame($gid) : array();
            $isDailyBonus = false;
            if (is_array($rule) && !empty($rule)) {
                $isDailyBonus = ((int)($rule['extraBallCount'] ?? 0) > 0 || (int)($rule['rangeExtra'] ?? 0) > 0);
            }
            if (!$isDailyBonus) {
                $isDailyBonus = ((int)($row['supports_bonus'] ?? 0) > 0 || (int)($row['draw_count_bonus'] ?? 0) > 0 || (int)($row['bonus_pool_size'] ?? 0) > 0);
            }
            if (!$isDailyBonus) { continue; }
            $result = mylottoexpertElite5RecalculateHistoricalRecoveryProfilesForGame($db, $lid, $gid);
            $out['attempted']++;
            $out['updated_profiles'] += (int)($result['updated_profiles'] ?? 0);
            $out['items'][] = array(
                'game_id' => $gid,
                'lottery_id' => $lid,
                'method_key' => (string)($row['method_key'] ?? ''),
                'prior_updated_at' => (string)($row['updated_at'] ?? ''),
                'prior_baseline_lift' => (float)($row['baseline_lift'] ?? 0.0),
                'result_reason' => (string)($result['reason'] ?? ''),
                'result_updated_profiles' => (int)($result['updated_profiles'] ?? 0)
            );
        }
    } catch (\Throwable $e) {
        $out['checked'] = true;
        $out['reason'] = 'query_or_sweep_failed';
    }
    return $out;
}

function mylottoexpertSharedSkaiFetchPerformanceJoinedSettingsRows($db, $lotteryId, $gameId, &$audit)
{
    $rows = array();
    $existsPerf = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_learning_performance');
    $existsSaved = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'user_saved_numbers');
    if (!$existsPerf || !$existsSaved) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_performance_join_saved_settings', ($existsPerf && $existsSaved), 0, true, false, 'Missing performance or saved-number table.');
        return $rows;
    }
    $pCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'skai_learning_performance');
    $sCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'user_saved_numbers');
    $brExists = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'mle_skai_batch_run');
    $bhExists = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'mle_skai_batch_header');
    $brCols = $brExists ? mylottoexpertSharedSkaiSafeTableColumns($db, 'mle_skai_batch_run') : array();
    $bhCols = $bhExists ? mylottoexpertSharedSkaiSafeTableColumns($db, 'mle_skai_batch_header') : array();
    try {
        $select = array('p.*');
        foreach (array(
            'id'=>'saved_id','user_id'=>'saved_user_id','lottery_id'=>'saved_lottery_id','target_lottery_id'=>'saved_target_lottery_id','target_game_id'=>'saved_target_game_id','game_id'=>'saved_game_id','source'=>'saved_source','origin_source'=>'saved_origin_source','analysis_method_key'=>'saved_analysis_method_key','settings_json'=>'settings_json','settings'=>'settings','prediction_target_json'=>'prediction_target_json','run_uuid'=>'saved_run_uuid','source_batch_id'=>'source_batch_id','source_batch_run_id'=>'source_batch_run_id','source_batch_run_order'=>'source_batch_run_order','draws_used'=>'saved_draws_used','draws_analyzed'=>'saved_draws_analyzed','skai_window_size'=>'saved_skai_window_size','skip_window'=>'saved_skip_window','best_window'=>'saved_best_window','tuned_window'=>'saved_tuned_window'
        ) as $col=>$as) {
            $frag = mylottoexpertSharedSkaiColumnSql($db, $sCols, 's', $col, $as);
            if ($frag !== '') { $select[] = $frag; }
        }
        if ($brExists) {
            foreach (array('id'=>'batch_run_id','batch_id'=>'batch_id','run_order'=>'batch_run_order','run_name'=>'batch_run_name','source'=>'batch_run_source','method'=>'batch_run_method','test_variable'=>'test_variable','test_value'=>'test_value','full_settings_json'=>'batch_full_settings_json','settings_json'=>'batch_settings_json') as $col=>$as) {
                $frag = mylottoexpertSharedSkaiColumnSql($db, $brCols, 'br', $col, $as);
                if ($frag !== '') { $select[] = $frag; }
            }
        }
        if ($bhExists) {
            foreach (array('batch_type'=>'batch_type','test_variable'=>'header_test_variable','range_min'=>'range_min','range_max'=>'range_max','recommended_value'=>'recommended_value','recommendation_level'=>'recommendation_level','precision_progress_level'=>'precision_progress_level','precision_lock_stage'=>'precision_lock_stage','lottery_id'=>'batch_lottery_id','game_id'=>'batch_game_id') as $col=>$as) {
                $frag = mylottoexpertSharedSkaiColumnSql($db, $bhCols, 'bh', $col, $as);
                if ($frag !== '') { $select[] = $frag; }
            }
        }
        $q = $db->getQuery(true)->select($select)->from($db->quoteName('#__skai_learning_performance', 'p'));
        $joinOn = array();
        if (in_array('run_id', $pCols, true) && in_array('id', $sCols, true)) { $joinOn[] = 's.' . $db->quoteName('id') . ' = p.' . $db->quoteName('run_id'); }
        if (in_array('run_uuid', $pCols, true) && in_array('run_uuid', $sCols, true)) { $joinOn[] = 'TRIM(COALESCE(s.' . $db->quoteName('run_uuid') . ',' . $db->quote('') . ')) = TRIM(COALESCE(p.' . $db->quoteName('run_uuid') . ',' . $db->quote('') . '))'; }
        if (empty($joinOn)) { $joinOn[] = '1=0'; }
        $q->join('LEFT', $db->quoteName('#__user_saved_numbers', 's') . ' ON (' . implode(' OR ', $joinOn) . ')');
        if ($brExists) {
            $brJoin = array();
            if (in_array('source_batch_run_id', $sCols, true) && in_array('id', $brCols, true)) { $brJoin[] = 'br.' . $db->quoteName('id') . ' = s.' . $db->quoteName('source_batch_run_id'); }
            if (in_array('source_batch_id', $sCols, true) && in_array('batch_id', $brCols, true) && in_array('source_batch_run_order', $sCols, true) && in_array('run_order', $brCols, true)) {
                $brJoin[] = '(br.' . $db->quoteName('batch_id') . ' = s.' . $db->quoteName('source_batch_id') . ' AND br.' . $db->quoteName('run_order') . ' = s.' . $db->quoteName('source_batch_run_order') . ')';
            }
            if (!empty($brJoin)) { $q->join('LEFT', $db->quoteName('#__mle_skai_batch_run', 'br') . ' ON (' . implode(' OR ', $brJoin) . ')'); }
        }
        if ($bhExists && $brExists && in_array('batch_id', $brCols, true) && in_array('id', $bhCols, true)) {
            $q->join('LEFT', $db->quoteName('#__mle_skai_batch_header', 'bh') . ' ON bh.' . $db->quoteName('id') . ' = br.' . $db->quoteName('batch_id'));
        }
        $identity = array();
        foreach (array('lottery_id','target_lottery_id') as $col) { if (in_array($col, $pCols, true)) { $identity[] = 'p.' . $db->quoteName($col) . ' = ' . (int)$lotteryId; } }
        foreach (array('lottery_id','target_lottery_id') as $col) { if (in_array($col, $sCols, true)) { $identity[] = 's.' . $db->quoteName($col) . ' = ' . (int)$lotteryId; } }
        if ($gameId !== '') {
            foreach (array('target_game_id','game_id') as $col) { if (in_array($col, $pCols, true)) { $identity[] = 'TRIM(COALESCE(p.' . $db->quoteName($col) . ',' . $db->quote('') . ')) = ' . $db->quote($gameId); } }
            foreach (array('target_game_id','game_id') as $col) { if (in_array($col, $sCols, true)) { $identity[] = 'TRIM(COALESCE(s.' . $db->quoteName($col) . ',' . $db->quote('') . ')) = ' . $db->quote($gameId); } }
        }
        if (!empty($identity)) { $q->where('(' . implode(' OR ', $identity) . ')'); }
        $methodParts = array();
        foreach (array('analysis_method_key','method_key') as $col) { if (in_array($col, $pCols, true)) { $methodParts[] = 'LOWER(TRIM(COALESCE(p.' . $db->quoteName($col) . ',' . $db->quote('') . '))) = ' . $db->quote('skai'); } }
        foreach (array('source','origin_source') as $col) { if (in_array($col, $pCols, true)) { $methodParts[] = 'LOWER(TRIM(COALESCE(p.' . $db->quoteName($col) . ',' . $db->quote('') . '))) IN (' . $db->quote('skai') . ',' . $db->quote('skai_prediction') . ',' . $db->quote('skai_batch') . ')'; } }
        foreach (array('analysis_method_key','method_key') as $col) { if (in_array($col, $sCols, true)) { $methodParts[] = 'LOWER(TRIM(COALESCE(s.' . $db->quoteName($col) . ',' . $db->quote('') . '))) = ' . $db->quote('skai'); } }
        foreach (array('source','origin_source') as $col) { if (in_array($col, $sCols, true)) { $methodParts[] = 'LOWER(TRIM(COALESCE(s.' . $db->quoteName($col) . ',' . $db->quote('') . '))) IN (' . $db->quote('skai') . ',' . $db->quote('skai_prediction') . ',' . $db->quote('skai_batch') . ',' . $db->quote('mle_precision_lock_batch') . ')'; } }
        if (!empty($methodParts)) { $q->where('(' . implode(' OR ', $methodParts) . ')'); }
        $dateOrder = in_array('draw_date', $pCols, true) ? 'p.' . $db->quoteName('draw_date') : (in_array('target_draw_date', $pCols, true) ? 'p.' . $db->quoteName('target_draw_date') : 'p.' . $db->quoteName('id'));
        $q->order($dateOrder . ' DESC')->setLimit(5000);
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        if (!is_array($rows)) { $rows = array(); }
        foreach ($rows as &$r) { if (is_array($r)) { $r['_mle_shared_source_table'] = 'v55_performance_join_saved_settings'; $r['_mle_shared_identity_filter_used'] = 1; } }
        unset($r);
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_performance_join_saved_settings', true, count($rows), true, false, 'Checked performance joined to saved AI settings and MLE settings test run settings.');
        return $rows;
    } catch (\Throwable $e) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_performance_join_saved_settings', true, 0, true, true, 'Read failed while joining performance to saved settings.');
        return array();
    }
}

function mylottoexpertSharedSkaiFetchLearningEventsJoinedSettingsRows($db, $lotteryId, $gameId, &$audit)
{
    $rows = array();
    $existsEvents = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_learning_events');
    $existsSaved = mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'user_saved_numbers');
    if (!$existsEvents || !$existsSaved) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_learning_events_join_saved_settings', ($existsEvents && $existsSaved), 0, true, false, 'Missing learning-event or saved-number table.');
        return $rows;
    }
    $eCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'skai_learning_events');
    $sCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'user_saved_numbers');
    try {
        $select = array('e.*');
        foreach (array('id'=>'saved_id','user_id'=>'saved_user_id','lottery_id'=>'saved_lottery_id','target_lottery_id'=>'saved_target_lottery_id','target_game_id'=>'saved_target_game_id','game_id'=>'saved_game_id','source'=>'saved_source','origin_source'=>'saved_origin_source','analysis_method_key'=>'saved_analysis_method_key','settings_json'=>'settings_json','settings'=>'settings','prediction_target_json'=>'prediction_target_json','run_uuid'=>'saved_run_uuid','draws_used'=>'saved_draws_used','draws_analyzed'=>'saved_draws_analyzed','skai_window_size'=>'saved_skai_window_size','skip_window'=>'saved_skip_window','best_window'=>'saved_best_window','tuned_window'=>'saved_tuned_window') as $col=>$as) {
            $frag = mylottoexpertSharedSkaiColumnSql($db, $sCols, 's', $col, $as);
            if ($frag !== '') { $select[] = $frag; }
        }
        $q = $db->getQuery(true)->select($select)->from($db->quoteName('#__skai_learning_events', 'e'));
        $joinOn = array();
        if (in_array('run_uuid', $eCols, true) && in_array('run_uuid', $sCols, true)) { $joinOn[] = 'TRIM(COALESCE(s.' . $db->quoteName('run_uuid') . ',' . $db->quote('') . ')) = TRIM(COALESCE(e.' . $db->quoteName('run_uuid') . ',' . $db->quote('') . '))'; }
        if (in_array('target_draw_date', $eCols, true) && in_array('target_draw_date', $sCols, true) && in_array('game_id', $eCols, true) && in_array('target_game_id', $sCols, true)) {
            $joinOn[] = '(TRIM(COALESCE(s.' . $db->quoteName('target_game_id') . ',' . $db->quote('') . ')) = TRIM(COALESCE(e.' . $db->quoteName('game_id') . ',' . $db->quote('') . ')) AND s.' . $db->quoteName('target_draw_date') . ' = e.' . $db->quoteName('target_draw_date') . ')';
        }
        if (empty($joinOn)) { $joinOn[] = '1=0'; }
        $q->join('LEFT', $db->quoteName('#__user_saved_numbers', 's') . ' ON (' . implode(' OR ', $joinOn) . ')');
        $identity = array();
        if ($gameId !== '' && in_array('game_id', $eCols, true)) { $identity[] = 'TRIM(COALESCE(e.' . $db->quoteName('game_id') . ',' . $db->quote('') . ')) = ' . $db->quote($gameId); }
        foreach (array('lottery_id','target_lottery_id') as $col) { if (in_array($col, $sCols, true)) { $identity[] = 's.' . $db->quoteName($col) . ' = ' . (int)$lotteryId; } }
        if ($gameId !== '') { foreach (array('target_game_id','game_id') as $col) { if (in_array($col, $sCols, true)) { $identity[] = 'TRIM(COALESCE(s.' . $db->quoteName($col) . ',' . $db->quote('') . ')) = ' . $db->quote($gameId); } } }
        if (!empty($identity)) { $q->where('(' . implode(' OR ', $identity) . ')'); }
        if (in_array('is_learned', $eCols, true)) { $q->where('e.' . $db->quoteName('is_learned') . ' = 1'); }
        $q->order((in_array('target_draw_date', $eCols, true) ? 'e.' . $db->quoteName('target_draw_date') : 'e.' . $db->quoteName('id')) . ' DESC')->setLimit(5000);
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        if (!is_array($rows)) { $rows = array(); }
        foreach ($rows as &$r) { if (is_array($r)) { $r['_mle_shared_source_table'] = 'v55_learning_events_join_saved_settings'; $r['_mle_shared_identity_filter_used'] = 1; } }
        unset($r);
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_learning_events_join_saved_settings', true, count($rows), true, false, 'Elite AI learning events joined to saved settings by run UUID / exact draw.');
        return $rows;
    } catch (\Throwable $e) {
        mylottoexpertSharedSkaiAddAuditTable($audit, 'v55_learning_events_join_saved_settings', true, 0, true, true, 'Read failed while joining learning events to saved settings.');
        return array();
    }
}

function mylottoexpertBuildAndSaveSharedSkaiHistoryWindowProfile($db, $lotteryId, array $cardRows = array())
{
    $lotteryId = (int)$lotteryId;
    $gameId = mylottoexpertResolveGameIdForLottery($db, $lotteryId, $cardRows);
    $backfillAudit = array(
        'version' => 'v80_global_learning_batch_intelligence',
        'mode' => 'user_saved_numbers_primary_plus_joined_skai_evidence_mapper',
        'total_rows_scanned' => 0,
        'usable_rows' => 0,
        'all_settings_usable_rows' => 0,
        'all_settings_users' => 0,
        'all_settings_draws' => 0,
        'history_window_usable_rows' => 0,
        'accepted_users' => 0,
        'accepted_draws' => 0,
        'tables_checked' => array(),
        'accepted_by_table' => array(),
        'window_keys_found' => array(),
        'skipped' => array(
            'identity_mismatch' => 0,
            'not_skai' => 0,
            'missing_settings' => 0,
            'missing_window' => 0,
            'invalid_draw_date' => 0,
            'not_scored_or_evaluated' => 0,
            'missing_prediction_numbers' => 0,
            'excluded_or_deleted' => 0
        ),
        'reality_audit' => array(),
        'skipped_by_table' => array(),
        'sample_rejections' => array(),
        'accepted_samples' => array(),
        'built_from_existing_database' => true,
        'mapper_note' => 'v79 makes all-settings intelligence the main learning objective. History Window remains one setting family. The mapper studies reliability, consistency, weak signals, and outlier repair from every valid scored AI saved run for this exact lottery.'
    );
    $empty = array(
        'available' => false,
        'status' => 'unavailable',
        'message' => 'Shared AI Learning is not available yet.',
        'game_id' => $gameId,
        'lottery_id' => $lotteryId,
        'method_key' => 'skai',
        'profile_type' => 'history_window',
        'evidence_users' => 0,
        'evidence_runs' => 0,
        'evidence_draws' => 0,
        'confidence_score' => 0.0,
        'stability_score' => 0.0,
        'recommended_window_min' => 0,
        'recommended_window_max' => 0,
        'recommended_window_center' => 0,
        'profile_json' => array(),
        'historical_backfill' => $backfillAudit
    );
    if ($lotteryId <= 0 || !mylottoexpertSharedSkaiLearningTableReady($db)) { return $empty; }

    $rows = array();

    $primarySavedRows = mylottoexpertSharedSkaiFetchUserSavedNumbersPrimaryRows($db, $lotteryId, $gameId, $backfillAudit);
    if (!empty($primarySavedRows)) { $rows = array_merge($rows, $primarySavedRows); }

    $perfRows = mylottoexpertSharedSkaiFetchPerformanceJoinedSettingsRows($db, $lotteryId, $gameId, $backfillAudit);
    if (!empty($perfRows)) { $rows = array_merge($rows, $perfRows); }
    $eventRows = mylottoexpertSharedSkaiFetchLearningEventsJoinedSettingsRows($db, $lotteryId, $gameId, $backfillAudit);
    if (!empty($eventRows)) { $rows = array_merge($rows, $eventRows); }

    $genericSources = array(
        'skai_backtest_summary',
        'skai_backtest_metrics',
        'skai_parameter_sets',
        'skai_run_log',
        'skai_shared_learning',
        'skai_tail_recovery_summary',
        'skai_best_settings'
    );
    foreach ($genericSources as $tableName) {
        $scan = mylottoexpertSharedSkaiFetchGenericTableRows($db, $tableName, $lotteryId, $gameId, 5000);
        $backfillAudit['tables_checked'][$tableName] = array(
            'exists' => !empty($scan['exists']),
            'scanned' => (int)($scan['scanned'] ?? 0),
            'identity_filter_used' => !empty($scan['identity_filter_used']),
            'read_error' => !empty($scan['read_error'])
        );
        if (!empty($scan['rows'])) { $rows = array_merge($rows, $scan['rows']); }
    }

    $scored = array();
    $users = array();
    $draws = array();
    $lastDate = '';
    $baselineLiftSum = 0.0;
    $baselineCount = 0;
    $seen = array();
    $allSettingsRows = 0;
    $allSettingsUsers = array();
    $allSettingsDraws = array();
    $allSettingsEvidenceRows = array();
    $backfillAudit['total_rows_scanned'] = count($rows);

    // [[MLE_ELITE4_BASELINE_LIFT]] Calculate lift from comparable top20 hit evidence when row-level lift fields are absent.
    $baselineTop20HitSum = 0.0;
    $baselineTop20Count = 0;
    $baselineExpectedTop20 = 0.0;
    try {
        if (mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_lottery_settings')) {
            $bq = $db->getQuery(true)
                ->select(array($db->quoteName('main_pool_size'), $db->quoteName('draw_count_main')))
                ->from($db->quoteName('#__skai_lottery_settings'))
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->setLimit(1);
            $db->setQuery($bq);
            $br = (array)$db->loadAssoc();
            $pool = (int)($br['main_pool_size'] ?? 0);
            $drawMain = (int)($br['draw_count_main'] ?? 0);
            if ($pool > 0 && $drawMain > 0) { $baselineExpectedTop20 = $drawMain * (min(20, $pool) / $pool); }
        }
    } catch (\Throwable $e) { $baselineExpectedTop20 = 0.0; }
    $backfillAudit['baseline_expected_top20_hits'] = $baselineExpectedTop20;

    foreach ($rows as $row) {
        if (!is_array($row)) { continue; }
        $table = (string)($row['_mle_shared_source_table'] ?? 'unknown');
        if (!isset($backfillAudit['accepted_by_table'][$table])) { $backfillAudit['accepted_by_table'][$table] = 0; }
        if (!isset($backfillAudit['skipped_by_table'][$table])) {
            $backfillAudit['skipped_by_table'][$table] = array('identity_mismatch'=>0,'not_skai'=>0,'missing_settings'=>0,'missing_window'=>0,'invalid_draw_date'=>0,'not_scored_or_evaluated'=>0,'missing_prediction_numbers'=>0,'excluded_or_deleted'=>0);
        }
        $rowId = (int)mylottoexpertSharedSkaiFirstValue($row, array('id','saved_id','run_id','parameter_set_id'), 0);
        $dedupeKey = $table . ':' . $rowId . ':' . md5(json_encode(array_slice($row, 0, 20), JSON_UNESCAPED_SLASHES));
        if (isset($seen[$dedupeKey])) { continue; }
        $seen[$dedupeKey] = true;

        $drawDate = mylottoexpertSharedSkaiExtractDrawDateFromRow($row);
        if ($drawDate === '') {
            $drawDate = mylottoexpertSharedSkaiNormalizeDateValue(mylottoexpertSharedSkaiFirstValue($row, array('date_saved','generated_at','run_date','created_at','updated_at'), ''));
        }
        if ($drawDate === '') {
            $backfillAudit['skipped']['invalid_draw_date']++;
            $backfillAudit['skipped_by_table'][$table]['invalid_draw_date']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'invalid_draw_date'); }
            continue;
        }
        if (!mylottoexpertSharedSkaiIdentityMatches($row, $lotteryId, $gameId)) {
            $backfillAudit['skipped']['identity_mismatch']++;
            $backfillAudit['skipped_by_table'][$table]['identity_mismatch']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'identity_mismatch'); }
            continue;
        }
        if ($table === 'user_saved_numbers_primary' && mylottoexpertSharedSkaiRowIsExcluded($row)) {
            $backfillAudit['skipped']['excluded_or_deleted']++;
            $backfillAudit['skipped_by_table'][$table]['excluded_or_deleted']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'excluded_or_deleted'); }
            continue;
        }
        if ($table === 'user_saved_numbers_primary' && !mylottoexpertSharedSkaiRowIsScoredEvaluated($row)) {
            $backfillAudit['skipped']['not_scored_or_evaluated']++;
            $backfillAudit['skipped_by_table'][$table]['not_scored_or_evaluated']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'not_scored_or_evaluated'); }
            continue;
        }
        if ($table === 'user_saved_numbers_primary' && !mylottoexpertSharedSkaiRowHasPredictionNumbers($row)) {
            $backfillAudit['skipped']['missing_prediction_numbers']++;
            $backfillAudit['skipped_by_table'][$table]['missing_prediction_numbers']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'missing_prediction_numbers'); }
            continue;
        }
        if (!mylottoexpertSharedSkaiIsSkaiRow($row)) {
            $backfillAudit['skipped']['not_skai']++;
            $backfillAudit['skipped_by_table'][$table]['not_skai']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'not_skai'); }
            continue;
        }
        if (!mylottoexpertSharedSkaiRowHasSettingsEvidence($row)) {
            $backfillAudit['skipped']['missing_settings']++;
            $backfillAudit['skipped_by_table'][$table]['missing_settings']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'missing_settings'); }
            continue;
        }
        $settings = mylottoexpertDecodeSettingsFromSharedLearningRow($row);
        $settings = mylottoexpertMergeSharedLearningSettings($settings, $row);
        if ($table === 'user_saved_numbers_primary') {
            $allSettingsRows++;
            $asu = (int)mylottoexpertSharedSkaiFirstValue($row, array('user_id','saved_user_id','created_by','owner_id'), 0);
            if ($asu > 0) { $allSettingsUsers[$asu] = true; }
            if ($drawDate !== '') { $allSettingsDraws[$drawDate] = true; }
            $allSettingsEvidenceRows[] = mylottoexpertV79BuildSettingsEvidenceRow($row, $settings, $drawDate, $table, $rowId);
        }
        $windowInfo = mylottoexpertExtractSkaiWindowInfo($settings);
        $window = (int)($windowInfo['window'] ?? 0);
        if ($window <= 0) {
            $backfillAudit['skipped']['missing_window']++;
            $backfillAudit['skipped_by_table'][$table]['missing_window']++;
            if (count($backfillAudit['sample_rejections']) < 25) { $backfillAudit['sample_rejections'][] = mylottoexpertSharedSkaiBuildSkipDrilldownRow($row, $table, $rowId, 'missing_window'); }
            continue;
        }
        $foundKey = (string)($windowInfo['key'] ?? 'window');
        if (!isset($backfillAudit['window_keys_found'][$foundKey])) { $backfillAudit['window_keys_found'][$foundKey] = 0; }
        $backfillAudit['window_keys_found'][$foundKey]++;

        $edge = function_exists('mleAdvisoryCalculateRandomEdgeForRow') ? mleAdvisoryCalculateRandomEdgeForRow($row) : array();
        $score = mylottoexpertSharedSkaiRowScore($row);
        if (!empty($edge)) {
            $score += ((float)($edge['avg_rank_lift'] ?? 0.0) * 8.0) + ((float)($edge['penalized_rank_lift'] ?? 0.0) * 10.0);
        }
        $penLift = (float)($edge['penalized_rank_lift'] ?? mylottoexpertSharedSkaiFirstValue($row, array('penalized_rank_lift','baseline_lift'), 0.0));
        $trendBucket = strtolower(trim((string)($row['trend_bucket'] ?? '')));
        $top20Raw = mylottoexpertSharedSkaiFirstValue($row, array('top20_hits','top_20_hits'), null);
        if ($baselineExpectedTop20 > 0.0 && $trendBucket !== 'post_draw_cron' && $top20Raw !== null && is_numeric($top20Raw)) {
            $baselineTop20HitSum += (float)$top20Raw;
            $baselineTop20Count++;
        }
        $scored[] = array('window' => $window, 'score' => $score, 'draw_date' => $drawDate, 'table' => $table, 'window_key' => $foundKey);
        $backfillAudit['accepted_by_table'][$table]++;
        if (count($backfillAudit['accepted_samples']) < 8) { $backfillAudit['accepted_samples'][] = array('table'=>$table,'row_id'=>$rowId,'window'=>$window,'key'=>$foundKey,'draw_date'=>$drawDate); }
        $uid = (int)mylottoexpertSharedSkaiFirstValue($row, array('user_id','saved_user_id','created_by','owner_id'), 0);
        if ($uid > 0) { $users[$uid] = true; }
        $draws[$drawDate] = true;
        if ($lastDate === '' || strcmp($drawDate, $lastDate) > 0) { $lastDate = $drawDate; }
        $baselineLiftSum += $penLift;
        $baselineCount++;
    }

    $runCount = count($scored);
    $userCount = count($users);
    $drawCount = count($draws);
    $backfillAudit['usable_rows'] = $runCount;
    $backfillAudit['history_window_usable_rows'] = $runCount;
    $backfillAudit['all_settings_usable_rows'] = $allSettingsRows;
    $backfillAudit['all_settings_users'] = count($allSettingsUsers);
    $backfillAudit['all_settings_draws'] = count($allSettingsDraws);
    $backfillAudit['accepted_users'] = $userCount;
    $backfillAudit['accepted_draws'] = $drawCount;
    $v79SettingsIntelligence = mylottoexpertV79BuildSettingsIntelligence($allSettingsEvidenceRows);
    $backfillAudit['v79_settings_intelligence_summary'] = array(
        'usable_rows' => (int)($v79SettingsIntelligence['usable_rows'] ?? 0),
        'users' => (int)($v79SettingsIntelligence['users'] ?? 0),
        'draws' => (int)($v79SettingsIntelligence['draws'] ?? 0),
        'learning_posture' => (string)($v79SettingsIntelligence['learning_posture'] ?? 'building'),
        'top_setting_patterns' => array_slice((array)($v79SettingsIntelligence['top_setting_patterns'] ?? array()), 0, 8),
        'outlier_recovery_settings' => array_slice((array)($v79SettingsIntelligence['outlier_recovery_settings'] ?? array()), 0, 8),
        'next_controlled_test' => (array)($v79SettingsIntelligence['next_controlled_test'] ?? array())
    );

    if ($runCount < 1) {
        $profile = $empty;
        $profile['status'] = 'collecting';
        $profile['message'] = 'Historical AI data was found, but the mapper did not yet find rows with verified History Window prediction history. Rows that are scored AI settings prediction history but missing a window are still counted separately as all-settings prediction history in the admin audit.';
        $profile['historical_backfill'] = $backfillAudit;
        $profile['global_settings_intelligence'] = $v79SettingsIntelligence;
    } else {
        usort($scored, function($a, $b) { return ($b['score'] > $a['score']) ? 1 : (($b['score'] < $a['score']) ? -1 : 0); });
        $cutStrong = max(1, (int)ceil($runCount * 0.40));
        $strong = array_slice($scored, 0, $cutStrong);
        $strongVals = array_map(function($r) { return (int)$r['window']; }, $strong);
        $wMin = (int)min($strongVals);
        $wMax = (int)max($strongVals);
        $wCenter = (int)round(array_sum($strongVals) / max(1, count($strongVals)));
        $cutSweet = max(1, (int)ceil($runCount * 0.20));
        $sweet = array_slice($scored, 0, $cutSweet);
        $sweetVals = array_map(function($r) { return (int)$r['window']; }, $sweet);
        $sweetMin = (int)min($sweetVals);
        $sweetMax = (int)max($sweetVals);
        $width = max(0, $wMax - $wMin);
        $stability = max(0.0, min(1.0, 1.0 - ($width / 975.0)));
        $evidenceFactor = min(1.0, ($runCount / 60.0) * 0.45 + ($drawCount / 10.0) * 0.35 + ($userCount / 3.0) * 0.20);
        $rowFieldBaselineLift = $baselineCount > 0 ? ($baselineLiftSum / $baselineCount) : 0.0;
        $top20BaselineLift = 0.0;
        if ($baselineTop20Count > 0 && $baselineExpectedTop20 > 0.0) {
            $avgTop20Hits = $baselineTop20HitSum / $baselineTop20Count;
            $top20BaselineLift = ($avgTop20Hits - $baselineExpectedTop20) / max(0.000001, $baselineExpectedTop20);
            $backfillAudit['baseline_lift_source'] = 'top20_hits_vs_random_expected';
            $backfillAudit['baseline_top20_rows'] = $baselineTop20Count;
            $backfillAudit['baseline_avg_top20_hits'] = $avgTop20Hits;
        } else {
            $backfillAudit['baseline_lift_source'] = 'row_fields';
            $backfillAudit['baseline_top20_rows'] = $baselineTop20Count;
        }
        $baselineLift = ($top20BaselineLift != 0.0) ? $top20BaselineLift : $rowFieldBaselineLift;
        $baselineFactor = $baselineLift > 0 ? min(1.0, $baselineLift / 0.25) : 0.0;
        $confidence = max(0.0, min(0.95, ($evidenceFactor * 0.55) + ($stability * 0.30) + ($baselineFactor * 0.15)));
        $runtimeHealth = mylottoexpertEliteSharedSkaiRuntimeHealth($db, $gameId);
        $eliteGate = mylottoexpertEliteSharedSkaiStatusGate(array(
            'evidence_users' => $userCount,
            'evidence_runs' => $runCount,
            'evidence_draws' => $drawCount,
            'confidence_score' => $confidence,
            'stability_score' => $stability,
            'baseline_lift' => $baselineLift,
            'runtime_ok' => !empty($runtimeHealth['elite_runtime_ok'])
        ));
        $status = (string)($eliteGate['status'] ?? 'collecting');
        $profileJson = array(
            'version' => 'v80_global_learning_batch_intelligence',
            'rule' => 'exact_identity_scored_user_saved_number_with_skai_settings_and_evaluated_outcome',
            'recommended_window_min' => $wMin,
            'recommended_window_max' => $wMax,
            'recommended_window_center' => $wCenter,
            'sweet_window_min' => $sweetMin,
            'sweet_window_max' => $sweetMax,
            'top_windows' => array_slice($scored, 0, 12),
            'all_settings_evidence' => array(
                'usable_rows' => (int)$allSettingsRows,
                'users' => count($allSettingsUsers),
                'draws' => count($allSettingsDraws),
                'note' => 'All-settings prediction history is the main global learning objective. History Window is one setting family.'
            ),
            'global_settings_intelligence' => $v79SettingsIntelligence,
            'elite_runtime_health' => $runtimeHealth,
            'elite_gate' => $eliteGate,
            'thresholds' => array(
                'ready_users'=>3,'ready_runs'=>30,'ready_draws'=>8,'ready_confidence'=>0.65,'ready_stability'=>0.20,'ready_baseline_lift_min'=>0.000001,
                'strong_users'=>5,'strong_runs'=>80,'strong_draws'=>15,'strong_confidence'=>0.75,'strong_stability'=>0.35,'strong_baseline_lift'=>0.05,
                'elite_users'=>8,'elite_runs'=>150,'elite_draws'=>25,'elite_confidence'=>0.85,'elite_stability'=>0.50,'elite_baseline_lift'=>0.10,
                'runtime_audit_required'=>'clean_no_fallback_no_domain_or_display_mismatch'
            ),
            'historical_backfill' => $backfillAudit,
            'updated_by' => 'mylottoexpert'
        );
        $profile = array(
            'available' => true,
            'status' => $status,
            'message' => $status === 'collecting' ? 'Shared AI Learning found usable historical prediction history and is still collecting enough support.' : 'Shared AI Learning built this starting window from scored saved AI predictions with exact target identity, saved settings, and evaluated outcome history.',
            'game_id' => $gameId,
            'lottery_id' => $lotteryId,
            'method_key' => 'skai',
            'profile_type' => 'history_window',
            'recommended_window_min' => $wMin,
            'recommended_window_max' => $wMax,
            'recommended_window_center' => $wCenter,
            'sweet_window_min' => $sweetMin,
            'sweet_window_max' => $sweetMax,
            'evidence_users' => $userCount,
            'evidence_runs' => $runCount,
            'evidence_draws' => $drawCount,
            'all_settings_evidence_users' => count($allSettingsUsers),
            'all_settings_evidence_runs' => (int)$allSettingsRows,
            'all_settings_evidence_draws' => count($allSettingsDraws),
            'confidence_score' => $confidence,
            'stability_score' => $stability,
            'baseline_lift' => $baselineLift,
            'last_scored_draw_date' => $lastDate,
            'profile_json' => $profileJson,
            'global_settings_intelligence' => $v79SettingsIntelligence,
            'elite_runtime_health' => $runtimeHealth,
            'elite_gate' => $eliteGate,
            'historical_backfill' => $backfillAudit
        );
        try {
            $rawName = $db->getPrefix() . 'skai_shared_learning_profiles';
            $now = date('Y-m-d H:i:s');
            $lastSql = $lastDate !== '' ? $db->quote($lastDate) : 'NULL';
            $jsonSql = $db->quote(json_encode($profileJson, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $backfillSql = $db->quote(json_encode($backfillAudit, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            $sql = "INSERT INTO `{$rawName}` "
                 . "(`game_id`,`lottery_id`,`method_key`,`profile_type`,`recommended_window_min`,`recommended_window_max`,`recommended_window_center`,`sweet_window_min`,`sweet_window_max`,`evidence_users`,`evidence_runs`,`evidence_draws`,`confidence_score`,`stability_score`,`baseline_lift`,`status`,`last_scored_draw_date`,`profile_json`,`historical_backfill_json`,`last_backfill_at`,`is_active`,`created_at`,`updated_at`) VALUES ("
                 . $db->quote($gameId) . "," . (int)$lotteryId . "," . $db->quote('skai') . "," . $db->quote('history_window') . ","
                 . (int)$wMin . "," . (int)$wMax . "," . (int)$wCenter . "," . (int)$sweetMin . "," . (int)$sweetMax . ","
                 . (int)$userCount . "," . (int)$runCount . "," . (int)$drawCount . "," . number_format($confidence, 6, '.', '') . "," . number_format($stability, 6, '.', '') . "," . number_format($baselineLift, 6, '.', '') . ","
                 . $db->quote($status) . "," . $lastSql . "," . $jsonSql . "," . $backfillSql . "," . $db->quote($now) . ",1," . $db->quote($now) . "," . $db->quote($now) . ") "
                 . "ON DUPLICATE KEY UPDATE `recommended_window_min`=VALUES(`recommended_window_min`),`recommended_window_max`=VALUES(`recommended_window_max`),`recommended_window_center`=VALUES(`recommended_window_center`),`sweet_window_min`=VALUES(`sweet_window_min`),`sweet_window_max`=VALUES(`sweet_window_max`),`evidence_users`=VALUES(`evidence_users`),`evidence_runs`=VALUES(`evidence_runs`),`evidence_draws`=VALUES(`evidence_draws`),`confidence_score`=VALUES(`confidence_score`),`stability_score`=VALUES(`stability_score`),`baseline_lift`=VALUES(`baseline_lift`),`status`=VALUES(`status`),`last_scored_draw_date`=VALUES(`last_scored_draw_date`),`profile_json`=VALUES(`profile_json`),`historical_backfill_json`=VALUES(`historical_backfill_json`),`last_backfill_at`=VALUES(`last_backfill_at`),`is_active`=1,`updated_at`=VALUES(`updated_at`)";
            $db->setQuery($sql);
            $db->execute();
        } catch (\Throwable $e) {

        }
    }
    if (function_exists('mylottoexpertElite5RecalculateHistoricalRecoveryProfilesForGame')) {
        $profile['elite6_daily_fireball_recovery'] = mylottoexpertElite5RecalculateHistoricalRecoveryProfilesForGame($db, $lotteryId, $gameId);
    }
    if (function_exists('mylottoexpertElite8DailyBonusStaleProfileSweep')) {
        $profile['elite8b_daily_bonus_stale_profile_sweep'] = mylottoexpertElite8DailyBonusStaleProfileSweep($db, 12);
    }
    return $profile;
}

function mylottoexpertV56EvidenceCheck($key, $label, $ok, $detail)
{
    return array(
        'key' => (string)$key,
        'label' => (string)$label,
        'ok' => (bool)$ok,
        'status' => !empty($ok) ? 'yes' : 'no',
        'detail' => (string)$detail
    );
}

function mylottoexpertV56LoadSavedRowsForBatch($db, $userId, $lotteryId, $batchId, array $matchedSavedIds = array())
{
    $userId = (int)$userId;
    $lotteryId = (int)$lotteryId;
    $batchId = (int)$batchId;
    $out = array();
    if ($userId <= 0 || $lotteryId <= 0 || $batchId <= 0 || !mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'user_saved_numbers')) { return $out; }
    $cols = mylottoexpertSharedSkaiSafeTableColumns($db, 'user_saved_numbers');
    if (empty($cols)) { return $out; }
    $select = array();
    foreach (array('id','user_id','lottery_id','target_lottery_id','game_id','target_game_id','source','origin_source','analysis_method_key','label','settings_json','settings','prediction_target_json','run_uuid','source_batch_id','source_batch_run_id','source_batch_run_order','draw_date','target_draw_date','created_at','updated_at','skai_window_size','skip_window','draws_used','draws_analyzed','best_window','tuned_window') as $col) {
        if (in_array($col, $cols, true)) { $select[] = $db->quoteName($col); }
    }
    if (empty($select)) { return $out; }
    $where = array();
    if (in_array('source_batch_id', $cols, true)) { $where[] = $db->quoteName('source_batch_id') . ' = ' . $batchId; }
    $ids = array();
    foreach ($matchedSavedIds as $sid) { $sid = (int)$sid; if ($sid > 0) { $ids[$sid] = true; } }
    if (!empty($ids) && in_array('id', $cols, true)) { $where[] = $db->quoteName('id') . ' IN (' . implode(',', array_map('intval', array_keys($ids))) . ')'; }
    if (empty($where)) { return $out; }
    try {
        $q = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__user_saved_numbers'))
            ->where($db->quoteName('user_id') . ' = ' . $userId)
            ->where($db->quoteName('lottery_id') . ' = ' . $lotteryId)
            ->where('(' . implode(' OR ', $where) . ')')
            ->order($db->quoteName('id') . ' DESC')
            ->setLimit(250);
        $db->setQuery($q);
        $rows = $db->loadAssocList();
        return is_array($rows) ? $rows : array();
    } catch (\Throwable $e) { return array(); }
}

function mylottoexpertV56CountScoredRowsForSavedBatch($db, array $savedRows, $gameId)
{
    $out = array('performance_count'=>0, 'learning_event_count'=>0, 'scored_count'=>0, 'linked_settings_count'=>0, 'run_uuid_count'=>0);
    if (empty($savedRows)) { return $out; }
    $savedIds = array();
    $runUuids = array();
    foreach ($savedRows as $row) {
        $sid = (int)($row['id'] ?? 0);
        if ($sid > 0) { $savedIds[$sid] = true; }
        $ru = preg_replace('/[^a-zA-Z0-9\-_.]/', '', (string)($row['run_uuid'] ?? ''));
        if ($ru !== '') { $runUuids[$ru] = true; }
        $settings = mylottoexpertDecodeSettingsFromSharedLearningRow($row);
        $settings = mylottoexpertMergeSharedLearningSettings($settings, $row);
        $wi = mylottoexpertExtractSkaiWindowInfo($settings);
        if ((int)($wi['window'] ?? 0) > 0) { $out['linked_settings_count']++; }
    }
    $out['run_uuid_count'] = count($runUuids);

    if (!empty($savedIds) && mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_learning_performance')) {
        $pCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'skai_learning_performance');
        if (!empty($pCols)) {
            $joinParts = array();
            if (in_array('run_id', $pCols, true)) { $joinParts[] = $db->quoteName('run_id') . ' IN (' . implode(',', array_map('intval', array_keys($savedIds))) . ')'; }
            if (!empty($runUuids) && in_array('run_uuid', $pCols, true)) {
                $quoted = array();
                foreach (array_keys($runUuids) as $ru) { $quoted[] = $db->quote($ru); }
                $joinParts[] = $db->quoteName('run_uuid') . ' IN (' . implode(',', $quoted) . ')';
            }
            if (!empty($joinParts)) {
                try {
                    $q = $db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__skai_learning_performance'))->where('(' . implode(' OR ', $joinParts) . ')');
                    if ($gameId !== '' && in_array('target_game_id', $pCols, true)) { $q->where('(' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameId) . ' OR ' . $db->quoteName('target_game_id') . ' = ' . $db->quote('') . ')'); }
                    if (in_array('draw_date', $pCols, true)) { $q->where($db->quoteName('draw_date') . ' IS NOT NULL')->where($db->quoteName('draw_date') . ' <> ' . $db->quote('0000-00-00')); }
                    $db->setQuery($q);
                    $out['performance_count'] = (int)$db->loadResult();
                } catch (\Throwable $e) { $out['performance_count'] = 0; }
            }
        }
    }

    if (!empty($runUuids) && mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'skai_learning_events')) {
        $eCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'skai_learning_events');
        if (in_array('run_uuid', $eCols, true)) {
            $quoted = array();
            foreach (array_keys($runUuids) as $ru) { $quoted[] = $db->quote($ru); }
            try {
                $q = $db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__skai_learning_events'))->where($db->quoteName('run_uuid') . ' IN (' . implode(',', $quoted) . ')');
                if ($gameId !== '' && in_array('game_id', $eCols, true)) { $q->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId)); }
                if (in_array('is_learned', $eCols, true)) { $q->where($db->quoteName('is_learned') . ' = 1'); }
                $db->setQuery($q);
                $out['learning_event_count'] = (int)$db->loadResult();
            } catch (\Throwable $e) { $out['learning_event_count'] = 0; }
        }
    }
    $out['scored_count'] = (int)$out['performance_count'] + (int)$out['learning_event_count'];
    return $out;
}

function mylottoexpertBuildHistoryWindowEvidenceVerification($db, $userId, $lotteryId, $gameId, array $sharedProfile = array())
{
    $userId = (int)$userId;
    $lotteryId = (int)$lotteryId;
    $gameId = trim((string)$gameId);
    $out = array(
        'version' => 'v60_full_skai_settings_evidence_mapper',
        'available' => true,
        'lottery_id' => $lotteryId,
        'game_id' => $gameId,
        'batch_id' => 0,
        'batch_status' => '',
        'batch_created_at' => '',
        'batch_name' => '',
        'reason' => '',
        'checks' => array(),
        'counts' => array('batch_runs'=>0,'saved_prediction_rows'=>0,'saved_distinct_runs'=>0,'window_values_found'=>0,'scored_rows'=>0,'linked_settings_rows'=>0),
        'window_values' => array()
    );
    if ($userId <= 0 || $lotteryId <= 0) {
        $out['available'] = false;
        $out['reason'] = 'Missing user or lottery identity.';
        return $out;
    }
    $prefix = $db->getPrefix();
    $hasHeader = mylottoexpertTableExistsSafe($db, $prefix . 'mle_skai_batch_header');
    $hasRun = mylottoexpertTableExistsSafe($db, $prefix . 'mle_skai_batch_run');
    if (!$hasHeader || !$hasRun) {
        $out['checks'][] = mylottoexpertV56EvidenceCheck('batch_created', 'History Window settings test group created', false, 'Batch tables are not available yet.');
        $out['reason'] = 'History Window settings test group tables are missing.';
        return $out;
    }

    $header = array();
    try {
        $hCols = mylottoexpertSharedSkaiSafeTableColumns($db, 'mle_skai_batch_header');
        $select = array();
        foreach (array('id','user_id','lottery_id','lottery_name','batch_name','batch_type','batch_source','source_page','status','test_variable','range_min','range_max','recommended_value','precision_lock_stage','recommendation_level','precision_progress_level','evidence_summary','created_at') as $col) {
            if (in_array($col, $hCols, true)) { $select[] = $db->quoteName($col); }
        }
        if (empty($select)) { $select[] = '*'; }
        $historyParts = array();
        if (in_array('test_variable', $hCols, true)) { $historyParts[] = $db->quoteName('test_variable') . ' LIKE ' . $db->quote('%History Window%'); }
        if (in_array('batch_type', $hCols, true)) {
            $historyParts[] = $db->quoteName('batch_type') . ' LIKE ' . $db->quote('%History Window%');
            $historyParts[] = $db->quoteName('batch_type') . ' LIKE ' . $db->quote('%History Horizon%');
            $historyParts[] = $db->quoteName('batch_type') . ' LIKE ' . $db->quote('%Horizon%');
            $historyParts[] = $db->quoteName('batch_type') . ' LIKE ' . $db->quote('%Window%');
        }
        $q = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__mle_skai_batch_header'))
            ->where($db->quoteName('user_id') . ' = ' . $userId)
            ->where($db->quoteName('lottery_id') . ' = ' . $lotteryId);
        if (!empty($historyParts)) { $q->where('(' . implode(' OR ', $historyParts) . ')'); }
        $q->order($db->quoteName('id') . ' DESC')->setLimit(1);
        $db->setQuery($q);
        $header = $db->loadAssoc();
        if (!is_array($header)) { $header = array(); }
    } catch (\Throwable $e) { $header = array(); }

    $batchId = (int)($header['id'] ?? 0);
    $out['batch_id'] = $batchId;
    $out['batch_status'] = (string)($header['status'] ?? '');
    $out['batch_created_at'] = (string)($header['created_at'] ?? '');
    $out['batch_name'] = (string)($header['batch_name'] ?? '');
    $out['checks'][] = mylottoexpertV56EvidenceCheck('batch_created', 'History Window settings test group created', $batchId > 0, $batchId > 0 ? ('Settings Test Group #' . $batchId . ' found. Status: ' . (string)($header['status'] ?? 'unknown') . '.') : 'No History Window settings test group has been created for this lottery yet.');

    $runs = array();
    if ($batchId > 0) { $runs = mylottoexpertLoadBatchRunsForReview($db, $batchId, $userId, $lotteryId); }
    $runCount = count($runs);
    $out['counts']['batch_runs'] = $runCount;

    $windowValues = array();
    foreach ($runs as $run) {
        $settings = array();
        if (isset($run['_settings']) && is_array($run['_settings'])) { $settings = $run['_settings']; }
        $settings = mylottoexpertMergeSharedLearningSettings($settings, $run);
        $info = mylottoexpertExtractSkaiWindowInfo($settings);
        $w = (int)($info['window'] ?? 0);
        if ($w > 0) { $windowValues[$w] = true; }
    }
    $out['window_values'] = array_map('intval', array_keys($windowValues));
    sort($out['window_values']);
    $out['counts']['window_values_found'] = count($out['window_values']);
    $out['checks'][] = mylottoexpertV56EvidenceCheck('batch_run_rows', '9 settings test definitions exist', $runCount >= 9, $runCount . ' settings test definition' . ($runCount === 1 ? '' : 's') . ' found.');
    $out['checks'][] = mylottoexpertV56EvidenceCheck('window_values_captured', 'settings/window values captured', $runCount >= 9 && count($windowValues) >= 8, count($windowValues) . ' distinct History Window value' . (count($windowValues) === 1 ? '' : 's') . ' found: ' . (!empty($out['window_values']) ? implode(', ', $out['window_values']) : 'none') . '.');

    $saveCounts = ($batchId > 0 && function_exists('mylottoexpertCountGeneratedPrecisionBatchSaves')) ? mylottoexpertCountGeneratedPrecisionBatchSaves($db, $userId, $lotteryId, $batchId) : array('saved_count'=>0,'saved_run_count'=>0,'matched_saved_ids'=>array());
    $savedRows = mylottoexpertV56LoadSavedRowsForBatch($db, $userId, $lotteryId, $batchId, (array)($saveCounts['matched_saved_ids'] ?? array()));
    $savedCount = max((int)($saveCounts['saved_count'] ?? 0), count($savedRows));
    $savedRunCount = max((int)($saveCounts['saved_run_count'] ?? 0), $savedCount);
    $out['counts']['saved_prediction_rows'] = $savedCount;
    $out['counts']['saved_distinct_runs'] = $savedRunCount;
    $out['checks'][] = mylottoexpertV56EvidenceCheck('saved_rows', '9 runs saved', $savedRunCount >= 9, $savedRunCount . ' distinct saved AI run' . ($savedRunCount === 1 ? '' : 's') . ' linked to the History Window settings test group.');

    $scored = mylottoexpertV56CountScoredRowsForSavedBatch($db, $savedRows, $gameId);
    $out['counts']['scored_rows'] = (int)($scored['scored_count'] ?? 0);
    $out['counts']['linked_settings_rows'] = (int)($scored['linked_settings_count'] ?? 0);
    $out['checks'][] = mylottoexpertV56EvidenceCheck('draw_scored', 'draw scored', (int)$out['counts']['scored_rows'] > 0, (int)$out['counts']['scored_rows'] . ' scored outcome row' . ((int)$out['counts']['scored_rows'] === 1 ? '' : 's') . ' found for saved rows from this batch.');
    $out['checks'][] = mylottoexpertV56EvidenceCheck('scored_linked_settings', 'scored outcome linked to saved settings', ((int)$out['counts']['scored_rows'] > 0 && (int)$out['counts']['linked_settings_rows'] > 0), (int)$out['counts']['linked_settings_rows'] . ' saved row' . ((int)$out['counts']['linked_settings_rows'] === 1 ? '' : 's') . ' include usable window/settings data.');

    $failed = array();
    foreach ($out['checks'] as $check) {
        if (empty($check['ok'])) { $failed[] = (string)$check['label']; }
    }
    $usable = empty($failed);
    $sharedBackfill = (array)($sharedProfile['historical_backfill'] ?? array());
    $sharedUsable = (int)($sharedBackfill['usable_rows'] ?? 0);
    $detail = $usable ? 'This History Window settings test group has the required batch, saved-run, scored-outcome, and saved-settings chain.' : ('Not usable yet: ' . implode(', ', $failed) . '.');
    if ($usable && $sharedUsable > 0) { $detail .= ' Shared mapper currently reports ' . $sharedUsable . ' usable scored AI row' . ($sharedUsable === 1 ? '' : 's') . ' for this lottery.'; }
    $out['checks'][] = mylottoexpertV56EvidenceCheck('usable_shared_learning', 'usable for shared learning', $usable, $detail);
    $out['usable_for_shared_learning'] = $usable;
    $out['reason'] = $usable ? 'Ready: the History Window prediction history chain is complete for at least one scored draw.' : $detail;
    return $out;
}

function mylottoexpertV60NormalizeSettingScalar($value)
{
    if (is_bool($value)) { return $value ? '1' : '0'; }
    if (is_int($value)) { return (string)$value; }
    if (is_float($value)) { return rtrim(rtrim(number_format($value, 6, '.', ''), '0'), '.'); }
    $value = trim((string)$value);
    if ($value === '') { return ''; }
    $value = preg_replace('/[\x00-\x1F\x7F]/', '', $value);
    return substr($value, 0, 120);
}

function mylottoexpertV60FlattenSettings(array $settings, $prefix = '', $depth = 0)
{
    $out = array();
    if ($depth > 3) { return $out; }
    foreach ($settings as $key => $value) {
        $cleanKey = strtolower(preg_replace('/[^a-zA-Z0-9_\-\.]/', '_', (string)$key));
        if ($cleanKey === '') { continue; }
        $path = $prefix === '' ? $cleanKey : ($prefix . '.' . $cleanKey);
        if (is_array($value)) {
            $nested = mylottoexpertV60FlattenSettings($value, $path, $depth + 1);
            foreach ($nested as $nk => $nv) { $out[$nk] = $nv; }
        } elseif (is_scalar($value) || $value === null) {
            $scalar = mylottoexpertV60NormalizeSettingScalar($value);
            if ($scalar !== '') { $out[$path] = $scalar; }
        }
    }
    return $out;
}

function mylottoexpertV60FirstSettingValue(array $flat, array $needles)
{
    foreach ($needles as $needle) {
        $needle = strtolower((string)$needle);
        foreach ($flat as $key => $value) {
            $k = strtolower((string)$key);
            if ($k === $needle || substr($k, -strlen('.' . $needle)) === '.' . $needle) {
                return array('value' => $value, 'source_key' => $key);
            }
        }
    }
    return array('value' => '', 'source_key' => '');
}

function mylottoexpertV60SupportedSettingDefinitions()
{
    return array(
