            'SUM(CASE WHEN ' . $scoredWhereS . ' THEN 1 ELSE 0 END) AS scored_rows, ' .
            'SUM(CASE WHEN ' . $pendingWhereS . ' THEN 1 ELSE 0 END) AS pending_rows, ' .
            'SUM(CASE WHEN ' . $futurePendingWhereS . ' THEN 1 ELSE 0 END) AS future_pending_rows, MAX(' . $activityExprS . ') AS latest_activity ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers', 's') .
            ($hasUsers ? ' LEFT JOIN ' . $db->quoteName('#__users', 'u') . ' ON u.' . $db->quoteName('id') . ' = s.' . $db->quoteName('user_id') : '') .
            ' GROUP BY s.' . $db->quoteName('user_id') . ', display_name ORDER BY saved_rows DESC, latest_activity DESC LIMIT 25'
        );
        $topUsers = $db->loadAssocList();
        $out['top_users'] = is_array($topUsers) ? $topUsers : array();

        $db->setQuery(
            'SELECT ' . $lotteryExpr . ' AS lottery_id, ' . $gameExpr . ' AS game_id, ' . $drawDateExpr . ' AS draw_date, COUNT(*) AS pending_rows, COUNT(DISTINCT ' . $qcol('user_id') . ') AS users, MAX(' . $activityExpr . ') AS latest_activity ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers') . ' WHERE ' . $pendingWhere .
            ' GROUP BY ' . $lotteryExpr . ', ' . $gameExpr . ', ' . $drawDateExpr . ' ORDER BY draw_date ASC, pending_rows DESC LIMIT 40'
        );
        $pending = $db->loadAssocList();
        foreach ((array)$pending as &$p) { $p['label'] = mylottoexpertV110ResolveLotteryLabel($db, (int)($p['lottery_id'] ?? 0), (string)($p['game_id'] ?? '')); }
        unset($p);
        $out['pending_draws'] = is_array($pending) ? $pending : array();
        $db->setQuery(
            'SELECT ' . $lotteryExpr . ' AS lottery_id, ' . $gameExpr . ' AS game_id, ' . $drawDateExpr . ' AS draw_date, COUNT(*) AS pending_rows, COUNT(DISTINCT ' . $qcol('user_id') . ') AS users, MAX(' . $activityExpr . ') AS latest_activity ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers') . ' WHERE ' . $futurePendingWhere .
            ' GROUP BY ' . $lotteryExpr . ', ' . $gameExpr . ', ' . $drawDateExpr . ' ORDER BY draw_date ASC, pending_rows DESC LIMIT 40'
        );
        $future = $db->loadAssocList();
        foreach ((array)$future as &$p) { $p['label'] = mylottoexpertV110ResolveLotteryLabel($db, (int)($p['lottery_id'] ?? 0), (string)($p['game_id'] ?? '')); }
        unset($p);
        $out['future_pending_draws'] = is_array($future) ? $future : array();

        $db->setQuery(
            'SELECT ' . $sourceExpr . ' AS method_key, COUNT(*) AS saved_rows, COUNT(DISTINCT ' . $qcol('user_id') . ') AS users, COUNT(DISTINCT ' . $lotteryExpr . ') AS lotteries, ' .
            'SUM(CASE WHEN ' . $scoredWhere . ' THEN 1 ELSE 0 END) AS scored_rows, MAX(' . $activityExpr . ') AS latest_activity ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers') . ' GROUP BY ' . $sourceExpr . ' ORDER BY saved_rows DESC LIMIT 25'
        );
        $methods = $db->loadAssocList();
        $out['method_focus'] = is_array($methods) ? $methods : array();

        $db->setQuery(
            'SELECT s.' . $db->quoteName('id') . ' AS id, s.' . $db->quoteName('user_id') . ' AS user_id, ' . $userSelectName . ' AS display_name, ' . $lotteryExprS . ' AS lottery_id, ' . $gameExprS . ' AS game_id, ' .
            $sourceExprS . ' AS method_key, ' .
            ($hasCol($savedCols,'evaluation_status') ? 's.' . $db->quoteName('evaluation_status') : $db->quote('pending')) . ' AS evaluation_status, ' .
            $drawDateExprS . ' AS target_draw_date, ' .
            ($hasCol($savedCols,'actual_draw_date') ? 's.' . $db->quoteName('actual_draw_date') : 'NULL') . ' AS actual_draw_date, ' .
            $activityExprS . ' AS latest_activity ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers', 's') .
            ($hasUsers ? ' LEFT JOIN ' . $db->quoteName('#__users', 'u') . ' ON u.' . $db->quoteName('id') . ' = s.' . $db->quoteName('user_id') : '') .
            ' ORDER BY latest_activity DESC, s.' . $db->quoteName('id') . ' DESC LIMIT 50'
        );
        $recent = $db->loadAssocList();
        foreach ((array)$recent as &$r) { $r['label'] = mylottoexpertV110ResolveLotteryLabel($db, (int)($r['lottery_id'] ?? 0), (string)($r['game_id'] ?? '')); }
        unset($r);
        $out['recent_activity'] = is_array($recent) ? $recent : array();

        $db->setQuery(
            'SELECT s.' . $db->quoteName('id') . ' AS id, s.' . $db->quoteName('user_id') . ' AS user_id, ' . $userSelectName . ' AS display_name, ' . $lotteryExprS . ' AS lottery_id, ' . $gameExprS . ' AS game_id, ' .
            $sourceExprS . ' AS method_key, ' .
            ($hasCol($savedCols,'label') ? 's.' . $db->quoteName('label') : $db->quote('')) . ' AS label_text, ' .
            ($hasCol($savedCols,'evaluation_status') ? 's.' . $db->quoteName('evaluation_status') : $db->quote('pending')) . ' AS evaluation_status, ' .
            ($hasCol($savedCols,'date_saved') ? 's.' . $db->quoteName('date_saved') : 'NULL') . ' AS date_saved, ' .
            ($hasCol($savedCols,'generated_at') ? 's.' . $db->quoteName('generated_at') : 'NULL') . ' AS generated_at, ' .
            ($hasCol($savedCols,'target_draw_date') ? 's.' . $db->quoteName('target_draw_date') : ($hasCol($savedCols,'next_draw_date') ? 's.' . $db->quoteName('next_draw_date') : 'NULL')) . ' AS target_draw_date, ' .
            ($hasCol($savedCols,'batch_uuid') ? 's.' . $db->quoteName('batch_uuid') : $db->quote('')) . ' AS batch_uuid ' .
            'FROM ' . $db->quoteName('#__user_saved_numbers', 's') .
            ($hasUsers ? ' LEFT JOIN ' . $db->quoteName('#__users', 'u') . ' ON u.' . $db->quoteName('id') . ' = s.' . $db->quoteName('user_id') : '') .
            ' ORDER BY s.' . $db->quoteName('id') . ' DESC LIMIT 75'
        );
        $latestById = $db->loadAssocList();
        foreach ((array)$latestById as &$r) { $r['resolved_lottery_label'] = mylottoexpertV110ResolveLotteryLabel($db, (int)($r['lottery_id'] ?? 0), (string)($r['game_id'] ?? '')); }
        unset($r);
        $out['latest_saved_rows'] = is_array($latestById) ? $latestById : array();

        $out['totals']['run_log_rows'] = (int)$out['table_health']['skai_run_log']['rows'];
        $out['totals']['runtime_audit_rows'] = (int)$out['table_health']['skai_runtime_audit']['rows'];
        $out['totals']['shared_learning_rows'] = (int)$out['table_health']['skai_shared_learning']['rows'];
        $out['totals']['learning_events_rows'] = (int)$out['table_health']['skai_learning_events']['rows'];
        $out['totals']['batch_headers'] = (int)$out['table_health']['mle_skai_batch_header']['rows'];
        $out['totals']['batch_runs'] = (int)$out['table_health']['mle_skai_batch_run']['rows'];
        $out['totals']['parameter_sets'] = (int)$out['table_health']['skai_parameter_sets']['rows'];
        $out['totals']['best_settings'] = (int)$out['table_health']['skai_best_settings']['rows'];
        $out['totals']['tail_summaries'] = (int)$out['table_health']['skai_tail_recovery_summary']['rows'];
        $out['totals']['backtest_summaries'] = (int)$out['table_health']['skai_backtest_summary']['rows'];
        $out['totals']['backtest_metrics'] = (int)$out['table_health']['skai_backtest_metrics']['rows'];
        $out['totals']['current_locked_settings'] = (int)$out['table_health']['mle_current_locked_settings']['rows'];
        $out['totals']['optimizer_snapshots'] = (int)$out['table_health']['mle_optimizer_snapshots']['rows'];
        $out['totals']['print_manifests'] = (int)$out['table_health']['mle_prediction_print_manifest']['rows'];

        foreach ($map as $key => $item) {
            $item['label'] = mylottoexpertV110ResolveLotteryLabel($db, (int)$item['lottery_id'], (string)$item['game_id']);
            $item['activity_score'] = ((int)($item['queue_open'] ?? 0) * 30) + ((int)($item['queue_assigned'] ?? 0) * 25) + ((int)($item['assignments'] ?? 0) * 20) + ((int)($item['pending_to_score'] ?? 0) * 16) + ((int)($item['future_pending_draws'] ?? 0) * 8) + ((int)($item['unscored_rows'] ?? 0) * 5) + ((int)($item['evidence_scored'] ?? 0) * 3) + ((int)($item['evidence_users'] ?? 0) * 6) + ((int)($item['run_log_rows'] ?? 0) * 4) + ((int)($item['learning_events'] ?? 0) * 4) + ((int)($item['shared_learning_samples'] ?? 0) * 2) + ((int)($item['recent_24h'] ?? 0) * 12) + ((int)($item['recent_7d'] ?? 0) * 3) + ((int)($item['settings_rows'] ?? 0)) + ((int)($item['active_locked'] ?? 0) * 8) + ((int)($item['optimizer_snapshots'] ?? 0) * 6) + ((int)($item['print_manifests'] ?? 0) * 3) + ((int)($item['saved_rows'] ?? 0));
            $map[$key] = $item;
            $out['totals']['queue_open'] += (int)($item['queue_open'] ?? 0);
            $out['totals']['queue_total'] += (int)($item['queue_total'] ?? 0);
            $out['totals']['assignments'] += (int)($item['assignments'] ?? 0);
            $out['totals']['distinct_assignment_users'] += (int)($item['assigned_users'] ?? 0);
        }
        $items = array_values($map);
        $items = function_exists('mylottoexpertV119MergeLotteryActivityItems') ? mylottoexpertV119MergeLotteryActivityItems($items) : $items;
        usort($items, function($a, $b) {
            $ra = (string)($a['group_region'] ?? '');
            $rb = (string)($b['group_region'] ?? '');
            if ($ra !== $rb) { return strcmp($ra, $rb); }
            if ((int)($b['activity_score'] ?? 0) === (int)($a['activity_score'] ?? 0)) { return strcmp((string)($b['latest_activity'] ?? ''), (string)($a['latest_activity'] ?? '')) * -1; }
            return ((int)($b['activity_score'] ?? 0) > (int)($a['activity_score'] ?? 0)) ? 1 : -1;
        });
        $out['totals']['lotteries'] = count($items);
        $out['active_lotteries'] = array_slice($items, 0, $limit);
    } catch (\Throwable $e) {
        $out['message'] = 'Sitewide shared AI learning intelligence could not be loaded: ' . $e->getMessage();
    }
    return $out;
}


if (!function_exists('mylottoexpertV175TableExists')) {
    function mylottoexpertV175TableExists($db, $table)
    {
        try {
            $raw = $db->getPrefix() . $table;
            $db->setQuery(
                "SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES" .
                " WHERE TABLE_SCHEMA = DATABASE()" .
                " AND TABLE_NAME = " . $db->quote($raw)
            );
            return ((int)$db->loadResult()) > 0;
        } catch (\Throwable $e) {
            return false;
        }
    }
}

if (!function_exists('mylottoexpertV175Columns')) {
    function mylottoexpertV175Columns($db, $table)
    {
        static $cache = array();
        if (isset($cache[$table])) { return $cache[$table]; }
        try {
            $raw = $db->getPrefix() . $table;
            $db->setQuery(
                "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS" .
                " WHERE TABLE_SCHEMA = DATABASE()" .
                " AND TABLE_NAME = " . $db->quote($raw)
            );
            $cols = $db->loadColumn();
            $cache[$table] = is_array($cols) ? $cols : array();
        } catch (\Throwable $e) {
            $cache[$table] = array();
        }
        return $cache[$table];
    }
}

if (!function_exists('mylottoexpertV175HasColumn')) {
    function mylottoexpertV175HasColumn(array $cols, $column)
    {
        return in_array((string)$column, $cols, true);
    }
}

if (!function_exists('mylottoexpertV175GameExpr')) {
    function mylottoexpertV175GameExpr($db, $alias, array $cols)
    {
        $alias = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$alias);
        $p = $alias !== '' ? ($alias . '.') : '';
        $parts = array();
        if (mylottoexpertV175HasColumn($cols, 'target_game_id')) { $parts[] = 'NULLIF(TRIM(COALESCE(' . $p . $db->quoteName('target_game_id') . ', ' . $db->quote('') . ')), ' . $db->quote('') . ')'; }
        if (mylottoexpertV175HasColumn($cols, 'game_id')) { $parts[] = 'NULLIF(TRIM(COALESCE(' . $p . $db->quoteName('game_id') . ', ' . $db->quote('') . ')), ' . $db->quote('') . ')'; }
        $lotParts = array();
        if (mylottoexpertV175HasColumn($cols, 'target_lottery_id')) { $lotParts[] = 'NULLIF(' . $p . $db->quoteName('target_lottery_id') . ',0)'; }
        if (mylottoexpertV175HasColumn($cols, 'lottery_id')) { $lotParts[] = 'NULLIF(' . $p . $db->quoteName('lottery_id') . ',0)'; }
        if (!empty($lotParts)) {
            $lotExpr = 'COALESCE(' . implode(',', $lotParts) . ',0)';
            $parts[] = 'CASE WHEN ' . $lotExpr . ' > 0 THEN CONCAT(' . $db->quote('lottery:') . ', ' . $lotExpr . ') ELSE NULL END';
        }
        if (empty($parts)) { return $db->quote('unknown'); }
        return 'COALESCE(' . implode(',', $parts) . ', ' . $db->quote('unknown') . ')';
    }
}
if (!function_exists('mylottoexpertV177LotteryLabelFromGameKey')) {
    function mylottoexpertV177LotteryLabelFromGameKey($db, $gameKey)
    {
        $gameKey = trim((string)$gameKey);
        $lotteryId = 0;
        $gameId = $gameKey;
        if (strpos($gameKey, 'lottery:') === 0) {
            $lotteryId = (int)substr($gameKey, 8);
            $gameId = '';
        }
        if (function_exists('mylottoexpertV110ResolveLotteryLabel')) {
            try {
                $label = mylottoexpertV110ResolveLotteryLabel($db, $lotteryId, $gameId);
                if (trim((string)$label) !== '') { return (string)$label; }
            } catch (\Throwable $e) {}
        }
        return $gameKey !== '' ? $gameKey : 'Unknown lottery';
    }
}



if (!function_exists('mylottoexpertV192CleanupNeverRanBatchPlansChunk')) {
    function mylottoexpertV192CleanupNeverRanBatchPlansChunk($db, $limit = 25)
    {
        // [[MLE_V92_SAFE_ASYNC_NEVER_RAN_BATCH_CLEANUP]]
        // Bounded housekeeping for batch-plan metadata only. This function is intentionally
        // not called during normal HTML rendering. It is used by a small admin AJAX request
        // after the Batch Coverage Glance has already loaded, so cleanup cannot block admin login.
        $out = array('ok'=>false, 'changed_headers'=>0, 'changed_runs'=>0, 'checked_limit'=>0, 'reason'=>'not_started');
        try {
            $limit = max(1, min(50, (int)$limit));
            $out['checked_limit'] = $limit;
            if (!function_exists('mylottoexpertV175TableExists') || !function_exists('mylottoexpertV175Columns') || !function_exists('mylottoexpertV175HasColumn')) {
                $out['reason'] = 'helpers_missing';
                return $out;
            }
            if (!mylottoexpertV175TableExists($db, 'mle_skai_batch_header') || !mylottoexpertV175TableExists($db, 'mle_skai_batch_run')) {
                $out['reason'] = 'tables_missing';
                return $out;
            }
            $hCols = mylottoexpertV175Columns($db, 'mle_skai_batch_header');
            $rCols = mylottoexpertV175Columns($db, 'mle_skai_batch_run');
            foreach (array('id','status','batch_type','created_at') as $c) {
                if (!mylottoexpertV175HasColumn($hCols, $c)) { $out['reason'] = 'header_columns_missing'; return $out; }
            }
            foreach (array('batch_id','status') as $c) {
                if (!mylottoexpertV175HasColumn($rCols, $c)) { $out['reason'] = 'run_columns_missing'; return $out; }
            }

            $hStatus = 'LOWER(TRIM(COALESCE(h.' . $db->quoteName('status') . ', ' . $db->quote('') . ')))';
            $batchType = 'LOWER(TRIM(COALESCE(h.' . $db->quoteName('batch_type') . ', ' . $db->quote('') . ')))';
            $rStatusExpr = 'LOWER(TRIM(COALESCE(r.' . $db->quoteName('status') . ', ' . $db->quote('') . ')))';
            $r0StatusExpr = 'LOWER(TRIM(COALESCE(r0.' . $db->quoteName('status') . ', ' . $db->quote('') . ')))';
            $r1StatusExpr = 'LOWER(TRIM(COALESCE(r1.' . $db->quoteName('status') . ', ' . $db->quote('') . ')))';
            $terminalOrActive = array('generated','completed','complete','saved','scored','running','in_progress','queued','assigned');
            $terminalSql = implode(',', array_map(array($db, 'quote'), $terminalOrActive));
            $regularTooOld = '(' . $batchType . ' LIKE ' . $db->quote('%regular%') . ' AND h.' . $db->quoteName('created_at') . ' < (NOW() - INTERVAL 6 HOUR))';
            $optionalTooOld = '(' . $batchType . ' NOT LIKE ' . $db->quote('%regular%') . ' AND h.' . $db->quoteName('created_at') . ' < (NOW() - INTERVAL 24 HOUR))';
            $pastDrawClause = '0=1';
            if (mylottoexpertV175HasColumn($rCols, 'target_draw_date')) {
                $pastDrawClause = 'EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_skai_batch_run', 'rd')
                    . ' WHERE rd.' . $db->quoteName('batch_id') . ' = h.' . $db->quoteName('id')
                    . ' AND rd.' . $db->quoteName('target_draw_date') . ' IS NOT NULL'
                    . ' AND rd.' . $db->quoteName('target_draw_date') . ' < CURDATE())';
            }
            $activeAssignmentBlock = '';
            if (mylottoexpertV175TableExists($db, 'mle_lottery_research_assignments')) {
                $aCols = mylottoexpertV175Columns($db, 'mle_lottery_research_assignments');
                if (mylottoexpertV175HasColumn($aCols, 'batch_header_id')) {
                    $aRunner = mylottoexpertV175HasColumn($aCols, 'runner_status') ? 'LOWER(TRIM(COALESCE(a.' . $db->quoteName('runner_status') . ', ' . $db->quote('') . ')))' : $db->quote('');
                    $aAssigned = mylottoexpertV175HasColumn($aCols, 'assigned_status') ? 'LOWER(TRIM(COALESCE(a.' . $db->quoteName('assigned_status') . ', ' . $db->quote('') . ')))' : $db->quote('');
                    $activeAssignmentBlock = ' AND NOT EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a')
                        . ' WHERE a.' . $db->quoteName('batch_header_id') . ' = h.' . $db->quoteName('id')
                        . ' AND (' . $aRunner . ' IN (' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('pending') . ',' . $db->quote('running') . ',' . $db->quote('in_progress') . ',' . $db->quote('retry') . ')'
                        . ' OR ' . $aAssigned . ' IN (' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('pending') . ',' . $db->quote('running') . ',' . $db->quote('in_progress') . ',' . $db->quote('retry') . ')))';
                }
            }
            $candidateSql = 'SELECT h.' . $db->quoteName('id')
                . ' FROM ' . $db->quoteName('#__mle_skai_batch_header', 'h')
                . ' WHERE ' . $hStatus . ' IN (' . $db->quote('pending') . ',' . $db->quote('partially_generated') . ')'
                . ' AND (' . $regularTooOld . ' OR ' . $optionalTooOld . ' OR ' . $pastDrawClause . ')'
                . ' AND EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_skai_batch_run', 'r') . ' WHERE r.' . $db->quoteName('batch_id') . ' = h.' . $db->quoteName('id') . ')'
                . ' AND NOT EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_skai_batch_run', 'r0') . ' WHERE r0.' . $db->quoteName('batch_id') . ' = h.' . $db->quoteName('id') . ' AND ' . $r0StatusExpr . ' IN (' . $terminalSql . '))'
                . ' AND NOT EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_skai_batch_run', 'r1') . ' WHERE r1.' . $db->quoteName('batch_id') . ' = h.' . $db->quoteName('id') . ' AND ' . $r1StatusExpr . ' NOT IN (' . $db->quote('') . ',' . $db->quote('pending') . '))'
                . $activeAssignmentBlock
                . ' ORDER BY h.' . $db->quoteName('created_at') . ' ASC'
                . ' LIMIT ' . (int)$limit;
            $db->setQuery($candidateSql);
            $ids = array_values(array_unique(array_filter(array_map('intval', (array)$db->loadColumn()))));
            if (empty($ids)) {
                $out['ok'] = true;
                $out['reason'] = 'none_found';
                return $out;
            }
            $idList = implode(',', $ids);
            $db->setQuery('UPDATE ' . $db->quoteName('#__mle_skai_batch_run')
                . ' SET ' . $db->quoteName('status') . ' = ' . $db->quote('abandoned_never_ran')
                . ' WHERE ' . $db->quoteName('batch_id') . ' IN (' . $idList . ')'
                . ' AND LOWER(TRIM(COALESCE(' . $db->quoteName('status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('') . ',' . $db->quote('pending') . ')');
            $db->execute();
            $out['changed_runs'] = (int)$db->getAffectedRows();
            $db->setQuery('UPDATE ' . $db->quoteName('#__mle_skai_batch_header')
                . ' SET ' . $db->quoteName('status') . ' = ' . $db->quote('abandoned_never_ran')
                . ' WHERE ' . $db->quoteName('id') . ' IN (' . $idList . ')'
                . ' AND LOWER(TRIM(COALESCE(' . $db->quoteName('status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('pending') . ',' . $db->quote('partially_generated') . ')');
            $db->execute();
            $out['changed_headers'] = (int)$db->getAffectedRows();
            $out['ok'] = true;
            $out['reason'] = 'marked_abandoned_never_ran';
            return $out;
        } catch (\Throwable $e) {
            $out['reason'] = 'exception';
            return $out;
        }
    }
}

try {
    if (!$user->guest
        && method_exists($user, 'authorise')
        && $user->authorise('core.admin')
        && (string)$app->input->getCmd('mle_ajax_action', '') === 'cleanup_never_ran_batch_plans') {
        while (ob_get_level() > 0) { @ob_end_clean(); }
        try {
            $app->setHeader('Content-Type', 'application/json; charset=utf-8', true);
            $app->setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0', true);
            $app->sendHeaders();
        } catch (\Throwable $e) { @header('Content-Type: application/json; charset=utf-8'); }
        if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
            echo json_encode(array('ok'=>false, 'reason'=>'csrf_failed'));
            exit;
        }
        $limit = (int)$app->input->getInt('limit', 25);
        echo json_encode(mylottoexpertV192CleanupNeverRanBatchPlansChunk($db, $limit), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        exit;
    }
} catch (\Throwable $e) { }

if (!function_exists('mylottoexpertV177DecisionForLottery')) {
    function mylottoexpertV177DecisionForLottery(array $row)
    {
        $saved = (int)($row['saved_rows'] ?? 0);
        $pending = (int)($row['pending_unscored'] ?? 0);
        $pastDue = (int)($row['past_due_unscored'] ?? 0);
        $waiting = (int)($row['waiting_official_draw'] ?? 0);
        $scored = (int)($row['scored_rows'] ?? 0);
        $learned = (int)($row['learning_events'] ?? 0);
        $avg = (float)($row['avg_learning_score'] ?? 0.0);
        $best = (float)($row['best_learning_score'] ?? 0.0);
        $spread = $best - $avg;
        $next = trim((string)($row['next_check_at'] ?? ''));
        $latestLearning = trim((string)($row['latest_learning_at'] ?? ''));
        $latestSaved = trim((string)($row['latest_activity'] ?? ''));

        $decision = array(
            'status' => 'Building Prediction History',
            'priority' => 'Medium priority',
            'next_action' => 'Continue Balanced AI Settings Test',
            'reason' => 'Prediction History exists, but the lottery is not ready to narrow yet.',
            'range_label' => 'Balanced exploration range',
            'range_detail' => 'AI blend 15-85 | Temperature 0.65-1.35 | Gap scale 0.20-0.80 | Epochs 40-180',
            'css' => 'mle-v177-status-building'
        );

        if ($waiting >= 10 || $pending >= 25) {
            $decision['status'] = 'Hold - Waiting For Draw Results';
            $decision['priority'] = 'Hold';
            $decision['next_action'] = 'Do not run more research yet';
            $decision['reason'] = 'There are already saved rows waiting for official draw results or scoring. Let the cron process them before spending more runner resources.';
            $decision['range_label'] = 'Resources already allocated';
            $decision['range_detail'] = 'Wait for official results and cron scoring. Next check: ' . ($next !== '' ? $next : 'not scheduled');
            $decision['css'] = 'mle-v177-status-hold';
            return $decision;
        }

        if ($pastDue >= 10 && $waiting >= 5) {
            $decision['status'] = 'Repair Needed';
            $decision['priority'] = 'Repair needed';
            $decision['next_action'] = 'Check official draw importer or scoring prediction history';
            $decision['reason'] = 'Past-due rows are waiting for official results. This is an operations issue before it is a research issue.';
            $decision['range_label'] = 'No new sweep recommended';
            $decision['range_detail'] = 'Fix result availability first, then let the cron score the backlog.';
            $decision['css'] = 'mle-v177-status-repair';
            return $decision;
        }

        if ($saved > 0 && $scored < 20 && $learned < 20) {
            $decision['status'] = 'Needs Broad Exploration';
            $decision['priority'] = 'High priority';
            $decision['next_action'] = 'Run Balanced AI Settings Test';
            $decision['reason'] = 'The lottery has activity but not enough scored learning prediction history after the Shared AI Learning start date.';
            $decision['range_label'] = 'Balanced exploration range';
            $decision['range_detail'] = 'AI blend 15-85 | Temperature 0.65-1.35 | Gap scale 0.20-0.80 | Epochs 40-180';
            $decision['css'] = 'mle-v177-status-broad';
            return $decision;
        }

        if ($scored >= 30 && $learned >= 30 && $spread >= 75.0) {
            $decision['status'] = 'Candidate Range Forming';
            $decision['priority'] = 'High priority';
            $decision['next_action'] = 'Run Tight Best AI Settings Test';
            $decision['reason'] = 'Completed prediction history exists and the best result is separating from the average. Narrow the range and verify the candidate.';
            $decision['range_label'] = 'Tight best-candidate range';
            $decision['range_detail'] = 'AI blend 35-65 | Temperature 0.85-1.15 | Gap scale 0.35-0.65 | Diversity 0.00-0.05';
            $decision['css'] = 'mle-v177-status-tight';
            return $decision;
        }

        if ($scored >= 100 && $learned >= 100 && $latestLearning !== '') {
            $decision['status'] = 'Stable - Monitor';
            $decision['priority'] = 'Low priority';
            $decision['next_action'] = 'Monitor only';
            $decision['reason'] = 'This lottery has substantial scored learning prediction history. Avoid spending research resources unless performance changes.';
            $decision['range_label'] = 'Monitor current best settings';
            $decision['range_detail'] = 'Use normal user runs and cron scoring. Run more research only after a material performance shift.';
            $decision['css'] = 'mle-v177-status-stable';
            return $decision;
        }

        if ($saved <= 0 && $latestSaved === '') {
            $decision['status'] = 'No Recent Prediction History';
            $decision['priority'] = 'Low priority';
            $decision['next_action'] = 'Do not allocate resources yet';
            $decision['reason'] = 'No saved activity was found for this lottery in the current audit window.';
            $decision['range_label'] = 'No active range';
            $decision['range_detail'] = 'Wait for user activity or deliberately select this lottery if it is strategically important.';
            $decision['css'] = 'mle-v177-status-stable';
            return $decision;
        }

        return $decision;
    }
}

if (!function_exists('mylottoexpertV177BuildResourceAllocation')) {
    function mylottoexpertV177BuildResourceAllocation($db, $limit = 40)
    {
        $limit = max(10, min(100, (int)$limit));
        $out = array(
            'totals' => array('lotteries'=>0,'high'=>0,'medium'=>0,'low'=>0,'hold'=>0,'repair'=>0,'tight'=>0,'balanced'=>0,'waiting'=>0,'scored'=>0,'learning_events'=>0),
            'items' => array(),
            'warnings' => array()
        );

        if (!function_exists('mylottoexpertV175TableExists') || !mylottoexpertV175TableExists($db, 'user_saved_numbers')) {
            $out['warnings'][] = 'user_saved_numbers table not found.';
            return $out;
        }
        $cols = mylottoexpertV175Columns($db, 'user_saved_numbers');
        if (empty($cols)) {
            $out['warnings'][] = 'Could not read user_saved_numbers columns.';
            return $out;
        }

        $gameExpr = mylottoexpertV175GameExpr($db, 's', $cols);
        $activityExpr = function_exists('mylottoexpertV176ActivityDateExpr') ? mylottoexpertV176ActivityDateExpr($db, 's', $cols) : $db->quote('');
        $hasActivity = ($activityExpr !== $db->quote(''));
        $latestActivity = $hasActivity ? 'MAX(' . $activityExpr . ')' : $db->quote('');
        $scoredExpr = function_exists('mylottoexpertV176ScoredExpr') ? mylottoexpertV176ScoredExpr($db, 's', $cols) : '0=1';
        $userExpr = mylottoexpertV175HasColumn($cols, 'user_id') ? 'COALESCE(s.' . $db->quoteName('user_id') . ',0)' : '0';

        $targetParts = array();
        foreach (array('target_draw_date','next_draw_date') as $c) {
            if (mylottoexpertV175HasColumn($cols, $c)) { $targetParts[] = 'NULLIF(s.' . $db->quoteName($c) . ', ' . $db->quote('') . ')'; }
        }
        $targetExpr = !empty($targetParts) ? 'COALESCE(' . implode(',', $targetParts) . ', ' . $db->quote('') . ')' : $db->quote('');
        $hasTargetExpr = '(' . $targetExpr . ' <> ' . $db->quote('') . ' AND ' . $targetExpr . ' <> ' . $db->quote('0000-00-00') . ' AND ' . $targetExpr . ' <> ' . $db->quote('0000-00-00 00:00:00') . ')';
        $pastDueExpr = '(' . $hasTargetExpr . ' AND DATE(' . $targetExpr . ') < CURDATE())';
        $currentOrFutureTargetExpr = '(' . $hasTargetExpr . ' AND DATE(' . $targetExpr . ') >= CURDATE())';
        $pendingExpr = '(' . $currentOrFutureTargetExpr . ' AND NOT (' . $scoredExpr . '))';

        $waitingExpr = '0';
        if (mylottoexpertV175HasColumn($cols, 'hive_cron_wait_reason')) {
            $waitingExpr = 'CASE WHEN LOWER(COALESCE(s.' . $db->quoteName('hive_cron_wait_reason') . ', ' . $db->quote('') . ')) = ' . $db->quote('official_draw_not_loaded') . ' THEN 1 ELSE 0 END';
        }
        $lastCheckExpr = mylottoexpertV175HasColumn($cols, 'hive_cron_last_checked_at') ? 'MAX(s.' . $db->quoteName('hive_cron_last_checked_at') . ')' : $db->quote('');
        $nextCheckExpr = mylottoexpertV175HasColumn($cols, 'hive_cron_next_check_at') ? 'MIN(NULLIF(s.' . $db->quoteName('hive_cron_next_check_at') . ', ' . $db->quote('0000-00-00 00:00:00') . '))' : $db->quote('');
        $attemptExpr = mylottoexpertV175HasColumn($cols, 'hive_cron_attempt_count') ? 'SUM(COALESCE(s.' . $db->quoteName('hive_cron_attempt_count') . ',0))' : '0';
        $avgScoreExpr = mylottoexpertV175HasColumn($cols, 'learning_score') ? 'AVG(CASE WHEN ' . $scoredExpr . ' THEN COALESCE(s.' . $db->quoteName('learning_score') . ',0) ELSE NULL END)' : '0';
        $bestScoreExpr = mylottoexpertV175HasColumn($cols, 'learning_score') ? 'MAX(CASE WHEN ' . $scoredExpr . ' THEN COALESCE(s.' . $db->quoteName('learning_score') . ',0) ELSE 0 END)' : '0';
        $latestTargetExpr = $targetExpr !== $db->quote('') ? 'MAX(' . $targetExpr . ')' : $db->quote('');

        $map = array();
        try {
            $sql = 'SELECT ' . $gameExpr . ' AS game_key, COUNT(*) AS saved_rows, COUNT(DISTINCT ' . $userExpr . ') AS users, '
                . 'SUM(CASE WHEN ' . $scoredExpr . ' THEN 1 ELSE 0 END) AS scored_rows, '
                . 'SUM(CASE WHEN ' . $pendingExpr . ' THEN 1 ELSE 0 END) AS pending_unscored, '
                . 'SUM(CASE WHEN ' . $pastDueExpr . ' AND NOT (' . $scoredExpr . ') THEN 1 ELSE 0 END) AS past_due_unscored, '
                . 'SUM(' . $waitingExpr . ') AS waiting_official_draw, '
                . $avgScoreExpr . ' AS avg_learning_score, ' . $bestScoreExpr . ' AS best_learning_score, '
                . $latestTargetExpr . ' AS latest_target_draw_date, ' . $latestActivity . ' AS latest_activity, '
                . $lastCheckExpr . ' AS last_checked_at, ' . $nextCheckExpr . ' AS next_check_at, ' . $attemptExpr . ' AS cron_attempts '
                . 'FROM ' . $db->quoteName('#__user_saved_numbers', 's') . ' GROUP BY ' . $gameExpr . ' ORDER BY waiting_official_draw DESC, pending_unscored DESC, scored_rows ASC, saved_rows DESC LIMIT ' . (int)max(100, $limit * 3);
            $db->setQuery($sql);
            $rows = $db->loadAssocList();
            foreach ((array)$rows as $r) {
                $k = (string)($r['game_key'] ?? 'unknown');
                $r['learning_events'] = 0;
                $r['learned_events'] = 0;
                $r['latest_learning_at'] = '';
                $r['queue_rows'] = 0;
                $r['assignments'] = 0;
                $r['saved_assignments'] = 0;
                $r['label'] = mylottoexpertV177LotteryLabelFromGameKey($db, $k);
                $map[$k] = $r;
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Allocation saved-row query failed: ' . $e->getMessage(); }

        try {
            if (mylottoexpertV175TableExists($db, 'skai_learning_events')) {
                $lcols = mylottoexpertV175Columns($db, 'skai_learning_events');
                $g = mylottoexpertV175GameExpr($db, 'l', $lcols);
                $learnedExpr = mylottoexpertV175HasColumn($lcols, 'is_learned') ? 'SUM(CASE WHEN COALESCE(l.' . $db->quoteName('is_learned') . ',0) = 1 THEN 1 ELSE 0 END)' : 'COUNT(*)';
                $latestParts = array();
                foreach (array('learned_at','created_at','target_draw_date','draw_date') as $c) { if (mylottoexpertV175HasColumn($lcols, $c)) { $latestParts[] = 'l.' . $db->quoteName($c); } }
                $latestLearningExpr = !empty($latestParts) ? 'MAX(COALESCE(' . implode(',', $latestParts) . '))' : $db->quote('');
                $db->setQuery('SELECT ' . $g . ' AS game_key, COUNT(*) AS learning_events, ' . $learnedExpr . ' AS learned_events, ' . $latestLearningExpr . ' AS latest_learning_at FROM ' . $db->quoteName('#__skai_learning_events', 'l') . ' GROUP BY ' . $g . ' LIMIT ' . (int)max(200, $limit * 5));
                foreach ((array)$db->loadAssocList() as $r) {
                    $k = (string)($r['game_key'] ?? 'unknown');
                    if (!isset($map[$k])) { $map[$k] = array('game_key'=>$k,'label'=>mylottoexpertV177LotteryLabelFromGameKey($db, $k),'saved_rows'=>0,'users'=>0,'scored_rows'=>0,'pending_unscored'=>0,'past_due_unscored'=>0,'waiting_official_draw'=>0,'avg_learning_score'=>0,'best_learning_score'=>0,'latest_target_draw_date'=>'','latest_activity'=>'','last_checked_at'=>'','next_check_at'=>'','cron_attempts'=>0,'queue_rows'=>0,'assignments'=>0,'saved_assignments'=>0); }
                    $map[$k]['learning_events'] = (int)($r['learning_events'] ?? 0);
                    $map[$k]['learned_events'] = (int)($r['learned_events'] ?? 0);
                    $map[$k]['latest_learning_at'] = (string)($r['latest_learning_at'] ?? '');
                }
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Allocation learning-event query failed: ' . $e->getMessage(); }

        try {
            if (mylottoexpertV175TableExists($db, 'mle_lottery_research_queue')) {
                $qcols = mylottoexpertV175Columns($db, 'mle_lottery_research_queue');
                $g = mylottoexpertV175GameExpr($db, 'q', $qcols);
                $db->setQuery('SELECT ' . $g . ' AS game_key, COUNT(*) AS queue_rows FROM ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' GROUP BY ' . $g . ' LIMIT ' . (int)max(200, $limit * 5));
                foreach ((array)$db->loadAssocList() as $r) {
                    $k = (string)($r['game_key'] ?? 'unknown');
                    if (!isset($map[$k])) { $map[$k] = array('game_key'=>$k,'label'=>mylottoexpertV177LotteryLabelFromGameKey($db, $k),'saved_rows'=>0,'users'=>0,'scored_rows'=>0,'pending_unscored'=>0,'past_due_unscored'=>0,'waiting_official_draw'=>0,'avg_learning_score'=>0,'best_learning_score'=>0,'latest_target_draw_date'=>'','latest_activity'=>'','last_checked_at'=>'','next_check_at'=>'','cron_attempts'=>0,'learning_events'=>0,'learned_events'=>0,'latest_learning_at'=>'','assignments'=>0,'saved_assignments'=>0); }
                    $map[$k]['queue_rows'] = (int)($r['queue_rows'] ?? 0);
                }
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Allocation queue query failed: ' . $e->getMessage(); }

        try {
            if (mylottoexpertV175TableExists($db, 'mle_lottery_research_assignments')) {
                $acols = mylottoexpertV175Columns($db, 'mle_lottery_research_assignments');
                $g = mylottoexpertV175GameExpr($db, 'a', $acols);
                $savedConds = array();
                if (mylottoexpertV175HasColumn($acols, 'runner_status')) { $savedConds[] = 'LOWER(COALESCE(a.' . $db->quoteName('runner_status') . ', ' . $db->quote('') . ')) = ' . $db->quote('saved'); }
                if (mylottoexpertV175HasColumn($acols, 'saved_count')) { $savedConds[] = 'COALESCE(a.' . $db->quoteName('saved_count') . ',0) > 0'; }
                $savedAssignExpr = !empty($savedConds) ? '(' . implode(' OR ', $savedConds) . ')' : '0=1';
                $db->setQuery('SELECT ' . $g . ' AS game_key, COUNT(*) AS assignments, SUM(CASE WHEN ' . $savedAssignExpr . ' THEN 1 ELSE 0 END) AS saved_assignments FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' GROUP BY ' . $g . ' LIMIT ' . (int)max(200, $limit * 5));
                foreach ((array)$db->loadAssocList() as $r) {
                    $k = (string)($r['game_key'] ?? 'unknown');
                    if (!isset($map[$k])) { $map[$k] = array('game_key'=>$k,'label'=>mylottoexpertV177LotteryLabelFromGameKey($db, $k),'saved_rows'=>0,'users'=>0,'scored_rows'=>0,'pending_unscored'=>0,'past_due_unscored'=>0,'waiting_official_draw'=>0,'avg_learning_score'=>0,'best_learning_score'=>0,'latest_target_draw_date'=>'','latest_activity'=>'','last_checked_at'=>'','next_check_at'=>'','cron_attempts'=>0,'learning_events'=>0,'learned_events'=>0,'latest_learning_at'=>'','queue_rows'=>0); }
                    $map[$k]['assignments'] = (int)($r['assignments'] ?? 0);
                    $map[$k]['saved_assignments'] = (int)($r['saved_assignments'] ?? 0);
                }
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Allocation assignment query failed: ' . $e->getMessage(); }

        $items = array();
        foreach ($map as $k => $row) {
            $row['game_key'] = $k;
            $row['decision'] = mylottoexpertV177DecisionForLottery($row);
            $items[] = $row;
        }
        usort($items, function($a, $b) {
            $priorityScore = function($r) {
                $d = (array)($r['decision'] ?? array());
                $p = (string)($d['priority'] ?? '');
                if ($p === 'Repair needed') { return 100000; }
                if ($p === 'High priority') { return 80000; }
                if ($p === 'Hold') { return 60000; }
                if ($p === 'Medium priority') { return 40000; }
                return 10000;
            };
            $as = $priorityScore($a) + ((int)($a['pending_unscored'] ?? 0) * 50) + ((int)($a['waiting_official_draw'] ?? 0) * 25) + ((int)($a['saved_rows'] ?? 0));
            $bs = $priorityScore($b) + ((int)($b['pending_unscored'] ?? 0) * 50) + ((int)($b['waiting_official_draw'] ?? 0) * 25) + ((int)($b['saved_rows'] ?? 0));
            if ($as === $bs) { return strcmp((string)($b['latest_activity'] ?? ''), (string)($a['latest_activity'] ?? '')); }
            return ($bs > $as) ? 1 : -1;
        });

        $items = array_slice($items, 0, $limit);
        foreach ($items as $row) {
            $d = (array)($row['decision'] ?? array());
            $out['totals']['lotteries']++;
            $out['totals']['waiting'] += (int)($row['waiting_official_draw'] ?? 0);
            $out['totals']['scored'] += (int)($row['scored_rows'] ?? 0);
            $out['totals']['learning_events'] += (int)($row['learning_events'] ?? 0);
            $priority = (string)($d['priority'] ?? '');
            $action = (string)($d['next_action'] ?? '');
            if ($priority === 'High priority') { $out['totals']['high']++; }
            elseif ($priority === 'Medium priority') { $out['totals']['medium']++; }
            elseif ($priority === 'Hold') { $out['totals']['hold']++; }
            elseif ($priority === 'Repair needed') { $out['totals']['repair']++; }
            else { $out['totals']['low']++; }
            if (strpos($action, 'Tight') !== false) { $out['totals']['tight']++; }
            if (strpos($action, 'Balanced') !== false) { $out['totals']['balanced']++; }
        }
        $out['items'] = $items;
        return $out;
    }
}


