if (!function_exists('mylottoexpertV178HiveMaturityStage')) {
    function mylottoexpertV178HiveMaturityStage(array $row)
    {
        $scored = (int)($row['scored_batch_runs'] ?? 0);
        $learning = (int)($row['learning_events'] ?? 0);
        $savedBatch = (int)($row['saved_batch_runs'] ?? 0);
        $waiting = (int)($row['waiting_official_draw'] ?? 0) + (int)($row['pending_unscored_batch_runs'] ?? 0);
        $evidence = min($scored, $learning);
        $nextScored = 0;
        $nextLearning = 0;
        $stage = array(
            'level' => 0,
            'label' => 'Stage 0 - Not Started',
            'short' => 'Not Started',
            'css' => 'mle-v178-maturity-0',
            'plain' => 'No scored batch prediction history is available yet. This lottery is not ready to guide users from Shared AI Learning learning.',
            'next' => 'Create and run a first Balanced AI Settings Test, then wait for official draw scoring.',
            'confidence' => 'Not useful yet'
        );

        if ($scored <= 0 && $learning <= 0 && $savedBatch <= 0) {
            return $stage;
        }
        if ($scored <= 0 && ($savedBatch > 0 || $waiting > 0)) {
            $stage['level'] = 1;
            $stage['label'] = 'Stage 1 - Waiting for First Score';
            $stage['short'] = 'Waiting Score';
            $stage['css'] = 'mle-v178-maturity-1';
            $stage['plain'] = 'Runs exist, but they have not produced scored learning yet. The lottery is still waiting for draw results or cron scoring.';
            $stage['next'] = 'Do not over-run it yet. Let the saved work score first, then evaluate again.';
            $stage['confidence'] = 'Too early';
            return $stage;
        }
        if ($evidence < 10) {
            $nextScored = max(0, 10 - $scored);
            $nextLearning = max(0, 10 - $learning);
            $stage['level'] = 1;
            $stage['label'] = 'Stage 1 - Early Learning';
            $stage['short'] = 'Early';
            $stage['css'] = 'mle-v178-maturity-1';
            $stage['plain'] = 'The lottery has very little scored learning. Advice should be treated as exploratory.';
            $stage['next'] = 'Needs about ' . $nextScored . ' more scored batch run(s) and ' . $nextLearning . ' more learning event(s) to reach Stage 2.';
            $stage['confidence'] = 'Very low';
            return $stage;
        }
        if ($evidence < 30) {
            $nextScored = max(0, 30 - $scored);
            $nextLearning = max(0, 30 - $learning);
            $stage['level'] = 2;
            $stage['label'] = 'Stage 2 - Building Baseline';
            $stage['short'] = 'Building';
            $stage['css'] = 'mle-v178-maturity-2';
            $stage['plain'] = 'The lottery has enough activity to start seeing patterns, but not enough to tighten recommendations confidently.';
            $stage['next'] = 'Needs about ' . $nextScored . ' more scored batch run(s) and ' . $nextLearning . ' more learning event(s) to reach Stage 3.';
            $stage['confidence'] = 'Low';
            return $stage;
        }
        if ($evidence < 100) {
            $nextScored = max(0, 100 - $scored);
            $nextLearning = max(0, 100 - $learning);
            $stage['level'] = 3;
            $stage['label'] = 'Stage 3 - Useful Learning';
            $stage['short'] = 'Useful';
            $stage['css'] = 'mle-v178-maturity-3';
            $stage['plain'] = 'The lottery has meaningful scored learning. User-facing guidance can be useful, but should still show caution.';
            $stage['next'] = 'Needs about ' . $nextScored . ' more scored batch run(s) and ' . $nextLearning . ' more learning event(s) to reach Stage 4.';
            $stage['confidence'] = 'Moderate';
            return $stage;
        }
        if ($evidence < 200) {
            $nextScored = max(0, 200 - $scored);
            $nextLearning = max(0, 200 - $learning);
            $stage['level'] = 4;
            $stage['label'] = 'Stage 4 - Strong Shared AI Learning Prediction History';
            $stage['short'] = 'Strong Shared AI Learning';
            $stage['css'] = 'mle-v178-maturity-4';
            $stage['plain'] = 'The lottery has strong scored learning. Admin work should usually shift from broad batches to refinement and monitoring.';
            $stage['next'] = 'Needs about ' . $nextScored . ' more scored batch run(s) and ' . $nextLearning . ' more learning event(s) to reach Stage 5.';
            $stage['confidence'] = 'High';
            return $stage;
        }
        $stage['level'] = 5;
        $stage['label'] = 'Stage 5 - Mature Precision Candidate';
        $stage['short'] = 'Mature';
        $stage['css'] = 'mle-v178-maturity-5';
        $stage['plain'] = 'This lottery has mature scored learning. It is one of the better candidates for stable recommendations and tighter confirmation work.';
        $stage['next'] = 'Monitor performance, refresh after new draws, and use tight sweeps only when performance changes.';
        $stage['confidence'] = 'Very high';
        return $stage;
    }
}

if (!function_exists('mylottoexpertV178BatchCoverageDecision')) {
    function mylottoexpertV178BatchCoverageDecision(array $row)
    {
        $queuePending = (int)($row['queue_pending'] ?? 0);
        $assignPending = (int)($row['assignments_pending'] ?? 0);
        $running = (int)($row['queue_running'] ?? 0) + (int)($row['assignments_running'] ?? 0);
        $waiting = (int)($row['waiting_official_draw'] ?? 0);
        $pendingSaved = (int)($row['pending_unscored_batch_runs'] ?? 0);
        $scored = (int)($row['scored_batch_runs'] ?? 0);
        $learning = (int)($row['learning_events'] ?? 0);
        $planned = (int)($row['planned_runs'] ?? 0) + (int)($row['queue_rows'] ?? 0) + (int)($row['assignments'] ?? 0);

        if ($running > 0) {
            return array(
                'status'=>'Resume queue',
                'priority'=>'Resume existing queue',
                'next_action'=>'Do not create more admin batches. Resume this lottery in the AI runner. If rows were marked running from an old session, the resume action will safely reset them to queued first.',
                'css'=>'mle-v178-status-running',
                'reason'=>'This lottery has AI work marked running, but the admin must actively run or resume the queue for it to continue.'
            );
        }
        if ($waiting >= 10 || $pendingSaved >= 25) {
            return array(
                'status'=>'Wait for scoring',
                'priority'=>'Wait',
                'next_action'=>'Do not create more admin batches yet. Wait for official draw results and cron scoring.',
                'css'=>'mle-v178-status-hold',
                'reason'=>'There are enough saved runs waiting for official draw results or scoring.'
            );
        }
        if (($queuePending + $assignPending) > 0) {
            return array(
                'status'=>'Run existing queue',
                'priority'=>'Run queue first',
                'next_action'=>'Do not create another sweep yet. Run the existing AI waiting prediction work first.',
                'css'=>'mle-v178-status-queued',
                'reason'=>'Waiting prediction work already exists and is waiting for AI to run it.'
            );
        }
        if ($planned <= 0 && $scored <= 0) {
            return array(
                'status'=>'Needs first batch',
                'priority'=>'Create batch',
                'next_action'=>'Yes. Create and run a Balanced AI Settings Test so this lottery can start building prediction history.',
                'css'=>'mle-v178-status-empty',
                'reason'=>'No visible batch coverage exists for this lottery.'
            );
        }
        if ($scored >= 100 && $learning >= 100) {
            return array(
                'status'=>'Enough coverage',
                'priority'=>'Monitor',
                'next_action'=>'No new admin batch is needed right now. Monitor the lottery and let new draws score naturally.',
                'css'=>'mle-v178-status-covered',
                'reason'=>'This lottery already has strong scored batch coverage and learning history.'
            );
        }
        if ($scored >= 30 && $learning >= 30) {
            return array(
                'status'=>'Ready to refine',
                'priority'=>'Optional tight sweep',
                'next_action'=>'Optional. Create a Tight Best AI Settings Test only if you want to refine the strongest settings.',
                'css'=>'mle-v178-status-tight',
                'reason'=>'There is enough scored learning to justify a narrower confirmation sweep.'
            );
        }
        if ($scored < 20) {
            return array(
                'status'=>'Needs more prediction history',
                'priority'=>'Create batch',
                'next_action'=>'Yes. Create a Balanced AI Settings Test after any existing waiting prediction work is clear.',
                'css'=>'mle-v178-status-broad',
                'reason'=>'This lottery does not have enough scored batch prediction history yet.'
            );
        }
        return array(
            'status'=>'Building prediction history',
            'priority'=>'Maybe',
            'next_action'=>'Maybe. Continue with Balanced AI Settings Test only after current queue and scoring work are clear.',
            'css'=>'mle-v178-status-building',
            'reason'=>'Some batch prediction history exists, but more scored outcomes are needed before tightening.'
        );
    }
}

if (!function_exists('mylottoexpertV178BuildAdminBatchAdvice')) {
    function mylottoexpertV178BuildAdminBatchAdvice(array $item)
    {
        $d = (array)($item['decision'] ?? array());
        $status = (string)($d['status'] ?? '');
        $queueWorkToRun = (int)($item['queue_pending'] ?? 0) + (int)($item['assignments_pending'] ?? 0);
        $pendingBatchPlans = (int)($item['planned_runs_pending'] ?? 0);
        $running = (int)($item['queue_running'] ?? 0) + (int)($item['assignments_running'] ?? 0);
        $waiting = (int)($item['waiting_official_draw'] ?? 0);
        $pendingSaved = (int)($item['pending_unscored_batch_runs'] ?? 0);
        $scored = (int)($item['scored_batch_runs'] ?? 0);
        $learning = (int)($item['learning_events'] ?? 0);

        $out = array(
            'answer' => 'Maybe.',
            'plain_reason' => (string)($d['reason'] ?? ''),
            'plain_action' => (string)($d['next_action'] ?? ''),
            'evidence_line' => 'Scored batch runs ' . $scored . ', learning events ' . $learning . '.',
            'work_line' => 'Runnable AI waiting prediction work still to run ' . $queueWorkToRun . ' assignment(s). Running now ' . $running . '. Pending batch-plan rows ' . $pendingBatchPlans . ' are shown separately because they are planned metadata, not live runner waiting prediction work.',
            'scoring_line' => 'Saved runs waiting for draw or scoring ' . ($waiting + $pendingSaved) . ' total.'
        );

        if ($status === 'Resume queue') {
            $out['answer'] = 'No. Resume the existing AI queue instead.';
            $out['plain_reason'] = 'This lottery already has work marked running or waiting. If AI is not open, those rows will not move by themselves. Use the resume action below to continue the existing queue before creating anything new.';
        } elseif ($status === 'Run existing queue') {
            $out['answer'] = 'No. Run the existing AI queue first.';
            $out['plain_reason'] = 'This lottery already has work waiting. The fastest way to help learning is to run what is already queued.';
        } elseif ($status === 'Wait for scoring') {
            $out['answer'] = 'No. Wait for draw results and cron scoring first.';
            $out['plain_reason'] = 'The system already has saved work that needs official results before it can learn from it.';
        } elseif ($status === 'Needs first batch') {
            $out['answer'] = 'Yes. This lottery needs an admin batch.';
            $out['plain_reason'] = 'There is no useful batch coverage yet, so a Balanced AI Settings Test is the right first step.';
        } elseif ($status === 'Needs more prediction history') {
            $out['answer'] = 'Yes. More admin batch prediction history would help.';
            $out['plain_reason'] = 'The lottery has fewer than 20 scored batch runs, so learning is still thin.';
        } elseif ($status === 'Ready to refine') {
            $out['answer'] = 'Optional. Do a tight sweep only if you want refinement.';
            $out['plain_reason'] = 'There is already enough broad prediction history. The next useful admin work is confirmation, not another broad batch.';
        } elseif ($status === 'Enough coverage') {
            $out['answer'] = 'No. This lottery already has enough admin coverage for now.';
            $out['plain_reason'] = 'The lottery already has strong completed prediction history and learning history. Monitor it instead of adding more work.';
        } elseif ($status === 'Building prediction history') {
            $out['answer'] = 'Maybe. Add more only after current work is clear.';
            $out['plain_reason'] = 'The lottery has some prediction history, but not enough to refine confidently yet.';
        }

        return $out;
    }
}

if (!function_exists('mylottoexpertV178BuildAdminBatchSummary')) {
    function mylottoexpertV178BuildAdminBatchSummary(array $totals)
    {
        $needNew = (int)($totals['empty'] ?? 0) + (int)($totals['broad'] ?? 0);
        $runFirst = (int)($totals['active'] ?? 0) + (int)($totals['queued'] ?? 0);
        $wait = (int)($totals['hold'] ?? 0);
        $tight = (int)($totals['tight'] ?? 0);
        $lines = array();
        if ($runFirst > 0) {
            $lines[] = $runFirst . ' lottery group(s) already have AI waiting prediction work. Resume or run that existing work before you create more batches.';
        }
        if ($needNew > 0) {
            $lines[] = $needNew . ' lottery group(s) need more broad batch prediction history when waiting prediction work is clear.';
        }
        if ($tight > 0) {
            $lines[] = $tight . ' lottery group(s) are ready for optional tight best-candidate refinement.';
        }
        if ($wait > 0) {
            $lines[] = $wait . ' lottery group(s) should wait for official draw results or cron scoring.';
        }
        if (empty($lines)) {
            $lines[] = 'No immediate admin settings test action is required from this list.';
        }
        return implode(' ', $lines);
    }
}

if (!function_exists('mylottoexpertV178LoadBatchCoverage')) {
    function mylottoexpertV178LoadBatchCoverage($db, $limit = 80, $activeOnly = false)
    {
        // Batch Coverage Glance must be able to show every lottery without loading full lottery cards.
        // Keep a hard upper bound so this admin-only summary remains server-safe.
        $limit = max(10, min(1000, (int)$limit));
        $activeOnly = !empty($activeOnly);
        $out = array('available'=>true,'warnings'=>array(),'totals'=>array('lotteries'=>0,'active'=>0,'queued'=>0,'hold'=>0,'empty'=>0,'broad'=>0,'tight'=>0,'covered'=>0,'pending_saved'=>0,'waiting'=>0,'queued_assignments'=>0,'following_users'=>0),'items'=>array());
        $map = array();

        // [[MLE_V89_ADMIN_GLANCE_CONFIG_SEED]]
        // Seed the Batch Coverage Glance from the lightweight lottery config files so
        // admin can see every configured lottery without loading full lottery cards.
        try {
            if (!$activeOnly) {
                $seedFiles = array();
                if (defined('JPATH_ROOT')) {
                    $seedFiles[] = rtrim((string)JPATH_ROOT, '/\\') . '/lottery_skip_config.json';
                    $seedFiles[] = rtrim((string)JPATH_ROOT, '/\\') . '/dailylotteries.json';
                }
                foreach ($seedFiles as $seedPath) {
                    if (!is_file($seedPath)) { continue; }
                    $rawSeed = json_decode((string)@file_get_contents($seedPath), true);
                    if (json_last_error() !== JSON_ERROR_NONE || !is_array($rawSeed)) { continue; }
                    $pools = array();
                    if (isset($rawSeed['lotteries']) && is_array($rawSeed['lotteries'])) { $pools[] = $rawSeed['lotteries']; }
                    if (isset($rawSeed['dailylotteries']) && is_array($rawSeed['dailylotteries'])) { $pools[] = $rawSeed['dailylotteries']; }
                    if (empty($pools)) { $pools[] = $rawSeed; }
                    foreach ($pools as $pool) {
                        if (!is_array($pool)) { continue; }
                        foreach ($pool as $cfgKey => $cfgRow) {
                            if (!is_array($cfgRow)) { continue; }
                            $cfg = isset($cfgRow['lotteryConfig']) && is_array($cfgRow['lotteryConfig']) ? $cfgRow['lotteryConfig'] : $cfgRow;
                            $gid = trim((string)($cfgRow['game_id'] ?? $cfgRow['gameId'] ?? $cfgRow['gid'] ?? $cfg['game_id'] ?? $cfg['gameId'] ?? $cfg['gid'] ?? $cfgKey));
                            $gid = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr($gid, 0, 50));
                            if ($gid === '') { continue; }
                            $lid = (int)($cfgRow['lottery_id'] ?? $cfgRow['id'] ?? $cfg['lottery_id'] ?? $cfg['id'] ?? 0);
                            $label = trim((string)($cfg['name'] ?? $cfg['lottery_name'] ?? $cfg['title'] ?? $cfg['gameName'] ?? $cfgRow['name'] ?? $cfgRow['lottery_name'] ?? $cfgRow['title'] ?? $gid));
                            mylottoexpertV178EnsureCoverageRow($map, $db, $gid);
                            if ($label !== '') { $map[$gid]['label'] = $label; }
                            if ($lid > 0) { $map[$gid]['lottery_id'] = $lid; }
                            $map[$gid]['game_key'] = $gid;
                        }
                    }
                }
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Batch coverage config seed failed: ' . $e->getMessage(); }

        try {
            if (!$activeOnly && function_exists('mylottoexpertV175TableExists') && mylottoexpertV175TableExists($db, 'lotteries')) {
                $lotCols = mylottoexpertV175Columns($db, 'lotteries');
                $idCol = mylottoexpertV175HasColumn($lotCols, 'lottery_id') ? 'lottery_id' : (mylottoexpertV175HasColumn($lotCols, 'id') ? 'id' : '');
                $gameCol = mylottoexpertV175HasColumn($lotCols, 'game_id') ? 'game_id' : '';
                $nameCol = mylottoexpertV175HasColumn($lotCols, 'name') ? 'name' : (mylottoexpertV175HasColumn($lotCols, 'lottery_name') ? 'lottery_name' : (mylottoexpertV175HasColumn($lotCols, 'title') ? 'title' : ''));
                if ($idCol !== '' || $gameCol !== '') {
                    $select = array();
                    if ($idCol !== '') { $select[] = 'l.' . $db->quoteName($idCol, 'lottery_id'); }
                    else { $select[] = '0 AS lottery_id'; }
                    if ($gameCol !== '') { $select[] = 'l.' . $db->quoteName($gameCol, 'game_id'); }
                    else { $select[] = $db->quote('', 'game_id'); }
                    if ($nameCol !== '') { $select[] = 'l.' . $db->quoteName($nameCol, 'lottery_name'); }
                    else { $select[] = $db->quote('', 'lottery_name'); }
                    $orderCol = $nameCol !== '' ? $nameCol : ($idCol !== '' ? $idCol : $gameCol);
                    $sql = 'SELECT ' . implode(',', $select) . ' FROM ' . $db->quoteName('#__lotteries', 'l') . ' ORDER BY l.' . $db->quoteName($orderCol) . ' ASC LIMIT 1000';
                    $db->setQuery($sql);
                    foreach ((array)$db->loadAssocList() as $lotRow) {
                        $gid = trim((string)($lotRow['game_id'] ?? ''));
                        $lid = (int)($lotRow['lottery_id'] ?? 0);
                        $k = $gid !== '' ? $gid : ($lid > 0 ? ('lottery:' . $lid) : 'unknown');
                        mylottoexpertV178EnsureCoverageRow($map, $db, $k);
                        $lotLabel = trim((string)($lotRow['lottery_name'] ?? ''));
                        if ($lotLabel !== '') { $map[$k]['label'] = $lotLabel; }
                        if ($lid > 0) { $map[$k]['lottery_id'] = $lid; }
                    }
                }
            }
        } catch (\Throwable $e) { $out['warnings'][] = 'Batch coverage lottery seed query failed: ' . $e->getMessage(); }

        try {
            if (!$activeOnly && function_exists('mylottoexpertV175TableExists') && mylottoexpertV175TableExists($db, 'user_lottery_preferences')) {
                $prefCols = mylottoexpertV175Columns($db, 'user_lottery_preferences');
                if (mylottoexpertV175HasColumn($prefCols, 'lottery_id') && mylottoexpertV175HasColumn($prefCols, 'user_id')) {
                    $prefLotteryExpr = 'p.' . $db->quoteName('lottery_id');
                    if (function_exists('mylottoexpertV175TableExists') && mylottoexpertV175TableExists($db, 'lotteries')) {
                        $lotCols2 = mylottoexpertV175Columns($db, 'lotteries');
