if (!function_exists('mylottoexpertV182RenderAdminBatchGlanceTable')) {
    function mylottoexpertV182RenderAdminBatchGlanceTable($db, $limit = 200, $maintenanceOnly = false)
    {
        if (!function_exists('mylottoexpertV178LoadBatchCoverage')) {
            return '';
        }

        $data = mylottoexpertV178LoadBatchCoverage($db, $limit);
        $items = (array)($data['items'] ?? array());
        $maintenanceOnly = !empty($maintenanceOnly);

        $actionItems = array();
        foreach ($items as $__mleV190Item) {
            $__mleV190Item = (array)$__mleV190Item;
            $__mleV190QueueToRun = (int)($__mleV190Item['queue_pending'] ?? 0) + (int)($__mleV190Item['assignments_pending'] ?? 0);
            $__mleV190Running = (int)($__mleV190Item['queue_running'] ?? 0) + (int)($__mleV190Item['assignments_running'] ?? 0);
            $__mleV190FailedUnknown = (int)($__mleV190Item['queue_failed'] ?? 0) + (int)($__mleV190Item['assignments_failed'] ?? 0) + (int)($__mleV190Item['assignments_unknown'] ?? 0);
            $__mleV190PendingScore = (int)($__mleV190Item['pending_unscored_batch_runs'] ?? 0);
            $__mleV190WaitingDraw = (int)($__mleV190Item['waiting_official_draw'] ?? 0);
            if (($__mleV190QueueToRun + $__mleV190Running + $__mleV190FailedUnknown + $__mleV190PendingScore + $__mleV190WaitingDraw) > 0) {
                $actionItems[] = $__mleV190Item;
            }
        }
        $displayItems = $maintenanceOnly ? $actionItems : $items;

        // [[MLE_V9_HIVE_RESEARCH_PRIORITY_WORKBENCH]]
        // Admin-only decision layer. This does not create, score, or alter predictions by itself.
        // It ranks lotteries by demand, active coverage, queue state, scored evidence, and draw spread.
        $__mleV9EvidenceStatusFor = function(array $item) {
            $scoredRuns = max(0, (int)($item['scored_batch_runs'] ?? 0));
            $scoredDraws = max(0, (int)($item['scored_draw_count'] ?? 0));
            $runsPerDraw = $scoredDraws > 0 ? round($scoredRuns / max(1, $scoredDraws), 1) : 0;
            if ($scoredRuns <= 0 || $scoredDraws <= 0) {
                return array('key'=>'no_evidence','label'=>'No Prediction History Yet','css'=>'mle-v8-status-needs','draws'=>$scoredDraws,'runs_per_draw'=>$runsPerDraw,'plain'=>'No shared prediction history has been collected yet.');
            }
            if ($scoredDraws <= 1 && $scoredRuns >= 100) {
                return array('key'=>'concentrated','label'=>'Concentrated Prediction History','css'=>'mle-v8-status-review','draws'=>$scoredDraws,'runs_per_draw'=>$runsPerDraw,'plain'=>'Many runs exist, but they are concentrated on too few scored draws.');
            }
            if ($scoredDraws < 4) {
                return array('key'=>'thin','label'=>'Needs More Draw History','css'=>'mle-v8-status-needs','draws'=>$scoredDraws,'runs_per_draw'=>$runsPerDraw,'plain'=>'Shared AI Learning has some prediction history, but not enough completed draws to narrow the profile with confidence.');
            }
            if ($scoredDraws < 8 || $scoredRuns < 400) {
                return array('key'=>'building','label'=>'Building Profile','css'=>'mle-v8-status-queue','draws'=>$scoredDraws,'runs_per_draw'=>$runsPerDraw,'plain'=>'Prediction history is growing across multiple draws, and the Shared AI Learning profile is still building.');
            }
            return array('key'=>'strong','label'=>'Strong Prediction History','css'=>'mle-v8-status-covered','draws'=>$scoredDraws,'runs_per_draw'=>$runsPerDraw,'plain'=>'Completed prediction history is spread across enough draws to support stronger Shared AI Learning guidance.');
        };

        $__mleV8CoverageStatusFor = function(array $item) use ($__mleV9EvidenceStatusFor) {
            $followers = max(0, (int)($item['following_users'] ?? 0));
            $pendingPredictions = max(0, (int)($item['pending_unscored_batch_runs'] ?? 0));
            $waitingDraw = max(0, (int)($item['waiting_official_draw'] ?? 0));
            $queueToRun = max(0, (int)($item['queue_pending'] ?? 0)) + max(0, (int)($item['assignments_pending'] ?? 0));
            $running = max(0, (int)($item['queue_running'] ?? 0)) + max(0, (int)($item['assignments_running'] ?? 0));
            $failedUnknown = max(0, (int)($item['queue_failed'] ?? 0)) + max(0, (int)($item['assignments_failed'] ?? 0)) + max(0, (int)($item['assignments_unknown'] ?? 0));
            $scored = max(0, (int)($item['scored_batch_runs'] ?? 0));
            $saved = max(0, (int)($item['saved_batch_runs'] ?? 0));
            $scoredDraws = max(0, (int)($item['scored_draw_count'] ?? 0));
            $otherPending = max(0, $pendingPredictions - $waitingDraw);
            $evidence = $__mleV9EvidenceStatusFor($item);
            $evidenceLabel = (string)($evidence['label'] ?? 'Prediction history unknown');

            if ($failedUnknown > 0) {
                return array('key'=>'needs_review','label'=>'Needs Review','priority'=>1,'css'=>'mle-v8-status-review','action'=>'Review the raw count sources before creating more work.','why'=>'Failed or unknown queue/assignment rows need admin attention.');
            }
            if ($queueToRun > 0) {
                return array('key'=>'queue_ready','label'=>'Waiting Predictions Ready to Run','priority'=>2,'css'=>'mle-v8-status-queue','action'=>'Run the waiting predictions before creating more predictions.','why'=>'Settings test work already exists and is waiting to run.');
            }
            if ($running > 0) {
                return array('key'=>'running_now','label'=>'Running Now','priority'=>3,'css'=>'mle-v8-status-running','action'=>'Do not create more yet. Let the current run finish or resume the open queue.','why'=>'This lottery already has waiting prediction work marked as running.');
            }
            if ($waitingDraw > 0) {
                return array('key'=>'waiting_draw','label'=>'Waiting for Draw','priority'=>6,'css'=>'mle-v8-status-wait','action'=>'No action needed. These predictions already exist and are waiting for official draw/scoring.','why'=>'Saved predictions are waiting for the official draw before they can be scored.');
            }
            if ($followers > 0 && $pendingPredictions <= 0 && $queueToRun <= 0 && $running <= 0 && $scored <= 0) {
                return array('key'=>'needs_batch','label'=>'Needs Shared AI Learning Settings Test','priority'=>4,'css'=>'mle-v8-status-needs','action'=>'Create a 100-run Shared AI Learning campaign and open the AI runner.','why'=>'Users follow this lottery, but there are no active pending predictions, no waiting prediction work, and no completed Shared AI Learning history yet.');
            }
            if ($followers > 0 && $pendingPredictions <= 0 && $queueToRun <= 0 && $running <= 0 && ($scoredDraws < 4 || (string)($evidence['key'] ?? '') === 'concentrated')) {
                return array('key'=>'needs_more_draw_evidence','label'=>'Needs More Draw History','priority'=>5,'css'=>'mle-v8-status-needs','action'=>'Create a 100-run Shared AI Learning campaign for the next draw cycle.','why'=>'The Shared AI Learning needs prediction history spread across more scored draws. ' . $evidenceLabel . ' means raw run count alone is not enough.');
            }
            if ($pendingPredictions > 0) {
                return array('key'=>'pending_score','label'=>'Pending Score','priority'=>6,'css'=>'mle-v8-status-wait','action'=>$otherPending > 0 ? 'No new batch needed yet. Let the remaining pending score work clear.' : 'No new batch needed yet.','why'=>'Saved predictions already exist and still need scoring.');
            }
            if ($followers > 0 && ((string)($evidence['key'] ?? '') === 'building')) {
                return array('key'=>'building_profile','label'=>'Building Profile','priority'=>7,'css'=>'mle-v8-status-queue','action'=>'Optional: add a 100-run campaign only if this lottery is high demand and no higher-priority lotteries need work.','why'=>'Prediction History is useful but still building across draws.');
            }
            if ($pendingPredictions > 0 || $scored > 0 || $saved > 0) {
                return array('key'=>'covered','label'=>'Scored / Covered','priority'=>8,'css'=>'mle-v8-status-covered','action'=>'No immediate settings test action needed.','why'=>'This lottery already has saved/scored coverage and no urgent Shared AI Learning research gap was found.');
            }
            return array('key'=>'no_demand','label'=>'No Demand Yet','priority'=>9,'css'=>'mle-v8-status-none','action'=>'No immediate action needed unless you want to seed this lottery manually.','why'=>'No followers or active coverage pressure was found for this lottery.');
        };

        $coverageTotals = array(
            'needs_batch' => 0,
            'needs_more_draw_evidence' => 0,
            'queue_ready' => 0,
            'running_now' => 0,
            'needs_review' => 0,
            'waiting_draw' => 0,
            'pending_score' => 0,
            'building_profile' => 0,
            'covered' => 0,
            'no_demand' => 0
        );
        foreach ($displayItems as $__mleV8K => $__mleV8Item) {
            $__mleV8Item = (array)$__mleV8Item;
            $__mleV8Status = $__mleV8CoverageStatusFor($__mleV8Item);
            $__mleV8Evidence = $__mleV9EvidenceStatusFor($__mleV8Item);
            $__mleV8Item['_coverage_status'] = $__mleV8Status;
            $__mleV8Item['_evidence_status'] = $__mleV8Evidence;
            $displayItems[$__mleV8K] = $__mleV8Item;
            $__mleV8Key = (string)($__mleV8Status['key'] ?? 'no_demand');
            if (!isset($coverageTotals[$__mleV8Key])) { $coverageTotals[$__mleV8Key] = 0; }
            $coverageTotals[$__mleV8Key]++;
        }
        usort($displayItems, function($a, $b) {
            $as = (array)($a['_coverage_status'] ?? array('priority'=>99));
            $bs = (array)($b['_coverage_status'] ?? array('priority'=>99));
            $ap = (int)($as['priority'] ?? 99);
            $bp = (int)($bs['priority'] ?? 99);
            if ($ap !== $bp) { return ($ap < $bp) ? -1 : 1; }
            $af = (int)($a['following_users'] ?? 0);
            $bf = (int)($b['following_users'] ?? 0);
            if ($af !== $bf) { return ($bf > $af) ? 1 : -1; }
            $aq = max(0, (int)($a['queue_pending'] ?? 0)) + max(0, (int)($a['assignments_pending'] ?? 0));
            $bq = max(0, (int)($b['queue_pending'] ?? 0)) + max(0, (int)($b['assignments_pending'] ?? 0));
            if ($aq !== $bq) { return ($bq > $aq) ? 1 : -1; }
            return strcasecmp((string)($a['label'] ?? ''), (string)($b['label'] ?? ''));
        });

        $nextRecommendedAction = 'No immediate admin settings test action needed.';
        foreach ($displayItems as $__mleV8Item) {
            $__mleV8Status = (array)($__mleV8Item['_coverage_status'] ?? array());
            if ((int)($__mleV8Status['priority'] ?? 99) <= 5) {
                $nextRecommendedAction = (string)($__mleV8Status['action'] ?? 'Review this lottery.');
                $nextRecommendedAction = (string)($__mleV8Item['label'] ?? 'This lottery') . ': ' . $nextRecommendedAction;
                break;
            }
        }

        $shownTotals = array(
            'lotteries' => count($displayItems),
            'followers' => 0,
            'saved_batch_runs' => 0,
            'already_scored' => 0,
            'scored_draws' => 0,
            'waiting_to_be_scored' => 0,
            'waiting_for_draw' => 0,
            'other_pending_score' => 0,
            'queue_to_run' => 0,
            'running_now' => 0,
            'failed_needs_review' => 0,
            'pending_batch_plans' => 0
        );
        foreach ($displayItems as $__mleV190TotalItem) {
            $__mleV190TotalItem = (array)$__mleV190TotalItem;
            $__mleV190PendingScore = max(0, (int)($__mleV190TotalItem['pending_unscored_batch_runs'] ?? 0));
            $__mleV190WaitingDraw = max(0, (int)($__mleV190TotalItem['waiting_official_draw'] ?? 0));
            $__mleV190OtherPending = max(0, $__mleV190PendingScore - $__mleV190WaitingDraw);
            $__mleV190QueueToRun = max(0, (int)($__mleV190TotalItem['queue_pending'] ?? 0)) + max(0, (int)($__mleV190TotalItem['assignments_pending'] ?? 0));
            $__mleV190PendingBatchPlans = max(0, (int)($__mleV190TotalItem['planned_runs_pending'] ?? 0));
            $__mleV190Running = max(0, (int)($__mleV190TotalItem['queue_running'] ?? 0)) + max(0, (int)($__mleV190TotalItem['assignments_running'] ?? 0));
            $__mleV190FailedUnknown = max(0, (int)($__mleV190TotalItem['queue_failed'] ?? 0)) + max(0, (int)($__mleV190TotalItem['assignments_failed'] ?? 0)) + max(0, (int)($__mleV190TotalItem['assignments_unknown'] ?? 0));
            $shownTotals['followers'] += max(0, (int)($__mleV190TotalItem['following_users'] ?? 0));
            $shownTotals['saved_batch_runs'] += max(0, (int)($__mleV190TotalItem['saved_batch_runs'] ?? 0));
            $shownTotals['already_scored'] += max(0, (int)($__mleV190TotalItem['scored_batch_runs'] ?? 0));
            $shownTotals['scored_draws'] += max(0, (int)($__mleV190TotalItem['scored_draw_count'] ?? 0));
            $shownTotals['waiting_to_be_scored'] += $__mleV190OtherPending;
            $shownTotals['waiting_for_draw'] += $__mleV190WaitingDraw;
            $shownTotals['other_pending_score'] += $__mleV190OtherPending;
            $shownTotals['queue_to_run'] += $__mleV190QueueToRun;
            $shownTotals['pending_batch_plans'] += $__mleV190PendingBatchPlans;
            $shownTotals['running_now'] += $__mleV190Running;
            $shownTotals['failed_needs_review'] += $__mleV190FailedUnknown;
        }

        try {
            $baseUri = \Joomla\CMS\Uri\Uri::getInstance();
            $fullUri = clone $baseUri;
            $fullUri->setVar('mle_full_workspace', '1');
            $fullWorkspaceUrl = $fullUri->toString();
            $refreshUri = clone $baseUri;
            $refreshUrl = $refreshUri->toString();
            $candidateUri = clone $baseUri;
