                              }
                              if ($lotteryIdColumnForButton !== '' && in_array('game_id', $lotteryColsForButton, true)) {
                                  $db->setQuery('SELECT ' . $db->quoteName($lotteryIdColumnForButton) . ' FROM ' . $db->quoteName('#__lotteries') . ' WHERE ' . $db->quoteName('game_id') . ' = ' . $db->quote($gameIdLabel) . ' ORDER BY ' . $db->quoteName($lotteryIdColumnForButton) . ' ASC', 0, 1);
                                  $rowLotteryId = max(0, (int)$db->loadResult());
                              }
                          } catch (\Throwable $__mleV12ResolveLidEx) { $rowLotteryId = max(0, (int)$rowLotteryId); }
