                      if ($recommendedTargetDrawDate === '') { $recommendedTargetDrawDate = substr((string)($item['latest_target_draw_date'] ?? ''), 0, 10); }
                      if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$recommendedTargetDrawDate)) { $recommendedTargetDrawDate = ''; }
