            <script>
(function(){
  function ready(fn){ if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', fn); } else { fn(); } }
  ready(function(){
    var root = document.getElementById('mle-v182-admin-batch-glance');
    if(!root || window.__mleV92NeverRanCleanupStarted){ return; }
    window.__mleV92NeverRanCleanupStarted = true;
    var tokenName = <?php echo json_encode(\Joomla\CMS\Session\Session::getFormToken()); ?>;
    var endpoint = <?php echo json_encode(\Joomla\CMS\Uri\Uri::getInstance()->toString(array('scheme','host','port','path','query'))); ?>;
    function postChunk(pass){
      if(pass > 4 || !window.FormData || !window.XMLHttpRequest){ return; }
      var fd = new FormData();
      fd.append('mle_ajax_action', 'cleanup_never_ran_batch_plans');
      fd.append('limit', '25');
      fd.append(tokenName, '1');
      var xhr = new XMLHttpRequest();
      xhr.open('POST', endpoint, true);
      xhr.onreadystatechange = function(){
        if(xhr.readyState !== 4){ return; }
        try {
          if(xhr.status < 200 || xhr.status >= 300){ return; }
          var data = JSON.parse(xhr.responseText || '{}');
          if(data && data.ok && parseInt(data.changed_headers || 0, 10) > 0){
            var note = document.getElementById('mle-v92-cleanup-note');
            if(!note){
              note = document.createElement('div');
              note.id = 'mle-v92-cleanup-note';
              note.style.cssText = 'margin:.65rem 0;padding:.55rem .7rem;border:1px solid #bfdbfe;border-radius:10px;background:#eff6ff;color:#1e3a8a;font-size:.82rem;';
              root.insertBefore(note, root.firstChild);
            }
            note.textContent = 'Background cleanup marked ' + parseInt(data.changed_headers || 0, 10) + ' abandoned never-ran batch plan(s). Refresh later to see updated counts.';
            window.setTimeout(function(){ postChunk(pass + 1); }, 900);
          }
        } catch(e) {}
      };
      window.setTimeout(function(){ try { xhr.send(fd); } catch(e) {} }, 600);
    }
    postChunk(1);
  });
})();
</script>
            <script>
(function(){
  function ready(fn){ if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', fn); } else { fn(); } }
  function cleanText(value){ return String(value || '').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, ''); }
  function numericValue(value){
    var n = parseFloat(String(value || '').replace(/[^0-9.\-]/g, ''));
    return isNaN(n) ? 0 : n;
  }
  function cellValue(row, index, type){
    var cells = row.cells || [];
    var cell = cells[index];
    if(!cell){ return type === 'number' ? 0 : ''; }
    var txt = cleanText(cell.textContent || cell.innerText || '');
    return type === 'number' ? numericValue(txt) : txt.toLowerCase();
  }
  ready(function(){
    var root = document.getElementById('mle-v182-admin-batch-glance');
    if(!root){ return; }
    var table = root.querySelector ? root.querySelector('table[data-mle-batch-glance-sortable]') : null;
    if(!table || !table.tHead || !table.tBodies || !table.tBodies.length){ return; }
    var headers = table.tHead.rows[0] ? table.tHead.rows[0].cells : [];
    var tbody = table.tBodies[0];
    var lastIndex = -1;
    var lastDirection = 'asc';
    for(var i=0; i<headers.length; i++){
      (function(index){
        var th = headers[index];
        if(!th){ return; }
        th.setAttribute('tabindex', '0');
        th.setAttribute('role', 'button');
        th.setAttribute('aria-sort', 'none');
        var type = th.getAttribute('data-mle-sort-type') || 'text';
        function applySort(){
          var direction = (lastIndex === index && lastDirection === 'asc') ? 'desc' : 'asc';
          var rows = [];
          for(var r=0; r<tbody.rows.length; r++){
            if(tbody.rows[r].cells && tbody.rows[r].cells.length > 1){ rows.push(tbody.rows[r]); }
          }
          rows.sort(function(a,b){
            var av = cellValue(a, index, type);
            var bv = cellValue(b, index, type);
            if(type === 'number'){
              if(av === bv){ return 0; }
              return direction === 'asc' ? av - bv : bv - av;
            }
            if(av === bv){ return 0; }
            return direction === 'asc' ? (av < bv ? -1 : 1) : (av > bv ? -1 : 1);
          });
          for(var x=0; x<rows.length; x++){ tbody.appendChild(rows[x]); }
          for(var h=0; h<headers.length; h++){ headers[h].setAttribute('aria-sort', 'none'); }
          th.setAttribute('aria-sort', direction === 'asc' ? 'ascending' : 'descending');
          lastIndex = index;
          lastDirection = direction;
        }
        th.onclick = applySort;
        th.onkeydown = function(ev){ ev = ev || window.event; var key = ev.key || ev.keyCode; if(key === 'Enter' || key === ' ' || key === 13 || key === 32){ if(ev.preventDefault){ ev.preventDefault(); } applySort(); return false; } };
      })(i);
    }
  });
})();
</script>
