        return '<div class="mle-v133-period-card">'
            . '<span class="mle-v133-period-card__label">' . htmlspecialchars((string)$title, ENT_QUOTES, 'UTF-8') . '</span>'
            . '<strong class="mle-v133-period-card__value">' . (int)$current . '</strong>'
            . '<span class="mle-v133-period-card__trend mle-v133-period-card__trend--' . htmlspecialchars((string)$meta['class'], ENT_QUOTES, 'UTF-8') . '">vs ' . htmlspecialchars((string)$previousLabel, ENT_QUOTES, 'UTF-8') . ': ' . htmlspecialchars((string)$meta['label'], ENT_QUOTES, 'UTF-8') . '</span>'
            . '<span class="mle-v133-period-card__note">' . htmlspecialchars((string)$previousLabel, ENT_QUOTES, 'UTF-8') . ': ' . (int)$previous . '. ' . htmlspecialchars((string)$note, ENT_QUOTES, 'UTF-8') . '</span>'
            . '</div>';
    }
}

