        );
        try {
            $queueCols = array();
            try { $queueCols = array_keys($db->getTableColumns('#__mle_lottery_research_queue', false)); } catch (\Throwable $e) { $queueCols = array(); }
            $assignCols = array();
            try { $assignCols = array_keys($db->getTableColumns('#__mle_lottery_research_assignments', false)); } catch (\Throwable $e) { $assignCols = array(); }

            $assignmentGameParts = array();
            if (in_array('game_id', $assignCols, true)) { $assignmentGameParts[] = 'a.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey); }
            if (in_array('target_game_id', $assignCols, true)) { $assignmentGameParts[] = 'a.' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameKey); }
            if (in_array('game_id', $queueCols, true)) { $assignmentGameParts[] = 'q.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey); }
            if (in_array('target_game_id', $queueCols, true)) { $assignmentGameParts[] = 'q.' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameKey); }
            if (empty($assignmentGameParts)) {
                return array('ok'=>false,'error'=>'missing_game_columns','message'=>'Could not identify game columns in the research queue tables. Cleanup stopped.','game_key'=>$gameKey);
            }
            $whereGame = '(' . implode(' OR ', $assignmentGameParts) . ')';

            $queueGameParts = array();
            if (in_array('game_id', $queueCols, true)) { $queueGameParts[] = 'q.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey); }
            if (in_array('target_game_id', $queueCols, true)) { $queueGameParts[] = 'q.' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameKey); }
            $whereQueueGame = !empty($queueGameParts) ? '(' . implode(' OR ', $queueGameParts) . ')' : '0=1';

            $savedLinkedAssignmentSafe = '0=1';
