            if (in_array('scored_count', $assignCols, true)) { $terminalParts[] = 'COALESCE(a.' . $db->quoteName('scored_count') . ',0) > 0'; }
            if (in_array('completed_at', $assignCols, true)) { $terminalParts[] = '(a.' . $db->quoteName('completed_at') . ' IS NOT NULL AND a.' . $db->quoteName('completed_at') . ' <> ' . $db->quote('') . ')'; }
            if (in_array('runner_saved_at', $assignCols, true)) { $terminalParts[] = '(a.' . $db->quoteName('runner_saved_at') . ' IS NOT NULL AND a.' . $db->quoteName('runner_saved_at') . ' <> ' . $db->quote('') . ')'; }
            $terminalSafe = !empty($terminalParts) ? '(' . implode(' OR ', $terminalParts) . ')' : '0=1';

            $runnableParts = array();
            if (in_array('runner_status', $assignCols, true)) {
                $runnableParts[] = 'LOWER(TRIM(COALESCE(a.' . $db->quoteName('runner_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('') . ',' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('retry') . ',' . $db->quote('pending') . ',' . $db->quote('running') . ',' . $db->quote('in_progress') . ',' . $db->quote('failed') . ',' . $db->quote('error') . ')';
            }
            if (in_array('assigned_status', $assignCols, true)) {
                $runnableParts[] = 'LOWER(TRIM(COALESCE(a.' . $db->quoteName('assigned_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('') . ',' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('retry') . ',' . $db->quote('pending') . ',' . $db->quote('running') . ',' . $db->quote('in_progress') . ',' . $db->quote('failed') . ',' . $db->quote('error') . ')';
            }
            $runnableExpr = !empty($runnableParts) ? '(NOT (' . $terminalSafe . ') AND (' . implode(' OR ', $runnableParts) . '))' : 'NOT (' . $terminalSafe . ')';

            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame);
            $out['before_assignments_total'] = (int)$db->loadResult();
            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame . ' AND (' . $runnableExpr . ')');
            $out['before_assignments_runnable'] = (int)$db->loadResult();
            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' WHERE ' . $whereQueueGame);
            $out['before_queue_rows'] = (int)$db->loadResult();
            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame . ' AND (' . $terminalSafe . ')');
            $out['saved_or_completed_assignments_retained'] = (int)$db->loadResult();
