                $savedGameParts = array();
                if (in_array('game_id', $savedCols, true)) { $savedGameParts[] = $db->quoteName('game_id') . ' = ' . $db->quote($gameKey); }
                if (in_array('target_game_id', $savedCols, true)) { $savedGameParts[] = $db->quoteName('target_game_id') . ' = ' . $db->quote($gameKey); }
                if (!empty($savedGameParts)) {
                    $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__user_saved_numbers') . ' WHERE (' . implode(' OR ', $savedGameParts) . ')');
