            }
            if (function_exists('mylottoexpertTableExistsSafe') && mylottoexpertTableExistsSafe($db, $prefix . 'mle_skai_batch_run')) {
                try {
                    $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_skai_batch_run', 'r') . ' INNER JOIN ' . $db->quoteName('#__mle_skai_batch_header', 'h') . ' ON h.' . $db->quoteName('id') . ' = r.' . $db->quoteName('batch_id') . ' WHERE h.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey));
                    $out['protected_user_batch_runs'] = (int)$db->loadResult();
                } catch (\Throwable $e) { $out['protected_user_batch_runs'] = 0; }
            }

            $db->transactionStart();
            $db->setQuery('DELETE a FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame . ' AND (' . $runnableExpr . ')');
            $db->execute();
            $out['assignments_deleted'] = (int)$db->getAffectedRows();

            $axSafeParts = array();
            if (in_array('runner_status', $assignCols, true)) { $axSafeParts[] = 'LOWER(TRIM(COALESCE(ax.' . $db->quoteName('runner_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('saved') . ',' . $db->quote('completed') . ',' . $db->quote('complete') . ',' . $db->quote('observed') . ',' . $db->quote('scored') . ')'; }
            if (in_array('assigned_status', $assignCols, true)) { $axSafeParts[] = 'LOWER(TRIM(COALESCE(ax.' . $db->quoteName('assigned_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('saved') . ',' . $db->quote('completed') . ',' . $db->quote('complete') . ',' . $db->quote('observed') . ',' . $db->quote('scored') . ')'; }
            if (in_array('result_status', $assignCols, true)) { $axSafeParts[] = 'LOWER(TRIM(COALESCE(ax.' . $db->quoteName('result_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('saved') . ',' . $db->quote('completed') . ',' . $db->quote('complete') . ',' . $db->quote('observed') . ',' . $db->quote('scored') . ')'; }
            if (in_array('saved_count', $assignCols, true)) { $axSafeParts[] = 'COALESCE(ax.' . $db->quoteName('saved_count') . ',0) > 0'; }
            if (in_array('scored_count', $assignCols, true)) { $axSafeParts[] = 'COALESCE(ax.' . $db->quoteName('scored_count') . ',0) > 0'; }
            if (in_array('completed_at', $assignCols, true)) { $axSafeParts[] = '(ax.' . $db->quoteName('completed_at') . ' IS NOT NULL AND ax.' . $db->quoteName('completed_at') . ' <> ' . $db->quote('') . ')'; }
            if (in_array('runner_saved_at', $assignCols, true)) { $axSafeParts[] = '(ax.' . $db->quoteName('runner_saved_at') . ' IS NOT NULL AND ax.' . $db->quoteName('runner_saved_at') . ' <> ' . $db->quote('') . ')'; }
            $axTerminal = !empty($axSafeParts) ? '(' . implode(' OR ', $axSafeParts) . ')' : '0=1';
            $openAssignmentExists = 'EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'ax') . ' WHERE ax.' . $db->quoteName('queue_id') . ' = q.' . $db->quoteName('id') . ' AND NOT (' . $axTerminal . '))';

            $closeSet = array();
            if (in_array('research_status', $queueCols, true)) { $closeSet[] = 'q.' . $db->quoteName('research_status') . ' = ' . $db->quote('completed'); }
            elseif (in_array('status', $queueCols, true)) { $closeSet[] = 'q.' . $db->quoteName('status') . ' = ' . $db->quote('completed'); }
            if (in_array('result_status', $queueCols, true)) { $closeSet[] = 'q.' . $db->quoteName('result_status') . ' = CASE WHEN TRIM(COALESCE(q.' . $db->quoteName('result_status') . ', ' . $db->quote('') . ')) = ' . $db->quote('') . ' THEN ' . $db->quote('observed') . ' ELSE q.' . $db->quoteName('result_status') . ' END'; }
            if (in_array('last_reconciled_at', $queueCols, true)) { $closeSet[] = 'q.' . $db->quoteName('last_reconciled_at') . ' = ' . $db->quote($now); }
            if (!empty($closeSet)) {
                $db->setQuery('UPDATE ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' SET ' . implode(', ', $closeSet) . ' WHERE ' . $whereQueueGame . ' AND EXISTS (SELECT 1 FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'ay') . ' WHERE ay.' . $db->quoteName('queue_id') . ' = q.' . $db->quoteName('id') . ') AND NOT (' . $openAssignmentExists . ')');
                $db->execute();
                $out['queue_rows_closed'] = (int)$db->getAffectedRows();
            }

            $db->setQuery('DELETE q FROM ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' LEFT JOIN ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' ON a.' . $db->quoteName('queue_id') . ' = q.' . $db->quoteName('id') . ' WHERE ' . $whereQueueGame . ' AND a.' . $db->quoteName('id') . ' IS NULL');
            $db->execute();
            $out['queue_rows_deleted'] = (int)$db->getAffectedRows();

            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame);
            $out['after_assignments_total'] = (int)$db->loadResult();
            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . ' INNER JOIN ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' WHERE ' . $whereGame . ' AND (' . $runnableExpr . ')');
            $out['after_assignments_runnable'] = (int)$db->loadResult();
            $db->setQuery('SELECT COUNT(*) FROM ' . $db->quoteName('#__mle_lottery_research_queue', 'q') . ' WHERE ' . $whereQueueGame);
            $out['after_queue_rows'] = (int)$db->loadResult();
            $out['queue_rows_retained'] = (int)$out['after_queue_rows'];
            $db->transactionCommit();

            $out['ok'] = true;
            $out['message'] = (!empty($hardDeleteMode) ? 'Deleted failed and queued research work for game ' : 'Reset visible research waiting prediction work for game ') . $gameKey . '. Saved predictions, linked saved assignment prediction history, successful prediction history, and AI saved batch history were not touched.';
            try {
                @file_put_contents(JPATH_ADMINISTRATOR . '/logs/mylottoexpert_game_queue_reset.log', $now . ' | scope=' . (string)$out['scope'] . ' | user_id=' . (int)($user->id ?? 0) . ' | game_key=' . $gameKey . ' | before_assignments_total=' . (int)$out['before_assignments_total'] . ' | before_assignments_runnable=' . (int)$out['before_assignments_runnable'] . ' | assignments_deleted=' . (int)$out['assignments_deleted'] . ' | queue_rows_deleted=' . (int)$out['queue_rows_deleted'] . ' | queue_rows_closed=' . (int)$out['queue_rows_closed'] . ' | after_assignments_total=' . (int)$out['after_assignments_total'] . ' | after_assignments_runnable=' . (int)$out['after_assignments_runnable'] . ' | after_queue_rows=' . (int)$out['after_queue_rows'] . ' | linked_saved_assignments_retained=' . (int)$out['linked_saved_assignments_retained'] . ' | saved_rows_retained=' . (int)$out['saved_rows_retained'] . ' | protected_batch_headers=' . (int)$out['protected_user_batch_headers'] . ' | protected_batch_runs=' . (int)$out['protected_user_batch_runs'] . PHP_EOL, FILE_APPEND | LOCK_EX);
            } catch (\Throwable $e) {}
            return $out;
        } catch (\Throwable $e) {
            try { $db->transactionRollback(); } catch (\Throwable $ignore) {}
            return array('ok'=>false,'error'=>'db_error','message'=>$e->getMessage(),'game_key'=>$gameKey);
        }
    }
}

if (!function_exists('mylottoexpertV178GameQueueCommand')) {
    function mylottoexpertV178GameQueueCommand($db, $user, array $input) {
        if (!mylottoexpertV150IsSuperUser($user)) { return array('ok'=>false,'error'=>'forbidden'); }
        mylottoexpertV150EnsureIntegratedSchema($db);
        $gameKey = preg_replace('/[^a-zA-Z0-9_\-\.]/', '', (string)($input['game_key'] ?? ''));
        $command = strtolower(preg_replace('/[^a-z0-9_\-]/i', '', (string)($input['command'] ?? '')));
        if ($gameKey === '') { return array('ok'=>false,'error'=>'missing_game_key'); }
        $now = date('Y-m-d H:i:s');
        $assignTable = '#__mle_lottery_research_assignments';
        $queueTable = '#__mle_lottery_research_queue';
        $whereGame = '(a.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey) . ' OR q.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameKey) . ')';
        $base = 'UPDATE ' . $db->quoteName($assignTable, 'a') . ' INNER JOIN ' . $db->quoteName($queueTable, 'q') . ' ON q.' . $db->quoteName('id') . ' = a.' . $db->quoteName('queue_id') . ' SET ';
        if ($command === 'resume_prepare_game' || $command === 'reset_running_game') {
            $sql = $base
                . 'a.' . $db->quoteName('runner_status') . ' = ' . $db->quote('queued')
                . ', a.' . $db->quoteName('assigned_status') . ' = ' . $db->quote('assigned')
                . ', a.' . $db->quoteName('runner_message') . ' = ' . $db->quote('Prepared for game queue resume by admin on ' . $now)
                . ' WHERE ' . $whereGame
                . ' AND a.' . $db->quoteName('runner_status') . ' = ' . $db->quote('running');
            try { $db->setQuery($sql); $db->execute(); return array('ok'=>true,'command'=>$command,'game_key'=>$gameKey,'changed'=>(int)$db->getAffectedRows()); }
            catch (\Throwable $e) { return array('ok'=>false,'error'=>'db_error','message'=>$e->getMessage()); }
        }
        if ($command === 'retry_failed_game') {
            $sql = $base
                . 'a.' . $db->quoteName('runner_status') . ' = ' . $db->quote('queued')
                . ', a.' . $db->quoteName('assigned_status') . ' = ' . $db->quote('assigned')
                . ', a.' . $db->quoteName('runner_message') . ' = ' . $db->quote('Waiting for game retry by admin on ' . $now)
                . ', a.' . $db->quoteName('saved_count') . ' = 0'
                . ' WHERE ' . $whereGame
                . ' AND a.' . $db->quoteName('runner_status') . ' = ' . $db->quote('failed');
            try { $db->setQuery($sql); $db->execute(); return array('ok'=>true,'command'=>$command,'game_key'=>$gameKey,'changed'=>(int)$db->getAffectedRows()); }
            catch (\Throwable $e) { return array('ok'=>false,'error'=>'db_error','message'=>$e->getMessage()); }
        }
        return array('ok'=>false,'error'=>'unknown_game_queue_command');
    }
}

