        if (!empty($__mleV178ResetResult['ok'])) {
            $app->enqueueMessage(((isset($__mleV178ResetResult['scope']) && $__mleV178ResetResult['scope'] === 'delete_failed_and_queued_research_work') ? 'Failed/queued queue delete complete for game ' : 'Queue reset complete for game ') . htmlspecialchars($__mleV178ResetGameKey, ENT_QUOTES, 'UTF-8') . '. Before: ' . (int)($__mleV178ResetResult['before_assignments_runnable'] ?? 0) . ' runnable assignment(s). Deleted ' . (int)($__mleV178ResetResult['assignments_deleted'] ?? 0) . ' runnable/failed assignment(s), deleted ' . (int)($__mleV178ResetResult['queue_rows_deleted'] ?? 0) . ' empty queue row(s), closed ' . (int)($__mleV178ResetResult['queue_rows_closed'] ?? 0) . ' completed/prediction history queue row(s). After: ' . (int)($__mleV178ResetResult['after_assignments_runnable'] ?? 0) . ' runnable assignment(s) and ' . (int)($__mleV178ResetResult['after_queue_rows'] ?? 0) . ' research queue row(s). User saved predictions and AI saved batch history were protected.', 'message');
        } else {
            $app->enqueueMessage('Queue cleanup failed: ' . htmlspecialchars((string)($__mleV178ResetResult['message'] ?? $__mleV178ResetResult['error'] ?? 'unknown error'), ENT_QUOTES, 'UTF-8'), 'error');
        }
        $__mleV178ResetRedirect = \Joomla\CMS\Uri\Uri::getInstance();
        $__mleV178ResetRedirect->delVar('mle_action');
        $__mleV178ResetRedirect->delVar('game_key');
        $__mleV178ResetRedirect->delVar('clear_confirm');
        $app->redirect((string)$__mleV178ResetRedirect);
        exit;
    }
} catch (\Throwable $__mleV178EarlyResetEx) {
