if (!function_exists('mylottoexpertV188AdminUrl')) {
    function mylottoexpertV188AdminUrl($key, $value = '1')
    {
        try {
            $uri = \Joomla\CMS\Uri\Uri::getInstance();
            $u = clone $uri;
            $u->setVar((string)$key, (string)$value);
            return $u->toString();
        } catch (\Throwable $e) {
            return '?' . rawurlencode((string)$key) . '=' . rawurlencode((string)$value);
        }
    }
}


if (!function_exists('mylottoexpertV189BuildGameQueueRunnerUrl')) {
    function mylottoexpertV189BuildGameQueueRunnerUrl($gameKey, $total = 0, $autostart = true)
    {
        $gameKey = preg_replace('/[^a-zA-Z0-9_\-]/', '', (string)$gameKey);
        if ($gameKey === '') { return ''; }
        $params = array(
            'gameId' => $gameKey,
            'gid' => $gameKey,
            'hive_research_runner' => '1',
            'mle_game_queue' => $gameKey,
            'mle_game_queue_total' => max(0, (int)$total),
            'mle_autostart' => $autostart ? '1' : '0'
        );
        return '/picking-winning-numbers/artificial-intelligence/skai-lottery-prediction?' . http_build_query($params, '', '&', PHP_QUERY_RFC3986) . '#skai-v158-hive-runner';
    }
}

if (!function_exists('mylottoexpertV189QueueTargetName')) {
    function mylottoexpertV189QueueTargetName($gameKey)
    {
        $gameKey = preg_replace('/[^a-zA-Z0-9_\-]/', '_', (string)$gameKey);
        return 'mle_queue_' . ($gameKey !== '' ? $gameKey : 'pending');
    }
}

if (!function_exists('mylottoexpertV188TableExists')) {
    function mylottoexpertV188TableExists($db, $table)
    {
        try {
            if (function_exists('mylottoexpertV175TableExists')) { return (bool)mylottoexpertV175TableExists($db, $table); }
            if (function_exists('mylottoexpertTableExistsSafe')) { return (bool)mylottoexpertTableExistsSafe($db, $db->getPrefix() . ltrim((string)$table, '#_')); }
            $name = str_replace('#__', $db->getPrefix(), (string)$table);
            $db->setQuery('SHOW TABLES LIKE ' . $db->quote($name));
            return (bool)$db->loadResult();
        } catch (\Throwable $e) { return false; }
    }
}

if (!function_exists('mylottoexpertV188Columns')) {
    function mylottoexpertV188Columns($db, $table)
    {
        try {
            if (function_exists('mylottoexpertV175Columns')) { return (array)mylottoexpertV175Columns($db, $table); }
            if (function_exists('mylottoexpertGetTableColumnNames')) { return (array)mylottoexpertGetTableColumnNames($db, $table); }
        } catch (\Throwable $e) { }
        return array();
    }
}

if (!function_exists('mylottoexpertV188HasColumn')) {
    function mylottoexpertV188HasColumn($cols, $name)
    {
        if (isset($cols[$name])) { return true; }
        foreach ((array)$cols as $k => $v) { if ((string)$k === (string)$name || (string)$v === (string)$name) { return true; } }
        return false;
    }
}

if (!function_exists('mylottoexpertV188LoadAdminQueueHealth')) {
    function mylottoexpertV188LoadAdminQueueHealth($db)
    {
        $out = array(
            'assignments_available' => false,
            'queue_available' => false,
            'queued' => 0,
            'running' => 0,
            'saved' => 0,
            'failed' => 0,
            'unknown' => 0,
            'old_running' => 0,
            'queue_rows' => 0,
            'queue_waiting' => 0,
            'latest_runner_activity' => '',
            'message' => ''
        );
        try {
            if (mylottoexpertV188TableExists($db, 'mle_lottery_research_assignments')) {
                $out['assignments_available'] = true;
                $cols = mylottoexpertV188Columns($db, 'mle_lottery_research_assignments');
                $statusParts = array();
                if (mylottoexpertV188HasColumn($cols, 'runner_status')) { $statusParts[] = 'NULLIF(LOWER(TRIM(a.' . $db->quoteName('runner_status') . ')), ' . $db->quote('') . ')'; }
                if (mylottoexpertV188HasColumn($cols, 'assigned_status')) { $statusParts[] = 'NULLIF(LOWER(TRIM(a.' . $db->quoteName('assigned_status') . ')), ' . $db->quote('') . ')'; }
                $statusExpr = !empty($statusParts) ? 'COALESCE(' . implode(',', $statusParts) . ',' . $db->quote('unknown') . ')' : $db->quote('unknown');
                $activityParts = array();
                foreach (array('runner_saved_at','runner_started_at','completed_at','assigned_at','updated_at','created_at') as $c) {
                    if (mylottoexpertV188HasColumn($cols, $c)) { $activityParts[] = 'NULLIF(a.' . $db->quoteName($c) . ', ' . $db->quote('0000-00-00 00:00:00') . ')'; }
                }
                $activityExpr = !empty($activityParts) ? 'MAX(COALESCE(' . implode(',', $activityParts) . '))' : $db->quote('');
                $oldRunningExpr = '0';
                if (mylottoexpertV188HasColumn($cols, 'runner_started_at')) {
                    $oldRunningExpr = 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('running') . ',' . $db->quote('started') . ') AND a.' . $db->quoteName('runner_started_at') . ' < DATE_SUB(NOW(), INTERVAL 45 MINUTE) THEN 1 ELSE 0 END)';
                }
                $healthWhere = '';
                $healthDateParts = array();
                foreach (array('runner_saved_at','runner_started_at','completed_at','assigned_at','created_at') as $c) {
                    if (mylottoexpertV188HasColumn($cols, $c)) { $healthDateParts[] = 'a.' . $db->quoteName($c); }
                }
                if (!empty($healthDateParts)) {
                    $recentExpr = 'COALESCE(' . implode(',', $healthDateParts) . ')';
                    $healthWhere = ' WHERE (' . $statusExpr . ' IN (' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('retry') . ',' . $db->quote('pending') . ',' . $db->quote('waiting') . ',' . $db->quote('running') . ',' . $db->quote('started') . ',' . $db->quote('failed') . ',' . $db->quote('error') . ') OR ' . $recentExpr . ' >= DATE_SUB(NOW(), INTERVAL 180 DAY))';
                }
                $sql = 'SELECT '
                    . 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('queued') . ',' . $db->quote('assigned') . ',' . $db->quote('retry') . ',' . $db->quote('pending') . ',' . $db->quote('waiting') . ') THEN 1 ELSE 0 END) AS queued, '
                    . 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('running') . ',' . $db->quote('started') . ') THEN 1 ELSE 0 END) AS running, '
                    . 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('saved') . ',' . $db->quote('completed') . ') THEN 1 ELSE 0 END) AS saved, '
                    . 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('failed') . ',' . $db->quote('error') . ') THEN 1 ELSE 0 END) AS failed, '
                    . 'SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('') . ',' . $db->quote('unknown') . ') THEN 1 ELSE 0 END) AS unknown, '
                    . $oldRunningExpr . ' AS old_running, '
                    . $activityExpr . ' AS latest_runner_activity '
                    . 'FROM ' . $db->quoteName('#__mle_lottery_research_assignments', 'a') . $healthWhere;
                $db->setQuery($sql);
                $r = (array)$db->loadAssoc();
                foreach (array('queued','running','saved','failed','unknown','old_running') as $k) { $out[$k] = (int)($r[$k] ?? 0); }
                $out['latest_runner_activity'] = (string)($r['latest_runner_activity'] ?? '');
            }
            if (mylottoexpertV188TableExists($db, 'mle_lottery_research_queue')) {
                $out['queue_available'] = true;
                $cols = mylottoexpertV188Columns($db, 'mle_lottery_research_queue');
                $statusExpr = mylottoexpertV188HasColumn($cols, 'research_status') ? 'LOWER(TRIM(q.' . $db->quoteName('research_status') . '))' : $db->quote('');
                $db->setQuery('SELECT COUNT(*) AS total_rows, SUM(CASE WHEN ' . $statusExpr . ' IN (' . $db->quote('queued') . ',' . $db->quote('pending') . ',' . $db->quote('planned') . ',' . $db->quote('observed_saved') . ') THEN 1 ELSE 0 END) AS waiting_rows FROM ' . $db->quoteName('#__mle_lottery_research_queue', 'q'));
                $q = (array)$db->loadAssoc();
                $out['queue_rows'] = (int)($q['total_rows'] ?? 0);
                $out['queue_waiting'] = (int)($q['waiting_rows'] ?? 0);
            }
        } catch (\Throwable $e) { $out['message'] = 'Queue health check failed: ' . $e->getMessage(); }
        return $out;
    }
}

if (!function_exists('mylottoexpertV188LoadAdminScoringHealth')) {
    function mylottoexpertV188LoadAdminScoringHealth($db)
    {
        $out = array('available'=>false,'pending'=>0,'waiting_draw'=>0,'past_due'=>0,'past_due_waiting_official'=>0,'past_due_review'=>0,'future_pending'=>0,'missing_target'=>0,'latest_saved'=>'','latest_scored'=>'','wait_reasons'=>array(),'statuses'=>array(),'message'=>'');
        try {
            if (!mylottoexpertV188TableExists($db, 'user_saved_numbers')) { return $out; }
            $out['available'] = true;
            $cols = mylottoexpertV188Columns($db, 'user_saved_numbers');
            $statusExpr = mylottoexpertV188HasColumn($cols, 'evaluation_status') ? 'LOWER(TRIM(COALESCE(s.' . $db->quoteName('evaluation_status') . ',' . $db->quote('pending') . ')))' : $db->quote('pending');
            $targetParts = array();
            foreach (array('target_draw_date','actual_draw_date','next_draw_date') as $c) { if (mylottoexpertV188HasColumn($cols, $c)) { $targetParts[] = 'NULLIF(NULLIF(NULLIF(s.' . $db->quoteName($c) . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ')'; } }
            $targetExpr = !empty($targetParts) ? 'COALESCE(' . implode(',', $targetParts) . ')' : 'NULL';
            $dateSavedExpr = mylottoexpertV188HasColumn($cols, 'date_saved') ? 'MAX(s.' . $db->quoteName('date_saved') . ')' : $db->quote('');
            $scoredAtExpr = mylottoexpertV188HasColumn($cols, 'evaluated_at') ? 'MAX(s.' . $db->quoteName('evaluated_at') . ')' : $db->quote('');
            $terminalStatuses = array($db->quote('scored'), $db->quote('evaluated'), $db->quote('checked'), $db->quote('completed'), $db->quote('archived'), $db->quote('retired'), $db->quote('deleted'), $db->quote('discarded'), $db->quote('cancelled'), $db->quote('canceled'), $db->quote('void'), $db->quote('not_scoreable'), $db->quote('stale_cancelled'), $db->quote('legacy_missing_target'));
            $unscoredCond = $statusExpr . ' NOT IN (' . implode(',', $terminalStatuses) . ')';
            $waitReasonExpr = mylottoexpertV188HasColumn($cols, 'hive_cron_wait_reason') ? 'LOWER(TRIM(COALESCE(s.' . $db->quoteName('hive_cron_wait_reason') . ',' . $db->quote('') . ')))' : $db->quote('');
            $waitCond = $waitReasonExpr . ' = ' . $db->quote('official_draw_not_loaded');
            $targetCleanExpr = !empty($targetParts) ? $targetExpr : 'NULL';
            $targetMissingCond = !empty($targetParts) ? '(' . $targetCleanExpr . ' IS NULL OR ' . $targetCleanExpr . ' = ' . $db->quote('') . ')' : '1=1';
            $targetPastCond = !empty($targetParts) ? '(NOT (' . $targetMissingCond . ') AND DATE(' . $targetCleanExpr . ') < CURDATE())' : '0=1';
            $targetFutureCond = !empty($targetParts) ? '(NOT (' . $targetMissingCond . ') AND DATE(' . $targetCleanExpr . ') >= CURDATE())' : '0=1';
            $pendingExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' THEN 1 ELSE 0 END)';
            $waitExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $waitCond . ' THEN 1 ELSE 0 END)';
            $pastDueExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $targetPastCond . ' THEN 1 ELSE 0 END)';
            $pastDueWaitingExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $targetPastCond . ' AND ' . $waitCond . ' THEN 1 ELSE 0 END)';
            $pastDueReviewExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $targetPastCond . ' AND NOT (' . $waitCond . ') THEN 1 ELSE 0 END)';
            $futurePendingExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $targetFutureCond . ' THEN 1 ELSE 0 END)';
            $missingTargetExpr = 'SUM(CASE WHEN ' . $unscoredCond . ' AND ' . $targetMissingCond . ' THEN 1 ELSE 0 END)';
            $savedWhere = '';
            if (mylottoexpertV188HasColumn($cols, 'date_saved')) {
                $savedWhere = ' WHERE (s.' . $db->quoteName('date_saved') . ' >= DATE_SUB(NOW(), INTERVAL 180 DAY) OR ' . $unscoredCond . ')';
            }
            $db->setQuery('SELECT ' . $pendingExpr . ' AS pending_rows, ' . $waitExpr . ' AS waiting_draw, ' . $pastDueExpr . ' AS past_due, ' . $pastDueWaitingExpr . ' AS past_due_waiting_official, ' . $pastDueReviewExpr . ' AS past_due_review, ' . $futurePendingExpr . ' AS future_pending, ' . $missingTargetExpr . ' AS missing_target, ' . $dateSavedExpr . ' AS latest_saved, ' . $scoredAtExpr . ' AS latest_scored FROM ' . $db->quoteName('#__user_saved_numbers', 's') . $savedWhere);
            $r = (array)$db->loadAssoc();
            $out['pending'] = (int)($r['pending_rows'] ?? 0);
            $out['waiting_draw'] = (int)($r['waiting_draw'] ?? 0);
            $out['past_due'] = (int)($r['past_due'] ?? 0);
            $out['past_due_waiting_official'] = (int)($r['past_due_waiting_official'] ?? 0);
            $out['past_due_review'] = (int)($r['past_due_review'] ?? 0);
            $out['future_pending'] = (int)($r['future_pending'] ?? 0);
            $out['missing_target'] = (int)($r['missing_target'] ?? 0);
            $out['latest_saved'] = (string)($r['latest_saved'] ?? '');
            $out['latest_scored'] = (string)($r['latest_scored'] ?? '');
            if (mylottoexpertV188HasColumn($cols, 'hive_cron_wait_reason')) {
                $db->setQuery('SELECT COALESCE(NULLIF(TRIM(s.' . $db->quoteName('hive_cron_wait_reason') . '), ' . $db->quote('') . '), ' . $db->quote('blank') . ') AS reason, COUNT(*) AS rows_found FROM ' . $db->quoteName('#__user_saved_numbers', 's') . $savedWhere . ($savedWhere === '' ? ' WHERE ' : ' AND ') . $unscoredCond . ' GROUP BY reason ORDER BY rows_found DESC LIMIT 8');
                $out['wait_reasons'] = (array)$db->loadAssocList();
            }
            if (mylottoexpertV188HasColumn($cols, 'evaluation_status')) {
                $db->setQuery('SELECT COALESCE(NULLIF(TRIM(s.' . $db->quoteName('evaluation_status') . '), ' . $db->quote('') . '), ' . $db->quote('blank') . ') AS status, COUNT(*) AS rows_found FROM ' . $db->quoteName('#__user_saved_numbers', 's') . $savedWhere . ($savedWhere === '' ? ' WHERE ' : ' AND ') . $unscoredCond . ' GROUP BY status ORDER BY rows_found DESC LIMIT 8');
                $out['statuses'] = (array)$db->loadAssocList();
            }
        } catch (\Throwable $e) { $out['message'] = 'Scoring health check failed: ' . $e->getMessage(); }
        return $out;
    }
}

if (!function_exists('mylottoexpertV84AdminScoringBacklogSanitizer')) {
    function mylottoexpertV84AdminScoringBacklogSanitizer($db, $action = 'preview', $limit = 10)
    {
        $limit = max(1, min(100, (int)$limit));
        $out = array('available'=>false,'action'=>$action,'limit'=>$limit,'updated'=>0,'counts'=>array(),'samples'=>array(),'message'=>'');
        try {
            if (!function_exists('mylottoexpertV188TableExists') || !mylottoexpertV188TableExists($db, 'user_saved_numbers')) {
                $out['message'] = 'Saved prediction table is not available.';
                return $out;
            }
            $cols = mylottoexpertV188Columns($db, 'user_saved_numbers');
            if (!mylottoexpertV188HasColumn($cols, 'id') || !mylottoexpertV188HasColumn($cols, 'evaluation_status')) {
                $out['message'] = 'Required saved prediction columns are missing.';
                return $out;
            }
            $out['available'] = true;

            $statusExpr = 'LOWER(TRIM(COALESCE(s.' . $db->quoteName('evaluation_status') . ',' . $db->quote('pending') . ')))';
            $terminal = array('scored','evaluated','checked','completed','archived','retired','deleted','discarded','cancelled','canceled','void','not_scoreable','stale_cancelled','legacy_missing_target');
            $terminalSql = array();
            foreach ($terminal as $st) { $terminalSql[] = $db->quote($st); }
            $unscoredCond = $statusExpr . ' NOT IN (' . implode(',', $terminalSql) . ')';

            $targetParts = array();
            foreach (array('target_draw_date','actual_draw_date','next_draw_date') as $c) {
                if (mylottoexpertV188HasColumn($cols, $c)) {
                    $targetParts[] = 'NULLIF(NULLIF(NULLIF(s.' . $db->quoteName($c) . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ')';
                }
            }
            $targetExpr = !empty($targetParts) ? 'COALESCE(' . implode(',', $targetParts) . ')' : 'NULL';
            $targetMissingCond = !empty($targetParts) ? '(' . $targetExpr . ' IS NULL OR ' . $targetExpr . ' = ' . $db->quote('') . ')' : '1=1';
            $targetPastCond = !empty($targetParts) ? '(NOT (' . $targetMissingCond . ') AND DATE(' . $targetExpr . ') < CURDATE())' : '0=1';

            $waitExpr = mylottoexpertV188HasColumn($cols, 'hive_cron_wait_reason') ? 'LOWER(TRIM(COALESCE(s.' . $db->quoteName('hive_cron_wait_reason') . ',' . $db->quote('') . ')))' : $db->quote('');
            $officialMissingCond = $waitExpr . ' = ' . $db->quote('official_draw_not_loaded');

            $ageParts = array();
            foreach (array('date_saved','generated_at','created_at') as $c) {
                if (mylottoexpertV188HasColumn($cols, $c)) {
                    $ageParts[] = 'NULLIF(NULLIF(NULLIF(s.' . $db->quoteName($c) . ', ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('0000-00-00') . '), ' . $db->quote('') . ')';
                }
            }
            $ageExpr = !empty($ageParts) ? 'COALESCE(' . implode(',', $ageParts) . ')' : 'NULL';
            $oldEnoughCond = !empty($ageParts) ? '(' . $ageExpr . ' IS NOT NULL AND ' . $ageExpr . ' < DATE_SUB(NOW(), INTERVAL 30 DAY))' : '0=1';
            $veryOldCond = !empty($ageParts) ? '(' . $ageExpr . ' IS NOT NULL AND ' . $ageExpr . ' < DATE_SUB(NOW(), INTERVAL 180 DAY))' : '0=1';

            $missingTargetStaleCond = '(' . $unscoredCond . ' AND ' . $targetMissingCond . ' AND ' . $oldEnoughCond . ')';
            $officialMissingStaleCond = '(' . $unscoredCond . ' AND ' . $targetPastCond . ' AND ' . $officialMissingCond . ' AND ' . $veryOldCond . ')';
            $pastReviewCond = '(' . $unscoredCond . ' AND ' . $targetPastCond . ' AND NOT (' . $officialMissingCond . '))';

            $blankTargetGameCond = '0=1';
            if (mylottoexpertV188HasColumn($cols, 'target_game_id') && mylottoexpertV188HasColumn($cols, 'game_id')) {
                $blankTargetGameCond = '(' . $unscoredCond . ' AND NULLIF(TRIM(COALESCE(s.' . $db->quoteName('target_game_id') . ',' . $db->quote('') . ')), ' . $db->quote('') . ') IS NULL AND NULLIF(TRIM(COALESCE(s.' . $db->quoteName('game_id') . ',' . $db->quote('') . ')), ' . $db->quote('') . ') IS NOT NULL)';
            }
            $blankTargetDrawCond = '0=1';
            if (mylottoexpertV188HasColumn($cols, 'target_draw_date') && mylottoexpertV188HasColumn($cols, 'next_draw_date')) {
                $blankTargetDrawCond = '(' . $unscoredCond . ' AND NULLIF(NULLIF(NULLIF(s.' . $db->quoteName('target_draw_date') . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ') IS NULL AND NULLIF(NULLIF(NULLIF(s.' . $db->quoteName('next_draw_date') . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ') IS NOT NULL)';
            }
            $safeRepairCond = '(' . $blankTargetGameCond . ' OR ' . $blankTargetDrawCond . ')';

            $db->setQuery('SELECT '
                . 'SUM(CASE WHEN ' . $missingTargetStaleCond . ' THEN 1 ELSE 0 END) AS stale_missing_target, '
                . 'SUM(CASE WHEN ' . $officialMissingStaleCond . ' THEN 1 ELSE 0 END) AS stale_official_missing, '
                . 'SUM(CASE WHEN ' . $pastReviewCond . ' THEN 1 ELSE 0 END) AS past_target_review, '
                . 'SUM(CASE WHEN ' . $blankTargetGameCond . ' THEN 1 ELSE 0 END) AS repair_target_game_id, '
                . 'SUM(CASE WHEN ' . $blankTargetDrawCond . ' THEN 1 ELSE 0 END) AS repair_target_draw_date '
                . 'FROM ' . $db->quoteName('#__user_saved_numbers', 's'));
            $counts = (array)$db->loadAssoc();
            foreach ($counts as $k => $v) { $out['counts'][$k] = (int)$v; }

            $sampleSelect = array('s.' . $db->quoteName('id') . ' AS id');
            foreach (array('user_id','lottery_id','game_id','target_game_id','target_draw_date','next_draw_date','actual_draw_date','evaluation_status','hive_cron_wait_reason','date_saved','generated_at','source','analysis_method_key') as $c) {
                if (mylottoexpertV188HasColumn($cols, $c)) { $sampleSelect[] = 's.' . $db->quoteName($c) . ' AS ' . $db->quoteName($c); }
            }

            $sampleWhere = $missingTargetStaleCond;
            if ($action === 'preview_repair' || $action === 'repair_safe_identity') { $sampleWhere = $safeRepairCond; }
            if ($action === 'archive_official_missing') { $sampleWhere = $officialMissingStaleCond; }
            if ($action === 'preview_review') { $sampleWhere = $pastReviewCond; }
            $db->setQuery('SELECT ' . implode(',', $sampleSelect) . ' FROM ' . $db->quoteName('#__user_saved_numbers', 's') . ' WHERE ' . $sampleWhere . ' ORDER BY s.' . $db->quoteName('id') . ' ASC LIMIT ' . (int)$limit);
            $out['samples'] = (array)$db->loadAssocList();

            if ($action === 'repair_safe_identity') {
                $ids = array();
                foreach ((array)$out['samples'] as $row) { $id = (int)($row['id'] ?? 0); if ($id > 0) { $ids[] = $id; } }
                if (empty($ids)) { $out['message'] = 'No safely repairable rows were found for this chunk.'; return $out; }
                $updated = 0;
                if (mylottoexpertV188HasColumn($cols, 'target_game_id') && mylottoexpertV188HasColumn($cols, 'game_id')) {
                    $q = 'UPDATE ' . $db->quoteName('#__user_saved_numbers')
                        . ' SET ' . $db->quoteName('target_game_id') . ' = ' . $db->quoteName('game_id')
                        . ' WHERE ' . $db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ids)) . ')'
                        . ' AND NULLIF(TRIM(COALESCE(' . $db->quoteName('target_game_id') . ', ' . $db->quote('') . ')), ' . $db->quote('') . ') IS NULL'
                        . ' AND NULLIF(TRIM(COALESCE(' . $db->quoteName('game_id') . ', ' . $db->quote('') . ')), ' . $db->quote('') . ') IS NOT NULL'
                        . ' AND LOWER(TRIM(COALESCE(' . $db->quoteName('evaluation_status') . ',' . $db->quote('pending') . '))) NOT IN (' . implode(',', $terminalSql) . ')';
                    $db->setQuery($q);
                    $db->execute();
                    $updated += method_exists($db, 'getAffectedRows') ? (int)$db->getAffectedRows() : 0;
                }
                if (mylottoexpertV188HasColumn($cols, 'target_draw_date') && mylottoexpertV188HasColumn($cols, 'next_draw_date')) {
                    $q = 'UPDATE ' . $db->quoteName('#__user_saved_numbers')
                        . ' SET ' . $db->quoteName('target_draw_date') . ' = ' . $db->quoteName('next_draw_date')
                        . ' WHERE ' . $db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ids)) . ')'
                        . ' AND NULLIF(NULLIF(NULLIF(' . $db->quoteName('target_draw_date') . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ') IS NULL'
                        . ' AND NULLIF(NULLIF(NULLIF(' . $db->quoteName('next_draw_date') . ', ' . $db->quote('0000-00-00') . '), ' . $db->quote('0000-00-00 00:00:00') . '), ' . $db->quote('') . ') IS NOT NULL'
                        . ' AND LOWER(TRIM(COALESCE(' . $db->quoteName('evaluation_status') . ',' . $db->quote('pending') . '))) NOT IN (' . implode(',', $terminalSql) . ')';
                    $db->setQuery($q);
                    $db->execute();
                    $updated += method_exists($db, 'getAffectedRows') ? (int)$db->getAffectedRows() : 0;
                }
                $out['updated'] = $updated;
                $out['message'] = 'Repaired ' . (int)$updated . ' saved prediction field value(s). No rows were scored, deleted, or archived.';
            } elseif ($action === 'archive_missing_target' || $action === 'archive_official_missing') {
                $ids = array(); foreach ((array)$out['samples'] as $row) { $id = (int)($row['id'] ?? 0); if ($id > 0) { $ids[] = $id; } }
                if (empty($ids)) { $out['message'] = 'No matching rows were found for this cleanup chunk.'; return $out; }
                $sets = array($db->quoteName('evaluation_status') . ' = ' . $db->quote('archived'));
                if (mylottoexpertV188HasColumn($cols, 'hive_cron_wait_reason')) {
                    $sets[] = $db->quoteName('hive_cron_wait_reason') . ' = ' . $db->quote($action === 'archive_missing_target' ? 'archived_legacy_missing_target_date' : 'archived_stale_official_draw_missing');
                }
                $q = $db->getQuery(true)
                    ->update($db->quoteName('#__user_saved_numbers'))
                    ->set($sets)
                    ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ids)) . ')')
                    ->where($db->quoteName('evaluation_status') . ' NOT IN (' . implode(',', $terminalSql) . ')');
                $db->setQuery($q);
                $db->execute();
                $out['updated'] = method_exists($db, 'getAffectedRows') ? (int)$db->getAffectedRows() : count($ids);
                $out['message'] = 'Archived ' . (int)$out['updated'] . ' stale/non-scoreable saved prediction row(s).';
            } elseif ($action === 'preview' || $action === 'preview_repair' || $action === 'preview_review') {
                $out['message'] = 'Preview only. No rows were changed.';
            }
        } catch (\Throwable $e) {
            $out['message'] = 'Scoring backlog sanitizer failed: ' . $e->getMessage();
        }
        return $out;
    }
}

if (!function_exists('mylottoexpertV188AdminLockStatus')) {
    function mylottoexpertV188AdminLockStatus()
    {
        $path = rtrim((string)JPATH_ROOT, '/') . '/tmp/mle_admin_operations.lock';
        $out = array('exists'=>false,'age'=>0,'content'=>'','path'=>$path);
        try {
            if (@is_file($path)) {
                $out['exists'] = true;
                $out['age'] = max(0, time() - (int)@filemtime($path));
                $out['content'] = trim((string)@file_get_contents($path));
            }
        } catch (\Throwable $e) { }
        return $out;
    }
}

