                  <button type="submit" class="mle-v38-primary-action">Repair safe missing fields</button>
                </form>
                <form method="post" style="display:flex;gap:.55rem;align-items:center;flex-wrap:wrap;margin:0;">
                  <input type="hidden" name="<?php echo htmlspecialchars(\Joomla\CMS\Session\Session::getFormToken(), ENT_QUOTES, 'UTF-8'); ?>" value="1">
                  <input type="hidden" name="mle_admin_op" value="scoring_backlog_archive_missing_target">
