        echo function_exists('mylottoexpertV150RenderAdminHiveResearchConsole') ? mylottoexpertV150RenderAdminHiveResearchConsole($db, $user) : '';
        $__mleV87LiteGlanceLimit = 1000; // Batch Coverage Glance shows all lotteries; full lottery cards remain deferred.
        echo function_exists('mylottoexpertV182RenderAdminBatchGlanceTable') ? mylottoexpertV182RenderAdminBatchGlanceTable($db, $__mleV87LiteGlanceLimit, false) : '';
        return ob_get_clean();
    }

    $__mleV109SeedSummary = array('attempted'=>0, 'created'=>0, 'existing'=>0, 'skipped'=>0, 'items'=>array(), 'manual'=>true, 'not_run'=>'Open Admin Operations Center and click Run Waiting Predictions Seed Chunk.');
    $__mleV131IntakeSummary = array('scanned'=>0,'skai_like'=>0,'groups'=>0,'created_queue'=>0,'created_assignment'=>0,'updated_assignment'=>0,'skipped'=>0,'manual'=>true,'not_run'=>'Open Admin Operations Center and click Run Learning Ingest Chunk.');
    $__mleV135ContractBackfill = array('updated'=>0,'scanned'=>0,'manual'=>true,'not_run'=>'Open Admin Operations Center and click Run Contract Backfill Chunk.');
    $__mleV99FeedbackSummary = array('checked'=>0,'updated'=>0,'manual'=>true,'not_run'=>'Open Admin Operations Center and click Run Reconciliation Chunk.');

    $__mleAdminApp = \Joomla\CMS\Factory::getApplication();
    $__mleAdminInput = $__mleAdminApp->input;
    $__mleAdminIsPost = (strtoupper((string)$__mleAdminInput->getMethod()) === 'POST');
    $__mleAdminToken = \Joomla\CMS\Session\Session::getFormToken();
    $__mleAdminTokenOk = (!$__mleAdminIsPost) || ((int)$__mleAdminInput->post->getInt($__mleAdminToken, 0) === 1);
    $__mleAdminOp = $__mleAdminIsPost ? strtolower(trim((string)$__mleAdminInput->post->getCmd('mle_admin_op', ''))) : '';
    $__mleAdminLoadSitewideHive = ((int)$__mleAdminInput->getInt('mle_sitewide_hive', 0) === 1);
    $__mleAdminOpMessage = '';
    $__mleAdminOpKind = '';

    $__mleAdminClamp = function($value, $default, $min, $max) {
        $value = (int)$value;
        if ($value <= 0) { $value = (int)$default; }
        return max((int)$min, min((int)$max, $value));
    };
    $__mleAdminRunWithLock = function($opLabel, $callback) use (&$__mleAdminOpMessage, &$__mleAdminOpKind) {
        $lockPath = rtrim((string)JPATH_ROOT, '/') . '/tmp/mle_admin_operations.lock';
        $fh = @fopen($lockPath, 'c');
        if (!$fh) {
            $__mleAdminOpKind = 'warn';
            $__mleAdminOpMessage = 'Could not open the admin operation lock file. Nothing was run.';
            return null;
        }
        if (!@flock($fh, LOCK_EX | LOCK_NB)) {
            $__mleAdminOpKind = 'warn';
            $__mleAdminOpMessage = 'Another admin operation appears to be running. Wait a minute and try again.';
            @fclose($fh);
            return null;
        }
        try {
            @ftruncate($fh, 0);
            @fwrite($fh, $opLabel . ' | ' . date('Y-m-d H:i:s'));
            $result = $callback();
            $__mleAdminOpKind = 'ok';
            $__mleAdminOpMessage = $opLabel . ' completed.';
            return $result;
        } catch (\Throwable $e) {
            $__mleAdminOpKind = 'error';
            $__mleAdminOpMessage = $opLabel . ' failed: ' . $e->getMessage();
            return null;
        } finally {
            @flock($fh, LOCK_UN);
            @fclose($fh);
        }
    };

    if ($__mleAdminOp !== '') {
        if (!$__mleAdminTokenOk) {
            $__mleAdminOpKind = 'error';
            $__mleAdminOpMessage = 'Security token check failed. No admin operation was run.';
        } elseif ($__mleAdminOp === 'seed_queue') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 12), 12, 1, 100);
            $__result = $__mleAdminRunWithLock('Queue Seed Chunk', function() use ($db, $user, $__limit) {
                return function_exists('mylottoexpertV109SeedHiveResearchQueueFromSharedLearning') ? mylottoexpertV109SeedHiveResearchQueueFromSharedLearning($db, (int)($user->id ?? 0), $__limit) : array('error'=>'function_missing');
            });
            if (is_array($__result)) { $__mleV109SeedSummary = $__result; }
        } elseif ($__mleAdminOp === 'learning_ingest') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 25), 25, 25, 100);
            $__result = $__mleAdminRunWithLock('Learning Ingest Chunk', function() use ($db, $__limit) {
                return function_exists('mylottoexpertV131IngestRecentSkaiSavedRowsIntoHive') ? mylottoexpertV131IngestRecentSkaiSavedRowsIntoHive($db, $__limit) : array('error'=>'function_missing');
            });
            if (is_array($__result)) { $__mleV131IntakeSummary = $__result; }
        } elseif ($__mleAdminOp === 'contract_backfill') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 50), 50, 50, 100);
            $__result = $__mleAdminRunWithLock('Contract Backfill Chunk', function() use ($db, $__limit) {
                return function_exists('mylottoexpertV135BackfillSkaiContractMissing') ? mylottoexpertV135BackfillSkaiContractMissing($db, $__limit) : array('error'=>'function_missing');
            });
            if (is_array($__result)) { $__mleV135ContractBackfill = $__result; }
        } elseif ($__mleAdminOp === 'reconcile_feedback') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 25), 25, 10, 100);
            $__result = $__mleAdminRunWithLock('Reconciliation Chunk', function() use ($db, $__limit) {
                return function_exists('mylottoexpertV99ReconcileResearchQueueFeedback') ? mylottoexpertV99ReconcileResearchQueueFeedback($db, $__limit) : array('error'=>'function_missing');
            });
            if (is_array($__result)) { $__mleV99FeedbackSummary = $__result; }
        } elseif ($__mleAdminOp === 'scoring_backlog_repair_safe_identity') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 25), 25, 1, 100);
            $__result = $__mleAdminRunWithLock('Scoring Backlog Safe Repair', function() use ($db, $__limit) {
                return function_exists('mylottoexpertV84AdminScoringBacklogSanitizer') ? mylottoexpertV84AdminScoringBacklogSanitizer($db, 'repair_safe_identity', $__limit) : array('message'=>'function_missing');
            });
            if (is_array($__result) && !empty($__result['message'])) {
                $__mleAdminOpMessage = (string)$__result['message'];
            }
        } elseif ($__mleAdminOp === 'scoring_backlog_archive_missing_target') {
            $__limit = $__mleAdminClamp($__mleAdminInput->post->getInt('mle_admin_limit', 25), 25, 1, 100);
            $__result = $__mleAdminRunWithLock('Scoring Backlog Missing-Target Archive', function() use ($db, $__limit) {
                return function_exists('mylottoexpertV84AdminScoringBacklogSanitizer') ? mylottoexpertV84AdminScoringBacklogSanitizer($db, 'archive_missing_target', $__limit) : array('message'=>'function_missing');
            });
            if (is_array($__result) && !empty($__result['message'])) {
                $__mleAdminOpMessage = (string)$__result['message'];
            }
        } else {
            $__mleAdminOpKind = 'warn';
            $__mleAdminOpMessage = 'Unknown admin operation. Nothing was run.';
        }
    }

    $displayLimit = function_exists('mylottoexpertV133AdminRowsLimit') ? mylottoexpertV133AdminRowsLimit(20) : 20;
    $data = mylottoexpertV100LoadHiveDashboardData($db, $displayLimit);
    $message = htmlspecialchars((string)($data['message'] ?? ''), ENT_QUOTES, 'UTF-8');
    $queueTotal = (int)($data['queue_total'] ?? 0);
    $assignmentTotal = (int)($data['assignment_total'] ?? 0);
    $queueStatus = mylottoexpertV100RenderStatusPills((array)($data['queue_status_counts'] ?? array()));
