    $learningEvents = (int)($siteTotals['learning_events_rows'] ?? 0);
    $scoredEvidence = (int)($siteTotals['scored_evidence'] ?? 0);

    $captureState = ($allSaved > 0 ? 'ok' : 'idle');
    $intakeState = (($queueTotal + $assignmentTotal + $skaiRows) > 0 ? 'ok' : 'wait');
    $scoreState = ($dueToScore > 0 ? 'warn' : ($unscoredRows > 0 || $futureDraws > 0 ? 'wait' : 'ok'));
    $learnState = ($learningEvents > 0 || $scoredEvidence > 0 ? 'ok' : 'wait');
    $contractReady = 0; $contractMissing = 0; $contractTracking = 0;
    foreach ((array)($contractHealth['counts'] ?? array()) as $c) {
        $st = (string)($c['status'] ?? '');
        if ($st === 'hive_ready') { $contractReady += (int)($c['total'] ?? 0); }
        elseif ($st === 'tracking_ready') { $contractTracking += (int)($c['total'] ?? 0); }
        elseif ($st === 'missing_required_fields') { $contractMissing += (int)($c['total'] ?? 0); }
    }
    $contractState = (!empty($contractHealth['available']) ? ($contractMissing > 0 ? 'warn' : 'ok') : 'wait');

