    echo function_exists('mylottoexpertV133RenderAdminCommandCenterStyles') ? mylottoexpertV133RenderAdminCommandCenterStyles() : '';
    $__mleV92AdminActive = 'creator';
    if ((int)$app->input->getInt('mle_batch_recovery', 0) === 1) { $__mleV92AdminActive = 'recovery'; }
