function mleAdvisoryComputeSettingsAdvisorFromRows(array $perfRows, array $savedById, $method) {
    $noAdvice = array('has_advice'=>false,'reason'=>'Settings do not show a clear pattern yet. Keep the current settings unchanged.','try_next'=>'','why'=>'','best_recipe_desc'=>'','keep_same_list'=>'');
    $method = mleAdvisorySourceToMethodKey($method);
    $scored = array();
    foreach ($perfRows as $row) {
        $m = (string)($row['__method_key'] ?? mleAdvisorySourceToMethodKey($row['source'] ?? ''));
        if ($m !== $method) { continue; }
        $sid = (int)($row['__saved_id'] ?? $row['run_id'] ?? 0);
        if ($sid <= 0 || empty($savedById[$sid])) { continue; }
        $settings = mylottoexpertResolveEffectiveSettings($savedById[$sid]);
        $top10 = (int)($row['top10_hits'] ?? 0); $top20 = (int)($row['top20_hits'] ?? 0); $rank = (float)($row['avg_winning_rank'] ?? 999); $quality = (float)($row['weighted_quality_score'] ?? 0);
        $score = ($quality > 0) ? ($quality * 10.0) : (($top10 * 3.0) + ($top20 * 1.5) - ($rank * 0.3));
        $scored[] = array('score'=>$score,'settings'=>$settings,'saved_id'=>$sid);
    }
    if (count($scored) < 3) { $noAdvice['reason'] = 'More completed saved runs are needed before changing settings.'; return $noAdvice; }
    usort($scored, function($a,$b){ return ($b['score'] > $a['score']) ? 1 : (($b['score'] < $a['score']) ? -1 : 0); });
    $total = count($scored); $cut = max(1, (int)floor($total * 0.35));
    $strong = array_slice($scored, 0, $cut); $weak = array_slice($scored, -$cut);
    $keys = array('skai_window_size','draws_analyzed','skai_blend_ai_pct','sampling_temperature','diversity_penalty','gap_scale','learning_rate','dropout_rate','hidden_layers','recency_decay','chain_len','burn_in','laplace_k','best_window','auto_tune');
    $bestKey=''; $old=''; $new=''; $bestDiff=0.0;
    $__optimizerDefs = function_exists('mleOptimizerSettingDefinitions') ? mleOptimizerSettingDefinitions() : array();
    foreach ($keys as $key) {
        $sv=array(); $wv=array();
        foreach ($strong as $r) { if (isset($r['settings'][$key]) && is_numeric($r['settings'][$key])) { $sv[]=(float)$r['settings'][$key]; } }
        foreach ($weak as $r) { if (isset($r['settings'][$key]) && is_numeric($r['settings'][$key])) { $wv[]=(float)$r['settings'][$key]; } }
        if (count($sv) < 1 || count($wv) < 1) { continue; }
        $sa = array_sum($sv)/count($sv); $wa = array_sum($wv)/count($wv); $diff=abs($sa-$wa);
        $__threshold = isset($__optimizerDefs[$key]['meaningful_diff']) ? (float)$__optimizerDefs[$key]['meaningful_diff'] : 1.0;
        if ($diff > $bestDiff && $diff >= $__threshold) { $bestDiff=$diff; $bestKey=$key; $old=round($wa,1); $new=round($sa,1); }
    }
    $bestRecipe = !empty($strong[0]['settings']) ? mleAdvisoryBuildBestRecipeDesc($strong[0]['settings'], $method) : '';
    if ($bestKey === '') { $noAdvice['best_recipe_desc'] = $bestRecipe; return $noAdvice; }
    $label = mleAdvisoryFormatSettingLabel($bestKey);
    $reason = 'Your stronger saved runs used a different ' . $label . '. Test this one change so LottoExpert can measure whether it improves consistency without changing everything else.';
    return array('has_advice'=>true,'setting'=>$bestKey,'setting_label'=>$label,'current_value'=>(string)$old,'suggested_value'=>(string)$new,'reason'=>$reason,'try_next'=>'Create one new settings run that changes only ' . $label . ' from ' . $old . ' to ' . $new . '.','why'=>$reason,'best_recipe_desc'=>$bestRecipe,'keep_same_list'=>'Keep the best method, mode, blend, and other settings the same for this test.','proof_level'=>mleAdvisoryGetProofLevelLabel(min($total,5),$total));
}

function mleAdvisoryComputeSettingsAdvisor($db, $userId, $lotteryId, $method = 'skai') {
    $active = mleAdvisoryBuildActiveSavedEvidence($db, $userId);
    $rows = isset($active[(int)$lotteryId]['rows']) ? $active[(int)$lotteryId]['rows'] : array();
    $savedById = array(); foreach ($rows as $r) { $savedById[(int)($r['id'] ?? 0)] = $r; }
    $perf = mleAdvisoryLoadMatchedPerformance($db, $userId, $lotteryId, $rows);
    return mleAdvisoryComputeSettingsAdvisorFromRows($perf, $savedById, $method);
}


function mleAdvisoryBuildBlendCoverageFromValues(array $values)
{
    $coverage = array(
        'total_values' => count($values),
        'distinct_values' => 0,
        'tested_min' => null,
        'tested_max' => null,
        'zone_counts' => array('low_edge'=>0,'low_middle'=>0,'center'=>0,'high_middle'=>0,'high_edge'=>0),
        'missing_zones' => array(),
        'has_low_edge' => false,
        'has_high_edge' => false,
        'has_center' => false,
        'full_coverage_met' => false,
        'coverage_label' => 'Full 0% to 100% blend exploration has not been proven yet.',
    );
    $distinct = array();
    $nums = array();
    foreach ($values as $value) {
        if (!is_numeric($value)) { continue; }
        $v = max(0.0, min(100.0, (float)$value));
        $nums[] = $v;
        $distinct[(string)((int)round($v))] = true;
        if ($v <= 20.0) { $coverage['zone_counts']['low_edge']++; }
        elseif ($v <= 40.0) { $coverage['zone_counts']['low_middle']++; }
        elseif ($v <= 60.0) { $coverage['zone_counts']['center']++; }
        elseif ($v <= 80.0) { $coverage['zone_counts']['high_middle']++; }
        else { $coverage['zone_counts']['high_edge']++; }
    }
    if (!empty($nums)) {
        $coverage['tested_min'] = (float)min($nums);
        $coverage['tested_max'] = (float)max($nums);
    }
    $coverage['distinct_values'] = count($distinct);
    $coverage['has_low_edge'] = ($coverage['tested_min'] !== null && $coverage['tested_min'] <= 10.0 && (int)$coverage['zone_counts']['low_edge'] > 0);
    $coverage['has_high_edge'] = ($coverage['tested_max'] !== null && $coverage['tested_max'] >= 90.0 && (int)$coverage['zone_counts']['high_edge'] > 0);
    $coverage['has_center'] = ((int)$coverage['zone_counts']['center'] > 0);
    foreach ($coverage['zone_counts'] as $zone => $count) {
        if ((int)$count <= 0) { $coverage['missing_zones'][] = $zone; }
    }
    $coverage['has_contract_lower'] = ((int)$coverage['zone_counts']['low_edge'] > 0 || (int)$coverage['zone_counts']['low_middle'] > 0);
    $coverage['has_contract_middle'] = ((int)$coverage['zone_counts']['center'] > 0);
    $coverage['has_contract_upper'] = ((int)$coverage['zone_counts']['high_middle'] > 0 || (int)$coverage['zone_counts']['high_edge'] > 0);
    $coverage['tested_span'] = ($coverage['tested_min'] !== null && $coverage['tested_max'] !== null) ? ((float)$coverage['tested_max'] - (float)$coverage['tested_min']) : 0.0;

    /*
     * V96 source-math correction: SKAI's regular 9-run contract tests the learned
     * lower/middle/upper blend corridor, often 35/50/65. Requiring literal 0% and
     * 100% evidence makes Precision Focus mathematically unreachable and conflicts
     * with the actual batch contract stored in saved settings. Keep the legacy
     * full_coverage_met key for downstream code, but make it mean complete coverage
     * of the tested SKAI blend corridor, not absolute 0-to-100 endpoints.
     */
    $coverage['contract_coverage_met'] = ($coverage['total_values'] >= 9
        && $coverage['distinct_values'] >= 3
        && !empty($coverage['has_contract_lower'])
        && !empty($coverage['has_contract_middle'])
        && !empty($coverage['has_contract_upper'])
        && (float)$coverage['tested_span'] >= 20.0);
    $coverage['absolute_0_to_100_coverage_met'] = ($coverage['total_values'] >= 9
        && $coverage['distinct_values'] >= 5
        && empty($coverage['missing_zones'])
        && !empty($coverage['has_low_edge'])
        && !empty($coverage['has_high_edge'])
        && !empty($coverage['has_center']));
    $coverage['full_coverage_met'] = !empty($coverage['contract_coverage_met']);
    if (!empty($coverage['full_coverage_met'])) {
        $coverage['coverage_label'] = 'Blend coverage has completed prediction history across the lower, middle, and upper points of the tested AI blend corridor.';
    } else {
        $coverage['coverage_label'] = 'LottoExpert needs completed prediction history across the lower, middle, and upper points of the tested AI blend corridor before narrowing.';
    }
    return $coverage;
}

function mleAdvisoryBuildHorizonCoverageFromValues(array $values)
{
    $coverage = array(
        'total_values' => count($values),
        'distinct_values' => 0,
        'tested_min' => null,
        'tested_max' => null,
        'zone_counts' => array('near'=>0,'short'=>0,'middle'=>0,'long'=>0,'full'=>0),
        'missing_zones' => array(),
        'has_25_edge' => false,
        'has_1000_edge' => false,
        'full_coverage_met' => false,
        'coverage_label' => 'Full 25 to 1,000 draw-window exploration has not been proven yet.',
    );
    $distinct = array();
    $nums = array();
    foreach ($values as $value) {
        if (!is_numeric($value)) { continue; }
        $v = max(25.0, min(1000.0, (float)$value));
        $nums[] = $v;
        $distinct[(string)((int)round($v))] = true;
        if ($v <= 50.0) { $coverage['zone_counts']['near']++; }
        elseif ($v <= 150.0) { $coverage['zone_counts']['short']++; }
        elseif ($v <= 300.0) { $coverage['zone_counts']['middle']++; }
        elseif ($v < 1000.0) { $coverage['zone_counts']['long']++; }
        else { $coverage['zone_counts']['full']++; }
    }
    if (!empty($nums)) {
        $coverage['tested_min'] = (float)min($nums);
        $coverage['tested_max'] = (float)max($nums);
    }
    $coverage['distinct_values'] = count($distinct);
    $coverage['has_25_edge'] = ($coverage['tested_min'] !== null && $coverage['tested_min'] <= 25.0);
    $coverage['has_1000_edge'] = ($coverage['tested_max'] !== null && $coverage['tested_max'] >= 1000.0);
    foreach ($coverage['zone_counts'] as $zone => $count) {
        if ((int)$count <= 0) { $coverage['missing_zones'][] = $zone; }
    }
    $coverage['tested_span'] = ($coverage['tested_min'] !== null && $coverage['tested_max'] !== null) ? ((float)$coverage['tested_max'] - (float)$coverage['tested_min']) : 0.0;
    $coverage['contract_coverage_met'] = ($coverage['total_values'] >= 9
        && $coverage['distinct_values'] >= 3
        && (float)$coverage['tested_span'] >= 20.0);
    $coverage['absolute_25_to_1000_coverage_met'] = ($coverage['total_values'] >= 9
        && $coverage['distinct_values'] >= 5
        && empty($coverage['missing_zones'])
        && !empty($coverage['has_25_edge'])
        && !empty($coverage['has_1000_edge']));
    $coverage['full_coverage_met'] = !empty($coverage['contract_coverage_met']);
    if (!empty($coverage['full_coverage_met'])) {
        $coverage['coverage_label'] = 'History-window coverage has completed prediction history across the tested AI lower/middle/upper window corridor.';
    } else {
        $coverage['coverage_label'] = 'LottoExpert needs completed prediction history across at least three distinct tested history-window values before narrowing.';
    }
    return $coverage;
}

function mleAdvisoryComputePrecisionLockData(array $perfRows, array $savedById, $method) {
    $method = mleAdvisorySourceToMethodKey($method);
    $scored = array();
    $ctrlLabel = 'Blend Setting';
    $methodRows = array();

    foreach ($perfRows as $row) {
        $m = (string)($row['__method_key'] ?? mleAdvisorySourceToMethodKey($row['source'] ?? ''));
        if ($m !== $method) { continue; }
        $sid = (int)($row['__saved_id'] ?? $row['run_id'] ?? 0);
        if ($sid <= 0 || empty($savedById[$sid])) { continue; }
        $settings = mylottoexpertResolveEffectiveSettings($savedById[$sid]);

        $pct = null;
        foreach (array('signal_blend_ai_pct','core_ai_ai_pct','skai_blend_ai_pct','blend_ai_pct','ai_pct','blend_percent','blend_pct','ai_blend_pct') as $k) {
            if (isset($settings[$k]) && is_numeric($settings[$k])) {
                $pct = (float)$settings[$k];
                $ctrlLabel = 'Blend Setting';
                break;
            }
        }
        /*
         * V95 source-math correction: Settings Precision Range is blend-percent math.
         * Do not coerce history-window values such as 70, 130, 500, or 1000 into a
         * fake 0-100 blend percentage. History-window evidence is handled by
         * mleAdvisoryComputeHorizonWindowLockData().
         */
        if ($pct === null) { continue; }

        $methodRows[] = $row;
        $edge = mleAdvisoryCalculateRandomEdgeForRow($row);
        $top10 = (int)($row['top10_hits'] ?? 0);
        $top20 = (int)($row['top20_hits'] ?? 0);
        $rank = (float)($row['avg_winning_rank'] ?? 999);
        $quality = (float)($row['weighted_quality_score'] ?? 0);
        $avgLift = (float)($edge['avg_rank_lift'] ?? 0.0);
        $penLift = (float)($edge['penalized_rank_lift'] ?? 0.0);
        $top10Lift = (float)($edge['top10_lift'] ?? 0.0);
        $top20Lift = (float)($edge['top20_lift'] ?? 0.0);

        $score = ($avgLift * 8.0)
               + ($penLift * 10.0)
               + ($top20Lift * 2.0)
               + ($top10Lift * 1.5)
               + ($quality * 4.0)
               + ($top10 * 0.8)
               + ($top20 * 0.35)
               - min(8.0, max(0.0, $rank) * 0.04);

        $scored[] = array(
            'pct' => $pct,
            'score' => $score,
            'avg_rank_lift' => $avgLift,
            'penalized_rank_lift' => $penLift,
            'random_edge' => $edge,
            'draw_date' => function_exists('mleAdvisoryCompletedDrawCycleDate') ? mleAdvisoryCompletedDrawCycleDate($row, $savedById[$sid]) : (string)($row['draw_date'] ?? $savedById[$sid]['target_draw_date'] ?? ''),
        );
    }

    $total = is_array($scored) ? count($scored) : 0;
    $edgeMetrics = mleAdvisoryAggregateRandomEdge($methodRows, $method);
    $noData = array(
        'stage'        => 'broad_testing',
        'stage_label'  => 'Broad testing',
        'has_range'    => false,
        'range_min'    => 0.0,
        'range_max'    => 100.0,
        'sweet_min'    => null,
        'sweet_max'    => null,
        'run_count'    => $total,
        'control_label'=> $ctrlLabel,
        'summary'      => 'Not enough saved scored runs yet for this lottery. Keep saving runs for this lottery before narrowing the range further.',
        'stage_plain'  => 'This lottery is still in broad testing.',
        'evidence_line'=> 'There are not enough saved scored runs yet to compare a narrowed range against the random baseline.',
        'next_step'    => 'Keep saving scored runs for this lottery before narrowing the range further.',
        'random_edge'  => $edgeMetrics,
        'range_width'  => 100.0,
        'blend_coverage' => mleAdvisoryBuildBlendCoverageFromValues(array()),
        'blend_full_coverage_met' => false,
        'tested_min' => null,
        'tested_max' => null,
        'distinct_values' => 0,
    );
    if ($total < 5) { return $noData; }

    $blendCoverage = mleAdvisoryBuildBlendCoverageFromValues(array_column($scored, 'pct'));
    if (empty($blendCoverage['full_coverage_met'])) {
        $noData['run_count'] = $total;
        $noData['summary'] = 'This lottery has scored runs, but LottoExpert has not yet proven enough lower/middle/upper blend coverage inside the tested AI blend corridor before narrowing.';
        $noData['stage_plain'] = 'This lottery is still in tested-corridor blend discovery.';
        $noData['evidence_line'] = $total . ' scored runs found. ' . (string)$blendCoverage['coverage_label'];
        $noData['next_step'] = 'Run or complete a controlled 9-run AI blend batch that scores lower, middle, and upper blend points inside the tested corridor.';
        $noData['blend_coverage'] = $blendCoverage;
        $noData['blend_full_coverage_met'] = false;
        $noData['tested_min'] = $blendCoverage['tested_min'];
        $noData['tested_max'] = $blendCoverage['tested_max'];
        $noData['distinct_values'] = (int)$blendCoverage['distinct_values'];
        return $noData;
    }

    usort($scored, function($a, $b) { return ($b['score'] > $a['score']) ? 1 : (($b['score'] < $a['score']) ? -1 : 0); });

    $cutStrong = max(1, (int)ceil($total * 0.40));
    $strongRuns = array_slice($scored, 0, $cutStrong);
    $strongPcts = array();
    foreach ($strongRuns as $r) { $strongPcts[] = $r['pct']; }
    $rangeMin = min($strongPcts);
    $rangeMax = max($strongPcts);

    $sweetMin = null;
    $sweetMax = null;
    $cutSweet = max(1, (int)ceil($total * 0.20));
    if ($cutSweet >= 2) {
        $sweetRuns = array_slice($scored, 0, $cutSweet);
        $sweetPcts = array();
        foreach ($sweetRuns as $r) { $sweetPcts[] = $r['pct']; }
        $sweetMin = (float)min($sweetPcts);
        $sweetMax = (float)max($sweetPcts);
        if (!($sweetMin >= $rangeMin && $sweetMax <= $rangeMax && ($sweetMax - $sweetMin) < ($rangeMax - $rangeMin))) {
            $sweetMin = null;
            $sweetMax = null;
        }
    }

    $rangeWidth = $rangeMax - $rangeMin;
    $avgLift = (float)($edgeMetrics['avg_rank_lift'] ?? 0.0);
    $penLift = (float)($edgeMetrics['penalized_rank_lift'] ?? 0.0);
    $repeatCount = (int)($edgeMetrics['repeat_count'] ?? 0);
    $validationDraws = (int)($edgeMetrics['validation_draws'] ?? 0);
    $hasBasicEdge = ($avgLift >= 1.05 && $penLift >= 1.00);
    $hasGoodEdge  = ($avgLift >= 1.15 && $penLift >= 1.05);
    $hasEliteEdge = ($avgLift >= 1.20 && $penLift >= 1.10);

    if ($total >= 120 && $validationDraws >= 20 && $repeatCount >= 5 && $hasEliteEdge && $sweetMin !== null && ($sweetMax - $sweetMin) <= 15.0) {
        $stage = 'precision_focus_range';
        $stageLabel = 'Settings Precision Range';
    } elseif ($total >= 75 && $validationDraws >= 12 && $repeatCount >= 4 && $hasGoodEdge && $rangeWidth <= 20.0) {
        $stage = 'validated_focus_range';
        $stageLabel = 'Validated Focus Range';
    } elseif ($total >= 45 && $validationDraws >= 6 && $repeatCount >= 3 && $hasGoodEdge && $rangeWidth <= 30.0) {
        $stage = 'narrowing_signal';
        $stageLabel = 'Narrowing Signal';
    } elseif ($total >= 27 && $validationDraws >= 4 && $repeatCount >= 2 && $hasBasicEdge && $rangeWidth <= 45.0) {
        $stage = 'exploratory_batch';
        $stageLabel = 'Exploratory Precision Settings Test';
    } elseif ($total >= 18 && $validationDraws >= 3 && $avgLift >= 1.00 && $rangeWidth <= 60.0) {
        $stage = 'early_direction';
        $stageLabel = 'Early Direction';
    } else {
        $stage = 'broad_testing';
        $stageLabel = 'Broad testing';
    }

    $rMin = (int)round($rangeMin);
    $rMax = (int)round($rangeMax);
    $edgeText = 'Average rank lift ' . number_format($avgLift, 2) . 'x; penalized lift ' . number_format($penLift, 2) . 'x versus random expectation.';

    if ($stage === 'broad_testing') {
        $summary = 'This lottery is still building prediction history. LottoExpert is comparing scored runs against a random baseline before narrowing too tightly.';
        $stagePlain = 'This lottery is still in broad testing.';
        $evidenceLine = $total . ' scored runs are being measured. ' . $edgeText;
        $nextStep = 'Keep saving scored runs and avoid changing everything at once.';
    } elseif ($stage === 'early_direction') {
        $summary = 'A possible signal is starting to appear for this lottery between ' . $rMin . ' and ' . $rMax . '. Keep tracking it before relying on it heavily.';
        $stagePlain = 'A possible strategy signal is forming.';
        $evidenceLine = $total . ' scored runs show an early range between ' . $rMin . ' and ' . $rMax . '. ' . $edgeText;
        $nextStep = 'Keep this range on watch and save more scored runs for this lottery.';
    } elseif ($stage === 'exploratory_batch') {
        $summary = 'This range is ready for an exploratory Precision Focus batch for this lottery. It is showing repeated prediction history and early lift over random expectation.';
        $stagePlain = 'An exploratory Precision Focus batch is ready.';
        $evidenceLine = $total . ' scored runs and ' . $repeatCount . ' positive-edge runs point to ' . $rMin . ' to ' . $rMax . '. ' . $edgeText;
        $nextStep = 'Run one controlled 9-run Precision Focus batch and keep the other settings steady.';
    } elseif ($stage === 'narrowing_signal') {
        $summary = 'Recent completed draws are starting to favor a tighter setting range for this lottery. LottoExpert recommends testing inside this range instead of making large changes.';
        $stagePlain = 'This lottery has a narrowing signal.';
        $evidenceLine = $total . ' scored runs point to the ' . $ctrlLabel . ' range ' . $rMin . ' to ' . $rMax . '. ' . $edgeText;
        $nextStep = 'Keep the next test inside this range and compare only one change after the next draw.';
    } elseif ($stage === 'validated_focus_range') {
        $summary = 'This range has repeated support across completed draws and positive lift versus random expectation. Use it as the current disciplined focus area.';
        $stagePlain = 'This lottery has a validated focus range.';
        $evidenceLine = $total . ' scored runs with ' . $validationDraws . ' completed draw dates support ' . $rMin . ' to ' . $rMax . '. ' . $edgeText;
        $nextStep = 'Stay inside this focus range and continue validating after future completed draws.';
    } else {
        $sMin = (int)round($sweetMin);
        $sMax = (int)round($sweetMax);
        $summary = 'This is LottoExpert\'s strongest current focus range for this lottery: ' . $sMin . ' to ' . $sMax . '. It is a disciplined test range, not a guarantee.';
        $stagePlain = 'This lottery has a Settings Precision Range.';
        $evidenceLine = $total . ' scored runs repeatedly point to the tighter ' . $ctrlLabel . ' range ' . $sMin . ' to ' . $sMax . '. ' . $edgeText;
        $nextStep = 'Stay inside this range and use one-setting tests to confirm what keeps working for this lottery.';
    }

    return array(
        'stage'        => $stage,
        'stage_label'  => $stageLabel,
        'has_range'    => ($stage !== 'broad_testing'),
        'range_min'    => (float)$rangeMin,
        'range_max'    => (float)$rangeMax,
        'sweet_min'    => $sweetMin,
        'sweet_max'    => $sweetMax,
        'run_count'    => $total,
        'control_label'=> $ctrlLabel,
        'summary'      => $summary,
        'stage_plain'  => $stagePlain,
        'evidence_line'=> $evidenceLine,
        'next_step'    => $nextStep,
        'random_edge'  => $edgeMetrics,
        'range_width'  => (float)$rangeWidth,
        'blend_coverage' => $blendCoverage,
        'blend_full_coverage_met' => true,
        'tested_min' => $blendCoverage['tested_min'],
        'tested_max' => $blendCoverage['tested_max'],
        'distinct_values' => (int)$blendCoverage['distinct_values'],
    );
}

function mleAdvisoryComputeHorizonWindowLockData(array $perfRows, array $savedById)
{
    $HORIZON_MIN = 25.0;
    $HORIZON_MAX = 1000.0;
    $scored = array();
    $latestWindow = 0.0;

    foreach ($perfRows as $row) {
        $sid = (int)($row['__saved_id'] ?? $row['run_id'] ?? 0);
        if ($sid <= 0 || empty($savedById[$sid])) { continue; }
        $settings = mylottoexpertResolveEffectiveSettings($savedById[$sid]);

        $windowVal = null;
        if (function_exists('mylottoexpertV99ExtractBlendAndHistoryValuesFromSettings')) {
            $resolvedVals = (array)mylottoexpertV99ExtractBlendAndHistoryValuesFromSettings((array)$settings);
            if (isset($resolvedVals['history']) && $resolvedVals['history'] !== null && is_numeric($resolvedVals['history'])) {
                $windowVal = (float)$resolvedVals['history'];
            }
        }
        if ($windowVal === null) { continue; }
        if ($windowVal > $latestWindow) { $latestWindow = $windowVal; }

        $edge = mleAdvisoryCalculateRandomEdgeForRow($row);
        $quality = (float)($row['weighted_quality_score'] ?? 0);
        $avgLift = (float)($edge['avg_rank_lift'] ?? 0.0);
        $penLift = (float)($edge['penalized_rank_lift'] ?? 0.0);
        $top10 = (int)($row['top10_hits'] ?? 0);
        $top20 = (int)($row['top20_hits'] ?? 0);
        $rank = (float)($row['avg_winning_rank'] ?? 999);

        $score = ($avgLift * 8.0)
               + ($penLift * 10.0)
               + ($quality * 4.0)
               + ($top10 * 0.8)
               + ($top20 * 0.35)
               - min(8.0, max(0.0, $rank) * 0.04);

        $scored[] = array('window' => $windowVal, 'score' => $score);
    }

    $noData = array(
        'has_range'     => false,
        'run_count'     => 0,
        'current_value' => 0.0,
        'range_min'     => $HORIZON_MIN,
        'range_max'     => $HORIZON_MAX,
        'sweet_min'     => null,
        'sweet_max'     => null,
        'stage'         => 'exploring',
        'stage_label'   => 'Exploring',
        'horizon_coverage' => mleAdvisoryBuildHorizonCoverageFromValues(array()),
        'horizon_full_coverage_met' => false,
        'distinct_windows' => 0,
        'tested_min' => null,
        'tested_max' => null,
    );
    $total = count($scored);
    if ($total < 1) { return $noData; }

    $windowBuckets = array();
    foreach ($scored as $scoredRow) {
        $windowBuckets[(string)((int)round((float)$scoredRow['window']))] = true;
    }
    $distinctWindowCount = count($windowBuckets);
    $testedMin = (float)min(array_column($scored, 'window'));
    $testedMax = (float)max(array_column($scored, 'window'));
    $horizonCoverage = mleAdvisoryBuildHorizonCoverageFromValues(array_column($scored, 'window'));

    /*
     * V96 source-math correction: SKAI's current contract tests a learned history-window
     * corridor, often 70/100/130. Do not require absolute 25-through-1000 endpoint
     * coverage before detecting a corridor signal. Require repeated scored evidence
     * across at least three distinct tested window values instead.
     */
    if ($distinctWindowCount < 2) {
        return array(
            'has_range'       => false,
            'run_count'       => $total,
            'current_value'   => $latestWindow,
            'range_min'       => $HORIZON_MIN,
            'range_max'       => $HORIZON_MAX,
            'tested_min'      => $testedMin,
            'tested_max'      => $testedMax,
            'distinct_windows'=> $distinctWindowCount,
            'sweet_min'       => null,
            'sweet_max'       => null,
            'stage'           => 'exploring',
            'stage_label'     => 'Waiting for broad window prediction history',
            'horizon_coverage' => $horizonCoverage,
            'horizon_full_coverage_met' => false,
        );
    }

    if (empty($horizonCoverage['full_coverage_met'])) {
        return array(
            'has_range'       => false,
            'run_count'       => $total,
            'current_value'   => $latestWindow,
            'range_min'       => $HORIZON_MIN,
            'range_max'       => $HORIZON_MAX,
            'tested_min'      => $testedMin,
            'tested_max'      => $testedMax,
            'distinct_windows'=> $distinctWindowCount,
            'sweet_min'       => null,
            'sweet_max'       => null,
            'stage'           => 'exploring',
            'stage_label'     => 'Needs tested window corridor coverage',
            'horizon_coverage' => $horizonCoverage,
            'horizon_full_coverage_met' => false,
        );
    }

    usort($scored, function($a, $b) { return ($b['score'] > $a['score']) ? 1 : (($b['score'] < $a['score']) ? -1 : 0); });

    $cutStrong = max(1, (int)ceil($total * 0.40));
    $strongVals = array_column(array_slice($scored, 0, $cutStrong), 'window');
    $rangeMin = (float)min($strongVals);
    $rangeMax = (float)max($strongVals);

    $sweetMin = null;
    $sweetMax = null;
    $cutSweet = max(1, (int)ceil($total * 0.20));
    if ($cutSweet >= 2) {
        $sweetVals = array_column(array_slice($scored, 0, $cutSweet), 'window');
        $sMin = (float)min($sweetVals);
        $sMax = (float)max($sweetVals);
        if ($sMin >= $rangeMin && $sMax <= $rangeMax && ($sMax - $sMin) < ($rangeMax - $rangeMin)) {
            $sweetMin = $sMin;
            $sweetMax = $sMax;
        }
    }

    $rangeWidth = $rangeMax - $rangeMin;
    $testedCoverage = ($testedMax - $testedMin) / max(1.0, ($HORIZON_MAX - $HORIZON_MIN));
    $testedContractSpan = max(1.0, (float)$testedMax - (float)$testedMin);
    $hasEnoughComparison = ($total >= 9 && $distinctWindowCount >= 3 && !empty($horizonCoverage['full_coverage_met']));
    $hasRange = ($hasEnoughComparison && $rangeWidth < max(20.0, $testedContractSpan * 0.80));
    if ($rangeWidth <= 100 && $hasEnoughComparison && $hasRange) {
        $stage = 'narrowing';
        $stageLabel = 'Narrowing horizon';
    } elseif ($hasRange) {
        $stage = 'early_horizon';
        $stageLabel = 'Early horizon signal';
    } else {
        $stage = 'exploring';
        $stageLabel = !empty($horizonCoverage['full_coverage_met'])
            ? 'Window corridor is scored, but the range is still broad'
            : 'Needs broader window comparison';
    }

    return array(
        'has_range'       => $hasRange,
        'run_count'       => $total,
        'current_value'   => $latestWindow,
        'range_min'       => $hasRange ? $rangeMin : $HORIZON_MIN,
        'range_max'       => $hasRange ? $rangeMax : $HORIZON_MAX,
        'tested_min'      => $testedMin,
        'tested_max'      => $testedMax,
        'distinct_windows'=> $distinctWindowCount,
        'sweet_min'       => $hasRange ? $sweetMin : null,
        'sweet_max'       => $hasRange ? $sweetMax : null,
        'stage'           => $stage,
        'stage_label'     => $stageLabel,
        'horizon_coverage' => $horizonCoverage,
        'horizon_full_coverage_met' => !empty($horizonCoverage['full_coverage_met']),
    );
}

function mleAdvisoryNormalizeBatchValue($value, $type) {
    $type = (string)$type;
    if (!is_numeric($value)) { return ''; }
    $v = (float)$value;
    if ($type === 'decimal') { return rtrim(rtrim(number_format($v, 3, '.', ''), '0'), '.'); }
    return (string)((int)round($v));
}

function mleAdvisoryGenerateEightDistinctBatchValues($rangeMin, $rangeMax, $recommendedValue, $variableType) {
    $rangeMin = (float)$rangeMin;
    $rangeMax = (float)$rangeMax;
    if ($rangeMax < $rangeMin) { $tmp = $rangeMin; $rangeMin = $rangeMax; $rangeMax = $tmp; }
    $variableType = ($variableType === 'decimal') ? 'decimal' : 'integer';
    $span = $rangeMax - $rangeMin;
    if ($variableType === 'integer') {
        $lo = (int)ceil($rangeMin);
        $hi = (int)floor($rangeMax);
        if (($hi - $lo + 1) < 8) { return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create 8 useful distinct integer test values from this range.'); }
        $raw = array($lo, $lo + (($hi - $lo) * 1.0 / 7.0), $lo + (($hi - $lo) * 2.0 / 7.0), $lo + (($hi - $lo) * 3.0 / 7.0), $lo + (($hi - $lo) * 4.0 / 7.0), $lo + (($hi - $lo) * 5.0 / 7.0), $hi);
        if (is_numeric($recommendedValue)) { $raw[] = max($lo, min($hi, (float)$recommendedValue)); }
        else { $raw[] = $lo + (($hi - $lo) * 6.0 / 7.0); }
        $vals = array();
        foreach ($raw as $v) { $vals[] = (int)round($v); }
        $seen = array(); $distinct = array();
        foreach ($vals as $v) { if ($v < $lo) { $v = $lo; } if ($v > $hi) { $v = $hi; } $k = (string)$v; if (!isset($seen[$k])) { $seen[$k] = true; $distinct[] = $v; } }
        for ($v=$lo; count($distinct)<8 && $v <= $hi; $v++) { $k=(string)$v; if (!isset($seen[$k])) { $seen[$k]=true; $distinct[]=$v; } }
        sort($distinct, SORT_NUMERIC);
        if (count($distinct) > 8) {
            $sample = array();
            for ($i=0; $i<8; $i++) { $idx = (int)round($i * (count($distinct)-1) / 7); $sample[] = $distinct[$idx]; }
            $distinct = array_values(array_unique($sample));
        }
        if (count($distinct) !== 8) { return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create 8 useful distinct integer test values from this range.'); }
        return array('ok'=>true,'values'=>$distinct,'reason'=>'');
    }
    if ($span <= 0) { return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create 8 useful distinct decimal test values from this range.'); }
    $raw = array();
    for ($i=0; $i<7; $i++) { $raw[] = $rangeMin + ($span * $i / 6.0); }
    if (is_numeric($recommendedValue)) { $raw[] = max($rangeMin, min($rangeMax, (float)$recommendedValue)); }
    else { $raw[] = $rangeMin + ($span * 0.5); }
    $seen = array(); $distinct = array();
    foreach ($raw as $v) { $k = mleAdvisoryNormalizeBatchValue($v, 'decimal'); if ($k !== '' && !isset($seen[$k])) { $seen[$k]=true; $distinct[]=(float)$k; } }
    for ($i=0; count($distinct)<8 && $i<80; $i++) { $v = $rangeMin + ($span * $i / 79.0); $k = mleAdvisoryNormalizeBatchValue($v, 'decimal'); if ($k !== '' && !isset($seen[$k])) { $seen[$k]=true; $distinct[]=(float)$k; } }
    sort($distinct, SORT_NUMERIC);
    if (count($distinct) > 8) {
        $sample = array();
        for ($i=0; $i<8; $i++) { $idx = (int)round($i * (count($distinct)-1) / 7); $sample[] = $distinct[$idx]; }
        $tmp = array(); $seen2=array();
        foreach ($sample as $v) { $k=mleAdvisoryNormalizeBatchValue($v,'decimal'); if (!isset($seen2[$k])) { $seen2[$k]=true; $tmp[]=$v; } }
        $distinct = $tmp;
    }
    if (count($distinct) !== 8) { return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create 8 useful distinct decimal test values from this range.'); }
    return array('ok'=>true,'values'=>$distinct,'reason'=>'');
}

function mleAdvisoryIsBlendPercentSettingKey($settingKey, $settingLabel = '') {
    $hay = strtolower((string)$settingKey . ' ' . (string)$settingLabel);
    return (strpos($hay, 'blend') !== false || strpos($hay, 'pct') !== false || strpos($hay, 'percent') !== false);
}

function mleAdvisoryGenerateNineSegmentedBlendBatchValues($rangeMin, $rangeMax) {
    $rangeMin = max(0.0, min(100.0, (float)$rangeMin));
    $rangeMax = max(0.0, min(100.0, (float)$rangeMax));
    if ($rangeMax < $rangeMin) { $tmp = $rangeMin; $rangeMin = $rangeMax; $rangeMax = $tmp; }
    if (($rangeMax - $rangeMin) < 8.0) {
        return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create a full low/middle/high blend discovery set from this narrow range.');
    }
    $span = $rangeMax - $rangeMin;
    $mid = ($rangeMin + $rangeMax) / 2.0;
    $raw = array(
        $rangeMin,
        $rangeMin + ($span * 0.05),
        $rangeMin + ($span * 0.10),
        $mid - ($span * 0.05),
        $mid,
        $mid + ($span * 0.05),
        $rangeMax - ($span * 0.10),
        $rangeMax - ($span * 0.05),
        $rangeMax
    );
    $seen = array();
    $values = array();
    foreach ($raw as $v) {
        $v = (int)round(max($rangeMin, min($rangeMax, $v)));
        $k = (string)$v;
        if (!isset($seen[$k])) { $seen[$k] = true; $values[] = $v; }
    }
    if (count($values) !== 9) {
        $values = array();
        $seen = array();
        for ($i = 0; $i < 9; $i++) {
            $v = (int)round($rangeMin + ($span * $i / 8.0));
            $k = (string)$v;
            if (!isset($seen[$k])) { $seen[$k] = true; $values[] = $v; }
        }
    }
    if (count($values) !== 9) {
        return array('ok'=>false,'values'=>array(),'reason'=>'LottoExpert could not create nine distinct low/middle/high blend percentages from this range.');
    }
    return array('ok'=>true,'values'=>$values,'reason'=>'');
}

function mleAdvisoryResolveControlledBatchPhase($settingKey, $settingLabel, $variableType, $rangeMin, $rangeMax, $isSegmentedBlendDiscovery = false) {
    $settingKey = (string)$settingKey;
    $settingLabel = (string)$settingLabel;
    $variableType = ($variableType === 'decimal') ? 'decimal' : 'integer';
    $rangeMin = (float)$rangeMin;
    $rangeMax = (float)$rangeMax;
    if ($rangeMax < $rangeMin) { $tmp = $rangeMin; $rangeMin = $rangeMax; $rangeMax = $tmp; }
    $span = max(0.0, $rangeMax - $rangeMin);
    $isBlend = mleAdvisoryIsBlendPercentSettingKey($settingKey, $settingLabel);

    if ($isSegmentedBlendDiscovery) {
        return array(
            'key' => 'full_blend_discovery',
            'label' => 'Full Blend Discovery',
            'short_label' => 'Full 0-100 blend discovery',
            'description' => 'The blend range has not been fully proven yet, so this batch deliberately tests the low, middle, and high zones across the full 0% to 100% avenue.',
            'test_plan' => 'Create 9 AI runs for this lottery across the full blend range: 3 low-end tests, 3 middle-range tests, and 3 high-end tests. This prevents LottoExpert from narrowing before the full 0% to 100% avenue has been explored.',
            'advanced_explanation' => 'This full-range blend discovery batch intentionally spreads the 9 generated runs over the low, middle, and high percentage zones before allowing LottoExpert to narrow the range.',
            'beginner_explanation' => 'This sends 9 controlled blend tests to AI: 3 low-end blend percentages, 3 middle-range percentages, and 3 high-end percentages.',
            'span' => $span
        );
    }

    if ($isBlend) {
        if ($span <= 12.0) {
            return array(
                'key' => 'fine_blend_precision',
                'label' => 'Fine Precision Blend Test',
                'short_label' => 'Fine blend precision',
                'description' => 'The blend range is already tight, so the batch tests exact integer percentage points inside the proven bracket instead of jumping by broad 5-point sections.',
                'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test exact blend percentages inside the narrowed Settings Precision Range so LottoExpert can identify the strongest point more precisely.',
                'advanced_explanation' => 'This fine precision batch keeps the base settings stable and varies only the blend percentage inside the narrowed range. It is designed for exact-point confirmation after broad zones have already been explored.',
                'beginner_explanation' => 'This is no longer a broad low/middle/high search. It tests specific blend percentages inside the narrowed range.',
                'span' => $span
            );
        }
        if ($span <= 30.0) {
            return array(
                'key' => 'narrow_blend_range',
                'label' => 'Narrow Blend Range Test',
                'short_label' => 'Narrow blend range',
                'description' => 'The blend range has narrowed, so the batch spreads test points across the current bracket instead of using only 5-point chunks.',
                'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test blend percentages spread across the narrowed Settings Precision Range.',
                'advanced_explanation' => 'This narrowed blend batch keeps the base settings stable and distributes the test values across the current bracket so the next scored draw can tighten the range again.',
                'beginner_explanation' => 'The system is now testing inside the narrowed blend range, not the entire 0% to 100% scale.',
                'span' => $span
            );
        }
        return array(
            'key' => 'bracketed_blend_range',
            'label' => 'Bracketed Blend Range Test',
            'short_label' => 'Bracketed blend range',
            'description' => 'The blend range is still fairly wide, so the batch brackets the current range before moving into finer precision.',
            'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 bracket the current blend range so LottoExpert can narrow the next test.',
            'advanced_explanation' => 'This bracketed blend batch is a controlled range test. It avoids prematurely jumping to a single point until more completed prediction history exists.',
            'beginner_explanation' => 'This tests several points across the current blend range so the next batch can become tighter.',
            'span' => $span
        );
    }

    if ($variableType === 'decimal') {
        if ($span <= 0.12) {
            return array(
                'key' => 'fine_decimal_precision',
                'label' => 'Fine Decimal Precision Test',
                'short_label' => 'Fine decimal precision',
                'description' => 'The decimal setting range is narrow, so the batch tests finer decimal points inside the proven bracket.',
                'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test fine decimal values inside the narrowed Settings Precision Range.',
                'advanced_explanation' => 'This fine decimal batch keeps the base settings stable and varies one decimal setting with up to three-decimal precision.',
                'beginner_explanation' => 'This tests fine decimal settings inside a tight range instead of broad jumps.',
                'span' => $span
            );
        }
        return array(
            'key' => 'decimal_range_test',
            'label' => 'Decimal Range Test',
            'short_label' => 'Decimal range',
            'description' => 'The batch spreads decimal test points across the current range so the next scored result can tighten it.',
            'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test decimal values across the current Settings Precision Range.',
            'advanced_explanation' => 'This decimal range batch keeps the base settings stable and varies one decimal setting across the current bracket.',
            'beginner_explanation' => 'This tests several decimal values across the current setting range.',
            'span' => $span
        );
    }

    return array(
        'key' => 'integer_range_test',
        'label' => 'Settings Range Test',
        'short_label' => 'Settings range',
        'description' => 'The batch spreads integer test points across the current range while all other settings stay stable.',
        'test_plan' => 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test one setting across a bracketed range so AI can narrow the next setting more clearly.',
        'advanced_explanation' => 'This batch keeps the base settings stable and varies one integer setting across 8 bracketed values.',
        'beginner_explanation' => 'This sends you directly to the correct AI lottery page with 9 controlled runs ready to test. The first run is the control; the other 8 test one setting.',
        'span' => $span
    );
}

function mleAdvisoryBuildForcedNextSettingsSkaiBatchPlan(array $settingsAdv, array $precisionLock, array $summary = array())
{
    $hasAdvice = !empty($settingsAdv['has_advice']);
    $settingKey = trim((string)($settingsAdv['setting'] ?? ''));
    $settingLabel = trim((string)($settingsAdv['setting_label'] ?? ''));
    $currentValue = trim((string)($settingsAdv['current_value'] ?? ''));
    $suggestedValue = trim((string)($settingsAdv['suggested_value'] ?? ''));

    if (!$hasAdvice || $settingKey === '' || $settingLabel === '') {
        return array('has_recommendation' => false, 'fail_reason' => 'No recommended next setting is available yet.');
    }

    $decimalKeys = array('diversity_penalty','sampling_temperature','recency_decay','learning_rate','dropout_rate','gap_scale');
    $binaryKeys = array('best_window','auto_tune');
    $variableType = in_array($settingKey, $decimalKeys, true) ? 'decimal' : 'integer';
    if (!empty($settingsAdv['batch_variable_type']) && in_array((string)$settingsAdv['batch_variable_type'], array('integer','decimal'), true)) {
        $variableType = (string)$settingsAdv['batch_variable_type'];
    }

    if (in_array($settingKey, $binaryKeys, true)) {
        $settingKey = 'skai_blend_ai_pct';
        $settingLabel = 'Blend Setting';
        $currentValue = '50';
        $suggestedValue = '55';
        $variableType = 'integer';
    }

    $cur = is_numeric($currentValue) ? (float)$currentValue : null;
    $sug = is_numeric($suggestedValue) ? (float)$suggestedValue : null;
    if ($cur === null && $sug === null) {
        return array('has_recommendation' => false, 'fail_reason' => 'The recommended setting is not numeric enough for a 9-run AI batch.');
    }
    if ($cur === null) { $cur = $sug; }
    if ($sug === null) { $sug = $cur; }

    $rangeMin = null;
    $rangeMax = null;

    if (isset($settingsAdv['batch_range_min'], $settingsAdv['batch_range_max']) && is_numeric($settingsAdv['batch_range_min']) && is_numeric($settingsAdv['batch_range_max'])) {
        $rangeMin = (float)$settingsAdv['batch_range_min'];
        $rangeMax = (float)$settingsAdv['batch_range_max'];
    } elseif (!empty($precisionLock['has_range']) && is_numeric($precisionLock['range_min'] ?? null) && is_numeric($precisionLock['range_max'] ?? null)) {
        $rangeMin = (float)$precisionLock['range_min'];
        $rangeMax = (float)$precisionLock['range_max'];
    }

    if ($rangeMin === null || $rangeMax === null || abs($rangeMax - $rangeMin) < 1.0e-9) {
        $low = min($cur, $sug);
        $high = max($cur, $sug);
        if ($variableType === 'decimal') {
            $center = ($cur + $sug) / 2.0;
            $span = max(0.08, abs($high - $low) * 2.0);
            $rangeMin = $center - ($span / 2.0);
            $rangeMax = $center + ($span / 2.0);
        } else {
            $center = ($cur + $sug) / 2.0;
            $span = max(7.0, abs($high - $low) * 2.0);
            $rangeMin = floor($center - ($span / 2.0));
            $rangeMax = ceil($center + ($span / 2.0));
        }
    }

    if ($rangeMax < $rangeMin) {
        $tmp = $rangeMin;
        $rangeMin = $rangeMax;
        $rangeMax = $tmp;
    }

    if (preg_match('/(pct|percent|blend)/i', $settingKey)) {
        $rangeMin = max(0.0, min(100.0, (float)$rangeMin));
        $rangeMax = max(0.0, min(100.0, (float)$rangeMax));
        if (($rangeMax - $rangeMin) < 7.0 && $variableType === 'integer') {
            $center = max(0.0, min(100.0, (float)$sug));
            $rangeMin = max(0.0, $center - 4.0);
            $rangeMax = min(100.0, $center + 4.0);
        }
    }

    if ($variableType === 'decimal' && in_array($settingKey, array('diversity_penalty','sampling_temperature','recency_decay','dropout_rate','gap_scale'), true)) {
        $rangeMin = max(0.0, min(1.0, (float)$rangeMin));
        $rangeMax = max(0.0, min(1.0, (float)$rangeMax));
        if (($rangeMax - $rangeMin) < 0.08) {
            $center = max(0.0, min(1.0, (float)$sug));
            $rangeMin = max(0.0, $center - 0.06);
            $rangeMax = min(1.0, $center + 0.06);
        }
    }

    $isBlendPercentSetting = mleAdvisoryIsBlendPercentSettingKey($settingKey, $settingLabel);
    $needsFullBlendDiscovery = ($isBlendPercentSetting && empty($precisionLock['blend_full_coverage_met']));
    if ($needsFullBlendDiscovery) {
        $rangeMin = 0.0;
        $rangeMax = 100.0;
        if ($suggestedValue === '' || !is_numeric($suggestedValue)) { $suggestedValue = '50'; }
    }
    $useSegmentedBlendDiscovery = ($isBlendPercentSetting && $variableType === 'integer' && ($needsFullBlendDiscovery || ($rangeMin <= 0.000001 && $rangeMax >= 99.999999)));
    $batchPhase = mleAdvisoryResolveControlledBatchPhase($settingKey, $settingLabel, $variableType, $rangeMin, $rangeMax, $useSegmentedBlendDiscovery);

    $batchRunLabels = array();
    $batchRunValues = array();
    $batchRunRoles = array();

    if ($useSegmentedBlendDiscovery) {
        $valueResult = mleAdvisoryGenerateNineSegmentedBlendBatchValues($rangeMin, $rangeMax);
        if (empty($valueResult['ok']) || count((array)($valueResult['values'] ?? array())) !== 9) {
            return array('has_recommendation' => false, 'fail_reason' => (string)($valueResult['reason'] ?? 'Could not build a 9-run AI blend discovery batch.'));
        }
        $values = (array)$valueResult['values'];
        $desc = array(
            0 => array('Low-range test 1', 'low_range'),
            1 => array('Low-range test 2', 'low_range'),
            2 => array('Low-range test 3', 'low_range'),
            3 => array('Middle-range test 1', 'middle_range'),
            4 => array('Middle-range test 2', 'middle_range'),
            5 => array('Middle-range test 3', 'middle_range'),
            6 => array('High-range test 1', 'high_range'),
            7 => array('High-range test 2', 'high_range'),
            8 => array('High-range test 3', 'high_range')
        );
        for ($i = 0; $i < 9; $i++) {
            $vText = mleAdvisoryNormalizeBatchValue($values[$i], $variableType);
            $batchRunLabels[] = 'Test ' . ($i + 1) . ' - ' . $settingLabel . ' ' . $vText . '% (' . $desc[$i][0] . ')';
            $batchRunValues[] = $vText;
            $batchRunRoles[] = $desc[$i][1];
        }
    } else {
        $valueResult = mleAdvisoryGenerateEightDistinctBatchValues($rangeMin, $rangeMax, $suggestedValue, $variableType);
        if (empty($valueResult['ok']) || count((array)($valueResult['values'] ?? array())) !== 8) {
            $settingKey = 'skai_blend_ai_pct';
            $settingLabel = 'Blend Setting';
            $variableType = 'integer';
            $rangeMin = 0.0;
            $rangeMax = 100.0;
            $suggestedValue = '50';
            $useSegmentedBlendDiscovery = true;
            $batchPhase = mleAdvisoryResolveControlledBatchPhase($settingKey, $settingLabel, $variableType, $rangeMin, $rangeMax, $useSegmentedBlendDiscovery);
            $valueResult = mleAdvisoryGenerateNineSegmentedBlendBatchValues($rangeMin, $rangeMax);
        }

        if ($useSegmentedBlendDiscovery) {
            if (empty($valueResult['ok']) || count((array)($valueResult['values'] ?? array())) !== 9) {
                return array('has_recommendation' => false, 'fail_reason' => (string)($valueResult['reason'] ?? 'Could not build a 9-run AI blend discovery batch.'));
            }
            $values = (array)$valueResult['values'];
            $desc = array(
                0 => array('Low-range test 1', 'low_range'),
                1 => array('Low-range test 2', 'low_range'),
                2 => array('Low-range test 3', 'low_range'),
                3 => array('Middle-range test 1', 'middle_range'),
                4 => array('Middle-range test 2', 'middle_range'),
                5 => array('Middle-range test 3', 'middle_range'),
                6 => array('High-range test 1', 'high_range'),
                7 => array('High-range test 2', 'high_range'),
                8 => array('High-range test 3', 'high_range')
            );
            for ($i = 0; $i < 9; $i++) {
                $vText = mleAdvisoryNormalizeBatchValue($values[$i], $variableType);
                $batchRunLabels[] = 'Test ' . ($i + 1) . ' - ' . $settingLabel . ' ' . $vText . '% (' . $desc[$i][0] . ')';
                $batchRunValues[] = $vText;
                $batchRunRoles[] = $desc[$i][1];
            }
        } else {
            if (empty($valueResult['ok']) || count((array)($valueResult['values'] ?? array())) !== 8) {
                return array('has_recommendation' => false, 'fail_reason' => (string)($valueResult['reason'] ?? 'Could not build a 9-run AI batch.'));
            }
            $values = (array)$valueResult['values'];
            $controlValue = mleAdvisoryNormalizeBatchValue($cur, $variableType);
            $batchRunLabels = array('Control - Current Best Settings');
            $batchRunValues = array($controlValue !== '' ? $controlValue : (string)$currentValue);
            $batchRunRoles = array('control');
            $desc = array(1=>'Low edge test',2=>'Low-mid test',3=>'Mid-low test',4=>'Center test',5=>'Mid-high test',6=>'High-mid test',7=>'High edge test',8=>'Recommended point');

            for ($i = 0; $i < 8; $i++) {
                $vText = mleAdvisoryNormalizeBatchValue($values[$i], $variableType);
                $batchRunLabels[] = 'Test ' . ($i + 1) . ' - ' . $settingLabel . ' ' . $vText . ' (' . $desc[$i + 1] . ')';
                $batchRunValues[] = $vText;
                $batchRunRoles[] = 'explore';
            }
        }
    }

    $controlValue = mleAdvisoryNormalizeBatchValue($cur, $variableType);

    $rMinText = mleAdvisoryNormalizeBatchValue($rangeMin, $variableType);
    $rMaxText = mleAdvisoryNormalizeBatchValue($rangeMax, $variableType);

    return array(
        'has_recommendation' => true,
        'title' => !empty($settingsAdv['_mle_v80_global_settings_advice']) ? 'Global Settings Intelligence 9-Run AI Batch' : 'Recommended Next Settings 9-Run AI Batch',
        'summary' => !empty($settingsAdv['_mle_v80_global_settings_advice']) ? 'LottoExpert created a controlled 9-run AI batch from global scored settings intelligence for this exact lottery.' : 'LottoExpert created a controlled 9-run AI batch from the recommended next setting.',
        'test_plan' => (string)($batchPhase['test_plan'] ?? ($useSegmentedBlendDiscovery ? 'Create 9 AI runs for this lottery across the full blend range: 3 low-end tests, 3 middle-range tests, and 3 high-end tests.' : 'Create 9 AI runs for this lottery. Run 1 is the control. Runs 2 through 9 test only ' . $settingLabel . ' across a bracketed range.')),
        'advanced_explanation' => (string)($batchPhase['advanced_explanation'] ?? ($useSegmentedBlendDiscovery ? 'This full-range blend discovery batch intentionally spreads the 9 generated runs over the low, middle, and high percentage zones before allowing LottoExpert to narrow the range.' : (!empty($settingsAdv['_mle_v80_global_settings_advice']) ? 'This batch uses per-lottery global completed prediction history to choose one setting family, then brackets it into eight sections while keeping the stronger settings stable.' : 'This batch keeps the base settings stable and varies one setting across 8 bracketed values.'))),
        'guardrail' => 'Do not change other settings while this batch is being tested.',
        'evidence_line' => ((int)($summary['total_runs'] ?? 0)) . ' saved runs are being used to create the next controlled test.',
        'batch_purpose' => 'Narrow the recommended next setting using a controlled 9-run AI batch.',
        'locked_settings' => trim((string)($settingsAdv['keep_same_list'] ?? 'Keep the strongest settings stable.')),
        'test_variable' => $settingLabel,
        'setting_key' => $settingKey,
        'control_run' => $useSegmentedBlendDiscovery ? 'Full-range discovery: no single control row is used; all 9 rows test low, middle, or high blend percentages.' : 'Control - Current Best Settings (' . $settingLabel . ' at ' . ($controlValue !== '' ? $controlValue : (string)$currentValue) . ').',
        'control_source' => 'Recommended Next Settings Run',
        'batch_runs' => $batchRunLabels,
        'batch_run_values' => $batchRunValues,
        'batch_run_roles' => $batchRunRoles,
        'no_control_run' => $useSegmentedBlendDiscovery ? true : false,
        '_mle_blend_full_range_segmented_discovery' => $useSegmentedBlendDiscovery ? true : false,
        'what_it_proves' => 'Which point in this setting range deserves the next focused test.',
        'preferred_use' => 'Best when the user wants the next settings recommendation to move directly into AI for immediate testing.',
        'range_basis' => $settingLabel,
        'current_range' => $rMinText . ' to ' . $rMaxText,
        'batch_phase' => (string)($batchPhase['key'] ?? ''),
        'batch_phase_label' => (string)($batchPhase['label'] ?? ''),
        'batch_phase_short_label' => (string)($batchPhase['short_label'] ?? ''),
        'batch_phase_description' => (string)($batchPhase['description'] ?? ''),
        'batch_precision_span' => (float)($batchPhase['span'] ?? ($rangeMax - $rangeMin)),
        'range_min' => $rangeMin,
        'range_max' => $rangeMax,
        'recommended_value' => $suggestedValue,
        'beginner_explanation' => (string)($batchPhase['beginner_explanation'] ?? ($useSegmentedBlendDiscovery ? 'This sends 9 controlled blend tests to AI: 3 low-end blend percentages, 3 middle-range percentages, and 3 high-end percentages.' : 'This sends you directly to the correct AI lottery page with 9 controlled runs ready to test. The first run is the control; the other 8 test one setting.')),
        'milestone_supported' => 'Run the next controlled AI test for this lottery.',
        'batch_type' => !empty($settingsAdv['_mle_v80_global_settings_advice']) ? 'Global Settings Intelligence 9-Run Batch' : 'Next Settings 9-Run Batch',
        'global_learning_scope' => !empty($settingsAdv['_mle_v80_global_settings_advice']) ? 'exact_lottery_only' : '',
        'global_setting_family' => (string)($settingsAdv['_mle_v80_setting_family'] ?? ''),
        'global_source_rows' => (int)($settingsAdv['_mle_v80_source_rows'] ?? 0),
        'global_source_users' => (int)($settingsAdv['_mle_v80_source_users'] ?? 0),
        'global_source_draws' => (int)($settingsAdv['_mle_v80_source_draws'] ?? 0),
        'source_evidence' => array(
            'settings_source' => (string)($settingsAdv['source'] ?? ''),
            'settings_source_detail' => (string)($settingsAdv['source_detail'] ?? ''),
            'confidence' => (string)($settingsAdv['confidence'] ?? ''),
            'evidence_count' => (int)($settingsAdv['evidence_count'] ?? 0),
            'hive_settings_fingerprint' => (string)($settingsAdv['hive_settings_fingerprint'] ?? '')
        )
    );
}

function mleAdvisoryParseSkaiLotteryUrlMetaFromUrl($url, $lotteryId = 0)
{
    $url = trim((string)$url);
    $parsedMeta = array(
        'lottery_url' => '',
        'base_url' => '',
        'gameId' => '',
        'st' => '',
        'stn' => '',
        'gm' => '',
        'lottery_id' => (int)$lotteryId,
    );
    if ($url === '') {
        return $parsedMeta;
    }

    $decodedUrl = html_entity_decode($url, ENT_QUOTES, 'UTF-8');
    if (!preg_match('#skai-lottery-prediction#i', $decodedUrl)) {
        return $parsedMeta;
    }

    $parts = @parse_url($decodedUrl);
    if (!is_array($parts)) {
        return $parsedMeta;
    }

    $scheme = isset($parts['scheme']) ? strtolower((string)$parts['scheme']) : '';
    $host   = isset($parts['host']) ? trim((string)$parts['host']) : '';
    $path   = isset($parts['path']) ? trim((string)$parts['path']) : '';
    if ($path === '' || stripos($path, 'skai-lottery-prediction') === false) {
        return $parsedMeta;
    }

    $baseUrl = $path;
    if ($host !== '') {
        $baseUrl = ($scheme !== '' ? $scheme : 'https') . '://' . $host . $path;
        if (!empty($parts['port'])) {
            $baseUrl = ($scheme !== '' ? $scheme : 'https') . '://' . $host . ':' . (int)$parts['port'] . $path;
        }
    } elseif ($baseUrl !== '' && $baseUrl[0] !== '/') {
        $baseUrl = '/' . ltrim($baseUrl, '/');
    }

    $query = array();
    if (!empty($parts['query'])) {
        parse_str((string)$parts['query'], $query);
    }

    $gameIdRaw = $query['gameId'] ?? ($query['game_id'] ?? ($query['gid'] ?? ''));
    $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameIdRaw, 0, 50));
    $stateCode = strtolower(preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($query['st'] ?? ''), 0, 20)));
    $stateName = trim((string)($query['stn'] ?? ''));
    $gameName  = trim((string)($query['gm'] ?? ''));

    $parsedMeta['lottery_url'] = $decodedUrl;
    $parsedMeta['base_url'] = $baseUrl;
    $parsedMeta['gameId'] = $gameId;
    $parsedMeta['st'] = $stateCode;
    $parsedMeta['stn'] = $stateName;
    $parsedMeta['gm'] = $gameName;
    return $parsedMeta;
}

function mleAdvisoryIsPlausibleSkaiGameId($value)
{

    $value = trim((string)$value);
    if ($value === '' || !preg_match('/^[A-Za-z0-9_.-]{1,50}$/', $value)) {
        return false;
    }
    if (preg_match('/^0+$/', $value)) {
        return false;
    }
    return true;
}

function mleAdvisoryResolveSkaiPageBaseUrl($db)
{

    $siteBase = rtrim(\Joomla\CMS\Uri\Uri::base(), '/');

    if (defined('MLE_SKAI_PAGE_PATH')) {
        $configured = trim((string)constant('MLE_SKAI_PAGE_PATH'));
        if ($configured !== '') {
            if (preg_match('#^https?://#i', $configured)) {
                return $configured;
            }
            return $siteBase . '/' . ltrim($configured, '/');
        }
    }

    return $siteBase . '/picking-winning-numbers/artificial-intelligence/skai-lottery-prediction';
}

function mleAdvisoryNormalizeStateCodeForSkai($stateName, $countryName = '')
{
    $stateName = trim((string)$stateName);
    $countryName = trim((string)$countryName);
    if ($stateName === '') {
        return '';
    }

    $key = strtolower(preg_replace('/[^a-z0-9]+/', ' ', $stateName));
    $key = trim(preg_replace('/\s+/', ' ', $key));

    $map = array(
        'alabama'=>'al','alaska'=>'ak','arizona'=>'az','arkansas'=>'ar','california'=>'ca','colorado'=>'co','connecticut'=>'ct','delaware'=>'de','district of columbia'=>'dc','florida'=>'fl','georgia'=>'ga','hawaii'=>'hi','idaho'=>'id','illinois'=>'il','indiana'=>'in','iowa'=>'ia','kansas'=>'ks','kentucky'=>'ky','louisiana'=>'la','maine'=>'me','maryland'=>'md','massachusetts'=>'ma','michigan'=>'mi','minnesota'=>'mn','mississippi'=>'ms','missouri'=>'mo','montana'=>'mt','nebraska'=>'ne','nevada'=>'nv','new hampshire'=>'nh','new jersey'=>'nj','new mexico'=>'nm','new york'=>'ny','north carolina'=>'nc','north dakota'=>'nd','ohio'=>'oh','oklahoma'=>'ok','oregon'=>'or','pennsylvania'=>'pa','rhode island'=>'ri','south carolina'=>'sc','south dakota'=>'sd','tennessee'=>'tn','texas'=>'tx','utah'=>'ut','vermont'=>'vt','virginia'=>'va','washington'=>'wa','west virginia'=>'wv','wisconsin'=>'wi','wyoming'=>'wy'
    );

    if (isset($map[$key])) {
        return $map[$key];
    }

    if (preg_match('/^[a-z]{2}$/i', $stateName)) {
        return strtolower($stateName);
    }

    $combo = strtolower($stateName . ' ' . $countryName);
    if (strpos($combo, 'multi') !== false || strpos($combo, 'euro') !== false) {
        return '';
    }

    return strtolower(substr(preg_replace('/[^a-z0-9]/i', '', $stateName), 0, 12));
}

function mleAdvisoryResolveSkaiLotteryUrlMeta($db, $lotteryId)
{
    $lotteryId = (int)$lotteryId;
    $meta = array(
        'lottery_url' => '',
        'base_url' => '',
        'gameId' => '',
        'st' => '',
        'stn' => '',
        'gm' => '',
        'lottery_id' => $lotteryId,
    );
    if ($lotteryId <= 0) {
        return $meta;
    }

    try {
        $lotteryColsRaw = $db->getTableColumns('#__lotteries', false);
        $lotteryCols = is_array($lotteryColsRaw) ? array_keys($lotteryColsRaw) : array();
        $stateColsRaw = $db->getTableColumns('#__states', false);
        $stateCols = is_array($stateColsRaw) ? array_keys($stateColsRaw) : array();

        $select = array();
        foreach (array('lottery_id','id','game_id','gameId','gid','game_code','game_alias','name','game_name','display_name','title','alias','lottery_urls','lottery_url','url','state_id') as $c) {
            if (in_array($c, $lotteryCols, true)) {
                $select[] = 'l.' . $db->quoteName($c) . ' AS ' . $db->quoteName('l_' . $c);
            }
        }
        foreach (array('state_id','name','state_name','state_code','code','abbr','abbrev','short_code','alias','title') as $c) {
            if (in_array($c, $stateCols, true)) {
                $select[] = 's.' . $db->quoteName($c) . ' AS ' . $db->quoteName('s_' . $c);
            }
        }
        if (empty($select)) {
            return $meta;
        }

        $where = array();
        foreach (array('lottery_id','id') as $idCol) {
            if (in_array($idCol, $lotteryCols, true)) {
                $where[] = 'l.' . $db->quoteName($idCol) . ' = ' . (int)$lotteryId;
            }
        }
        if (empty($where)) {
            return $meta;
        }

        $q = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__lotteries', 'l'))
            ->where('(' . implode(' OR ', $where) . ')')
            ->setLimit(1);
        if (in_array('state_id', $lotteryCols, true) && in_array('state_id', $stateCols, true)) {
            $q->join('LEFT', $db->quoteName('#__states', 's') . ' ON l.' . $db->quoteName('state_id') . ' = s.' . $db->quoteName('state_id'));
        }
        $db->setQuery($q);
        $row = $db->loadAssoc();
        if (!is_array($row)) {
            return $meta;
        }

        foreach (array('l_lottery_urls','l_lottery_url','l_url') as $k) {
            $candidateUrl = trim((string)($row[$k] ?? ''));
            if ($candidateUrl === '') { continue; }
            $urlMeta = mleAdvisoryParseSkaiLotteryUrlMetaFromUrl($candidateUrl, $lotteryId);
            if (!empty($urlMeta['lottery_url'])) {
                $meta['lottery_url'] = (string)$urlMeta['lottery_url'];
                $meta['base_url'] = (string)$urlMeta['base_url'];
                if ($meta['gameId'] === '' && $urlMeta['gameId'] !== '') { $meta['gameId'] = (string)$urlMeta['gameId']; }
                if ($meta['st'] === '' && $urlMeta['st'] !== '') { $meta['st'] = (string)$urlMeta['st']; }
                if ($meta['stn'] === '' && $urlMeta['stn'] !== '') { $meta['stn'] = (string)$urlMeta['stn']; }
                if ($meta['gm'] === '' && $urlMeta['gm'] !== '') { $meta['gm'] = (string)$urlMeta['gm']; }
                break;
            }
        }

        foreach (array('l_game_id','l_gameId','l_gid','l_game_code','l_game_alias') as $k) {
            if ($meta['gameId'] !== '') { break; }
            $v = trim((string)($row[$k] ?? ''));
            if (mleAdvisoryIsPlausibleSkaiGameId($v)) { $meta['gameId'] = $v; break; }
        }
        if ($meta['gameId'] === '') {
            foreach (array('l_alias') as $k) {
                $v = trim((string)($row[$k] ?? ''));
                if (mleAdvisoryIsPlausibleSkaiGameId($v)) { $meta['gameId'] = $v; break; }
            }
        }

        if ($meta['gameId'] === '') {
            try {
                $snCols = function_exists('mleAdvisoryGetTableColumnsSafe')
                    ? mleAdvisoryGetTableColumnsSafe($db, '#__user_saved_numbers')
                    : array();
                $candidateCols = array();
                foreach (array('target_game_id', 'game_id') as $snCol) {
                    if (in_array($snCol, $snCols, true)) {
                        $candidateCols[] = $snCol;
                    }
                }
                $jsonCols = array();
                foreach (array('prediction_target_json', 'settings_json', 'settings') as $snJsonCol) {
                    if (in_array($snJsonCol, $snCols, true)) {
                        $jsonCols[] = $snJsonCol;
                    }
                }
                if (in_array('lottery_id', $snCols, true) && (!empty($candidateCols) || !empty($jsonCols))) {
                    $snSelect = array();
                    foreach (array_merge($candidateCols, $jsonCols) as $snSelCol) {
                        $snSelect[] = $db->quoteName($snSelCol);
                    }
                    $snQ = $db->getQuery(true)
                        ->select($snSelect)
                        ->from($db->quoteName('#__user_saved_numbers'))
                        ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                        ->setLimit(25);
                    try {
                        $fallbackUser = \Joomla\CMS\Factory::getUser();
                        $fallbackUserId = (int)($fallbackUser->id ?? 0);
                    } catch (\Throwable $e) {
                        $fallbackUserId = 0;
                    }
                    if ($fallbackUserId > 0 && in_array('user_id', $snCols, true)) {
                        $snQ->where($db->quoteName('user_id') . ' = ' . (int)$fallbackUserId);
                    }
                    foreach (array('generated_at', 'date_saved', 'id') as $orderCol) {
                        if (in_array($orderCol, $snCols, true)) {
                            $snQ->order($db->quoteName($orderCol) . ' DESC');
                            break;
                        }
                    }
                    $db->setQuery($snQ);
                    $snRows = $db->loadAssocList();
                    foreach ((array)$snRows as $snRow) {
                        foreach ($candidateCols as $snCol) {
                            $candidate = trim((string)($snRow[$snCol] ?? ''));
                            if (mleAdvisoryIsPlausibleSkaiGameId($candidate)) {
                                $meta['gameId'] = $candidate;
                                break 2;
                            }
                        }
                        foreach ($jsonCols as $snJsonCol) {
                            $decoded = json_decode((string)($snRow[$snJsonCol] ?? ''), true);
                            if (!is_array($decoded)) { continue; }
                            foreach (array('game_id', 'gameId', 'gid', 'target_game_id') as $jsonKey) {
                                $candidate = trim((string)($decoded[$jsonKey] ?? ''));
                                if (mleAdvisoryIsPlausibleSkaiGameId($candidate)) {
                                    $meta['gameId'] = $candidate;
                                    break 3;
                                }
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {

            }
        }

        foreach (array('l_game_name','l_name','l_display_name','l_title','l_alias') as $k) {
            if ($meta['gm'] !== '') { break; }
            $v = trim((string)($row[$k] ?? ''));
            if ($v !== '') { $meta['gm'] = $v; break; }
        }

        $stateName = trim((string)($meta['stn'] ?? ''));
        foreach (array('s_name','s_state_name','s_title') as $k) {
            $v = trim((string)($row[$k] ?? ''));
            if ($v !== '') { $stateName = $v; break; }
        }
        $stateCode = trim((string)($meta['st'] ?? ''));
        foreach (array('s_state_code','s_code','s_abbr','s_abbrev','s_short_code','s_alias') as $k) {
            $v = trim((string)($row[$k] ?? ''));
            if ($v !== '') { $stateCode = $v; break; }
        }
        if ($stateCode === '') {
            $stateCode = mleAdvisoryNormalizeStateCodeForSkai($stateName, '');
        } elseif (!preg_match('/^[a-z]{2}$/i', $stateCode)) {
            $stateCode = mleAdvisoryNormalizeStateCodeForSkai($stateCode, '');
        } else {
            $stateCode = strtolower($stateCode);
        }

        if ($stateName === '' && mylottoexpertIsKnownMultiStateLottery((string)$meta['gm'], (string)$meta['gameId'], '')) {
            $stateName = 'United States';
        }
        if ($stateCode === '' && $stateName === 'United States') {
            $stateCode = 'us';
        }

        $meta['gameId'] = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$meta['gameId'], 0, 50));
        if (!mleAdvisoryIsPlausibleSkaiGameId($meta['gameId'])) {
            $meta['gameId'] = '';
        }
        $meta['st'] = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$stateCode, 0, 20));
        $meta['stn'] = $stateName !== '' ? $stateName : (string)($meta['stn'] ?? '');
        $meta['gm'] = $meta['gm'] !== '' ? $meta['gm'] : ('Lottery ' . $lotteryId);
    } catch (\Throwable $e) {
        return $meta;
    }

    return $meta;
}

function mleAdvisoryValidateSkaiLotteryUrlMeta(array $meta)
{

    $missing = array();
    $gameId = trim((string)($meta['gameId'] ?? ''));
    if (!mleAdvisoryIsPlausibleSkaiGameId($gameId)) {
        $missing[] = 'gameId';
    }
    return array(
        'ok' => empty($missing),
        'missing' => $missing,
    );
}

function mleAdvisoryBuildCanonicalSkaiLotteryUrl($db, $lotteryId, array $extraArgs = array(), $hash = '')
{

    $lotteryId = (int)$lotteryId;
    $meta = mleAdvisoryResolveSkaiLotteryUrlMeta($db, $lotteryId);
    $gameId = trim((string)($meta['gameId'] ?? ''));
    $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr($gameId, 0, 50));

    $baseUrl = trim((string)($meta['base_url'] ?? ''));
    if ($baseUrl === '') {
        $baseUrl = mleAdvisoryResolveSkaiPageBaseUrl($db);
    }

    $queryArgs = array('gameId' => $gameId);

    /* [[MLE_V151_SKAI_RETURN_CONTEXT_LOCK]]
     * Preserve the exact MyLottoExpert lottery context that launched SKAI.
     * This only affects dashboard routing after a run; it does not change
     * prediction generation, saved numbers, scoring, or access control.
     */
    if ($lotteryId > 0) {
        $queryArgs['mle_return_lottery_id'] = $lotteryId;
        $queryArgs['mle_focus_lottery_id'] = $lotteryId;
        $queryArgs['mle_return_dashboard_lottery_id'] = $lotteryId;
    }

    foreach (array('st', 'stn', 'gm') as $displayKey) {
        $displayValue = trim((string)($meta[$displayKey] ?? ''));
        if ($displayValue !== '') {
            $queryArgs[$displayKey] = $displayValue;
        }
    }

    foreach ($extraArgs as $k => $v) {
        if ($k === '' || $v === null) { continue; }
        if (is_string($v) && trim($v) === '') { continue; }
        $queryArgs[$k] = $v;
    }

    $url = $baseUrl . '?' . http_build_query($queryArgs, '', '&', PHP_QUERY_RFC3986);
    $hash = trim((string)$hash);
    if ($hash !== '') {
        $url .= '#' . ltrim($hash, '#');
    }
    return $url;
}

function mleAdvisoryResolveSkaiBatchOpenUrl($db, $lotteryId, $batchId, $batchType = '')
{
    $lotteryId = (int)$lotteryId;
    $batchId = (int)$batchId;
    $batchType = trim((string)$batchType);
    $isRegularBatch = ($batchType !== '' && stripos($batchType, 'regular') !== false);
    $requiredAction = $isRegularBatch ? 'regular_9_batch' : 'precision_batch';
    $openAction = $isRegularBatch ? 'regular_9_batch' : 'precision_batch';
    $extraArgs = array(
        'mle_skai_batch' => 1,
        'mle_skai_bridge' => 1,
        'mle_guided_mode' => 'required',
        'mle_required_action' => $requiredAction,
        'mle_cancel_allowed' => 1,
        'mle_command_source' => 'mylottoexpert',
        'mle_batch_enforcement' => 'guided_locked',
        'mle_global_batch' => 1,
        'mle_batch_scope' => 'exact_lottery',
        'batch_id' => $batchId,
        'lottery_id' => $lotteryId,
        'open' => $openAction,
        'source' => 'mylottoexpert',
    );
    if (!$isRegularBatch) {
        $extraArgs['mle_precision_batch'] = 1;
    }
    if ($batchType !== '') {
        $extraArgs['mle_batch_type'] = strtolower(preg_replace('/[^a-z0-9]+/i', '_', $batchType));
    }

    return mleAdvisoryBuildCanonicalSkaiLotteryUrl($db, $lotteryId, $extraArgs);
}

function mleAdvisoryResolveSkaiRegularRunUrl($db, $lotteryId)
{
    $lotteryId = (int)$lotteryId;
    return mleAdvisoryBuildCanonicalSkaiLotteryUrl($db, $lotteryId, array(
        'mle_guided_mode' => 'global_learning',
        'mle_command_source' => 'mylottoexpert',
        'source' => 'mylottoexpert',
        'mle_single_mode' => 'best_global_settings',
        'mle_single_source' => 'global_learning'
    ));
}

function mylottoexpertResolveBestHiveSettingsForSkaiRun($db, $gameId, $lotteryId, $predictionFamily, $predictionType)
{
    $gameId          = (string)$gameId;
    $lotteryId       = (int)$lotteryId;
    $predictionFamily = strtolower(trim((string)$predictionFamily));
    $predictionType   = strtolower(trim((string)$predictionType));

    $empty = array(
        'found'                  => false,
        'source'                 => 'stable_default',
        'settings'               => array(),
        'confidence'             => 'none',
        'evidence_count'         => 0,
        'average_learning_score' => 0.0,
        'best_learning_score'    => 0.0,
        'latest_evaluated_at'    => '',
        'hive_settings_fingerprint' => '',
        'reason'                 => 'no_reliable_hive_learned_settings_available',
    );

    if ($gameId === '' && $lotteryId <= 0) {
        $empty['reason'] = 'no_game_id_or_lottery_id';
        return $empty;
    }

    $profileTable = $db->getPrefix() . 'skai_shared_learning_profiles';
    try {
        $tables = $db->getTableList();
    } catch (\Throwable $e) {
        $tables = array();
    }
    if (!in_array($profileTable, $tables, true)) {
        $empty['reason'] = 'shared_learning_profile_table_missing';
        return $empty;
    }

    $profileCols = array();
    try {
        $rawCols = $db->getTableColumns('#__skai_shared_learning_profiles', false);
        $profileCols = is_array($rawCols) ? array_keys($rawCols) : array();
    } catch (\Throwable $e) {
        $profileCols = array();
    }

    $candidates = array();

    if ($gameId !== '') {
        try {
            $q = $db->getQuery(true)
                ->select('*')
                ->from($db->quoteName('#__skai_shared_learning_profiles'))
                ->where($db->quoteName('method_key') . ' = ' . $db->quote('skai'))
                ->where($db->quoteName('is_active') . ' = 1')
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->order($db->quoteName('updated_at') . ' DESC')
                ->setLimit(5);
            $db->setQuery($q);
            $rows = $db->loadAssocList();
            if (is_array($rows)) {
                foreach ($rows as $r) { $r['_resolve_source'] = 'exact_game'; $candidates[] = $r; }
            }
        } catch (\Throwable $e) {   }
    }

    if (empty($candidates) && $lotteryId > 0) {
        try {
            $q = $db->getQuery(true)
                ->select('*')
                ->from($db->quoteName('#__skai_shared_learning_profiles'))
                ->where($db->quoteName('method_key') . ' = ' . $db->quote('skai'))
                ->where($db->quoteName('is_active') . ' = 1')
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->order($db->quoteName('updated_at') . ' DESC')
                ->setLimit(5);
            $db->setQuery($q);
            $rows = $db->loadAssocList();
            if (is_array($rows)) {
                foreach ($rows as $r) { $r['_resolve_source'] = 'lottery_fallback'; $candidates[] = $r; }
            }
        } catch (\Throwable $e) {   }
    }

    if (empty($candidates) && $predictionFamily !== '') {
        try {
            $q = $db->getQuery(true)
                ->select('*')
                ->from($db->quoteName('#__skai_shared_learning_profiles'))
                ->where($db->quoteName('method_key') . ' = ' . $db->quote('skai'))
                ->where($db->quoteName('is_active') . ' = 1')
                ->order($db->quoteName('updated_at') . ' DESC')
                ->setLimit(5);
            $db->setQuery($q);
            $rows = $db->loadAssocList();
            if (is_array($rows)) {
                foreach ($rows as $r) { $r['_resolve_source'] = 'global_family'; $candidates[] = $r; }
            }
        } catch (\Throwable $e) {   }
    }

    if (empty($candidates)) {
        $empty['reason'] = 'no_active_profile_found';
        return $empty;
    }

    $best = null;
    foreach ($candidates as $c) {
        if ($best === null) { $best = $c; continue; }
        $bestRuns = (int)($best['evidence_runs'] ?? 0);
        $cRuns    = (int)($c['evidence_runs'] ?? 0);
        if ($cRuns > $bestRuns) { $best = $c; continue; }
        if ($cRuns === $bestRuns && strcmp((string)($c['updated_at'] ?? ''), (string)($best['updated_at'] ?? '')) > 0) { $best = $c; }
    }

    if ($best === null) {
        $empty['reason'] = 'candidate_selection_failed';
        return $empty;
    }

    $profileJson = (string)($best['profile_json'] ?? '');
    $profile = array();
    if ($profileJson !== '') {
        $decoded = json_decode($profileJson, true);
        if (is_array($decoded)) { $profile = $decoded; }
    }

    $settings = array();

    if (!empty($profile['global_settings_intelligence']['recommended_settings'])) {
        $settings = (array)$profile['global_settings_intelligence']['recommended_settings'];
    } elseif (!empty($profile['settings'])) {
        $settings = (array)$profile['settings'];
    } elseif (!empty($profile['winning_profile'])) {
        $settings = (array)$profile['winning_profile'];
    } elseif (!empty($profile['best_profile'])) {
        $settings = (array)$profile['best_profile'];
    }

    if (empty($settings)) {
        $empty['reason'] = 'profile_found_but_no_usable_settings';
        return $empty;
    }

    $evidenceRuns = (int)($best['evidence_runs'] ?? 0);
    $updatedAt    = (string)($best['updated_at'] ?? '');
    $fingerprint  = (string)($best['settings_fingerprint'] ?? '');
    $resolveSource = (string)($best['_resolve_source'] ?? 'exact_game');

    if ($evidenceRuns >= 20) { $confidence = 'high'; }
    elseif ($evidenceRuns >= 5) { $confidence = 'medium'; }
    elseif ($evidenceRuns >= 1) { $confidence = 'low'; }
    else { $confidence = 'none'; }

    if ($confidence === 'none') {
        $empty['reason'] = 'insufficient_evidence';
        return $empty;
    }

    $avgLearningScore  = 0.0;
    $bestLearningScore = 0.0;
    $perfTable = $db->getPrefix() . 'skai_learning_performance';
    if (in_array($perfTable, $tables, true)) {
        try {
            $q2 = $db->getQuery(true)
                ->select('AVG(' . $db->quoteName('learning_score') . ') AS avg_score, MAX(' . $db->quoteName('learning_score') . ') AS best_score')
                ->from($db->quoteName('#__skai_learning_performance'))
                ->where($db->quoteName('is_active') . ' IS NULL OR ' . $db->quoteName('is_active') . ' = 1')
                ->setLimit(1);
            if ($gameId !== '') {
                $q2->where('(' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameId) . ' OR ' . $db->quoteName('game_id') . ' = ' . $db->quote($gameId) . ')');
            } elseif ($lotteryId > 0) {
                $q2->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId);
            }
            $db->setQuery($q2);
            $perfRow = $db->loadAssoc();
            if (is_array($perfRow)) {
                $avgLearningScore  = round((float)($perfRow['avg_score'] ?? 0.0), 8);
                $bestLearningScore = round((float)($perfRow['best_score'] ?? 0.0), 8);
            }
        } catch (\Throwable $e) {   }
    }

    return array(
        'found'                  => true,
        'source'                 => 'hive_best',
        'source_detail'          => $resolveSource,
        'settings'               => $settings,
        'confidence'             => $confidence,
        'evidence_count'         => $evidenceRuns,
        'average_learning_score' => $avgLearningScore,
        'best_learning_score'    => $bestLearningScore,
        'latest_evaluated_at'    => $updatedAt,
        'hive_settings_fingerprint' => $fingerprint,
        'reason'                 => 'hive_best_settings_resolved',
    );
}

function mleAdvisoryResolveCoreAiPageBaseUrl($db)
{
    $siteBase = rtrim(\Joomla\CMS\Uri\Uri::base(), '/');
    if (defined('MLE_CORE_AI_PAGE_PATH')) {
        $configured = trim((string)constant('MLE_CORE_AI_PAGE_PATH'));
        if ($configured !== '') {
            if (preg_match('#^https?://#i', $configured)) {
                return $configured;
            }
            return $siteBase . '/' . ltrim($configured, '/');
        }
    }
    return $siteBase . '/ai-powered-predictions';
}

function mleAdvisoryBase64UrlEncode($value)
{
    return rtrim(strtr(base64_encode((string)$value), '+/', '-_'), '=');
}

function mleAdvisoryBuildCoreAiBatchPlanJson(array $profiles, array $blends)
{
    $cleanProfiles = array();
    foreach ($profiles as $profile) {
        $profile = strtolower(preg_replace('/[^a-z0-9_-]/i', '', (string)$profile));
        if (!in_array($profile, array('balanced','explorative','conservative'), true)) {
            $profile = 'balanced';
        }
        if (!in_array($profile, $cleanProfiles, true)) {
            $cleanProfiles[] = $profile;
        }
    }
    if (empty($cleanProfiles)) { $cleanProfiles = array('balanced'); }

    $cleanBlends = array();
    foreach ($blends as $blend) {
        $blend = max(0, min(100, (int)$blend));
        if (!in_array($blend, $cleanBlends, true)) {
            $cleanBlends[] = $blend;
        }
    }
    if (empty($cleanBlends)) { $cleanBlends = array(25,50,75); }

    $out = array();
    foreach ($cleanProfiles as $profile) {
        foreach ($cleanBlends as $blend) {
            if (count($out) >= 9) { break 2; }
            $focusLabel = $profile === 'explorative' ? 'Explorative Focus' : ($profile === 'conservative' ? 'Conservative Focus' : 'Balanced Focus');
            $out[] = array(
                'profile' => $profile,
                'blend_pct' => $blend,
                'label' => $focusLabel . ' x Blend ' . $blend . '%'
            );
        }
    }
    return json_encode($out, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
}

function mleAdvisoryBuildCanonicalCoreAiLotteryUrl($db, $lotteryId, array $extraArgs = array(), $hash = '')
{
    $lotteryId = (int)$lotteryId;
    $meta = mleAdvisoryResolveSkaiLotteryUrlMeta($db, $lotteryId);
    $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($meta['gameId'] ?? ''), 0, 50));
    $baseUrl = mleAdvisoryResolveCoreAiPageBaseUrl($db);
    $queryArgs = array('gameId' => $gameId);
    foreach (array('st','stn','gm') as $displayKey) {
        $displayValue = trim((string)($meta[$displayKey] ?? ''));
        if ($displayValue !== '') { $queryArgs[$displayKey] = $displayValue; }
    }
    foreach ($extraArgs as $k => $v) {
        if ($k === '' || $v === null) { continue; }
        if (is_string($v) && trim($v) === '') { continue; }
        $queryArgs[$k] = $v;
    }
    $url = $baseUrl . '?' . http_build_query($queryArgs, '', '&', PHP_QUERY_RFC3986);
    $hash = trim((string)$hash);
    if ($hash !== '') { $url .= '#' . ltrim($hash, '#'); }
    return $url;
}

function mleAdvisoryResolveCoreAiRangeTestUrl($db, $lotteryId, array $profiles = array('balanced','explorative','conservative'), array $blends = array(25,50,75), $autoRun = false)
{
    $planJson = mleAdvisoryBuildCoreAiBatchPlanJson($profiles, $blends);
    $extra = array(
        'core_ai_batch_plan' => mleAdvisoryBase64UrlEncode($planJson),
        'core_ai_batch_uuid' => 'mle_core_' . substr(hash('sha256', (string)$lotteryId . '|' . $planJson . '|' . time()), 0, 24),
        'source' => 'mylottoexpert',
        'open' => 'core_ai_precision_batch'
    );
    if ($autoRun) { $extra['core_ai_autorun'] = '1'; }
    return mleAdvisoryBuildCanonicalCoreAiLotteryUrl($db, (int)$lotteryId, $extra, 'core-ai-precision-lock-intro');
}

function mleAdvisoryReadIncomingSkaiRequest($app)
{
    $get = $app->input->get;
    $aliases = array(
        'gameId' => array('gameId', 'game', 'gameName', 'lottery'),
        'st' => array('st', 'state'),
        'stn' => array('stn', 'stateName'),
        'gm' => array('gm', 'gameName', 'game'),
        'batch_id' => array('batch_id', 'batchId', 'batch'),
        'run_id' => array('run_id', 'runId'),
    );
    $result = array(
        'gameId' => '',
        'st' => '',
        'stn' => '',
        'gm' => '',
        'batch_id' => 0,
        'run_id' => 0,
        'lottery_id' => (int)$get->getInt('lottery_id', 0),
        'open' => trim((string)$get->getCmd('open', '')),
        'mle_skai_batch' => (int)$get->getInt('mle_skai_batch', 0),
        'mle_precision_batch' => (int)$get->getInt('mle_precision_batch', 0),
        'param_sources' => array(),
    );

    foreach ($aliases as $canonical => $keys) {
        foreach ($keys as $key) {
            if ($canonical === 'batch_id' || $canonical === 'run_id') {
                $value = (int)$get->getInt($key, 0);
                if ($value > 0) {
                    $result[$canonical] = $value;
                    $result['param_sources'][$canonical] = $key;
                    break;
                }
                continue;
            }
            $value = trim((string)$get->getString($key, ''));
            if ($value !== '') {
                $result[$canonical] = $value;
                $result['param_sources'][$canonical] = $key;
                break;
            }
        }
    }

    $result['gameId'] = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$result['gameId'], 0, 50));
    $result['st'] = strtolower(preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$result['st'], 0, 20)));
    $result['stn'] = trim((string)$result['stn']);
    $result['gm'] = trim((string)$result['gm']);

    return $result;
}

function mleAdvisoryResolveIncomingSkaiRequest($db, $app)
{
    $request = mleAdvisoryReadIncomingSkaiRequest($app);
    $request['matched_lottery_id'] = 0;
    $request['matched_game_id'] = '';
    $request['matched_state_code'] = '';
    $request['matched_state_name'] = '';
    $request['matched_game_name'] = '';

    if ($request['gameId'] === '' && $request['st'] === '' && $request['stn'] === '' && $request['gm'] === '') {
        return $request;
    }

    try {
        $lotteryColsRaw = $db->getTableColumns('#__lotteries', false);
        $lotteryCols = is_array($lotteryColsRaw) ? array_keys($lotteryColsRaw) : array();
        $stateColsRaw = $db->getTableColumns('#__states', false);
        $stateCols = is_array($stateColsRaw) ? array_keys($stateColsRaw) : array();
        if (empty($lotteryCols)) {
            return $request;
        }

        $select = array();
        foreach (array('lottery_id','id','game_id','gameId','gid','game_code','game_alias','name','game_name','display_name','title','alias','state_id') as $c) {
            if (in_array($c, $lotteryCols, true)) {
                $select[] = 'l.' . $db->quoteName($c) . ' AS ' . $db->quoteName('l_' . $c);
            }
        }
        foreach (array('state_id','name','state_name','state_code','code','abbr','abbrev','short_code','alias','title') as $c) {
            if (in_array($c, $stateCols, true)) {
                $select[] = 's.' . $db->quoteName($c) . ' AS ' . $db->quoteName('s_' . $c);
            }
        }
        if (empty($select)) {
            return $request;
        }

        $query = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__lotteries', 'l'))
            ->setLimit(250);
        if (in_array('state_id', $lotteryCols, true) && in_array('state_id', $stateCols, true)) {
            $query->join('LEFT', $db->quoteName('#__states', 's') . ' ON l.' . $db->quoteName('state_id') . ' = s.' . $db->quoteName('state_id'));
        }
        $db->setQuery($query);
        $rows = $db->loadAssocList();
    } catch (\Throwable $e) {
        $rows = array();
    }

    if (!is_array($rows) || empty($rows)) {
        return $request;
    }

    $wantedGameId = strtoupper(trim((string)$request['gameId']));
    $wantedStateCode = strtolower(trim((string)$request['st']));
    $wantedStateName = strtolower(trim((string)$request['stn']));
    $wantedGameName = strtolower(trim((string)$request['gm']));

    foreach ($rows as $row) {
        $rowLotteryId = (int)($row['l_lottery_id'] ?? $row['l_id'] ?? 0);
        if ($rowLotteryId <= 0) {
            continue;
        }
        $rowGameId = '';
        foreach (array('l_game_id','l_gameId','l_gid','l_game_code','l_game_alias') as $k) {
            $candidate = trim((string)($row[$k] ?? ''));
            if ($candidate !== '') { $rowGameId = $candidate; break; }
        }
        $rowGameName = '';
        foreach (array('l_game_name','l_name','l_display_name','l_title','l_alias') as $k) {
            $candidate = trim((string)($row[$k] ?? ''));
            if ($candidate !== '') { $rowGameName = $candidate; break; }
        }
        $rowStateName = '';
        foreach (array('s_name','s_state_name','s_title') as $k) {
            $candidate = trim((string)($row[$k] ?? ''));
            if ($candidate !== '') { $rowStateName = $candidate; break; }
        }
        $rowStateCode = '';
        foreach (array('s_state_code','s_code','s_abbr','s_abbrev','s_short_code','s_alias') as $k) {
            $candidate = trim((string)($row[$k] ?? ''));
            if ($candidate !== '') { $rowStateCode = strtolower($candidate); break; }
        }
        if ($rowStateCode === '' && $rowStateName !== '') {
            $rowStateCode = mleAdvisoryNormalizeStateCodeForSkai($rowStateName, '');
        }

        $gameIdMatch = ($wantedGameId !== '' && strtoupper($rowGameId) === $wantedGameId);
        $gameNameMatch = ($wantedGameName !== '' && strtolower($rowGameName) === $wantedGameName);
        $stateCodeMatch = ($wantedStateCode !== '' && $rowStateCode === $wantedStateCode);
        $stateNameMatch = ($wantedStateName !== '' && strtolower($rowStateName) === $wantedStateName);

        if (!$gameIdMatch && !$gameNameMatch) {
            continue;
        }
        if ($wantedStateCode !== '' && !$stateCodeMatch && $wantedStateName !== '' && !$stateNameMatch) {
            continue;
        }
        if ($wantedStateName !== '' && !$stateNameMatch && $wantedStateCode !== '' && !$stateCodeMatch) {
            continue;
        }

        $request['matched_lottery_id'] = $rowLotteryId;
        $request['matched_game_id'] = $rowGameId;
        $request['matched_state_code'] = $rowStateCode;
        $request['matched_state_name'] = $rowStateName;
        $request['matched_game_name'] = $rowGameName;
        if ($request['lottery_id'] <= 0) {
            $request['lottery_id'] = $rowLotteryId;
        }
        break;
    }

    return $request;
}

function mleAdvisoryBuildHistoryHorizonSkaiBatchPlan(array $summary, array $precisionLock = array(), array $settingsAdv = array())
{
    $runCount = (int)($summary['total_runs'] ?? ($precisionLock['run_count'] ?? 0));
    $drawCount = (int)($summary['scored_draws'] ?? 0);
    $clusterCount = (int)($summary['true_cluster_support'] ?? ($precisionLock['true_cluster_support'] ?? 0));

    if ($runCount < 18 || $drawCount < 2) {
        return array(
            'has_recommendation' => false,
            'fail_reason' => 'History Window is not ready yet. LottoExpert first needs at least 2 completed draw cycles and about 18 scored runs so the first window test is not based on a single draw.'
        );
    }

    $currentValue = '';
    $settingKey = trim((string)($settingsAdv['setting'] ?? ''));
    if (in_array($settingKey, array('skai_window_size','draws_used','draws_analyzed','skip_window','window_size'), true)) {
        $currentValue = trim((string)($settingsAdv['current_value'] ?? ''));
    }
    if ($currentValue === '' && isset($precisionLock['control_value']) && is_numeric($precisionLock['control_value'])) {
        $currentValue = (string)((int)round((float)$precisionLock['control_value']));
    }
    if ($currentValue === '' || !is_numeric($currentValue)) {
        $currentValue = '100';
    }

    $horizons = array(25, 50, 100, 150, 200, 300, 500, 1000);
    $labels = array(
        25  => 'Near-history window',
        50  => 'Short-term window',
        100 => 'Balanced recent window',
        150 => 'Medium window',
        200 => 'Medium-long window',
        300 => 'Long window',
        500 => 'Deep-history window',
        1000 => 'Long/full-history proxy'
    );

    $batchRunLabels = array('Control - Current History Window');
    $batchRunValues = array((string)((int)round((float)$currentValue)));
    $batchRunRoles = array('control');
    foreach ($horizons as $h) {
        $batchRunLabels[] = 'Test - History Window ' . (string)$h . ' draws (' . (string)$labels[$h] . ')';
        $batchRunValues[] = (string)$h;
        $batchRunRoles[] = 'explore';
    }

    $evidenceLine = $runCount . ' scored runs across ' . $drawCount . ' completed draw cycle' . ($drawCount === 1 ? '' : 's') . '. ';
    $evidenceLine .= 'Cluster support: ' . $clusterCount . '. This batch is for History Window discovery, not Settings Precision.';

    return array(
        'has_recommendation' => true,
        'title' => 'History Window 9-Run AI Settings Test',
        'summary' => 'This batch tests how far back AI should look by comparing history windows from 25 to 1,000 past draws. It is a research/search run, not a prediction run.',
        'test_plan' => 'Create 9 AI analysis window-search runs for this lottery. Run 1 keeps the current history window as the control. Runs 2 through 9 test broad history horizons: 25, 50, 100, 150, 200, 300, 500, and 1000 draws. Do not treat these runs as playable predictions.',
        'advanced_explanation' => 'More draws are not automatically better. This batch compares responsiveness versus stability so LottoExpert can learn whether this lottery is behaving better with short, medium, long, or deeper history windows.',
        'guardrail' => 'Important: this is a window-narrowing search only. Do not use these numbers as predictions. The purpose is to test which draw-history range performs best so future prediction runs can use a better-supported window.',
        'evidence_line' => $evidenceLine,
        'batch_purpose' => 'Explore whether a draw-history range needs adjustment as optional admin diagnostics. This does not create a final prediction and does not gate Settings Precision.',
        'locked_settings' => 'Keep all other AI settings stable while only the history window changes.',
        'test_variable' => 'History Window',
        'setting_key' => 'skai_window_size',
        'setting_key_aliases' => array('skai_window_size','draws_used','skip_window','window_size'),
        'control_run' => 'Control - Current History Window (' . (string)((int)round((float)$currentValue)) . ' draws).',
        'control_source' => 'Current AI baseline',
        'batch_runs' => $batchRunLabels,
        'batch_run_values' => $batchRunValues,
        'batch_run_roles' => $batchRunRoles,
        'what_it_proves' => 'Whether this lottery is currently responding better to short, medium, long, or deeper draw-history windows.',
        'preferred_use' => 'Best when the best history window is not yet supported or when the draw-history prediction history needs broader comparison.',
        'range_basis' => 'History Window',
        'current_range' => '25 to 1000 draws',
        'range_min' => 25,
        'range_max' => 1000,
        'recommended_value' => 'Broad horizon comparison',
        'beginner_explanation' => 'This tests the History Window Range as optional admin diagnostics. It compares several history depths so LottoExpert can learn whether recent, medium, or deeper history is useful. This is not a prediction batch and should not be played as a prediction.',
        'milestone_supported' => 'Discover the best AI history window for this lottery.',
        'batch_type' => 'History Horizon Discovery Settings Test'
    );
}


if (!function_exists('mylottoexpertV90ParseAdminBatchWindowValues')) {
    function mylottoexpertV90ParseAdminBatchWindowValues($raw, $maxCount = 1000)
    {
        $out = array();
        $raw = trim((string)$raw);
        if ($raw === '') { return $out; }
        $parts = preg_split('/[^0-9]+/', $raw);
        foreach ((array)$parts as $part) {
            $v = (int)$part;
            if ($v <= 0) { continue; }
            if ($v > 5000) { $v = 5000; }
            $out[] = (string)$v;
            if (count($out) >= (int)$maxCount) { break; }
        }
        return $out;
    }
}

if (!function_exists('mylottoexpertV90BuildAdminWindowBatchPlan')) {
    function mylottoexpertV90BuildAdminWindowBatchPlan(array $basePlan, $runCount, array $customWindows = array())
    {
        $runCount = (int)$runCount;
        if ($runCount <= 0) { $runCount = 9; }
        if ($runCount > 1000) { $runCount = 1000; }
        $values = array();
        foreach ((array)$customWindows as $windowValue) {
            $windowValue = (int)$windowValue;
            if ($windowValue <= 0) { continue; }
            if ($windowValue > 5000) { $windowValue = 5000; }
            $values[] = (string)$windowValue;
            if (count($values) >= 1000) { break; }
        }
        if (!empty($values)) {
            $runCount = count($values);
        } else {
            /* [[MLE_ELITE_HISTORY_WINDOW_SPREAD_V1]]
               Scientific history-window campaigns must cover the usable search space, not 1..N.
               Generate deterministic log-spaced windows from 25 to 1000 so large admin batches
               test recent, middle, and deep history with dense unique coverage. */
            if ($runCount === 1) {
                $values[] = '250';
            } else {
                $minWindow = 25.0;
                $maxWindow = 1000.0;
                $seenWindows = array();
                for ($i = 0; $i < $runCount; $i++) {
                    $ratio = ($runCount <= 1) ? 0.0 : ($i / max(1, $runCount - 1));
                    $candidate = (int)round($minWindow * pow($maxWindow / $minWindow, $ratio));
                    if ($candidate < 25) { $candidate = 25; }
                    if ($candidate > 1000) { $candidate = 1000; }
                    while (isset($seenWindows[(string)$candidate]) && $candidate < 1000) { $candidate++; }
                    while (isset($seenWindows[(string)$candidate]) && $candidate > 25) { $candidate--; }
                    if (isset($seenWindows[(string)$candidate])) { continue; }
                    $seenWindows[(string)$candidate] = true;
                    $values[] = (string)$candidate;
                }
                if (empty($values)) { $values = array('25','50','100','250','500','750','1000'); }
                $runCount = count($values);
            }
        }
        $labels = array();
        $roles = array();
        foreach ($values as $idx => $windowValue) {
            $labels[] = 'Window Run ' . (string)($idx + 1) . ' - History Window ' . (string)$windowValue . ' draws';
            $roles[] = 'horizon';
        }
        $plan = $basePlan;
        $plan['has_recommendation'] = true;
        $plan['title'] = 'Admin History Window ' . (string)$runCount . '-Run AI Batch';
        $plan['summary'] = 'Admin-created history-window batch using the requested draw-window values/count.';
        $plan['test_plan'] = 'Create ' . (string)$runCount . ' AI history-window runs for this lottery.';
        $plan['guardrail'] = 'Admin history-window diagnostic batch. Use this to test draw-history windows, then score completed rows normally after the official draw.';
        $plan['evidence_line'] = 'Admin selected a custom history-window batch size/value set.';
        $plan['batch_purpose'] = 'Admin diagnostics for history-window coverage.';
        $plan['locked_settings'] = 'Keep all other AI settings stable while only the history window changes.';
        $plan['test_variable'] = 'History Window';
        $plan['setting_key'] = 'skai_window_size';
        $plan['setting_key_aliases'] = array('skai_window_size','draws_used','skip_window','window_size');
        $plan['control_run'] = '';
        $plan['control_source'] = 'Admin custom window batch';
        $plan['batch_runs'] = $labels;
        $plan['batch_run_values'] = $values;
        $plan['batch_run_roles'] = $roles;
        $plan['range_basis'] = 'Admin selected History Window values';
        $plan['range_min'] = (float)min(array_map('intval', $values));
        $plan['range_max'] = (float)max(array_map('intval', $values));
        $plan['recommended_value'] = 'Admin custom window batch';
        $plan['preferred_use'] = 'Admin-created history-window batch for broad testing.';
        $plan['milestone_supported'] = 'Admin custom history-window prediction history';
        $plan['batch_type'] = 'Admin History Window ' . (string)$runCount . '-Run Batch';
        $plan['no_control_run'] = true;
        $plan['_mle_admin_custom_batch'] = true;
        $plan['_mle_admin_custom_run_count'] = $runCount;
        $plan['_mle_admin_allow_duplicate_test_values'] = false;
        return $plan;
    }
}

if (!function_exists('mylottoexpertV90ExpandAdminRegularBatchPlan')) {
    function mylottoexpertV90ExpandAdminRegularBatchPlan(array $plan, $runCount)
    {
        $runCount = (int)$runCount;
        if ($runCount <= 0) { $runCount = 9; }
        if ($runCount > 1000) { $runCount = 1000; }
        $baseLabels = is_array($plan['batch_runs'] ?? null) ? array_values($plan['batch_runs']) : array();
        $baseValues = is_array($plan['batch_run_values'] ?? null) ? array_values($plan['batch_run_values']) : array();
        $baseRoles  = is_array($plan['batch_run_roles'] ?? null) ? array_values($plan['batch_run_roles']) : $baseValues;
        if (empty($baseLabels) || empty($baseValues)) { return $plan; }
        $labels = array();
        $values = array();
        $roles = array();
        $baseCount = min(count($baseLabels), count($baseValues));
        for ($i = 0; $i < $runCount; $i++) {
            $baseIdx = $i % $baseCount;
            $cycle = (int)floor($i / $baseCount) + 1;
            $labels[] = 'Run ' . (string)($i + 1) . ' - ' . (string)$baseLabels[$baseIdx] . ($cycle > 1 ? ' / Cycle ' . (string)$cycle : '');
            $values[] = (string)$baseValues[$baseIdx];
            $roles[] = isset($baseRoles[$baseIdx]) ? (string)$baseRoles[$baseIdx] : (string)$baseValues[$baseIdx];
        }
        $plan['title'] = 'Admin Shared AI Learning AI Testing ' . (string)$runCount . '-Run Campaign';
        $plan['summary'] = 'Admin-only Shared AI Learning AI Testing campaign using the champion-centered profile/window/blend contract repeated across the requested run count.';
        $plan['guardrail'] = 'Admin Shared AI Learning AI Testing only. This builds prediction history around the best-known champion across draw cycles; it should not replace the user-facing champion prediction lane.';
        $plan['batch_runs'] = $labels;
        $plan['batch_run_values'] = $values;
        $plan['batch_run_roles'] = $roles;
        $plan['batch_type'] = 'Admin Shared AI Learning AI Testing ' . (string)$runCount . '-Run Campaign';
        $plan['preferred_use'] = 'Admin-created Shared AI Learning AI Testing campaign for prediction history building and narrowing around the champion.';
        $plan['_mle_admin_custom_batch'] = true;
        $plan['_mle_hive_research_admin_only'] = true;
        $plan['_mle_hive_research_campaign'] = true;
        $plan['_mle_prediction_lane'] = 'admin_hive_research';
        $plan['_mle_admin_custom_run_count'] = $runCount;
        $plan['_mle_admin_allow_duplicate_test_values'] = true;
        return $plan;
    }
}

function mleAdvisoryBuildRecommendedSkaiBatchTest(array $precisionLock, array $settingsAdv, array $summary, array $currentLockedSettings = array()) {
    $runCount = (int)($precisionLock['run_count'] ?? 0);
    $drawCount = (int)($summary['scored_draws'] ?? 0);
    $trueClusterCount = (int)($summary['true_cluster_support'] ?? ($precisionLock['true_cluster_support'] ?? 0));
    $hasRange = !empty($precisionLock['has_range']);
    $stage = (string)($precisionLock['stage'] ?? 'broad_testing');
    $rangeMin = (float)($precisionLock['range_min'] ?? 0.0);
    $rangeMax = (float)($precisionLock['range_max'] ?? 100.0);
    $controlLabel = trim((string)($precisionLock['control_label'] ?? 'primary setting'));
    if ($controlLabel === '') { $controlLabel = 'primary setting'; }
    $hasAdvice = !empty($settingsAdv['has_advice']);
    $settingLabel = trim((string)($settingsAdv['setting_label'] ?? ''));
    $settingKey = trim((string)($settingsAdv['setting'] ?? ''));
    $currentValue = trim((string)($settingsAdv['current_value'] ?? ''));
    $suggestedValue = trim((string)($settingsAdv['suggested_value'] ?? ''));
    $lockReady = !empty($currentLockedSettings['has_active_lock']) || in_array((string)($currentLockedSettings['status'] ?? ''), array('Locked for Testing','Precision Focus Candidate','Elite Baseline'), true);
    $controlSource = $lockReady ? 'Current Locked Settings' : 'Current Best Settings';
    $controlRunName = $lockReady ? 'Control - Current Locked Settings' : 'Control - Current Best Settings';
    $rMinInt = (int)round($rangeMin);
    $rMaxInt = (int)round($rangeMax);
    $empty = array(
        'has_recommendation'=>false,
        'title'=>'Controlled AI Settings Test',
        'summary'=>'Not enough saved scored runs yet for a controlled AI batch test in this lottery.',
        'test_plan'=>'',
        'guardrail'=>'Keep saving and scoring runs for this lottery first.',
        'evidence_line'=>$runCount . ' saved scored runs and ' . $drawCount . ' completed draw date' . ($drawCount === 1 ? '' : 's') . '.',
        'batch_purpose'=>'',
        'locked_settings'=>'',
        'test_variable'=>'',
        'setting_key'=>'',
        'control_run'=>'',
        'control_source'=>$controlSource,
        'batch_runs'=>array(),
        'batch_run_values'=>array(),
        'what_it_proves'=>'',
        'preferred_use'=>'Best if you want AI to test several points inside the current Settings Precision Range.',
        'range_basis'=>$controlLabel,
        'current_range'=>($rMinInt . ' to ' . $rMaxInt),
        'batch_phase'=>(string)($batchPhase['key'] ?? ''),
        'batch_phase_label'=>(string)($batchPhase['label'] ?? ''),
        'batch_phase_short_label'=>(string)($batchPhase['short_label'] ?? ''),
        'batch_phase_description'=>(string)($batchPhase['description'] ?? ''),
        'batch_precision_span'=>(float)($batchPhase['span'] ?? ($rangeMax - $rangeMin)),
        'beginner_explanation'=>(string)($batchPhase['beginner_explanation'] ?? 'This creates 9 AI runs for this lottery. Run 1 keeps the current best settings as the control. Runs 2 through 9 test one AI setting inside its current Settings Precision Range. This is different from the History Window Range.'),
        'milestone_supported'=>'',
        'fail_reason'=>'This lottery is not ready for a 9-run AI batch yet. LottoExpert needs more repeated saved completed prediction history before creating a controlled batch.'
    );
    if ($runCount < 45 || $drawCount < 5 || !$hasRange || $trueClusterCount < 2) {
        $empty['guardrail'] = 'This lottery is not ready for a Settings Precision 9-test group yet. LottoExpert first needs about 5 completed regular batch cycles, at least 45 scored runs, and a repeated settings pattern. Until then, run regular AI batches from the best available Shared AI Learning champion settings and save the results for automatic future scoring. History Window research is optional admin research only, not the required first step.';
        $empty['fail_reason'] = $empty['guardrail'];
        return $empty;
    }
    if (!in_array($stage, array('exploratory_batch','strategy_candidate','narrowing_signal','validated_focus_range','precision_focus_range'), true)) { return $empty; }
    if (!$hasAdvice || $settingLabel === '' || $settingKey === '') {
        $empty['guardrail'] = 'Keep using one clean next test until this lottery isolates a single setting strongly enough for a batch.';
        return $empty;
    }
    $binaryKeys = array('best_window','auto_tune');
    if (in_array($settingKey, $binaryKeys, true)) {
        $empty['guardrail'] = 'This lottery is not ready for a 9-run AI batch yet. LottoExpert needs a numeric range setting before creating a controlled batch.';
        return $empty;
    }
    $decimalKeys = array('diversity_penalty','sampling_temperature','recency_decay','learning_rate','dropout_rate','gap_scale');
    $variableType = in_array($settingKey, $decimalKeys, true) ? 'decimal' : 'integer';
    $batchPhase = mleAdvisoryResolveControlledBatchPhase($settingKey, $settingLabel, $variableType, $rangeMin, $rangeMax, false);
    $valueResult = mleAdvisoryGenerateEightDistinctBatchValues($rangeMin, $rangeMax, $suggestedValue, $variableType);
    if (empty($valueResult['ok']) || count((array)($valueResult['values'] ?? array())) !== 8) {
        $empty['guardrail'] = (string)($valueResult['reason'] ?? 'This lottery is not ready for a 9-run AI batch yet. LottoExpert could not create 8 useful distinct test values from the current prediction history.');
        $empty['fail_reason'] = $empty['guardrail'];
        return $empty;
    }
    $values = (array)$valueResult['values'];
    $batchRunLabels = array($controlRunName);
    $batchRunValues = array($currentValue !== '' ? $currentValue : '');
    $desc = array(1=>'Low edge of current range',2=>'Low-mid test point',3=>'Mid-low test point',4=>'Center point',5=>'Mid-high test point',6=>'High-mid test point',7=>'High edge of current range',8=>'Current recommended next setting');
    for ($i=0; $i<8; $i++) {
        $vText = mleAdvisoryNormalizeBatchValue($values[$i], $variableType);
        $batchRunLabels[] = 'Test ' . ($i+1) . ' - ' . $settingLabel . ' ' . $vText . ' (' . $desc[$i+1] . ')';
        $batchRunValues[] = $vText;
    }
    $phaseLabel = trim((string)($batchPhase['label'] ?? 'Settings Range Test'));
    $phaseDescription = trim((string)($batchPhase['description'] ?? ''));
    $plan = 'Create 9 saved runs for this lottery while keeping the control settings locked. The first run is the control from ' . $controlSource . '. Runs 2 through 9 test only ' . $settingLabel . ' across the current Settings Precision Range (' . $rMinInt . ' to ' . $rMaxInt . '). This is a setting scale, not the draw-history window. Review results after LottoExpert automatically scores the next completed draw.';
    if (!empty($batchPhase['test_plan'])) { $plan .= ' Phase: ' . $phaseLabel . '. ' . (string)$batchPhase['description']; }
    $advancedExplanation = !empty($batchPhase['advanced_explanation']) ? (string)$batchPhase['advanced_explanation'] : ('This batch keeps the base settings locked and varies only ' . $settingLabel . ' across 8 useful distinct test points inside the current Settings Precision Range. The control run preserves ' . $controlSource . '.');
    return array(
        'has_recommendation'=>true,
        'title'=>'Controlled AI Settings Test',
        'summary'=>'Prediction History is now strong enough to run a controlled 9-run AI batch test for this lottery only.',
        'test_plan'=>$plan,
        'advanced_explanation'=>$advancedExplanation,
        'guardrail'=>'Do not change multiple unrelated settings. Keep the current strongest setup stable and test one focused range question.',
        'evidence_line'=>$runCount . ' saved scored runs, ' . $drawCount . ' completed draw dates, and repeated cluster support in ' . $trueClusterCount . ' strong prediction history runs.',
        'batch_purpose'=>'Test which exact point inside the current Settings Precision Range for ' . $settingLabel . ' performs best when all other proven settings stay locked.',
        'locked_settings'=>trim((string)($settingsAdv['keep_same_list'] ?? 'Keep the strongest settings stable.')),
        'test_variable'=>$settingLabel,
        'setting_key'=>$settingKey,
        'control_run'=>$controlRunName . ' (' . $settingLabel . ' at ' . ($currentValue !== '' ? $currentValue : 'the current value') . ').',
        'control_source'=>$controlSource,
        'batch_runs'=>$batchRunLabels,
        'batch_run_values'=>$batchRunValues,
        'what_it_proves'=>'Which exact point inside this lottery current Settings Precision Range performs best when all other proven settings stay locked.',
        'preferred_use'=>'Best if you want AI to test several useful distinct points inside the current Settings Precision Range.',
        'range_basis'=>$controlLabel,
        'current_range'=>($rMinInt . ' to ' . $rMaxInt),
        'beginner_explanation'=>'This creates 9 AI runs for this lottery. Run 1 keeps the current best settings as the control. Runs 2 through 9 test one AI setting inside its current Settings Precision Range. This is different from the History Window Range.',
        'milestone_supported'=>'Confirm the range across more completed draws.',
        'batch_type'=>'Precision Focus Settings Test'
    );
}

function mleAdvisoryComputeRecommendationLevel(array $precisionLock, array $summary, array $topMethod, array $settingsAdv, array $batchTest) {
    $runCount = (int)($precisionLock['run_count'] ?? ($summary['total_runs'] ?? 0));
    $drawCount = (int)($summary['scored_draws'] ?? 0);
    $methodRepeat = (int)($topMethod['run_count'] ?? 0);
    $trueClusterSupport = (int)($summary['true_cluster_support'] ?? ($precisionLock['true_cluster_support'] ?? 0));
    $clusterDrawSupport = (int)($summary['true_cluster_draw_support'] ?? 0);
    $hasRange = !empty($precisionLock['has_range']);
    $stage = (string)($precisionLock['stage'] ?? 'broad_testing');
    $isNarrow = in_array($stage, array('narrowing_signal','validated_focus_range','precision_focus_range'), true);
    $hasAdvice = !empty($settingsAdv['has_advice']);
    $hasBatch = !empty($batchTest['has_recommendation']);
    $label = 'Learning Stage';
    $key = 'learning_stage';
    $why = 'This lottery is still building completed draw-cycle prediction history. Batches add scored runs, but each target date counts as one completed draw cycle.';
    $next = 'Keep saving runs. LottoExpert will score them automatically after completed draws.';

    if ($runCount >= 120 && $drawCount >= 20 && $methodRepeat >= 12 && $trueClusterSupport >= 5 && $clusterDrawSupport >= 5 && $isNarrow && $hasAdvice) {
        $label = 'Settings Precision Range';
        $key = 'precision_focus_range';
        $why = 'This lottery has strong completed draw-cycle support, repeated scored runs, and repeated settings cluster prediction history. This is LottoExpert\'s strongest disciplined range, not a guarantee.';
        $next = $hasBatch ? 'Use the controlled Precision Focus batch and keep validating future draw cycles.' : 'Keep the strongest baseline stable and continue one-setting tests.';
    } elseif ($runCount >= 75 && $drawCount >= 12 && $trueClusterSupport >= 4 && $clusterDrawSupport >= 4 && $isNarrow && ($hasAdvice || $hasBatch)) {
        $label = 'Validated Focus Range';
        $key = 'validated_focus_range';
        $why = 'This lottery has repeated support across completed draw cycles and enough scored-run prediction history to guide disciplined testing.';
        $next = $hasBatch ? 'Run the controlled 9-run AI batch and let LottoExpert score it automatically after the next draw.' : 'Create the recommended next settings run and keep measuring after the next draw.';
    } elseif ($runCount >= 45 && $drawCount >= 6 && $trueClusterSupport >= 3 && $hasRange && ($hasAdvice || $hasBatch)) {
        $label = 'Narrowing Signal';
        $key = 'narrowing_signal';
        $why = 'Repeated completed-draw prediction history is starting to favor a tighter strategy range for this lottery.';
        $next = 'Keep locked settings stable and test one uncertain setting next.';
    } elseif ($runCount >= 27 && $drawCount >= 4 && $trueClusterSupport >= 2 && $hasRange && ($hasAdvice || $hasBatch)) {
        $label = 'Exploratory Precision Settings Test';
        $key = 'exploratory_batch';
        $why = 'This lottery has enough completed draw-cycle prediction history for the first controlled 9-run Precision Focus batch.';
        $next = $hasBatch ? 'Run the controlled Precision Focus batch.' : 'Create a controlled 9-run Precision Focus batch.';
    } elseif ($runCount >= 18 && $drawCount >= 3) {
        $label = 'Early Direction';
        $key = 'early_direction';
        $why = 'A possible direction is forming, but LottoExpert needs more completed draw cycles before stronger narrowing guidance.';
        $next = 'Keep scoring saved runs until the same method or range repeats across more draw cycles.';
    }
    return array('label'=>$label,'key'=>$key,'why'=>$why,'next'=>$next,'cluster_support'=>$trueClusterSupport,'cluster_draw_support'=>$clusterDrawSupport,'saved_scored_runs'=>$runCount,'completed_draws'=>$drawCount);
}

function mleAdvisoryComputePrecisionProgress(array $precisionLock, array $summary, array $recommendationLevel, array $settingsAdv, array $batchTest) {
    $runCount = (int)($precisionLock['run_count'] ?? ($summary['total_runs'] ?? 0));
    $drawCount = (int)($summary['scored_draws'] ?? 0);
    $clusterSupport = (int)($summary['true_cluster_support'] ?? ($precisionLock['true_cluster_support'] ?? 0));
    $clusterDrawSupport = (int)($summary['true_cluster_draw_support'] ?? 0);
    $hasPending = (int)($summary['pending_runs'] ?? 0);

    $defs = mleAdvisoryPrecisionMilestoneDefinitions();
    $currentIndex = 0;
    foreach ($defs as $idx => $def) {
        $meetsDraws = ((int)$drawCount >= (int)$def['draws']);
        $meetsRuns = ((int)$runCount >= (int)$def['runs']);
        $meetsClusters = ((int)$clusterSupport >= (int)$def['clusters']);
        if ($meetsDraws && $meetsRuns && $meetsClusters) { $currentIndex = (int)$idx; }
    }

    $current = $defs[$currentIndex];
    $currentKey = (string)$current['key'];
    $nextIndex = min(count($defs) - 1, $currentIndex + 1);
    $next = $defs[$nextIndex];

    $milestones = array();
    foreach ($defs as $idx => $def) {
        $status = mleAdvisoryResolvePrecisionMilestoneStatus($currentKey, $def['key']);
        $milestones[] = array(
            'key' => (string)$def['key'],
            'label' => (string)$def['label'],
            'short' => (string)$def['short'],
            'draws_required' => (int)$def['draws'],
            'runs_required' => (int)$def['runs'],
            'clusters_required' => (int)$def['clusters'],
            'status' => $status,
        );
    }

    $drawTarget = max(1, (int)$defs[count($defs)-1]['draws']);
    $drawProgressPercent = min(100, (int)round(((int)$drawCount / $drawTarget) * 100));
    $progressPercent = (int)round((($currentIndex + 1) / count($defs)) * 100);
    if ($currentIndex < (count($defs) - 1)) { $progressPercent = min(99, $progressPercent); }

    $waitingText = mleAdvisoryBuildPrecisionWaitingText($currentKey, $drawCount, $runCount, $clusterSupport);
    if ($hasPending > 0) {
        $waitingText = 'A Precision Focus test is in progress: ' . $hasPending . ' pending run' . ($hasPending === 1 ? '' : 's') . ' are waiting for the next completed draw result. After that draw posts, score the runs to move the prediction history forward.';
    }

    $why = 'This stage is based primarily on completed draw cycles, with scored runs and repeated setting clusters used as support gates.';
    if ($currentKey === 'learning_stage') { $why = 'LottoExpert is collecting prediction history. A batch can create several scored runs, but it still represents one target draw cycle.'; }
    elseif ($currentKey === 'early_direction') { $why = 'A possible direction is forming across completed draw cycles. LottoExpert is not treating this as a strong narrowed range yet.'; }
    elseif ($currentKey === 'exploratory_batch') { $why = 'Enough completed draw-cycle prediction history exists to test a controlled 9-run Precision Focus batch.'; }
    elseif ($currentKey === 'narrowing_signal') { $why = 'Repeated prediction history is starting to favor a tighter range, but more completed draw cycles are needed before validation.'; }
    elseif ($currentKey === 'validated_focus_range') { $why = 'This range has stronger repeated support across completed draw cycles and scored runs.'; }
    elseif ($currentKey === 'precision_focus_range') { $why = 'This is LottoExpert\'s strongest disciplined range, backed by many completed draw cycles and repeated completed prediction history.'; }

    $achieved = $current['label'] . ' reached: ' . $drawCount . ' completed draw cycle' . ($drawCount === 1 ? '' : 's') . ', ' . $runCount . ' scored run' . ($runCount === 1 ? '' : 's') . ', and ' . $clusterSupport . ' repeated setting cluster' . ($clusterSupport === 1 ? '' : 's') . '.';
    $evidenceLine = 'Current prediction history: ' . $drawCount . ' completed draw cycle' . ($drawCount === 1 ? '' : 's') . ' - ' . $runCount . ' scored run' . ($runCount === 1 ? '' : 's') . ' - ' . $clusterSupport . ' repeated setting cluster' . ($clusterSupport === 1 ? '' : 's') . '.';
    if ($hasPending > 0) { $evidenceLine .= ' Pending activity: ' . $hasPending . ' run' . ($hasPending === 1 ? '' : 's') . ' waiting for draw results.'; }

    return array(
        'level'=>$currentIndex + 1,
        'level_name'=>(string)$current['label'],
        'level_key'=>$currentKey,
        'progress_percent'=>$progressPercent,
        'draw_progress_percent'=>$drawProgressPercent,
        'why'=>$why,
        'next_milestone'=>$currentIndex >= (count($defs)-1) ? 'Keep validating the Settings Precision Range after future completed draws.' : ((string)$next['label'] . ' at ' . (int)$next['draws'] . ' completed draw cycles and ' . (int)$next['runs'] . ' scored runs.'),
        'achieved'=>$achieved,
        'evidence_line'=>$evidenceLine,
        'beginner_explanation'=>'Precision Progress is based primarily on completed draw cycles. A 9-test group gives nine scored comparisons, but it counts as one completed draw cycle because all nine runs are tested against the same official result.',
        'waiting_for'=>$waitingText,
        'current_draw_cycles'=>$drawCount,
        'current_scored_runs'=>$runCount,
        'current_clusters'=>$clusterSupport,
        'current_cluster_draw_support'=>$clusterDrawSupport,
        'pending_runs'=>$hasPending,
        'milestones'=>$milestones,
    );
}

function mleAdvisoryBuildTrueSettingsClusterFromStrongRuns(array $strongRuns) {
    $settingKeys = array('skai_blend_ai_pct','blend_ai_pct','ai_pct','blend_percent','blend_pct','ai_blend_pct','mode','run_mode','skai_window_size','draws_analyzed','best_window','auto_tune','diversity_penalty','sampling_temperature','recency_decay','gap_scale','learning_rate','dropout_rate','hidden_layers','chain_len','burn_in');
    $clusters = array();
    foreach ($strongRuns as $run) {
        if (!is_array($run)) { continue; }
        $settings = isset($run['settings']) && is_array($run['settings']) ? $run['settings'] : array();
        $method = trim((string)($run['method_key'] ?? ''));
        if ($method === '') { $method = 'method_unknown'; }
        $parts = array('method=' . $method);
        $labelParts = array('Method ' . mleAdvisoryMethodLabel($method));
        foreach ($settingKeys as $key) {
            if (!array_key_exists($key, $settings)) { continue; }
            $v = $settings[$key];
            if ($v === '' || $v === null) { continue; }
            if (is_bool($v)) { $norm = $v ? 'On' : 'Off'; }
            elseif (is_numeric($v)) {
                $num = (float)$v;
                if (in_array($key, array('skai_blend_ai_pct','blend_ai_pct','ai_pct','blend_percent','blend_pct','ai_blend_pct','skai_window_size','draws_analyzed'), true)) { $norm = (string)((int)round($num)); }
                else { $norm = rtrim(rtrim(number_format($num, 3, '.', ''), '0'), '.'); }
            } else { $norm = trim((string)$v); }
            if ($norm === '') { continue; }
            $parts[] = $key . '=' . strtolower($norm);
            $labelParts[] = mleAdvisoryFormatSettingLabel($key) . ' ' . $norm;
            if (count($parts) >= 5) { break; }
        }
        $clusterKey = implode('|', $parts);
        if (!isset($clusters[$clusterKey])) { $clusters[$clusterKey] = array('cluster_key'=>$clusterKey,'cluster_label'=>implode(', ', $labelParts),'strong_run_count'=>0,'completed_draw_dates'=>array(),'best_total_hits'=>0,'best_main_hits'=>0,'best_extra_hits'=>0,'score_sum'=>0.0,'members'=>array()); }
        $clusters[$clusterKey]['strong_run_count']++;
        $dd = trim((string)($run['draw_date'] ?? ''));
        if ($dd !== '') { $clusters[$clusterKey]['completed_draw_dates'][$dd] = 1; }
        $clusters[$clusterKey]['best_total_hits'] = max((int)$clusters[$clusterKey]['best_total_hits'], (int)($run['total_hits'] ?? 0));
        $clusters[$clusterKey]['best_main_hits'] = max((int)$clusters[$clusterKey]['best_main_hits'], (int)($run['main_hits'] ?? 0));
        $clusters[$clusterKey]['best_extra_hits'] = max((int)$clusters[$clusterKey]['best_extra_hits'], (int)($run['extra_hits'] ?? 0));
        $clusters[$clusterKey]['score_sum'] += (float)($run['evidence_score'] ?? 0);
        if (!empty($run['saved_id'])) { $clusters[$clusterKey]['members'][] = (int)$run['saved_id']; }
    }
    $out = array();
    foreach ($clusters as $c) {
        $cnt = max(1, (int)$c['strong_run_count']);
        $c['completed_draw_count'] = count($c['completed_draw_dates']);
        $c['average_evidence_score'] = round(((float)$c['score_sum']) / $cnt, 2);
        unset($c['completed_draw_dates'], $c['score_sum']);
        if ($cnt >= 2) { $out[] = $c; }
    }
    usort($out, function($a, $b) {
        $as = ((int)($a['strong_run_count'] ?? 0) * 1000) + ((int)($a['completed_draw_count'] ?? 0) * 100) + (float)($a['average_evidence_score'] ?? 0);
        $bs = ((int)($b['strong_run_count'] ?? 0) * 1000) + ((int)($b['completed_draw_count'] ?? 0) * 100) + (float)($b['average_evidence_score'] ?? 0);
        if ($bs == $as) { return 0; }
        return ($bs > $as) ? 1 : -1;
    });
    return $out;
}

function mleAdvisoryEvidenceStatusLabelFromRow(array $row) {
    $status = strtolower(trim((string)($row['advice_status'] ?? $row['evidence_status'] ?? $row['status'] ?? '')));
    if ($status === 'retire' || $status === 'retired' || $status === 'excluded' || $status === 'exclude' || $status === 'do_not_use') { return 'Exclude'; }
    if ($status === 'watch' || $status === 'review') { return 'Watch for Now'; }
    if ($status === 'keep' || $status === 'use' || $status === 'active' || $status === '') { return 'Use for Advice'; }
    return 'Watch for Now';
}

function mleAdvisoryBuildEvidenceIntelligence(array $visualRows, array $savedById, $method) {
    $method = mleAdvisorySourceToMethodKey($method);
    $completed = array_merge((array)($visualRows['recent'] ?? array()), (array)($visualRows['older'] ?? array()));
    $evidenceRows = array();
    $allStrongSettings = array();
    $allStrongMethods = array();
    foreach ($completed as $row) {
        if (!is_array($row)) { continue; }
        $savedId = (int)($row['saved_id'] ?? 0);
        if ($savedId <= 0 || empty($savedById[$savedId]) || !is_array($savedById[$savedId])) { continue; }
        $saved = $savedById[$savedId];
        $settings = mylottoexpertResolveEffectiveSettings($saved);
        if (!is_array($settings)) { $settings = array(); }
        $mainHits = (int)($row['main_hits'] ?? $row['hits_main'] ?? 0);
        $extraHits = (int)($row['extra_hits'] ?? $row['hits_extra'] ?? 0);
        $totalHits = (int)($row['total_hits'] ?? ($mainHits + $extraHits));
        $actualMain = (array)($row['actual'] ?? array());
        $expectedMain = count($actualMain);
        if ($expectedMain <= 0) { $expectedMain = (int)($saved['pick_count'] ?? $saved['main_count'] ?? 0); }
        if ($expectedMain <= 0) { $expectedMain = max(5, $mainHits); }
        $missing = max(0, $expectedMain - $mainHits);
        $top10 = (int)($row['top10_hits'] ?? 0);
        $top20 = (int)($row['top20_hits'] ?? 0);
        $avgRank = (float)($row['avg_winning_rank'] ?? 0);
        $allMain = ($expectedMain > 0 && $mainHits >= $expectedMain);
        $score = ($mainHits * 18.0) + ($extraHits * 6.0) + ($top10 * 3.0) + ($top20 * 1.5) - ($missing * 4.0);
        if ($avgRank > 0) { $score -= min(25.0, $avgRank * 0.10); }
        if ($allMain) { $score += 60.0; }
        if ($totalHits >= 4) { $score += 12.0; }
        $evidenceStatus = mleAdvisoryEvidenceStatusLabelFromRow($row);
        $group = 'Weak but Informative';
        if ($evidenceStatus === 'Exclude') { $group = 'Excluded'; }
        elseif ($allMain || $mainHits >= max(3, $expectedMain - 1) || $score >= 55.0) { $group = 'Strong Prediction History'; }
        elseif ($totalHits >= 2 || $top10 > 0 || $top20 > 0) { $group = 'Useful Prediction History'; }
        $settingsSummary = mleAdvisoryBuildBestRecipeDesc($settings, (string)($saved['source'] ?? $method));
        $item = array(
            'saved_id' => $savedId,
            'draw_date' => (string)($row['draw_date'] ?? ''),
            'method_key' => (string)($row['method_key'] ?? mleAdvisorySourceToMethodKey($row['source'] ?? $saved['source'] ?? $method)),
            'method_label' => (string)($row['method_label'] ?? mleAdvisoryMethodLabel($row['source'] ?? $saved['source'] ?? $method)),
            'main_hits' => $mainHits,
            'extra_hits' => $extraHits,
            'total_hits' => $totalHits,
            'missing_count' => $missing,
            'top10_hits' => $top10,
            'top20_hits' => $top20,
            'avg_rank' => $avgRank,
            'all_main_found' => $allMain,
            'evidence_score' => round($score, 2),
            'evidence_group' => $group,
            'evidence_status' => $evidenceStatus,
            'settings_summary' => $settingsSummary,
            'settings' => $settings
        );
        $evidenceRows[] = $item;
        if ($group === 'Strong Prediction History' && $evidenceStatus !== 'Exclude') {
            $allStrongSettings[] = $settings;
            $mk = (string)$item['method_key'];
            if ($mk !== '') {
                if (!isset($allStrongMethods[$mk])) { $allStrongMethods[$mk] = array('count'=>0, 'label'=>mleAdvisoryMethodLabel($mk)); }
                $allStrongMethods[$mk]['count']++;
            }
        }
    }
    usort($evidenceRows, function($a, $b) {
        $as = (float)($a['evidence_score'] ?? 0);
        $bs = (float)($b['evidence_score'] ?? 0);
        if ($bs == $as) { return strcmp((string)($b['draw_date'] ?? ''), (string)($a['draw_date'] ?? '')); }
        return ($bs > $as) ? 1 : -1;
    });
    $strong = array(); $useful = array(); $weak = array(); $excluded = array();
    foreach ($evidenceRows as $item) {
        $g = (string)($item['evidence_group'] ?? 'Weak but Informative');
        if ($g === 'Strong Prediction History') { $strong[] = $item; }
        elseif ($g === 'Useful Prediction History') { $useful[] = $item; }
        elseif ($g === 'Excluded') { $excluded[] = $item; }
        else { $weak[] = $item; }
    }
    $repeat = mleAdvisoryBuildSettingsRepeatReport($allStrongSettings, $allStrongMethods);
    $trueClusters = mleAdvisoryBuildTrueSettingsClusterFromStrongRuns($strong);
    $topCluster = !empty($trueClusters[0]) && is_array($trueClusters[0]) ? $trueClusters[0] : array();
    $lock = mleAdvisoryBuildCurrentLockedSettings($repeat, count($strong), $topCluster);
    return array(
        'strong_runs' => $strong,
        'useful_runs' => $useful,
        'weak_runs' => $weak,
        'excluded_runs' => $excluded,
        'strong_count' => count($strong),
        'useful_count' => count($useful),
        'weak_count' => count($weak),
        'excluded_count' => count($excluded),
        'settings_repeat' => $repeat,
        'current_locked_settings' => $lock,
        'true_clusters' => $trueClusters,
        'top_cluster' => $topCluster,
        'true_cluster_support' => (int)($topCluster['strong_run_count'] ?? 0),
        'true_cluster_draw_support' => (int)($topCluster['completed_draw_count'] ?? 0),
        'summary' => count($strong) > 0 ? ('LottoExpert found ' . count($strong) . ' strong prediction history run' . (count($strong) === 1 ? '' : 's') . ' for this lottery. These runs stay in the prediction history pool so repeated settings can be found.') : 'No strong prediction history runs are ready yet for this lottery. Keep saving and scoring runs.'
    );
}

function mleAdvisoryBuildSettingsRepeatReport(array $strongSettings, array $strongMethods) {
    $keys = array('skai_blend_ai_pct','blend_ai_pct','ai_pct','blend_percent','blend_pct','ai_blend_pct','mode','run_mode','skai_window_size','draws_analyzed','best_window','auto_tune','diversity_penalty','sampling_temperature','recency_decay','gap_scale','learning_rate','dropout_rate','hidden_layers','chain_len','burn_in');
    $total = count($strongSettings);
    $repeated = array();
    $notProven = array();
    foreach ($strongMethods as $methodKey => $info) {
        $cnt = (int)($info['count'] ?? 0);
        if ($cnt >= 2) {
            $repeated[] = array('key'=>'method','label'=>'Method','value'=>(string)($info['label'] ?? mleAdvisoryMethodLabel($methodKey)),'count'=>$cnt,'support'=>'Appears in ' . $cnt . ' strong prediction history runs.');
        }
    }
    foreach ($keys as $key) {
        $vals = array();
        foreach ($strongSettings as $settings) {
            if (!is_array($settings) || !array_key_exists($key, $settings)) { continue; }
            $v = $settings[$key];
            if ($v === '' || $v === null) { continue; }
            if (is_bool($v)) { $norm = $v ? 'On' : 'Off'; }
            elseif (is_numeric($v)) { $norm = (string)round((float)$v, 3); }
            else { $norm = trim((string)$v); }
            if ($norm === '') { continue; }
            if (!isset($vals[$norm])) { $vals[$norm] = 0; }
            $vals[$norm]++;
        }
        if (empty($vals)) { continue; }
        arsort($vals);
        $topVal = (string)key($vals);
        $topCount = (int)current($vals);
        $label = mleAdvisoryFormatSettingLabel($key);
        if ($topCount >= 2) {
            $support = 'Appears in ' . $topCount . ' strong prediction history runs.';
            $repeated[] = array('key'=>$key,'label'=>$label,'value'=>$topVal,'count'=>$topCount,'support'=>$support);
        } else {
            $notProven[] = array('key'=>$key,'label'=>$label,'value'=>$topVal,'count'=>$topCount,'support'=>'This setting appeared in one strong run, but it is not proven yet.');
        }
    }
    return array(
        'total_strong_runs' => $total,
        'repeated' => $repeated,
        'not_proven' => $notProven,
        'summary' => !empty($repeated) ? 'Repeated settings are the clues. If the same setting keeps showing up in stronger runs, LottoExpert can start trusting it more.' : 'Strong runs exist, but the repeated settings pattern is still forming.'
    );
}

function mleAdvisoryBuildCurrentLockedSettings(array $repeat, $strongCount, array $topCluster = array()) {
    $repeated = (array)($repeat['repeated'] ?? array());
    $locked = array();
    foreach ($repeated as $item) {
        if (!is_array($item)) { continue; }
        $count = (int)($item['count'] ?? 0);
        if ($count >= 2) { $locked[] = $item; }
    }
    $clusterCount = (int)($topCluster['strong_run_count'] ?? 0);
    $clusterDraws = (int)($topCluster['completed_draw_count'] ?? 0);
    $status = 'Not Ready';
    $reason = 'Current Locked Settings are not ready yet. LottoExpert needs more saved scored runs for this lottery before locking a baseline.';
    if ($strongCount >= 2 && $clusterCount >= 2 && count($locked) >= 2) {
        $status = 'Candidate';
        $reason = 'These settings are candidates because they repeat across the strongest saved prediction history for this lottery.';
    }
    if ($strongCount >= 3 && $clusterCount >= 2 && $clusterDraws >= 1 && count($locked) >= 3) {
        $status = 'Locked for Testing';
        $reason = 'These settings are the current baseline because they repeat across the strongest saved prediction history for this lottery.';
    }
    if ($strongCount >= 5 && $clusterCount >= 3 && $clusterDraws >= 2 && count($locked) >= 4) {
        $status = 'Precision Focus Candidate';
        $reason = 'These settings have repeated cluster support across multiple strong prediction history runs and can be used as the controlled baseline.';
    }
    if ($strongCount >= 8 && $clusterCount >= 4 && $clusterDraws >= 2 && count($locked) >= 5) {
        $status = 'Elite Baseline';
        $reason = 'These settings have strong repeated cluster prediction history and support the current elite baseline for this lottery.';
    }
    return array('status'=>$status,'items'=>$locked,'reason'=>$reason,'last_updated'=>date('Y-m-d H:i:s'),'cluster'=>$topCluster,'cluster_support'=>$clusterCount,'cluster_draw_support'=>$clusterDraws,'has_active_lock'=>false);
}

function mleAdvisoryCurrentLockReady(array $lock) {
    return in_array((string)($lock['status'] ?? ''), array('Locked for Testing','Precision Focus Candidate','Elite Baseline'), true);
}

function mleAdvisoryBestVisualCompletedRow(array $visual) {
    $recent = isset($visual['recent']) && is_array($visual['recent']) ? $visual['recent'] : array();
    if (!empty($recent) && is_array($recent[0])) { return $recent[0]; }
    $older = isset($visual['older']) && is_array($visual['older']) ? $visual['older'] : array();
    if (!empty($older) && is_array($older[0])) { return $older[0]; }
    return array();
}

function mleAdvisoryFormatDateLabel($dateValue) {
    $dateValue = trim((string)$dateValue);
    if ($dateValue === '') { return ''; }
    $ts = strtotime($dateValue);
    if ($ts === false) { return $dateValue; }
    return date('M j, Y', $ts);
}

function mleAdvisoryBuildWhySupportText($methodLabel, array $topMethod, array $visual, array $precisionLock, array $proof) {
    $methodLabel = trim((string)$methodLabel);
    if ($methodLabel === '') { $methodLabel = 'This method'; }
    $runCount = (int)($topMethod['run_count'] ?? 0);
    $drawCount = (int)($topMethod['draw_count'] ?? 0);
    $proofKey = (string)($proof['level'] ?? 'too_early');
    $bestRow = mleAdvisoryBestVisualCompletedRow($visual);
    if ($drawCount <= 0 && empty($bestRow)) {
        return 'This is still early. LottoExpert needs more saved scored runs for this lottery before it can narrow confidently.';
    }

    $parts = array();
    if ($drawCount > 0) {
        $parts[] = $drawCount . ' completed scored run' . ($drawCount === 1 ? '' : 's');
    }
    if ($runCount > 0) {
        $parts[] = $runCount . ' active saved run' . ($runCount === 1 ? '' : 's');
    }

    if (!empty($bestRow)) {
        $bestTotal = (int)($bestRow['total_hits'] ?? 0);
        $bestMain = (int)($bestRow['main_hits'] ?? 0);
        $bestExtra = (int)($bestRow['extra_hits'] ?? 0);
        $bestDate = mleAdvisoryFormatDateLabel($bestRow['draw_date'] ?? '');
        if ($bestTotal > 0 && $bestDate !== '') {
            $bestText = 'best result of ' . $bestTotal . ' total hit' . ($bestTotal === 1 ? '' : 's') . ' on ' . $bestDate;
            if ($bestMain > 0 || $bestExtra > 0) {
                $bestText .= ' (' . $bestMain . ' main';
                if ($bestExtra > 0) { $bestText .= ', ' . $bestExtra . ' extra'; }
                $bestText .= ')';
            }
            $parts[] = $bestText;
        }
    }

    if (!empty($precisionLock['has_range'])) {
        $rangeMin = (int)round((float)($precisionLock['range_min'] ?? 0));
        $rangeMax = (int)round((float)($precisionLock['range_max'] ?? 100));
        $parts[] = 'stronger results between ' . $rangeMin . ' and ' . $rangeMax;
        if (isset($precisionLock['control_label']) && trim((string)$precisionLock['control_label']) !== '') {
            $parts[] = 'measured on the ' . trim((string)$precisionLock['control_label']);
        }
    }

    $text = $methodLabel . ' is leading for this lottery because it has the strongest saved completed prediction history here';
    if (!empty($parts)) {
        $text .= ': ' . implode(', ', $parts) . '.';
    } else {
        $text .= '.';
    }

    if (in_array($proofKey, array('learning_stage', 'no_clear_edge', 'early_signal', 'strategy_candidate', 'close_race'), true)) {
        $text .= ' This is still early. LottoExpert needs more saved scored runs for this lottery before it can narrow confidently.';
    }
    return $text;
}

function mleAdvisoryNumbersFromJson($raw) {
    $out = array();
    $decoded = is_string($raw) && $raw !== '' ? json_decode($raw, true) : null;
    if (is_array($decoded)) {
        $flat = array();
        $it = function($v) use (&$it, &$flat) { if (is_array($v)) { foreach ($v as $x) { $it($x); } } else { $flat[] = $v; } };
        $it($decoded);
        foreach ($flat as $n) { $n=(int)$n; if ($n > 0 && !in_array($n,$out,true)) { $out[]=$n; } }
    }
    return $out;
}

function mleAdvisoryBuildVisualRunRows(array $activeRows, array $perfRows) {
    $savedById = array();
    foreach ($activeRows as $r) { $savedById[(int)($r['id'] ?? 0)] = $r; }

    $rowsByKey = array();
    $usedSavedIds = array();

    $scoreRow = function(array $r) {
        $total = (int)($r['total_hits'] ?? 0);
        $main = (int)($r['main_hits'] ?? 0);
        $quality = is_numeric($r['quality_score'] ?? null) ? (float)$r['quality_score'] : 0.0;
        $rank = is_numeric($r['avg_rank'] ?? null) ? (float)$r['avg_rank'] : 9999.0;
        $date = strtotime((string)($r['draw_date'] ?? ''));
        if ($date === false) { $date = 0; }
        return ($total * 1000000.0) + ($main * 100000.0) + ($quality * 1000.0) - $rank + ($date / 10000000000.0);
    };

    $addRow = function(array $row) use (&$rowsByKey, $scoreRow) {
        $predKey = implode(',', array_map('intval', (array)($row['predicted'] ?? array())));
        $actualKey = implode(',', array_map('intval', (array)($row['actual'] ?? array())));
        $drawDate = (string)($row['draw_date'] ?? '');
        $method = (string)($row['method'] ?? '');
        $savedId = (int)($row['saved_id'] ?? 0);
        if (!empty($row['completed'])) {
            $key = 'c|' . $savedId . '|' . $drawDate . '|' . $method . '|' . md5($predKey);
        } else {
            $key = 'u|' . $savedId . '|' . $drawDate . '|' . $method . '|' . md5($predKey);
        }
        if (!isset($rowsByKey[$key]) || $scoreRow($row) > $scoreRow($rowsByKey[$key])) {
            $rowsByKey[$key] = $row;
        }
    };

    foreach ($perfRows as $p) {
        $sid = (int)($p['__saved_id'] ?? $p['run_id'] ?? 0);
        $s = isset($savedById[$sid]) ? $savedById[$sid] : array();
        if (empty($s)) { continue; }
        if (function_exists('mleAdvisoryIsSystemLearningOnlyRow') && (mleAdvisoryIsSystemLearningOnlyRow($s) || mleAdvisoryIsSystemLearningOnlyRow($p))) { continue; }
        $__rowProvenance = function_exists('mleAdvisoryBuildRunProvenance') ? mleAdvisoryBuildRunProvenance($s, $p) : array('scope'=>'user_saved_prediction','label'=>'Your Saved Prediction','trace'=>'','is_user_prediction'=>true,'is_system_learning_only'=>false);
        $__dailyViewForVisual = mylottoexpertExtractDailySavedView($s);
        $__isDailyForVisual = !empty($__dailyViewForVisual['is_daily']);
        $__dailyComboStringsForVisual = array_values((array)($__dailyViewForVisual['combo_strings'] ?? array()));
        $__dailyPickSizeForVisual = (int)($__dailyViewForVisual['pick_size'] ?? 0);
        $__regularViewForVisual = mylottoexpertExtractRegularSavedView($s);
        if (function_exists('mylottoexpertShouldForceRegularPoolDisplay') && mylottoexpertShouldForceRegularPoolDisplay($s, $__regularViewForVisual)) {
            $__isDailyForVisual = false;
            $__dailyComboStringsForVisual = array();
            $__dailyPickSizeForVisual = 0;
        }
        $pred = array_values(array_map('intval', (array)($__regularViewForVisual['main'] ?? array())));
        $predExtra = array_values(array_map('intval', (array)($__regularViewForVisual['extra'] ?? array())));
        if (empty($pred)) { $pred = mylottoexpertParseNumberCsv($s['main_numbers'] ?? '', true); }
        if (empty($predExtra)) { $predExtra = mylottoexpertParseNumberCsv($s['extra_ball_numbers'] ?? '', true); }
        if ($__isDailyForVisual) {
            if (!empty($__dailyViewForVisual['primary_combo_digits'])) {
                $pred = array_values(array_map('intval', (array)$__dailyViewForVisual['primary_combo_digits']));
            } elseif (!empty($__dailyComboStringsForVisual)) {
                $pred = mleAdvisoryDigitArrayFromComboString((string)$__dailyComboStringsForVisual[0]);
            }
            if (!empty($__dailyViewForVisual['bonus_digits'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['bonus_digits']));
            } elseif (!empty($__dailyViewForVisual['extra_digits'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['extra_digits']));
            } elseif (!empty($__dailyViewForVisual['top_extras'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['top_extras']));
            }
        }
        if (empty($pred)) { $pred = mleAdvisoryNumbersFromJson($p['predicted_ranking_json'] ?? ''); }
        $__actualParts = mleAdvisoryResolveActualDrawPartsForVisual($p, $s, $pred, $predExtra);
        $actual = (array)$__actualParts['main'];
        $actualExtra = (array)$__actualParts['extra'];
        $__actualOfficialFound = !empty($__actualParts['found']);
        $__actualMissingMessage = trim((string)($__actualParts['message'] ?? ''));
        if (empty($pred)) { continue; }

        $matches = array_values(mleCountDuplicateAwareMatches($actual, $pred));
        $extraMatches = array_values(mleCountDuplicateAwareMatches($actualExtra, $predExtra));
        $drawDate = (string)($p['draw_date'] ?? $s['target_draw_date'] ?? $s['next_draw_date'] ?? '');
        if ($drawDate === '0000-00-00') { $drawDate = ''; }
        $__mleVisualMethodProbe = array_merge((array)$p, (array)$s);
        $method = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey')
            ? mleAdvisoryResolveSavedEvidenceMethodKey($__mleVisualMethodProbe)
            : (string)($p['__method_key'] ?? $s['__method_key'] ?? mleAdvisorySourceToMethodKey($s['source'] ?? $p['source'] ?? ''));
        if ($method === '' || $method === 'unknown') { $method = (string)($p['__method_key'] ?? $s['__method_key'] ?? mleAdvisorySourceToMethodKey($s['source'] ?? $p['source'] ?? '')); }
        $settings = mylottoexpertResolveRunDisplayInfo($s, array('skai_prediction'=>'AI','ai_prediction'=>'Core AI','core_ai'=>'Core AI','core_ai_prediction'=>'Core AI','mcmc_prediction'=>'MCMC','skip_hit'=>'Skip Hit','strategy_set'=>'Saved Run'));
        $label = (string)($settings['label'] ?? ($s['label'] ?? 'Saved run'));
        $quality = is_numeric($p['weighted_quality_score'] ?? null) ? (float)$p['weighted_quality_score'] : 0.0;
        $__advStatusRaw = (string)($p['advice_status'] ?? $s['advice_status'] ?? 'use_in_advice');
        $__advStatusKey = strtolower(trim($__advStatusRaw));

        $__advStatusExplicit = (
            !empty($p['status_explicit']) ||
            !empty($s['status_explicit']) ||
            !empty($p['advice_status_updated_at']) ||
            !empty($s['advice_status_updated_at']) ||
            in_array($__advStatusKey, array('watch','review','retired','archived','excluded','exclude','do_not_use'), true)
        );
        $addRow(array(
            'saved_id'=>$sid,
            'perf_id'=>(int)($p['id'] ?? 0),

            'source_record_id'=>$sid,
            'run_uuid'=>(string)($p['run_uuid'] ?? $s['run_uuid'] ?? ''),
            'snapshot_run_uuid'=>(string)($p['snapshot_run_uuid'] ?? $s['snapshot_run_uuid'] ?? ''),
            'run_identity_key'=>(string)($p['run_identity_key'] ?? ''),
            'batch_uuid'=>(string)($s['batch_uuid'] ?? ''),
            'batch_index'=>(int)($s['batch_index'] ?? 0),
            'batch_total'=>(int)($s['batch_total'] ?? 0),

            'source_batch_id'=>(int)($s['source_batch_id'] ?? 0),
            'source_batch_run_id'=>(int)($s['source_batch_run_id'] ?? 0),
            'source_batch_run_order'=>(int)($s['source_batch_run_order'] ?? 0),
            'source_batch_type'=>(string)($s['source_batch_type'] ?? ''),
            'source_batch_origin'=>(string)($s['source_batch_origin'] ?? ''),
            'source_batch_test_variable'=>(string)($s['source_batch_test_variable'] ?? ''),
            'source_batch_test_value'=>(string)($s['source_batch_test_value'] ?? ''),
            'prediction_target_id'=>(string)($p['prediction_target_id'] ?? $s['prediction_target_id'] ?? ''),
            'prediction_target_key'=>(string)($p['prediction_target_key'] ?? $s['prediction_target_key'] ?? ''),
            'analysis_method_key'=>(string)($p['analysis_method_key'] ?? $s['analysis_method_key'] ?? $method),
            'origin_source'=>(string)($s['origin_source'] ?? ''),
            'source'=>(string)($s['source'] ?? $p['source'] ?? ''),
            'draw_date'=>$drawDate,
            'method'=>$method,
            'method_label'=>mleAdvisoryMethodLabel($method),
            'label'=>$label,
            'predicted'=>$pred,
            'predicted_ranking'=>$pred,
            'predicted_extra'=>$predExtra,
            'actual'=>$actual,
            'actual_extra'=>$actualExtra,
            'is_daily'=>$__isDailyForVisual,
            'pred_combo_strings'=>$__dailyComboStringsForVisual,
            'daily_pick_size'=>$__dailyPickSizeForVisual,
            'daily_ranked_digits'=>(array)($__dailyViewForVisual['ranked_digits'] ?? array()),
            'daily_bonus_digits'=>(array)($__dailyViewForVisual['bonus_digits'] ?? $__dailyViewForVisual['extra_digits'] ?? $__dailyViewForVisual['top_extras'] ?? array()),
            'matches'=>$matches,
            'extra_matches'=>$extraMatches,
            'main_hits'=>count($matches),
            'extra_hits'=>count($extraMatches),
            'total_hits'=>count($matches) + count($extraMatches),
            'avg_rank'=>$p['avg_winning_rank'] ?? null,
            'quality_score'=>$quality,
            'top10_hits'=>(int)($p['top10_hits'] ?? 0),
            'top20_hits'=>(int)($p['top20_hits'] ?? 0),
            'status'=>$__advStatusRaw,
            'status_explicit'=>$__advStatusExplicit,
            'actual_official_found'=>$__actualOfficialFound,
            'actual_source'=>(string)($__actualParts['source'] ?? 'official_draw_result'),
            'actual_missing_message'=>$__actualMissingMessage,
            'actual_cached_mismatch'=>!empty($__actualParts['cached_mismatch']),
            'completed'=>$__actualOfficialFound && (!empty($actual) || !empty($actualExtra)),
            'provenance_scope'=>(string)($__rowProvenance['scope'] ?? 'user_saved_prediction'),
            'provenance_label'=>(string)($__rowProvenance['label'] ?? 'Your Saved Prediction'),
            'provenance_trace'=>(string)($__rowProvenance['trace'] ?? ''),
            'provenance_explain'=>(string)($__rowProvenance['explain'] ?? ''),
            'is_user_prediction'=>(int)!empty($__rowProvenance['is_user_prediction']),
            'is_system_learning_only'=>(int)!empty($__rowProvenance['is_system_learning_only'])
        ));
        if ($sid > 0) { $usedSavedIds[$sid] = 1; }
    }

    foreach ($activeRows as $s) {
        $sid = (int)($s['id'] ?? 0);
        if ($sid <= 0 || isset($usedSavedIds[$sid])) { continue; }
        if (function_exists('mleAdvisoryIsSystemLearningOnlyRow') && mleAdvisoryIsSystemLearningOnlyRow($s)) { continue; }
        $__rowProvenance = function_exists('mleAdvisoryBuildRunProvenance') ? mleAdvisoryBuildRunProvenance($s, array()) : array('scope'=>'user_saved_prediction','label'=>'Your Saved Prediction','trace'=>'','is_user_prediction'=>true,'is_system_learning_only'=>false);
        $__dailyViewForVisual = mylottoexpertExtractDailySavedView($s);
        $__isDailyForVisual = !empty($__dailyViewForVisual['is_daily']);
        $__dailyComboStringsForVisual = array_values((array)($__dailyViewForVisual['combo_strings'] ?? array()));
        $__dailyPickSizeForVisual = (int)($__dailyViewForVisual['pick_size'] ?? 0);
        $__regularViewForVisual = mylottoexpertExtractRegularSavedView($s);
        if (function_exists('mylottoexpertShouldForceRegularPoolDisplay') && mylottoexpertShouldForceRegularPoolDisplay($s, $__regularViewForVisual)) {
            $__isDailyForVisual = false;
            $__dailyComboStringsForVisual = array();
            $__dailyPickSizeForVisual = 0;
        }
        $pred = array_values(array_map('intval', (array)($__regularViewForVisual['main'] ?? array())));
        $predExtra = array_values(array_map('intval', (array)($__regularViewForVisual['extra'] ?? array())));
        if (empty($pred)) { $pred = mylottoexpertParseNumberCsv($s['main_numbers'] ?? '', true); }
        if (empty($predExtra)) { $predExtra = mylottoexpertParseNumberCsv($s['extra_ball_numbers'] ?? '', true); }
        if ($__isDailyForVisual) {
            if (!empty($__dailyViewForVisual['primary_combo_digits'])) {
                $pred = array_values(array_map('intval', (array)$__dailyViewForVisual['primary_combo_digits']));
            } elseif (!empty($__dailyComboStringsForVisual)) {
                $pred = mleAdvisoryDigitArrayFromComboString((string)$__dailyComboStringsForVisual[0]);
            }
            if (!empty($__dailyViewForVisual['bonus_digits'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['bonus_digits']));
            } elseif (!empty($__dailyViewForVisual['extra_digits'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['extra_digits']));
            } elseif (!empty($__dailyViewForVisual['top_extras'])) {
                $predExtra = array_values(array_map('intval', (array)$__dailyViewForVisual['top_extras']));
            }
        }
        if (empty($pred) && empty($predExtra)) { continue; }
        $method = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey')
            ? mleAdvisoryResolveSavedEvidenceMethodKey($s)
            : (string)($s['__method_key'] ?? mleAdvisorySourceToMethodKey($s['source'] ?? ''));
        if ($method === '' || $method === 'unknown') { $method = (string)($s['__method_key'] ?? mleAdvisorySourceToMethodKey($s['source'] ?? '')); }
        if ($method === 'strategy_set') { continue; }
        $settings = mylottoexpertResolveRunDisplayInfo($s, array('skai_prediction'=>'AI','ai_prediction'=>'Core AI','core_ai'=>'Core AI','core_ai_prediction'=>'Core AI','mcmc_prediction'=>'MCMC','skip_hit'=>'Skip Hit','strategy_set'=>'Saved Run'));
        $__advSavedStatusRaw = (string)($s['advice_status'] ?? 'use_in_advice');
        $__advSavedStatusKey = strtolower(trim($__advSavedStatusRaw));

        $__advSavedStatusExplicit = (
            !empty($s['status_explicit']) ||
            !empty($s['advice_status_updated_at']) ||
            in_array($__advSavedStatusKey, array('watch','review','retired','archived','excluded','exclude','do_not_use'), true)
        );
        $drawDate = (string)($s['target_draw_date'] ?? $s['next_draw_date'] ?? $s['actual_draw_date'] ?? $s['latest_draw_date'] ?? '');
        if ($drawDate === '0000-00-00') { $drawDate = ''; }

        $actual = array();
        $actualExtra = array();
        $completed = false;
        $__actualParts = array(
            'found' => false,
            'source' => 'official_draw_result',
            'message' => 'Official draw result not loaded yet',
            'cached_mismatch' => false,
        );
        if ($drawDate !== '') {
            $drawTs = strtotime($drawDate);
            if ($drawTs !== false && $drawTs < time()) {
                try {
                    $__actualParts = mleAdvisoryResolveActualDrawPartsForVisual(
                        array('draw_date' => $drawDate),
                        $s, $pred, $predExtra
                    );
                    $actual = array_values(array_map('intval', (array)$__actualParts['main']));
                    $actualExtra = array_values(array_map('intval', (array)$__actualParts['extra']));
                    if (!empty($__actualParts['found']) && (!empty($actual) || !empty($actualExtra))) {
                        $completed = true;
                    }
                } catch (\Throwable $e) { }
            }
        }
        $matches = $completed ? array_values(array_intersect($pred, $actual)) : array();
        $extraMatches = $completed ? array_values(array_intersect($predExtra, $actualExtra)) : array();
        $addRow(array(
            'saved_id'=>$sid,
            'perf_id'=>0,

            'source_record_id'=>$sid,
            'run_uuid'=>(string)($s['run_uuid'] ?? ''),
            'snapshot_run_uuid'=>(string)($s['snapshot_run_uuid'] ?? ''),
            'run_identity_key'=>'',
            'batch_uuid'=>(string)($s['batch_uuid'] ?? ''),
            'batch_index'=>(int)($s['batch_index'] ?? 0),
            'batch_total'=>(int)($s['batch_total'] ?? 0),

            'source_batch_id'=>(int)($s['source_batch_id'] ?? 0),
            'source_batch_run_id'=>(int)($s['source_batch_run_id'] ?? 0),
            'source_batch_run_order'=>(int)($s['source_batch_run_order'] ?? 0),
            'source_batch_type'=>(string)($s['source_batch_type'] ?? ''),
            'source_batch_origin'=>(string)($s['source_batch_origin'] ?? ''),
            'source_batch_test_variable'=>(string)($s['source_batch_test_variable'] ?? ''),
            'source_batch_test_value'=>(string)($s['source_batch_test_value'] ?? ''),
            'prediction_target_id'=>(string)($s['prediction_target_id'] ?? ''),
            'prediction_target_key'=>(string)($s['prediction_target_key'] ?? ''),
            'analysis_method_key'=>(string)($s['analysis_method_key'] ?? $method),
            'origin_source'=>(string)($s['origin_source'] ?? ''),
            'source'=>(string)($s['source'] ?? ''),
            'draw_date'=>$drawDate,
            'method'=>$method,
            'method_label'=>mleAdvisoryMethodLabel($method),
            'label'=>(string)($settings['label'] ?? ($s['label'] ?? 'Saved run')),
            'predicted'=>$pred,
            'predicted_ranking'=>$pred,
            'predicted_extra'=>$predExtra,
            'actual'=>$actual,
            'actual_extra'=>$actualExtra,
            'is_daily'=>$__isDailyForVisual,
            'pred_combo_strings'=>$__dailyComboStringsForVisual,
            'daily_pick_size'=>$__dailyPickSizeForVisual,
            'daily_ranked_digits'=>(array)($__dailyViewForVisual['ranked_digits'] ?? array()),
            'daily_bonus_digits'=>(array)($__dailyViewForVisual['bonus_digits'] ?? $__dailyViewForVisual['extra_digits'] ?? $__dailyViewForVisual['top_extras'] ?? array()),
            'matches'=>$matches,
            'extra_matches'=>$extraMatches,
            'main_hits'=>count($matches),
            'extra_hits'=>count($extraMatches),
            'total_hits'=>count($matches) + count($extraMatches),
            'avg_rank'=>null,
            'quality_score'=>0.0,
            'top10_hits'=>0,
            'top20_hits'=>0,
            'status'=>$__advSavedStatusRaw,
            'status_explicit'=>$__advSavedStatusExplicit,
            'actual_official_found'=>!empty($__actualParts['found']),
            'actual_source'=>(string)($__actualParts['source'] ?? 'official_draw_result'),
            'actual_missing_message'=>trim((string)($__actualParts['message'] ?? '')),
            'actual_cached_mismatch'=>!empty($__actualParts['cached_mismatch']),
            'completed'=>$completed,
            'provenance_scope'=>(string)($__rowProvenance['scope'] ?? 'user_saved_prediction'),
            'provenance_label'=>(string)($__rowProvenance['label'] ?? 'Your Saved Prediction'),
            'provenance_trace'=>(string)($__rowProvenance['trace'] ?? ''),
            'provenance_explain'=>(string)($__rowProvenance['explain'] ?? ''),
            'is_user_prediction'=>(int)!empty($__rowProvenance['is_user_prediction']),
            'is_system_learning_only'=>(int)!empty($__rowProvenance['is_system_learning_only'])
        ));
    }

    $rows = array_values($rowsByKey);

    $officialByDrawDate = array();
    foreach ($rows as $__r) {
        $dd = trim((string)($__r['draw_date'] ?? ''));
        if ($dd === '' || empty($__r['completed'])) { continue; }
        if (!empty($__r['actual']) || !empty($__r['actual_extra'])) {
            if (!isset($officialByDrawDate[$dd])) {
                $officialByDrawDate[$dd] = array('actual'=>array(), 'actual_extra'=>array());
            }
            if (!empty($__r['actual']) && count((array)$__r['actual']) >= count((array)$officialByDrawDate[$dd]['actual'])) {
                $officialByDrawDate[$dd]['actual'] = array_values(array_map('intval', (array)$__r['actual']));
            }
            if (!empty($__r['actual_extra']) && count((array)$__r['actual_extra']) >= count((array)$officialByDrawDate[$dd]['actual_extra'])) {
                $officialByDrawDate[$dd]['actual_extra'] = array_values(array_map('intval', (array)$__r['actual_extra']));
            }
        }
    }
    foreach ($rows as $__i => $__r) {
        $dd = trim((string)($__r['draw_date'] ?? ''));
        if ($dd === '' || empty($__r['completed']) || empty($officialByDrawDate[$dd])) { continue; }

        if (!empty($officialByDrawDate[$dd]['actual'])) {
            $rows[$__i]['actual'] = $officialByDrawDate[$dd]['actual'];
        }
        if (!empty($officialByDrawDate[$dd]['actual_extra'])) {
            $rows[$__i]['actual_extra'] = $officialByDrawDate[$dd]['actual_extra'];
        }
        $rows[$__i]['matches'] = array_values(mleCountDuplicateAwareMatches((array)($rows[$__i]['actual'] ?? array()), (array)($rows[$__i]['predicted'] ?? array())));
        $rows[$__i]['extra_matches'] = array_values(mleCountDuplicateAwareMatches((array)($rows[$__i]['actual_extra'] ?? array()), (array)($rows[$__i]['predicted_extra'] ?? array())));
        $rows[$__i]['main_hits'] = count($rows[$__i]['matches']);
        $rows[$__i]['extra_hits'] = count($rows[$__i]['extra_matches']);
        $rows[$__i]['total_hits'] = (int)$rows[$__i]['main_hits'] + (int)$rows[$__i]['extra_hits'];
    }

    usort($rows, function($a,$b){
        if ((bool)$a['completed'] !== (bool)$b['completed']) { return $a['completed'] ? -1 : 1; }
        if ((int)$a['total_hits'] !== (int)$b['total_hits']) { return ((int)$b['total_hits'] - (int)$a['total_hits']); }
        if ((int)($a['top20_hits'] ?? 0) !== (int)($b['top20_hits'] ?? 0)) { return (int)($b['top20_hits'] ?? 0) - (int)($a['top20_hits'] ?? 0); }
        if ((int)($a['top10_hits'] ?? 0) !== (int)($b['top10_hits'] ?? 0)) { return (int)($b['top10_hits'] ?? 0) - (int)($a['top10_hits'] ?? 0); }
        $aq = (float)($a['quality_score'] ?? 0); $bq = (float)($b['quality_score'] ?? 0);
        if (abs($aq - $bq) > 0.000001) { return ($bq > $aq) ? 1 : -1; }
        return strcmp((string)$b['draw_date'], (string)$a['draw_date']);
    });

    $completed = array(); $upcoming = array();
    foreach ($rows as $r) {
        if ($r['completed']) { $completed[]=$r; } else { $upcoming[]=$r; }
    }
    if (!empty($completed)) { $completed[0]['is_best_overall'] = true; }
    return array('recent'=>array_slice($completed,0,6),'older'=>array_slice($completed,6),'upcoming'=>$upcoming);
}

if (!function_exists('mleAdvisoryRunPredictionCount')) {
    function mleAdvisoryRunPredictionCount(array $row): int
    {
        $main = (array)($row['predicted'] ?? array());
        $extra = (array)($row['predicted_extra'] ?? array());
        $combos = (array)($row['pred_combo_strings'] ?? array());
        $dailyDigits = (array)($row['daily_ranked_digits'] ?? array());
        return count(array_unique(array_map('strval', array_merge($main, $extra, $combos, $dailyDigits))));
    }
}

if (!function_exists('mleAdvisoryRunSpreadScore')) {
    function mleAdvisoryRunSpreadScore(array $numbers): float
    {
        $numbers = array_values(array_unique(array_map('intval', $numbers)));
        $numbers = array_values(array_filter($numbers, static function($v){ return $v > 0; }));
        $count = count($numbers);
        if ($count <= 1) { return 0.45; }
        sort($numbers);
        $range = max($numbers) - min($numbers);
        $avgGap = $range / max(1, $count - 1);
        $clusterPenalty = 0.0;
        for ($i = 1; $i < $count; $i++) {
            if (($numbers[$i] - $numbers[$i - 1]) <= 1) { $clusterPenalty += 0.05; }
        }
        $rangeScore = min(1.0, max(0.0, $range / max(1, max($numbers))));
        $gapScore = min(1.0, max(0.0, $avgGap / 6.0));
        return max(0.0, min(1.0, (0.65 * $rangeScore) + (0.35 * $gapScore) - $clusterPenalty));
    }
}

if (!function_exists('mleAdvisoryPendingRunEvidenceScore')) {
    function mleAdvisoryPendingRunEvidenceScore(array $run, array $context, array $selectedRuns = array()): array
    {
        $score = 28.0;
        $reasons = array();
        $warnings = array();

        $scoredRuns = max(0, (int)($context['scored_runs'] ?? 0));
        $drawCycles = max(0, (int)($context['draw_cycles'] ?? 0));
        $strongCount = max(0, (int)($context['strong_count'] ?? 0));
        $method = strtolower((string)($run['method'] ?? ''));
        $methodLabel = trim((string)($run['method_label'] ?? 'Saved run'));
        $label = strtolower((string)($run['label'] ?? ''));
        $topMethod = strtolower((string)($context['top_method'] ?? ''));
        $precisionStage = strtolower((string)($context['precision_stage'] ?? ''));
        $progressKey = strtolower((string)($context['progress_key'] ?? ''));
        $predCount = mleAdvisoryRunPredictionCount($run);
        $hasNumbers = $predCount > 0;

        $score += min(16.0, $scoredRuns * 0.28);
        if ($scoredRuns >= 45) { $reasons[] = 'meaningful scored-run history'; }
        elseif ($scoredRuns >= 18) { $reasons[] = 'some scored-run history'; }
        else { $warnings[] = 'thin scored-run history'; }

        $score += min(16.0, $drawCycles * 1.25);
        if ($drawCycles >= 6) { $reasons[] = 'multiple completed draw cycles'; }
        elseif ($drawCycles >= 3) { $reasons[] = 'early draw-cycle prediction history'; }
        else { $warnings[] = 'few completed draw cycles'; }

        if ($hasNumbers) { $score += 8.0; $reasons[] = 'saved numbers are present'; }
        else { $score -= 25.0; $warnings[] = 'missing saved numbers'; }

        if ($topMethod !== '' && $method !== '' && $method === $topMethod) {
            $score += 10.0;
            $reasons[] = 'matches the current leading method';
        } elseif ($method === 'skai') {
            $score += 6.0;
            $reasons[] = 'AI run';
        }

        if (strpos($label, 'control') !== false || strpos($label, 'current strongest') !== false) {
            $score += 8.0;
            $reasons[] = 'control/current-strongest test point';
        }
        if (strpos($label, 'precision') !== false || strpos($label, 'narrow') !== false || strpos($label, 'focus') !== false || strpos($label, 'recommended') !== false) {
            $score += 9.0;
            $reasons[] = 'tied to the Precision Focus plan';
        }
        if (strpos($label, 'divers') !== false || strpos($label, 'alternate') !== false) {
            $score += 4.0;
            $reasons[] = 'useful alternate / diversity test';
        }

        if ($strongCount >= 3) { $score += 8.0; $reasons[] = 'supported by repeated strong prediction history'; }
        elseif ($strongCount >= 1) { $score += 4.0; $reasons[] = 'some strong prediction history exists'; }

        if (strpos($precisionStage, 'precision') !== false || strpos($progressKey, 'precision') !== false) {
            $score += 6.0;
            $reasons[] = 'higher precision-progress stage';
        } elseif (strpos($precisionStage, 'validated') !== false || strpos($progressKey, 'validated') !== false) {
            $score += 5.0;
            $reasons[] = 'validated-focus progress stage';
        } elseif (strpos($precisionStage, 'narrow') !== false || strpos($progressKey, 'narrow') !== false) {
            $score += 3.0;
            $reasons[] = 'narrowing signal is forming';
        }

        $spread = mleAdvisoryRunSpreadScore((array)($run['predicted'] ?? array()));
        $score += 7.0 * $spread;
        if ($spread >= 0.62) { $reasons[] = 'healthy number spread'; }
        elseif ($spread < 0.35 && $hasNumbers) { $warnings[] = 'number spread is concentrated'; }

        if (!empty($selectedRuns) && $hasNumbers) {
            $main = array_values(array_unique(array_map('intval', (array)($run['predicted'] ?? array()))));
            $maxOverlapRatio = 0.0;
            foreach ($selectedRuns as $sel) {
                $selMain = array_values(array_unique(array_map('intval', (array)($sel['predicted'] ?? array()))));
                if (empty($main) || empty($selMain)) { continue; }
                $overlap = count(array_intersect($main, $selMain));
                $ratio = $overlap / max(1, min(count($main), count($selMain)));
                if ($ratio > $maxOverlapRatio) { $maxOverlapRatio = $ratio; }
            }
            if ($maxOverlapRatio >= 0.75) {
                $score -= 7.0;
                $warnings[] = 'high overlap with another highlighted run';
            } elseif ($maxOverlapRatio <= 0.45) {
                $score += 4.0;
                $reasons[] = 'good alternate coverage';
            }
        }

        $score = (int)round(max(0, min(100, $score)));
        $reasonText = 'Best available balance of saved numbers, prediction history history, method alignment, stability, and coverage quality.';
        if (!empty($reasons)) {
            $reasonText = ucfirst(implode('; ', array_slice(array_values(array_unique($reasons)), 0, 4))) . '.';
        }
        if (!empty($warnings)) {
            $reasonText .= ' Caution: ' . implode('; ', array_slice(array_values(array_unique($warnings)), 0, 2)) . '.';
        }
        return array('score' => $score, 'reason' => $reasonText, 'warnings' => $warnings, 'has_numbers' => $hasNumbers, 'method_label' => $methodLabel);
    }
}

if (!function_exists('mleAdvisoryCleanHiveKey')) {
    function mleAdvisoryCleanHiveKey($value): string
    {
        $value = strtolower(trim((string)$value));
        $value = str_replace(array('-', '_'), ' ', $value);
        $value = preg_replace('/[^a-z0-9]+/', ' ', $value);
        return trim(preg_replace('/\s+/', ' ', $value));
    }
}

if (!function_exists('mleAdvisoryHiveTextMatches')) {
    function mleAdvisoryHiveTextMatches($a, $b): bool
    {
        $a = mleAdvisoryCleanHiveKey($a);
        $b = mleAdvisoryCleanHiveKey($b);
        if ($a === '' || $b === '') { return false; }
        if ($a === $b) { return true; }
        return (strpos($a, $b) !== false || strpos($b, $a) !== false);
    }
}

if (!function_exists('mleAdvisoryPendingRunHiveRecommendationScore')) {
    function mleAdvisoryPendingRunHiveRecommendationScore(array $run, array $context): array
    {
        $score = 0.0;
        $reasons = array();
        $warnings = array();
        $sourceLabel = 'Strongest scored Shared AI Learning settings';
        $hasHiveProfile = false;

        $method = strtolower(trim((string)($run['method'] ?? $run['analysis_method_key'] ?? '')));
        $topMethod = strtolower(trim((string)($context['top_method'] ?? '')));
        $label = strtolower(trim((string)($run['label'] ?? '')));
        $lock = is_array($context['hive_current_lock'] ?? null) ? (array)$context['hive_current_lock'] : array();
        $precision = is_array($context['hive_precision_lock'] ?? null) ? (array)$context['hive_precision_lock'] : array();
        $settingsAdv = is_array($context['hive_settings_advice'] ?? null) ? (array)$context['hive_settings_advice'] : array();
        $recommendationLevel = is_array($context['hive_recommendation_level'] ?? null) ? (array)$context['hive_recommendation_level'] : array();
        $progress = is_array($context['hive_precision_progress'] ?? null) ? (array)$context['hive_precision_progress'] : array();

        $lockStatus = strtolower(trim((string)($lock['status'] ?? $lock['locked_status'] ?? '')));
        $lockReady = !empty($lock['has_active_lock']) || !empty($lock['persisted_lock_id']) || in_array($lockStatus, array('locked for testing','precision focus candidate','elite baseline','precision lock candidate'), true);
        $precisionStage = strtolower(trim((string)($precision['stage'] ?? $precision['stage_label'] ?? '')));
        $progressKey = strtolower(trim((string)($progress['current_key'] ?? $progress['level_key'] ?? '')));
        $precisionReady = !empty($precision['has_range']) || strpos($precisionStage, 'precision') !== false || strpos($precisionStage, 'validated') !== false || strpos($progressKey, 'precision') !== false || strpos($progressKey, 'validated') !== false;
        $settingsReady = !empty($settingsAdv['has_advice']) || trim((string)($settingsAdv['setting'] ?? $settingsAdv['setting_key'] ?? '')) !== '';
        $sharedProfile = is_array($context['hive_shared_profile'] ?? null) ? (array)$context['hive_shared_profile'] : array();
        $sharedAvailable = !empty($sharedProfile['available']);
        $sharedStatus = strtolower(trim((string)($sharedProfile['status'] ?? '')));
        $sharedReady = $sharedAvailable && in_array($sharedStatus, array('ready','strong','active'), true);
        $sharedEvidenceRuns = (int)($sharedProfile['evidence_runs'] ?? 0);
        $sharedEvidenceUsers = (int)($sharedProfile['evidence_users'] ?? 0);

        if ($sharedReady || $sharedEvidenceRuns > 0) {
            $hasHiveProfile = true;
            $sourceLabel = 'LottoExpert Learning';
            $score += $sharedReady ? 34.0 : 22.0;
            if ($sharedEvidenceRuns > 0) { $score += min(16.0, $sharedEvidenceRuns * 0.20); }
            if ($sharedEvidenceUsers > 1) { $score += min(8.0, $sharedEvidenceUsers * 1.5); }
            $reasons[] = 'uses LottoExpert Learning from all scored saved predictions for this lottery';
        }

        if ($lockReady) {
            $hasHiveProfile = true;
            if (!$sharedReady && $sharedEvidenceRuns <= 0) {
                $sourceLabel = 'LottoExpert Learning';
            }
            $score += 30.0;
            $reasons[] = 'matches the active learned-settings profile';
        } elseif ($precisionReady) {
            $hasHiveProfile = true;
            $sourceLabel = 'LottoExpert Learning';
            $score += 20.0;
            $reasons[] = 'uses the current LottoExpert Learning precision-progress profile';
        } elseif ($settingsReady) {
            $hasHiveProfile = true;
            $sourceLabel = 'LottoExpert Learning';
            $score += 16.0;
            $reasons[] = 'uses the current LottoExpert Learning settings-advice profile';
        }

        $preferredMethod = strtolower(trim((string)($lock['method'] ?? $lock['source'] ?? '')));
        if ($preferredMethod === '') { $preferredMethod = $topMethod; }
        if ($preferredMethod !== '' && $method !== '') {
            if ($method === $preferredMethod || mleAdvisoryHiveTextMatches($method, $preferredMethod)) {
                $score += 24.0;
                $reasons[] = 'matches the LottoExpert Learning preferred method';
            } elseif ($method === $topMethod && $topMethod !== '') {
                $score += 12.0;
                $reasons[] = 'matches the strongest scored Shared AI Learning method currently available';
            } else {
                $score -= 8.0;
                $warnings[] = 'method is not the current LottoExpert Learning leader';
            }
        }

        $baseRunId = (int)($lock['base_run_id'] ?? $lock['base_settings_id'] ?? 0);
        $runIds = array(
            (int)($run['saved_id'] ?? 0),
            (int)($run['source_record_id'] ?? 0),
            (int)($run['source_batch_run_id'] ?? 0),
            (int)($run['source_batch_id'] ?? 0)
        );
        if ($baseRunId > 0 && in_array($baseRunId, $runIds, true)) {
            $score += 28.0;
            $reasons[] = 'directly tied to the saved LottoExpert Learning baseline run';
        }

        $rangeBasis = trim((string)($lock['range_basis'] ?? $precision['control_label'] ?? $settingsAdv['label'] ?? $settingsAdv['setting_label'] ?? ''));
        $settingKey = trim((string)($settingsAdv['setting'] ?? $settingsAdv['setting_key'] ?? ''));
        $testVar = trim((string)($run['source_batch_test_variable'] ?? $run['test_variable'] ?? ''));
        $testValueRaw = trim((string)($run['source_batch_test_value'] ?? $run['test_value'] ?? ''));
        $rangeMin = null;
        $rangeMax = null;
        if (isset($lock['range_min']) && isset($lock['range_max']) && is_numeric($lock['range_min']) && is_numeric($lock['range_max'])) {
            $rangeMin = (float)$lock['range_min'];
            $rangeMax = (float)$lock['range_max'];
        } elseif (isset($precision['range_min']) && isset($precision['range_max']) && is_numeric($precision['range_min']) && is_numeric($precision['range_max'])) {
            $rangeMin = (float)$precision['range_min'];
            $rangeMax = (float)$precision['range_max'];
        }

        $varMatches = false;
        if ($testVar !== '') {
            $varMatches = mleAdvisoryHiveTextMatches($testVar, $rangeBasis) || mleAdvisoryHiveTextMatches($testVar, $settingKey);
            if ($varMatches) {
                $score += 15.0;
                $reasons[] = 'tests the current LottoExpert Learning focus setting';
            }
        }
        if ($testValueRaw !== '' && is_numeric($testValueRaw) && $rangeMin !== null && $rangeMax !== null) {
            $testValue = (float)$testValueRaw;
            $lo = min($rangeMin, $rangeMax);
            $hi = max($rangeMin, $rangeMax);
            if ($testValue >= $lo && $testValue <= $hi) {
                $score += $varMatches ? 18.0 : 9.0;
                $reasons[] = 'inside the current LottoExpert Learning focus range';
            } elseif ($varMatches) {
                $score -= 6.0;
                $warnings[] = 'outside the current LottoExpert Learning focus range';
            }
        }

        if (strpos($label, 'control') !== false || strpos($label, 'current strongest') !== false || strpos($label, 'baseline') !== false) {
            $score += 9.0;
            $reasons[] = 'control or baseline candidate';
        }
        if (strpos($label, 'precision') !== false || strpos($label, 'focus') !== false || strpos($label, 'recommended') !== false || strpos($label, 'narrow') !== false) {
            $score += 10.0;
            $reasons[] = 'explicitly marked as a LottoExpert Learning precision candidate';
        }
        if (!empty($recommendationLevel['level']) || !empty($recommendationLevel['label'])) {
            $score += 4.0;
            $reasons[] = 'supported by the current recommendation level';
        }

        $score = (int)round(max(0, min(100, $score)));
        if (!$hasHiveProfile) {
            return array(
                'has_hive_profile' => false,
                'score' => 0,
                'source' => $sourceLabel,
                'reason' => 'AI is still narrowing this lottery’s Learning Profile, so LottoExpert is using the strongest scored Shared AI Learning settings currently available while more prediction history is collected.',
                'warnings' => $warnings
            );
        }

        $reasonText = 'Ranked against the current LottoExpert Learning profile.';
        if (!empty($reasons)) {
            $reasonText = ucfirst(implode('; ', array_slice(array_values(array_unique($reasons)), 0, 4))) . '.';
        }
        if (!empty($warnings)) {
            $reasonText .= ' Caution: ' . implode('; ', array_slice(array_values(array_unique($warnings)), 0, 2)) . '.';
        }

        return array(
            'has_hive_profile' => true,
            'score' => $score,
            'source' => $sourceLabel,
            'reason' => $reasonText,
            'warnings' => $warnings
        );
    }
}

if (!function_exists('mleAdvisoryBuildPendingDrawRecommendations')) {
    function mleAdvisoryBuildPendingDrawRecommendations(array $upcomingRows, array $completedRows, array $context): array
    {
        $out = array(
            'has_pending' => !empty($upcomingRows),
            'confidence' => 'not_ready',
            'confidence_label' => 'Not Ready',
            'title' => 'Recommendation status',
            'summary' => 'No pending saved runs are available for a responsible recommendation yet.',
            'draw_date' => '',
            'top' => array(),
            'all' => array(),
            'note' => '',
        );
        if (empty($upcomingRows)) { return $out; }

        $groups = array();
        foreach ($upcomingRows as $r) {
            $dd = trim((string)($r['draw_date'] ?? ''));
            if ($dd === '' || $dd === '0000-00-00') { $dd = 'Upcoming'; }
            if (!isset($groups[$dd])) { $groups[$dd] = array(); }
            $groups[$dd][] = $r;
        }
        uksort($groups, static function($a, $b){
            if ($a === 'Upcoming') { return 1; }
            if ($b === 'Upcoming') { return -1; }
            return strcmp($a, $b);
        });
        $drawDate = (string)array_key_first($groups);
        $pendingForDraw = array_values((array)$groups[$drawDate]);

        $batchGroups = array();
        foreach ($upcomingRows as $r) {
            if (!is_array($r)) { continue; }
            $dd = trim((string)($r['draw_date'] ?? ''));
            if ($dd === '' || $dd === '0000-00-00') { $dd = 'Upcoming'; }
            $batchKey = trim((string)($r['batch_uuid'] ?? ''));
            if ($batchKey === '') {
                $sourceBatchId = (int)($r['source_batch_id'] ?? 0);
                if ($sourceBatchId > 0) { $batchKey = 'source_batch:' . $sourceBatchId; }
            }
            if ($batchKey === '') {
                $targetKey = trim((string)($r['prediction_target_key'] ?? $r['prediction_target_id'] ?? ''));
                if ($targetKey !== '') { $batchKey = 'target:' . $targetKey; }
            }
            if ($batchKey === '') { continue; }
            $groupKey = $batchKey . '|draw:' . $dd;
            if (!isset($batchGroups[$groupKey])) {
                $batchGroups[$groupKey] = array('draw_date' => $dd, 'rows' => array(), 'expected_total' => 0, 'has_batch_identity' => true);
            }
            $batchGroups[$groupKey]['rows'][] = $r;
            $batchTotal = (int)($r['batch_total'] ?? 0);
            if ($batchTotal > (int)$batchGroups[$groupKey]['expected_total']) { $batchGroups[$groupKey]['expected_total'] = $batchTotal; }
        }
        $bestBatchGroup = null;
        foreach ($batchGroups as $batchGroup) {
            $rowCount = count((array)($batchGroup['rows'] ?? array()));
            $expectedTotal = (int)($batchGroup['expected_total'] ?? 0);
            $isFullExpectedBatch = ($expectedTotal >= 9 && $rowCount >= min(9, $expectedTotal));
            $isNineRunGroup = ($rowCount >= 9);
            if (!$isFullExpectedBatch && !$isNineRunGroup) { continue; }
            if ($bestBatchGroup === null) { $bestBatchGroup = $batchGroup; continue; }
            $bestCount = count((array)($bestBatchGroup['rows'] ?? array()));
            $bestExpected = (int)($bestBatchGroup['expected_total'] ?? 0);
            $score = ($isFullExpectedBatch ? 100000 : 0) + ($isNineRunGroup ? 50000 : 0) + ($rowCount * 100) + $expectedTotal;
            $bestScore = (($bestExpected >= 9 && $bestCount >= min(9, $bestExpected)) ? 100000 : 0) + ($bestCount >= 9 ? 50000 : 0) + ($bestCount * 100) + $bestExpected;
            if ($score > $bestScore) { $bestBatchGroup = $batchGroup; }
        }

        $out['draw_date'] = $drawDate;

        $scoredRuns = max(0, (int)($context['scored_runs'] ?? count($completedRows)));
        $drawCycles = max(0, (int)($context['draw_cycles'] ?? 0));
        $completedCount = count($completedRows);
        $hasEnoughPending = count($pendingForDraw) >= 2;
        $hasBasicHistory = ($completedCount >= 3 || $scoredRuns >= 3);
        $hasStrongHistory = ($completedCount >= 5 && $scoredRuns >= 5 && $drawCycles >= 1);

        $scored = array();
        $hasHiveRanker = false;
        foreach ($pendingForDraw as $r) {
            $eval = mleAdvisoryPendingRunEvidenceScore($r, $context, array_column($scored, 'row'));
            $hiveEval = mleAdvisoryPendingRunHiveRecommendationScore($r, $context);
            $evidenceScore = (int)$eval['score'];
            $hiveScore = (int)$hiveEval['score'];
            $isHive = !empty($hiveEval['has_hive_profile']);
            if ($isHive) { $hasHiveRanker = true; }
            $finalScore = $isHive ? (int)round(($hiveScore * 0.72) + ($evidenceScore * 0.28)) : $evidenceScore;
            $r['pending_evidence_score'] = $evidenceScore;
            $r['pending_evidence_reason'] = (string)$eval['reason'];
            $r['pending_hive_score'] = $hiveScore;
            $r['pending_hive_reason'] = (string)$hiveEval['reason'];
            $r['pending_hive_source'] = (string)$hiveEval['source'];
            $r['pending_hive_governed'] = $isHive ? 1 : 0;
            $r['pending_recommendation_score'] = $finalScore;
            $r['pending_recommendation_source'] = $isHive ? (string)$hiveEval['source'] : 'Strongest scored Shared AI Learning settings';
            $r['pending_has_numbers'] = !empty($eval['has_numbers']);
            $scored[] = array('row' => $r, 'score' => $finalScore, 'hive_score' => $hiveScore, 'evidence_score' => $evidenceScore);
        }
        usort($scored, static function($a, $b) use ($hasHiveRanker){
            if ($hasHiveRanker) {
                if ((int)$a['score'] !== (int)$b['score']) { return (int)$b['score'] - (int)$a['score']; }
                if ((int)$a['hive_score'] !== (int)$b['hive_score']) { return (int)$b['hive_score'] - (int)$a['hive_score']; }
            } else {
                if ((int)$a['evidence_score'] !== (int)$b['evidence_score']) { return (int)$b['evidence_score'] - (int)$a['evidence_score']; }
            }
            return strcmp((string)($a['row']['label'] ?? ''), (string)($b['row']['label'] ?? ''));
        });
        $ranked = array();
        foreach ($scored as $item) { $ranked[] = $item['row']; }
        $out['all'] = $ranked;
        $out['ranking_source'] = $hasHiveRanker ? 'hive_learned_settings' : 'strongest_scored_hive_settings';
        $out['ranking_source_label'] = $hasHiveRanker ? 'LottoExpert Learning' : 'Strongest scored Shared AI Learning settings';

        $top = array_slice($ranked, 0, 2);
        $topScore = isset($top[0]) ? (int)($top[0]['pending_recommendation_score'] ?? $top[0]['pending_evidence_score'] ?? 0) : 0;
        $secondScore = isset($top[1]) ? (int)($top[1]['pending_recommendation_score'] ?? $top[1]['pending_evidence_score'] ?? 0) : 0;
        $avgScore = 0.0;
        if (!empty($ranked)) {
            foreach ($ranked as $r) { $avgScore += (int)($r['pending_recommendation_score'] ?? $r['pending_evidence_score'] ?? 0); }
            $avgScore = $avgScore / max(1, count($ranked));
        }
        $marginVsSecond = $topScore - $secondScore;
        $marginVsAvg = $topScore - $avgScore;
        $allTopHaveNumbers = !empty($top);
        foreach ($top as $r) { if (empty($r['pending_has_numbers'])) { $allTopHaveNumbers = false; } }

        if (!$hasEnoughPending || !$allTopHaveNumbers || !$hasBasicHistory) {
            $out['confidence'] = 'not_ready';
            $out['confidence_label'] = 'Not Ready';
            $out['top'] = array();
            $out['summary'] = 'Pending numbers are saved for this draw, but there is not enough completed-run prediction history to responsibly choose a top two yet.';
            $out['note'] = 'You may still review all pending runs. LottoExpert recommends waiting for more completed scored runs before treating any pending set as preferred.';
            return $out;
        }

        $out['top'] = $top;
        if ($hasStrongHistory && $topScore >= 78 && ($marginVsSecond >= 5 || $marginVsAvg >= 7)) {
            $out['confidence'] = 'strong';
            $out['confidence_label'] = 'Strong';
            $out['summary'] = $hasHiveRanker ? 'Top 2 recommendations are selected from the current LottoExpert Learning profile for this lottery.' : 'Top 2 recommendations are available for this pending draw based on the strongest available completed prediction history.';
            $out['note'] = 'These are still pending predictions, not guarantees. Review them first after the draw and score the full group.';
        } else {
            $out['confidence'] = 'limited';
            $out['confidence_label'] = 'Limited';
            $out['summary'] = $hasHiveRanker ? 'LottoExpert Learning can rank the saved pending runs, but the prediction history margin is still limited.' : 'LottoExpert can rank the saved pending runs, but the prediction history base is still thin or the score margin is not yet strong.';
            $out['note'] = $hasHiveRanker ? 'These are the best current pending options according to LottoExpert Learning. Use caution until more completed draw cycles confirm the margin.' : 'These are the best current options from the saved pending runs, but use caution until more completed draw cycles build up.';
        }
        return $out;
    }
}

function mleAdvisoryBuildBatchCleanupRecommendationFromVisual(array $visualRows) {
    $scored = array_merge(
        (array)($visualRows['recent'] ?? array()),
        (array)($visualRows['older'] ?? array())
    );

    $upcomingExplicit = array();
    foreach ((array)($visualRows['upcoming'] ?? array()) as $uRow) {
        if (!is_array($uRow)) { continue; }
        if (!empty($uRow['status_explicit'])) {
            $upcomingExplicit[] = $uRow;
        }
    }

    $all = $scored;

    if (empty($all) && empty($upcomingExplicit)) {
        return array('has_recommendation' => false);
    }

    if (empty($all)) {

        $all = array();
    }

    $normalizeStatus = function ($status) {
        $status = strtolower(trim((string)$status));

        if (in_array($status, array('use_in_advice', 'use', 'keep', 'active'), true)) {
            return 'keep';
        }

        if (in_array($status, array('watch', 'review', 'keep_for_review'), true)) {
            return 'review';
        }

        if (in_array($status, array('retired', 'excluded', 'exclude', 'archive', 'archived', 'do_not_use'), true)) {
            return 'archive';
        }

        return '';
    };

    $sortRuns = function (array $rows) {
        usort($rows, function ($a, $b) {
            $aHits = (int)($a['total_hits'] ?? 0);
            $bHits = (int)($b['total_hits'] ?? 0);

            if ($bHits !== $aHits) {
                return $bHits - $aHits;
            }

            $aQuality = is_numeric($a['quality_score'] ?? null) ? (float)$a['quality_score'] : 0.0;
            $bQuality = is_numeric($b['quality_score'] ?? null) ? (float)$b['quality_score'] : 0.0;

            if (abs($bQuality - $aQuality) > 0.00001) {
                return ($bQuality > $aQuality) ? 1 : -1;
            }

            return strcmp((string)($b['draw_date'] ?? ''), (string)($a['draw_date'] ?? ''));
        });

        return $rows;
    };

    $explicitKeep = array();
    $explicitReview = array();
    $explicitArchive = array();
    $unassigned = array();

    foreach ($all as $row) {
        if (!is_array($row)) {
            continue;
        }

        $statusIsExplicit = !empty($row['status_explicit']);
        $statusGroup = $statusIsExplicit ? $normalizeStatus($row['status'] ?? '') : '';

        if ($statusGroup === 'keep') {
            $explicitKeep[] = $row;
        } elseif ($statusGroup === 'review') {
            $explicitReview[] = $row;
        } elseif ($statusGroup === 'archive') {
            $explicitArchive[] = $row;
        } else {
            $unassigned[] = $row;
        }
    }

    foreach ($upcomingExplicit as $uRow) {
        $uGroup = $normalizeStatus($uRow['status'] ?? '');
        if ($uGroup === 'keep') {
            $explicitKeep[] = $uRow;
        } elseif ($uGroup === 'review') {
            $explicitReview[] = $uRow;
        } else {

            $explicitArchive[] = $uRow;
        }
    }

    $unassigned = $sortRuns($unassigned);

    $totalUnassigned = count($unassigned);
    $autoKeepCount = min(2, $totalUnassigned);
    $autoReviewCount = min(3, max(0, $totalUnassigned - $autoKeepCount));

    $autoKeep = array_slice($unassigned, 0, $autoKeepCount);
    $autoReview = array_slice($unassigned, $autoKeepCount, $autoReviewCount);
    $autoArchive = array_slice($unassigned, $autoKeepCount + $autoReviewCount);

    $isStrongLearningRun = function (array $row) {
        $mainHits = (int)($row['main_hits'] ?? 0);
        $totalHits = (int)($row['total_hits'] ?? 0);
        $actualMain = (array)($row['actual'] ?? array());
        $expectedMain = count($actualMain);
        if ($expectedMain <= 0) {
            $expectedMain = (int)($row['pick_count'] ?? $row['main_count'] ?? $row['target_pick_size'] ?? 0);
        }
        if ($expectedMain <= 0) {
            $expectedMain = max(5, $mainHits);
        }
        if ($expectedMain > 0 && $mainHits >= $expectedMain) {
            return true;
        }
        if ($expectedMain >= 5 && $mainHits >= ($expectedMain - 1)) {
            return true;
        }
        if ($totalHits >= 4 && $mainHits >= 3) {
            return true;
        }
        return false;
    };

    if (!empty($autoArchive)) {
        $guardedReview = array();
        $safeArchive = array();
        foreach ($autoArchive as $archRow) {
            if (is_array($archRow) && $isStrongLearningRun($archRow)) {
                $archRow['auto_reason'] = 'Strong hit result kept for review instead of auto-exclude.';
                $guardedReview[] = $archRow;
            } else {
                $safeArchive[] = $archRow;
            }
        }
        if (!empty($guardedReview)) {
            $autoReview = array_merge($autoReview, $guardedReview);
        }
        $autoArchive = $safeArchive;
    }

    return array(
        'has_recommendation' => true,
        'total_runs' => count($all) + count($upcomingExplicit),
        'keep' => $sortRuns(array_merge($explicitKeep, $autoKeep)),
        'review' => $sortRuns(array_merge($explicitReview, $autoReview)),
        'archive' => $sortRuns(array_merge($explicitArchive, $autoArchive))
    );
}

function mleAdvisoryBuildBatchCleanupRecommendation($db, $userId, $lotteryId) {
    $active = mleAdvisoryBuildActiveSavedEvidence($db, $userId);
    $rows = isset($active[(int)$lotteryId]['rows']) ? $active[(int)$lotteryId]['rows'] : array();
    $perf = mleAdvisoryLoadMatchedPerformance($db, $userId, $lotteryId, $rows);
    return mleAdvisoryBuildBatchCleanupRecommendationFromVisual(mleAdvisoryBuildVisualRunRows($rows, $perf));
}

function mleAdvisoryLoadSavedSettingsForLottery($db, $userId, $lotteryId, $limit = 30) {
    $userId = (int)$userId; $lotteryId = (int)$lotteryId; $limit = max(1, min(100, (int)$limit));
    if ($userId <= 0 || $lotteryId <= 0) { return array(); }
    $cols = mleAdvisoryGetTableColumnsSafe($db, '#__user_saved_settings');
    if (empty($cols)) { return array(); }
    $select = array(); foreach ($cols as $c) { $select[] = $db->quoteName($c); }
    try {
        $q = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__user_saved_settings'))
            ->where($db->quoteName('user_id') . ' = ' . $userId)
            ->where($db->quoteName('lottery_id') . ' = ' . $lotteryId);
        if (in_array('status', $cols, true)) {
            $q->where('LOWER(COALESCE(' . $db->quoteName('status') . ', ' . $db->quote('') . ')) NOT IN (' . $db->quote('deleted') . ',' . $db->quote('archived') . ',' . $db->quote('retired') . ')');
        }
        if (in_array('created_at', $cols, true)) {
            $q->order($db->quoteName('created_at') . ' DESC');
        } else {
            $q->order($db->quoteName('id') . ' DESC');
        }
        $db->setQuery($q, 0, $limit);
        $rows = $db->loadAssocList();
        return is_array($rows) ? $rows : array();
    } catch (\Throwable $e) { return array(); }
}

function mleAdvisoryLoadNumbersToPlayForLottery($db, $userId, $lotteryId, $limit = 30) {
    $userId = (int)$userId; $lotteryId = (int)$lotteryId; $limit = max(1, min(100, (int)$limit));
    if ($userId <= 0 || $lotteryId <= 0) { return array(); }
    $cols = mleAdvisoryGetTableColumnsSafe($db, '#__user_saved_numbers');
    if (empty($cols)) { return array(); }
    $select = array(); foreach ($cols as $c) { $select[] = 'sn.' . $db->quoteName($c); }
    try {
        $heatmapSourcesSql = array(
            $db->quote('heatmap_manual'),
            $db->quote('manual_heatmap'),
            $db->quote('heatmap'),
            $db->quote('heat_map'),
            $db->quote('frequency_heatmap'),
            $db->quote('frequency_map')
        );
        $q = $db->getQuery(true)
            ->select($select)
            ->from($db->quoteName('#__user_saved_numbers', 'sn'))
            ->where('sn.' . $db->quoteName('user_id') . ' = ' . $userId)
            ->where('sn.' . $db->quoteName('lottery_id') . ' = ' . $lotteryId)
            ->where("(sn." . $db->quoteName('source') . " = " . $db->quote('strategy_set') . " OR LOWER(COALESCE(sn." . $db->quoteName('source') . ",'')) IN (" . implode(',', $heatmapSourcesSql) . "))");
        if (in_array('save_intent', $cols, true)) {
            $q->where("(sn.save_intent IN ('play_set','custom_play','wheel_candidate') OR COALESCE(sn.save_intent,'') = '')");
        }
        if (in_array('play_status', $cols, true)) {
            $q->where("LOWER(COALESCE(sn.play_status,'')) NOT IN ('deleted','archived','retired')");
        }
        $q->order('COALESCE(sn.date_saved, sn.generated_at, sn.id) DESC');
        $db->setQuery($q, 0, $limit);
        $rows = $db->loadAssocList();
        return is_array($rows) ? $rows : array();
    } catch (\Throwable $e) { return array(); }
}

function mleAdvisoryInferPickSizeFromRows(array $rows) {
    foreach ($rows as $row) {
        foreach (array('target_pick_size','daily_pick_size','pick_size') as $k) {
            if (isset($row[$k]) && (int)$row[$k] > 0) { return (int)$row[$k]; }
        }
        $nums = mylottoexpertParseNumberCsv($row['main_numbers'] ?? '', true);
        if (!empty($nums)) { return count($nums); }
    }
    return 0;
}

function mleAdvisoryLoadFavoriteWheelsForLottery($db, $userId, $lotteryId, array $activeRows, $limit = 12) {
    $userId = (int)$userId; $limit = max(1, min(50, (int)$limit));
    if ($userId <= 0) { return array(); }
    $pickSize = mleAdvisoryInferPickSizeFromRows($activeRows);
    $data = mylottoexpertLoadHydratedWheelFavorites($db, $userId);
    $items = isset($data['available']) && is_array($data['available']) ? $data['available'] : array();
    if (empty($items)) {
        $catalog = mylottoexpertLoadEffectiveCatalog($db);
        $items = is_array($catalog) ? array_values($catalog) : array();
    }
    $out = array();
    foreach ($items as $item) {
        $itemPick = (int)($item['pick_size'] ?? 0);
        if ($pickSize > 0 && $itemPick > 0 && $itemPick !== $pickSize) { continue; }
        $out[] = $item;
        if (count($out) >= $limit) { break; }
    }
    return $out;
}

function mleAdvisoryFormatSavedSettingName(array $row) {
    foreach (array('setting_name','name','label','template_name') as $k) {
        if (isset($row[$k]) && trim((string)$row[$k]) !== '') { return trim((string)$row[$k]); }
    }
    return 'Saved settings #' . (int)($row['id'] ?? 0);
}

function mleCoreAiIsSavedRow($row) {

    $method = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey') ? mleAdvisoryResolveSavedEvidenceMethodKey($row) : '';
    return $method === 'core_ai';
}

function mleCoreAiDecodeNumbersForOverlap($row) {
    $settings = function_exists('mylottoexpertResolveEffectiveSettings') ? mylottoexpertResolveEffectiveSettings($row) : array();
    foreach (array('main_display_json','regular_main_numbers_json','ranked_main_numbers_json','top20_numbers','top_numbers','main_numbers') as $k) {
        $raw = null;
        if (is_array($row) && array_key_exists($k, $row)) { $raw = $row[$k]; }
        if (($raw === null || $raw === '') && is_array($settings) && array_key_exists($k, $settings)) { $raw = $settings[$k]; }
        if ($raw === null || $raw === '') { continue; }
        $numbers = function_exists('mylottoexpertNormalizeNumberArray') ? mylottoexpertNormalizeNumberArray($raw, false) : array();
        if (!empty($numbers)) { return array_slice(array_values($numbers), 0, 20); }
    }
    return array();
}

function mleCoreAiExtractFocusBlend($row) {
    $settings = function_exists('mylottoexpertResolveEffectiveSettings') ? mylottoexpertResolveEffectiveSettings($row) : array();
    $get = function($keys, $default = '') use ($row, $settings) {
        foreach ((array)$keys as $k) {
            if (is_array($settings) && array_key_exists($k, $settings) && $settings[$k] !== '' && $settings[$k] !== null) { return $settings[$k]; }
            if (is_array($row) && array_key_exists($k, $row) && $row[$k] !== '' && $row[$k] !== null) { return $row[$k]; }
            if (is_object($row) && isset($row->$k) && $row->$k !== '' && $row->$k !== null) { return $row->$k; }
        }
        return $default;
    };

    $focus = trim((string)$get(array('focus_profile','risk_profile','profile','training_style'), 'Balanced Focus'));
    if ($focus === '') { $focus = 'Balanced Focus'; }
    $focusKey = strtolower(trim(str_replace(array('_','-'), ' ', $focus)));
    if ($focusKey === 'balanced') { $focus = 'Balanced Focus'; }
    elseif ($focusKey === 'explorative') { $focus = 'Explorative Focus'; }
    elseif ($focusKey === 'conservative') { $focus = 'Conservative Focus'; }
    else { $focus = mylottoexpertBuildSimpleModeLabel($focus); }

    $blendRaw = $get(array(
        'signal_blend_pct',
        'signal_blend_ai_pct',
        'core_ai_blend_pct',
        'core_ai_ai_pct',
        'ai_pct',
        'blend_ai_pct',
        'blend_percent',
        'blend_pct',
        'ai_blend_pct'
    ), null);
    $skipRaw = $get(array('signal_blend_skip_pct','core_ai_skip_pct','skip_pct','blend_skip_pct'), null);

    if ($blendRaw !== null && $blendRaw !== '') {
        $blendPct = max(0.0, min(100.0, (float)$blendRaw));
    } elseif ($skipRaw !== null && $skipRaw !== '') {
        $blendPct = max(0.0, min(100.0, 100.0 - (float)$skipRaw));
    } else {
        $blendPct = null;
    }

    $label = trim((string)$get(array('signal_blend_label','strategy_profile','strategy','blend'), ''));
    if ($label === '') {
        if ($blendPct !== null) {
            if ($blendPct >= 70) { $label = 'AI-Forward'; }
            elseif ($blendPct <= 30) { $label = 'Skip-Pattern Heavy'; }
            else { $label = 'Balanced Mix'; }
        } else {
            $label = 'Balanced Mix';
        }
    }

    $blendText = $blendPct !== null ? mylottoexpertFormatPercentForLabel($blendPct) . '%' : 'Still forming';
    $display = $blendText;
    if ($label !== '' && $label !== 'Still forming') {
        $display .= ' - ' . $label;
    }

    return array(
        'focus'        => $focus,
        'blend_pct'    => $blendPct,
        'ai_pct'       => $blendPct,
        'skip_pct'     => ($blendPct !== null ? 100.0 - (float)$blendPct : null),
        'label'        => $label,
        'blend_display'=> $display,
    );
}

function mleCoreAiBuildBatchSummaries(array $activeRows, array $perfRows) {
    $perfBySaved = array();
    foreach ($perfRows as $p) {
        $sid = (int)($p['__saved_id'] ?? $p['run_id'] ?? 0);
        if ($sid > 0) { $perfBySaved[$sid][] = $p; }
    }
    $groups = array();
    foreach ($activeRows as $row) {
        if (!mleCoreAiIsSavedRow($row)) { continue; }
        $batchUuid = strtolower(trim((string)($row['batch_uuid'] ?? '')));
        if ($batchUuid === '') {
            $batchUuid = 'single:' . (int)($row['id'] ?? 0);
        }
        if (!isset($groups[$batchUuid])) {
            $groups[$batchUuid] = array(
                'batch_uuid' => $batchUuid,
                'batch_type' => (string)($row['batch_type'] ?? ''),
                'target_draw_date' => (string)($row['target_draw_date'] ?? $row['next_draw_date'] ?? ''),
                'target_game_id' => (string)($row['target_game_id'] ?? $row['mle_lottery_game_id'] ?? ''),
                'batch_total' => max(1, (int)($row['batch_total'] ?? 0)),
                'rows' => array(), 'indexes' => array(), 'saved_count'=>0, 'scored_count'=>0,
                'overlap'=>array(), 'focus_counts'=>array(), 'blend_counts'=>array(), 'best_scored'=>null
            );
        }
        $idx = (int)($row['batch_index'] ?? 0);
        if ($idx > 0) { $groups[$batchUuid]['indexes'][$idx] = 1; }
        $groups[$batchUuid]['rows'][] = $row;
        $groups[$batchUuid]['saved_count']++;
        $sid = (int)($row['id'] ?? 0);
        $fb = mleCoreAiExtractFocusBlend($row);
        $focusKey = trim((string)$fb['focus']);
        $blendKey = trim((string)($fb['blend_display'] ?? $fb['label'] ?? ''));
        if ($focusKey !== '') { $groups[$batchUuid]['focus_counts'][$focusKey] = ($groups[$batchUuid]['focus_counts'][$focusKey] ?? 0) + 1; }
        if ($blendKey !== '') { $groups[$batchUuid]['blend_counts'][$blendKey] = ($groups[$batchUuid]['blend_counts'][$blendKey] ?? 0) + 1; }
        foreach (mleCoreAiDecodeNumbersForOverlap($row) as $n) {
            $n = (int)$n; if ($n <= 0) { continue; }
            $groups[$batchUuid]['overlap'][$n] = ($groups[$batchUuid]['overlap'][$n] ?? 0) + 1;
        }
        if ($sid > 0 && !empty($perfBySaved[$sid])) {
            $groups[$batchUuid]['scored_count'] += count($perfBySaved[$sid]);
            foreach ($perfBySaved[$sid] as $p) {
                $score = (float)($p['weighted_quality_score'] ?? 0) + ((int)($p['top20_hits'] ?? 0) * 0.25) + ((int)($p['top10_hits'] ?? 0) * 0.5) - ((float)($p['avg_winning_rank'] ?? 9999) * 0.01);
                if ($groups[$batchUuid]['best_scored'] === null || $score > (float)$groups[$batchUuid]['best_scored']['_score']) {
                    $best = $fb;
                    $best['saved_id'] = $sid;
                    $best['avg_rank'] = $p['avg_winning_rank'] ?? null;
                    $best['top10_hits'] = (int)($p['top10_hits'] ?? 0);
                    $best['top20_hits'] = (int)($p['top20_hits'] ?? 0);
                    $best['_score'] = $score;
                    $groups[$batchUuid]['best_scored'] = $best;
                }
            }
        }
    }
    $out = array();
    foreach ($groups as $g) {
        $total = (int)$g['batch_total'];
        if ($total <= 1 && $g['saved_count'] >= 2) { $total = 9; }
        $missing = max(0, $total - count($g['indexes']));
        arsort($g['overlap']);
        arsort($g['focus_counts']);
        arsort($g['blend_counts']);
        $topOverlap = array();
        foreach (array_slice($g['overlap'], 0, 10, true) as $num=>$cnt) { $topOverlap[] = array('number'=>(int)$num,'count'=>(int)$cnt); }
        $out[] = array(
            'batch_uuid'=>$g['batch_uuid'],
            'batch_type'=>$g['batch_type'] !== '' ? $g['batch_type'] : 'core_ai_precision_lock_9_batch',
            'target_draw_date'=>$g['target_draw_date'],
            'target_game_id'=>$g['target_game_id'],
            'batch_total'=>$total,
            'saved_count'=>(int)$g['saved_count'],
            'missing_count'=>$missing,
            'scored_count'=>(int)$g['scored_count'],
            'status'=>$missing > 0 ? 'partial' : ((int)$g['scored_count'] > 0 ? 'scored' : 'pending'),
            'top_overlap'=>$topOverlap,
            'top_focus'=>!empty($g['focus_counts']) ? (string)key($g['focus_counts']) : 'Still forming',
            'top_blend'=>!empty($g['blend_counts']) ? (string)key($g['blend_counts']) : 'Still forming',
            'top_blend_label'=>!empty($g['blend_counts']) ? (string)key($g['blend_counts']) : 'Still forming',
            'best_scored'=>$g['best_scored'],
        );
    }
    usort($out, function($a,$b){ return strcmp((string)($b['target_draw_date'] ?? ''), (string)($a['target_draw_date'] ?? '')); });
    return array('has_core_ai'=>!empty($out), 'batches'=>$out, 'batch_count'=>count($out));
}

function mleAdvisoryNormalizeMethodBreakdownKey($method) {
    $method = strtolower(trim((string)$method));
    if ($method === '') { return 'unknown'; }
    if (in_array($method, array('skai','skai_prediction','skai_blend'), true)) { return 'skai'; }
    if (in_array($method, array('core_ai','core-ai','core ai','core_ai_prediction','lottoexpert_core_ai','ai_prediction','ai','neural','neural_ai','neural_ai_prediction','classic_ai','classic_ai_prediction'), true)) { return 'core_ai'; }
    if (in_array($method, array('mcmc','mcmc_prediction'), true)) { return 'mcmc'; }
    if (in_array($method, array('skip','skiphit','skip_hit','skip_hit_prediction'), true)) { return 'skip_hit'; }
    if (in_array($method, array('frequency','frequency_map','heat_map','heatmap','heatmap_manual','manual_heatmap','frequency_heatmap'), true)) { return 'frequency'; }
    return $method;
}

function mleAdvisoryMethodBreakdownRow($method) {
    $method = mleAdvisoryNormalizeMethodBreakdownKey($method);
    $role = function_exists('mleAdvisoryMethodRoleInfo') ? mleAdvisoryMethodRoleInfo($method) : array();
    $label = function_exists('mleAdvisoryMethodLabel') ? mleAdvisoryMethodLabel($method) : ucwords(str_replace('_', ' ', $method));
    return array(
        'method' => $method,
        'label' => (string)$label,
        'role' => (string)($role['role'] ?? 'Comparison Signal'),
        'track' => (string)($role['short_track'] ?? ($role['track'] ?? 'Comparison Track')),
        'saved_count' => 0,
        'pending_count' => 0,
        'past_due_count' => 0,
        'scored_count' => 0,
        'scored_saved_count' => 0,
        'draw_count' => 0,
        'target_draws' => array(),
        'scored_draws' => array(),
        'batch_count' => 0,
        'partial_batch_count' => 0,
        'saved_ids' => array(),
        'saved_rows' => array(),
        'scored_saved_ids' => array(),
        'batch_uuids' => array(),
        'top20_total' => 0,
        'top10_total' => 0,
        'quality_total' => 0.0,
        'avg_rank_sum' => 0.0,
        'unknown_trace_rows' => array(),
        'unknown_phantom_sources' => array(),
    );
}

function mleAdvisoryBuildMethodRunBreakdown(array $activeRows, array $perfRows, array $visualRows = array()) {

    $knownOrder = array('skai','core_ai','mcmc','skip_hit','frequency');
    $rows = array();
    foreach ($knownOrder as $m) { $rows[$m] = mleAdvisoryMethodBreakdownRow($m); }

    $safeDate = function($value) {
        $value = trim((string)$value);
        if ($value === '' || strncmp($value, '0000-00-00', 10) === 0) { return ''; }
        $ts = strtotime($value);
        return $ts ? date('Y-m-d', $ts) : substr($value, 0, 10);
    };
    $addPendingVisual = function(&$bucket, array $vrow) use ($safeDate) {
        $label = trim((string)($vrow['label'] ?? 'Pending run'));
        if ($label === '') { $label = 'Pending run'; }
        $bucket[] = array(
            'saved_id' => (int)($vrow['saved_id'] ?? 0),
            'label' => $label,
            'draw_date' => $safeDate($vrow['draw_date'] ?? ''),
            'method_label' => (string)($vrow['method_label'] ?? ''),
            'numbers_count' => count((array)($vrow['predicted'] ?? array())) + count((array)($vrow['predicted_extra'] ?? array())),
            'is_daily' => !empty($vrow['is_daily']) ? 1 : 0,
        );
    };

    $activeRowBySavedId = array();
    foreach ($activeRows as $row) {
        if (!is_array($row)) { continue; }
        $method = mleAdvisoryNormalizeMethodBreakdownKey($row['__method_key'] ?? ($row['source'] ?? 'unknown'));
        if ($method === 'strategy_set') { continue; }
        if (!isset($rows[$method])) { $rows[$method] = mleAdvisoryMethodBreakdownRow($method); }
        if ($method === 'unknown' && function_exists('mleV69IsPhantomUnknownSource') && mleV69IsPhantomUnknownSource($row, array())) {
            $pkey = 'active_' . count($rows[$method]['unknown_phantom_sources']);
            $rows[$method]['unknown_phantom_sources'][$pkey] = mleV69BuildUnknownSourceProvenance($row, array(), 'activeRows');
            continue;
        }
        $id = (int)($row['id'] ?? 0);
        if ($id > 0) { $activeRowBySavedId[$id] = $row; }
        if ($id > 0) { $rows[$method]['saved_ids'][$id] = true; }
        $targetDate = $safeDate($row['target_draw_date'] ?? ($row['next_draw_date'] ?? ''));
        $savedLabel = trim((string)($row['label'] ?? 'Saved run'));
        if ($savedLabel === '') { $savedLabel = 'Saved run'; }
        if ($id > 0 && !isset($rows[$method]['saved_rows'][$id])) {
            $rows[$method]['saved_rows'][$id] = array(
                'saved_id' => $id,
                'label' => $savedLabel,
                'draw_date' => $targetDate,
                'source' => (string)($row['source'] ?? ''),
                'batch_uuid' => (string)($row['batch_uuid'] ?? ''),
                'batch_index' => (int)($row['batch_index'] ?? 0),
                'batch_total' => (int)($row['batch_total'] ?? 0),
                'status' => (string)($row['play_status'] ?? $row['status'] ?? ''),
            );
        }
        if ($method === 'unknown' && function_exists('mleV65BuildUnknownRunTraceRow')) {
            $traceId = $id > 0 ? $id : count($rows[$method]['unknown_trace_rows']) + 1;
            $rows[$method]['unknown_trace_rows'][$traceId] = mleV65BuildUnknownRunTraceRow($row);
        }
        $rows[$method]['saved_count'] = count($rows[$method]['saved_ids']);

        if ($targetDate !== '') { $rows[$method]['target_draws'][$targetDate] = true; }
        $batchUuid = strtolower(trim((string)($row['batch_uuid'] ?? '')));
        if ($batchUuid !== '') { $rows[$method]['batch_uuids'][$batchUuid] = true; }
    }

    foreach ($perfRows as $perf) {
        if (!is_array($perf)) { continue; }
        $method = mleAdvisoryNormalizeMethodBreakdownKey($perf['__method_key'] ?? ($perf['source'] ?? 'unknown'));
        if ($method === 'strategy_set') { continue; }
        if (!isset($rows[$method])) { $rows[$method] = mleAdvisoryMethodBreakdownRow($method); }
        $sid = (int)($perf['__saved_id'] ?? $perf['run_id'] ?? 0);
        if ($sid > 0) { $rows[$method]['scored_saved_ids'][$sid] = true; }
        $rows[$method]['scored_count']++;
        $drawDate = function_exists('mleAdvisoryCompletedDrawCycleDate') ? mleAdvisoryCompletedDrawCycleDate((array)$perf, ($sid > 0 && isset($activeRowBySavedId[$sid]) && is_array($activeRowBySavedId[$sid])) ? $activeRowBySavedId[$sid] : array()) : $safeDate($perf['draw_date'] ?? '');
        if ($drawDate !== '') { $rows[$method]['scored_draws'][$drawDate] = true; }
        $rows[$method]['top20_total'] += (int)($perf['top20_hits'] ?? 0);
        $rows[$method]['top10_total'] += (int)($perf['top10_hits'] ?? 0);
        $rows[$method]['quality_total'] += (float)($perf['weighted_quality_score'] ?? 0.0);
        if (isset($perf['avg_winning_rank']) && $perf['avg_winning_rank'] !== null && $perf['avg_winning_rank'] !== '') {
            $rows[$method]['avg_rank_sum'] += (float)$perf['avg_winning_rank'];
        }
    }

    $visualFlatRows = array();
    foreach ($visualRows as $__visualBucketKey => $__visualBucketRows) {
        if (!is_array($__visualBucketRows)) { continue; }

        if (array_key_exists('saved_id', $__visualBucketRows)
            || array_key_exists('predicted', $__visualBucketRows)
            || array_key_exists('method', $__visualBucketRows)
            || array_key_exists('completed', $__visualBucketRows)) {
            $visualFlatRows[] = $__visualBucketRows;
            continue;
        }
        foreach ($__visualBucketRows as $__visualCandidateRow) {
            if (is_array($__visualCandidateRow)) { $visualFlatRows[] = $__visualCandidateRow; }
        }
    }

    $pendingSeen = array();
    foreach ($visualFlatRows as $vrow) {
        if (!is_array($vrow)) { continue; }
        if (!empty($vrow['completed'])) { continue; }
        $method = mleAdvisoryNormalizeMethodBreakdownKey($vrow['method'] ?? 'unknown');
        if ($method === 'strategy_set') { continue; }
        if (!isset($rows[$method])) { $rows[$method] = mleAdvisoryMethodBreakdownRow($method); }
        $sid = (int)($vrow['saved_id'] ?? 0);
        $drawDate = $safeDate($vrow['draw_date'] ?? '');
        $key = $method . '|' . $sid . '|' . $drawDate;
        if (isset($pendingSeen[$key])) { continue; }
        if ($method === 'unknown' && function_exists('mleV69IsPhantomUnknownSource')) {
            $traceSourceRow = ($sid > 0 && isset($activeRowBySavedId[$sid])) ? $activeRowBySavedId[$sid] : $vrow;
            if (mleV69IsPhantomUnknownSource($traceSourceRow, $vrow)) {
                $pkey = $key !== 'unknown||' ? $key : ('visual_' . count($rows[$method]['unknown_phantom_sources']));
                $rows[$method]['unknown_phantom_sources'][$pkey] = mleV69BuildUnknownSourceProvenance($traceSourceRow, $vrow, 'visualRows');
                $pendingSeen[$key] = true;
                continue;
            }
        }
        $pendingSeen[$key] = true;
        $__mlePastDue = ($drawDate !== '' && strtotime($drawDate) < strtotime(date('Y-m-d')));
        if ($__mlePastDue) {
            if (!isset($rows[$method]['past_due_count'])) { $rows[$method]['past_due_count'] = 0; }
            $rows[$method]['past_due_count']++;
        } else {
            $rows[$method]['pending_count']++;
        }
        if ($drawDate !== '') { $rows[$method]['target_draws'][$drawDate] = true; }
        if (!isset($rows[$method]['pending_rows']) || !is_array($rows[$method]['pending_rows'])) { $rows[$method]['pending_rows'] = array(); }
        $addPendingVisual($rows[$method]['pending_rows'], $vrow);
        if ($method === 'unknown' && function_exists('mleV65BuildUnknownRunTraceRow')) {
            $traceSourceRow = ($sid > 0 && isset($activeRowBySavedId[$sid])) ? $activeRowBySavedId[$sid] : $vrow;
            $traceId = $sid > 0 ? $sid : ('visual_' . count($rows[$method]['unknown_trace_rows']));
            $rows[$method]['unknown_trace_rows'][$traceId] = mleV65BuildUnknownRunTraceRow($traceSourceRow, $vrow);
        }
    }

    foreach ($rows as $method => $row) {
        $savedIds = array_keys($row['saved_ids']);
        $scoredSavedIds = array_keys($row['scored_saved_ids']);
        $rows[$method]['saved_count'] = count($savedIds);
        $rows[$method]['scored_saved_count'] = count($scoredSavedIds);
        $rows[$method]['draw_count'] = count($row['scored_draws']);
        $rows[$method]['batch_count'] = count($row['batch_uuids']);
        $rows[$method]['saved_rows_list'] = array_values((array)$row['saved_rows']);
        usort($rows[$method]['saved_rows_list'], function($a, $b) {
            $ad = strtotime((string)($a['draw_date'] ?? '')) ?: 0;
            $bd = strtotime((string)($b['draw_date'] ?? '')) ?: 0;
            if ($ad !== $bd) { return $bd <=> $ad; }
            return ((int)($b['saved_id'] ?? 0)) <=> ((int)($a['saved_id'] ?? 0));
        });
        $rows[$method]['target_draw_list'] = array_keys($row['target_draws']);
        rsort($rows[$method]['target_draw_list']);
        $rows[$method]['scored_draw_list'] = array_keys($row['scored_draws']);
        rsort($rows[$method]['scored_draw_list']);
        $rawUnknownTraceRows = array_values((array)($rows[$method]['unknown_trace_rows'] ?? array()));
        if ($method === 'unknown' && function_exists('mleV69TraceHasMeaningfulIdentity')) {
            $keptUnknownTraceRows = array();
            foreach ($rawUnknownTraceRows as $traceCandidate) {
                if (is_array($traceCandidate) && mleV69TraceHasMeaningfulIdentity($traceCandidate)) { $keptUnknownTraceRows[] = $traceCandidate; }
                else {
                    $pkey = 'trace_' . count($rows[$method]['unknown_phantom_sources']);
                    $rows[$method]['unknown_phantom_sources'][$pkey] = array(
                        'origin' => 'unknown_trace_rows',
                        'admin_message' => 'An Unknown trace candidate was suppressed because it did not include a real saved row identity or usable source data.',
                        'has_meaningful_identity' => 0,
                    );
                }
            }
            $rows[$method]['unknown_trace_rows_list'] = $keptUnknownTraceRows;
        } else {
            $rows[$method]['unknown_trace_rows_list'] = $rawUnknownTraceRows;
        }
        $rows[$method]['unknown_phantom_sources_list'] = array_values((array)($rows[$method]['unknown_phantom_sources'] ?? array()));
        $rows[$method]['avg_top20'] = $row['scored_count'] > 0 ? round($row['top20_total'] / max(1, $row['scored_count']), 2) : null;
        $rows[$method]['avg_top10'] = $row['scored_count'] > 0 ? round($row['top10_total'] / max(1, $row['scored_count']), 2) : null;
        $rows[$method]['avg_quality'] = $row['scored_count'] > 0 ? round($row['quality_total'] / max(1, $row['scored_count']), 6) : null;
        $rows[$method]['avg_rank'] = $row['scored_count'] > 0 ? round($row['avg_rank_sum'] / max(1, $row['scored_count']), 2) : null;
        if ($rows[$method]['pending_count'] > 0 && $rows[$method]['scored_count'] > 0) { $status = 'mixed'; }
        elseif ($rows[$method]['pending_count'] > 0) { $status = 'pending'; }
        elseif ($rows[$method]['scored_count'] > 0) { $status = 'scored'; }
        elseif ($rows[$method]['saved_count'] > 0) { $status = 'saved'; }
        else { $status = 'empty'; }
        $rows[$method]['status'] = $status;
    }

    $hasAnyMethodData = false;
    foreach ($rows as $row) {
        if ((int)($row['saved_count'] ?? 0) > 0 || (int)($row['scored_count'] ?? 0) > 0 || (int)($row['pending_count'] ?? 0) > 0) {
            $hasAnyMethodData = true;
            break;
        }
    }
    $items = $hasAnyMethodData ? array_values($rows) : array();
    usort($items, function($a, $b) use ($knownOrder) {
        $pa = array_search($a['method'], $knownOrder, true); if ($pa === false) { $pa = 99; }
        $pb = array_search($b['method'], $knownOrder, true); if ($pb === false) { $pb = 99; }
        if ($pa !== $pb) { return $pa <=> $pb; }
        return strcmp((string)$a['label'], (string)$b['label']);
    });
    return array(
        'has_methods' => !empty($items),
        'items' => $items,
        'pending_total' => array_sum(array_map(function($row){ return (int)($row['pending_count'] ?? 0); }, $items)),
        'past_due_total' => array_sum(array_map(function($row){ return (int)($row['past_due_count'] ?? 0); }, $items)),
        'scored_total' => array_sum(array_map(function($row){ return (int)($row['scored_count'] ?? 0); }, $items)),
        'saved_total' => array_sum(array_map(function($row){ return (int)($row['saved_count'] ?? 0); }, $items)),
        'unknown_phantom_sources' => array_values((array)($rows['unknown']['unknown_phantom_sources'] ?? array())),
        'unknown_phantom_count' => count((array)($rows['unknown']['unknown_phantom_sources'] ?? array())),
    );
}

if (!function_exists('mleCllV1SafeJsonEncode')) {
    function mleCllV1SafeJsonEncode($value) {
        $json = json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        return ($json === false) ? '{}' : $json;
    }
}
if (!function_exists('mleCllV1SafeJsonDecode')) {
    function mleCllV1SafeJsonDecode($value) {
        $decoded = json_decode((string)$value, true);
        return (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) ? $decoded : array();
    }
}
if (!function_exists('mleCllV1TableExists')) {
    function mleCllV1TableExists($db, $rawTable) {
        try {
            $rawTable = str_replace('#__', $db->getPrefix(), (string)$rawTable);
            return in_array($rawTable, (array)$db->getTableList(), true);
        } catch (\Throwable $e) { return false; }
    }
}
if (!function_exists('mleCllV1ColumnMap')) {
    function mleCllV1ColumnMap($db, $table) {
        $out = array();
        try {
            foreach ((array)$db->getTableColumns($table, false) as $k => $v) {
                if (is_string($k) && $k !== '') { $out[$k] = true; }
                elseif (is_object($v) && isset($v->Field)) { $out[(string)$v->Field] = true; }
            }
        } catch (\Throwable $e) { }
        return $out;
    }
}

if (!function_exists('mleCllV6BackfillGuidanceColumns')) {
    function mleCllV6BackfillGuidanceColumns($db) {

        if (!mleCllV1TableExists($db, '#__skai_best_settings')) { return false; }
        try {
            $cols = mleCllV1ColumnMap($db, '#__skai_best_settings');
            foreach (array('source_mode','status','is_active','evidence_runs','evidence_draws','avg_recall_at_20','guidance_mode','guidance_reason','guidance_score') as $requiredCol) {
                if (empty($cols[$requiredCol])) { return false; }
            }
            $q = $db->getQuery(true)
                ->update($db->quoteName('#__skai_best_settings'))
                ->set($db->quoteName('guidance_mode') . " = CASE"
                    . " WHEN " . $db->quoteName('is_active') . " = 1 OR " . $db->quoteName('status') . " = " . $db->quote('active') . " THEN " . $db->quote('closed_loop_active')
                    . " WHEN " . $db->quoteName('evidence_runs') . " >= 100 AND " . $db->quoteName('evidence_draws') . " >= 12 AND " . $db->quoteName('avg_recall_at_20') . " >= 0.350000 THEN " . $db->quote('closed_loop_learning_guided')
                    . " ELSE " . $db->quote('closed_loop_collecting') . " END")
                ->set($db->quoteName('guidance_reason') . " = CASE"
                    . " WHEN " . $db->quoteName('is_active') . " = 1 OR " . $db->quoteName('status') . " = " . $db->quote('active') . " THEN " . $db->quote('active_threshold_met')
                    . " WHEN " . $db->quoteName('evidence_runs') . " >= 100 AND " . $db->quoteName('evidence_draws') . " >= 12 AND " . $db->quoteName('avg_recall_at_20') . " >= 0.350000 THEN " . $db->quote('guided_threshold_met_runs_draws_recall')
                    . " ELSE " . $db->quote('collecting_more_draws') . " END")
                ->set($db->quoteName('guidance_score') . " = CASE WHEN " . $db->quoteName('score') . " > 0 THEN " . $db->quoteName('score') . " ELSE " . $db->quoteName('best_score') . " END")
                ->set($db->quoteName('status') . " = CASE"
                    . " WHEN " . $db->quoteName('is_active') . " = 1 OR " . $db->quoteName('status') . " = " . $db->quote('active') . " THEN " . $db->quote('active')
                    . " WHEN " . $db->quoteName('status') . " = " . $db->quote('learning') . " AND " . $db->quoteName('evidence_runs') . " >= 100 AND " . $db->quoteName('evidence_draws') . " >= 12 AND " . $db->quoteName('avg_recall_at_20') . " >= 0.350000 THEN " . $db->quote('learning_guided')
                    . " ELSE " . $db->quoteName('status') . " END")
                ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'))
                ->where('('
                    . $db->quoteName('guidance_mode') . " = '' OR "
                    . $db->quoteName('guidance_reason') . " = '' OR "
                    . $db->quoteName('guidance_score') . " = 0 OR ("
                    . $db->quoteName('status') . " = " . $db->quote('learning')
                    . " AND " . $db->quoteName('evidence_runs') . " >= 100"
                    . " AND " . $db->quoteName('evidence_draws') . " >= 12"
                    . " AND " . $db->quoteName('avg_recall_at_20') . " >= 0.350000))");
            $db->setQuery($q);
            $db->execute();
            return true;
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V6] guidance backfill failed: ' . $e->getMessage());
            return false;
        }
    }
}

