        try {
            $db->setQuery("CREATE TABLE IF NOT EXISTS `{$prefix}skai_closed_loop_learning_events` (
                `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
                `lottery_id` INT NOT NULL DEFAULT 0,
                `game_id` VARCHAR(50) NOT NULL DEFAULT '',
                `draw_date` DATE NOT NULL,
                `saved_number_id` INT NOT NULL DEFAULT 0,
                `user_id` INT NOT NULL DEFAULT 0,
                `run_uuid` VARCHAR(80) NOT NULL DEFAULT '',
                `batch_uuid` VARCHAR(80) NOT NULL DEFAULT '',
                `settings_fingerprint` CHAR(64) NOT NULL DEFAULT '',
                `predicted_main_json` LONGTEXT NOT NULL,
                `predicted_extra_json` LONGTEXT NULL,
                `actual_main_json` LONGTEXT NOT NULL,
                `actual_extra_json` LONGTEXT NULL,
                `missed_main_json` LONGTEXT NULL,
                `winner_rank_json` LONGTEXT NULL,
                `outlier_miss_json` LONGTEXT NULL,
                `settings_json` LONGTEXT NULL,
                `signal_help_hurt_json` LONGTEXT NULL,
                `main_hits` INT NOT NULL DEFAULT 0,
                `extra_hits` INT NOT NULL DEFAULT 0,
                `top10_hits` INT NOT NULL DEFAULT 0,
                `top20_hits` INT NOT NULL DEFAULT 0,
                `quality_score` DECIMAL(12,6) NOT NULL DEFAULT 0.000000,
                `learning_status` VARCHAR(32) NOT NULL DEFAULT 'captured',
                `created_at` DATETIME NOT NULL,
                `updated_at` DATETIME NOT NULL,
                PRIMARY KEY (`id`),
                UNIQUE KEY `uq_mle_cll_saved_draw` (`saved_number_id`,`draw_date`),
                KEY `idx_mle_cll_game_draw` (`game_id`,`draw_date`),
                KEY `idx_mle_cll_lottery_draw` (`lottery_id`,`draw_date`),
                KEY `idx_mle_cll_fingerprint` (`settings_fingerprint`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
            $db->execute();
            if (mleCllV1TableExists($db, '#__skai_best_settings')) {
                mleCllV1EnsureBestSettingsSchema($db);
            }
            $done = true;
            return true;
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V1] table ensure failed: ' . $e->getMessage());
            return false;
        }
    }
}
if (!function_exists('mleCllV1CanonicalSettings')) {
    function mleCllV1CanonicalSettings(array $settings) {
        $allow = array('skai_window_size','window_size','draws_used','skip_window','skai_blend_ai_pct','blend_ai_pct','ai_pct','skai_blend_skip_pct','freq_weight','skip_weight','hist_weight','pb_freq_weight','pb_skip_weight','pb_hist_weight','profile','risk_profile','training_style','strategy','strategy_profile','sampling_temperature','diversity_penalty','gap_scale','laplace_k','epochs','batch_size','skai_top_n_numbers','skai_top_n_combos','walks','burn_in','chain_len','auto_tune','tune_used');
        $out = array();
        foreach ($allow as $k) {
            if (array_key_exists($k, $settings) && !is_array($settings[$k]) && !is_object($settings[$k]) && trim((string)$settings[$k]) !== '') {
                $out[$k] = trim((string)$settings[$k]);
            }
        }
        ksort($out);
        return $out;
    }
}
if (!function_exists('mleCllV1SettingsFingerprint')) {
    function mleCllV1SettingsFingerprint(array $settings) {
        return hash('sha256', mleCllV1SafeJsonEncode(mleCllV1CanonicalSettings($settings)));
    }
}
if (!function_exists('mleCllV1ExtractSettingsFromSavedRow')) {
    function mleCllV1ExtractSettingsFromSavedRow(array $savedRow, array $fallbackSettings = array()) {
        foreach (array('settings_json','settings','params_json','params','run_settings','source_tracking','mle_tracking','tracking','payload_json') as $key) {
            if (!empty($savedRow[$key])) {
                $decoded = mleCllV1SafeJsonDecode($savedRow[$key]);
                foreach (array('settings','run_settings','params','skai','mle_skai_settings','base_settings','control_settings') as $nested) {
                    if (!empty($decoded[$nested]) && is_array($decoded[$nested])) { return $decoded[$nested]; }
                }
                if (!empty($decoded)) { return $decoded; }
            }
        }
        return $fallbackSettings;
    }
}
if (!function_exists('mleCllV1BuildOutcomeProfile')) {
    function mleCllV1BuildOutcomeProfile(array $predMain, array $actualMain, array $predExtra, array $actualExtra, array $metrics) {
        $rankMap = array();
        foreach (array_values($predMain) as $idx => $num) { $rankMap[(int)$num] = $idx + 1; }
        $missed = array();
        $winnerRanks = array();
        $outliers = array();
        foreach (array_values($actualMain) as $num) {
            $n = (int)$num;
            $rank = isset($rankMap[$n]) ? (int)$rankMap[$n] : 0;
            $winnerRanks[] = array('number' => $n, 'rank' => $rank, 'status' => $rank > 0 ? 'ranked' : 'missing');
            if ($rank <= 0) { $missed[] = $n; $outliers[] = array('number'=>$n,'reason'=>'not_in_prediction_ranking','rank'=>0); }
            elseif ($rank > 20) { $outliers[] = array('number'=>$n,'reason'=>'winner_ranked_outside_top20','rank'=>$rank); }
        }
        $extraMissed = array_values(array_diff(array_map('intval', $actualExtra), array_map('intval', $predExtra)));
        return array(
            'missed_main' => $missed,
            'missed_extra' => $extraMissed,
            'winner_ranks' => $winnerRanks,
            'outlier_misses' => $outliers,
            'top10_hits' => (int)($metrics['top10_hits'] ?? 0),
            'top20_hits' => (int)($metrics['top20_hits'] ?? 0),
            'missing_hits_count' => (int)($metrics['missing_count'] ?? count($missed)),
        );
    }
}
if (!function_exists('mleCllV1CaptureScoredRun')) {
    function mleCllV1CaptureScoredRun($db, $userId, $lotteryId, $gameId, $drawDate, $savedId, array $savedRow, array $vrow, array $settings, array $metrics, array $lineageMeta, $promoteAfterCapture = true) {
        if (!mleCllV1EnsureTables($db)) { return false; }
        $userId = (int)$userId; $lotteryId = (int)$lotteryId; $savedId = (int)$savedId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        if (function_exists('mleCllV12CanonicalGameIdFromSavedRow')) {
            $gameId = mleCllV12CanonicalGameIdFromSavedRow($db, $savedRow, $lotteryId, $gameId);
        }
        if ($gameId === '') { $gameId = 'lottery_' . $lotteryId; }
        $predMain = array_values(array_map('intval', (array)($vrow['predicted'] ?? array())));
        $predExtra = array_values(array_map('intval', (array)($vrow['predicted_extra'] ?? array())));
        $actualMain = array_values(array_map('intval', (array)($vrow['actual'] ?? array())));
        $actualExtra = array_values(array_map('intval', (array)($vrow['actual_extra'] ?? array())));
        if ($savedId <= 0 || empty($predMain) || empty($actualMain)) { return false; }
        $effectiveSettings = mleCllV1CanonicalSettings(mleCllV1ExtractSettingsFromSavedRow($savedRow, $settings));
        $fingerprint = mleCllV1SettingsFingerprint($effectiveSettings);
        $profile = mleCllV1BuildOutcomeProfile($predMain, $actualMain, $predExtra, $actualExtra, $metrics);
        $mainHits = (int)($vrow['main_hits'] ?? count(array_intersect($predMain, $actualMain)));
        $extraHits = (int)($vrow['extra_hits'] ?? count(array_intersect($predExtra, $actualExtra)));
        $quality = (float)($metrics['weighted_score'] ?? 0.0);
        if ($quality <= 0.0) { $quality = ($mainHits * 10.0) + ((int)$profile['top20_hits'] * 1.5) + ((int)$profile['top10_hits'] * 2.5) - count($profile['outlier_misses']); }
        $now = date('Y-m-d H:i:s');
        try {
            $cols = array('lottery_id','game_id','draw_date','saved_number_id','user_id','run_uuid','batch_uuid','settings_fingerprint','predicted_main_json','predicted_extra_json','actual_main_json','actual_extra_json','missed_main_json','winner_rank_json','outlier_miss_json','settings_json','signal_help_hurt_json','main_hits','extra_hits','top10_hits','top20_hits','quality_score','learning_status','created_at','updated_at');
            $vals = array(
                (int)$lotteryId,
                $db->quote($gameId),
                $db->quote(substr((string)$drawDate,0,10)),
                (int)$savedId,
                (int)$userId,
                $db->quote(substr((string)($lineageMeta['run_uuid'] ?? ''),0,80)),
                $db->quote(substr((string)($lineageMeta['batch_uuid'] ?? $savedRow['batch_uuid'] ?? ''),0,80)),
                $db->quote($fingerprint),
                $db->quote(mleCllV1SafeJsonEncode($predMain)),
                $db->quote(mleCllV1SafeJsonEncode($predExtra)),
                $db->quote(mleCllV1SafeJsonEncode($actualMain)),
                $db->quote(mleCllV1SafeJsonEncode($actualExtra)),
                $db->quote(mleCllV1SafeJsonEncode($profile['missed_main'])),
                $db->quote(mleCllV1SafeJsonEncode($profile['winner_ranks'])),
                $db->quote(mleCllV1SafeJsonEncode($profile['outlier_misses'])),
                $db->quote(mleCllV1SafeJsonEncode($effectiveSettings)),
                $db->quote(mleCllV1SafeJsonEncode(array('captured_from'=>'mylottoexpert_scoring','missing_extra'=>$profile['missed_extra']))),
                (int)$mainHits,
                (int)$extraHits,
                (int)$profile['top10_hits'],
                (int)$profile['top20_hits'],
                (float)$quality,
                $db->quote('captured'),
                $db->quote($now),
                $db->quote($now)
            );
            $q = $db->getQuery(true)->insert($db->quoteName('#__skai_closed_loop_learning_events'))->columns($db->quoteName($cols))->values(implode(',', $vals));
            $db->setQuery($q);
            try { $db->execute(); }
            catch (\Throwable $dup) {
                $uq = $db->getQuery(true)->update($db->quoteName('#__skai_closed_loop_learning_events'))
                    ->set($db->quoteName('run_uuid') . ' = ' . $db->quote(substr((string)($lineageMeta['run_uuid'] ?? ''),0,80)))
                    ->set($db->quoteName('batch_uuid') . ' = ' . $db->quote(substr((string)($lineageMeta['batch_uuid'] ?? $savedRow['batch_uuid'] ?? ''),0,80)))
                    ->set($db->quoteName('settings_fingerprint') . ' = ' . $db->quote($fingerprint))
                    ->set($db->quoteName('missed_main_json') . ' = ' . $db->quote(mleCllV1SafeJsonEncode($profile['missed_main'])))
                    ->set($db->quoteName('winner_rank_json') . ' = ' . $db->quote(mleCllV1SafeJsonEncode($profile['winner_ranks'])))
                    ->set($db->quoteName('outlier_miss_json') . ' = ' . $db->quote(mleCllV1SafeJsonEncode($profile['outlier_misses'])))
                    ->set($db->quoteName('settings_json') . ' = ' . $db->quote(mleCllV1SafeJsonEncode($effectiveSettings)))
                    ->set($db->quoteName('main_hits') . ' = ' . (int)$mainHits)
                    ->set($db->quoteName('extra_hits') . ' = ' . (int)$extraHits)
                    ->set($db->quoteName('top10_hits') . ' = ' . (int)$profile['top10_hits'])
                    ->set($db->quoteName('top20_hits') . ' = ' . (int)$profile['top20_hits'])
                    ->set($db->quoteName('quality_score') . ' = ' . (float)$quality)
                    ->set($db->quoteName('updated_at') . ' = ' . $db->quote($now))
                    ->where($db->quoteName('saved_number_id') . ' = ' . (int)$savedId)
                    ->where($db->quoteName('draw_date') . ' = ' . $db->quote(substr((string)$drawDate,0,10)));
                $db->setQuery($uq); $db->execute();
            }
            if ($promoteAfterCapture) { mleCllV1MaybePromoteSettings($db, $lotteryId, $gameId); }
            return true;
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V1] capture failed saved_id=' . (int)$savedId . ' msg=' . $e->getMessage());
            return false;
        }
    }
}

if (!function_exists('mleCllV11FlattenNumericValues')) {
    function mleCllV11FlattenNumericValues($value, &$out) {
        if (is_array($value)) {
            foreach ($value as $v) { mleCllV11FlattenNumericValues($v, $out); }
            return;
        }
        if (is_object($value)) {
            mleCllV11FlattenNumericValues((array)$value, $out);
            return;
        }
        $s = trim((string)$value);
        if ($s === '') { return; }
        if (preg_match_all('/\d+/', $s, $m)) {
            foreach ($m[0] as $n) {
                $i = (int)$n;
                if ($i > 0) { $out[] = $i; }
            }
        }
    }
}
if (!function_exists('mleCllV11ParseNumbers')) {
    function mleCllV11ParseNumbers($value, $max = 0) {
        $out = array();
        if (is_array($value) || is_object($value)) {
            mleCllV11FlattenNumericValues($value, $out);
        } else {
            $raw = trim((string)$value);
            if ($raw !== '') {
                $decoded = json_decode($raw, true);
                if (json_last_error() === JSON_ERROR_NONE && (is_array($decoded) || is_object($decoded))) {
                    mleCllV11FlattenNumericValues($decoded, $out);
                } else {
                    mleCllV11FlattenNumericValues($raw, $out);
                }
            }
        }
        $clean = array();
        foreach ($out as $n) {
            $i = (int)$n;
            if ($i <= 0) { continue; }

            if (!in_array($i, $clean, true)) { $clean[] = $i; }
        }
        if ($max > 0 && count($clean) > $max) { $clean = array_slice($clean, 0, $max); }
        return array_values($clean);
    }
}
if (!function_exists('mleCllV11FirstNumberListFromRow')) {
    function mleCllV11FirstNumberListFromRow(array $row, array $keys, $max = 0) {
        foreach ($keys as $key) {
            if (array_key_exists($key, $row) && trim((string)$row[$key]) !== '') {
                $nums = mleCllV11ParseNumbers($row[$key], $max);
                if (!empty($nums)) { return $nums; }
            }
        }
        return array();
    }
}

if (!function_exists('mleCllV12CleanGameId')) {
    function mleCllV12CleanGameId($value) {
        return preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr(trim((string)$value), 0, 50));
    }
}
