    function mleCllV12IsLotteryFallbackGameId($lotteryId, $gameId) {
        $lotteryId = (int)$lotteryId;
        $gameId = mleCllV12CleanGameId($gameId);
        return ($lotteryId > 0 && $gameId === ('lottery_' . $lotteryId));
    }
}
