    function mleCllV12InferCanonicalGameIdForLottery($db, $lotteryId) {
        static $cache = array();
        $lotteryId = (int)$lotteryId;
        if ($lotteryId <= 0) { return ''; }
        if (array_key_exists($lotteryId, $cache)) { return $cache[$lotteryId]; }
        $fallback = 'lottery_' . $lotteryId;
