                        ->select($expr . ' AS gid, COUNT(*) AS c')
                        ->from($db->quoteName('#__user_saved_numbers'))
                        ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                        ->where($expr . ' IS NOT NULL')
                        ->where($expr . ' <> ' . $db->quote($fallback));
                    if (!empty($cols['evaluation_status'])) { $q->where($db->quoteName('evaluation_status') . ' = ' . $db->quote('scored')); }
                    $q->group($expr)->order('c DESC')->setLimit(1);
                    $db->setQuery($q);
                    $row = $db->loadAssoc();
                    if (is_array($row) && !empty($row['gid'])) { $best = mleCllV12CleanGameId($row['gid']); }
                }
            }
        } catch (\Throwable $e) { }
        if ($best === '') {
            try {
                if (mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
