                        ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                        ->where($db->quoteName('game_id') . ' <> ' . $db->quote(''))
                        ->where($db->quoteName('game_id') . ' <> ' . $db->quote($fallback))
                        ->group($db->quoteName('game_id'))->order('c DESC')->setLimit(1);
                    $db->setQuery($q);
                    $row = $db->loadAssoc();
                    if (is_array($row) && !empty($row['gid'])) { $best = mleCllV12CleanGameId($row['gid']); }
                }
            } catch (\Throwable $e) { }
        }
        $cache[$lotteryId] = $best;
        return $best;
    }
}
if (!function_exists('mleCllV12CanonicalGameIdFromSavedRow')) {
    function mleCllV12CanonicalGameIdFromSavedRow($db, array $row, $lotteryId = 0, $fallbackGameId = '') {
        $lotteryId = (int)$lotteryId;
        if ($lotteryId <= 0) {
            foreach (array('target_lottery_id','lottery_id') as $lk) {
                if (!empty($row[$lk]) && (int)$row[$lk] > 0) { $lotteryId = (int)$row[$lk]; break; }
            }
        }
        foreach (array('target_game_id','game_id') as $gk) {
            if (!empty($row[$gk])) {
                $gid = mleCllV12CleanGameId($row[$gk]);
                if ($gid !== '' && !mleCllV12IsLotteryFallbackGameId($lotteryId, $gid)) { return $gid; }
            }
        }
        $fallbackGameId = mleCllV12CleanGameId($fallbackGameId);
        if ($fallbackGameId !== '' && !mleCllV12IsLotteryFallbackGameId($lotteryId, $fallbackGameId)) { return $fallbackGameId; }
        $inferred = mleCllV12InferCanonicalGameIdForLottery($db, $lotteryId);
        if ($inferred !== '') { return $inferred; }
        return $lotteryId > 0 ? ('lottery_' . $lotteryId) : '';
    }
}
if (!function_exists('mleCllV12NormalizeClosedLoopGameIdentities')) {
    function mleCllV12NormalizeClosedLoopGameIdentities($db, $lotteryId = 0) {
        static $ran = array();
        $scope = (int)$lotteryId;
        if (isset($ran[$scope])) { return array('normalized'=>0, 'reason'=>'already_ran'); }
        $ran[$scope] = true;
        if (!mleCllV1EnsureTables($db)) { return array('normalized'=>0, 'reason'=>'no_tables'); }
        if (!mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) { return array('normalized'=>0, 'reason'=>'no_events'); }
        $normalized = 0;
        try {
            $q = $db->getQuery(true)
                ->select('DISTINCT ' . $db->quoteName('lottery_id'))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' > 0');
            if ($scope > 0) { $q->where($db->quoteName('lottery_id') . ' = ' . (int)$scope); }
            $db->setQuery($q);
            $lotteries = array_map('intval', (array)$db->loadColumn());
            foreach ($lotteries as $lid) {
                if ($lid <= 0) { continue; }
                $canonical = mleCllV12InferCanonicalGameIdForLottery($db, $lid);
                if ($canonical === '') { continue; }
                $fallback = 'lottery_' . $lid;
                $u = $db->getQuery(true)
                    ->update($db->quoteName('#__skai_closed_loop_learning_events'))
                    ->set($db->quoteName('game_id') . ' = ' . $db->quote($canonical))
                    ->set($db->quoteName('updated_at') . ' = ' . $db->quote(date('Y-m-d H:i:s')))
                    ->where($db->quoteName('lottery_id') . ' = ' . (int)$lid)
                    ->where('(' . $db->quoteName('game_id') . ' = ' . $db->quote($fallback) . ' OR ' . $db->quoteName('game_id') . ' = ' . $db->quote('') . ')');
                $db->setQuery($u);
                $db->execute();
                $normalized += (int)$db->getAffectedRows();
            }
            if ($normalized > 0) { error_log('[MLE_CLOSED_LOOP_LEARNING_V15] normalized fallback game IDs rows=' . $normalized . ' scope=' . $scope); }
            return array('normalized'=>$normalized, 'reason'=>'ok');
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V15] normalize failed: ' . $e->getMessage());
            return array('normalized'=>$normalized, 'reason'=>'error');
        }
    }
}

if (!function_exists('mleCllV18CalculateLearningHealth')) {
    function mleCllV18CalculateLearningHealth($db, $lotteryId, $gameId, $baselineRecallAt20, $evidenceRuns, $evidenceDraws) {

        $lotteryId = (int)$lotteryId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        $baselineRecallAt20 = max(0.0, min(1.0, (float)$baselineRecallAt20));
        $out = array(
            'status' => 'unchecked',
            'reason' => 'not_checked',
            'recent_draws' => 0,
            'recent_runs' => 0,
            'recent_recall_at_20' => 0.0,
            'baseline_recall_at_20' => $baselineRecallAt20,
            'recent_avg_top20_hits' => 0.0,
            'recent_avg_quality_score' => 0.0,
            'checked_at' => date('Y-m-d H:i:s'),
        );
        if ($lotteryId <= 0 || $gameId === '' || (int)$evidenceRuns <= 0 || (int)$evidenceDraws <= 0) {
            $out['status'] = 'building';
            $out['reason'] = 'insufficient_evidence';
            return $out;
        }
        if ((int)$evidenceDraws < 8 || (int)$evidenceRuns < 30) {
            $out['status'] = 'building';
            $out['reason'] = 'collecting_more_draws';
            return $out;
        }
        try {
            $dq = $db->getQuery(true)
                ->select($db->quoteName('draw_date'))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->where($db->quoteName('draw_date') . ' IS NOT NULL')
                ->group($db->quoteName('draw_date'))
                ->order($db->quoteName('draw_date') . ' DESC')
                ->setLimit(5);
            $db->setQuery($dq);
            $recentDates = (array)$db->loadColumn();
            $recentDates = array_values(array_filter(array_map('strval', $recentDates)));
            if (count($recentDates) < 3) {
                $out['status'] = 'building';
                $out['reason'] = 'not_enough_recent_draws';
                $out['recent_draws'] = count($recentDates);
                return $out;
            }
            $quotedDates = array();
            foreach ($recentDates as $d) { $quotedDates[] = $db->quote($d); }
            $rq = $db->getQuery(true)
                ->select(array(
                    'COUNT(*) AS recent_runs',
                    'COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS recent_draws',
                    'AVG(COALESCE(' . $db->quoteName('top20_hits') . ',0)) AS recent_avg_top20_hits',
                    'AVG(COALESCE(' . $db->quoteName('quality_score') . ',0)) AS recent_avg_quality_score',
                    'AVG(COALESCE(' . $db->quoteName('main_hits') . ',0)) AS recent_avg_main_hits',
                    'SUM(CASE WHEN COALESCE(' . $db->quoteName('main_hits') . ',0) = 0 THEN 1 ELSE 0 END) AS recent_zero_hit_count'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->where($db->quoteName('draw_date') . ' IN (' . implode(',', $quotedDates) . ')');
            $db->setQuery($rq);
            $r = (array)$db->loadAssoc();
            $recentRuns = (int)($r['recent_runs'] ?? 0);
            $recentDraws = (int)($r['recent_draws'] ?? 0);
            $recentAvgTop20 = (float)($r['recent_avg_top20_hits'] ?? 0);
            $recentRecall = max(0.0, min(1.0, $recentAvgTop20 / 5.0));
            $out['recent_runs'] = $recentRuns;
            $out['recent_draws'] = $recentDraws;
            $out['recent_avg_top20_hits'] = $recentAvgTop20;
            $out['recent_avg_quality_score'] = (float)($r['recent_avg_quality_score'] ?? 0);
            $out['recent_recall_at_20'] = $recentRecall;
            if ($recentDraws < 3 || $recentRuns < 10) {
                $out['status'] = 'building';
                $out['reason'] = 'not_enough_recent_scored_runs';
                return $out;
            }
            $delta = $recentRecall - $baselineRecallAt20;
            $ratio = ($baselineRecallAt20 > 0.000001) ? ($recentRecall / $baselineRecallAt20) : 1.0;
            if ($recentDraws >= 5 && $recentRuns >= 20 && $recentRecall <= max(0.05, $baselineRecallAt20 * 0.45)) {
                $out['status'] = 'paused';
                $out['reason'] = 'recent_recall_far_below_baseline';
            } elseif ($recentDraws >= 5 && ($delta <= -0.15 || $ratio <= 0.65)) {
                $out['status'] = 'declining';
                $out['reason'] = 'recent_recall_below_baseline';
            } elseif ($recentDraws >= 4 && ($delta <= -0.07 || $ratio <= 0.85)) {
                $out['status'] = 'watch';
                $out['reason'] = 'recent_recall_softening';
            } else {
                $out['status'] = 'healthy';
                $out['reason'] = 'recent_recall_within_expected_range';
            }
            return $out;
        } catch (\Throwable $e) {
            $out['status'] = 'unchecked';
            $out['reason'] = 'health_check_error';
            return $out;
        }
    }
}

if (!function_exists('mleCllV18RefreshLearningHealth')) {
    function mleCllV18RefreshLearningHealth($db, $lotteryId = 0, $maxRows = 40) {

        static $ran = array();
        $lotteryId = (int)$lotteryId;
        $key = $lotteryId > 0 ? ('lottery_' . $lotteryId) : 'global';
        if (isset($ran[$key])) { return array('checked'=>0, 'updated'=>0, 'reason'=>'already_ran'); }
        $ran[$key] = true;
        $maxRows = max(1, min(12, (int)$maxRows));
        if (!mleCllV1TableExists($db, '#__skai_best_settings') || !mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
            return array('checked'=>0, 'updated'=>0, 'reason'=>'missing_tables');
        }
        mleCllV1EnsureBestSettingsSchema($db);
        $cols = mleCllV1ColumnMap($db, '#__skai_best_settings');
        foreach (array('learning_health_status','learning_health_reason','learning_health_checked_at','source_mode','lottery_id','game_id') as $required) {
            if (empty($cols[$required])) { return array('checked'=>0, 'updated'=>0, 'reason'=>'missing_health_columns'); }
        }
        $checked = 0; $updated = 0;
        try {
            $q = $db->getQuery(true)
                ->select(array(
                    $db->quoteName('id'), $db->quoteName('lottery_id'), $db->quoteName('game_id'),
                    $db->quoteName('status'), $db->quoteName('evidence_runs'), $db->quoteName('evidence_draws'),
                    $db->quoteName('avg_recall_at_20'), $db->quoteName('learning_health_checked_at')
                ))
                ->from($db->quoteName('#__skai_best_settings'))
                ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
            if ($lotteryId > 0) { $q->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId); }

            $q->where('(' . $db->quoteName('learning_health_checked_at') . ' IS NULL OR ' . $db->quoteName('learning_health_checked_at') . ' < DATE_SUB(NOW(), INTERVAL 6 HOUR) OR ' . $db->quoteName('learning_health_status') . ' IN (' . $db->quote('') . ',' . $db->quote('unchecked') . '))')
              ->order(
                  'CASE WHEN ' . $db->quoteName('learning_health_checked_at') . ' IS NULL OR ' . $db->quoteName('learning_health_status') . ' IN (' . $db->quote('') . ',' . $db->quote('unchecked') . ') THEN 0 ELSE 1 END ASC, ' .
                  'CASE WHEN ' . $db->quoteName('status') . ' = ' . $db->quote('active') . ' THEN 0 WHEN ' . $db->quoteName('status') . ' = ' . $db->quote('learning_guided') . ' THEN 1 ELSE 2 END ASC, ' .
                  $db->quoteName('learning_health_checked_at') . ' ASC, ' .
                  $db->quoteName('evidence_runs') . ' DESC, ' . $db->quoteName('evidence_draws') . ' DESC'
              )
              ->setLimit($maxRows);
            $db->setQuery($q);
            $rows = (array)$db->loadAssocList();
            foreach ($rows as $row) {
                if (!is_array($row)) { continue; }
                $id = (int)($row['id'] ?? 0);
                $lid = (int)($row['lottery_id'] ?? 0);
                $gid = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($row['game_id'] ?? ''), 0, 50));
                if ($id <= 0 || $lid <= 0 || $gid === '') { continue; }
                $runs = (int)($row['evidence_runs'] ?? 0);
                $draws = (int)($row['evidence_draws'] ?? 0);
                $baseline = (float)($row['avg_recall_at_20'] ?? 0);
                $health = mleCllV18CalculateLearningHealth($db, $lid, $gid, $baseline, $runs, $draws);
                $healthStatus = strtolower((string)($health['status'] ?? 'unchecked'));
                $healthReason = (string)($health['reason'] ?? '');
                $activeRuns = 80; $activeDraws = 30; $guidedRuns = 100; $guidedDraws = 12; $guidedRecall = 0.35;
                $rawFullyActive = ($runs >= $activeRuns && $draws >= $activeDraws);
                $blocksActive = in_array($healthStatus, array('declining','paused'), true);
                $isFullyActive = ($rawFullyActive && !$blocksActive);
                $isGuided = (!$isFullyActive && $runs >= $guidedRuns && $draws >= $guidedDraws && $baseline >= $guidedRecall && $healthStatus !== 'paused');
                $status = $isFullyActive ? 'active' : ($isGuided ? 'learning_guided' : 'learning');
                $guidanceMode = $isFullyActive ? 'closed_loop_active' : ($isGuided ? 'closed_loop_learning_guided' : 'closed_loop_collecting');
                $guidanceReason = $isFullyActive ? 'active_threshold_met' : ($isGuided ? 'guided_threshold_met_runs_draws_recall' : 'collecting_more_draws');
                if ($blocksActive) { $guidanceReason = 'health_guard_' . ($healthReason !== '' ? $healthReason : $healthStatus); }
                $uq = $db->getQuery(true)->update($db->quoteName('#__skai_best_settings'));
                $sets = array(
                    $db->quoteName('status') . ' = ' . $db->quote($status),
                    $db->quoteName('is_active') . ' = ' . ($isFullyActive ? '1' : '0'),
                    $db->quoteName('guidance_mode') . ' = ' . $db->quote($guidanceMode),
                    $db->quoteName('guidance_reason') . ' = ' . $db->quote(substr($guidanceReason, 0, 250)),
                    $db->quoteName('learning_health_status') . ' = ' . $db->quote($healthStatus),
                    $db->quoteName('learning_health_reason') . ' = ' . $db->quote(substr($healthReason, 0, 250)),
                    $db->quoteName('learning_health_recent_draws') . ' = ' . (int)($health['recent_draws'] ?? 0),
                    $db->quoteName('learning_health_recent_runs') . ' = ' . (int)($health['recent_runs'] ?? 0),
                    $db->quoteName('learning_health_recent_recall_at_20') . ' = ' . (float)($health['recent_recall_at_20'] ?? 0),
                    $db->quoteName('learning_health_baseline_recall_at_20') . ' = ' . (float)($health['baseline_recall_at_20'] ?? $baseline),
                    $db->quoteName('learning_health_checked_at') . ' = ' . $db->quote((string)($health['checked_at'] ?? date('Y-m-d H:i:s'))),
                    $db->quoteName('updated_at') . ' = NOW()'
                );
                $uq->set($sets)->where($db->quoteName('id') . ' = ' . (int)$id)->setLimit(1);
                $db->setQuery($uq); $db->execute();
                $checked++; $updated++;
            }

            try {
                $fix = $db->getQuery(true)->update($db->quoteName('#__skai_best_settings'))
                    ->set($db->quoteName('is_active') . ' = CASE WHEN ' . $db->quoteName('status') . ' = ' . $db->quote('active') . ' THEN 1 ELSE 0 END')
                    ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
                $db->setQuery($fix); $db->execute();
            } catch (\Throwable $ignore) {}
            if ($updated > 0) { error_log('[MLE_CLOSED_LOOP_LEARNING_V20] health refreshed=' . $updated . ' scope=' . $key); }
            return array('checked'=>$checked, 'updated'=>$updated, 'reason'=>'ok');
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V20] health refresh failed: ' . $e->getMessage());
            return array('checked'=>$checked, 'updated'=>$updated, 'reason'=>'error');
        }
    }
}

