if (!function_exists('mleCllV21AggregateWindow')) {
    function mleCllV21AggregateWindow($db, $lotteryId, $gameId, array $drawDates) {
        $out = array('draws'=>0, 'runs'=>0, 'recall_at_20'=>0.0, 'zero_hit_rate'=>0.0);
        $lotteryId = (int)$lotteryId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        $cleanDates = array();
        foreach ($drawDates as $d) {
            $d = substr((string)$d, 0, 10);
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $d)) { $cleanDates[$d] = $d; }
        }
        if ($lotteryId <= 0 || $gameId === '' || empty($cleanDates)) { return $out; }
        try {
            $quoted = array();
            foreach ($cleanDates as $d) { $quoted[] = $db->quote($d); }
            $q = $db->getQuery(true)
                ->select(array(
                    'COUNT(*) AS runs',
                    'COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS draws',
                    'AVG(COALESCE(' . $db->quoteName('top20_hits') . ',0)) AS avg_top20_hits',
                    'AVG(CASE WHEN COALESCE(' . $db->quoteName('main_hits') . ',0) <= 0 THEN 1 ELSE 0 END) AS zero_hit_rate'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->where($db->quoteName('draw_date') . ' IN (' . implode(',', $quoted) . ')');
            $db->setQuery($q);
            $row = (array)$db->loadAssoc();
            $runs = (int)($row['runs'] ?? 0);
            $draws = (int)($row['draws'] ?? 0);
            $avgTop20 = (float)($row['avg_top20_hits'] ?? 0);
            $out['draws'] = $draws;
            $out['runs'] = $runs;
            $out['recall_at_20'] = $runs > 0 ? min(1.0, max(0.0, $avgTop20 / 20.0)) : 0.0;
            $out['zero_hit_rate'] = $runs > 0 ? min(1.0, max(0.0, (float)($row['zero_hit_rate'] ?? 0))) : 0.0;
            return $out;
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V21] aggregate window failed: ' . $e->getMessage());
            return $out;
        }
    }
}

if (!function_exists('mleCllV21BuildLearningImprovementReport')) {
    function mleCllV21BuildLearningImprovementReport($db, $maxRows = 100) {

        $maxRows = max(1, min(250, (int)$maxRows));
        $out = array('processed'=>0, 'stored'=>0, 'improving'=>0, 'stable'=>0, 'softening'=>0, 'insufficient'=>0, 'reason'=>'starting');
        if (!mleCllV1TableExists($db, '#__skai_best_settings') || !mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
            $out['reason'] = 'missing_tables';
            return $out;
        }
        if (!mleCllV21EnsureImprovementReportTable($db)) { $out['reason'] = 'report_table_failed'; return $out; }
        try {
            $q = $db->getQuery(true)
                ->select(array(
                    $db->quoteName('lottery_id'), $db->quoteName('game_id'), $db->quoteName('status'), $db->quoteName('is_active'),
                    $db->quoteName('evidence_runs'), $db->quoteName('evidence_draws'), $db->quoteName('avg_recall_at_20'),
                    $db->quoteName('learning_health_status')
                ))
                ->from($db->quoteName('#__skai_best_settings'))
                ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'))
                ->order($db->quoteName('evidence_runs') . ' DESC, ' . $db->quoteName('evidence_draws') . ' DESC')
                ->setLimit($maxRows);
            $db->setQuery($q);
            $sources = (array)$db->loadAssocList();
            foreach ($sources as $src) {
                if (!is_array($src)) { continue; }
                $lid = (int)($src['lottery_id'] ?? 0);
                $gid = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($src['game_id'] ?? ''), 0, 50));
                if ($lid <= 0 || $gid === '') { continue; }
                $out['processed']++;
                $dq = $db->getQuery(true)
                    ->select($db->quoteName('draw_date'))
                    ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                    ->where($db->quoteName('lottery_id') . ' = ' . (int)$lid)
                    ->where($db->quoteName('game_id') . ' = ' . $db->quote($gid))
                    ->group($db->quoteName('draw_date'))
                    ->order($db->quoteName('draw_date') . ' ASC');
                $db->setQuery($dq);
                $allDates = array_values(array_filter(array_map('strval', (array)$db->loadColumn())));
                $totalDraws = count($allDates);
                $earlyDates = array(); $recentDates = array();
                if ($totalDraws >= 10) {
                    $earlyDates = array_slice($allDates, 0, min(5, (int)floor($totalDraws / 2)));
                    $recentDates = array_slice($allDates, -5);
                } else {
                    $recentDates = array_slice($allDates, -min(5, $totalDraws));
                }
                $early = mleCllV21AggregateWindow($db, $lid, $gid, $earlyDates);
                $recent = mleCllV21AggregateWindow($db, $lid, $gid, $recentDates);
                $baseline = (float)($src['avg_recall_at_20'] ?? 0);
                $delta = (float)$recent['recall_at_20'] - (float)$early['recall_at_20'];
                $lift = ((float)$early['recall_at_20'] > 0.000001) ? ($delta / (float)$early['recall_at_20']) * 100.0 : 0.0;
                $zeroDelta = (float)$recent['zero_hit_rate'] - (float)$early['zero_hit_rate'];
                $status = 'insufficient';
                $reason = 'needs_at_least_10_draw_dates_for_early_vs_recent_comparison';
                if ($totalDraws >= 10 && (int)$early['runs'] >= 20 && (int)$recent['runs'] >= 20) {
                    if ($delta >= 0.030000 && $zeroDelta <= 0.050000) { $status = 'improving'; $reason = 'recent_recall_higher_than_early_window'; }
                    elseif ($delta <= -0.050000 || $zeroDelta >= 0.150000) { $status = 'softening'; $reason = 'recent_recall_or_zero_hit_rate_weaker_than_early_window'; }
                    else { $status = 'stable'; $reason = 'recent_window_close_to_early_window'; }
                }
                if (!isset($out[$status])) { $out[$status] = 0; }
                $out[$status]++;
                $cols = array(
                    'lottery_id','game_id','status','is_active','health_status','evidence_runs','evidence_draws','unique_users',
                    'baseline_recall_at_20','early_draws','early_runs','early_recall_at_20','early_zero_hit_rate',
                    'recent_draws','recent_runs','recent_recall_at_20','recent_zero_hit_rate','recall_delta','recall_lift_pct','zero_hit_delta',
                    'improvement_status','improvement_reason','generated_at'
                );
                $uqUsers = $db->getQuery(true)
                    ->select('COUNT(DISTINCT ' . $db->quoteName('user_id') . ')')
                    ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                    ->where($db->quoteName('lottery_id') . ' = ' . (int)$lid)
                    ->where($db->quoteName('game_id') . ' = ' . $db->quote($gid));
                $db->setQuery($uqUsers);
                $uniqueUsers = (int)$db->loadResult();
                $vals = array(
                    (int)$lid,
                    $db->quote($gid),
                    $db->quote(substr((string)($src['status'] ?? ''), 0, 32)),
                    (int)($src['is_active'] ?? 0),
                    $db->quote(substr((string)($src['learning_health_status'] ?? ''), 0, 32)),
                    (int)($src['evidence_runs'] ?? 0),
                    (int)($src['evidence_draws'] ?? 0),
                    (int)$uniqueUsers,
                    sprintf('%.6F', $baseline),
                    (int)$early['draws'],
                    (int)$early['runs'],
                    sprintf('%.6F', (float)$early['recall_at_20']),
                    sprintf('%.6F', (float)$early['zero_hit_rate']),
                    (int)$recent['draws'],
                    (int)$recent['runs'],
                    sprintf('%.6F', (float)$recent['recall_at_20']),
                    sprintf('%.6F', (float)$recent['zero_hit_rate']),
                    sprintf('%.6F', $delta),
                    sprintf('%.4F', $lift),
                    sprintf('%.6F', $zeroDelta),
                    $db->quote($status),
                    $db->quote(substr($reason, 0, 250)),
                    'NOW()'
                );
                $iq = $db->getQuery(true)->insert($db->quoteName('#__skai_learning_improvement_report_cache'))->columns($db->quoteName($cols))->values(implode(',', $vals));
                $updates = array();
                foreach ($cols as $c) {
                    if (in_array($c, array('lottery_id','game_id'), true)) { continue; }
                    $updates[] = $db->quoteName($c) . ' = VALUES(' . $db->quoteName($c) . ')';
                }
                $db->setQuery((string)$iq . ' ON DUPLICATE KEY UPDATE ' . implode(', ', $updates));
                $db->execute();
                $out['stored']++;
            }
            $out['reason'] = 'ok';
            error_log('[MLE_CLOSED_LOOP_LEARNING_V21] improvement report built stored=' . (int)$out['stored']);
            return $out;
        } catch (\Throwable $e) {
            $out['reason'] = 'error: ' . $e->getMessage();
            error_log('[MLE_CLOSED_LOOP_LEARNING_V21] improvement report failed: ' . $e->getMessage());
            return $out;
        }
    }
}

