            $db->setQuery('SHOW COLUMNS FROM `' . str_replace('`', '``', $table) . '` LIKE ' . $db->quote((string)$columnName));
            return (bool)$db->loadAssoc();
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V22] column check failed ' . $columnName . ': ' . $e->getMessage());
            return false;
        }
    }
}

