if (!function_exists('mleCllV22BuildLearningImprovementReport')) {
    function mleCllV22BuildLearningImprovementReport($db, $maxRows = 100) {
        $maxRows = max(1, min(500, (int)$maxRows));
        $out = array('processed'=>0, 'stored'=>0, 'improving'=>0, 'stable'=>0, 'softening'=>0, 'insufficient'=>0, 'reason'=>'starting');
        if (!mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) { $out['reason'] = 'missing_evidence_table'; return $out; }
        if (!mleCllV22EnsureImprovementReportTable($db)) { $out['reason'] = 'report_table_failed'; return $out; }
        try {

            $q = $db->getQuery(true)
                ->select(array(
                    'e.' . $db->quoteName('lottery_id') . ' AS lottery_id',
                    'e.' . $db->quoteName('game_id') . ' AS game_id',
                    'COUNT(*) AS evidence_runs',
                    'COUNT(DISTINCT e.' . $db->quoteName('draw_date') . ') AS evidence_draws',
                    'COUNT(DISTINCT e.' . $db->quoteName('user_id') . ') AS unique_users',
                    'LEAST(1, AVG(COALESCE(e.' . $db->quoteName('top20_hits') . ',0)) / 20) AS baseline_recall_at_20',
                    'MAX(COALESCE(bs.' . $db->quoteName('status') . ',\'\')) AS status',
                    'MAX(COALESCE(bs.' . $db->quoteName('is_active') . ',0)) AS is_active',
                    'MAX(COALESCE(bs.' . $db->quoteName('learning_health_status') . ',\'\')) AS health_status'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events', 'e'))
                ->join('LEFT', $db->quoteName('#__skai_best_settings', 'bs') . ' ON bs.' . $db->quoteName('lottery_id') . ' = e.' . $db->quoteName('lottery_id') . ' AND bs.' . $db->quoteName('game_id') . ' = e.' . $db->quoteName('game_id') . ' AND bs.' . $db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'))
                ->where('e.' . $db->quoteName('lottery_id') . ' IS NOT NULL')
                ->where('e.' . $db->quoteName('game_id') . ' IS NOT NULL')
                ->where('e.' . $db->quoteName('game_id') . ' <> ' . $db->quote(''))
                ->group(array('e.' . $db->quoteName('lottery_id'), 'e.' . $db->quoteName('game_id')))
                ->order('COUNT(*) DESC, COUNT(DISTINCT e.' . $db->quoteName('draw_date') . ') DESC')
                ->setLimit($maxRows);
            $db->setQuery($q);
            $sources = (array)$db->loadAssocList();

            try {
                $dq = $db->getQuery(true)
                    ->delete($db->quoteName('#__skai_learning_improvement_report_cache'))
                    ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
                $db->setQuery($dq); $db->execute();
            } catch (\Throwable $e) { error_log('[MLE_CLOSED_LOOP_LEARNING_V22] report cache delete failed: ' . $e->getMessage()); }

            foreach ($sources as $src) {
                if (!is_array($src)) { continue; }
                $lid = (int)($src['lottery_id'] ?? 0);
                $gid = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($src['game_id'] ?? ''), 0, 64));
                if ($lid <= 0 || $gid === '') { continue; }
                $out['processed']++;

                $datesQ = $db->getQuery(true)
                    ->select('e.' . $db->quoteName('draw_date'))
                    ->from($db->quoteName('#__skai_closed_loop_learning_events', 'e'))
                    ->where('e.' . $db->quoteName('lottery_id') . ' = ' . (int)$lid)
                    ->where('e.' . $db->quoteName('game_id') . ' = ' . $db->quote($gid))
                    ->group('e.' . $db->quoteName('draw_date'))
                    ->order('e.' . $db->quoteName('draw_date') . ' ASC');
                $db->setQuery($datesQ);
                $allDates = array_values(array_filter(array_map('strval', (array)$db->loadColumn())));
                $totalDraws = count($allDates);
                $earlyDates = array(); $recentDates = array();
                if ($totalDraws >= 10) {
                    $earlyDates = array_slice($allDates, 0, min(5, (int)floor($totalDraws / 2)));
                    $recentDates = array_slice($allDates, -5);
                } else {
                    $recentDates = array_slice($allDates, -min(5, $totalDraws));
                }
                $early = mleCllV22AggregateWindow($db, $lid, $gid, $earlyDates);
                $recent = mleCllV22AggregateWindow($db, $lid, $gid, $recentDates);
                $baseline = (float)($src['baseline_recall_at_20'] ?? 0);
                $delta = (float)$recent['recall_at_20'] - (float)$early['recall_at_20'];
                $lift = ((float)$early['recall_at_20'] > 0.000001) ? ($delta / (float)$early['recall_at_20']) * 100.0 : 0.0;
                $zeroDelta = (float)$recent['zero_hit_rate'] - (float)$early['zero_hit_rate'];
                $status = 'insufficient';
                $reason = 'needs_at_least_10_draw_dates_and_20_runs_in_each_window';
                if ($totalDraws >= 10 && (int)$early['runs'] >= 20 && (int)$recent['runs'] >= 20) {
                    if ($delta >= 0.030000 && $zeroDelta <= 0.050000) { $status = 'improving'; $reason = 'recent_recall_higher_than_early_window'; }
                    elseif ($delta <= -0.050000 || $zeroDelta >= 0.150000) { $status = 'softening'; $reason = 'recent_recall_or_zero_hit_rate_weaker_than_early_window'; }
                    else { $status = 'stable'; $reason = 'recent_window_close_to_early_window'; }
                }
                if (!isset($out[$status])) { $out[$status] = 0; }
                $out[$status]++;
                $report = array(
                    'builder' => 'v22_deterministic',
                    'lottery_id' => $lid,
                    'game_id' => $gid,
                    'total_draws' => $totalDraws,
                    'early_dates' => array_values($earlyDates),
                    'recent_dates' => array_values($recentDates),
                    'baseline_recall_at_20' => $baseline,
                    'early' => $early,
                    'recent' => $recent,
                    'recall_delta' => $delta,
                    'recall_lift_pct' => $lift,
                    'zero_hit_delta' => $zeroDelta,
                    'improvement_status' => $status,
                    'improvement_reason' => $reason
                );
                $cols = array(
                    'lottery_id','game_id','source_mode','status','is_active','health_status','evidence_runs','evidence_draws','unique_users',
                    'baseline_recall_at_20','early_draws','early_runs','early_recall_at_20','early_zero_hit_rate',
                    'recent_draws','recent_runs','recent_recall_at_20','recent_zero_hit_rate','recall_delta','recall_lift_pct','zero_hit_delta',
                    'improvement_status','improvement_reason','report_json','built_at','generated_at'
                );
                $vals = array(
                    (int)$lid,
                    $db->quote($gid),
                    $db->quote('mle_closed_loop_learning_v1'),
                    $db->quote(substr((string)($src['status'] ?? ''), 0, 32)),
                    (int)($src['is_active'] ?? 0),
                    $db->quote(substr((string)($src['health_status'] ?? ''), 0, 32)),
                    (int)($src['evidence_runs'] ?? 0),
                    (int)($src['evidence_draws'] ?? 0),
                    (int)($src['unique_users'] ?? 0),
                    sprintf('%.6F', $baseline),
                    (int)$early['draws'],
                    (int)$early['runs'],
                    sprintf('%.6F', (float)$early['recall_at_20']),
                    sprintf('%.6F', (float)$early['zero_hit_rate']),
                    (int)$recent['draws'],
                    (int)$recent['runs'],
                    sprintf('%.6F', (float)$recent['recall_at_20']),
                    sprintf('%.6F', (float)$recent['zero_hit_rate']),
                    sprintf('%.6F', $delta),
                    sprintf('%.4F', $lift),
                    sprintf('%.6F', $zeroDelta),
                    $db->quote($status),
                    $db->quote(substr($reason, 0, 250)),
                    $db->quote(json_encode($report)),
                    'NOW()',
                    'NOW()'
                );
                $iq = $db->getQuery(true)->insert($db->quoteName('#__skai_learning_improvement_report_cache'))->columns($db->quoteName($cols))->values(implode(',', $vals));
                $db->setQuery($iq);
                $db->execute();
                $out['stored']++;
            }
            $out['reason'] = 'ok';
            error_log('[MLE_CLOSED_LOOP_LEARNING_V22] deterministic improvement report built stored=' . (int)$out['stored']);
            return $out;
        } catch (\Throwable $e) {
            $out['reason'] = 'error: ' . $e->getMessage();
            error_log('[MLE_CLOSED_LOOP_LEARNING_V22] deterministic improvement report failed: ' . $e->getMessage());
            return $out;
        }
    }
}

