if (!function_exists('mleCllV24EnsurePostLearningColumns')) {
    function mleCllV24EnsurePostLearningColumns($db) {
        if (!function_exists('mleCllV1TableExists') || !mleCllV1TableExists($db, '#__skai_learning_improvement_report_cache')) { return false; }
        $prefix = $db->getPrefix();
        $table = $prefix . 'skai_learning_improvement_report_cache';
        $columns = array(
            'measurement_mode' => "ALTER TABLE `{$table}` ADD COLUMN `measurement_mode` VARCHAR(64) NOT NULL DEFAULT 'early_recent_window' AFTER `source_mode`",
            'learning_split_at' => "ALTER TABLE `{$table}` ADD COLUMN `learning_split_at` DATETIME NULL AFTER `measurement_mode`",
            'pre_learning_draws' => "ALTER TABLE `{$table}` ADD COLUMN `pre_learning_draws` INT(11) NOT NULL DEFAULT 0 AFTER `learning_split_at`",
            'pre_learning_runs' => "ALTER TABLE `{$table}` ADD COLUMN `pre_learning_runs` INT(11) NOT NULL DEFAULT 0 AFTER `pre_learning_draws`",
            'pre_learning_recall_at_20' => "ALTER TABLE `{$table}` ADD COLUMN `pre_learning_recall_at_20` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `pre_learning_runs`",
            'pre_learning_zero_hit_rate' => "ALTER TABLE `{$table}` ADD COLUMN `pre_learning_zero_hit_rate` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `pre_learning_recall_at_20`",
            'post_learning_draws' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_draws` INT(11) NOT NULL DEFAULT 0 AFTER `pre_learning_zero_hit_rate`",
            'post_learning_runs' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_runs` INT(11) NOT NULL DEFAULT 0 AFTER `post_learning_draws`",
            'post_learning_recall_at_20' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_recall_at_20` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `post_learning_runs`",
            'post_learning_zero_hit_rate' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_zero_hit_rate` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `post_learning_recall_at_20`",
            'post_learning_recall_delta' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_recall_delta` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `post_learning_zero_hit_rate`",
            'post_learning_recall_lift_pct' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_recall_lift_pct` DECIMAL(12,4) NOT NULL DEFAULT 0.0000 AFTER `post_learning_recall_delta`",
            'post_learning_zero_hit_delta' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_zero_hit_delta` DECIMAL(12,6) NOT NULL DEFAULT 0.000000 AFTER `post_learning_recall_lift_pct`",
            'post_learning_status' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_status` VARCHAR(32) NOT NULL DEFAULT 'unchecked' AFTER `post_learning_zero_hit_delta`",
            'post_learning_reason' => "ALTER TABLE `{$table}` ADD COLUMN `post_learning_reason` VARCHAR(255) NOT NULL DEFAULT '' AFTER `post_learning_status`"
        );
        foreach ($columns as $col => $sql) {
            try {
                if (function_exists('mleCllV22ColumnExists') && !mleCllV22ColumnExists($db, '#__skai_learning_improvement_report_cache', $col)) {
                    $db->setQuery($sql); $db->execute();
                }
            } catch (\Throwable $e) { error_log('[MLE_CLOSED_LOOP_LEARNING_V24] add column failed ' . $col . ': ' . $e->getMessage()); }
        }
        return true;
    }
}

if (!function_exists('mleCllV24AggregateBySplit')) {
    function mleCllV24AggregateBySplit($db, $lotteryId, $gameId, $splitDate, $side) {
        $out = array('draws'=>0, 'runs'=>0, 'recall_at_20'=>0.0, 'zero_hit_rate'=>0.0);
        $lotteryId = (int)$lotteryId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 64));
        $splitDate = substr((string)$splitDate, 0, 10);
        if ($lotteryId <= 0 || $gameId === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $splitDate)) { return $out; }
        $op = ($side === 'post') ? '>=' : '<';
        try {
            $q = $db->getQuery(true)
                ->select(array(
                    'COUNT(*) AS runs',
                    'COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS draws',
                    'AVG(COALESCE(' . $db->quoteName('top20_hits') . ',0)) AS avg_top20_hits',
                    'AVG(CASE WHEN COALESCE(' . $db->quoteName('main_hits') . ',0) <= 0 THEN 1 ELSE 0 END) AS zero_hit_rate'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->where($db->quoteName('draw_date') . ' ' . $op . ' ' . $db->quote($splitDate));
            $db->setQuery($q);
            $row = (array)$db->loadAssoc();
            $runs = (int)($row['runs'] ?? 0);
            $draws = (int)($row['draws'] ?? 0);
            $avgTop20 = (float)($row['avg_top20_hits'] ?? 0);
            $out['draws'] = $draws;
            $out['runs'] = $runs;
            $out['recall_at_20'] = $runs > 0 ? min(1.0, max(0.0, $avgTop20 / 20.0)) : 0.0;
            $out['zero_hit_rate'] = $runs > 0 ? min(1.0, max(0.0, (float)($row['zero_hit_rate'] ?? 0))) : 0.0;
        } catch (\Throwable $e) { error_log('[MLE_CLOSED_LOOP_LEARNING_V24] aggregate split failed: ' . $e->getMessage()); }
        return $out;
    }
}

if (!function_exists('mleCllV24BuildPrePostLearningReport')) {
    function mleCllV24BuildPrePostLearningReport($db, $maxRows = 100) {
        $maxRows = max(1, min(500, (int)$maxRows));
        $out = array('processed'=>0, 'updated'=>0, 'improving'=>0, 'stable'=>0, 'softening'=>0, 'awaiting'=>0, 'insufficient'=>0, 'reason'=>'starting');
        if (!function_exists('mleCllV22BuildLearningImprovementReport')) { $out['reason'] = 'missing_v22_builder'; return $out; }
        if (!mleCllV1TableExists($db, '#__skai_learning_improvement_report_cache')) { mleCllV22BuildLearningImprovementReport($db, $maxRows); }
        if (!mleCllV24EnsurePostLearningColumns($db)) { $out['reason'] = 'post_learning_columns_failed'; return $out; }
        try {

            $countQ = $db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__skai_learning_improvement_report_cache'))->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
            $db->setQuery($countQ);
            if ((int)$db->loadResult() <= 0) { mleCllV22BuildLearningImprovementReport($db, $maxRows); }

            $q = $db->getQuery(true)
                ->select(array(
                    'e.' . $db->quoteName('lottery_id') . ' AS lottery_id',
                    'e.' . $db->quoteName('game_id') . ' AS game_id',
                    'COUNT(*) AS evidence_runs',
                    'COUNT(DISTINCT e.' . $db->quoteName('draw_date') . ') AS evidence_draws',
                    'MIN(e.' . $db->quoteName('draw_date') . ') AS first_draw',
                    'MAX(e.' . $db->quoteName('draw_date') . ') AS latest_draw',
                    'MAX(bs.' . $db->quoteName('promoted_at') . ') AS promoted_at',
                    'MAX(bs.' . $db->quoteName('updated_at') . ') AS best_updated_at'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events', 'e'))
                ->join('LEFT', $db->quoteName('#__skai_best_settings', 'bs') . ' ON bs.' . $db->quoteName('lottery_id') . ' = e.' . $db->quoteName('lottery_id') . ' AND bs.' . $db->quoteName('game_id') . ' = e.' . $db->quoteName('game_id') . ' AND bs.' . $db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'))
                ->where('e.' . $db->quoteName('lottery_id') . ' IS NOT NULL')
                ->where('e.' . $db->quoteName('game_id') . ' IS NOT NULL')
                ->where('e.' . $db->quoteName('game_id') . ' <> ' . $db->quote(''))
                ->group(array('e.' . $db->quoteName('lottery_id'), 'e.' . $db->quoteName('game_id')))
                ->order('COUNT(*) DESC, COUNT(DISTINCT e.' . $db->quoteName('draw_date') . ') DESC')
                ->setLimit($maxRows);
            $db->setQuery($q);
            $sources = (array)$db->loadAssocList();
            foreach ($sources as $src) {
                $lid = (int)($src['lottery_id'] ?? 0);
                $gid = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($src['game_id'] ?? ''), 0, 64));
                if ($lid <= 0 || $gid === '') { continue; }
                $out['processed']++;
                $splitAtRaw = (string)($src['promoted_at'] ?? '');
                if ($splitAtRaw === '' || $splitAtRaw === '0000-00-00 00:00:00') { $splitAtRaw = (string)($src['best_updated_at'] ?? ''); }
                $splitDate = substr($splitAtRaw, 0, 10);
                $pre = array('draws'=>0,'runs'=>0,'recall_at_20'=>0.0,'zero_hit_rate'=>0.0);
                $post = array('draws'=>0,'runs'=>0,'recall_at_20'=>0.0,'zero_hit_rate'=>0.0);
                $status = 'awaiting_post_learning_scores';
                $reason = 'learning_promoted_but_no_scored_post_learning_draw_window_yet';
                if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $splitDate)) {
                    $status = 'insufficient';
                    $reason = 'missing_learning_promotion_split_date';
                    $splitDate = null;
                } else {
                    $pre = mleCllV24AggregateBySplit($db, $lid, $gid, $splitDate, 'pre');
                    $post = mleCllV24AggregateBySplit($db, $lid, $gid, $splitDate, 'post');
                    if ((int)$post['draws'] < 3 || (int)$post['runs'] < 20) {
                        $status = 'awaiting_post_learning_scores';
                        $reason = 'needs_at_least_3_post_learning_draw_dates_and_20_post_learning_runs';
                    } elseif ((int)$pre['draws'] < 10 || (int)$pre['runs'] < 50) {
                        $status = 'insufficient';
                        $reason = 'needs_at_least_10_pre_learning_draw_dates_and_50_pre_learning_runs';
                    } else {
                        $deltaTmp = (float)$post['recall_at_20'] - (float)$pre['recall_at_20'];
                        $zeroTmp = (float)$post['zero_hit_rate'] - (float)$pre['zero_hit_rate'];
                        if ($deltaTmp >= 0.030000 && $zeroTmp <= 0.050000) { $status = 'improving_after_learning'; $reason = 'post_learning_recall_higher_than_pre_learning_baseline'; }
                        elseif ($deltaTmp <= -0.050000 || $zeroTmp >= 0.150000) { $status = 'softening_after_learning'; $reason = 'post_learning_recall_or_zero_hit_rate_weaker_than_pre_learning_baseline'; }
                        else { $status = 'stable_after_learning'; $reason = 'post_learning_window_close_to_pre_learning_baseline'; }
                    }
                }
                $delta = (float)$post['recall_at_20'] - (float)$pre['recall_at_20'];
                $lift = ((float)$pre['recall_at_20'] > 0.000001) ? ($delta / (float)$pre['recall_at_20']) * 100.0 : 0.0;
                $zeroDelta = (float)$post['zero_hit_rate'] - (float)$pre['zero_hit_rate'];
                if (strpos($status, 'improving') !== false) { $out['improving']++; }
                elseif (strpos($status, 'softening') !== false) { $out['softening']++; }
                elseif (strpos($status, 'stable') !== false) { $out['stable']++; }
                elseif (strpos($status, 'awaiting') !== false) { $out['awaiting']++; }
                else { $out['insufficient']++; }
                $report = array(
                    'builder' => 'v24_pre_post_learning',
                    'measurement_mode' => 'pre_post_learning',
                    'split_at' => $splitAtRaw,
                    'split_date' => $splitDate,
                    'pre_learning' => $pre,
                    'post_learning' => $post,
                    'recall_delta' => $delta,
                    'recall_lift_pct' => $lift,
                    'zero_hit_delta' => $zeroDelta,
                    'post_learning_status' => $status,
                    'post_learning_reason' => $reason
                );
                $uq = $db->getQuery(true)
                    ->update($db->quoteName('#__skai_learning_improvement_report_cache'))
                    ->set($db->quoteName('measurement_mode') . ' = ' . $db->quote('pre_post_learning'))
                    ->set($db->quoteName('learning_split_at') . ' = ' . ($splitAtRaw !== '' ? $db->quote($splitAtRaw) : 'NULL'))
                    ->set($db->quoteName('pre_learning_draws') . ' = ' . (int)$pre['draws'])
                    ->set($db->quoteName('pre_learning_runs') . ' = ' . (int)$pre['runs'])
                    ->set($db->quoteName('pre_learning_recall_at_20') . ' = ' . sprintf('%.6F', (float)$pre['recall_at_20']))
                    ->set($db->quoteName('pre_learning_zero_hit_rate') . ' = ' . sprintf('%.6F', (float)$pre['zero_hit_rate']))
                    ->set($db->quoteName('post_learning_draws') . ' = ' . (int)$post['draws'])
                    ->set($db->quoteName('post_learning_runs') . ' = ' . (int)$post['runs'])
                    ->set($db->quoteName('post_learning_recall_at_20') . ' = ' . sprintf('%.6F', (float)$post['recall_at_20']))
                    ->set($db->quoteName('post_learning_zero_hit_rate') . ' = ' . sprintf('%.6F', (float)$post['zero_hit_rate']))
                    ->set($db->quoteName('post_learning_recall_delta') . ' = ' . sprintf('%.6F', $delta))
                    ->set($db->quoteName('post_learning_recall_lift_pct') . ' = ' . sprintf('%.4F', $lift))
                    ->set($db->quoteName('post_learning_zero_hit_delta') . ' = ' . sprintf('%.6F', $zeroDelta))
                    ->set($db->quoteName('post_learning_status') . ' = ' . $db->quote(substr($status, 0, 32)))
                    ->set($db->quoteName('post_learning_reason') . ' = ' . $db->quote(substr($reason, 0, 250)))
                    ->set($db->quoteName('improvement_status') . ' = ' . $db->quote(substr($status, 0, 32)))
                    ->set($db->quoteName('improvement_reason') . ' = ' . $db->quote(substr($reason, 0, 250)))
                    ->set($db->quoteName('report_json') . ' = ' . $db->quote(json_encode($report)))
                    ->set($db->quoteName('built_at') . ' = NOW()')
                    ->set($db->quoteName('generated_at') . ' = NOW()')
                    ->where($db->quoteName('lottery_id') . ' = ' . (int)$lid)
                    ->where($db->quoteName('game_id') . ' = ' . $db->quote($gid))
                    ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
                $db->setQuery($uq); $db->execute();
                $out['updated']++;
            }
            $out['reason'] = 'ok';
            error_log('[MLE_CLOSED_LOOP_LEARNING_V24] pre/post learning report updated=' . (int)$out['updated']);
            return $out;
        } catch (\Throwable $e) {
            $out['reason'] = 'error: ' . $e->getMessage();
            error_log('[MLE_CLOSED_LOOP_LEARNING_V24] pre/post learning report failed: ' . $e->getMessage());
            return $out;
        }
    }
}

