                    'r.' . $db->quoteName('recent_recall_at_20'),
                    'r.' . $db->quoteName('recent_zero_hit_rate'),
                    'r.' . $db->quoteName('recall_delta'),
                    'r.' . $db->quoteName('recall_lift_pct'),
                    'r.' . $db->quoteName('zero_hit_delta'),
                    'r.' . $db->quoteName('measurement_mode'),
                    'r.' . $db->quoteName('post_learning_status'),
                    'r.' . $db->quoteName('post_learning_reason'),
                    'r.' . $db->quoteName('post_learning_draws'),
                    'r.' . $db->quoteName('post_learning_runs'),
                    'r.' . $db->quoteName('post_learning_recall_delta'),
                    'r.' . $db->quoteName('post_learning_recall_lift_pct'),
                    'r.' . $db->quoteName('post_learning_zero_hit_delta'),
                    'r.' . $db->quoteName('improvement_status'),
                    'r.' . $db->quoteName('improvement_reason'),
                    'r.' . $db->quoteName('built_at'),
                    'r.' . $db->quoteName('generated_at')
                ))
                ->from($db->quoteName('#__skai_learning_improvement_report_cache', 'r'))
                ->order('CASE r.' . $db->quoteName('status') . ' WHEN ' . $db->quote('active') . ' THEN 1 WHEN ' . $db->quote('learning_guided') . ' THEN 2 ELSE 3 END ASC')
                ->order('CASE r.' . $db->quoteName('health_status') . ' WHEN ' . $db->quote('paused') . ' THEN 1 WHEN ' . $db->quote('declining') . ' THEN 2 WHEN ' . $db->quote('watch') . ' THEN 3 WHEN ' . $db->quote('healthy') . ' THEN 4 ELSE 5 END ASC')
                ->order('r.' . $db->quoteName('evidence_runs') . ' DESC');
            $db->setQuery($q, 0, $limit);
            $rows = $db->loadAssocList();
            $out['ok'] = true;
            $out['rows'] = is_array($rows) ? $rows : array();
            $out['reason'] = 'ok';
            return $out;
        } catch (\Throwable $e) {
            $out['reason'] = 'error: ' . $e->getMessage();
            error_log('[MLE_CLOSED_LOOP_LEARNING_V23] dashboard load failed: ' . $e->getMessage());
            return $out;
        }
    }
}

if (!function_exists('mleCllV23RenderLearningDashboard')) {
    function mleCllV23RenderLearningDashboard($db, $app, $limit = 100) {
        $data = mleCllV23LoadImprovementRows($db, $limit);
        $rows = isset($data['rows']) && is_array($data['rows']) ? $data['rows'] : array();
        $counts = array('total'=>0, 'active'=>0, 'guided'=>0, 'learning'=>0, 'healthy'=>0, 'watch'=>0, 'declining'=>0, 'paused'=>0, 'building'=>0, 'improving'=>0, 'stable'=>0, 'softening'=>0, 'insufficient'=>0);
        foreach ($rows as $r) {
            $counts['total']++;
            $st = strtolower((string)($r['status'] ?? ''));
            if ($st === 'active') { $counts['active']++; }
            elseif ($st === 'learning_guided') { $counts['guided']++; }
            else { $counts['learning']++; }
            $hs = strtolower((string)($r['health_status'] ?? ''));
            if (isset($counts[$hs])) { $counts[$hs]++; }
            $is = strtolower((string)($r['improvement_status'] ?? ''));
            if (isset($counts[$is])) { $counts[$is]++; }
        }

        $dashboardUrl = '';
        $refreshUrl = '';
        $healthRefreshUrl = '';
        $fullMaintenanceUrl = '';
        try {
            $uri = \Joomla\CMS\Uri\Uri::getInstance();
            $du = clone $uri;
            $du->setVar('mle_learning_dashboard', '1');
            $dashboardUrl = $du->toString();

            $ru = clone $uri;
            $ru->setVar('mle_learning_dashboard', '1');
            $ru->setVar('mle_build_learning_improvement_report', '1');
            $ru->setVar('mle_report_limit', (string)max(1, min(250, (int)$limit)));
            $refreshUrl = $ru->toString();

            $hu = clone $uri;
            $hu->setVar('mle_learning_dashboard', '1');
            $hu->setVar('mle_refresh_learning_health', '1');
            $hu->setVar('mle_health_limit', (string)max(1, min(250, (int)$limit)));
            $healthRefreshUrl = $hu->toString();

            $fu = clone $uri;
            $fu->setVar('mle_learning_dashboard', '1');
            $fu->setVar('mle_refresh_learning_health', '1');
            $fu->setVar('mle_health_limit', (string)max(1, min(250, (int)$limit)));
            $fu->setVar('mle_build_learning_improvement_report', '1');
            $fu->setVar('mle_report_limit', (string)max(1, min(250, (int)$limit)));
            $fullMaintenanceUrl = $fu->toString();
        } catch (\Throwable $ignore) {}

        echo '<section class="mle-v23-learning-dashboard" style="margin:18px 0;padding:18px;border:1px solid #dbeafe;border-radius:18px;background:#f8fbff;color:#0f172a;box-shadow:0 12px 30px rgba(15,23,42,.06);">';
        echo '<div style="display:flex;gap:14px;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;">';
        echo '<div><h2 style="margin:0 0 6px;font-size:22px;line-height:1.2;color:#0f172a;">LottoExpert Learning Dashboard</h2>';
        echo '<p style="margin:0;color:#475569;font-size:14px;">Admin-only view of closed-loop learning status, health, and measured improvement. Pending post-learning measurements are shown as Pending until enough scored draws exist after LottoExpert Learning was activated.</p></div>';
        echo '<div style="display:flex;gap:8px;align-items:center;justify-content:flex-end;flex-wrap:wrap;">';
        if ($healthRefreshUrl !== '') { echo '<a href="' . mleCllV23Html($healthRefreshUrl) . '" style="display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border-radius:999px;background:#047857;color:#fff;text-decoration:none;font-weight:800;font-size:13px;">Refresh Learning Health</a>'; }
        if ($refreshUrl !== '') { echo '<a href="' . mleCllV23Html($refreshUrl) . '" style="display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border-radius:999px;background:#1d4ed8;color:#fff;text-decoration:none;font-weight:800;font-size:13px;">Rebuild Improvement Report</a>'; }
        if ($fullMaintenanceUrl !== '') { echo '<a href="' . mleCllV23Html($fullMaintenanceUrl) . '" style="display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border-radius:999px;background:#111827;color:#fff;text-decoration:none;font-weight:900;font-size:13px;">Run Full Learning Maintenance</a>'; }
        echo '</div>';
        echo '</div>';
        echo '<div style="margin-top:12px;padding:12px;border:1px solid #dbeafe;border-radius:14px;background:#ffffff;color:#334155;font-size:13px;line-height:1.45;">';
        echo '<strong style="color:#0f172a;">Maintenance panel:</strong> Use these buttons instead of remembering URL parameters. Normal dashboard loading stays read-only; maintenance runs only when you click a button. Refresh Learning Health updates health/watch/paused statuses. Rebuild Improvement Report refreshes the measured improvement report. Full Learning Maintenance runs both in one intentional admin action.';
        echo '</div>';

        if (!$data['ok']) {
            echo '<div style="margin-top:14px;padding:12px;border-radius:12px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-weight:700;">Report cache is not ready: ' . mleCllV23Html($data['reason'] ?? 'unknown') . '. Use the refresh report link after the v22/v23 file is installed.</div>';
            echo '</section>';
            return;
        }

        if (empty($rows)) {
            echo '<div style="margin-top:14px;padding:12px;border-radius:12px;background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;font-weight:700;">No report rows found yet. Click Rebuild Improvement Report to build the dashboard cache.</div>';
            echo '</section>';
            return;
        }

        $cards = array(
            array('Learning sources', $counts['total']),
            array('Active', $counts['active']),
            array('Guided', $counts['guided']),
            array('Healthy', $counts['healthy']),
            array('Watch', $counts['watch']),
            array('Paused', $counts['paused']),
            array('Improving', $counts['improving']),
            array('Stable', $counts['stable']),
            array('Insufficient', $counts['insufficient'])
        );
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-top:16px;">';
        foreach ($cards as $c) {
            echo '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:12px;">';
            echo '<div style="font-size:12px;color:#64748b;font-weight:800;text-transform:uppercase;letter-spacing:.04em;">' . mleCllV23Html($c[0]) . '</div>';
            echo '<div style="font-size:24px;font-weight:900;color:#0f172a;margin-top:4px;">' . (int)$c[1] . '</div>';
            echo '</div>';
        }
        echo '</div>';

        echo '<div style="overflow:auto;margin-top:16px;background:#fff;border:1px solid #e2e8f0;border-radius:14px;">';
        echo '<table style="width:100%;border-collapse:separate;border-spacing:0;font-size:13px;min-width:1120px;">';
        echo '<thead><tr style="background:#eff6ff;color:#1e3a8a;text-align:left;">';
        $heads = array('Lottery','Stage','Health','Improvement','Evidence','Early recall','Recent recall','Lift','Zero-hit change','Reason','Built');
        foreach ($heads as $h) { echo '<th style="padding:10px;border-bottom:1px solid #bfdbfe;font-weight:900;">' . mleCllV23Html($h) . '</th>'; }
        echo '</tr></thead><tbody>';
        foreach ($rows as $r) {
            $health = strtolower((string)($r['health_status'] ?? ''));
            $imp = strtolower((string)($r['improvement_status'] ?? ''));
            $badgeBg = '#f1f5f9'; $badgeColor = '#334155';
            if ($health === 'healthy') { $badgeBg = '#dcfce7'; $badgeColor = '#14532d'; }
            elseif ($health === 'watch') { $badgeBg = '#fef9c3'; $badgeColor = '#713f12'; }
            elseif ($health === 'paused' || $health === 'declining') { $badgeBg = '#fee2e2'; $badgeColor = '#7f1d1d'; }
            elseif ($health === 'building') { $badgeBg = '#e0f2fe'; $badgeColor = '#075985'; }
            echo '<tr>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;font-weight:900;">' . mleCllV23Html(($r['game_id'] ?? '') . ' / ' . ($r['lottery_id'] ?? '')) . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . mleCllV23Html($r['status'] ?? '') . (((int)($r['is_active'] ?? 0) === 1) ? ' <strong style="color:#166534;">Active</strong>' : '') . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;"><span style="display:inline-flex;padding:4px 9px;border-radius:999px;background:' . $badgeBg . ';color:' . $badgeColor . ';font-weight:900;">' . mleCllV23Html($health) . '</span></td>';
            $postStatus = strtolower((string)($r['post_learning_status'] ?? ''));
            $isAwaitingPostLearning = ($postStatus === 'awaiting_post_learning_scores');
            $displayImp = $isAwaitingPostLearning ? 'awaiting post-learning scores' : $imp;
            $displayReason = $isAwaitingPostLearning
                ? (string)($r['post_learning_reason'] ?? 'Awaiting enough scored draws after LottoExpert Learning activation.')
                : (string)($r['improvement_reason'] ?? '');
            $liftDisplay = $isAwaitingPostLearning ? '<span style="color:#64748b;font-weight:800;">Pending</span>' : number_format((float)($r['recall_lift_pct'] ?? 0), 2) . '%';
            $zeroDisplay = $isAwaitingPostLearning ? '<span style="color:#64748b;font-weight:800;">Pending</span>' : number_format((float)($r['zero_hit_delta'] ?? 0), 6);
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;font-weight:800;">' . mleCllV23Html($displayImp) . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . (int)($r['evidence_runs'] ?? 0) . ' runs / ' . (int)($r['evidence_draws'] ?? 0) . ' draws / all users</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . number_format((float)($r['early_recall_at_20'] ?? 0), 6) . '<br><small>' . (int)($r['early_runs'] ?? 0) . ' runs</small></td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . number_format((float)($r['recent_recall_at_20'] ?? 0), 6) . '<br><small>' . (int)($r['recent_runs'] ?? 0) . ' runs</small>' . ($isAwaitingPostLearning ? '<br><small style="color:#64748b;font-weight:800;">Post-learning pending</small>' : '') . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . $liftDisplay . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;">' . $zeroDisplay . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;max-width:260px;white-space:normal;color:#475569;">' . mleCllV23Html($displayReason) . '</td>';
            echo '<td style="padding:10px;border-bottom:1px solid #f1f5f9;color:#64748b;">' . mleCllV23Html($r['built_at'] ?? $r['generated_at'] ?? '') . '</td>';
            echo '</tr>';
        }
        echo '</tbody></table></div>';
        echo '<p style="margin:12px 0 0;color:#64748b;font-size:12px;">Improvement is intentionally conservative. Pending means LottoExpert Learning is active but there are not yet enough scored post-learning draws to calculate a fair before-vs-after lift.</p>';
        echo '</section>';
    }
}

if (isset($__mleIsCoreAdmin) && $__mleIsCoreAdmin && isset($app) && (int)$app->input->getInt('mle_learning_dashboard', 0) === 1) {
    try { mleCllV23RenderLearningDashboard($db, $app, (int)$app->input->getInt('mle_dashboard_limit', 100)); } catch (\Throwable $e) { error_log('[MLE_CLOSED_LOOP_LEARNING_V23] render failed: ' . $e->getMessage()); }
} elseif (isset($__mleIsCoreAdmin) && $__mleIsCoreAdmin && isset($app) && (int)$app->input->getInt('mle_admin_tools', 0) === 1) {
    try {
        $uri = \Joomla\CMS\Uri\Uri::getInstance();
        $du = clone $uri;
        $du->setVar('mle_learning_dashboard', '1');
        echo '<div class="mle-v23-learning-dashboard-link" style="margin:12px 0;padding:10px 12px;border:1px solid #bfdbfe;border-radius:12px;background:#eff6ff;color:#1e3a8a;font-weight:800;">Admin: <a href="' . mleCllV23Html($du->toString()) . '" style="color:#1d4ed8;text-decoration:underline;">Open LottoExpert Learning Dashboard</a></div>';
    } catch (\Throwable $ignore) {}
}

if (!function_exists('mleCllV12RebuildClosedLoopPromotions')) {
    function mleCllV12RebuildClosedLoopPromotions($db, $lotteryId = 0) {

        static $globalRan = false;
        if ($globalRan) { return array('rebuilt'=>0, 'reason'=>'already_ran_global'); }
        $globalRan = true;
        if (!mleCllV1EnsureTables($db) || !mleCllV1TableExists($db, '#__skai_best_settings') || !mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
            return array('rebuilt'=>0, 'reason'=>'no_tables');
        }
        mleCllV1EnsureBestSettingsSchema($db);
        if (function_exists('mleCllV12NormalizeClosedLoopGameIdentities')) { mleCllV12NormalizeClosedLoopGameIdentities($db, 0); }
        $rebuilt = 0;
        try {
            $cols = mleCllV1ColumnMap($db, '#__skai_best_settings');

            $q = $db->getQuery(true)
                ->select(array(
                    $db->quoteName('lottery_id'),
                    $db->quoteName('game_id'),
                    'COUNT(*) AS evidence_runs',
                    'COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS evidence_draws',
                    'COUNT(DISTINCT ' . $db->quoteName('user_id') . ') AS evidence_users',
                    'AVG(' . $db->quoteName('top20_hits') . ') AS avg_top20_hits',
                    'AVG(' . $db->quoteName('quality_score') . ') AS avg_quality_score',
                    'AVG(' . $db->quoteName('main_hits') . ') AS avg_main_hits',
                    'SUM(CASE WHEN ' . $db->quoteName('main_hits') . ' = 0 THEN 1 ELSE 0 END) AS zero_hit_count',
                    'MAX(' . $db->quoteName('updated_at') . ') AS latest_update'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' > 0')
                ->where($db->quoteName('game_id') . ' IS NOT NULL')
                ->where($db->quoteName('game_id') . ' <> ' . $db->quote(''))
                ->group($db->quoteName(array('lottery_id','game_id')))
                ->order('evidence_runs DESC, evidence_draws DESC, latest_update DESC');
            $db->setQuery($q);
            $groups = (array)$db->loadAssocList();

            foreach ($groups as $g) {
                $lid = (int)($g['lottery_id'] ?? 0);
                $gid = function_exists('mleCllV12CleanGameId') ? mleCllV12CleanGameId($g['game_id'] ?? '') : preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)($g['game_id'] ?? ''), 0, 50));
                if ($lid <= 0 || $gid === '') { continue; }

                $settings = array();
                $settingsFingerprint = '';
                try {
                    $sq = $db->getQuery(true)
                        ->select(array(
                            $db->quoteName('settings_json'),
                            $db->quoteName('settings_fingerprint'),
                            $db->quoteName('quality_score'),
                            $db->quoteName('top20_hits'),
                            $db->quoteName('updated_at')
                        ))
                        ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                        ->where($db->quoteName('lottery_id') . ' = ' . (int)$lid)
                        ->where($db->quoteName('game_id') . ' = ' . $db->quote($gid))
                        ->where($db->quoteName('settings_json') . ' IS NOT NULL')
                        ->where($db->quoteName('settings_json') . ' <> ' . $db->quote(''))
                        ->where($db->quoteName('settings_json') . ' <> ' . $db->quote('{}'))
                        ->order($db->quoteName('quality_score') . ' DESC, ' . $db->quoteName('top20_hits') . ' DESC, ' . $db->quoteName('updated_at') . ' DESC')
                        ->setLimit(1);
                    $db->setQuery($sq);
                    $sr = $db->loadAssoc();
                    if (is_array($sr) && !empty($sr['settings_json'])) {
                        $decoded = mleCllV1SafeJsonDecode($sr['settings_json']);
                        if (!empty($decoded['settings']) && is_array($decoded['settings'])) { $decoded = $decoded['settings']; }
                        if (!empty($decoded)) { $settings = $decoded; }
                        $settingsFingerprint = (string)($sr['settings_fingerprint'] ?? '');
                    }
                } catch (\Throwable $eSettings) { }

                if (empty($settings)) {
                    $settings = array(
                        'closed_loop_evidence_only' => true,
                        'lottery_id' => $lid,
                        'game_id' => $gid,
                        'note' => 'Historical closed-loop evidence exists, but no concrete settings_json payload was available for this group.'
                    );
                }
                if ($settingsFingerprint === '') { $settingsFingerprint = hash('sha256', mleCllV1SafeJsonEncode($settings) . '|' . $lid . '|' . $gid); }

                $runs = (int)($g['evidence_runs'] ?? 0);
                $draws = (int)($g['evidence_draws'] ?? 0);
                $users = (int)($g['evidence_users'] ?? 0);
                $avgTop20 = (float)($g['avg_top20_hits'] ?? 0);
                $avgQuality = (float)($g['avg_quality_score'] ?? 0);
                $avgMain = (float)($g['avg_main_hits'] ?? 0);
                $avgRecall20 = max(0.0, min(1.0, $avgTop20 / 5.0));
                $health = function_exists('mleCllV18CalculateLearningHealth') ? mleCllV18CalculateLearningHealth($db, $lid, $gid, $avgRecall20, $runs, $draws) : array('status'=>'unchecked','reason'=>'not_checked','recent_draws'=>0,'recent_runs'=>0,'recent_recall_at_20'=>0,'baseline_recall_at_20'=>$avgRecall20,'checked_at'=>date('Y-m-d H:i:s'));
                $healthStatus = strtolower((string)($health['status'] ?? 'unchecked'));
                $healthReason = (string)($health['reason'] ?? '');

                $activeRuns = 80; $activeDraws = 30;
                $guidedRuns = 100; $guidedDraws = 12; $guidedRecall = 0.35;
                $rawFullyActive = ($runs >= $activeRuns && $draws >= $activeDraws);
                $healthBlocksActive = in_array($healthStatus, array('declining','paused'), true);
                $isFullyActive = ($rawFullyActive && !$healthBlocksActive);
                $isGuided = (!$isFullyActive && $runs >= $guidedRuns && $draws >= $guidedDraws && $avgRecall20 >= $guidedRecall && $healthStatus !== 'paused');
                $status = $isFullyActive ? 'active' : ($isGuided ? 'learning_guided' : 'learning');
                $guidanceMode = $isFullyActive ? 'closed_loop_active' : ($isGuided ? 'closed_loop_learning_guided' : 'closed_loop_collecting');
                $guidanceReason = $isFullyActive ? 'active_threshold_met' : ($isGuided ? 'guided_threshold_met_runs_draws_recall' : 'collecting_more_draws');
                if ($healthBlocksActive) { $guidanceReason = 'health_guard_' . ($healthReason !== '' ? $healthReason : $healthStatus); }

                $payload = array(
                    'source' => 'mle_closed_loop_learning_v1',
                    'rebuild_marker' => '[[MLE_CLOSED_LOOP_LEARNING_V20_MANUAL_HEALTH_REFRESH]]',
                    'lottery_id' => $lid,
                    'game_id' => $gid,
                    'settings' => $settings,
                    'evidence' => array(
                        'runs' => $runs,
                        'draws' => $draws,
                        'users' => $users,
                        'avg_top20_hits' => $avgTop20,
                        'avg_quality_score' => $avgQuality,
                        'avg_main_hits' => $avgMain,
                        'zero_hit_count' => (int)($g['zero_hit_count'] ?? 0),
                        'settings_fingerprint' => $settingsFingerprint,
                        'latest_update' => (string)($g['latest_update'] ?? ''),
                        'learning_health' => $health
                    )
                );

                $now = date('Y-m-d H:i:s');
                $insertCols = array(); $insertVals = array();
                $put = function($col, $val) use (&$insertCols, &$insertVals, $cols, $db) {
                    if (empty($cols[$col])) { return; }
                    $insertCols[] = $col;
                    if (is_int($val) || is_float($val)) { $insertVals[] = (string)$val; }
                    else { $insertVals[] = $db->quote((string)$val); }
                };
                $summary = 'Closed-loop learned settings: ' . $gid . ' | runs=' . $runs . ' | draws=' . $draws . ' | all users | status=' . $status;
                $put('user_id', 0);
                $put('lottery_id', $lid);
                $put('source_lottery_id', $lid);
                $put('game_id', $gid);
                $put('source_mode', 'mle_closed_loop_learning_v1');
                $put('status', $status);
                $put('is_active', $isFullyActive ? 1 : 0);
                $put('parameter_version', 'mle_cll_v18_' . gmdate('YmdHis'));
                $put('settings_json', mleCllV1SafeJsonEncode($settings));
                $put('settings_summary', $summary);
                $put('notes', 'Generated by [[MLE_CLOSED_LOOP_LEARNING_V20_MANUAL_HEALTH_REFRESH]] from canonical full-hive evidence with recent-performance safety checks.');
                $put('parameter_json', mleCllV1SafeJsonEncode($payload));
                $put('best_params_json', mleCllV1SafeJsonEncode($settings));
                $put('score', $avgQuality);
                $put('best_score', $avgQuality);
                $put('avg_recall_at_20', $avgRecall20);
                $put('evidence_runs', $runs);
                $put('evidence_draws', $draws);
                $put('settings_fingerprint', $settingsFingerprint);
                $put('guidance_mode', $guidanceMode);
                $put('guidance_reason', $guidanceReason);
                $put('guidance_score', $avgQuality);
                $put('learning_health_status', $healthStatus);
                $put('learning_health_reason', substr($healthReason, 0, 250));
                $put('learning_health_recent_draws', (int)($health['recent_draws'] ?? 0));
                $put('learning_health_recent_runs', (int)($health['recent_runs'] ?? 0));
                $put('learning_health_recent_recall_at_20', (float)($health['recent_recall_at_20'] ?? 0));
                $put('learning_health_baseline_recall_at_20', (float)($health['baseline_recall_at_20'] ?? $avgRecall20));
                $put('learning_health_checked_at', (string)($health['checked_at'] ?? $now));
                $put('promoted_at', $now);
                $put('created_at', $now);
                $put('updated_at', $now);
                if (empty($insertCols)) { continue; }
                $iq = $db->getQuery(true)
                    ->insert($db->quoteName('#__skai_best_settings'))
                    ->columns($db->quoteName($insertCols))
                    ->values(implode(',', $insertVals));

                $updateParts = array();
                foreach ($insertCols as $ucol) {
                    if (in_array($ucol, array('user_id', 'lottery_id', 'created_at'), true)) { continue; }
                    $updateParts[] = $db->quoteName($ucol) . ' = VALUES(' . $db->quoteName($ucol) . ')';
                }
                if (empty($updateParts)) { continue; }
                $sql = (string)$iq . ' ON DUPLICATE KEY UPDATE ' . implode(', ', $updateParts);
                $db->setQuery($sql);
                $db->execute();
                $rebuilt++;
            }

            if (!empty($cols['source_mode']) && !empty($cols['status']) && !empty($cols['is_active'])) {
                $uq = $db->getQuery(true)
                    ->update($db->quoteName('#__skai_best_settings'))
                    ->set($db->quoteName('is_active') . ' = CASE WHEN ' . $db->quoteName('status') . ' = ' . $db->quote('active') . ' THEN 1 ELSE 0 END')
                    ->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1'));
                $db->setQuery($uq);
                $db->execute();
            }

            error_log('[MLE_CLOSED_LOOP_LEARNING_V15] hard global promotion rebuilt=' . $rebuilt);
            return array('rebuilt'=>$rebuilt, 'reason'=>'ok');
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V15] hard global promotion rebuild failed: ' . $e->getMessage());
            return array('rebuilt'=>$rebuilt, 'reason'=>'error');
        }
    }
}

if (!function_exists('mleCllV11BackfillGlobalScoredEvidence')) {
    function mleCllV11BackfillGlobalScoredEvidence($db, $lotteryId = 0, $gameId = '', $limit = 2500) {
        static $ran = array();
        $lotteryId = (int)$lotteryId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        $key = $lotteryId . '|' . $gameId;
        if (isset($ran[$key])) { return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'already_ran'); }
        $ran[$key] = true;
        $limit = max(50, min(5000, (int)$limit));
        if (!mleCllV1EnsureTables($db)) { return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'no_tables'); }
        if (!mleCllV1TableExists($db, '#__user_saved_numbers')) { return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'no_saved_table'); }
        if (!mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) { return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'no_event_table'); }
        try {
            $cols = mleCllV1ColumnMap($db, '#__user_saved_numbers');
            foreach (array('id','user_id','lottery_id','evaluation_status','actual_draw_date','actual_main_numbers') as $required) {
                if (empty($cols[$required])) { return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'missing_col_' . $required); }
            }
            $q = $db->getQuery(true)
                ->select('s.*')
                ->from($db->quoteName('#__user_saved_numbers', 's'))
                ->join('LEFT', $db->quoteName('#__skai_closed_loop_learning_events', 'e') . ' ON e.' . $db->quoteName('saved_number_id') . ' = s.' . $db->quoteName('id') . ' AND e.' . $db->quoteName('draw_date') . ' = s.' . $db->quoteName('actual_draw_date'))
                ->where('e.' . $db->quoteName('id') . ' IS NULL')
                ->where('s.' . $db->quoteName('evaluation_status') . ' = ' . $db->quote('scored'))
                ->where('s.' . $db->quoteName('actual_draw_date') . ' IS NOT NULL')
                ->where('s.' . $db->quoteName('actual_draw_date') . " <> '0000-00-00'")
                ->where('TRIM(s.' . $db->quoteName('actual_main_numbers') . ") <> ''");
            if ($lotteryId > 0) {
                $or = array('s.' . $db->quoteName('lottery_id') . ' = ' . (int)$lotteryId);
                if (!empty($cols['target_lottery_id'])) { $or[] = 's.' . $db->quoteName('target_lottery_id') . ' = ' . (int)$lotteryId; }
                $q->where('(' . implode(' OR ', $or) . ')');
            }
            if ($gameId !== '') {
                $or = array();
                if (!empty($cols['game_id'])) { $or[] = 's.' . $db->quoteName('game_id') . ' = ' . $db->quote($gameId); }
                if (!empty($cols['target_game_id'])) { $or[] = 's.' . $db->quoteName('target_game_id') . ' = ' . $db->quote($gameId); }
                if (!empty($or)) { $q->where('(' . implode(' OR ', $or) . ')'); }
            }
            $q->order('s.' . $db->quoteName('actual_draw_date') . ' DESC, s.' . $db->quoteName('id') . ' DESC')->setLimit($limit);
            $db->setQuery($q);
            $rows = (array)$db->loadAssocList();
            $processed = 0; $captured = 0; $skipped = 0; $games = array();
            foreach ($rows as $row) {
                $processed++;
                if (!is_array($row) || empty($row['id'])) { $skipped++; continue; }
                $rowLotteryId = (int)($row['lottery_id'] ?? 0);
                if ($rowLotteryId <= 0 && !empty($row['target_lottery_id'])) { $rowLotteryId = (int)$row['target_lottery_id']; }
                $rowGameId = function_exists('mleCllV12CanonicalGameIdFromSavedRow')
                    ? mleCllV12CanonicalGameIdFromSavedRow($db, $row, $rowLotteryId, '')
                    : '';
                if ($rowGameId === '') {
                    if (!empty($row['target_game_id'])) { $rowGameId = (string)$row['target_game_id']; }
                    elseif (!empty($row['game_id'])) { $rowGameId = (string)$row['game_id']; }
                    else { $rowGameId = 'lottery_' . $rowLotteryId; }
                }
                $drawDate = substr((string)($row['actual_draw_date'] ?? ''), 0, 10);
                $actualMain = mleCllV11ParseNumbers($row['actual_main_numbers'] ?? '');
                $actualExtra = mleCllV11ParseNumbers($row['actual_extra_numbers'] ?? '');
                $predMain = mleCllV11FirstNumberListFromRow($row, array(
                    'ranked_main_numbers_json','regular_main_numbers_json','daily_top_picks_json','daily_primary_prediction_json','main_display_json','canonical_main_display','main_numbers'
                ));
                $predExtra = mleCllV11FirstNumberListFromRow($row, array(
                    'ranked_extra_numbers_json','regular_extra_numbers_json','extra_display_json','canonical_extra_display','extra_ball_numbers','daily_bonus_digits_json'
                ));
                if ($rowLotteryId <= 0 || $drawDate === '' || empty($actualMain) || empty($predMain)) { $skipped++; continue; }
                $top10 = count(array_intersect(array_slice($predMain, 0, 10), $actualMain));
                $top20 = count(array_intersect(array_slice($predMain, 0, 20), $actualMain));
                $mainHits = isset($row['main_hits_count']) ? (int)$row['main_hits_count'] : count(array_intersect($predMain, $actualMain));
                $extraHits = isset($row['extra_hits_count']) ? (int)$row['extra_hits_count'] : count(array_intersect($predExtra, $actualExtra));
                $quality = isset($row['learning_score']) ? (float)$row['learning_score'] : 0.0;
                if ($quality <= 0.0) { $quality = ($mainHits * 10.0) + ($top20 * 1.5) + ($top10 * 2.5); }
                $settings = mleCllV1ExtractSettingsFromSavedRow($row, array());
                $vrow = array(
                    'predicted' => $predMain,
                    'predicted_extra' => $predExtra,
                    'actual' => $actualMain,
                    'actual_extra' => $actualExtra,
                    'main_hits' => $mainHits,
                    'extra_hits' => $extraHits
                );
                $metrics = array('top10_hits'=>$top10, 'top20_hits'=>$top20, 'weighted_score'=>$quality, 'missing_count'=>max(0, count($actualMain) - $mainHits));
                $lineage = array('run_uuid'=>(string)($row['run_uuid'] ?? ''), 'batch_uuid'=>(string)($row['batch_uuid'] ?? ''), 'source'=>'mle_v11_full_hive_backfill');
                $ok = mleCllV1CaptureScoredRun($db, (int)($row['user_id'] ?? 0), $rowLotteryId, $rowGameId, $drawDate, (int)$row['id'], $row, $vrow, $settings, $metrics, $lineage, false);
                if ($ok) { $captured++; $games[$rowLotteryId . '|' . $rowGameId] = array($rowLotteryId, $rowGameId); }
                else { $skipped++; }
            }
            foreach ($games as $g) { mleCllV1MaybePromoteSettings($db, (int)$g[0], (string)$g[1]); }
            if (function_exists('mleCllV12RebuildClosedLoopPromotions')) { mleCllV12RebuildClosedLoopPromotions($db, $lotteryId > 0 ? $lotteryId : 0); }
            if ($captured > 0) { error_log('[MLE_CLOSED_LOOP_LEARNING_V15] backfill captured=' . $captured . ' processed=' . $processed . ' scope=' . $key); }
            return array('processed'=>$processed, 'captured'=>$captured, 'skipped'=>$skipped, 'reason'=>'ok');
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V15] backfill failed: ' . $e->getMessage());
            return array('processed'=>0, 'captured'=>0, 'skipped'=>0, 'reason'=>'error');
        }
    }
}

if (!function_exists('mleCllV1MaybePromoteSettings')) {
    function mleCllV1MaybePromoteSettings($db, $lotteryId, $gameId) {
        $lotteryId = (int)$lotteryId;
        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        if (function_exists('mleCllV12CanonicalGameIdFromSavedRow')) {
            $gameId = mleCllV12CanonicalGameIdFromSavedRow($db, array(), $lotteryId, $gameId);
        }
        if ($gameId === '') { return false; }
        if (!mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) { return false; }
        if (!mleCllV1TableExists($db, '#__skai_best_settings')) { return false; }
        mleCllV1EnsureBestSettingsSchema($db);
        try {
            $q = $db->getQuery(true)
                ->select(array(
                    $db->quoteName('settings_fingerprint'),
                    'COUNT(*) AS run_count',
                    'COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS draw_count',
                    'AVG(' . $db->quoteName('quality_score') . ') AS avg_quality',
                    'AVG(' . $db->quoteName('main_hits') . ') AS avg_main_hits',
                    'SUM(CASE WHEN ' . $db->quoteName('main_hits') . ' = 0 THEN 1 ELSE 0 END) AS zero_hit_count',
                    'MAX(' . $db->quoteName('settings_json') . ') AS settings_json',
                    'MAX(' . $db->quoteName('updated_at') . ') AS last_seen'
                ))
                ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)
                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                ->group($db->quoteName('settings_fingerprint'))
                ->having('run_count >= 3')
                ->order('avg_quality DESC, avg_main_hits DESC, draw_count DESC')
                ->setLimit(1);
            $db->setQuery($q);
            $best = $db->loadAssoc();
            if (!is_array($best) || empty($best['settings_json'])) { return false; }
            $eQ = $db->getQuery(true)->select('COUNT(*) AS runs, COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS draws')->from($db->quoteName('#__skai_closed_loop_learning_events'))->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId));
            $db->setQuery($eQ); $e = $db->loadAssoc();
            $totalRuns = (int)($e['runs'] ?? 0); $totalDraws = (int)($e['draws'] ?? 0);

            $avgRecall20 = max(0.0, min(1.0, ((float)($best['avg_main_hits'] ?? 0)) / 5.0));
            $minRuns = 9; $minDraws = 3;
            $activeRuns = 80; $activeDraws = 30;
            $guidedRuns = 100; $guidedDraws = 12; $guidedRecall = 0.35;
            $isFullyActive = ($totalRuns >= $activeRuns && $totalDraws >= $activeDraws);
            $isGuided = (!$isFullyActive && $totalRuns >= $guidedRuns && $totalDraws >= $guidedDraws && $avgRecall20 >= $guidedRecall);
            $status = $isFullyActive ? 'active' : ($isGuided ? 'learning_guided' : 'learning');
            $isPromotable = ($totalRuns >= $minRuns && $totalDraws >= $minDraws);
            if (!$isPromotable) { return false; }
            $settings = mleCllV1SafeJsonDecode($best['settings_json']);
            if (empty($settings)) { return false; }
            $payload = array(
                'source' => 'mle_closed_loop_learning_v1',
                'lottery_id' => $lotteryId,
                'game_id' => $gameId,
                'settings' => $settings,
                'caps' => isset($settings['caps']) && is_array($settings['caps']) ? $settings['caps'] : array(),
                'evidence' => array(
                    'runs' => $totalRuns,
                    'draws' => $totalDraws,
                    'candidate_runs' => (int)($best['run_count'] ?? 0),
                    'candidate_draws' => (int)($best['draw_count'] ?? 0),
                    'avg_quality' => (float)($best['avg_quality'] ?? 0),
                    'avg_main_hits' => (float)($best['avg_main_hits'] ?? 0),
                    'zero_hit_count' => (int)($best['zero_hit_count'] ?? 0),
                    'settings_fingerprint' => (string)($best['settings_fingerprint'] ?? '')
                )
            );
            $now = date('Y-m-d H:i:s');
            $cols = mleCllV1ColumnMap($db, '#__skai_best_settings');
            try {
                if (!empty($cols['is_active']) && !empty($cols['game_id']) && !empty($cols['source_mode'])) {
                    $db->setQuery($db->getQuery(true)->update($db->quoteName('#__skai_best_settings'))->set($db->quoteName('is_active') . ' = 0')->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId)->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1')));
                    $db->execute();
                }
            } catch (\Throwable $e1) { }
            $insertCols = array(); $insertVals = array();
            $put = function($col, $val) use (&$insertCols, &$insertVals, $cols, $db) { if (!empty($cols[$col])) { $insertCols[] = $col; $insertVals[] = is_int($val) || is_float($val) ? (string)$val : $db->quote((string)$val); } };
            $summary = 'Closed-loop learned settings: ' . $gameId . ' | runs=' . $totalRuns . ' | draws=' . $totalDraws . ' | avg_hits=' . round((float)($best['avg_main_hits'] ?? 0), 3) . ' | status=' . $status;
            $put('user_id', 0);
            $put('lottery_id', (int)$lotteryId);
            $put('source_lottery_id', (int)$lotteryId);
            $put('game_id', $gameId);
            $put('parameter_version', 'mle_cll_v5_' . gmdate('YmdHis'));
            $put('settings_json', mleCllV1SafeJsonEncode($settings));
            $put('settings_summary', $summary);
            $put('notes', 'Generated by [[MLE_CLOSED_LOOP_LEARNING_V7]] from scored prediction evidence. Active rows are fully validated; learning_guided rows may guide runs with honest labeling.');
            $put('parameter_json', mleCllV1SafeJsonEncode($payload));
            $put('best_params_json', mleCllV1SafeJsonEncode($settings));
            $put('score', (float)($best['avg_quality'] ?? 0));
            $put('best_score', (float)($best['avg_quality'] ?? 0));
            $put('avg_recall_at_20', $avgRecall20);
            $put('evidence_runs', (int)$totalRuns);
            $put('evidence_draws', (int)$totalDraws);
            $put('settings_fingerprint', (string)($best['settings_fingerprint'] ?? ''));
            $put('source_mode', 'mle_closed_loop_learning_v1');
            $put('is_active', $isFullyActive ? 1 : 0);
            $put('status', $status);
            $put('guidance_mode', $isFullyActive ? 'closed_loop_active' : ($isGuided ? 'closed_loop_learning_guided' : 'closed_loop_collecting'));
            $put('guidance_reason', $isFullyActive ? 'active_threshold_met' : ($isGuided ? 'guided_threshold_met_runs_draws_recall' : 'collecting_more_draws'));
            $put('guidance_score', (float)($best['avg_quality'] ?? 0));
            $put('promoted_at', $now);
            $put('created_at', $now);
            $put('updated_at', $now);
            if (empty($insertCols)) { return false; }
            // [[MLE_V76_CLOSED_LOOP_BEST_SETTINGS_UPSERT]]
            // The table #__skai_best_settings has a unique key on user_id + lottery_id.
            // Shared/global learning uses user_id=0, so repeated promotion for the same
            // lottery must update the existing row instead of trying to insert a duplicate.
            // This preserves learning and prevents Duplicate entry '0-x' log flooding.
            $iq = $db->getQuery(true)
                ->insert($db->quoteName('#__skai_best_settings'))
                ->columns($db->quoteName($insertCols))
                ->values(implode(',', $insertVals));

            $updateParts = array();

            foreach ($insertCols as $upsertCol) {
                $upsertCol = (string) $upsertCol;

                // Do not update the unique identity columns.
                if ($upsertCol === 'user_id' || $upsertCol === 'lottery_id') {
                    continue;
                }

                // Preserve the original created timestamp when updating an existing row.
                if ($upsertCol === 'created_at') {
                    continue;
                }

                $updateParts[] = $db->quoteName($upsertCol) . ' = VALUES(' . $db->quoteName($upsertCol) . ')';
            }

            if (!empty($cols['updated_at'])) {
                $updateParts[] = $db->quoteName('updated_at') . ' = ' . $db->quote($now);
            }

            if (!empty($updateParts)) {
                $iq = (string) $iq . ' ON DUPLICATE KEY UPDATE ' . implode(', ', $updateParts);
            }

            $db->setQuery($iq);
            $db->execute();

            // [[MLE_V77_QUIET_SUCCESS_LOG]] Success logging disabled to prevent PHP error-log flooding during dashboard loads.
            // error_log('[MLE_CLOSED_LOOP_LEARNING_V76] promoted settings upsert game_id=' . $gameId . ' runs=' . $totalRuns . ' draws=' . $totalDraws . ' status=' . $status);
            return true;
        } catch (\Throwable $e) {
            error_log('[MLE_CLOSED_LOOP_LEARNING_V1] promotion failed game_id=' . $gameId . ' msg=' . $e->getMessage());
            return false;
        }
    }
}

if (!function_exists('mleCllV7LearningBadgeForLottery')) {

if (!function_exists('mleCllV9FriendlyLearningSourceProof')) {
    function mleCllV9FriendlyLearningSourceProof($run, $settings = null) {
        $hay = '';
        if (is_array($run)) {
            foreach (array('settings_source','learning_source','source_priority','source_label','source_mode','guidance_mode') as $k) {
                if (isset($run[$k]) && !is_array($run[$k]) && !is_object($run[$k])) { $hay .= ' ' . (string)$run[$k]; }
            }
        }
        if (is_array($settings)) {
            foreach (array('settings_source','learning_source','source_priority','source_label','source_mode','guidance_mode') as $k) {
                if (isset($settings[$k]) && !is_array($settings[$k]) && !is_object($settings[$k])) { $hay .= ' ' . (string)$settings[$k]; }
            }
            if (isset($settings['hive_settings_source']) && is_array($settings['hive_settings_source'])) {
                foreach ($settings['hive_settings_source'] as $v) {
                    if (!is_array($v) && !is_object($v)) { $hay .= ' ' . (string)$v; }
                }
            }
        }
        $hay = strtolower($hay);
        if ($hay !== '' && (strpos($hay, 'closed_loop') !== false || strpos($hay, 'mle_closed_loop_learning') !== false || strpos($hay, 'closed-loop') !== false)) {
            return 'Settings source: LottoExpert Learning';
        }
        return '';
    }
}

function mleCllV7LearningBadgeForLottery($db, $lotteryId) {

        $lotteryId = (int)$lotteryId;
        $out = array(
            'state' => 'pending',
            'label' => 'Learning Pending',
            'title' => 'LottoExpert will begin learning after scored results are available for this lottery.',
            'admin_detail' => '',
            'has_learning' => false,
        );
        if ($lotteryId <= 0) { return $out; }
        try {
            if (function_exists('mleCllV1EnsureBestSettingsSchema')) { mleCllV1EnsureBestSettingsSchema($db); }
            if (function_exists('mleCllV6BackfillGuidanceColumns')) { mleCllV6BackfillGuidanceColumns($db); }
            if (function_exists('mleCllV18RefreshLearningHealth')) {

                mleCllV18RefreshLearningHealth($db, $lotteryId, 8);
                mleCllV18RefreshLearningHealth($db, 0, 3);
            }

            if (function_exists('mleCllV1TableExists') && mleCllV1TableExists($db, '#__skai_best_settings')) {
                $cols = function_exists('mleCllV1ColumnMap') ? mleCllV1ColumnMap($db, '#__skai_best_settings') : array();
                if (!empty($cols['lottery_id'])) {
                    $q = $db->getQuery(true)
                        ->select('*')
                        ->from($db->quoteName('#__skai_best_settings'))
                        ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId);
                    if (!empty($cols['source_mode'])) { $q->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1')); }
                    $order = array();
                    if (!empty($cols['is_active'])) { $order[] = $db->quoteName('is_active') . ' DESC'; }
                    if (!empty($cols['status'])) { $order[] = "CASE WHEN " . $db->quoteName('status') . " = 'active' THEN 4 WHEN " . $db->quoteName('status') . " = 'learning_guided' THEN 3 WHEN " . $db->quoteName('status') . " = 'learning' THEN 2 ELSE 1 END DESC"; }
                    if (!empty($cols['evidence_draws'])) { $order[] = $db->quoteName('evidence_draws') . ' DESC'; }
                    if (!empty($cols['evidence_runs'])) { $order[] = $db->quoteName('evidence_runs') . ' DESC'; }
                    if (!empty($cols['guidance_score'])) { $order[] = $db->quoteName('guidance_score') . ' DESC'; }
                    $order[] = (!empty($cols['updated_at']) ? $db->quoteName('updated_at') : $db->quoteName('id')) . ' DESC';
                    $q->order(implode(', ', $order))->setLimit(1);
                    $db->setQuery($q);
                    $row = $db->loadAssoc();
                    if (is_array($row) && !empty($row)) {
                        $status = strtolower((string)($row['status'] ?? ''));
                        $guidance = strtolower((string)($row['guidance_mode'] ?? ''));
                        $healthStatus = strtolower((string)($row['learning_health_status'] ?? ''));
                        $runs = (int)($row['evidence_runs'] ?? 0);
                        $draws = (int)($row['evidence_draws'] ?? 0);
                        $out['state'] = 'active';
                        $out['label'] = in_array($healthStatus, array('declining','paused'), true) ? 'Learning Building' : 'Learning Active';
                        $out['title'] = in_array($healthStatus, array('declining','paused'), true) ? 'LottoExpert is still learning from scored results and is using a more cautious learning profile.' : 'LottoExpert is learning from scored results for this lottery.';
                        $out['has_learning'] = true;
                        $healthDetail = $healthStatus !== '' ? (' | health=' . $healthStatus) : '';
                        $out['admin_detail'] = trim(($guidance ?: $status) . ' | runs=' . $runs . ' | draws=' . $draws . $healthDetail);
                        return $out;
                    }
                }
            }

            if (function_exists('mleCllV1TableExists') && mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
                $q = $db->getQuery(true)
                    ->select('COUNT(*) AS runs, COUNT(DISTINCT ' . $db->quoteName('draw_date') . ') AS draws')
                    ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                    ->where($db->quoteName('lottery_id') . ' = ' . (int)$lotteryId);
                $db->setQuery($q);
                $ev = $db->loadAssoc();
                $runs = (int)($ev['runs'] ?? 0);
                $draws = (int)($ev['draws'] ?? 0);
                if ($runs > 0) {
                    $out['state'] = 'active';
                    $out['label'] = 'Learning Active';
                    $out['title'] = 'LottoExpert is learning from scored results for this lottery.';
                    $out['has_learning'] = true;
                    $out['admin_detail'] = 'captured prediction history | runs=' . $runs . ' | draws=' . $draws;
                    return $out;
                }
            }
        } catch (\Throwable $e) {
            $out['state'] = 'pending';
            $out['label'] = 'Learning Pending';
            $out['title'] = 'Learning status will update after scored results are available.';
            $out['admin_detail'] = 'status unavailable';
        }
        return $out;
    }
}

if (!function_exists('mleCllV1LoadPromotedSettingsForBatch')) {
    function mleCllV1LoadPromotedSettingsForBatch($db, $gameId) {

        $gameId = preg_replace('/[^a-zA-Z0-9_\-.]/', '', substr((string)$gameId, 0, 50));
        if ($gameId === '' || !mleCllV1TableExists($db, '#__skai_best_settings')) { return array('found'=>false); }
        mleCllV1EnsureBestSettingsSchema($db);
        if (function_exists('mleCllV18RefreshLearningHealth')) { mleCllV18RefreshLearningHealth($db, 0, 3); }

        try {
            $cols = mleCllV1ColumnMap($db, '#__skai_best_settings');
            if (empty($cols['game_id'])) { return array('found'=>false); }
            $q = $db->getQuery(true)->select('*')->from($db->quoteName('#__skai_best_settings'));
            $q->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId));
            if (!empty($cols['lottery_id'])) { $q->where($db->quoteName('lottery_id') . ' > 0'); }
            if (!empty($cols['settings_fingerprint'])) { $q->where('TRIM(COALESCE(' . $db->quoteName('settings_fingerprint') . ',' . $db->quote('') . ')) <> ' . $db->quote('')); }
            if (!empty($cols['source_mode'])) { $q->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1')); }
            $order = array();
            if (!empty($cols['is_active'])) { $order[] = $db->quoteName('is_active') . ' DESC'; }
            if (!empty($cols['status'])) { $order[] = "CASE WHEN " . $db->quoteName('status') . " = 'active' THEN 3 WHEN " . $db->quoteName('status') . " = 'learning_guided' THEN 2 ELSE 1 END DESC"; }
            if (!empty($cols['evidence_draws'])) { $order[] = $db->quoteName('evidence_draws') . ' DESC'; }
            if (!empty($cols['evidence_runs'])) { $order[] = $db->quoteName('evidence_runs') . ' DESC'; }
            if (!empty($cols['score'])) { $order[] = $db->quoteName('score') . ' DESC'; }
            $order[] = (!empty($cols['updated_at']) ? $db->quoteName('updated_at') : $db->quoteName('id')) . ' DESC';
            $q->order(implode(', ', $order))->setLimit(10);
            $db->setQuery($q); $rows = (array)$db->loadAssocList();
            foreach ($rows as $row) {
                if (!is_array($row) || empty($row)) { continue; }
                $runs = (int)($row['evidence_runs'] ?? 0);
                $draws = (int)($row['evidence_draws'] ?? 0);
                $recall = (float)($row['avg_recall_at_20'] ?? 0);
                $status = strtolower((string)($row['status'] ?? 'learning'));
                $healthStatus = strtolower((string)($row['learning_health_status'] ?? ''));
                $healthPaused = in_array($healthStatus, array('paused'), true);
                $healthDeclining = in_array($healthStatus, array('declining'), true);
                $active = (((int)($row['is_active'] ?? 0) === 1) || $status === 'active') && !$healthPaused && !$healthDeclining;
                $guided = (!$active && !$healthPaused && $runs >= 100 && $draws >= 12 && $recall >= 0.35);
                if (!$active && !$guided) { continue; }
                $settings = array();
                foreach (array('best_params_json','settings_json','parameter_json') as $k) {
                    if (!empty($row[$k])) {
                        $settings = mleCllV1SafeJsonDecode($row[$k]);
                        if (!empty($settings['settings']) && is_array($settings['settings'])) { $settings = $settings['settings']; }
                        if (!empty($settings)) { break; }
                    }
                }
                if (empty($settings)) { continue; }
                $tier = $active ? 'active' : 'learning_guided';
                return array(
                    'found'=>true,
                    'settings'=>$settings,
                    'row'=>$row,
                    'confidence'=>$tier,
                    'guidance_tier'=>$tier,
                    'source_priority'=>$active ? 'closed_loop_active' : 'closed_loop_learning_guided',
                    'source_label'=>$active ? 'Closed-loop active learned settings' : 'Closed-loop learning-guided settings',
                    'evidence_count'=>$runs,
                    'evidence_draws'=>$draws,
                    'avg_recall_at_20'=>$recall,
                    'learning_health_status'=>$healthStatus,
                    'hive_settings_fingerprint'=>hash('sha256', mleCllV1SafeJsonEncode(mleCllV1CanonicalSettings($settings)))
                );
            }
            return array('found'=>false);
        } catch (\Throwable $e) { return array('found'=>false); }
    }
}

if (!function_exists('mleAdvisoryPersistCompletedVisualRuns')) {
    function mleAdvisoryPersistCompletedVisualRuns($db, $userId, $lotteryId, $lotteryName, array $visualRows, array $savedById) {
        $result = array(
            'attempted' => 0,
            'saved' => 0,
            'skipped' => 0,
            'errors' => array(),
            'checked_at' => date('Y-m-d H:i:s')
        );
        $userId = (int)$userId;
        $lotteryId = (int)$lotteryId;
        if ($userId <= 0 || $lotteryId <= 0 || !function_exists('skaiUpsertPerformanceRecord')) {
            return $result;
        }

        $allRows = array();
        foreach (array('recent', 'older', 'upcoming') as $bucket) {
            foreach ((array)($visualRows[$bucket] ?? array()) as $row) {
                if (!is_array($row)) {
                    continue;
                }

                if ($bucket === 'upcoming') {
                    $hasOfficialForPendingTarget = !empty($row['actual_official_found'])
                        && (!empty($row['actual']) || !empty($row['actual_extra']));

                    if (!$hasOfficialForPendingTarget) {
                        continue;
                    }

                    $row['completed'] = true;
                    if (empty($row['draw_date']) && !empty($row['target_draw_date'])) {
                        $row['draw_date'] = $row['target_draw_date'];
                    }
                }

                $allRows[] = $row;
            }
        }
        $seen = array();
        foreach ($allRows as $vrow) {
            if (empty($vrow['completed'])) { $result['skipped']++; continue; }
            $savedId = (int)($vrow['saved_id'] ?? $vrow['source_record_id'] ?? 0);
            if ($savedId <= 0) { $result['skipped']++; continue; }
            $drawDate = trim((string)($vrow['draw_date'] ?? ''));
            if ($drawDate === '' || strncmp($drawDate, '0000-00-00', 10) === 0) { $result['skipped']++; continue; }
            $drawTs = strtotime($drawDate);
            if ($drawTs === false || $drawTs <= 0) { $result['skipped']++; continue; }
            $drawDate = date('Y-m-d', $drawTs);
            $key = $savedId . '|' . $drawDate;
            if (isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $predMain = array_values(array_map('intval', (array)($vrow['predicted'] ?? array())));
            $actualMain = array_values(array_map('intval', (array)($vrow['actual'] ?? array())));
            if (empty($predMain) || empty($actualMain)) { $result['skipped']++; continue; }
            $savedRow = isset($savedById[$savedId]) && is_array($savedById[$savedId]) ? $savedById[$savedId] : array();
            $settings = array();
            foreach (array('settings_json','settings','params_json','params') as $jsonKey) {
                if (!empty($savedRow[$jsonKey])) {
                    $decoded = json_decode((string)$savedRow[$jsonKey], true);
                    if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) { $settings = $decoded; break; }
                }
            }
            $targetMeta = function_exists('mylottoexpertResolvePredictionTargetMeta') ? mylottoexpertResolvePredictionTargetMeta($savedRow) : array();
            $lineageMeta = function_exists('mylottoexpertResolveRunLineageMeta') ? mylottoexpertResolveRunLineageMeta($savedRow) : array();
            $metrics = function_exists('skaiCalcWinningRankMetrics') ? skaiCalcWinningRankMetrics($predMain, $actualMain) : array(
                'avg_rank'=>null,'best_rank'=>null,'worst_rank'=>null,'median_rank'=>null,
                'weighted_score'=>0.0,'top10_hits'=>0,'top20_hits'=>0,'top30_hits'=>0,'top50_hits'=>0,'missing_count'=>0
            );
            $source = (string)($savedRow['source'] ?? $vrow['source'] ?? '');
            $methodKey = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey') ? mleAdvisoryResolveSavedEvidenceMethodKey($savedRow) : $source;
            $labels = function_exists('mleAdvisoryAnalysisMethodLabels') ? mleAdvisoryAnalysisMethodLabels($methodKey) : array('', '');
            $runDate = (string)($savedRow['generated_at'] ?? $savedRow['date_saved'] ?? '');
            $blendInfo = function_exists('mylottoexpertBuildBlendDisplayInfo') ? mylottoexpertBuildBlendDisplayInfo($savedRow, $settings) : array('ai'=>null,'skip'=>null,'strategy_label'=>'');
            $data = array(
                'lottery_id' => $lotteryId,
                'lottery_name' => (string)$lotteryName,
                'draw_date' => $drawDate,
                'run_date' => $runDate,
                'run_id' => $savedId,
                'run_uuid' => (string)($lineageMeta['run_uuid'] ?? ''),
                'snapshot_run_uuid' => (string)($lineageMeta['snapshot_run_uuid'] ?? ''),
                'run_identity_key' => (string)($lineageMeta['run_identity_key'] ?? ('rowid:' . $savedId)),
                'prediction_target_id' => (string)($targetMeta['prediction_target_id'] ?? ''),
                'prediction_target_key' => (string)($targetMeta['prediction_target_key'] ?? ''),
                'target_game_id' => (string)($targetMeta['target_game_id'] ?? ''),
                'target_lottery_id' => (int)($targetMeta['target_lottery_id'] ?? $lotteryId),
                'target_draw_date' => (string)($targetMeta['target_draw_date'] ?? $drawDate),
                'target_draw_at' => (string)($targetMeta['target_draw_at'] ?? ''),
                'target_draw_session' => (string)($targetMeta['target_draw_session'] ?? ''),
                'target_timezone_id' => (string)($targetMeta['target_timezone_id'] ?? ''),
                'target_prediction_family' => (string)($targetMeta['target_prediction_family'] ?? ''),
                'target_prediction_type' => (string)($targetMeta['target_prediction_type'] ?? ''),
                'source' => $source,
                'analysis_method_key' => (string)$methodKey,
                'analysis_engine_label' => (string)($labels[0] ?? ''),
                'analysis_track_label' => (string)($labels[1] ?? ''),
                'actual_numbers' => $actualMain,
                'predicted_ranking' => $predMain,
                'avg_winning_rank' => $metrics['avg_rank'] ?? null,
                'best_winning_rank' => $metrics['best_rank'] ?? null,
                'worst_winning_rank' => $metrics['worst_rank'] ?? null,
                'median_winning_rank' => $metrics['median_rank'] ?? null,
                'weighted_quality_score' => $metrics['weighted_score'] ?? 0.0,
                'top10_hits' => (int)($metrics['top10_hits'] ?? 0),
                'top20_hits' => (int)($metrics['top20_hits'] ?? 0),
                'top30_hits' => (int)($metrics['top30_hits'] ?? 0),
                'top50_hits' => (int)($metrics['top50_hits'] ?? 0),
                'missing_hits_count' => (int)($metrics['missing_count'] ?? 0),
                'combo_hit_summary' => array('hits_main'=>(int)($vrow['main_hits'] ?? 0),'hits_extra'=>(int)($vrow['extra_hits'] ?? 0)),
                'tail_enabled' => 0,
                'tail_active' => 0,
                'tail_promoted_count' => 0,
                'tail_promoted_hit_count' => 0,
                'calibration_enabled' => 0,
                'calibration_active' => 0,
                'shared_learning_enabled' => 0,
                'pairwise_enabled' => 0,
                'gibbs_enabled' => 0,
                'live_tuning_enabled' => 0,
                'confidence_level' => 'scored',
                'trend_bucket' => 'auto_scored_exact_draw',
                'notes' => array(
                    'auto_scored_from_visual_row' => true,
                    'scoring_rule' => 'exact_draw_saved_prediction_only',
                    'actual_source' => (string)($vrow['actual_source'] ?? 'official_draw_result'),
                    'run_ai_pct' => $blendInfo['ai'] ?? null,
                    'run_skip_pct' => $blendInfo['skip'] ?? null,
                    'run_strategy_family' => $blendInfo['strategy_label'] ?? '',
                ),
            );
            $result['attempted']++;
            try {
                if (skaiUpsertPerformanceRecord($db, $userId, $data)) {
                    $result['saved']++;

                    try {
                        $colsRaw = $db->getTableColumns('#__user_saved_numbers', false);
                        $cols = array();

                        foreach ((array)$colsRaw as $ck => $cv) {
                            if (is_string($ck) && $ck !== '') {
                                $cols[$ck] = true;
                            } elseif (is_object($cv) && isset($cv->Field)) {
                                $cols[(string)$cv->Field] = true;
                            }
                        }

                        $sets = array();
                        $actualExtra = array_values(array_map('intval', (array)($vrow['actual_extra'] ?? array())));

                        if (isset($cols['evaluation_status'])) {
                            $sets[] = $db->quoteName('evaluation_status') . ' = ' . $db->quote('scored');
                        }
                        if (isset($cols['status'])) {
                            $sets[] = $db->quoteName('status') . ' = ' . $db->quote('scored');
                        }
                        if (isset($cols['score_status'])) {
                            $sets[] = $db->quoteName('score_status') . ' = ' . $db->quote('scored');
                        }
                        if (isset($cols['play_status'])) {
                            $sets[] = $db->quoteName('play_status') . ' = ' . $db->quote('scored');
                        }
                        if (isset($cols['evaluated_at'])) {
                            $sets[] = $db->quoteName('evaluated_at') . ' = ' . $db->quote(gmdate('Y-m-d H:i:s'));
                        }
                        if (isset($cols['actual_draw_date'])) {
                            $sets[] = $db->quoteName('actual_draw_date') . ' = ' . $db->quote($drawDate);
                        }
                        if (isset($cols['actual_main_numbers'])) {
                            $sets[] = $db->quoteName('actual_main_numbers') . ' = ' . $db->quote(implode(',', array_map('intval', $actualMain)));
                        }
                        if (isset($cols['actual_extra_numbers'])) {
                            $sets[] = $db->quoteName('actual_extra_numbers') . ' = ' . $db->quote(implode(',', $actualExtra));
                        }
                        if (isset($cols['main_hits_count'])) {
                            $sets[] = $db->quoteName('main_hits_count') . ' = ' . (int)($vrow['main_hits'] ?? 0);
                        }
                        if (isset($cols['extra_hits_count'])) {
                            $sets[] = $db->quoteName('extra_hits_count') . ' = ' . (int)($vrow['extra_hits'] ?? 0);
                        }
                        if (isset($cols['post_draw_score'])) {
                            $__mlePostDrawScoreForSave = ((int)($vrow['total_hits'] ?? 0) * 1000000) + ((int)($vrow['main_hits'] ?? 0) * 10000) + ((int)($vrow['extra_hits'] ?? 0) * 1000) + ((int)($vrow['top20_hits'] ?? 0) * 10) + (int)($vrow['top10_hits'] ?? 0);
                            $sets[] = $db->quoteName('post_draw_score') . ' = ' . (float)$__mlePostDrawScoreForSave;
                            unset($__mlePostDrawScoreForSave);
                        }
                        if (isset($cols['scored_after_draw_date'])) {
                            $sets[] = $db->quoteName('scored_after_draw_date') . ' = ' . $db->quote($drawDate);
                        }

                        if (!empty($sets)) {
                            $uq = $db->getQuery(true)
                                ->update($db->quoteName('#__user_saved_numbers'))
                                ->set($sets)
                                ->where($db->quoteName('id') . ' = ' . (int)$savedId)
                                ->where($db->quoteName('user_id') . ' = ' . (int)$userId);

                            $db->setQuery($uq);
                            $db->execute();
                        }
                    } catch (\Throwable $__mleMarkScoredEx) {
                        $result['errors'][] = 'Saved run ' . $savedId . ': scored performance saved, but saved row status update failed.';
                    }

                    try {
                        if (function_exists('mleCllV1CaptureScoredRun')) {
                            $__mleCllGameId = (string)($targetMeta['target_game_id'] ?? $savedRow['game_id'] ?? $savedRow['target_game_id'] ?? '');
                            if ($__mleCllGameId === '') { $__mleCllGameId = 'lottery_' . (int)$lotteryId; }
                            mleCllV1CaptureScoredRun($db, $userId, $lotteryId, $__mleCllGameId, $drawDate, $savedId, $savedRow, $vrow, $settings, $metrics, $lineageMeta);
                        }
                    } catch (\Throwable $__mleCllEx) {
                        error_log('[MLE_CLOSED_LOOP_LEARNING_V1] capture bridge failed saved_id=' . (int)$savedId . ' msg=' . $__mleCllEx->getMessage());
                    }
                }
                else { $result['skipped']++; }
            } catch (\Throwable $e) {
                $result['errors'][] = 'Saved run ' . $savedId . ': scoring write failed.';
            }
        }
        return $result;
    }
}

if (!function_exists('mylottoexpertFirstLoadReconcileDuePendingRows')) {
    function mylottoexpertFirstLoadReconcileDuePendingRows($db, $userId, array $active, $maxLotteries = 20)
    {
        $result = array(
            'checked_lotteries' => 0,
            'attempted_lotteries' => 0,
            'saved_rows' => 0,
            'changed' => false,
            'errors' => array()
        );
        $userId = (int)$userId;
        $maxLotteries = (int)$maxLotteries;
        if ($maxLotteries <= 0) { $maxLotteries = 20; }
        if (!is_object($db) || $userId <= 0 || empty($active)) { return $result; }
        if (!function_exists('mleAdvisoryLoadMatchedPerformance') || !function_exists('mleAdvisoryBuildVisualRunRows') || !function_exists('mleAdvisoryPersistCompletedVisualRuns')) { return $result; }

        $todayTs = strtotime(date('Y-m-d'));
        if ($todayTs === false || $todayTs <= 0) { $todayTs = time(); }

        foreach ((array)$active as $lotteryId => $bucket) {
            if ($result['attempted_lotteries'] >= $maxLotteries) { break; }
            $lotteryId = (int)$lotteryId;
            if ($lotteryId <= 0 || !is_array($bucket)) { continue; }
            $rows = isset($bucket['rows']) && is_array($bucket['rows']) ? (array)$bucket['rows'] : array();
            if (empty($rows)) { continue; }

            $hasDuePending = false;
            foreach ($rows as $row) {
                if (!is_array($row)) { continue; }
                $status = strtolower(trim((string)($row['evaluation_status'] ?? $row['status'] ?? $row['score_status'] ?? '')));
                $playStatus = strtolower(trim((string)($row['play_status'] ?? '')));
                $evaluatedAt = trim((string)($row['evaluated_at'] ?? ''));
                $actualDraw = trim((string)($row['actual_draw_date'] ?? ''));
                $actualMain = trim((string)($row['actual_main_numbers'] ?? ''));
                $targetDate = trim((string)($row['target_draw_date'] ?? $row['next_draw_date'] ?? ''));
                if ($targetDate === '' || strpos($targetDate, '0000-00-00') === 0) { continue; }
                $targetTs = strtotime(substr($targetDate, 0, 10));
                if ($targetTs === false || $targetTs > $todayTs) { continue; }
                if ($evaluatedAt !== '' || $actualDraw !== '' || $actualMain !== '') { continue; }
                if ($status !== '' && !in_array($status, array('pending','queued','draft','unscored',''), true)) { continue; }
                if ($playStatus !== '' && !in_array($playStatus, array('draft','pending',''), true)) { continue; }
                $hasDuePending = true;
                break;
            }
            if (!$hasDuePending) { continue; }

            $result['checked_lotteries']++;
            $result['attempted_lotteries']++;
            try {
                $perf = mleAdvisoryLoadMatchedPerformance($db, $userId, $lotteryId, $rows);
                $visual = mleAdvisoryBuildVisualRunRows($rows, is_array($perf) ? $perf : array());
                $savedById = array();
                foreach ($rows as $r) {
                    if (is_array($r)) { $savedById[(int)($r['id'] ?? 0)] = $r; }
                }
                $lotteryName = trim((string)($bucket['lottery_name'] ?? ''));
                if ($lotteryName === '') { $lotteryName = 'Lottery ID ' . $lotteryId; }
                $scoreResult = mleAdvisoryPersistCompletedVisualRuns($db, $userId, $lotteryId, $lotteryName, $visual, $savedById);
                $saved = (int)($scoreResult['saved'] ?? 0);
                if ($saved > 0) {
                    $result['saved_rows'] += $saved;
                    $result['changed'] = true;
                }
                if (!empty($scoreResult['errors']) && is_array($scoreResult['errors'])) {
                    foreach ($scoreResult['errors'] as $err) {
                        $err = trim((string)$err);
                        if ($err !== '') { $result['errors'][] = 'Lottery ' . $lotteryId . ': ' . $err; }
                    }
                }
            } catch (\Throwable $e) {
                $result['errors'][] = 'Lottery ' . $lotteryId . ': first-load pending reconciliation failed.';
            }
        }

        return $result;
    }
}

if (!function_exists('mleAdvisoryBuildScoringStatusSummary')) {
    function mleAdvisoryBuildScoringStatusSummary(array $visualRows, array $methodBreakdown, array $autoScoreResult = array()) {
        $out = array(
            'status' => 'no_runs',
            'title' => 'No saved runs yet',
            'message' => 'Save prediction runs for upcoming draws. LottoExpert will score eligible saved runs automatically after official results are available.',
            'pending_total' => (int)($methodBreakdown['pending_total'] ?? 0),
            'scored_total' => (int)($methodBreakdown['scored_total'] ?? 0),
            'saved_total' => (int)($methodBreakdown['saved_total'] ?? 0),
            'completed_visible' => 0,
            'future_waiting' => 0,
            'missing_result' => 0,
            'scoreable_pending' => 0,
            'score_action_available' => false,
            'auto_scored' => (int)($autoScoreResult['saved'] ?? 0),
            'errors' => (array)($autoScoreResult['errors'] ?? array())
        );

        $today = strtotime(date('Y-m-d'));
        foreach ((array)($visualRows['recent'] ?? array()) as $row) {
            if (is_array($row) && !empty($row['completed'])) { $out['completed_visible']++; }
        }
        foreach ((array)($visualRows['older'] ?? array()) as $row) {
            if (is_array($row) && !empty($row['completed'])) { $out['completed_visible']++; }
        }
        foreach ((array)($visualRows['upcoming'] ?? array()) as $row) {
            if (!is_array($row)) { continue; }
            $dd = trim((string)($row['target_draw_date'] ?? $row['draw_date'] ?? ''));
            if ($dd !== '' && strpos($dd, '0000-00-00') === 0) { $dd = ''; }
            $ts = $dd !== '' ? strtotime(substr($dd, 0, 10)) : false;
            $hasOfficialForThisPendingTarget = !empty($row['actual_official_found'])
                && (!empty($row['actual']) || !empty($row['actual_extra']));
            if ($hasOfficialForThisPendingTarget) {
                $out['scoreable_pending']++;
            } elseif ($ts !== false && $ts < $today) {
                $out['missing_result']++;
            } else {
                $out['future_waiting']++;
            }
        }
        if ($out['auto_scored'] > 0) {
            $out['status'] = 'scored_now';
            $out['title'] = 'Scoring updated now';
            $out['message'] = $out['auto_scored'] . ' saved run' . ($out['auto_scored'] === 1 ? '' : 's') . ' were matched to an official result and converted into completed prediction history.';
        } elseif ($out['pending_total'] > 0 && $out['scoreable_pending'] > 0) {
            $out['status'] = 'scoreable';
            $out['title'] = 'Automatic scoring is ready';
            $out['message'] = 'The official result for the exact pending draw is available. LottoExpert will score the saved runs automatically and update the prediction history. No user action is required.';
            $out['score_action_available'] = false;
        } elseif ($out['pending_total'] > 0 && $out['missing_result'] > 0 && $out['future_waiting'] <= 0) {
            $out['status'] = 'needs_result_or_match';
            $out['title'] = 'Waiting for exact official result match';
            $out['message'] = 'Some saved runs are past their target date, but LottoExpert has not confirmed the exact official result match yet. The system will keep checking automatically. If this persists, the admin audit can review the draw date, game id, draw session, and result import.';
        } elseif ($out['pending_total'] > 0) {
            $out['status'] = 'waiting';
            $out['title'] = 'Runs are saved and waiting for the draw';
            $out['message'] = 'Saved runs will become completed prediction history automatically after the official result for the same target draw is available.';
        } elseif ($out['scored_total'] > 0 || $out['completed_visible'] > 0) {
            $out['status'] = 'scored';
            $out['title'] = 'Checked prediction history is available';
            $out['message'] = 'These scored records are exact-draw comparisons. They do not pull better historical runs from other drawings.';
        } elseif ($out['saved_total'] > 0) {
            $out['status'] = 'saved_only';
            $out['title'] = 'Saved runs exist, but none are scored yet';
            $out['message'] = 'Saved runs are pre-draw predictions. LottoExpert scores them automatically after the official result is matched to their target draw.';
        }
        if (!empty($out['errors'])) {
            $out['status'] = 'error';
            $out['title'] = 'Scoring needs attention';
            $out['message'] = 'LottoExpert found runs that may be ready for automatic scoring, but one or more scoring writes failed. This is a system review item; no regular user action is required.';
        }
        return $out;
    }
}

