    } catch (\Throwable $e) {

    }

    return array('lottery_id'=>$lotteryId,'game_id'=>$resolvedGameId,'target_game_id'=>$resolvedGameId,'lottery_name'=>$resolvedLotteryName,'has_data'=>true,'top_method'=>$topMethod,'leaderboard'=>$methods,'method_opinions'=>$methodOpinions,'settings_advice'=>$settingsAdv,'proof_level'=>$proof,'next_step'=>!empty($settingsAdv['has_advice'])?'Create the recommended next settings run and test only one change.':'Keep saving predictions while automatic scoring builds prediction history before changing settings.','what_to_do'=>'Use the visual run comparison to keep strong runs, remove noisy runs from advice, and create the next settings test.','decision'=>$decision,'why_support'=>$why,'base_run_id'=>$baseRunId,'stats'=>array('total_runs'=>$leaderboard['stats']['total_runs']??count($activeRows),'completed_draws'=>$leaderboard['stats']['total_draws']??0,'active_methods'=>$leaderboard['stats']['method_count']??0),'batch_cleanup'=>($cleanup['has_recommendation']??false)?$cleanup:null,'prediction_summary'=>$summary,'visual_runs'=>$visual,'active_rows'=>$activeRows,'saved_settings'=>$settingsRows,'numbers_to_play'=>$playRows,'wheel_systems'=>$wheelRows,'precision_lock'=>$precisionLock,'horizon_window_lock'=>$horizonWindowLock,'shared_skai_learning_profile'=>$sharedSkaiLearningProfile,'history_window_evidence_verification'=>$historyWindowEvidenceVerification,'full_skai_settings_evidence_mapper'=>$fullSkaiSettingsEvidenceMapper,'closed_loop_skai_recommendation_intelligence'=>$closedLoopSkaiRecommendationIntelligence,'recommendation_level'=>$recommendationLevel,'precision_progress'=>$precisionProgress,'recommended_skai_batch_test'=>$recommendedBatchTest,'method_run_breakdown'=>$methodRunBreakdown,'scoring_status'=>$scoringStatus,'core_ai_batches'=>$coreAiBatches,'evidence_intelligence'=>$evidenceIntel,'settings_that_repeat'=>$repeatReport,'current_locked_settings'=>$currentLockedSettings,'optimizer'=>$__mleOptimizerData);
}

function mleAdvisorySummarizeActiveLotteryBucket(array $bucket) {
    $lotteryId = (int)($bucket['lottery_id'] ?? 0);
    $lotteryName = trim((string)($bucket['lottery_name'] ?? ''));
    if ($lotteryName === '') { $lotteryName = $lotteryId > 0 ? ('Lottery #' . $lotteryId) : 'Lottery'; }
    $rows = is_array($bucket['rows'] ?? null) ? $bucket['rows'] : array();
    $totalRuns = count($rows);
    $scoredRuns = 0;
    $pendingRuns = 0;
    $methodCounts = array();
    $scoredDrawDates = array();
    $upcomingLightRows = array();
    $upcomingDrawDate = '';
    foreach ($rows as $row) {
        $methodKey = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey')
            ? mleAdvisoryResolveSavedEvidenceMethodKey((array)$row)
            : mleAdvisorySourceToMethodKey((string)($row['source'] ?? ''));
        if ($methodKey === '') { $methodKey = 'pending_evidence'; }
        if (!isset($methodCounts[$methodKey])) { $methodCounts[$methodKey] = 0; }
        $methodCounts[$methodKey]++;
        $hasScore = function_exists('mylottoexpertRowHasUserScoredEvidence')
            ? mylottoexpertRowHasUserScoredEvidence((array)$row)
            : false;
        if ($hasScore) {
            $scoredRuns++;

            $__selectorScoredDrawDate = function_exists('mleAdvisoryCompletedDrawCycleDate') ? mleAdvisoryCompletedDrawCycleDate((array)$row) : '';
            if ($__selectorScoredDrawDate !== '') { $scoredDrawDates[$__selectorScoredDrawDate] = true; }
        } else {
            $pendingRuns++;

            $__selUpcomingDate = '';
            foreach (array('target_draw_date', 'next_draw_date') as $__selDrawKey) {
                $__selRawDate = trim((string)($row[$__selDrawKey] ?? ''));
                if ($__selRawDate !== '' && strpos($__selRawDate, '0000-00-00') !== 0 && preg_match('/^\d{4}-\d{2}-\d{2}/', $__selRawDate)) {
                    $__selUpcomingDate = substr($__selRawDate, 0, 10);
                    break;
                }
            }
            if ($__selUpcomingDate !== '') {
                $__selLightRow = array(
                    'id' => isset($row['id']) ? (int)$row['id'] : 0,
                    'target_draw_date' => $__selUpcomingDate,
                    'next_draw_date' => $__selUpcomingDate,
                );
                foreach (array('evaluation_status', 'play_status', 'status') as $__selStKey) {
                    $__selStVal = trim((string)($row[$__selStKey] ?? ''));
                    if ($__selStVal !== '') { $__selLightRow[$__selStKey] = $__selStVal; break; }
                }
                $upcomingLightRows[] = $__selLightRow;
                if ($upcomingDrawDate === '') { $upcomingDrawDate = $__selUpcomingDate; }
            }
        }
    }
    $completedDrawCycles = function_exists('mylottoexpertCanonicalCompletedDrawCycleCount') ? mylottoexpertCanonicalCompletedDrawCycleCount($rows) : count($scoredDrawDates);
    if ($completedDrawCycles <= 0) { $completedDrawCycles = count($scoredDrawDates); }
    unset($__selectorScoredDrawDate);
    $topMethod = 'pending_evidence';
    $topMethodCount = 0;
    foreach ($methodCounts as $methodKey => $methodCount) {
        if ((int)$methodCount > (int)$topMethodCount) {
            $topMethod = (string)$methodKey;
            $topMethodCount = (int)$methodCount;
        }
    }
    $__selectorCard = array(
        'lottery_id' => $lotteryId,
        'game_id' => (string)($bucket['game_id'] ?? ''),
        'target_game_id' => (string)($bucket['game_id'] ?? ''),
        'lottery_name' => $lotteryName,
        'has_data' => ($totalRuns > 0),
        'top_method' => array('method' => $topMethod, 'run_count' => (int)$topMethodCount, 'draw_count' => (int)$completedDrawCycles),
        'stats' => array('total_runs' => (int)$totalRuns, 'completed_draws' => (int)$completedDrawCycles, 'active_methods' => count($methodCounts)),
        'prediction_summary' => array('total_runs' => (int)$totalRuns, 'pending_runs' => (int)$pendingRuns, 'scored_runs' => (int)$scoredRuns, 'scored_draws' => (int)$completedDrawCycles),
        'visual_runs' => array('recent' => array(), 'older' => array(), 'upcoming' => $upcomingLightRows),
        'precision_progress' => array('level_key' => 'learning_stage', 'level_name' => 'Learning Stage', 'current_draw_cycles' => (int)$completedDrawCycles),
        'recommended_skai_batch_test' => array('has_recommendation' => false),
        'settings_advice' => array('has_advice' => false),
    );
    if ($upcomingDrawDate !== '') {
        $__selectorCard['next_draw_date'] = $upcomingDrawDate;
        $__selectorCard['target_draw_date'] = $upcomingDrawDate;
    }
    return $__selectorCard;
}

function mleAdvisoryLogPerfTiming($sectionName, array $context = array()) {
    $safe = array(
        'section' => (string)$sectionName,
        'elapsed_ms' => (int)($context['elapsed_ms'] ?? 0),
        'user_id' => (int)($context['user_id'] ?? 0),
        'lottery_id' => (int)($context['lottery_id'] ?? 0),
        'game_id' => (string)($context['game_id'] ?? ''),
        'row_count' => (int)($context['row_count'] ?? 0),
        'request_mode' => (string)($context['request_mode'] ?? 'first_load'),
        'first_load_start' => (int)($context['first_load_start'] ?? 0),
        'first_load_end' => (int)($context['first_load_end'] ?? 0),
        'first_load_total_elapsed_ms' => (int)($context['first_load_total_elapsed_ms'] ?? 0),
        'selected_lottery_id' => (int)($context['selected_lottery_id'] ?? 0),
        'active_lottery_count' => (int)($context['active_lottery_count'] ?? 0),
        'selected_card_elapsed_ms' => (int)($context['selected_card_elapsed_ms'] ?? 0),
        'forced_fast_mode' => !empty($context['forced_fast_mode']) ? 'yes' : 'no',
        'timeout_guard_triggered' => !empty($context['timeout_guard_triggered']) ? 'yes' : 'no',
        'ajax_mode' => (string)($context['ajax_mode'] ?? ''),
        'ajax_elapsed_ms' => (int)($context['ajax_elapsed_ms'] ?? 0),
        'ajax_rows_returned' => (int)($context['ajax_rows_returned'] ?? 0),
        'slow_query_label' => (string)($context['slow_query_label'] ?? ''),
    );
    if ($safe['elapsed_ms'] > 0) {
        error_log('[MLE PERF] ' . json_encode($safe, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    }
}

if (!function_exists('mylottoexpertArrayMaxIntValue')) {
    function mylottoexpertArrayMaxIntValue(array $values)
    {
        $max = 0;
        foreach ($values as $value) {
            $value = (int)$value;
            if ($value > $max) { $max = $value; }
        }
        return $max;
    }
}

if (!function_exists('mylottoexpertResolveUpcomingDrawScope')) {
    function mylottoexpertResolveUpcomingDrawScope(array $card)
    {
        $date = '';
        $drawAt = '';
        foreach (array('next_draw_date','target_draw_date','upcoming_draw_date') as $key) {
            $raw = trim((string)($card[$key] ?? ''));
            if ($raw !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', substr($raw, 0, 10))) {
                $date = substr($raw, 0, 10);
                break;
            }
        }
        foreach (array('next_draw_at','target_draw_at','upcoming_draw_at') as $key) {
            $rawAt = trim((string)($card[$key] ?? ''));
            if ($rawAt !== '' && strncmp($rawAt, '0000-00-00', 10) !== 0) {
                $drawAt = $rawAt;
                break;
            }
        }
        $visual = is_array($card['visual_runs'] ?? null) ? (array)$card['visual_runs'] : array();
        $visualUpcoming = (isset($visual['upcoming']) && is_array($visual['upcoming'])) ? (array)$visual['upcoming'] : array();
        if ($date === '' && is_array($visualUpcoming)) {
            foreach ($visualUpcoming as $row) {
                foreach (array('target_draw_date','next_draw_date','draw_date') as $drawKey) {
                    $rawDate = trim((string)($row[$drawKey] ?? ''));
                    if ($rawDate !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', substr($rawDate, 0, 10))) {
                        $date = substr($rawDate, 0, 10);
                        break 2;
                    }
                }
            }
        }
        if ($drawAt === '' && is_array($visualUpcoming)) {
            foreach ($visualUpcoming as $row) {
                foreach (array('target_draw_at','next_draw_at','draw_at') as $drawAtKey) {
                    $rawDrawAt = trim((string)($row[$drawAtKey] ?? ''));
                    if ($rawDrawAt !== '' && strncmp($rawDrawAt, '0000-00-00', 10) !== 0) {
                        $drawAt = $rawDrawAt;
                        break 2;
                    }
                }
            }
        }
        return array('date' => $date, 'draw_at' => $drawAt);
    }
}


if (!function_exists('mylottoexpertNormalizePendingTargetDate')) {
    function mylottoexpertNormalizePendingTargetDate($value)
    {
        $value = trim((string)$value);
        if ($value === '' || strpos($value, '0000-00-00') === 0) { return ''; }
        if (preg_match('/^(\d{4})-(\d{2})-(\d{2})/', $value, $m)) { return $m[1] . '-' . $m[2] . '-' . $m[3]; }
        if (preg_match('/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/', $value, $m)) { return $m[3] . '-' . str_pad($m[1], 2, '0', STR_PAD_LEFT) . '-' . str_pad($m[2], 2, '0', STR_PAD_LEFT); }
        return '';
    }
}

if (!function_exists('mylottoexpertCardHasCompletedEvidenceForDraw')) {
    function mylottoexpertCardHasCompletedEvidenceForDraw(array $card, $drawDate)
    {
        $drawDate = mylottoexpertNormalizePendingTargetDate($drawDate);
        if ($drawDate === '') { return false; }
        $visual = is_array($card['visual_runs'] ?? null) ? (array)$card['visual_runs'] : array();
        $completedRows = array_merge((array)($visual['recent'] ?? array()), (array)($visual['older'] ?? array()));
        foreach ($completedRows as $row) {
            if (!is_array($row)) { continue; }
            $rowDate = '';
            foreach (array('draw_date','actual_draw_date','official_draw_date','target_draw_date','next_draw_date','latest_draw_date','generated_at','date_saved') as $dateKey) {
                $rowDate = mylottoexpertNormalizePendingTargetDate($row[$dateKey] ?? '');
                if ($rowDate !== '') { break; }
            }
            if ($rowDate !== $drawDate) { continue; }
            if (!empty($row['completed']) || !empty($row['is_scored']) || !empty($row['scored'])) { return true; }
            foreach (array('actual','actual_extra','actual_main_numbers','actual_numbers','actual_extra_numbers','matches','extra_matches','ranking_matches') as $evidenceKey) {
                if (!array_key_exists($evidenceKey, $row)) { continue; }
                $evidenceValue = $row[$evidenceKey];
                if (is_array($evidenceValue) && !empty($evidenceValue)) { return true; }
                if (!is_array($evidenceValue)) {
                    $raw = trim((string)$evidenceValue);
                    if ($raw !== '' && $raw !== '[]' && $raw !== '{}' && strtolower($raw) !== 'null') { return true; }
                }
            }
            foreach (array('total_hits','main_hits','extra_hits','hits_main','hits_extra','top10_hits','top20_hits') as $hitKey) {
                if (array_key_exists($hitKey, $row) && is_numeric($row[$hitKey])) { return true; }
            }
        }
        return false;
    }
}

if (!function_exists('mylottoexpertSavedPredictionPartsForOfficialPendingCheck')) {
    function mylottoexpertSavedPredictionPartsForOfficialPendingCheck(array $row)
    {
        $main = array();
        $extra = array();
        try {
            if (function_exists('mylottoexpertExtractDailySavedView')) {
                $daily = mylottoexpertExtractDailySavedView($row);
                if (!empty($daily['is_daily'])) {
                    if (!empty($daily['primary_combo_digits'])) { $main = array_values(array_map('intval', (array)$daily['primary_combo_digits'])); }
                    elseif (!empty($daily['combo_strings'][0]) && function_exists('mleAdvisoryDigitArrayFromComboString')) { $main = mleAdvisoryDigitArrayFromComboString((string)$daily['combo_strings'][0]); }
                    if (!empty($daily['bonus_digits'])) { $extra = array_values(array_map('intval', (array)$daily['bonus_digits'])); }
                    elseif (!empty($daily['extra_digits'])) { $extra = array_values(array_map('intval', (array)$daily['extra_digits'])); }
                    elseif (!empty($daily['top_extras'])) { $extra = array_values(array_map('intval', (array)$daily['top_extras'])); }
                }
            }
        } catch (\Throwable $e) { }
        if (empty($main) && function_exists('mylottoexpertExtractRegularSavedView')) {
            try {
                $regular = mylottoexpertExtractRegularSavedView($row);
                $main = array_values(array_map('intval', (array)($regular['main'] ?? array())));
                $extra = array_values(array_map('intval', (array)($regular['extra'] ?? array())));
            } catch (\Throwable $e) { }
        }
        if (empty($main) && function_exists('mylottoexpertParseNumberCsv')) { $main = mylottoexpertParseNumberCsv($row['main_numbers'] ?? '', true); }
        if (empty($extra) && function_exists('mylottoexpertParseNumberCsv')) { $extra = mylottoexpertParseNumberCsv($row['extra_ball_numbers'] ?? '', true); }
        return array('main'=>array_values(array_map('intval', (array)$main)), 'extra'=>array_values(array_map('intval', (array)$extra)));
    }
}

if (!function_exists('mylottoexpertSavedRowHasOfficialResultForPendingTarget')) {
    function mylottoexpertSavedRowHasOfficialResultForPendingTarget(array $row)
    {
        if (!function_exists('mleAdvisoryResolveActualDrawPartsForVisual')) { return false; }
        $drawDate = '';
        foreach (array('target_draw_date','next_draw_date','draw_date','latest_draw_date') as $dateKey) {
            $drawDate = mylottoexpertNormalizePendingTargetDate($row[$dateKey] ?? '');
            if ($drawDate !== '') { break; }
        }
        if ($drawDate === '') { return false; }
        $drawTs = strtotime($drawDate);
        if ($drawTs !== false && $drawTs > time()) { return false; }
        $parts = mylottoexpertSavedPredictionPartsForOfficialPendingCheck($row);
        try {
            $actual = mleAdvisoryResolveActualDrawPartsForVisual(array(
                'draw_date' => $drawDate,
                'target_draw_date' => $drawDate,
                'lottery_id' => (int)($row['lottery_id'] ?? 0),
                'target_lottery_id' => (int)($row['target_lottery_id'] ?? 0),
                'target_game_id' => (string)($row['target_game_id'] ?? $row['game_id'] ?? ''),
                'game_id' => (string)($row['game_id'] ?? $row['target_game_id'] ?? ''),
                'target_draw_session' => (string)($row['target_draw_session'] ?? $row['draw_session'] ?? '')
            ), $row, (array)$parts['main'], (array)$parts['extra']);
            return !empty($actual['found']) && (!empty($actual['main']) || !empty($actual['extra']));
        } catch (\Throwable $e) {
            return false;
        }
    }
}

if (!function_exists('mylottoexpertDatabasePendingRunCount')) {

    function mylottoexpertDatabasePendingRunCount($db, $userId, array $card, $requireIdentity = false)
    {
        $userId = (int)$userId;
        $lotteryId = (int)($card['lottery_id'] ?? 0);
        $gameId = trim((string)($card['game_id'] ?? $card['target_game_id'] ?? ''));
        if (!is_object($db) || $userId <= 0 || ($lotteryId <= 0 && $gameId === '')) { return null; }

        try {
            $table = '#__user_saved_numbers';
            $colsRaw = $db->getTableColumns($table, false);
            $cols = array();
            foreach ((array)$colsRaw as $ck => $cv) {
                if (is_string($ck) && $ck !== '') { $cols[$ck] = true; }
                elseif (is_object($cv) && isset($cv->Field)) { $cols[(string)$cv->Field] = true; }
            }
            if (empty($cols) || empty($cols['user_id'])) { return null; }
            $hasCol = function($name) use ($cols) { return isset($cols[(string)$name]); };
            $qn = function($name) use ($db) { return $db->quoteName((string)$name); };

            $where = array($qn('user_id') . ' = ' . (int)$userId);

            $__hasLotteryIdCol = $hasCol('lottery_id');
            $__hasTargetLotteryIdCol = $hasCol('target_lottery_id');
            $__hasGameIdCol = $hasCol('game_id');
            $__hasTargetGameIdCol = $hasCol('target_game_id');
            if ($lotteryId > 0) {
                $__effLotParts = array();
                if ($__hasTargetLotteryIdCol) { $__effLotParts[] = 'NULLIF(' . $qn('target_lottery_id') . ', 0)'; }
                if ($__hasLotteryIdCol)       { $__effLotParts[] = 'NULLIF(' . $qn('lottery_id') . ', 0)'; }
                if (empty($__effLotParts)) { return null; }
                $__effLotExpr = 'COALESCE(' . implode(', ', $__effLotParts) . ', 0)';
                $where[] = '(' . $__effLotExpr . ' = ' . (int)$lotteryId . ')';
            } elseif ($gameId !== '') {

                $__effGameParts = array();
                if ($__hasTargetGameIdCol) { $__effGameParts[] = "NULLIF(" . $qn('target_game_id') . ", '')"; }
                if ($__hasGameIdCol)       { $__effGameParts[] = "NULLIF(" . $qn('game_id') . ", '')"; }
                if (empty($__effGameParts)) { return null; }
                $__effGameExpr = "LOWER(TRIM(COALESCE(" . implode(', ', $__effGameParts) . ", '')))";
                $where[] = '(' . $__effGameExpr . ' = ' . $db->quote(strtolower(trim($gameId))) . ')';
            } else {
                return null;
            }

            $terminal = array('scored','evaluated','complete','completed','result_found','official_found','archived','deleted','discarded','inactive','retired','cancelled','canceled','failed','void','quarantined');
            foreach (array('evaluation_status','status','play_status','score_status') as $statusCol) {
                if ($hasCol($statusCol)) {
                    $quoted = array();
                    foreach ($terminal as $v) { $quoted[] = $db->quote($v); }
                    $where[] = '(' . $qn($statusCol) . ' IS NULL OR TRIM(' . $qn($statusCol) . ') = ' . $db->quote('') . ' OR LOWER(TRIM(' . $qn($statusCol) . ')) NOT IN (' . implode(',', $quoted) . '))';
                }
            }
            if ($requireIdentity && $hasCol('evaluation_status')) {
                $where[] = "(LOWER(TRIM(COALESCE(" . $qn('evaluation_status') . ",''))) = 'pending')";
            }
            if ($requireIdentity && $hasCol('play_status')) {
                $where[] = "(LOWER(TRIM(COALESCE(" . $qn('play_status') . ",''))) = 'draft')";
            }
            if ($hasCol('evaluated_at')) {
                $where[] = '(' . $qn('evaluated_at') . ' IS NULL OR ' . $qn('evaluated_at') . ' = ' . $db->quote('0000-00-00 00:00:00') . ')';
            }
            foreach (array('actual_main_numbers','actual_numbers','actual_extra_numbers','actual_draw_date') as $actualCol) {
                if ($hasCol($actualCol)) {
                    $where[] = '(' . $qn($actualCol) . ' IS NULL OR TRIM(' . $qn($actualCol) . ') = ' . $db->quote('') . ' OR ' . $qn($actualCol) . ' = ' . $db->quote('0000-00-00') . ')';
                }
            }

            $upcoming = mylottoexpertResolveUpcomingDrawScope($card);
            $upcomingDate = trim((string)($upcoming['date'] ?? ''));
            if ($upcomingDate === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $upcomingDate)) { return 0; }
            if (function_exists('mylottoexpertCardHasCompletedEvidenceForDraw') && mylottoexpertCardHasCompletedEvidenceForDraw($card, $upcomingDate)) {
                return 0;
            }
            $drawParts = array();
            $drawCols = $requireIdentity ? array('target_draw_date','next_draw_date','latest_draw_date') : array('target_draw_date','next_draw_date','latest_draw_date','draw_date');
            foreach ($drawCols as $drawCol) {
                if ($hasCol($drawCol)) { $drawParts[] = 'NULLIF(' . $qn($drawCol) . ', ' . $db->quote('0000-00-00') . ')'; }
            }
            $drawExpr = !empty($drawParts) ? 'COALESCE(' . implode(',', $drawParts) . ')' : 'NULL';
            $where[] = '((' . $drawExpr . ') IS NOT NULL AND DATE(' . $drawExpr . ') = ' . $db->quote($upcomingDate) . ')';

            if ($requireIdentity) {

                if ($hasCol('source')) {
                    $where[] = '(LOWER(TRIM(' . $qn('source') . ")) <> 'strategy_set')";
                }

                if ($hasCol('save_intent')) {
                    $where[] = '('
                        . 'LOWER(TRIM(COALESCE(' . $qn('save_intent') . ",''))) NOT LIKE 'training%'"
                        . " AND LOWER(TRIM(COALESCE(" . $qn('save_intent') . ",''))) NOT LIKE 'learning%'"
                        . " AND LOWER(TRIM(COALESCE(" . $qn('save_intent') . ",''))) NOT LIKE 'system%'"
                        . ')';
                }
                $placeholderKinds = array('batch_header','research_queue','research_assignment','recommendation_only','needs_run_placeholder');
                foreach (array('source','origin_source','save_intent','status','play_status') as $kindCol) {
                    if ($hasCol($kindCol)) {
                        $kindQuoted = array();
                        foreach ($placeholderKinds as $kind) { $kindQuoted[] = $db->quote($kind); }
                        $where[] = '(LOWER(TRIM(COALESCE(' . $qn($kindCol) . ",''))) NOT IN (" . implode(',', $kindQuoted) . '))';
                    }
                }

                $identityParts = array();
                if ($hasCol('run_uuid'))             { $identityParts[] = "(TRIM(COALESCE(" . $qn('run_uuid')             . ",'')) <> '')"; }
                if ($hasCol('batch_uuid'))           { $identityParts[] = "(TRIM(COALESCE(" . $qn('batch_uuid')           . ",'')) <> '')"; }
                if ($hasCol('source_batch_id'))      { $identityParts[] = "(COALESCE("      . $qn('source_batch_id')      . ",0) > 0)"; }
                if ($hasCol('source_batch_run_id'))  { $identityParts[] = "(COALESCE("      . $qn('source_batch_run_id')  . ",0) > 0)"; }
                if ($hasCol('prediction_target_id')) { $identityParts[] = "(TRIM(COALESCE(" . $qn('prediction_target_id') . ",'')) <> '')"; }
                if ($hasCol('prediction_target_key')){ $identityParts[] = "(TRIM(COALESCE(" . $qn('prediction_target_key'). ",'')) <> '')"; }
                if (!empty($identityParts)) {
                    $where[] = '(' . implode(' OR ', $identityParts) . ')';
                } else {
                    return 0;
                }
            }

            if ($requireIdentity) {
                $identityGroupParts = array();
                if ($hasCol('run_uuid'))             { $identityGroupParts[] = "NULLIF(CONCAT('run:',TRIM(COALESCE(" . $qn('run_uuid') . ",''))),'run:')"; }
                if ($hasCol('batch_uuid'))           { $identityGroupParts[] = "NULLIF(CONCAT('batch:',TRIM(COALESCE(" . $qn('batch_uuid') . ",''))),'batch:')"; }
                if ($hasCol('source_batch_run_id'))  { $identityGroupParts[] = "CASE WHEN COALESCE(" . $qn('source_batch_run_id') . ",0) > 0 THEN CONCAT('sbr:',COALESCE(" . $qn('source_batch_run_id') . ",0)) ELSE NULL END"; }
                if ($hasCol('source_batch_id'))      { $identityGroupParts[] = "CASE WHEN COALESCE(" . $qn('source_batch_id') . ",0) > 0 THEN CONCAT('sb:',COALESCE(" . $qn('source_batch_id') . ",0)) ELSE NULL END"; }
                if ($hasCol('prediction_target_id')) { $identityGroupParts[] = "NULLIF(CONCAT('ptid:',TRIM(COALESCE(" . $qn('prediction_target_id') . ",''))),'ptid:')"; }
                if ($hasCol('prediction_target_key')){ $identityGroupParts[] = "NULLIF(CONCAT('ptk:',TRIM(COALESCE(" . $qn('prediction_target_key') . ",''))),'ptk:')"; }
                if ($hasCol('id'))                   { $identityGroupParts[] = "CONCAT('id:'," . $qn('id') . ')'; }
                if (empty($identityGroupParts)) { return 0; }
                $groupExpr = 'COALESCE(' . implode(', ', $identityGroupParts) . ')';
                $query = 'SELECT COUNT(*) FROM (SELECT ' . $groupExpr . ' AS ' . $qn('run_identity') . ' FROM ' . $db->quoteName($table) . ' WHERE ' . implode(' AND ', $where) . ' GROUP BY ' . $qn('run_identity') . ') AS ' . $qn('mle_pending_groups');
            } else {
                $idExpr = $hasCol('id') ? 'COUNT(DISTINCT ' . $qn('id') . ')' : 'COUNT(*)';
                $query = 'SELECT ' . $idExpr . ' FROM ' . $db->quoteName($table) . ' WHERE ' . implode(' AND ', $where);
            }
            $db->setQuery($query);
            $count = (int)$db->loadResult();
            return max(0, $count);
        } catch (\Throwable $e) {
            return null;
        }
    }
}

if (!function_exists('mylottoexpertCanonicalPendingRunCount')) {
    function mylottoexpertCanonicalPendingRunCount(array $card)
    {
        $visual = is_array($card['visual_runs'] ?? null) ? (array)$card['visual_runs'] : array();
        $upcoming = mylottoexpertResolveUpcomingDrawScope($card);
        $upcomingDate = trim((string)($upcoming['date'] ?? ''));
        $upcomingDrawAt = trim((string)($upcoming['draw_at'] ?? ''));
        $visualCount = 0;
        $hasVisualUpcoming = false;
        if (array_key_exists('upcoming', $visual) && is_array($visual['upcoming'])) {
            $hasVisualUpcoming = true;
            foreach ((array)$visual['upcoming'] as $vrow) {
                $drawDate = '';
                foreach (array('target_draw_date','next_draw_date','draw_date') as $drawKey) {
                    $drawRaw = trim((string)($vrow[$drawKey] ?? ''));
                    if ($drawRaw !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', substr($drawRaw, 0, 10))) { $drawDate = substr($drawRaw, 0, 10); break; }
                }
                if ($upcomingDate === '' || $drawDate !== $upcomingDate) { continue; }
                if ($upcomingDate === date('Y-m-d')) {
                    $rowDrawAt = '';
                    foreach (array('target_draw_at','next_draw_at','draw_at') as $drawAtKey) {
                        $drawAtRaw = trim((string)($vrow[$drawAtKey] ?? ''));
                        if ($drawAtRaw !== '' && strncmp($drawAtRaw, '0000-00-00', 10) !== 0) { $rowDrawAt = $drawAtRaw; break; }
                    }
                    if ($rowDrawAt === '') { $rowDrawAt = $upcomingDrawAt; }
                    if ($rowDrawAt !== '' && strtotime($rowDrawAt) && strtotime($rowDrawAt) < time()) { continue; }
                }
                $visualCount++;
            }
        }
        $dbCount = array_key_exists('mle_db_pending_runs', $card) ? (int)$card['mle_db_pending_runs'] : -1;
        $summary = is_array($card['prediction_summary'] ?? null) ? (array)$card['prediction_summary'] : array();
        $progress = is_array($card['precision_progress'] ?? null) ? (array)$card['precision_progress'] : array();
        $summaryCount = max(0, (int)($summary['pending_runs'] ?? 0));
        $progressCount = max(0, (int)($progress['pending_runs'] ?? 0));

        if ($upcomingDate !== '' && function_exists('mylottoexpertCardHasCompletedEvidenceForDraw') && mylottoexpertCardHasCompletedEvidenceForDraw($card, $upcomingDate)) {
            return 0;
        }
        if ($upcomingDate === '') {
            return ($dbCount >= 0) ? max(0, $dbCount) : 0;
        }
        if ($visualCount > 0 || $dbCount > 0) {
            return mylottoexpertArrayMaxIntValue(array($visualCount, $dbCount));
        }
        if ($dbCount === 0) { return 0; }
        if ($hasVisualUpcoming) { return $visualCount; }
        return mylottoexpertArrayMaxIntValue(array($summaryCount, $progressCount));
    }
}

if (!function_exists('mylottoexpertSyncCardPendingCount')) {
    function mylottoexpertSyncCardPendingCount(array $card, $db = null, $userId = 0)
    {
        $dbPending = null;
        if (is_object($db) && (int)$userId > 0) {
            $dbPending = mylottoexpertDatabasePendingRunCount($db, (int)$userId, $card);
            if ($dbPending !== null) { $card['mle_db_pending_runs'] = (int)$dbPending; }
        }
        $pending = mylottoexpertCanonicalPendingRunCount($card);
        if (!isset($card['prediction_summary']) || !is_array($card['prediction_summary'])) {
            $card['prediction_summary'] = array();
        }
        if (!isset($card['precision_progress']) || !is_array($card['precision_progress'])) {
            $card['precision_progress'] = array();
        }
        $card['prediction_summary']['pending_runs'] = $pending;
        $card['precision_progress']['pending_runs'] = $pending;
        $card['mle_canonical_pending_runs'] = $pending;
        return $card;
    }
}

if (!function_exists('mylottoexpertStrictPendingGroupedRows')) {
    function mylottoexpertStrictPendingGroupedRows($db, $userId, array $visibleLotteryIds = array())
    {
        $userId = (int)$userId;
        if (!is_object($db) || $userId <= 0) { return array(); }
        try {
            $table = '#__user_saved_numbers';
            $colsRaw = $db->getTableColumns($table, false);
            $cols = array();
            foreach ((array)$colsRaw as $ck => $cv) {
                if (is_string($ck) && $ck !== '') { $cols[$ck] = true; }
                elseif (is_object($cv) && isset($cv->Field)) { $cols[(string)$cv->Field] = true; }
            }
            if (empty($cols) || empty($cols['user_id']) || empty($cols['target_draw_date'])) { return array(); }
            $hasCol = function($name) use ($cols) { return isset($cols[(string)$name]); };
            $qn = function($name) use ($db) { return $db->quoteName((string)$name); };
            $qc = function($alias, $name) use ($db) { return (string)$alias . '.' . $db->quoteName((string)$name); };

            $visibleLotteryIds = array_values(array_unique(array_filter(array_map('intval', (array)$visibleLotteryIds), static function($v){ return $v > 0; })));
            if (empty($visibleLotteryIds)) { return array(); }

            $effectiveLotteryExprFor = function($alias) use ($hasCol, $qc) {
                $parts = array();
                if ($hasCol('target_lottery_id')) { $parts[] = 'NULLIF(' . $qc($alias, 'target_lottery_id') . ',0)'; }
                if ($hasCol('lottery_id')) { $parts[] = 'NULLIF(' . $qc($alias, 'lottery_id') . ',0)'; }
                if (empty($parts)) { return '0'; }
                return 'COALESCE(' . implode(', ', $parts) . ', 0)';
            };
            $effectiveGameExprFor = function($alias) use ($hasCol, $qc) {
                $parts = array();
                if ($hasCol('target_game_id')) { $parts[] = "NULLIF(TRIM(COALESCE(" . $qc($alias, 'target_game_id') . ",'')),'')"; }
                if ($hasCol('game_id')) { $parts[] = "NULLIF(TRIM(COALESCE(" . $qc($alias, 'game_id') . ",'')),'')"; }
                if (empty($parts)) { return "''"; }
                return 'LOWER(TRIM(COALESCE(' . implode(', ', $parts) . ", '')))";
            };

            $where = array();
            $where[] = $qc('p', 'user_id') . ' = ' . $userId;
            $where[] = '(' . $effectiveLotteryExprFor('p') . ' IN (' . implode(',', array_map('intval', $visibleLotteryIds)) . '))';
            if ($hasCol('target_lottery_id')) { $where[] = '(COALESCE(' . $qc('p', 'target_lottery_id') . ',0) > 0)'; }
            if ($hasCol('evaluation_status')) { $where[] = "(LOWER(TRIM(COALESCE(" . $qc('p', 'evaluation_status') . ",''))) = 'pending')"; }
            if ($hasCol('play_status')) { $where[] = "(LOWER(TRIM(COALESCE(" . $qc('p', 'play_status') . ",''))) = 'draft')"; }
            if ($hasCol('source')) { $where[] = "(LOWER(TRIM(COALESCE(" . $qc('p', 'source') . ",''))) = 'skai_prediction')"; }
            $where[] = '(' . $qc('p', 'target_draw_date') . ' IS NOT NULL)';
            $where[] = "(TRIM(COALESCE(" . $qc('p', 'target_draw_date') . ",'')) <> '')";
            $where[] = '(' . $qc('p', 'target_draw_date') . " <> '0000-00-00')";
            if ($hasCol('evaluated_at')) { $where[] = '(' . $qc('p', 'evaluated_at') . ' IS NULL OR TRIM(' . $qc('p', 'evaluated_at') . ") = '' OR " . $qc('p', 'evaluated_at') . " = '0000-00-00 00:00:00')"; }
            if ($hasCol('actual_draw_date')) { $where[] = '(' . $qc('p', 'actual_draw_date') . ' IS NULL OR TRIM(' . $qc('p', 'actual_draw_date') . ") = '' OR " . $qc('p', 'actual_draw_date') . " = '0000-00-00')"; }
            foreach (array('actual_main_numbers','actual_extra_numbers') as $actualCol) {
                if ($hasCol($actualCol)) { $where[] = '(' . $qc('p', $actualCol) . ' IS NULL OR TRIM(' . $qc('p', $actualCol) . ") = '')"; }
            }
            $identity = array();
            if ($hasCol('source_batch_id')) { $identity[] = '(COALESCE(' . $qc('p', 'source_batch_id') . ',0) > 0)'; }
            if ($hasCol('source_batch_run_id')) { $identity[] = '(COALESCE(' . $qc('p', 'source_batch_run_id') . ',0) > 0)'; }
            if ($hasCol('run_uuid')) { $identity[] = "(TRIM(COALESCE(" . $qc('p', 'run_uuid') . ",'')) <> '')"; }
            if (empty($identity)) { return array(); }
            $where[] = '(' . implode(' OR ', $identity) . ')';

            $sourceBatchExpr = $hasCol('source_batch_id') ? ('COALESCE(p.' . $qn('source_batch_id') . ',0)') : '0';
            $select = array('p.*');
            $select[] = $effectiveLotteryExprFor('p') . ' AS ' . $qn('effective_lottery_id');
            $select[] = $effectiveGameExprFor('p') . ' AS ' . $qn('effective_game_id');
            $select[] = 'DATE(p.' . $qn('target_draw_date') . ') AS ' . $qn('mle_pending_target_draw_date');
            $select[] = $sourceBatchExpr . ' AS ' . $qn('mle_pending_source_batch_id');
            $query = 'SELECT ' . implode(', ', $select)
                . ' FROM ' . $db->quoteName($table) . ' AS p'
                . ' WHERE ' . implode(' AND ', $where)
                . ' ORDER BY ' . $qn('effective_lottery_id') . ' ASC, ' . $qn('mle_pending_target_draw_date') . ' DESC, ' . $qn('mle_pending_source_batch_id') . ' ASC, ' . ($hasCol('id') ? 'p.' . $qn('id') . ' ASC' : 'p.' . $qn('target_draw_date') . ' ASC');
            $db->setQuery($query, 0, 2000);
            $candidateRows = $db->loadAssocList();
            if (empty($candidateRows) || !is_array($candidateRows)) { return array(); }

            $eligibleRows = array();
            $latestDateByLottery = array();
            foreach ($candidateRows as $row) {
                if (!is_array($row)) { continue; }
                $lid = (int)($row['effective_lottery_id'] ?? $row['target_lottery_id'] ?? $row['lottery_id'] ?? 0);
                if ($lid <= 0) { continue; }
                $drawDate = mylottoexpertNormalizePendingTargetDate($row['mle_pending_target_draw_date'] ?? $row['target_draw_date'] ?? '');
                if ($drawDate === '') { continue; }

                if (function_exists('mylottoexpertSavedRowHasOfficialResultForPendingTarget') && mylottoexpertSavedRowHasOfficialResultForPendingTarget($row)) {
                    continue;
                }

                $row['mle_pending_target_draw_date'] = $drawDate;
                $eligibleRows[] = $row;
                if (!isset($latestDateByLottery[$lid]) || strcmp($drawDate, (string)$latestDateByLottery[$lid]) > 0) {
                    $latestDateByLottery[$lid] = $drawDate;
                }
            }
            if (empty($eligibleRows)) { return array(); }

            $grouped = array();
            foreach ($eligibleRows as $row) {
                $lid = (int)($row['effective_lottery_id'] ?? $row['target_lottery_id'] ?? $row['lottery_id'] ?? 0);
                $drawDate = (string)($row['mle_pending_target_draw_date'] ?? '');
                if ($lid <= 0 || $drawDate === '' || (isset($latestDateByLottery[$lid]) && $drawDate !== $latestDateByLottery[$lid])) { continue; }
                $game = strtolower(trim((string)($row['effective_game_id'] ?? $row['target_game_id'] ?? $row['game_id'] ?? '')));
                $batch = (int)($row['mle_pending_source_batch_id'] ?? $row['source_batch_id'] ?? 0);
                $key = $lid . '|' . $game . '|' . $drawDate . '|' . $batch;
                if (!isset($grouped[$key])) {
                    $grouped[$key] = array(
                        'effective_lottery_id' => $lid,
                        'effective_game_id' => $game,
                        'target_draw_date' => $drawDate,
                        'source_batch_id' => $batch,
                        'row_count' => 0,
                    );
                }
                $grouped[$key]['row_count']++;
            }
            $rows = array_values($grouped);
            usort($rows, static function($a, $b) {
                $al = (int)($a['effective_lottery_id'] ?? 0); $bl = (int)($b['effective_lottery_id'] ?? 0);
                if ($al !== $bl) { return $al <=> $bl; }
                $ad = (string)($a['target_draw_date'] ?? ''); $bd = (string)($b['target_draw_date'] ?? '');
                if ($ad !== $bd) { return strcmp($ad, $bd); }
                return ((int)($a['source_batch_id'] ?? 0)) <=> ((int)($b['source_batch_id'] ?? 0));
            });
            return $rows;
        } catch (\Throwable $e) {
            return array();
        }
    }
}

if (!function_exists('mylottoexpertBriefDrawCyclePercent')) {
    function mylottoexpertBriefDrawCyclePercent($cycles, $target = 20)
    {
        $cycles = max(0, (int)$cycles);
        $target = max(1, (int)$target);
        return min(100, (int)round(($cycles / $target) * 100));
    }
}

if (!function_exists('mylottoexpertBriefDrawCycleLabel')) {
    function mylottoexpertBriefDrawCycleLabel($cycles, $target = 20)
    {
        $cycles = max(0, (int)$cycles);
        $target = max(1, (int)$target);
        if ($cycles >= $target) {
            return (string)$target . '+ draw-cycle target met';
        }
        return (string)$cycles . '/' . (string)$target . ' draw cycles';
    }
}

if (!function_exists('mylottoexpertBriefDrawCycleTitle')) {
    function mylottoexpertBriefDrawCycleTitle($cycles, $target = 20)
    {
        $cycles = max(0, (int)$cycles);
        $target = max(1, (int)$target);
        if ($cycles >= $target) {
            return (string)$cycles . ' completed draw cycles tracked. The ' . (string)$target . '-cycle milestone is already met.';
        }
        return (string)$cycles . ' completed draw cycles tracked toward the ' . (string)$target . '-cycle milestone.';
    }
}


if (!function_exists('mylottoexpertEvidenceReadinessNumericValues')) {
    function mylottoexpertEvidenceReadinessNumericValues($values)
    {
        $out = array();
        if (!is_array($values)) { return $out; }
        foreach ($values as $k => $v) {
            $raw = is_numeric($k) ? $v : $k;
            if (is_array($v) && isset($v['value'])) { $raw = $v['value']; }
            $txt = trim((string)$raw);
            if ($txt === '') { continue; }
            if (preg_match('/-?\d+(?:\.\d+)?/', $txt, $m)) {
                $num = (float)$m[0];
                if ($num > 0 && $num <= 1) { $num *= 100.0; }
                $out[] = $num;
            }
        }
        $out = array_values(array_unique(array_map(static function($n) { return (float)$n; }, $out)));
        sort($out, SORT_NUMERIC);
        return $out;
    }
}

if (!function_exists('mylottoexpertEvidenceReadinessFindProfile')) {
    function mylottoexpertEvidenceReadinessFindProfile(array $profiles, array $needles)
    {
        foreach ($profiles as $key => $profile) {
            if (!is_array($profile)) { continue; }
            $hay = strtolower((string)$key . ' ' . (string)($profile['label'] ?? ''));
            foreach ($needles as $needle) {
                if ($needle !== '' && strpos($hay, strtolower((string)$needle)) !== false) { return $profile; }
            }
        }
        return array();
    }
}

if (!function_exists('mylottoexpertEvidenceReadinessBlendCoverage')) {
    function mylottoexpertEvidenceReadinessBlendCoverage(array $profiles)
    {
        $profile = mylottoexpertEvidenceReadinessFindProfile($profiles, array('blend', 'ai_pct', 'ai percent', 'ai weight'));
        $values = array();
        if (!empty($profile)) {
            $values = array_merge(
                mylottoexpertEvidenceReadinessNumericValues((array)($profile['top_values'] ?? array())),
                mylottoexpertEvidenceReadinessNumericValues((array)($profile['value_signals'] ?? array()))
            );
        }
        $zones = array(
            'low_edge' => array('label'=>'low edge', 'range'=>'0% to 20%', 'ok'=>false),
            'low_middle' => array('label'=>'low-middle', 'range'=>'21% to 40%', 'ok'=>false),
            'center' => array('label'=>'center', 'range'=>'41% to 60%', 'ok'=>false),
            'high_middle' => array('label'=>'high-middle', 'range'=>'61% to 80%', 'ok'=>false),
            'high_edge' => array('label'=>'high edge', 'range'=>'81% to 100%', 'ok'=>false),
        );
        foreach ($values as $num) {
            if ($num >= 0 && $num <= 20) { $zones['low_edge']['ok'] = true; }
            elseif ($num > 20 && $num <= 40) { $zones['low_middle']['ok'] = true; }
            elseif ($num > 40 && $num <= 60) { $zones['center']['ok'] = true; }
            elseif ($num > 60 && $num <= 80) { $zones['high_middle']['ok'] = true; }
            elseif ($num > 80 && $num <= 100) { $zones['high_edge']['ok'] = true; }
        }
        $hasLower = (!empty($zones['low_edge']['ok']) || !empty($zones['low_middle']['ok']));
        $hasMiddle = !empty($zones['center']['ok']);
        $hasUpper = (!empty($zones['high_middle']['ok']) || !empty($zones['high_edge']['ok']));
        $tested = ($hasLower ? 1 : 0) + ($hasMiddle ? 1 : 0) + ($hasUpper ? 1 : 0);
        $missing = array();
        if (!$hasLower) { $missing[] = 'lower AI blend corridor'; }
        if (!$hasMiddle) { $missing[] = 'middle AI blend corridor'; }
        if (!$hasUpper) { $missing[] = 'upper AI blend corridor'; }
        return array(
            'tested_zones'=>$tested,
            'total_zones'=>3,
            'complete'=>($tested >= 3 && count($values) >= 3),
            'edges_complete'=>($hasLower && $hasUpper),
            'center_complete'=>$hasMiddle,
            'label'=>$tested . ' of 3 AI blend corridor points tested',
            'missing'=>empty($missing) ? 'none' : implode(', ', $missing),
            'values'=>$values,
            'zones'=>$zones,
        );
    }
}

if (!function_exists('mylottoexpertEvidenceReadinessHistoryCoverage')) {
    function mylottoexpertEvidenceReadinessHistoryCoverage(array $profiles, array $historyVerification = array(), array $horizonLock = array())
    {
        $values = array();
        if (!empty($historyVerification['window_values']) && is_array($historyVerification['window_values'])) {
            $values = array_merge($values, mylottoexpertEvidenceReadinessNumericValues((array)$historyVerification['window_values']));
        }
        $profile = mylottoexpertEvidenceReadinessFindProfile($profiles, array('history_window', 'history window', 'draw depth', 'window'));
        if (!empty($profile)) {
            $values = array_merge($values, mylottoexpertEvidenceReadinessNumericValues((array)($profile['top_values'] ?? array())), mylottoexpertEvidenceReadinessNumericValues((array)($profile['value_signals'] ?? array())));
        }
        /*
         * Strict scientific coverage rule:
         * Do not count recommended/current horizon-lock values as tested coverage.
         * Coverage must come from scored history-window evidence/profile values only.
         * Otherwise a suggested range can incorrectly make the page look fully tested.
         */
        $values = array_values(array_unique(array_map('intval', $values)));
        sort($values, SORT_NUMERIC);
        $distinctCount = count($values);
        $testedMin = !empty($values) ? (float)min($values) : null;
        $testedMax = !empty($values) ? (float)max($values) : null;
        $testedSpan = ($testedMin !== null && $testedMax !== null) ? ((float)$testedMax - (float)$testedMin) : 0.0;
        $hasLower = ($distinctCount >= 1);
        $hasMiddle = ($distinctCount >= 2);
        $hasUpper = ($distinctCount >= 3 && $testedSpan >= 20.0);
        $tested = ($hasLower ? 1 : 0) + ($hasMiddle ? 1 : 0) + ($hasUpper ? 1 : 0);
        $missing = array();
        if (!$hasLower) { $missing[] = 'lower tested AI history-window point'; }
        if (!$hasMiddle) { $missing[] = 'middle tested AI history-window point'; }
        if (!$hasUpper) { $missing[] = 'upper tested AI history-window point'; }
        $anchors = array('lower_corridor'=>$hasLower, 'middle_corridor'=>$hasMiddle, 'upper_corridor'=>$hasUpper);
        return array(
            'tested_windows'=>$tested,
            'total_windows'=>3,
            'distinct_values'=>$distinctCount,
            'complete'=>($tested >= 3),
            'edges_complete'=>($hasLower && $hasUpper),
            'label'=>$tested . ' of 3 AI history-window corridor points tested',
            'missing'=>empty($missing) ? 'none' : implode(', ', $missing),
            'values'=>$values,
            'anchors'=>$anchors,
            'tested_min'=>$testedMin,
            'tested_max'=>$testedMax,
        );
    }
}


if (!function_exists('mylottoexpertV97EvidenceReadinessBlendFromPrecisionLock')) {
    function mylottoexpertV97EvidenceReadinessBlendFromPrecisionLock(array $precisionLock, array $currentBlend)
    {
        $coverage = (array)($precisionLock['blend_coverage'] ?? array());
        $totalValues = max(0, (int)($coverage['total_values'] ?? 0));
        $distinctValues = max(0, (int)($coverage['distinct_values'] ?? 0));
        if ($totalValues <= 0 && $distinctValues <= 0) { return $currentBlend; }
        $zoneCounts = (array)($coverage['zone_counts'] ?? array());
        $hasLower = !empty($coverage['has_contract_lower']) || (int)($zoneCounts['low_edge'] ?? 0) > 0 || (int)($zoneCounts['low_middle'] ?? 0) > 0;
        $hasMiddle = !empty($coverage['has_contract_middle']) || (int)($zoneCounts['center'] ?? 0) > 0;
        $hasUpper = !empty($coverage['has_contract_upper']) || (int)($zoneCounts['high_middle'] ?? 0) > 0 || (int)($zoneCounts['high_edge'] ?? 0) > 0;
        $tested = ($hasLower ? 1 : 0) + ($hasMiddle ? 1 : 0) + ($hasUpper ? 1 : 0);
        $complete = !empty($coverage['full_coverage_met']) || !empty($coverage['contract_coverage_met']) || ($tested >= 3 && $distinctValues >= 3 && $totalValues >= 9);
        $missing = array();
        if (!$hasLower) { $missing[] = 'lower AI blend corridor'; }
        if (!$hasMiddle) { $missing[] = 'middle AI blend corridor'; }
        if (!$hasUpper) { $missing[] = 'upper AI blend corridor'; }
        $label = $tested . ' of 3 AI blend corridor points tested';
        if ($complete) { $label = '3 of 3 AI blend corridor points tested'; }
        return array(
            'tested_zones'=>$complete ? 3 : $tested,
            'total_zones'=>3,
            'complete'=>$complete,
            'edges_complete'=>($hasLower && $hasUpper),
            'center_complete'=>$hasMiddle,
            'label'=>$label,
            'missing'=>empty($missing) ? 'none' : implode(', ', $missing),
            'values'=>(array)($coverage['values'] ?? array()),
            'zones'=>array(
                'lower_corridor'=>array('label'=>'lower AI blend corridor','ok'=>$hasLower),
                'middle_corridor'=>array('label'=>'middle AI blend corridor','ok'=>$hasMiddle),
