if (!function_exists('mylottoexpertV97EvidenceReadinessHistoryFromHorizonLock')) {
    function mylottoexpertV97EvidenceReadinessHistoryFromHorizonLock(array $horizonLock, array $currentHistory)
    {
        $coverage = (array)($horizonLock['horizon_coverage'] ?? array());
        $totalValues = max(0, (int)($coverage['total_values'] ?? ($horizonLock['run_count'] ?? 0)));
        $distinctValues = max(0, (int)($coverage['distinct_values'] ?? ($horizonLock['distinct_windows'] ?? 0)));
        if ($totalValues <= 0 && $distinctValues <= 0) { return $currentHistory; }
        $complete = !empty($coverage['full_coverage_met']) || !empty($coverage['contract_coverage_met']) || !empty($horizonLock['horizon_full_coverage_met']) || ($totalValues >= 9 && $distinctValues >= 3);
        $tested = min(3, $distinctValues);
        $testedMin = $coverage['tested_min'] ?? ($horizonLock['tested_min'] ?? null);
        $testedMax = $coverage['tested_max'] ?? ($horizonLock['tested_max'] ?? null);
        $missing = array();
        if ($distinctValues < 1) { $missing[] = 'lower AI history-window corridor'; }
        if ($distinctValues < 2) { $missing[] = 'middle AI history-window corridor'; }
        if ($distinctValues < 3) { $missing[] = 'upper AI history-window corridor'; }
        $label = ($complete ? 3 : $tested) . ' of 3 AI history-window corridor points tested';
        return array(
            'tested_windows'=>$complete ? 3 : $tested,
            'total_windows'=>3,
            'distinct_values'=>$distinctValues,
            'complete'=>$complete,
            'edges_complete'=>($distinctValues >= 3),
            'label'=>$label,
            'missing'=>empty($missing) ? 'none' : implode(', ', $missing),
            'values'=>(array)($coverage['values'] ?? array()),
            'anchors'=>array(),
            'source'=>'horizon_window_lock_coverage',
            'total_values'=>$totalValues,
            'tested_min'=>$testedMin,
            'tested_max'=>$testedMax,
        );
    }
}


if (!function_exists('mylottoexpertV99DecodeSettingsCandidateInto')) {
    function mylottoexpertV99DecodeSettingsCandidateInto(array $settings, $raw)
    {
        $raw = trim((string)$raw);
        if ($raw === '' || strlen($raw) <= 1 || strlen($raw) > 262144) { return $settings; }
        $first = substr(ltrim($raw), 0, 1);
        if ($first !== '{' && $first !== '[') { return $settings; }
        $decoded = json_decode($raw, true);
        if (json_last_error() !== JSON_ERROR_NONE || !is_array($decoded)) { return $settings; }
        foreach ($decoded as $k => $v) {
            if (!array_key_exists($k, $settings) || $settings[$k] === '' || $settings[$k] === null) {
                $settings[$k] = $v;
            }
        }
        return $settings;
    }
}

if (!function_exists('mylottoexpertV99ExtractBlendAndHistoryValuesFromSettings')) {
    function mylottoexpertV99ExtractBlendAndHistoryValuesFromSettings(array $settings)
    {
        $out = array('blend'=>null, 'history'=>null);
        foreach (array('signal_blend_ai_pct','core_ai_ai_pct','skai_blend_ai_pct','blend_ai_pct','ai_pct','blend_percent','blend_pct','ai_blend_pct') as $k) {
            if (isset($settings[$k]) && is_numeric($settings[$k])) {
                $out['blend'] = max(0.0, min(100.0, (float)$settings[$k]));
                break;
            }
        }
        foreach (array('skai_window_size','draws_used','draws_analyzed','skip_window','window_size','history_window','history_window_size','lookback_draws','training_window','used_window','best_window','tuned_window') as $k) {
            if (isset($settings[$k]) && is_numeric($settings[$k])) {
                $out['history'] = max(25.0, min(1000.0, (float)$settings[$k]));
                break;
            }
        }
        return $out;
    }
}

if (!function_exists('mylottoexpertV116LearningWeightFromRow')) {
    function mylottoexpertV116LearningWeightFromRow(array $row)
    {
        $cutoff = '2026-05-20';
        foreach (array('date_saved','created_at','evaluated_at','actual_draw_date','target_draw_date','next_draw_date','draw_date','result_draw_date') as $key) {
            $raw = trim((string)($row[$key] ?? ''));
            if ($raw === '' || strpos($raw, '0000-00-00') === 0) { continue; }
            $date = substr($raw, 0, 10);
            if (!preg_match('/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/', $date)) { continue; }
            return ($date < $cutoff) ? 0.35 : 1.0;
        }
        return 1.0;
    }
}

