        }

        $missingParts = array();
        if (empty($blend['complete'])) { $missingParts[] = 'Blend missing: ' . (string)$blend['missing']; }
        if (empty($hist['complete'])) { $missingParts[] = 'History windows missing: ' . (string)$hist['missing']; }
        if (!$outcomeSampleInitialMet) {
            $missingParts[] = 'Outcome validation still needs at least 27 scored prediction outcomes across 10 independent draw dates.';
        } elseif ($mapperEvidenceLimited) {
            $missingParts[] = 'Full outcome history is sufficient, but mapper setting prediction history is still limited to ' . number_format((int)$scored) . ' mapped row' . ($scored === 1 ? '' : 's') . ' across ' . number_format((int)$draws) . ' completed draw' . ($draws === 1 ? '' : 's') . '.';
        }
        if ($baselineNeedsMoreEvidence) {
            $missingParts[] = $baselineAvailable ? 'Edge vs Random is still below the minimum lift/z-score screen.' : 'Edge vs Random is still measuring because comparable predicted-number counts are incomplete.';
        }
        if ($avgHits < 2.5) { $missingParts[] = 'Average main-number hits are below the current precision-trust performance floor.'; }
        if ($repeatabilityLimited && $outcomeSampleInitialMet) { $missingParts[] = 'Settings repeatability/stability is still limited across independent draw dates.'; }
        $missing = empty($missingParts) ? 'No coverage gaps are currently blocking this status; final narrowing still depends on performance, edge, repeatability, and stability gates.' : implode(' | ', $missingParts);
        return array(
            'key'=>$key,
            'label'=>$label,
            'plain'=>$plain,
            'next'=>$next,
            'hive_line'=>$hiveLine,
            'personal_line'=>$personal,
            'coverage_score'=>$score,
            'scientific_score'=>$score,
            'raw_score'=>$rawScore,
            'cap'=>$cap,
            'score_line'=>$scoreLine,
            'component_line'=>$componentLine,
            'cap_line'=>$capLine,
            'component_scores'=>array(
                'coverage'=>$coverageComponent,
                'sample'=>$sampleComponent,
                'effect'=>$effectComponent,
                'repeatability'=>$repeatComponent,
                'stability'=>$stabilityComponent,
                'validation'=>$validationComponent,
            ),
            'blend_label'=>(string)$blend['label'],
            'blend_missing'=>(string)$blend['missing'],
            'blend_complete'=>!empty($blend['complete']),
            'history_label'=>(string)$hist['label'],
            'history_missing'=>(string)$hist['missing'],
            'history_complete'=>!empty($hist['complete']),
            'missing_line'=>$missing,
            'scored'=>$scored,
            'draws'=>$draws,
            'pending'=>$pending,
            'outcome_count'=>$outcomeCount,
            'outcome_draw_count'=>$outcomeDrawCount,
            'avg_hits'=>$avgHits,
            'row_avg_hits'=>$rowAvgHits,
            'avg_total_hits'=>$avgTotalHits,
            'random_expected_avg_hits'=>$randomExpectedAvgHits,
            'baseline_lift_pct'=>$baselineLiftPct,
            'baseline_z'=>$baselineZ,
            'baseline_rows'=>$baselineRows,
            'baseline_comparable_avg_hits'=>$baselineComparableAvgHits,
            'baseline_avg_predicted_main_count'=>$baselineAvgPredictedMainCount,
            'baseline_draws_used'=>$baselineDrawsUsedForDisplay,
            'baseline_se_method'=>$baselineSeMethod,
            'zero_hit_rate'=>$zeroRate,
            'three_plus_rate'=>$threePlusRate,
            'validation_stage'=>$validationStage,
            'validation_stage_detail'=>$validationStageDetail,
        );
    }
}


if (!function_exists('mylottoexpertV94LoadCanonicalSavedEvidenceTotals')) {
    function mylottoexpertV94LoadCanonicalSavedEvidenceTotals($db, array $card)
    {
        $out = array(
            'available' => false,
            'game_id' => '',
            'total_saved_rows' => 0,
            'scored_or_evaluated_rows' => 0,
            'pending_rows' => 0,
            'distinct_draw_dates' => 0,
            'skai_scored_rows' => 0,
            'avg_main_hits' => null,
            'avg_total_hits' => null,
            'line' => '',
        );
        if (!is_object($db)) { return $out; }
        $gameId = trim((string)($card['target_game_id'] ?? $card['game_id'] ?? ''));
        if ($gameId === '') { return $out; }
        try {
            $colsRaw = $db->getTableColumns('#__user_saved_numbers', false);
            $cols = is_array($colsRaw) ? array_keys($colsRaw) : array();
        } catch (\Throwable $e) {
            $cols = array();
        }
        if (empty($cols) || (!in_array('target_game_id', $cols, true) && !in_array('game_id', $cols, true))) { return $out; }
        $qn = array($db, 'quoteName');
        $q = array($db, 'quote');
        $table = $db->quoteName('#__user_saved_numbers');
        $has = static function($name) use ($cols) { return in_array((string)$name, $cols, true); };
        $gameWhereParts = array();
        if ($has('target_game_id')) { $gameWhereParts[] = "s." . $db->quoteName('target_game_id') . " = " . $db->quote($gameId); }
        if ($has('game_id')) { $gameWhereParts[] = "s." . $db->quoteName('game_id') . " = " . $db->quote($gameId); }
        $gameWhere = '(' . implode(' OR ', $gameWhereParts) . ')';
        $statusExpr = $has('evaluation_status') ? "LOWER(TRIM(COALESCE(s." . $db->quoteName('evaluation_status') . ",'')))" : "''";
        $scoredParts = array($statusExpr . " IN ('scored','evaluated','completed','saved_scored')");
        if ($has('evaluated_at')) { $scoredParts[] = "s." . $db->quoteName('evaluated_at') . " IS NOT NULL"; }
        if ($has('actual_draw_date')) { $scoredParts[] = "(s." . $db->quoteName('actual_draw_date') . " IS NOT NULL AND s." . $db->quoteName('actual_draw_date') . " <> '0000-00-00')"; }
        $scoredCond = '(' . implode(' OR ', $scoredParts) . ')';
        $dateCandidates = array();
        if ($has('target_draw_date')) { $dateCandidates[] = "NULLIF(DATE(s." . $db->quoteName('target_draw_date') . "),'0000-00-00')"; }
        if ($has('actual_draw_date')) { $dateCandidates[] = "NULLIF(DATE(s." . $db->quoteName('actual_draw_date') . "),'0000-00-00')"; }
        if ($has('next_draw_date')) { $dateCandidates[] = "NULLIF(DATE(s." . $db->quoteName('next_draw_date') . "),'0000-00-00')"; }
        $drawExpr = !empty($dateCandidates) ? ('COALESCE(' . implode(',', $dateCandidates) . ')') : "NULL";
        $skaiParts = array();
        if ($has('source')) { $skaiParts[] = "LOWER(TRIM(COALESCE(s." . $db->quoteName('source') . ",''))) LIKE '%skai%'"; }
        if ($has('origin_source')) { $skaiParts[] = "LOWER(TRIM(COALESCE(s." . $db->quoteName('origin_source') . ",''))) LIKE '%skai%'"; }
        if ($has('source_batch_type')) { $skaiParts[] = "LOWER(TRIM(COALESCE(s." . $db->quoteName('source_batch_type') . ",''))) LIKE '%skai%'"; }
        if ($has('source_batch_origin')) { $skaiParts[] = "LOWER(TRIM(COALESCE(s." . $db->quoteName('source_batch_origin') . ",''))) LIKE '%skai%'"; }
        $skaiCond = !empty($skaiParts) ? ('(' . implode(' OR ', $skaiParts) . ')') : '0=1';
        $avgMainExpr = $has('main_hits_count') ? ("AVG(CASE WHEN " . $scoredCond . " THEN COALESCE(s." . $db->quoteName('main_hits_count') . ",0) ELSE NULL END)") : "NULL";
        $avgTotalExpr = ($has('main_hits_count') && $has('extra_hits_count')) ? ("AVG(CASE WHEN " . $scoredCond . " THEN COALESCE(s." . $db->quoteName('main_hits_count') . ",0)+COALESCE(s." . $db->quoteName('extra_hits_count') . ",0) ELSE NULL END)") : "NULL";
        $sql = "SELECT COUNT(*) AS total_saved_rows, "
             . "SUM(CASE WHEN " . $scoredCond . " THEN 1 ELSE 0 END) AS scored_or_evaluated_rows, "
             . "SUM(CASE WHEN NOT " . $scoredCond . " THEN 1 ELSE 0 END) AS pending_rows, "
             . "COUNT(DISTINCT CASE WHEN " . $scoredCond . " THEN " . $drawExpr . " ELSE NULL END) AS distinct_draw_dates, "
             . "SUM(CASE WHEN " . $scoredCond . " AND " . $skaiCond . " THEN 1 ELSE 0 END) AS skai_scored_rows, "
             . $avgMainExpr . " AS avg_main_hits, "
             . $avgTotalExpr . " AS avg_total_hits "
             . "FROM " . $table . " s WHERE " . $gameWhere;
        try {
            $db->setQuery($sql);
            $row = (array)$db->loadAssoc();
            if (empty($row)) { return $out; }
            $out['available'] = true;
            $out['game_id'] = $gameId;
            $out['total_saved_rows'] = max(0, (int)($row['total_saved_rows'] ?? 0));
            $out['scored_or_evaluated_rows'] = max(0, (int)($row['scored_or_evaluated_rows'] ?? 0));
            $out['pending_rows'] = max(0, (int)($row['pending_rows'] ?? 0));
            $out['distinct_draw_dates'] = max(0, (int)($row['distinct_draw_dates'] ?? 0));
            $out['skai_scored_rows'] = max(0, (int)($row['skai_scored_rows'] ?? 0));
            $out['avg_main_hits'] = is_numeric($row['avg_main_hits'] ?? null) ? (float)$row['avg_main_hits'] : null;
            $out['avg_total_hits'] = is_numeric($row['avg_total_hits'] ?? null) ? (float)$row['avg_total_hits'] : null;
            $line = 'Full saved history for canonical game ' . $gameId . ': ' . number_format((int)$out['scored_or_evaluated_rows']) . ' scored/evaluated prediction row' . ((int)$out['scored_or_evaluated_rows'] === 1 ? '' : 's') . ' across ' . number_format((int)$out['distinct_draw_dates']) . ' draw date' . ((int)$out['distinct_draw_dates'] === 1 ? '' : 's') . ' from ' . number_format((int)$out['total_saved_rows']) . ' saved row' . ((int)$out['total_saved_rows'] === 1 ? '' : 's') . '.';
            if ((int)$out['skai_scored_rows'] > 0) { $line .= ' AI-tagged scored rows: ' . number_format((int)$out['skai_scored_rows']) . '.'; }
            if ($out['avg_main_hits'] !== null) { $line .= ' Full-history row avg main hits: ' . number_format((float)$out['avg_main_hits'], 2) . '.'; }
            $out['line'] = $line;
        } catch (\Throwable $e) {
            return array('available'=>false, 'game_id'=>$gameId, 'error'=>'saved_history_query_failed');
        }
        return $out;
    }
}

if (!function_exists('mylottoexpertResolveUserActionState')) {
    function mylottoexpertResolveUserActionState($pendingRuns, $hasRecommendedAction, $scoredRuns, $checkedRuns, $methodTrack)
    {
        $pendingRuns = max(0, (int)$pendingRuns);
        $hasRecommendedAction = !empty($hasRecommendedAction);
        $scoredRuns = max(0, (int)$scoredRuns);
        $checkedRuns = max(0, (int)$checkedRuns);
        $methodTrack = trim((string)$methodTrack);
        if ($methodTrack === '') { $methodTrack = 'selected track'; }

        if ($pendingRuns > 0) {
            return array(
                'type' => 'pending',
                'label' => 'In Progress',
                'detail' => (string)$pendingRuns . ' pending run' . ($pendingRuns === 1 ? '' : 's') . ' waiting for the next official draw result.',
                'priority' => 1000 + $pendingRuns,
                'cta' => 'Review pending runs',
                'target_kind' => 'pending'
            );
        }
        if ($hasRecommendedAction) {
            return array(
                'type' => 'action',
                'label' => 'Action Ready',
                'detail' => $methodTrack . ' has a recommended controlled test ready or forming.',
                'priority' => 850 + $scoredRuns,
                'cta' => 'Open ready action',
                'target_kind' => 'recommended'
            );
        }
        if ($checkedRuns <= 0 && $scoredRuns <= 0) {
            return array(
                'type' => 'action',
                'label' => 'Start Prediction History',
                'detail' => 'No completed prediction history yet. Start with regular saved runs for the active track, then score after the draw.',
                'priority' => 700,
                'cta' => 'Open first step',
                'target_kind' => 'start'
            );
        }
        return array(
            'type' => 'action',
            'label' => 'Run Next Prediction',
            'detail' => 'No runs are currently pending for the next draw. Create fresh saved runs so LottoExpert has new prediction history to score after the draw.',
            'priority' => 600 + $scoredRuns,
            'cta' => 'Run next prediction',
            'target_kind' => 'run_next'
        );
    }
}

function mleAdvisoryLoadAllLotteryCards($db, $userId, $selectedLotteryId = 0, $loadAllFullCards = false) {
    $t0 = microtime(true);
    $firstLoadStartMs = (int)round($t0 * 1000);
    $userId = (int)$userId;
    $selectedLotteryId = (int)$selectedLotteryId;
    $loadAllFullCards = !empty($loadAllFullCards);
    if ($userId <= 0) {
        return array('has_any_data'=>false,'cards'=>array(),'selector_cards'=>array(),'selected_card'=>array(),'selected_lottery_id'=>0,'total_lotteries'=>0);
    }
    // [[MLE_V1_FIRST_LOAD_ACTIVE_EVIDENCE_CAP]]
    // Normal user first-load must not hydrate the entire saved-number history before first paint.
    // Reuse the existing performance profile limit when available; full workspace keeps the uncapped behavior.
    $__mleFirstLoadActiveLimit = 0;
    if (!$loadAllFullCards) {
        try {
            $__mleFirstLoadProfile = array();
            if (function_exists('mylottoexpertBuildPerformanceProfile')) {
                $__mleFirstLoadProfile = mylottoexpertBuildPerformanceProfile(\Joomla\CMS\Factory::getApplication());
            }
            $__mleFirstLoadActiveLimit = (int)($__mleFirstLoadProfile['saved_prediction_limit'] ?? 300);
            if ($__mleFirstLoadActiveLimit <= 0) { $__mleFirstLoadActiveLimit = 300; }
            $__mleFirstLoadActiveLimit = min(300, max(120, $__mleFirstLoadActiveLimit));
        } catch (\Throwable $__mleFirstLoadLimitEx) {
            $__mleFirstLoadActiveLimit = 300;
        }
    }
    $active = mleAdvisoryBuildActiveSavedEvidence($db, $userId, 0, $__mleFirstLoadActiveLimit);
    if (empty($active)) {
        return array('has_any_data'=>false,'cards'=>array(),'selector_cards'=>array(),'selected_card'=>array(),'selected_lottery_id'=>0,'total_lotteries'=>0);
    }
    $__mleFirstLoadReconcile = array('changed'=>false,'saved_rows'=>0,'skipped_first_load'=>!$loadAllFullCards);
    if ($loadAllFullCards && function_exists('mylottoexpertFirstLoadReconcileDuePendingRows')) {
        try {
            $__mleFirstLoadReconcile = mylottoexpertFirstLoadReconcileDuePendingRows($db, $userId, $active, 20);
            if (!empty($__mleFirstLoadReconcile['changed'])) {
                $active = mleAdvisoryBuildActiveSavedEvidence($db, $userId, 0, 0);
            }
        } catch (\Throwable $__mleFirstLoadReconcileEx) {
            $__mleFirstLoadReconcile = array('changed'=>false,'saved_rows'=>0,'error'=>'first_load_reconcile_failed');
        }
    }
    $selectorCards = array();
    $selectorByLottery = array();
    foreach ($active as $lid => $data) {
        $summaryCard = mleAdvisorySummarizeActiveLotteryBucket((array)$data);
        $selectorCards[] = $summaryCard;
        $selectorByLottery[(int)($summaryCard['lottery_id'] ?? 0)] = $summaryCard;
    }
    if ($selectedLotteryId <= 0 || !isset($active[$selectedLotteryId])) {
        foreach ($active as $lid => $data) { $selectedLotteryId = (int)$lid; break; }
    }
    $cards = array();
    $selectedCard = array();
    $selectedCardElapsedMs = 0;
    $timeoutGuardTriggered = false;
    $forcedFastMode = false;
    if ($loadAllFullCards) {
        foreach ($active as $lid => $data) {
            $cardStart = microtime(true);
            $card = mleAdvisoryBuildLotteryCard($db, $userId, (int)$lid, (string)($data['lottery_name'] ?? ''), $active);
            if (is_array($card) && !empty($card)) { $card = mylottoexpertSyncCardPendingCount($card, $db, $userId); }
            $cardMs = (int)round((microtime(true) - $cardStart) * 1000);
            if ($cardMs >= 5000) {
                mleAdvisoryLogPerfTiming('lottery_card_query', array('elapsed_ms' => $cardMs, 'user_id' => $userId, 'lottery_id' => (int)$lid, 'game_id' => (string)($card['game_id'] ?? ''), 'row_count' => (int)($card['stats']['total_runs'] ?? 0), 'request_mode' => 'full_workspace'));
            }
            if (!empty($card['has_data'])) {
                $cards[] = $card;
                $selectorByLottery[(int)$lid] = $card;
                foreach ($selectorCards as $__mleSelIdx => $__mleSelCard) {
                    if ((int)($__mleSelCard['lottery_id'] ?? 0) === (int)$lid) { $selectorCards[$__mleSelIdx] = $card; break; }
                }
                unset($__mleSelIdx, $__mleSelCard);
                if ((int)$lid === $selectedLotteryId) { $selectedCard = $card; }
            }
        }
    } elseif ($selectedLotteryId > 0 && isset($active[$selectedLotteryId])) {
        $selectedSummary = isset($selectorByLottery[$selectedLotteryId]) ? (array)$selectorByLottery[$selectedLotteryId] : array();
        $selectedSlowSessionKey = 'mle_fast_mode_lottery_' . (int)$selectedLotteryId;
        if (isset($_SESSION[$selectedSlowSessionKey])) { unset($_SESSION[$selectedSlowSessionKey]); }
        $forcedFastMode = true;
        $selectedStart = microtime(true);
        // [[MLE_V78_GLOBAL_FIRST_LOAD_FAST_CARD_FLAG]]
        // Build only a lightweight selected card on dashboard first-load. This applies to all lotteries.
        $__mlePrevFastCardMode = array_key_exists('mle_first_load_fast_card_mode', $GLOBALS) ? $GLOBALS['mle_first_load_fast_card_mode'] : null;
        $GLOBALS['mle_first_load_fast_card_mode'] = true;
        try {
            $selectedCard = mleAdvisoryBuildLotteryCard($db, $userId, (int)$selectedLotteryId, (string)($active[$selectedLotteryId]['lottery_name'] ?? ''), $active);
        } catch (\Throwable $__mleV78FastCardEx) {
            $selectedCard = $selectedSummary;
            if (is_array($selectedCard)) {
                $selectedCard['mle_first_load_fast_card'] = 1;
                $selectedCard['mle_forced_fast_mode'] = true;
                $selectedCard['mle_timeout_guard_triggered'] = true;
            }
        }
        if ($__mlePrevFastCardMode === null) { unset($GLOBALS['mle_first_load_fast_card_mode']); }
        else { $GLOBALS['mle_first_load_fast_card_mode'] = $__mlePrevFastCardMode; }
        unset($__mlePrevFastCardMode);
        $selectedMs = (int)round((microtime(true) - $selectedStart) * 1000);
        $selectedCardElapsedMs = $selectedMs;
        mleAdvisoryLogPerfTiming('selected_lottery_card_query', array('elapsed_ms' => $selectedMs, 'user_id' => $userId, 'lottery_id' => $selectedLotteryId, 'game_id' => (string)($selectedCard['game_id'] ?? ''), 'row_count' => (int)($selectedCard['stats']['total_runs'] ?? 0), 'request_mode' => 'first_load', 'selected_lottery_id' => $selectedLotteryId, 'active_lottery_count' => count($selectorCards), 'selected_card_elapsed_ms' => $selectedMs));
        if ($selectedMs >= 5000) {
            mleAdvisoryLogPerfTiming('slow_selected_lottery_card_query', array('elapsed_ms' => $selectedMs, 'user_id' => $userId, 'lottery_id' => $selectedLotteryId, 'game_id' => (string)($selectedCard['game_id'] ?? ''), 'row_count' => (int)($selectedCard['stats']['total_runs'] ?? 0), 'request_mode' => 'first_load', 'selected_lottery_id' => $selectedLotteryId, 'active_lottery_count' => count($selectorCards), 'selected_card_elapsed_ms' => $selectedMs, 'timeout_guard_triggered' => false, 'slow_query_label' => 'selected_lottery_card_query_logged_only'));
        }
        if (!empty($selectedCard['has_data'])) {
            $selectedCard['mle_forced_fast_mode'] = true;
            $selectedCard['mle_timeout_guard_triggered'] = false;
            // [[MLE_V78_SKIP_FIRST_LOAD_PENDING_DB_SYNC]]
            // First-load fast cards use the preloaded active bucket counts. The heavier canonical DB sync remains available in full/detail loads.
            $cards[] = $selectedCard;
            $selectorByLottery[(int)$selectedLotteryId] = $selectedCard;
            foreach ($selectorCards as $__mleSelIdx => $__mleSelCard) {
                if ((int)($__mleSelCard['lottery_id'] ?? 0) === (int)$selectedLotteryId) { $selectorCards[$__mleSelIdx] = $selectedCard; break; }
            }
            unset($__mleSelIdx, $__mleSelCard);
        } else {
            $selectedCard = array();
        }
    }
    $totalMs = (int)round((microtime(true) - $t0) * 1000);
    mleAdvisoryLogPerfTiming('first_load_start', array('elapsed_ms' => 1, 'user_id' => $userId, 'lottery_id' => $selectedLotteryId, 'row_count' => count($selectorCards), 'request_mode' => $loadAllFullCards ? 'full_workspace' : 'first_load', 'first_load_start' => $firstLoadStartMs, 'selected_lottery_id' => $selectedLotteryId, 'active_lottery_count' => count($selectorCards), 'selected_card_elapsed_ms' => $selectedCardElapsedMs, 'forced_fast_mode' => $forcedFastMode, 'timeout_guard_triggered' => $timeoutGuardTriggered));
    mleAdvisoryLogPerfTiming('first_load_total', array('elapsed_ms' => $totalMs, 'user_id' => $userId, 'lottery_id' => $selectedLotteryId, 'row_count' => count($selectorCards), 'request_mode' => $loadAllFullCards ? 'full_workspace' : 'first_load', 'first_load_total_elapsed_ms' => $totalMs, 'selected_lottery_id' => $selectedLotteryId, 'active_lottery_count' => count($selectorCards), 'selected_card_elapsed_ms' => $selectedCardElapsedMs, 'forced_fast_mode' => $forcedFastMode, 'timeout_guard_triggered' => $timeoutGuardTriggered));
    mleAdvisoryLogPerfTiming('first_load_end', array('elapsed_ms' => 1, 'user_id' => $userId, 'lottery_id' => $selectedLotteryId, 'row_count' => count($selectorCards), 'request_mode' => $loadAllFullCards ? 'full_workspace' : 'first_load', 'first_load_end' => (int)round(microtime(true) * 1000), 'first_load_total_elapsed_ms' => $totalMs, 'selected_lottery_id' => $selectedLotteryId, 'active_lottery_count' => count($selectorCards), 'selected_card_elapsed_ms' => $selectedCardElapsedMs, 'forced_fast_mode' => $forcedFastMode, 'timeout_guard_triggered' => $timeoutGuardTriggered));
    return array(
        'has_any_data' => !empty($selectorCards),
        'cards' => $cards,
        'selector_cards' => $selectorCards,
        'selected_card' => $selectedCard,
        'selected_lottery_id' => (int)$selectedLotteryId,
        'total_lotteries' => count($selectorCards),
        'forced_fast_mode' => $forcedFastMode ? 1 : 0,
        'timeout_guard_triggered' => $timeoutGuardTriggered ? 1 : 0
    );
}

function mylottoexpertEnsureCurrentLockedSettingsTable($db) {
    $prefix = $db->getPrefix();
    $table = $prefix . 'mle_current_locked_settings';
    $sql = "CREATE TABLE IF NOT EXISTS `{$table}` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT 0,
  `lottery_id` int(11) NOT NULL DEFAULT 0,
  `lottery_name` varchar(191) NOT NULL DEFAULT '',
  `source` varchar(64) NOT NULL DEFAULT '',
  `method` varchar(64) NOT NULL DEFAULT '',
  `base_run_id` int(11) NOT NULL DEFAULT 0,
  `base_settings_id` int(11) NOT NULL DEFAULT 0,
  `settings_json` mediumtext,
  `locked_status` varchar(64) NOT NULL DEFAULT 'Not Ready',
  `recommendation_level` varchar(100) NOT NULL DEFAULT '',
  `precision_progress_level` varchar(100) NOT NULL DEFAULT '',
  `precision_lock_stage` varchar(64) NOT NULL DEFAULT '',
  `range_basis` varchar(100) NOT NULL DEFAULT '',
  `range_min` decimal(10,4) NOT NULL DEFAULT 0,
  `range_max` decimal(10,4) NOT NULL DEFAULT 100,
  `evidence_summary` text,
  `locked_reason` text,
  `repeated_cluster_key` varchar(255) NOT NULL DEFAULT '',
  `repeated_cluster_count` int(11) NOT NULL DEFAULT 0,
  `completed_draw_count` int(11) NOT NULL DEFAULT 0,
  `strong_evidence_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_lottery_active` (`user_id`,`lottery_id`,`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci";
    try { $db->setQuery($sql); $db->execute(); } catch (\Throwable $e) { }
}

function mleAdvisoryLoadCurrentLockedSettings($db, $userId, $lotteryId) {
    $userId = (int)$userId; $lotteryId = (int)$lotteryId;
    if ($userId <= 0 || $lotteryId <= 0) { return array(); }
    mylottoexpertEnsureCurrentLockedSettingsTable($db);
    try {
        $q = $db->getQuery(true)->select('*')->from($db->quoteName('#__mle_current_locked_settings'))->where($db->quoteName('user_id') . ' = ' . $userId)->where($db->quoteName('lottery_id') . ' = ' . $lotteryId)->where($db->quoteName('is_active') . ' = 1')->order($db->quoteName('updated_at') . ' DESC');
        $db->setQuery($q, 0, 1);
        $row = $db->loadAssoc();
        if (!is_array($row) || empty($row)) { return array(); }
        $settings = array();
        if (isset($row['settings_json']) && trim((string)$row['settings_json']) !== '') { $tmp = json_decode((string)$row['settings_json'], true); if (is_array($tmp)) { $settings = $tmp; } }
        $row['settings_array'] = $settings;
        $row['has_active_lock'] = true;
        $row['status'] = (string)($row['locked_status'] ?? '');
        $row['reason'] = (string)($row['locked_reason'] ?? '');
        $row['last_updated'] = (string)($row['updated_at'] ?? '');
        return $row;
    } catch (\Throwable $e) { return array(); }
}

