    $__resetConfirm = (string)$app->input->post->getString('clear_confirm', '');
    $__resetResult = function_exists('mylottoexpertV170ClearUnsavedGameQueueWork') ? mylottoexpertV170ClearUnsavedGameQueueWork($db, $__resetUser, $__resetGameKey, $__resetConfirm) : array('ok'=>false,'message'=>'Waiting predictions clear function is missing.');
    if (!empty($__resetResult['ok'])) {
