if ($__mleAction === 'clear_stuck_skai_batch') {
    if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
        $app->enqueueMessage('Session expired. Please refresh and try again.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if ($workspaceUserId <= 0) {
        $app->enqueueMessage('You must be logged in to clear a batch.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrBatchId   = $app->input->post->getInt('batch_id', 0);
    $__clrLotteryId = $app->input->post->getInt('lottery_id', 0);
    $__clrMode      = strtolower(trim((string)$app->input->post->getString('clear_mode', '')));
    $__clrAllowedModes = array('cancel_empty', 'abandon_empty', 'abandon_partial', 'hard_delete_empty_admin_only');
    if ($__clrBatchId <= 0 || $__clrLotteryId <= 0 || !in_array($__clrMode, $__clrAllowedModes, true)) {
        $app->enqueueMessage('Clear batch request is missing required parameters.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrUser = \Joomla\CMS\Factory::getUser();
    $__clrIsAdmin = (!$__clrUser->guest && $__clrUser->authorise('core.admin'));
    $__clrPrefix = $db->getPrefix();
    $__clrHeaderTable = $__clrPrefix . 'mle_skai_batch_header';
    $__clrRunTable    = $__clrPrefix . 'mle_skai_batch_run';
    if (!mylottoexpertTableExistsByRawName($db, $__clrHeaderTable) || !mylottoexpertTableExistsByRawName($db, $__clrRunTable)) {
        $app->enqueueMessage('Batch tables are not available.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    try {
        $__clrHq = $db->getQuery(true)
            ->select('*')
            ->from($db->quoteName('#__mle_skai_batch_header'))
            ->where($db->quoteName('id') . ' = ' . $__clrBatchId);
        if (!$__clrIsAdmin) {
            $__clrHq->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);
        }
        $db->setQuery($__clrHq, 0, 1);
        $__clrHeader = $db->loadAssoc();
    } catch (\Throwable $e) {
        $__clrHeader = array();
    }
    if (!is_array($__clrHeader) || empty($__clrHeader)) {
        $app->enqueueMessage('Batch not found or you do not have permission to clear it.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if ((int)($__clrHeader['lottery_id'] ?? 0) !== $__clrLotteryId) {
        $app->enqueueMessage('Batch lottery context mismatch. Clear action aborted.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrBatchOwner = (int)($__clrHeader['user_id'] ?? 0);
    if (!$__clrIsAdmin && $__clrBatchOwner !== (int)$workspaceUserId) {
        $app->enqueueMessage('You do not have permission to clear this batch.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrOldStatus = strtolower(trim((string)($__clrHeader['status'] ?? 'pending')));
    if (function_exists('mylottoexpertSkaiBatchTerminalStatuses') && in_array($__clrOldStatus, mylottoexpertSkaiBatchTerminalStatuses(), true)) {
        $app->enqueueMessage('This batch is already in a terminal status: ' . htmlspecialchars($__clrOldStatus, ENT_QUOTES, 'UTF-8') . '.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrSaveCounts = mylottoexpertCountGeneratedPrecisionBatchSaves($db, $__clrBatchOwner, $__clrLotteryId, $__clrBatchId);
    $__clrSavedCount = (int)($__clrSaveCounts['saved_count'] ?? 0);
    if ($__clrMode === 'hard_delete_empty_admin_only' && !$__clrIsAdmin) {
        $app->enqueueMessage('Hard delete requires Super User access.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if (in_array($__clrMode, array('cancel_empty', 'abandon_empty', 'hard_delete_empty_admin_only'), true) && $__clrSavedCount > 0) {
        $app->enqueueMessage('This clear mode requires saved_row_count = 0. This batch has ' . (int)$__clrSavedCount . ' saved rows. Use abandon_partial instead.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if ($__clrMode === 'abandon_partial' && ($__clrSavedCount < 1 || $__clrSavedCount > 8)) {
        $app->enqueueMessage('abandon_partial requires saved_row_count between 1 and 8. Found: ' . (int)$__clrSavedCount . '.', 'error');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    $__clrNewHeaderStatus = 'cancelled';
    $__clrNewRunStatus    = 'cancelled';
    if ($__clrMode === 'abandon_empty') {
        $__clrNewHeaderStatus = 'abandoned';
        $__clrNewRunStatus    = 'abandoned';
    } elseif ($__clrMode === 'abandon_partial') {
        $__clrNewHeaderStatus = 'partial_abandoned';
        $__clrNewRunStatus    = 'partial_abandoned';
    }
    try {
        $db->transactionStart();
        if ($__clrMode === 'hard_delete_empty_admin_only') {
            $db->setQuery($db->getQuery(true)->delete($db->quoteName('#__mle_skai_batch_run'))->where($db->quoteName('batch_id') . ' = ' . $__clrBatchId));
            $db->execute();
            $db->setQuery($db->getQuery(true)->delete($db->quoteName('#__mle_skai_batch_header'))->where($db->quoteName('id') . ' = ' . $__clrBatchId));
            $db->execute();
        } else {
            $__clrHeaderCols = mylottoexpertGetTableColumnNames($db, '#__mle_skai_batch_header');
            if (in_array('status', $__clrHeaderCols, true)) {
                $__clrUq = $db->getQuery(true)
                    ->update($db->quoteName('#__mle_skai_batch_header'))
                    ->set($db->quoteName('status') . ' = ' . $db->quote($__clrNewHeaderStatus))
                    ->where($db->quoteName('id') . ' = ' . $__clrBatchId);
                $db->setQuery($__clrUq);
                $db->execute();
            }
            $__clrRunCols = mylottoexpertGetTableColumnNames($db, '#__mle_skai_batch_run');
            if (in_array('status', $__clrRunCols, true)) {
                $__clrRunUq = $db->getQuery(true)
                    ->update($db->quoteName('#__mle_skai_batch_run'))
                    ->set($db->quoteName('status') . ' = ' . $db->quote($__clrNewRunStatus))
                    ->where($db->quoteName('batch_id') . ' = ' . $__clrBatchId);
                if ($__clrMode === 'abandon_partial') {
                    $__clrRunUq->where($db->quoteName('status') . ' NOT IN (' . $db->quote('generated') . ',' . $db->quote('completed') . ',' . $db->quote('saved') . ',' . $db->quote('scored') . ')');
                }
                $db->setQuery($__clrRunUq);
                $db->execute();
            }
        }
        $db->transactionCommit();
        $__clrSuccess = true;
    } catch (\Throwable $e) {
        try { $db->transactionRollback(); } catch (\Throwable $re) {}
        $__clrSuccess = false;
        error_log('[MLE BATCH RECOVERY] clear_stuck_skai_batch error: ' . $e->getMessage() . ' batch_id=' . $__clrBatchId);
    }
    $__clrLogEntry = date('Y-m-d H:i:s') . ' | acting_user_id=' . (int)$workspaceUserId . ' | target_batch_id=' . $__clrBatchId . ' | target_batch_user_id=' . $__clrBatchOwner . ' | lottery_id=' . $__clrLotteryId . ' | old_status=' . $__clrOldStatus . ' | new_status=' . ($__clrMode === 'hard_delete_empty_admin_only' ? 'HARD_DELETED' : $__clrNewHeaderStatus) . ' | saved_row_count=' . $__clrSavedCount . ' | action=' . $__clrMode . ' | success=' . ($__clrSuccess ? '1' : '0') . "\n";
    $__clrLogFile = JPATH_ADMINISTRATOR . '/logs/mylottoexpert_batch_recovery.log';
    @file_put_contents($__clrLogFile, $__clrLogEntry, FILE_APPEND | LOCK_EX);
    if ($__clrSuccess) {
        $__clrModeLabel = array('cancel_empty' => 'cancelled', 'abandon_empty' => 'marked abandoned', 'abandon_partial' => 'marked partial abandoned', 'hard_delete_empty_admin_only' => 'hard deleted');
        $app->enqueueMessage('Settings Test Group #' . $__clrBatchId . ' was ' . ($__clrModeLabel[$__clrMode] ?? 'cleared') . ' successfully.', 'message');
    } else {
        $app->enqueueMessage('Settings Test Group #' . $__clrBatchId . ' could not be cleared due to a database error. See site error log for details.', 'error');
    }
    $__clrRedirect = \Joomla\CMS\Uri\Uri::getInstance();
    $__clrRedirect->delVar('mle_action');
    $__clrRedirect->delVar('batch_id');
    $__clrRedirect->delVar('lottery_id');
    $__clrRedirect->delVar('clear_mode');
    $app->redirect((string)$__clrRedirect);
    return;
}

if ($__mleAction === 'update_advice_status') {
    $app->setHeader('Content-Type', 'application/json; charset=utf-8', true);
    if (!\Joomla\CMS\Session\Session::checkToken('post')) {
        echo json_encode(array('ok' => false, 'error' => 'Invalid token.'));
        exit;
    }
    if (MLE_DEMO_MODE) {
        echo json_encode(array('ok' => false, 'error' => 'Demo mode.'));
        exit;
    }
    $actionUser = \Joomla\CMS\Factory::getUser();
    $actionUserId = (int)(is_object($actionUser) ? $actionUser->get('id') : 0);
    if ($actionUserId <= 0) {
        echo json_encode(array('ok' => false, 'error' => 'Not logged in.'));
        exit;
    }

    $savedId = (int)$app->input->post->getInt('run_id', 0);
    $normalizedAction = mylottoexpertNormalizeAdviceStatusAction($app->input->post->getString('status', ''));
    if ($savedId <= 0 || $normalizedAction === '' || mylottoexpertIsAdminOnlyAdviceAction($normalizedAction)) {
        echo json_encode(array('ok' => false, 'error' => 'Invalid status action.'));
        exit;
    }
    if (!mylottoexpertCanPerformAdviceStatusAction($db, $actionUser, $savedId, $normalizedAction)) {
        echo json_encode(array('ok' => false, 'error' => 'Not authorized.'));
        exit;
    }

    try {
        mleAdvisoryEnsureSchemaColumns($db);
        $targetUserId = $actionUserId;
        if (method_exists($actionUser, 'authorise') && $actionUser->authorise('core.admin')) {
            $qOwner = $db->getQuery(true)
                ->select($db->quoteName('user_id'))
                ->from($db->quoteName('#__myle_saved_predictions'))
                ->where($db->quoteName('id') . ' = ' . (int)$savedId)
                ->setLimit(1);
            $db->setQuery($qOwner);
            $targetUserId = (int)$db->loadResult();
        }

        $statusSql = $db->quote($normalizedAction);
        $qSave = $db->getQuery(true)
            ->update($db->quoteName('#__myle_saved_predictions'))
            ->set($db->quoteName('advice_status') . ' = ' . $statusSql)
            ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
            ->set($db->quoteName('status_explicit') . ' = 1')
            ->where($db->quoteName('id') . ' = ' . (int)$savedId)
            ->where($db->quoteName('is_deleted') . ' = 0');
        if ($targetUserId > 0) {
            $qSave->where($db->quoteName('user_id') . ' = ' . (int)$targetUserId);
        }
        $db->setQuery($qSave);
        $db->execute();
        if ((int)$db->getAffectedRows() < 1) {
            echo json_encode(array('ok' => false, 'error' => 'Run not found.'));
            exit;
        }

        try {
            $qLp = $db->getQuery(true)
                ->update($db->quoteName('#__myle_learning_performance'))
                ->set($db->quoteName('advice_status') . ' = ' . $statusSql)
                ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                ->set($db->quoteName('status_explicit') . ' = 1')
                ->where($db->quoteName('saved_prediction_id') . ' = ' . (int)$savedId);
            if ($targetUserId > 0) {
                $qLp->where($db->quoteName('user_id') . ' = ' . (int)$targetUserId);
            }
            $db->setQuery($qLp);
            $db->execute();
        } catch (\Throwable $ignoreMirror) {
        }

        echo json_encode(array(
            'ok' => true,
            'status' => $normalizedAction,
            'stored' => $normalizedAction
        ));
    } catch (\Throwable $e) {
        error_log('[MLE Advisory] update_advice_status error: ' . $e->getMessage());
        echo json_encode(array('ok' => false, 'error' => 'Database error.'));
    }
    exit;
}

if ($__mleAction === 'bulk_run_selection_action') {
    $hasDecision = trim((string)$app->input->post->getString('decision', '')) !== '';
    $postedRunIds = (array)$app->input->post->get('run_ids', array(), 'array');
    $postedRunIdsCsv = trim((string)$app->input->post->getString('run_ids_csv', ''));
    if ($hasDecision || !empty($postedRunIds) || $postedRunIdsCsv !== '') {
        if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
            $app->enqueueMessage('Session expired. Please refresh and try again.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }
        if (MLE_DEMO_MODE) {
            $app->enqueueMessage('Demo mode: Cannot apply bulk run selection actions.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }
        $actionUser = \Joomla\CMS\Factory::getUser();
        $actionUserId = (int)(is_object($actionUser) ? $actionUser->get('id') : 0);
        $isActionAdmin = is_object($actionUser) && method_exists($actionUser, 'authorise') && $actionUser->authorise('core.admin');
        if ($actionUserId <= 0) {
            $app->enqueueMessage('Please log in to apply bulk run selection actions.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $normalizedAction = mylottoexpertNormalizeAdviceStatusAction($app->input->post->getString('decision', ''));
        if ($normalizedAction === '') {
            $app->enqueueMessage('Invalid bulk action.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }
        if (mylottoexpertIsAdminOnlyAdviceAction($normalizedAction) && !$isActionAdmin) {
            $app->enqueueMessage('Not authorized.', 'error');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $runIds = array();
        foreach ($postedRunIds as $rid) {
            $rid = (int)$rid;
            if ($rid > 0) {
                $runIds[$rid] = $rid;
            }
        }
        if ($postedRunIdsCsv !== '') {
            foreach (explode(',', $postedRunIdsCsv) as $part) {
                $rid = (int)trim($part);
                if ($rid > 0) {
                    $runIds[$rid] = $rid;
                }
            }
        }
        $selectedSavedIds = (array)$app->input->post->get('selected_saved_ids', array(), 'array');
        foreach ($selectedSavedIds as $rid) {
            $rid = (int)$rid;
            if ($rid > 0) {
                $runIds[$rid] = $rid;
            }
        }
        $runIds = array_values($runIds);
        if (empty($runIds)) {
            $app->enqueueMessage('No rows selected.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $allowedIds = array();
        foreach ($runIds as $savedId) {
            if (mylottoexpertCanPerformAdviceStatusAction($db, $actionUser, $savedId, $normalizedAction)) {
                $allowedIds[$savedId] = $savedId;
            }
        }
        $allowedIds = array_values($allowedIds);
        if (empty($allowedIds)) {
            $app->enqueueMessage('No selected runs were eligible for this action.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        try {
            mleAdvisoryEnsureSchemaColumns($db);
            $in = implode(',', array_map('intval', $allowedIds));
            if ($normalizedAction === 'delete_permanently') {
                $qDel = $db->getQuery(true)
                    ->update($db->quoteName('#__myle_saved_predictions'))
                    ->set($db->quoteName('is_deleted') . ' = 1')
                    ->set($db->quoteName('advice_status') . ' = ' . $db->quote('exclude'))
                    ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                    ->set($db->quoteName('status_explicit') . ' = 1')
                    ->set($db->quoteName('updated_at') . ' = NOW()')
                    ->where($db->quoteName('is_deleted') . ' = 0')
                    ->where($db->quoteName('id') . ' IN (' . $in . ')');
                if (!$isActionAdmin) {
                    $qDel->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId);
                }
                $db->setQuery($qDel);
                $db->execute();
                $changed = max(0, (int)$db->getAffectedRows());

                try {
                    $qLp = $db->getQuery(true)
                        ->update($db->quoteName('#__myle_learning_performance'))
                        ->set($db->quoteName('advice_status') . ' = ' . $db->quote('exclude'))
                        ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                        ->set($db->quoteName('status_explicit') . ' = 1')
                        ->where($db->quoteName('saved_prediction_id') . ' IN (' . $in . ')');
                    if (!$isActionAdmin) {
                        $qLp->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId);
                    }
                    $db->setQuery($qLp);
                    $db->execute();
                } catch (\Throwable $ignoreLp) {
                }

                $app->enqueueMessage('Rows permanently deleted: ' . (int)$changed, 'message');
            } else {
                $qSave = $db->getQuery(true)
                    ->update($db->quoteName('#__myle_saved_predictions'))
                    ->set($db->quoteName('advice_status') . ' = ' . $db->quote($normalizedAction))
                    ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                    ->set($db->quoteName('status_explicit') . ' = 1')
                    ->set($db->quoteName('updated_at') . ' = NOW()')
                    ->where($db->quoteName('is_deleted') . ' = 0')
                    ->where($db->quoteName('id') . ' IN (' . $in . ')');
                if (!$isActionAdmin) {
                    $qSave->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId);
                }
                $db->setQuery($qSave);
                $db->execute();
                $changed = max(0, (int)$db->getAffectedRows());

                try {
                    $qLp = $db->getQuery(true)
                        ->update($db->quoteName('#__myle_learning_performance'))
                        ->set($db->quoteName('advice_status') . ' = ' . $db->quote($normalizedAction))
                        ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                        ->set($db->quoteName('status_explicit') . ' = 1')
                        ->where($db->quoteName('saved_prediction_id') . ' IN (' . $in . ')');
                    if (!$isActionAdmin) {
                        $qLp->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId);
                    }
                    $db->setQuery($qLp);
                    $db->execute();
                } catch (\Throwable $ignoreLp) {
                }

                $labels = array(
                    'consider' => 'Use for future advice',
                    'review' => 'Keep for review',
                    'exclude' => 'Exclude from advice'
                );
                $label = isset($labels[$normalizedAction]) ? $labels[$normalizedAction] : 'Updated';
                $app->enqueueMessage($label . ': ' . (int)$changed, 'message');
            }
        } catch (\Throwable $e) {
            $app->enqueueMessage('Bulk update failed.', 'error');
        }

        $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
        $__cleanRedirectUri->delVar('mle_action');
        $app->redirect($__cleanRedirectUri->toString());
        return;
    }

    $__mleV135CanManageLearningStatus = false;
    try {
        $__mleV135ActionUser = \Joomla\CMS\Factory::getUser();
        $__mleV135CanManageLearningStatus = is_object($__mleV135ActionUser) && method_exists($__mleV135ActionUser, 'authorise') && $__mleV135ActionUser->authorise('core.admin');
    } catch (\Throwable $__mleV135GateEx) {
        $__mleV135CanManageLearningStatus = false;
    }
    if (!$__mleV135CanManageLearningStatus) {
        $app->enqueueMessage('LottoExpert now handles learning eligibility automatically. You can still review or delete saved predictions from Review Past Predictions.', 'message');
        $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
        $__cleanRedirectUri->delVar('mle_action');
        $app->redirect($__cleanRedirectUri->toString());
        return;
    }
    if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
        $app->enqueueMessage('Session expired. Please refresh and try again.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if (MLE_DEMO_MODE) {
        $app->enqueueMessage('Demo mode: Cannot apply bulk run selection actions.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if ($workspaceUserId <= 0) {
        $app->enqueueMessage('Please log in to apply bulk run selection actions.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    mleAdvisoryEnsureSchemaColumns($db);

    $allowedBulkActions = array('use_in_advice', 'watch', 'retired', 'delete_permanently');
    $bulkAction = strtolower(trim((string)$app->input->post->getString('bulk_action', '')));
    if (!in_array($bulkAction, $allowedBulkActions, true)) {
        $app->enqueueMessage('Invalid bulk action.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    $bulkLotteryId = (int)$app->input->post->getInt('lottery_id', 0);
    if ($bulkLotteryId <= 0) {
        $app->enqueueMessage('Invalid lottery context for bulk action.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    $rawSavedIds = (array)$app->input->post->get('selected_saved_ids', array(), 'ARRAY');
    $selectedSavedIds = array();
    foreach ($rawSavedIds as $rawId) {
        $id = (int)$rawId;
        if ($id > 0) { $selectedSavedIds[$id] = $id; }
    }

    $rawPerfIds = (array)$app->input->post->get('selected_run_ids', array(), 'ARRAY');
    $selectedPerfIds = array();
    foreach ($rawPerfIds as $rawPerfId) {
        $perfId = (int)$rawPerfId;
        if ($perfId > 0) { $selectedPerfIds[$perfId] = $perfId; }
    }

    $selectedSavedIds = array_values($selectedSavedIds);
    $selectedPerfIds = array_values($selectedPerfIds);

    if (count($selectedSavedIds) > 200) { $selectedSavedIds = array_slice($selectedSavedIds, 0, 200); }
    if (count($selectedPerfIds) > 200) { $selectedPerfIds = array_slice($selectedPerfIds, 0, 200); }

    if (empty($selectedSavedIds) && empty($selectedPerfIds)) {
        $app->enqueueMessage('No runs were selected for bulk action.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    $ownedSavedIds = array();
    if (!empty($selectedSavedIds)) {
        try {
            $qOwnedSaved = $db->getQuery(true)
                ->select($db->quoteName('id'))
                ->from($db->quoteName('#__user_saved_numbers'))
                ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $selectedSavedIds)) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId)
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$bulkLotteryId);
            $db->setQuery($qOwnedSaved);
            $ownedSavedRows = (array)$db->loadColumn();
            foreach ($ownedSavedRows as $savedId) {
                $savedId = (int)$savedId;
                if ($savedId > 0) { $ownedSavedIds[$savedId] = $savedId; }
            }
        } catch (\Throwable $e) { }
    }

    if (!empty($selectedPerfIds)) {
        try {
            $qPerfFromIds = $db->getQuery(true)
                ->select(array($db->quoteName('id'), $db->quoteName('run_id')))
                ->from($db->quoteName('#__skai_learning_performance'))
                ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $selectedPerfIds)) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);
            $db->setQuery($qPerfFromIds);
            $perfRowsFromIds = (array)$db->loadAssocList();
            foreach ($perfRowsFromIds as $perfRow) {
                $runId = (int)($perfRow['run_id'] ?? 0);
                if ($runId > 0) { $ownedSavedIds[$runId] = $runId; }
            }
        } catch (\Throwable $e) { }
    }

    if (!empty($ownedSavedIds)) {
        try {
            $qOwnedSavedFinal = $db->getQuery(true)
                ->select($db->quoteName('id'))
                ->from($db->quoteName('#__user_saved_numbers'))
                ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', array_values($ownedSavedIds))) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId)
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$bulkLotteryId);
            $db->setQuery($qOwnedSavedFinal);
            $ownedSavedRowsFinal = (array)$db->loadColumn();
            $ownedSavedIds = array();
            foreach ($ownedSavedRowsFinal as $savedId) {
                $savedId = (int)$savedId;
                if ($savedId > 0) { $ownedSavedIds[$savedId] = $savedId; }
            }
        } catch (\Throwable $e) {
            $ownedSavedIds = array();
        }
    }
    $ownedSavedIds = array_values($ownedSavedIds);

    $ownedPerfIds = array();
    if (!empty($ownedSavedIds)) {
        try {
            $qPerfByRun = $db->getQuery(true)
                ->select($db->quoteName('id'))
                ->from($db->quoteName('#__skai_learning_performance'))
                ->where($db->quoteName('run_id') . ' IN (' . implode(',', array_map('intval', $ownedSavedIds)) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);
            $db->setQuery($qPerfByRun);
            $ownedPerfRows = (array)$db->loadColumn();
            foreach ($ownedPerfRows as $perfId) {
                $perfId = (int)$perfId;
                if ($perfId > 0) { $ownedPerfIds[$perfId] = $perfId; }
            }
        } catch (\Throwable $e) { }
    }
    $ownedPerfIds = array_values($ownedPerfIds);

    if ($bulkAction === 'delete_permanently') {
        $confirmDelete = trim((string)$app->input->post->getString('confirm_bulk_delete', ''));
        if ($confirmDelete !== 'DELETE') {
            $app->enqueueMessage('Bulk delete blocked. Type DELETE to confirm permanent deletion.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }
        if (empty($ownedSavedIds)) {
            $app->enqueueMessage('No deletable saved runs were found for the selected items.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $snCols = array();
        try {
            $snColsRaw = $db->getTableColumns('#__user_saved_numbers', false);
            $snCols = is_array($snColsRaw) ? array_keys($snColsRaw) : array();
        } catch (\Throwable $e) { $snCols = array(); }

        try {
            $qDel = $db->getQuery(true)
                ->delete($db->quoteName('#__user_saved_numbers'))
                ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ownedSavedIds)) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId)
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$bulkLotteryId);
            if (in_array('save_intent', $snCols, true)) {
                $qDel->where(
                    '(' .
                    $db->quoteName('save_intent') . " = 'prediction_archive' OR (" .
                    $db->quoteName('save_intent') . " = '' AND " . $db->quoteName('source') . " <> 'strategy_set'))"
                );
            }
            $db->setQuery($qDel);
            $db->execute();
            $deletedCount = max(0, (int)$db->getAffectedRows());
            if ($deletedCount > 0) {
                $app->enqueueMessage($deletedCount . ' run' . ($deletedCount === 1 ? '' : 's') . ' permanently deleted.', 'message');
            } else {
                $app->enqueueMessage('No selected runs were deleted. They may already be removed or not eligible for deletion.', 'warning');
            }
        } catch (\Throwable $e) {
            $app->enqueueMessage('An error occurred while deleting selected runs.', 'error');
        }

        $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
        $__cleanRedirectUri->delVar('mle_action');
        $app->redirect($__cleanRedirectUri->toString());
        return;
    }

    if (empty($ownedPerfIds) && empty($ownedSavedIds)) {
        $app->enqueueMessage('No selected runs were eligible for status updates.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    $updatedPerfCount = 0;
    $updatedSavedCount = 0;
    try {
        $qUpdatePerf = $db->getQuery(true)
            ->update($db->quoteName('#__skai_learning_performance'))
            ->set($db->quoteName('advice_status') . ' = ' . $db->quote($bulkAction))
            ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
            ->set($db->quoteName('status_explicit') . ' = 1')
            ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ownedPerfIds)) . ')')
            ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);
        $db->setQuery($qUpdatePerf);
        $db->execute();
        $updatedPerfCount = max(0, (int)$db->getAffectedRows());
    } catch (\Throwable $e) {
        $updatedPerfCount = 0;
    }

    if (!empty($ownedSavedIds)) {
        try {
            $qUpdateSaved = $db->getQuery(true)
                ->update($db->quoteName('#__user_saved_numbers'))
                ->set($db->quoteName('advice_status') . ' = ' . $db->quote($bulkAction))
                ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                ->set($db->quoteName('status_explicit') . ' = 1')
                ->where($db->quoteName('id') . ' IN (' . implode(',', array_map('intval', $ownedSavedIds)) . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId)
                ->where($db->quoteName('lottery_id') . ' = ' . (int)$bulkLotteryId);
            $db->setQuery($qUpdateSaved);
            $db->execute();
            $updatedSavedCount = max(0, (int)$db->getAffectedRows());
        } catch (\Throwable $e) {
            $updatedSavedCount = 0;
        }
    }

    if ($updatedPerfCount > 0 || $updatedSavedCount > 0) {
        $label = ($bulkAction === 'use_in_advice') ? 'Use for Advice' : (($bulkAction === 'watch') ? 'Watch for Now' : 'Exclude');
        $app->enqueueMessage(
            'Bulk run selection applied. Action: ' . $label
            . '. Updated saved runs: ' . (int)$updatedSavedCount
            . (!empty($ownedPerfIds) ? '; updated completed prediction history rows: ' . (int)$updatedPerfCount : '')
            . '.',
            'message'
        );
    } else {
        $app->enqueueMessage('No selected runs were changed by the bulk action.', 'warning');
    }

    $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
    $__cleanRedirectUri->delVar('mle_action');
    $app->redirect($__cleanRedirectUri->toString());
    return;
}

if ($__mleAction === 'apply_evidence_choices' || $__mleAction === 'apply_batch_cleanup') {
    $modernChoice = trim((string)$app->input->post->getString('evidence_choice', ''));
    $modernRunIds = (array)$app->input->post->get('run_ids', array(), 'array');
    $modernRunIdsCsv = trim((string)$app->input->post->getString('run_ids_csv', ''));
    if ($modernChoice !== '' || !empty($modernRunIds) || $modernRunIdsCsv !== '') {
        if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
            $app->enqueueMessage('Session expired. Please refresh and try again.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }
        if (MLE_DEMO_MODE) {
            $app->enqueueMessage('Demo mode: Cannot apply run selection.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $actionUser = \Joomla\CMS\Factory::getUser();
        $actionUserId = (int)(is_object($actionUser) ? $actionUser->get('id') : 0);
        if ($actionUserId <= 0) {
            $app->enqueueMessage('Please log in to apply run selection.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $normalizedAction = mylottoexpertNormalizeAdviceStatusAction($modernChoice);
        if ($normalizedAction === '' || mylottoexpertIsAdminOnlyAdviceAction($normalizedAction)) {
            $app->enqueueMessage('Invalid run selection action.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $runIds = array();
        foreach ($modernRunIds as $rid) {
            $rid = (int)$rid;
            if ($rid > 0) {
                $runIds[$rid] = $rid;
            }
        }
        if ($modernRunIdsCsv !== '') {
            foreach (explode(',', $modernRunIdsCsv) as $part) {
                $rid = (int)trim($part);
                if ($rid > 0) {
                    $runIds[$rid] = $rid;
                }
            }
        }
        $runIds = array_values($runIds);
        if (empty($runIds)) {
            $app->enqueueMessage('No selected runs were eligible for status updates.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        $allowedIds = array();
        foreach ($runIds as $savedId) {
            if (mylottoexpertCanPerformAdviceStatusAction($db, $actionUser, $savedId, $normalizedAction)) {
                $allowedIds[$savedId] = $savedId;
            }
        }
        $allowedIds = array_values($allowedIds);
        if (empty($allowedIds)) {
            $app->enqueueMessage('No selected runs were eligible for status updates.', 'warning');
            $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
            return;
        }

        try {
            mleAdvisoryEnsureSchemaColumns($db);
            $in = implode(',', array_map('intval', $allowedIds));

            $qUpdateSaved = $db->getQuery(true)
                ->update($db->quoteName('#__myle_saved_predictions'))
                ->set($db->quoteName('advice_status') . ' = ' . $db->quote($normalizedAction))
                ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                ->set($db->quoteName('status_explicit') . ' = 1')
                ->set($db->quoteName('updated_at') . ' = NOW()')
                ->where($db->quoteName('id') . ' IN (' . $in . ')')
                ->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId)
                ->where($db->quoteName('is_deleted') . ' = 0');
            $db->setQuery($qUpdateSaved);
            $db->execute();
            $updatedSaved = max(0, (int)$db->getAffectedRows());

            $updatedPerf = 0;
            try {
                $qUpdatePerf = $db->getQuery(true)
                    ->update($db->quoteName('#__myle_learning_performance'))
                    ->set($db->quoteName('advice_status') . ' = ' . $db->quote($normalizedAction))
                    ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                    ->set($db->quoteName('status_explicit') . ' = 1')
                    ->where($db->quoteName('saved_prediction_id') . ' IN (' . $in . ')')
                    ->where($db->quoteName('user_id') . ' = ' . (int)$actionUserId);
                $db->setQuery($qUpdatePerf);
                $db->execute();
                $updatedPerf = max(0, (int)$db->getAffectedRows());
            } catch (\Throwable $ignorePerf) {
                $updatedPerf = 0;
            }

            if ($updatedSaved > 0 || $updatedPerf > 0) {
                $labels = array(
                    'consider' => 'Use for future advice',
                    'review' => 'Keep for review',
                    'exclude' => 'Exclude from advice'
                );
                $label = isset($labels[$normalizedAction]) ? $labels[$normalizedAction] : 'Updated';
                $app->enqueueMessage(
                    'Run selection applied. Action: ' . $label
                    . '. Updated saved runs: ' . (int)$updatedSaved
                    . ($updatedPerf > 0 ? '; updated completed prediction history rows: ' . (int)$updatedPerf : '')
                    . '.',
                    'message'
                );
            } else {
                $app->enqueueMessage('No selected runs were changed by the bulk action.', 'warning');
            }
        } catch (\Throwable $e) {
            $app->enqueueMessage('Run selection update failed.', 'error');
        }

        $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
        $__cleanRedirectUri->delVar('mle_action');
        $app->redirect($__cleanRedirectUri->toString());
        return;
    }

    $__mleV135CanManageLearningStatus = false;
    try {
        $__mleV135ActionUser = \Joomla\CMS\Factory::getUser();
        $__mleV135CanManageLearningStatus = is_object($__mleV135ActionUser) && method_exists($__mleV135ActionUser, 'authorise') && $__mleV135ActionUser->authorise('core.admin');
    } catch (\Throwable $__mleV135GateEx) {
        $__mleV135CanManageLearningStatus = false;
    }
    if (!$__mleV135CanManageLearningStatus) {
        $app->enqueueMessage('LottoExpert now handles learning eligibility automatically. You can still review or delete saved predictions from Review Past Predictions.', 'message');
        $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
        $__cleanRedirectUri->delVar('mle_action');
        $app->redirect($__cleanRedirectUri->toString());
        return;
    }
    if ($app->input->getMethod() !== 'POST' || !\Joomla\CMS\Session\Session::checkToken('post')) {
        $app->enqueueMessage('Session expired. Please refresh and try again.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if (MLE_DEMO_MODE) {
        $app->enqueueMessage('Demo mode: Cannot apply run selection.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }
    if ($workspaceUserId <= 0) {
        $app->enqueueMessage('Please log in to apply run selection.', 'warning');
        $app->redirect(\Joomla\CMS\Uri\Uri::getInstance()->toString());
        return;
    }

    mleAdvisoryEnsureSchemaColumns($db);
    $prefix = $db->getPrefix();

    try {
        $perfColsRaw = $db->getTableColumns('#__skai_learning_performance', false);
        $perfCols = is_array($perfColsRaw) ? array_keys($perfColsRaw) : array();

        if (!in_array('advice_status', $perfCols, true)) {
            $db->setQuery('ALTER TABLE `' . $prefix . 'skai_learning_performance` ADD COLUMN `advice_status` VARCHAR(20) NOT NULL DEFAULT \'use_in_advice\'');
            $db->execute();
        }

        if (!in_array('advice_status_updated_at', $perfCols, true)) {
            $db->setQuery('ALTER TABLE `' . $prefix . 'skai_learning_performance` ADD COLUMN `advice_status_updated_at` DATETIME NULL DEFAULT NULL AFTER `advice_status`');
            $db->execute();
        }
    } catch (\Throwable $e) {
        $perfCols = array();
    }

    try {
        $snColsRaw = $db->getTableColumns('#__user_saved_numbers', false);
        $snCols = is_array($snColsRaw) ? array_keys($snColsRaw) : array();

        if (!in_array('advice_status', $snCols, true)) {
            $db->setQuery('ALTER TABLE `' . $prefix . 'user_saved_numbers` ADD COLUMN `advice_status` VARCHAR(20) NOT NULL DEFAULT \'use_in_advice\'');
            $db->execute();
        }

        if (!in_array('advice_status_updated_at', $snCols, true)) {
            $db->setQuery('ALTER TABLE `' . $prefix . 'user_saved_numbers` ADD COLUMN `advice_status_updated_at` DATETIME NULL DEFAULT NULL AFTER `advice_status`');
            $db->execute();
        }
    } catch (\Throwable $e) {
        $snCols = array();
    }

    $sets = array(
        'use_in_advice' => array_map('intval', (array)$app->input->post->get('keep_ids', array(), 'ARRAY')),
        'watch' => array_map('intval', (array)$app->input->post->get('watch_ids', array(), 'ARRAY')),
        'retired' => array_map('intval', (array)$app->input->post->get('retire_ids', $app->input->post->get('archive_ids', array(), 'ARRAY'), 'ARRAY'))
    );

    $updated = 0;
    $keep = 0;
    $watch = 0;
    $retired = 0;

    foreach ($sets as $status => $ids) {
        foreach ($ids as $id) {
            $id = (int)$id;
            if ($id <= 0) {
                continue;
            }

            try {
                $q = $db->getQuery(true)
                    ->select('*')
                    ->from($db->quoteName('#__skai_learning_performance'))
                    ->where($db->quoteName('id') . ' = ' . $id)
                    ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);

                $db->setQuery($q, 0, 1);
                $perf = $db->loadAssoc();

                if (empty($perf)) {
                    continue;
                }

                $q = $db->getQuery(true)
                    ->update($db->quoteName('#__skai_learning_performance'))
                    ->set($db->quoteName('advice_status') . ' = ' . $db->quote($status))
                    ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                    ->set($db->quoteName('status_explicit') . ' = 1')
                    ->where($db->quoteName('id') . ' = ' . $id)
                    ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);

                $db->setQuery($q);
                $db->execute();
                $updated++;

                $savedId = (int)($perf['run_id'] ?? 0);
                if ($savedId > 0) {
                    try {
                        $q2 = $db->getQuery(true)
                            ->update($db->quoteName('#__user_saved_numbers'))
                            ->set($db->quoteName('advice_status') . ' = ' . $db->quote($status))
                            ->set($db->quoteName('advice_status_updated_at') . ' = NOW()')
                            ->set($db->quoteName('status_explicit') . ' = 1')
                            ->where($db->quoteName('id') . ' = ' . $savedId)
                            ->where($db->quoteName('user_id') . ' = ' . (int)$workspaceUserId);

                        $db->setQuery($q2);
                        $db->execute();
                    } catch (\Throwable $e2) {}
                }

                if ($status === 'use_in_advice') {
                    $keep++;
                } elseif ($status === 'watch') {
                    $watch++;
                } else {
                    $retired++;
                }
            } catch (\Throwable $e) {}
        }
    }

    if ($updated > 0) {
        $app->enqueueMessage('Run selection applied. Used for future advice: ' . $keep . '. Kept for review: ' . $watch . '. Excluded from Advice: ' . $retired . '. These choices will now shape future recommendations for this lottery.', 'message');
    } else {
        $app->enqueueMessage('No prediction history choices were changed. LottoExpert could not match the submitted prediction history rows to active saved runs.', 'warning');
    }

    $__cleanRedirectUri = \Joomla\CMS\Uri\Uri::getInstance();
    $__cleanRedirectUri->delVar('mle_action');
    $app->redirect($__cleanRedirectUri->toString());
    return;
}

