$doc->addScriptDeclaration(<<<'JS'
(function(){
  'use strict';
  /* [[MLE_V65B_SAFE_DISPLAY_CONTROL_REMOVE]]
     Remove only the small Display Control card itself. Do not scan/remove broad
     page containers, because template scripts may observe those containers. */
  function textOf(el){
    return String((el && el.textContent) || '').replace(/\s+/g, ' ').trim();
  }
  function isProtectedContainer(el){
    if (!el || !el.closest) { return true; }
    if (el === document.body || el === document.documentElement) { return true; }
    if (el.id === 'sp-page-builder' || el.id === 'sp-main-body' || el.classList.contains('body-wrapper') || el.classList.contains('body-innerwrapper')) { return true; }
    if (el.closest('#mle-user-manual') || el.closest('#mle-premium-hero')) { return true; }
    return false;
  }
  function removeDisplayControlPanel(){
    var nodes = Array.prototype.slice.call(document.querySelectorAll('section, aside, details, div'));
    var best = null;
    var bestLen = 999999;
    nodes.forEach(function(el){
      if (isProtectedContainer(el)) { return; }
      var txt = textOf(el);
      var low = txt.toLowerCase();
      if (low.indexOf('display control') === -1 || low.indexOf('choose what you want to see') === -1) { return; }
      if (low.indexOf('start here: how to use mylottoexpert') !== -1 || low.indexOf('your next best action') !== -1) { return; }
      if (txt.length > 700) { return; }
      if (txt.length < bestLen) {
        best = el;
        bestLen = txt.length;
      }
    });
    if (best && best.parentNode) {
      best.parentNode.removeChild(best);
    }
  }
  function schedule(){
    window.setTimeout(removeDisplayControlPanel, 400);
    window.setTimeout(removeDisplayControlPanel, 1400);
  }
  if (document.readyState === 'complete') {
    schedule();
  } else {
    window.addEventListener('load', schedule, {once:true});
  }
})();
JS);

