<script>
/* [[MLE_V151_SKAI_RETURN_CONTEXT_LOCK]]
   Preserve the MyLottoExpert lottery card that launched SKAI so the dashboard
   does not return to a different card after a completed run. */
(function () {
    'use strict';

    var storageKey = 'mle_skai_return_lottery_id_v151';
    var maxAgeMs = 2 * 60 * 60 * 1000;

    function nowMs() {
        return Date.now ? Date.now() : new Date().getTime();
    }

    function parseJson(raw) {
        try {
            return JSON.parse(String(raw || ''));
        } catch (e) {
            return null;
        }
    }

    function readContext() {
        try {
            return parseJson(window.localStorage.getItem(storageKey));
        } catch (e) {
            return null;
        }
    }

    function writeContext(lotteryId) {
        lotteryId = parseInt(lotteryId, 10) || 0;
        if (lotteryId <= 0) {
            return;
        }

        try {
            window.localStorage.setItem(storageKey, JSON.stringify({
                lottery_id: lotteryId,
                created_at: nowMs()
            }));
        } catch (e) {
        }
    }

    function clearContext() {
        try {
            window.localStorage.removeItem(storageKey);
        } catch (e) {
        }
    }

    function currentDashboardLotteryId() {
        try {
            var params = new URLSearchParams(window.location.search || '');
            return parseInt(params.get('mle_lottery_id') || '0', 10) || 0;
        } catch (e) {
            return 0;
        }
    }

    function isDashboard() {
        return String(window.location.pathname || '').toLowerCase().indexOf('/membership/my-dashboard') !== -1;
    }

    function correctDashboardContext() {
        if (!isDashboard()) {
            return;
        }

        var context = readContext();
        if (!context) {
            return;
        }

        var lotteryId = parseInt(context.lottery_id || '0', 10) || 0;
        var createdAt = parseInt(context.created_at || '0', 10) || 0;
        if (lotteryId <= 0 || createdAt <= 0 || (nowMs() - createdAt) > maxAgeMs) {
            clearContext();
            return;
        }

        if (currentDashboardLotteryId() === lotteryId) {
            clearContext();
            return;
        }

        try {
            var url = new URL(window.location.href);
            url.searchParams.set('mle_lottery_id', String(lotteryId));
            url.searchParams.set('mle_focus_return', '1');
            window.location.replace(url.toString());
        } catch (e) {
            window.location.href = '/membership/my-dashboard?mle_lottery_id=' + encodeURIComponent(String(lotteryId)) + '&mle_focus_return=1';
        }
    }

    function lotteryIdFromElement(node) {
        var el = node;
        while (el && el !== document) {
            if (el.getAttribute) {
                var direct = el.getAttribute('data-lottery-id') || el.getAttribute('data-mle-lottery-id');
                if (direct) {
                    direct = parseInt(String(direct).replace(/[^0-9].*$/, ''), 10) || 0;
                    if (direct > 0) {
                        return direct;
                    }
                }

                var href = el.getAttribute('href') || el.getAttribute('data-skai-url') || el.getAttribute('data-skai-regular-url');
                if (href && String(href).indexOf('skai-lottery-prediction') !== -1) {
                    try {
                        var parsed = new URL(href, window.location.origin);
                        var focusId = parseInt(parsed.searchParams.get('mle_focus_lottery_id') || '0', 10) || 0;
                        var returnId = parseInt(parsed.searchParams.get('mle_return_lottery_id') || '0', 10) || 0;
                        var dashboardId = parseInt(parsed.searchParams.get('mle_return_dashboard_lottery_id') || '0', 10) || 0;
                        var lotteryId = parseInt(parsed.searchParams.get('lottery_id') || '0', 10) || 0;
                        if (focusId > 0) { return focusId; }
                        if (returnId > 0) { return returnId; }
                        if (dashboardId > 0) { return dashboardId; }
                        if (lotteryId > 0) { return lotteryId; }
                    } catch (e) {
                    }
                }
            }
            el = el.parentNode;
        }
        return 0;
    }

    document.addEventListener('click', function (event) {
        var lotteryId = lotteryIdFromElement(event && event.target ? event.target : null);
        if (lotteryId > 0) {
            writeContext(lotteryId);
        }
    }, true);

    correctDashboardContext();
})();
</script>

