if (!function_exists('mle_confidence_rank_map')) {
    function mle_confidence_rank_map() {
        return array(
            'No Confidence Yet' => 0,
            'Early Learning' => 1,
            'Developing Signal' => 2,
            'Promising Signal' => 3,
            'Strong Candidate' => 4,
            'High-Confidence Candidate' => 5,
        );
    }
}

if (!function_exists('mle_cap_confidence')) {
    function mle_cap_confidence($current, $cap) {
        $map = mle_confidence_rank_map();
        $current = isset($map[(string)$current]) ? (string)$current : 'No Confidence Yet';
        $cap = isset($map[(string)$cap]) ? (string)$cap : 'No Confidence Yet';
        return ($map[$current] <= $map[$cap]) ? $current : $cap;
    }
}

if (!function_exists('mle_calculate_recent_trend')) {
    function mle_calculate_recent_trend($scored_rows) {
        $rows = array_values(is_array($scored_rows) ? $scored_rows : array());
        if (count($rows) < 6) { return 'insufficient'; }
        usort($rows, function($a, $b) {
            $aTime = strtotime((string)($a['draw_date'] ?? $a['target_draw_date'] ?? $a['evaluated_at'] ?? $a['scored_at'] ?? ''));
            $bTime = strtotime((string)($b['draw_date'] ?? $b['target_draw_date'] ?? $b['evaluated_at'] ?? $b['scored_at'] ?? ''));
            $aTime = $aTime !== false ? $aTime : 0;
            $bTime = $bTime !== false ? $bTime : 0;
            if ($aTime === $bTime) { return 0; }
            return ($aTime > $bTime) ? -1 : 1;
        });
        $current = array_slice($rows, 0, 5);
        $previous = array_slice($rows, 5, 5);
        if (count($current) < 3 || count($previous) < 3) { return 'insufficient'; }
        $avg = function($items) {
            $sum = 0.0;
            $count = 0;
            foreach ((array)$items as $row) {
                $sum += (float)((int)($row['total_hits'] ?? (($row['main_hits'] ?? 0) + ($row['extra_hits'] ?? 0))));
                $count++;
            }
            return $count > 0 ? ($sum / $count) : null;
        };
        $currentAvg = $avg($current);
        $previousAvg = $avg($previous);
        if ($currentAvg === null || $previousAvg === null) { return 'insufficient'; }
        if (($currentAvg - $previousAvg) >= 0.20) { return 'improving'; }
        if (($previousAvg - $currentAvg) >= 0.20) { return 'declining'; }
        return 'stable';
    }
}

if (!function_exists('mle_calculate_baseline_lift')) {
    function mle_calculate_baseline_lift($avg_hits, $random_expected) {
        $avg_hits = is_numeric($avg_hits) ? (float)$avg_hits : null;
        $random_expected = is_numeric($random_expected) ? (float)$random_expected : null;
        if ($avg_hits === null || $random_expected === null || $random_expected <= 0) { return null; }
        return round((($avg_hits - $random_expected) / $random_expected) * 100, 2);
    }
}

if (!function_exists('mle_calculate_hive_ranking_signal')) {
    function mle_calculate_hive_ranking_signal($predicted_numbers_arr, $hive_top20_arr, $hive_top10_arr, $game_pick_size) {
        $predicted = array_values(array_unique(array_map('intval', (array)$predicted_numbers_arr)));
        $top20 = array_values(array_unique(array_map('intval', (array)$hive_top20_arr)));
        $top10 = array_values(array_unique(array_map('intval', (array)$hive_top10_arr)));
        $pickSize = max(0, (int)$game_pick_size);
        if (empty($top20)) {
            return array('signal' => 'Unknown', 'overlap_count' => 0, 'explanation' => 'Shared AI Learning ranked number data is not available for this lottery.');
        }
        if (empty($predicted)) {
            return array('signal' => 'Unknown', 'overlap_count' => 0, 'explanation' => 'No saved prediction numbers were available to compare with Shared AI Learning data.');
        }
        $overlap20 = array_values(array_intersect($predicted, $top20));
        $overlap10 = array_values(array_intersect($predicted, $top10));
        $overlapCount = count($overlap20);
        $signal = 'No Shared AI Learning Support';
        if ($overlapCount <= 0) {
            $signal = 'No Shared AI Learning Support';
        } elseif ($pickSize > 0 && $overlapCount >= max(4, min($pickSize, (int)ceil($pickSize * 0.75))) && count($overlap10) >= max(2, (int)floor($pickSize / 2))) {
            $signal = 'Top Shared AI Learning Alignment';
        } elseif ($overlapCount >= max(3, (int)ceil(max(1, $pickSize) * 0.60)) || count($overlap10) >= max(2, (int)floor(max(1, $pickSize) * 0.40))) {
            $signal = 'Strong Shared AI Learning Support';
        } elseif ($overlapCount >= 2 || count($overlap10) >= 1) {
            $signal = 'Moderate Shared AI Learning Support';
        } elseif ($overlapCount === 1) {
            $signal = 'Light Shared AI Learning Support';
        }
        return array(
            'signal' => $signal,
            'overlap_count' => $overlapCount,
            'explanation' => $overlapCount . ' predicted number' . ($overlapCount === 1 ? '' : 's') . ' appear inside the Shared AI Learning Top 20 pool.',
        );
    }
}

if (!function_exists('mle_calculate_precision_lock_status')) {
    function mle_calculate_precision_lock_status($precision_stage, $range_guidance, $lock_data) {
        $stage = strtolower(trim((string)$precision_stage));
        $guidance = strtolower(trim((string)$range_guidance));
        $lock = is_array($lock_data) ? $lock_data : array();
        $hasRange = !empty($lock['has_range']);
        $rangeMin = isset($lock['range_min']) && is_numeric($lock['range_min']) ? (float)$lock['range_min'] : null;
        $rangeMax = isset($lock['range_max']) && is_numeric($lock['range_max']) ? (float)$lock['range_max'] : null;
        $currentValue = null;
        foreach (array('current_value','recommended_window_center','recommended_window_min','recommended_window_max') as $key) {
            if (isset($lock[$key]) && $lock[$key] !== '' && is_numeric($lock[$key])) {
                $currentValue = (float)$lock[$key];
                break;
            }
        }
        if ($currentValue !== null && $rangeMin !== null && $rangeMax !== null && ($currentValue < min($rangeMin, $rangeMax) || $currentValue > max($rangeMin, $rangeMax))) {
            return 'Range Mismatch Review';
        }
        if (strpos($guidance, 'mismatch') !== false || strpos($guidance, 'outside') !== false) { return 'Range Mismatch Review'; }
        if (strpos($guidance, 'recheck') !== false || strpos($guidance, 'weaken') !== false || strpos($guidance, 'review') !== false) { return 'Recheck Needed'; }
        if (in_array($stage, array('precision_focus_range','keep_locked','locked','locked_range'), true)) { return 'Keep Locked'; }
        if (in_array($stage, array('validated_focus_range','testing_inside_range','inside_range'), true)) { return 'Testing Inside Range'; }
        if (in_array($stage, array('narrowing_signal','early_direction','exploratory_batch'), true) || ($hasRange && $rangeMin !== null && $rangeMax !== null)) { return 'Early Signal Narrowing'; }
        if ($stage === 'broad_testing' || $stage === 'exploring' || $stage === '') { return 'Broad Testing'; }
        return 'Unknown';
    }
}

if (!function_exists('mle_calculate_risk_signal')) {
    function mle_calculate_risk_signal($scored_runs, $zero_hit_rate, $recent_trend, $avg_hits, $all_time_avg) {
        $scoredRuns = max(0, (int)$scored_runs);
        $zeroHitRate = is_numeric($zero_hit_rate) ? (float)$zero_hit_rate : null;
        $avgHits = is_numeric($avg_hits) ? (float)$avg_hits : null;
        $allTimeAvg = is_numeric($all_time_avg) ? (float)$all_time_avg : null;
        if ($scoredRuns <= 0) { return 'Needs More Draws'; }
        if ($scoredRuns < 5) { return 'Small Sample Warning'; }
        if ($zeroHitRate !== null && $zeroHitRate >= 0.60) { return 'Zero-Hit Risk Elevated'; }
        if ($recent_trend === 'declining') { return 'Recent Drop-Off'; }
        if ($avgHits !== null && $allTimeAvg !== null) {
            $gap = abs($avgHits - $allTimeAvg);
            if ($gap >= 0.50) { return 'High Variance'; }
            if ($gap <= 0.15 && ($zeroHitRate === null || $zeroHitRate <= 0.35)) { return 'Stable Pattern'; }
            return 'Moderate Variance';
        }
        return 'Unknown';
    }
}

if (!function_exists('mle_calculate_historical_performance_signal')) {
    function mle_calculate_historical_performance_signal($scored_runs, $zero_hit_rate, $one_plus_rate, $avg_hits, $baseline_lift_pct, $recent_trend) {
        $scoredRuns = max(0, (int)$scored_runs);
        $zeroHitRate = is_numeric($zero_hit_rate) ? (float)$zero_hit_rate : null;
        $onePlusRate = is_numeric($one_plus_rate) ? (float)$one_plus_rate : null;
        $avgHits = is_numeric($avg_hits) ? (float)$avg_hits : null;
        $baselineLiftPct = is_numeric($baseline_lift_pct) ? (float)$baseline_lift_pct : null;
        if ($scoredRuns < 5) { return 'Insufficient Prediction History'; }
        if (($zeroHitRate !== null && $zeroHitRate >= 0.65) || ($baselineLiftPct !== null && $baselineLiftPct < 0)) { return 'Weak Historical Signal'; }
        if ($scoredRuns >= 20 && $zeroHitRate !== null && $zeroHitRate <= 0.25 && $onePlusRate !== null && $onePlusRate >= 0.75 && $avgHits !== null && $avgHits >= 1.20 && $baselineLiftPct !== null && $baselineLiftPct >= 20 && in_array($recent_trend, array('stable','improving'), true)) {
            return 'Strong Historical Signal';
        }
        if ($scoredRuns >= 12 && $zeroHitRate !== null && $zeroHitRate <= 0.35 && $onePlusRate !== null && $onePlusRate >= 0.60 && $avgHits !== null && $avgHits >= 1.00 && in_array($recent_trend, array('stable','improving'), true)) {
            return 'Consistent Historical Signal';
        }
        if ($recent_trend === 'improving' && $baselineLiftPct !== null && $baselineLiftPct > 0) {
            return 'Improving Historical Signal';
        }
        if ($zeroHitRate !== null && $zeroHitRate <= 0.50 && $onePlusRate !== null && $onePlusRate >= 0.45) {
            return 'Mixed Historical Signal';
        }
        return 'Weak Historical Signal';
    }
}

if (!function_exists('mle_calculate_prediction_quality_signal')) {
    function mle_calculate_prediction_quality_signal($prediction_confidence, $hive_signal, $precision_status, $risk_signal) {
        $confidence = (string)$prediction_confidence;
        $hiveSignal = (string)$hive_signal;
        $precisionStatus = (string)$precision_status;
        $riskSignal = (string)$risk_signal;
        if ($confidence === 'High-Confidence Candidate' && in_array($hiveSignal, array('Strong Shared AI Learning Support', 'Top Shared AI Learning Alignment'), true) && in_array($precisionStatus, array('Keep Locked', 'Testing Inside Range'), true) && !in_array($riskSignal, array('Zero-Hit Risk Elevated', 'Recent Drop-Off'), true)) {
            return 'High-Confidence Candidate';
        }
        if ($confidence === 'Strong Candidate' && in_array($precisionStatus, array('Keep Locked', 'Testing Inside Range', 'Early Signal Narrowing'), true) && !in_array($riskSignal, array('Zero-Hit Risk Elevated', 'Recent Drop-Off'), true)) {
            return 'Strong Candidate';
        }
        if (in_array($confidence, array('Promising Signal', 'Strong Candidate', 'High-Confidence Candidate'), true) && !in_array($precisionStatus, array('Range Mismatch Review', 'Recheck Needed'), true)) {
            return 'Promising Signal';
        }
        if (in_array($confidence, array('Developing Signal', 'Promising Signal', 'Strong Candidate', 'High-Confidence Candidate'), true)) {
            return 'Developing Signal';
        }
        if ($confidence === 'Early Learning') { return 'Early Learning'; }
        return 'No Confidence Yet';
    }
}

if (!function_exists('mle_apply_confidence_caps')) {
    function mle_apply_confidence_caps($raw_confidence, $scored_runs, $zero_hit_rate, $baseline_lift_pct, $recent_trend, $hive_signal, $precision_status, $prediction_was_saved_before_draw) {
        $current = isset(mle_confidence_rank_map()[(string)$raw_confidence]) ? (string)$raw_confidence : 'No Confidence Yet';
        $scoredRuns = max(0, (int)$scored_runs);
        $zeroHitRate = is_numeric($zero_hit_rate) ? (float)$zero_hit_rate : null;
        $baselineLiftPct = is_numeric($baseline_lift_pct) ? (float)$baseline_lift_pct : null;
        if ($scoredRuns <= 0) { $current = mle_cap_confidence($current, 'No Confidence Yet'); }
        elseif ($scoredRuns < 5) { $current = mle_cap_confidence($current, 'Early Learning'); }
        elseif ($scoredRuns < 10) { $current = mle_cap_confidence($current, 'Developing Signal'); }
        if ($zeroHitRate !== null && $zeroHitRate >= 0.55) { $current = mle_cap_confidence($current, 'Developing Signal'); }
        if ($baselineLiftPct === null || $baselineLiftPct <= 0) { $current = mle_cap_confidence($current, 'Developing Signal'); }
        if ($recent_trend === 'declining') { $current = mle_cap_confidence($current, 'Developing Signal'); }
        if (in_array((string)$hive_signal, array('No Shared AI Learning Support', 'Light Shared AI Learning Support'), true)) { $current = mle_cap_confidence($current, 'Promising Signal'); }
        if (in_array((string)$precision_status, array('Range Mismatch Review', 'Recheck Needed'), true)) { $current = mle_cap_confidence($current, 'Early Learning'); }
        if (empty($prediction_was_saved_before_draw)) { $current = mle_cap_confidence($current, 'No Confidence Yet'); }
        return $current;
    }
}

if (!function_exists('mle_calculate_recommendation_readiness')) {
    function mle_calculate_recommendation_readiness($prediction_confidence, $scored_runs, $zero_hit_rate, $hive_signal, $precision_status, $recent_trend, $is_top_recommendation, $saved_before_draw, $baseline_lift_pct, $learning_readiness) {
        $confidence = (string)$prediction_confidence;
        $scoredRuns = max(0, (int)$scored_runs);
        $zeroHitRate = is_numeric($zero_hit_rate) ? (float)$zero_hit_rate : null;
        $baselineLiftPct = is_numeric($baseline_lift_pct) ? (float)$baseline_lift_pct : null;
        $learningReadiness = strtolower(trim((string)$learning_readiness));
        $ticketGate = in_array($confidence, array('Promising Signal', 'Strong Candidate', 'High-Confidence Candidate'), true)
            && $scoredRuns >= 10
            && ($zeroHitRate === null || $zeroHitRate <= 0.40)
            && in_array((string)$hive_signal, array('Moderate Shared AI Learning Support', 'Strong Shared AI Learning Support', 'Top Shared AI Learning Alignment'), true)
            && in_array((string)$precision_status, array('Keep Locked', 'Testing Inside Range'), true)
            && in_array((string)$recent_trend, array('stable', 'improving'), true)
            && !empty($is_top_recommendation)
            && !empty($saved_before_draw)
            && ($baseline_lift_pct === null || $baselineLiftPct > 0)
            && in_array($learningReadiness, array('can influence recommendations','can support precision lock','can support ticket consideration'), true);
        if ($ticketGate) { return 'Ticket Consideration Candidate'; }
        if (in_array((string)$precision_status, array('Range Mismatch Review', 'Recheck Needed'), true) || $recent_trend === 'declining') { return 'Review Candidate'; }
        if ($confidence === 'No Confidence Yet' || empty($saved_before_draw)) { return 'Watch Only'; }
        if ($scoredRuns < 5 || !in_array($learningReadiness, array('can guide exploration','can influence recommendations','can support precision lock','can support ticket consideration'), true)) { return 'Learning Mode'; }
        if (in_array($confidence, array('Promising Signal', 'Strong Candidate', 'High-Confidence Candidate'), true) && !empty($is_top_recommendation)) { return 'Best Current Candidate'; }
        return 'Watch Only';
    }
}

if (!function_exists('mle_build_learning_quality_profile')) {
    function mle_build_learning_quality_profile($lottery_id, $db) {
        $lotteryId = (int)$lottery_id;
        $profile = array(
            'learning_events' => 0,
            'scored_runs' => 0,
            'evidence_draws' => 0,
            'evidence_users' => 0,
            'zero_hit_rate' => null,
            'one_plus_rate' => null,
            'two_plus_rate' => null,
            'three_plus_rate' => null,
            'avg_hits' => null,
            'random_avg_hits' => null,
            'baseline_lift_pct' => null,
            'recent_5_lift_pct' => null,
            'recent_10_lift_pct' => null,
            'trend' => 'insufficient',
            'overfit_flag' => false,
            'quality_grade' => 'Insufficient',
            'readiness' => 'Observe Only',
            'maturity_label' => 'No Learning Yet',
            'quality_label' => 'Insufficient',
            'readiness_label' => 'Observe Only',
            'summary' => 'Learning prediction history is not available yet.',
        );
        if (!is_object($db) || $lotteryId <= 0) { return $profile; }
        try {
            $user = \Joomla\CMS\Factory::getApplication()->getIdentity();
        } catch (\Throwable $e) {
            $user = null;
        }
        $userId = is_object($user) ? (int)($user->id ?? 0) : 0;
        if ($userId <= 0) { return $profile; }
        $savedColsRaw = $db->getTableColumns('#__user_saved_numbers', false);
        $savedCols = is_array($savedColsRaw) ? array_keys($savedColsRaw) : array();
        $wantedCols = array('id','user_id','lottery_id','game_id','source','method','label','status','evaluation_status','score_status','target_draw_date','next_draw_date','date_saved','created_at','generated_at','evaluated_at','scored_at','last_scored_at','main_hits','extra_hits','total_hits','top10_hits','top20_hits','weighted_quality_score','original_recommendation_rank','pre_draw_confidence_rank','original_pre_draw_score','pre_draw_confidence_score','post_draw_score','result_performance_rank','scored_after_draw_date','prediction_group_snapshot');
        $selectCols = array();
        foreach ($wantedCols as $col) { if (in_array($col, $savedCols, true)) { $selectCols[] = $db->quoteName($col); } }
        if (empty($selectCols)) { return $profile; }
        $q = $db->getQuery(true)
            ->select($selectCols)
            ->from($db->quoteName('#__user_saved_numbers'))
            ->where($db->quoteName('user_id') . ' = :mleUserId')
            ->where($db->quoteName('lottery_id') . ' = :mleLotteryId')
            ->order($db->quoteName('id') . ' DESC')
            ->setLimit(200);
        $q->bind(':mleUserId', $userId, \Joomla\Database\ParameterType::INTEGER);
        $q->bind(':mleLotteryId', $lotteryId, \Joomla\Database\ParameterType::INTEGER);
        $db->setQuery($q);
        $rows = (array)$db->loadAssocList();
        $scoredRows = array();
        foreach ($rows as $row) {
            if (!is_array($row)) { continue; }
            if (function_exists('mylottoexpertRowHasUserScoredEvidence') && !mylottoexpertRowHasUserScoredEvidence($row)) { continue; }
            $row['total_hits'] = (int)($row['total_hits'] ?? (($row['main_hits'] ?? 0) + ($row['extra_hits'] ?? 0)));
            $scoredRows[] = $row;
        }
        $profile['scored_runs'] = count($scoredRows);
        if (!empty($scoredRows)) {
            $zero = 0; $one = 0; $two = 0; $three = 0; $sum = 0.0;
            foreach ($scoredRows as $row) {
                $hits = (int)($row['total_hits'] ?? 0);
                $sum += $hits;
                if ($hits <= 0) { $zero++; }
                if ($hits >= 1) { $one++; }
                if ($hits >= 2) { $two++; }
                if ($hits >= 3) { $three++; }
                $mainHitsForBaseline = null;
                foreach (array('main_hits','main_hits_count','matched_count','hit_count') as $mhKey) {
                    if (isset($row[$mhKey]) && is_numeric($row[$mhKey])) { $mainHitsForBaseline = max(0, (int)$row[$mhKey]); break; }
                }
                if ($mainHitsForBaseline !== null && $pickSize > 0 && $domainMax > 1 && function_exists('mylottoexpertV104ExtractPredictedMainCountFromRow')) {
                    $predictedMainCountForBaseline = mylottoexpertV104ExtractPredictedMainCountFromRow($row, $guard);
                    if ($predictedMainCountForBaseline > 0) {
                        $predictedMainCountForBaseline = min($predictedMainCountForBaseline, $domainMax);
                        $mainHitSumForBaseline += (float)$mainHitsForBaseline;
                        $mainHitCountForBaseline++;
                        $expectedMainSumForBaseline += ((float)$pickSize * ((float)$predictedMainCountForBaseline / (float)$domainMax));
                        $expectedMainCountForBaseline++;
                        $predictedMainCountSumForBaseline += (float)$predictedMainCountForBaseline;
                    }
                }
            }
            $count = max(1, count($scoredRows));
            $profile['zero_hit_rate'] = round($zero / $count, 4);
            $profile['one_plus_rate'] = round($one / $count, 4);
            $profile['two_plus_rate'] = round($two / $count, 4);
            $profile['three_plus_rate'] = round($three / $count, 4);
            $profile['avg_hits'] = round($sum / $count, 2);
            $profile['trend'] = mle_calculate_recent_trend($scoredRows);
            $recent5 = array_slice($scoredRows, 0, 5);
            $recent10 = array_slice($scoredRows, 0, 10);
            $avgWindow = function($items) {
                $sum = 0.0;
                $count = 0;
                foreach ((array)$items as $row) { $sum += (float)($row['total_hits'] ?? 0); $count++; }
                return $count > 0 ? ($sum / $count) : null;
            };
            $lotteryGameId = '';
            foreach ($rows as $row) {
                $lotteryGameId = trim((string)($row['game_id'] ?? ''));
                if ($lotteryGameId !== '') { break; }
            }
            $guard = function_exists('mylottoexpertGetGameRangeGuard') ? mylottoexpertGetGameRangeGuard($lotteryGameId) : array();
            $pickSize = (int)($guard['pick_size'] ?? 0);
            $domainMax = (int)($guard['main_max'] ?? 0);
            if ($pickSize > 0 && $domainMax > 0) {
                $profile['random_avg_hits'] = round(($pickSize * $pickSize) / $domainMax, 2);
                $profile['baseline_lift_pct'] = mle_calculate_baseline_lift($profile['avg_hits'], $profile['random_avg_hits']);
                $recent5Avg = $avgWindow($recent5);
                $recent10Avg = $avgWindow($recent10);
                $profile['recent_5_lift_pct'] = mle_calculate_baseline_lift($recent5Avg, $profile['random_avg_hits']);
                $profile['recent_10_lift_pct'] = mle_calculate_baseline_lift($recent10Avg, $profile['random_avg_hits']);
            }
        }
        $gameId = '';
        try {
            $lotteryQ = $db->getQuery(true)
                ->select(array($db->quoteName('game_id')))
                ->from($db->quoteName('#__lotteries'))
                ->where($db->quoteName('lottery_id') . ' = :mleProfileLotteryId')
                ->setLimit(1);
            $lotteryQ->bind(':mleProfileLotteryId', $lotteryId, \Joomla\Database\ParameterType::INTEGER);
            $db->setQuery($lotteryQ);
            $lotteryRow = (array)$db->loadAssoc();
            $gameId = trim((string)($lotteryRow['game_id'] ?? ''));
        } catch (\Throwable $e) {
            $gameId = '';
        }
        if ($gameId !== '') {
            try {
                $profileQ = $db->getQuery(true)
                    ->select(array($db->quoteName('evidence_users'), $db->quoteName('evidence_runs'), $db->quoteName('evidence_draws'), $db->quoteName('baseline_lift'), $db->quoteName('profile_json'), $db->quoteName('status')))
                    ->from($db->quoteName('#__skai_shared_learning_profiles'))
                    ->where($db->quoteName('method_key') . ' = ' . $db->quote('skai'))
                    ->where($db->quoteName('is_active') . ' = 1')
                    ->where($db->quoteName('lottery_id') . ' = :mleProfileLotteryId')
                    ->order($db->quoteName('evidence_runs') . ' DESC, ' . $db->quoteName('updated_at') . ' DESC')
                    ->setLimit(1);
                $profileQ->bind(':mleProfileLotteryId', $lotteryId, \Joomla\Database\ParameterType::INTEGER);
                $db->setQuery($profileQ);
                $sharedProfile = (array)$db->loadAssoc();
                if (!empty($sharedProfile)) {
                    $profile['evidence_users'] = (int)($sharedProfile['evidence_users'] ?? 0);
                    $profile['evidence_draws'] = max($profile['evidence_draws'], (int)($sharedProfile['evidence_draws'] ?? 0));
                    if ($profile['baseline_lift_pct'] === null && isset($sharedProfile['baseline_lift']) && is_numeric($sharedProfile['baseline_lift'])) {
                        $profile['baseline_lift_pct'] = round((float)$sharedProfile['baseline_lift'] * 100, 2);
                    }
                }
            } catch (\Throwable $e) { }
            try {
                $learningQ = $db->getQuery(true)
                    ->select('SUM(' . $db->quoteName('sample_count') . ')')
                    ->from($db->quoteName('#__skai_shared_learning'))
                    ->where($db->quoteName('game_id') . ' = :mleProfileGameId');
                $learningQ->bind(':mleProfileGameId', $gameId);
                $db->setQuery($learningQ);
                $profile['learning_events'] = (int)$db->loadResult();
            } catch (\Throwable $e) {
                $profile['learning_events'] = 0;
            }
        }
        if ($profile['learning_events'] <= 0 && $profile['scored_runs'] <= 0) {
            $profile['maturity_label'] = 'No Learning Yet';
        } elseif ($profile['scored_runs'] <= 0) {
            $profile['maturity_label'] = 'Waiting for First Score';
        } elseif ($profile['scored_runs'] < 5) {
            $profile['maturity_label'] = 'Early Learning';
        } elseif ($profile['scored_runs'] < 10) {
            $profile['maturity_label'] = 'Building Baseline';
        } elseif ($profile['learning_events'] >= 200 || $profile['evidence_draws'] >= 20) {
            $profile['maturity_label'] = 'Mature Prediction History Volume';
        } elseif ($profile['learning_events'] >= 120 || $profile['evidence_draws'] >= 12) {
            $profile['maturity_label'] = 'Strong Prediction History Volume';
        } else {
            $profile['maturity_label'] = 'Useful Prediction History Volume';
        }
        $baselineLiftPct = is_numeric($profile['baseline_lift_pct']) ? (float)$profile['baseline_lift_pct'] : null;
        $zeroHitRate = is_numeric($profile['zero_hit_rate']) ? (float)$profile['zero_hit_rate'] : null;
        $avgHits = is_numeric($profile['avg_hits']) ? (float)$profile['avg_hits'] : null;
        if ($profile['scored_runs'] < 5 || $avgHits === null) {
            $profile['quality_label'] = 'Insufficient';
        } elseif (($baselineLiftPct !== null && $baselineLiftPct >= 20) && ($zeroHitRate === null || $zeroHitRate <= 0.25) && in_array($profile['trend'], array('stable','improving'), true)) {
            $profile['quality_label'] = 'Strong';
        } elseif (($baselineLiftPct !== null && $baselineLiftPct >= 8) && ($zeroHitRate === null || $zeroHitRate <= 0.40)) {
            $profile['quality_label'] = 'Useful';
        } elseif ($profile['trend'] === 'improving' && ($baselineLiftPct === null || $baselineLiftPct > 0)) {
            $profile['quality_label'] = 'Developing';
        } elseif ($zeroHitRate !== null && $zeroHitRate >= 0.60) {
            $profile['quality_label'] = 'Weak';
        } else {
            $profile['quality_label'] = 'Mixed';
        }
        $profile['overfit_flag'] = ($profile['learning_events'] >= 80 && $profile['evidence_draws'] < 5) || ($profile['maturity_label'] === 'Mature Prediction History Volume' && in_array($profile['quality_label'], array('Weak','Mixed'), true));
        if ($profile['quality_label'] === 'Strong' && !$profile['overfit_flag']) {
            $profile['readiness_label'] = 'Can Support Ticket Consideration';
        } elseif (in_array($profile['quality_label'], array('Useful','Strong'), true) && !$profile['overfit_flag'] && $profile['evidence_draws'] >= 8) {
            $profile['readiness_label'] = 'Can Support Precision Lock';
        } elseif (in_array($profile['quality_label'], array('Developing','Useful','Strong'), true) && !$profile['overfit_flag']) {
            $profile['readiness_label'] = 'Can Influence Recommendations';
        } elseif ($profile['scored_runs'] >= 5) {
            $profile['readiness_label'] = 'Can Guide Exploration';
        } else {
            $profile['readiness_label'] = 'Observe Only';
        }
        $profile['quality_grade'] = $profile['quality_label'];
        $profile['readiness'] = $profile['readiness_label'];
        $profile['summary'] = 'Learning Maturity: ' . $profile['maturity_label'] . '. Learning Quality: ' . $profile['quality_label'] . '. Learning Readiness: ' . $profile['readiness_label'] . '.';
        return $profile;
    }
}

if (!function_exists('mle_get_closed_loop_learning_summary')) {
    function mle_get_closed_loop_learning_summary($lottery_id, $db) {
        $lotteryId = (int)$lottery_id;
        $out = array(
            'found' => false,
            'lottery_id' => $lotteryId,
            'game_id' => '',
            'status' => 'learning',
            'is_active' => 0,
            'evidence_runs' => 0,
            'evidence_draws' => 0,
            'unique_users' => 0,
            'avg_recall_at_20' => 0.0,
            'guidance_mode' => '',
            'guidance_reason' => '',
            'learning_health_status' => '',
            'learning_health_reason' => '',
            'updated_at' => '',
            'source' => 'closed_loop',
        );
        if ($lotteryId <= 0 || !is_object($db)) { return $out; }
        try {
            if (function_exists('mleCllV1TableExists') && !mleCllV1TableExists($db, '#__skai_best_settings')) { return $out; }
            $cols = function_exists('mleCllV1ColumnMap') ? mleCllV1ColumnMap($db, '#__skai_best_settings') : array();
            if (empty($cols['lottery_id'])) { return $out; }
            $select = array(
                $db->quoteName('lottery_id'),
                !empty($cols['game_id']) ? $db->quoteName('game_id') : $db->quote('') . ' AS game_id',
                !empty($cols['status']) ? $db->quoteName('status') : $db->quote('learning') . ' AS status',
                !empty($cols['is_active']) ? $db->quoteName('is_active') : '0 AS is_active',
                !empty($cols['evidence_runs']) ? $db->quoteName('evidence_runs') : '0 AS evidence_runs',
                !empty($cols['evidence_draws']) ? $db->quoteName('evidence_draws') : '0 AS evidence_draws',
                !empty($cols['avg_recall_at_20']) ? $db->quoteName('avg_recall_at_20') : '0 AS avg_recall_at_20',
                !empty($cols['guidance_mode']) ? $db->quoteName('guidance_mode') : $db->quote('') . ' AS guidance_mode',
                !empty($cols['guidance_reason']) ? $db->quoteName('guidance_reason') : $db->quote('') . ' AS guidance_reason',
                !empty($cols['learning_health_status']) ? $db->quoteName('learning_health_status') : $db->quote('') . ' AS learning_health_status',
                !empty($cols['learning_health_reason']) ? $db->quoteName('learning_health_reason') : $db->quote('') . ' AS learning_health_reason',
                !empty($cols['updated_at']) ? $db->quoteName('updated_at') : $db->quote('') . ' AS updated_at'
            );
            $q = $db->getQuery(true)
                ->select($select)
                ->from($db->quoteName('#__skai_best_settings'))
                ->where($db->quoteName('lottery_id') . ' = :mleClsLotteryId');
            if (!empty($cols['source_mode'])) { $q->where($db->quoteName('source_mode') . ' = ' . $db->quote('mle_closed_loop_learning_v1')); }
            $order = array();
            if (!empty($cols['is_active'])) { $order[] = $db->quoteName('is_active') . ' DESC'; }
            if (!empty($cols['status'])) { $order[] = "CASE WHEN " . $db->quoteName('status') . " = 'active' THEN 4 WHEN " . $db->quoteName('status') . " = 'learning_guided' THEN 3 WHEN " . $db->quoteName('status') . " = 'learning' THEN 2 ELSE 1 END DESC"; }
            if (!empty($cols['evidence_draws'])) { $order[] = $db->quoteName('evidence_draws') . ' DESC'; }
            if (!empty($cols['evidence_runs'])) { $order[] = $db->quoteName('evidence_runs') . ' DESC'; }
            $order[] = !empty($cols['updated_at']) ? $db->quoteName('updated_at') . ' DESC' : $db->quoteName('id') . ' DESC';
            $q->order(implode(', ', $order))->setLimit(1);
            $q->bind(':mleClsLotteryId', $lotteryId, \Joomla\Database\ParameterType::INTEGER);
            $db->setQuery($q);
            $row = $db->loadAssoc();
            if (!is_array($row) || empty($row)) { return $out; }
            $out['found'] = true;
            foreach ($out as $k => $v) {
                if (array_key_exists($k, $row)) { $out[$k] = $row[$k]; }
            }
            $out['lottery_id'] = $lotteryId;
            $out['game_id'] = trim((string)($row['game_id'] ?? ''));
            $out['status'] = trim((string)($row['status'] ?? 'learning'));
            $out['is_active'] = (int)($row['is_active'] ?? 0);
            $out['evidence_runs'] = (int)($row['evidence_runs'] ?? 0);
            $out['evidence_draws'] = (int)($row['evidence_draws'] ?? 0);
            $out['avg_recall_at_20'] = (float)($row['avg_recall_at_20'] ?? 0);
            $out['guidance_mode'] = trim((string)($row['guidance_mode'] ?? ''));
            $out['guidance_reason'] = trim((string)($row['guidance_reason'] ?? ''));
            $out['learning_health_status'] = trim((string)($row['learning_health_status'] ?? ''));
            $out['learning_health_reason'] = trim((string)($row['learning_health_reason'] ?? ''));
            $out['updated_at'] = trim((string)($row['updated_at'] ?? ''));
            try {
                if (function_exists('mleCllV1TableExists') && mleCllV1TableExists($db, '#__skai_closed_loop_learning_events')) {
                    $uq = $db->getQuery(true)
                        ->select('COUNT(DISTINCT ' . $db->quoteName('user_id') . ')')
                        ->from($db->quoteName('#__skai_closed_loop_learning_events'))
                        ->where($db->quoteName('lottery_id') . ' = :mleClsUserLotteryId');
                    if ($out['game_id'] !== '') { $uq->where($db->quoteName('game_id') . ' = :mleClsUserGameId'); }
                    $uq->bind(':mleClsUserLotteryId', $lotteryId, \Joomla\Database\ParameterType::INTEGER);
                    if ($out['game_id'] !== '') { $uq->bind(':mleClsUserGameId', $out['game_id']); }
                    $db->setQuery($uq);
                    $out['unique_users'] = (int)$db->loadResult();
                }
            } catch (\Throwable $e) { }
        } catch (\Throwable $e) {
            $out['found'] = false;
        }
        return $out;
    }
}


/* [[MLE_V185_LEARNING_EVIDENCE_DASHBOARD]]
   Builds a strict admin evidence audit for confidence source selection.
   The public confidence source must not reset just because the latest exact
   settings fingerprint is a one-row pending bucket. Exact fingerprint evidence
   is useful only after it has enough scored rows and independent draw dates.
*/
if (!function_exists('mle_v185_count_learning_evidence')) {
    function mle_v185_count_learning_evidence($db, $gameId, $fingerprint = '', array $fingerprintList = array()) {
        $empty = array(
            'total_rows' => 0,
            'scored_rows' => 0,
            'pending_rows' => 0,
            'draw_dates' => 0,
            'settings_rows' => 0,
            'users' => 0,
            'first_saved' => '',
            'last_saved' => '',
            'reason' => ''
        );
        $gameId = trim((string)$gameId);
        if (!is_object($db) || $gameId === '') { $empty['reason'] = 'missing_game_id'; return $empty; }
        try {
            $colsRaw = $db->getTableColumns('#__user_saved_numbers', false);
            $cols = is_array($colsRaw) ? array_keys($colsRaw) : array();
            if (empty($cols)) { $empty['reason'] = 'saved_numbers_columns_unavailable'; return $empty; }
            $alias = 's';
            $qn = function($col) use ($db, $alias) { return $alias . '.' . $db->quoteName($col); };
            $nullDate = function($col) use ($db, $alias, $cols) {
                if (!in_array($col, $cols, true)) { return 'NULL'; }
                return 'NULLIF(' . $alias . '.' . $db->quoteName($col) . ', ' . $db->quote('0000-00-00') . ')';
            };
            $gameParts = array();
            if (in_array('target_game_id', $cols, true)) { $gameParts[] = $qn('target_game_id') . ' = ' . $db->quote($gameId); }
            if (in_array('game_id', $cols, true)) { $gameParts[] = $qn('game_id') . ' = ' . $db->quote($gameId); }
            if (empty($gameParts)) { $empty['reason'] = 'missing_game_columns'; return $empty; }
            $where = array('(' . implode(' OR ', $gameParts) . ')');
            if ($fingerprint !== '' && in_array('hive_settings_fingerprint', $cols, true)) {
                $where[] = $qn('hive_settings_fingerprint') . ' = ' . $db->quote($fingerprint);
            } elseif (!empty($fingerprintList) && in_array('hive_settings_fingerprint', $cols, true)) {
                $safe = array();
                foreach ($fingerprintList as $fp) {
                    $fp = trim((string)$fp);
                    if ($fp !== '') { $safe[$fp] = $db->quote($fp); }
                }
                if (!empty($safe)) { $where[] = $qn('hive_settings_fingerprint') . ' IN (' . implode(',', array_values($safe)) . ')'; }
            }
            $scoredBits = array();
            if (in_array('evaluation_status', $cols, true)) { $scoredBits[] = 'LOWER(TRIM(COALESCE(' . $qn('evaluation_status') . ', ' . $db->quote('') . '))) IN (' . $db->quote('scored') . ',' . $db->quote('evaluated') . ',' . $db->quote('completed') . ',' . $db->quote('saved_scored') . ')'; }
            foreach (array('evaluated_at','scored_at','last_scored_at') as $dtCol) {
                if (in_array($dtCol, $cols, true)) { $scoredBits[] = '(' . $qn($dtCol) . ' IS NOT NULL AND ' . $qn($dtCol) . ' <> ' . $db->quote('0000-00-00 00:00:00') . ')'; }
            }
            if (in_array('actual_draw_date', $cols, true)) { $scoredBits[] = '(' . $qn('actual_draw_date') . ' IS NOT NULL AND ' . $qn('actual_draw_date') . ' <> ' . $db->quote('0000-00-00') . ')'; }
            if (in_array('actual_numbers_json', $cols, true)) { $scoredBits[] = '(' . $qn('actual_numbers_json') . ' IS NOT NULL AND TRIM(' . $qn('actual_numbers_json') . ') <> ' . $db->quote('') . ')'; }
            $scoredExpr = !empty($scoredBits) ? '(' . implode(' OR ', $scoredBits) . ')' : '0';
            $drawExpr = 'COALESCE(' . implode(',', array(
                $nullDate('actual_draw_date'),
                $nullDate('target_draw_date'),
                $nullDate('next_draw_date'),
                $nullDate('draw_date')
            )) . ')';
            $settingsBits = array();
            foreach (array('settings_json','settings','params_json','full_settings_json','batch_settings_json','batch_full_settings_json') as $settingsCol) {
                if (in_array($settingsCol, $cols, true)) { $settingsBits[] = '(' . $qn($settingsCol) . ' IS NOT NULL AND TRIM(' . $qn($settingsCol) . ') <> ' . $db->quote('') . ')'; }
            }
            $settingsExpr = !empty($settingsBits) ? '(' . implode(' OR ', $settingsBits) . ')' : '0';
            $dateSavedExpr = in_array('date_saved', $cols, true) ? $qn('date_saved') : (in_array('created_at', $cols, true) ? $qn('created_at') : 'NULL');
            $userExpr = in_array('user_id', $cols, true) ? $qn('user_id') : 'NULL';
            $sql = 'SELECT COUNT(*) AS total_rows, '
                 . 'SUM(CASE WHEN ' . $scoredExpr . ' THEN 1 ELSE 0 END) AS scored_rows, '
                 . 'SUM(CASE WHEN NOT (' . $scoredExpr . ') THEN 1 ELSE 0 END) AS pending_rows, '
                 . 'COUNT(DISTINCT DATE(' . $drawExpr . ')) AS draw_dates, '
                 . 'SUM(CASE WHEN ' . $settingsExpr . ' THEN 1 ELSE 0 END) AS settings_rows, '
                 . 'COUNT(DISTINCT ' . $userExpr . ') AS users, '
                 . 'MIN(' . $dateSavedExpr . ') AS first_saved, MAX(' . $dateSavedExpr . ') AS last_saved '
                 . 'FROM ' . $db->quoteName('#__user_saved_numbers', $alias) . ' WHERE ' . implode(' AND ', $where);
            $db->setQuery($sql);
            $row = (array)$db->loadAssoc();
            if (empty($row)) { return $empty; }
            return array(
                'total_rows' => (int)($row['total_rows'] ?? 0),
                'scored_rows' => (int)($row['scored_rows'] ?? 0),
                'pending_rows' => (int)($row['pending_rows'] ?? 0),
                'draw_dates' => (int)($row['draw_dates'] ?? 0),
                'settings_rows' => (int)($row['settings_rows'] ?? 0),
                'users' => (int)($row['users'] ?? 0),
                'first_saved' => (string)($row['first_saved'] ?? ''),
                'last_saved' => (string)($row['last_saved'] ?? ''),
                'reason' => ''
            );
        } catch (\Throwable $e) {
            $empty['reason'] = 'evidence_query_failed';
            return $empty;
        }
    }
}

if (!function_exists('mle_v185_build_learning_evidence_dashboard')) {
    function mle_v185_build_learning_evidence_dashboard($db, $lotteryId, $gameId, array $targetRow = array()) {
        $fingerprint = trim((string)($targetRow['hive_settings_fingerprint'] ?? ''));
        $gameId = trim((string)$gameId);
        if ($gameId === '') {
            foreach (array('target_game_id','game_id') as $k) {
                $candidate = trim((string)($targetRow[$k] ?? ''));
                if ($candidate !== '') { $gameId = $candidate; break; }
            }
        }
        $out = array(
            'available' => false,
            'lottery_id' => (int)$lotteryId,
            'game_id' => $gameId,
            'active_settings_fingerprint' => $fingerprint,
            'confidence_source' => 'unknown',
            'source_reason' => 'Prediction History not available yet.',
            'minimum_scored_rows' => 27,
            'minimum_draw_dates' => 10,
            'exact_fingerprint' => array(),
            'compatible_family' => array(),
            'game_level' => array(),
            'family_key' => '',
            'family_fingerprint_count' => 0,
            'selected_scored_rows' => 0,
            'selected_draw_dates' => 0
        );
        if (!is_object($db) || $gameId === '') { $out['source_reason'] = 'Missing canonical game_id.'; return $out; }
        $familyFingerprints = array();
        $familyKey = '';
        if ($fingerprint !== '') {
            try {
                if (function_exists('mylottoexpertTableExistsSafe') && mylottoexpertTableExistsSafe($db, $db->getPrefix() . 'mle_lottery_research_queue')) {
                    $qColsRaw = $db->getTableColumns('#__mle_lottery_research_queue', false);
                    $qCols = is_array($qColsRaw) ? array_keys($qColsRaw) : array();
                    if (in_array('settings_fingerprint', $qCols, true)) {
                        $select = array();
                        foreach (array('setting_family','setting_key','control_value') as $c) { if (in_array($c, $qCols, true)) { $select[] = $db->quoteName($c); } }
                        if (!empty($select)) {
                            $q = $db->getQuery(true)
                                ->select($select)
                                ->from($db->quoteName('#__mle_lottery_research_queue'))
                                ->where($db->quoteName('game_id') . ' = ' . $db->quote($gameId))
                                ->where($db->quoteName('settings_fingerprint') . ' = ' . $db->quote($fingerprint))
                                ->setLimit(1);
                            $db->setQuery($q);
                            $fam = (array)$db->loadAssoc();
                            $familyKey = trim((string)($fam['setting_family'] ?? '')) . '|' . trim((string)($fam['setting_key'] ?? '')) . '|' . trim((string)($fam['control_value'] ?? ''));
                            $out['family_key'] = trim($familyKey, '|');
                            if (trim($familyKey, '|') !== '') {
                                $where = array(
                                    $db->quoteName('game_id') . ' = ' . $db->quote($gameId),
                                    $db->quoteName('settings_fingerprint') . ' <> ' . $db->quote('')
                                );
                                foreach (array('setting_family','setting_key','control_value') as $c) {
                                    if (in_array($c, $qCols, true) && array_key_exists($c, $fam)) { $where[] = $db->quoteName($c) . ' = ' . $db->quote((string)$fam[$c]); }
                                }
                                $fq = $db->getQuery(true)
                                    ->select('DISTINCT ' . $db->quoteName('settings_fingerprint'))
                                    ->from($db->quoteName('#__mle_lottery_research_queue'))
                                    ->where($where)
                                    ->order($db->quoteName('id') . ' DESC');
                                $db->setQuery($fq, 0, 500);
                                $familyFingerprints = (array)$db->loadColumn();
                                $out['family_fingerprint_count'] = count($familyFingerprints);
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {
                $familyFingerprints = array();
            }
        }
        $out['exact_fingerprint'] = ($fingerprint !== '') ? mle_v185_count_learning_evidence($db, $gameId, $fingerprint, array()) : mle_v185_count_learning_evidence($db, $gameId, '__no_exact_fingerprint__', array());
        $out['compatible_family'] = !empty($familyFingerprints) ? mle_v185_count_learning_evidence($db, $gameId, '', $familyFingerprints) : array('total_rows'=>0,'scored_rows'=>0,'pending_rows'=>0,'draw_dates'=>0,'settings_rows'=>0,'users'=>0,'first_saved'=>'','last_saved'=>'','reason'=>'no_compatible_family_fingerprints');
        $out['game_level'] = mle_v185_count_learning_evidence($db, $gameId, '', array());
        $minRows = (int)$out['minimum_scored_rows'];
        $minDraws = (int)$out['minimum_draw_dates'];
        $source = 'game_level';
        $reason = 'Exact fingerprint and compatible-family prediction history are below the minimum, so confidence falls back to canonical game-level completed prediction history.';
        if ((int)($out['exact_fingerprint']['scored_rows'] ?? 0) >= $minRows && (int)($out['exact_fingerprint']['draw_dates'] ?? 0) >= $minDraws) {
            $source = 'exact_fingerprint';
            $reason = 'Exact settings fingerprint has enough scored rows and independent draw dates.';
        } elseif ((int)($out['compatible_family']['scored_rows'] ?? 0) >= $minRows && (int)($out['compatible_family']['draw_dates'] ?? 0) >= $minDraws) {
            $source = 'compatible_family';
            $reason = 'Exact fingerprint is thin, but compatible settings-family prediction history has enough scored support.';
        } elseif ((int)($out['game_level']['scored_rows'] ?? 0) >= $minRows && (int)($out['game_level']['draw_dates'] ?? 0) >= $minDraws) {
            $source = 'game_level';
            $reason = 'Exact/family prediction history is thin; canonical game-level AI/Shared AI Learning history prevents a false learning reset.';
        } else {
            $source = 'collecting';
            $reason = 'No source has enough completed prediction history yet.';
        }
        $selected = ($source === 'exact_fingerprint') ? $out['exact_fingerprint'] : (($source === 'compatible_family') ? $out['compatible_family'] : (($source === 'game_level') ? $out['game_level'] : array()));
        $out['available'] = true;
        $out['confidence_source'] = $source;
        $out['source_reason'] = $reason;
        $out['selected_scored_rows'] = (int)($selected['scored_rows'] ?? 0);
        $out['selected_draw_dates'] = (int)($selected['draw_dates'] ?? 0);
        return $out;
    }
}

