            $sum = 0.0; $best = 0; $zero = 0; $one = 0; $two = 0; $three = 0;
            $mainHitSumForBaseline = 0.0; $mainHitCountForBaseline = 0; $expectedMainSumForBaseline = 0.0; $expectedMainCountForBaseline = 0; $predictedMainCountSumForBaseline = 0.0;
            foreach ($scoredRows as $row) {
                $hits = (int)($row['total_hits'] ?? 0);
                $sum += $hits;
                if ($hits > $best) { $best = $hits; }
                if ($hits <= 0) { $zero++; }
                if ($hits >= 1) { $one++; }
                if ($hits >= 2) { $two++; }
                if ($hits >= 3) { $three++; }
            }
            $windowAvg = function($items) {
                $sum = 0.0; $count = 0;
                foreach ((array)$items as $row) { $sum += (float)($row['total_hits'] ?? 0); $count++; }
                return $count > 0 ? round($sum / $count, 2) : null;
            };
            $result['zero_hit_rate'] = round($zero / $count, 4);
            $result['one_plus_rate'] = round($one / $count, 4);
            $result['two_plus_rate'] = round($two / $count, 4);
            $result['three_plus_rate'] = round($three / $count, 4);
            $result['avg_hits'] = round($sum / $count, 2);
            $result['best_hits'] = $best;
            $result['recent_3_avg_hits'] = $windowAvg(array_slice($scoredRows, 0, 3));
            $result['recent_5_avg_hits'] = $windowAvg(array_slice($scoredRows, 0, 5));
            $result['recent_10_avg_hits'] = $windowAvg(array_slice($scoredRows, 0, 10));
            $result['all_time_avg_hits'] = $result['avg_hits'];
            $result['recent_trend'] = mle_calculate_recent_trend($scoredRows);
            if ($expectedMainCountForBaseline > 0 && $mainHitCountForBaseline > 0) {
                $result['random_expected_avg_hits'] = round($expectedMainSumForBaseline / max(1, $expectedMainCountForBaseline), 2);
                $result['baseline_lift_pct'] = mle_calculate_baseline_lift(($mainHitSumForBaseline / max(1, $mainHitCountForBaseline)), $result['random_expected_avg_hits']);
                $result['baseline_candidate_count'] = round($predictedMainCountSumForBaseline / max(1, $expectedMainCountForBaseline), 2);
            } else {
                $result['random_expected_avg_hits'] = null;
                $result['baseline_lift_pct'] = null;
            }
            if ($result['baseline_lift_pct'] === null) { $result['baseline_status'] = 'unknown'; }
            elseif ($result['baseline_lift_pct'] > 0) { $result['baseline_status'] = 'above_random'; }
            elseif ($result['baseline_lift_pct'] < 0) { $result['baseline_status'] = 'below_random'; }
            else { $result['baseline_status'] = 'at_random'; }
        }
        $learningProfile = mle_build_learning_quality_profile($lotteryId, $db);
        $result['learning_profile'] = $learningProfile;
        $hiveTop20 = array();
        $hiveTop10 = array();
        if ($gameId !== '') {
            try {
                $hiveQ = $db->getQuery(true)
                    ->select(array($db->quoteName('learning_key'), $db->quoteName('metric_json'), $db->quoteName('sample_count')))
                    ->from($db->quoteName('#__skai_shared_learning'))
                    ->where($db->quoteName('game_id') . ' = :mleEvidenceGameId')
                    ->order($db->quoteName('sample_count') . ' DESC, ' . $db->quoteName('updated_at') . ' DESC');
                $hiveQ->bind(':mleEvidenceGameId', $gameId);
                $db->setQuery($hiveQ, 0, 5);
                $hiveRows = (array)$db->loadAssocList();
                $freq = array();
                foreach ($hiveRows as $hiveRow) {
                    $metric = json_decode((string)($hiveRow['metric_json'] ?? ''), true);
                    if (!is_array($metric)) { continue; }
                    $sourceFreq = array();
                    if (isset($metric['frequency']) && is_array($metric['frequency'])) { $sourceFreq = $metric['frequency']; }
                    elseif (isset($metric['numbers']) && is_array($metric['numbers'])) { $sourceFreq = $metric['numbers']; }
                    foreach ($sourceFreq as $num => $countVal) {
                        $num = (int)$num;
                        $countVal = is_numeric($countVal) ? (float)$countVal : 0.0;
                        if ($num <= 0 && empty($guard['is_daily'])) { continue; }
                        if (!isset($freq[$num])) { $freq[$num] = 0.0; }
                        $freq[$num] += $countVal;
                    }
                }
                if (!empty($freq)) {
                    arsort($freq, SORT_NUMERIC);
                    $hiveTop20 = array_slice(array_map('intval', array_keys($freq)), 0, 20);
                    $hiveTop10 = array_slice($hiveTop20, 0, 10);
                }
            } catch (\Throwable $e) {
                $hiveTop20 = array();
                $hiveTop10 = array();
            }
        }
        if (!empty($targetRow)) {
            $result['method_source'] = function_exists('mylottoexpertAnalysisSourceLabel')
                ? (string)mylottoexpertAnalysisSourceLabel($targetRow)
                : trim((string)($targetRow['analysis_engine_label'] ?? $targetRow['method_label'] ?? $targetRow['source'] ?? 'Unknown'));
            if ($result['method_source'] === '') { $result['method_source'] = 'Unknown'; }
            $savedDateRaw = trim((string)($targetRow['date_saved'] ?? $targetRow['generated_at'] ?? $targetRow['created_at'] ?? ''));
            $targetDrawRaw = trim((string)($targetRow['target_draw_date'] ?? $targetRow['next_draw_date'] ?? $targetRow['draw_date'] ?? ''));
            $result['saved_run_date'] = $savedDateRaw;
            $result['target_draw'] = $targetDrawRaw;
            $batchIndex = (int)($targetRow['batch_index'] ?? $targetRow['source_batch_run_order'] ?? 0);
            $batchTotal = (int)($targetRow['batch_total'] ?? 0);
            if ($batchIndex > 0 && $batchTotal > 0) { $result['batch_position'] = 'Run ' . $batchIndex . ' of ' . $batchTotal; }
            elseif ($batchIndex > 0) { $result['batch_position'] = 'Run ' . $batchIndex; }
            else { $result['batch_position'] = 'Not Available'; }
            $savedTs = $savedDateRaw !== '' ? strtotime($savedDateRaw) : false;
            $targetTs = $targetDrawRaw !== '' ? strtotime($targetDrawRaw) : false;
            $result['saved_before_draw'] = ($savedTs !== false && $targetTs !== false) ? ($savedTs <= $targetTs) : ($savedDateRaw !== '' && $targetDrawRaw !== '');
            $result['prediction_numbers'] = $parseNumbers($targetRow['main_numbers'] ?? '', !empty($guard['is_daily']));
            if (empty($result['prediction_numbers']) && !empty($targetRow['predicted_ranking_json'])) {
                $rankedPool = $parseNumbers($targetRow['predicted_ranking_json'], !empty($guard['is_daily']));
                if ($pickSize > 0) { $result['prediction_numbers'] = array_slice($rankedPool, 0, $pickSize); }
            }
            $hiveSignal = mle_calculate_hive_ranking_signal($result['prediction_numbers'], $hiveTop20, $hiveTop10, $pickSize);
            $result['hive_ranking_signal'] = (string)($hiveSignal['signal'] ?? 'Unknown');
            $result['hive_ranking_explanation'] = (string)($hiveSignal['explanation'] ?? 'Shared AI Learning ranked number data is not available for this lottery.');
            $topMethod = trim((string)($targetRow['analysis_method_key'] ?? $targetRow['method'] ?? $targetRow['source'] ?? 'skai'));
            $precisionLock = function_exists('mleAdvisoryComputePrecisionLockData') ? mleAdvisoryComputePrecisionLockData($scoredRows, $savedById, $topMethod) : array();
            $result['precision_lock_status'] = mle_calculate_precision_lock_status((string)($precisionLock['stage'] ?? ''), (string)($precisionLock['summary'] ?? ''), (array)$precisionLock);
            $isScoredTarget = function_exists('mylottoexpertRowHasUserScoredEvidence') ? mylottoexpertRowHasUserScoredEvidence($targetRow) : false;
            if ($isScoredTarget) {
                $result['official_scoring_status'] = !empty($targetRow['actual_numbers_json']) || !empty($targetRow['actual_main_numbers']) ? 'Verified Against Official Draw' : 'Scored';
            } elseif ($targetTs !== false && $targetTs > strtotime(date('Y-m-d'))) {
                $result['official_scoring_status'] = 'Pending Official Draw';
            } elseif ($targetTs !== false && $targetTs <= strtotime(date('Y-m-d'))) {
                $result['official_scoring_status'] = 'Waiting for Official Results';
            } else {
                $result['official_scoring_status'] = 'Waiting for Official Results';
            }
        } else {
            $result['official_scoring_status'] = 'No Saved Prediction';
            $result['batch_position'] = 'Not Available';
        }
        $result['risk_signal'] = mle_calculate_risk_signal($result['scored_runs'], $result['zero_hit_rate'], $result['recent_trend'], $result['recent_5_avg_hits'], $result['all_time_avg_hits']);
        $result['historical_performance_signal'] = mle_calculate_historical_performance_signal($result['scored_runs'], $result['zero_hit_rate'], $result['one_plus_rate'], $result['avg_hits'], $result['baseline_lift_pct'], $result['recent_trend']);
        $rawConfidence = 'No Confidence Yet';
        if ($result['scored_runs'] >= 25 && ($result['zero_hit_rate'] === null || $result['zero_hit_rate'] <= 0.20) && $result['baseline_lift_pct'] !== null && $result['baseline_lift_pct'] >= 25 && in_array($result['recent_trend'], array('stable','improving'), true) && in_array($result['hive_ranking_signal'], array('Strong Shared AI Learning Support','Top Shared AI Learning Alignment'), true) && in_array($result['precision_lock_status'], array('Keep Locked','Testing Inside Range'), true)) {
            $rawConfidence = 'High-Confidence Candidate';
        } elseif ($result['scored_runs'] >= 15 && ($result['zero_hit_rate'] === null || $result['zero_hit_rate'] <= 0.30) && $result['baseline_lift_pct'] !== null && $result['baseline_lift_pct'] >= 10 && in_array($result['recent_trend'], array('stable','improving'), true)) {
            $rawConfidence = 'Strong Candidate';
        } elseif ($result['scored_runs'] >= 10 && ($result['zero_hit_rate'] === null || $result['zero_hit_rate'] <= 0.45) && ($result['baseline_lift_pct'] === null || $result['baseline_lift_pct'] > 0)) {
            $rawConfidence = 'Promising Signal';
        } elseif ($result['scored_runs'] >= 5) {
            $rawConfidence = 'Developing Signal';
        } elseif ($result['scored_runs'] > 0) {
            $rawConfidence = 'Early Learning';
        }
        $result['prediction_confidence'] = mle_apply_confidence_caps($rawConfidence, $result['scored_runs'], $result['zero_hit_rate'], $result['baseline_lift_pct'], $result['recent_trend'], $result['hive_ranking_signal'], $result['precision_lock_status'], $result['saved_before_draw']);
        $result['prediction_quality_signal'] = mle_calculate_prediction_quality_signal($result['prediction_confidence'], $result['hive_ranking_signal'], $result['precision_lock_status'], $result['risk_signal']);
        $result['recommendation_role'] = mle_calculate_recommendation_readiness($result['prediction_confidence'], $result['scored_runs'], $result['zero_hit_rate'], $result['hive_ranking_signal'], $result['precision_lock_status'], $result['recent_trend'], $result['is_top_recommendation'], $result['saved_before_draw'], $result['baseline_lift_pct'], (string)($learningProfile['readiness_label'] ?? 'Observe Only'));
        $result['recommendation_readiness'] = $result['recommendation_role'];
        if ($result['official_scoring_status'] === 'No Saved Prediction') {
            $result['official_scoring_status'] = 'No Exact Saved Prediction for Latest Draw';
            if (!empty($result['closed_loop_summary']['found'])) {
                $result['next_best_action'] = 'Use the current LottoExpert Learning guidance and run the ready batch when appropriate.';
                $result['why_this_matters'] = 'No exact saved prediction was matched to the latest completed draw, but historical LottoExpert Learning prediction history is available for this lottery.';
                $result['historical_performance_signal'] = 'Historical Learning Available';
            } else {
                $result['next_best_action'] = 'Save a prediction before the draw so LottoExpert can build prediction history.';
                $result['why_this_matters'] = 'There is no saved prediction for this lottery right now, so confidence stays at the safest fallback.';
            }
        } elseif ($result['official_scoring_status'] === 'Pending Official Draw') {
            $result['next_best_action'] = 'Wait for the official draw, then score the saved run.';
            $result['why_this_matters'] = 'This prediction is still pending the official draw, so the strip separates status from confidence and keeps pending rows out of historical success math.';
        } elseif ($result['risk_signal'] === 'Recent Drop-Off') {
            $result['next_best_action'] = 'Review the recent decline before trusting this signal.';
            $result['why_this_matters'] = 'Recent scored runs weakened compared with the prior window, so confidence is capped until the trend stabilizes.';
        } elseif ($result['recommendation_role'] === 'Ticket Consideration Candidate') {
            $result['next_best_action'] = 'Review this top saved prediction carefully before deciding whether to use it.';
            $result['why_this_matters'] = 'Ticket Consideration Candidate does not mean a guaranteed win. It means this is the best-supported candidate based on LottoExpert completed prediction history.';
        } elseif ($result['recommendation_role'] === 'Review Candidate') {
            $result['next_best_action'] = 'Review the range and Shared AI Learning support before trusting this prediction.';
            $result['why_this_matters'] = 'One or more prediction history gates are warning that this prediction needs more review before stronger language is used.';
        } else {
            $result['next_best_action'] = 'Keep collecting completed prediction history.';
            $result['why_this_matters'] = 'This signal is based on scored official prediction history only, with safe fallbacks when Shared AI Learning, baseline, or precision data are incomplete.';
        }
        return $result;
    }
}

if (!function_exists('mle_render_prediction_indicator_strip')) {
    function mle_render_prediction_indicator_strip($evidence, $learning) {
        $evidence = is_array($evidence) ? $evidence : array();
        $learning = is_array($learning) ? $learning : array();
        $closedLoop = !empty($evidence['closed_loop_summary']) && is_array($evidence['closed_loop_summary']) ? $evidence['closed_loop_summary'] : array();
        $hasClosedLoop = !empty($closedLoop['found']) && ((int)($closedLoop['evidence_runs'] ?? 0) > 0 || (int)($closedLoop['evidence_draws'] ?? 0) > 0);
        $esc = function($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); };
        $fmtStatus = function($value) {
            $value = trim((string)$value);
            if ($value === '') { return 'Not Available'; }
            $value = str_replace(array('_','-'), ' ', $value);
            return ucwords($value);
        };
        $baselineValue = 'Pending';
        if (isset($evidence['baseline_lift_pct']) && is_numeric($evidence['baseline_lift_pct'])) {
            $baselinePct = (float)$evidence['baseline_lift_pct'];
            $baselineValue = ($baselinePct >= 0 ? '+' : '') . number_format($baselinePct, 2) . '% vs random';
        }
        $exactStatus = trim((string)($evidence['official_scoring_status'] ?? 'Unknown'));
        if ($exactStatus === 'No Saved Prediction') { $exactStatus = 'No exact saved prediction for latest draw'; }
        $historicalStatus = $hasClosedLoop ? 'Available' : (trim((string)($evidence['historical_performance_signal'] ?? '')) ?: 'Building');
        $learningStatus = $hasClosedLoop
            ? (((int)($closedLoop['is_active'] ?? 0) === 1 || strtolower((string)($closedLoop['status'] ?? '')) === 'active') ? 'Learning Active' : $fmtStatus($closedLoop['status'] ?? 'Learning'))
            : ($learning['readiness_label'] ?? 'Building');
        $healthStatus = $hasClosedLoop ? $fmtStatus($closedLoop['learning_health_status'] ?? '') : 'Pending';
        $runs = $hasClosedLoop ? (int)($closedLoop['evidence_runs'] ?? 0) : (int)($evidence['scored_runs'] ?? 0);
        $draws = $hasClosedLoop ? (int)($closedLoop['evidence_draws'] ?? 0) : (int)($evidence['completed_draw_cycles'] ?? 0);
        $users = $hasClosedLoop ? (int)($closedLoop['unique_users'] ?? 0) : 0;
        $recall = $hasClosedLoop && isset($closedLoop['avg_recall_at_20']) ? number_format((float)$closedLoop['avg_recall_at_20'], 4) : 'Pending';
        $html = '';
        $html .= '<section class="mle-evidence-panel" data-mle-evidence-strip="1" aria-label="Prediction evidence indicators" style="border:1px solid #cfe0ff;border-radius:16px;background:#fff;box-shadow:0 8px 22px rgba(15,23,42,.06);margin:14px 0;overflow:hidden;">';
        $html .= '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:14px 16px;background:linear-gradient(135deg,#eff6ff,#ffffff);border-bottom:1px solid #dbeafe;">';
        $html .= '<div><div style="font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#1d4ed8;">Prediction History Review</div>';
        $html .= '<div style="font-size:15px;font-weight:900;color:#0f172a;margin-top:3px;">Current draw status and historical learning prediction history</div>';
        $html .= '<p style="margin:6px 0 0;color:#334155;font-size:13px;line-height:1.45;">' . $esc($evidence['why_this_matters'] ?? 'LottoExpert separates the current draw match from long-term learning prediction history.') . '</p></div>';
        $html .= '<span style="white-space:nowrap;align-self:center;border:1px solid #bbf7d0;background:#dcfce7;color:#14532d;border-radius:999px;padding:6px 10px;font-size:12px;font-weight:900;">' . $esc($learningStatus) . '</span>';
        $html .= '</div>';
        $cards = array(
            array('Current draw match', $exactStatus, 'No exact match only means this latest official draw was not tied to a saved prediction card.'),
            array('Historical learning prediction history', $historicalStatus, $hasClosedLoop ? number_format($runs) . ' scored runs across ' . number_format($draws) . ' draw cycles from all users.' : 'Prediction History is still building.'),
            array('Recommended next action', $evidence['next_best_action'] ?? 'Keep collecting completed prediction history.', 'Uses aggregate learning prediction history; it is not limited to the visible 10 prediction cards.'),
        );
        $html .= '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;padding:14px 16px;">';
        foreach ($cards as $card) {
            $html .= '<div style="border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc;padding:12px;">';
            $html .= '<div style="font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;color:#64748b;">' . $esc($card[0]) . '</div>';
            $html .= '<div style="font-size:14px;font-weight:900;color:#0f172a;margin-top:4px;">' . $esc($card[1]) . '</div>';
            $html .= '<div style="font-size:12px;color:#475569;line-height:1.45;margin-top:5px;">' . $esc($card[2]) . '</div>';
            $html .= '</div>';
        }
        $html .= '</div>';
        $html .= '<details style="border-top:1px solid #e2e8f0;background:#fff;"><summary style="cursor:pointer;padding:12px 16px;font-weight:900;color:#1d4ed8;">View advanced prediction history</summary>';
        $html .= '<div style="overflow:auto;padding:0 16px 16px;">';
        $html .= '<table style="width:100%;border-collapse:separate;border-spacing:0;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;font-size:12px;">';
        $html .= '<tbody>';
        $rows = array(
            array('Prediction confidence', $evidence['prediction_confidence'] ?? 'No Confidence Yet'),
            array('Official scoring status', $exactStatus),
            array('Recommendation role', $evidence['recommendation_role'] ?? 'Watch Only'),
            array('Historical learning runs', $runs > 0 ? number_format($runs) : 'Building'),
            array('Historical draw cycles', $draws > 0 ? number_format($draws) : 'Building'),
            array('Learning health', $healthStatus),
            array('Recall@20 baseline', $recall),
            array('Risk signal', $evidence['risk_signal'] ?? 'Needs More Draws'),
            array('Recent trend', $evidence['recent_trend'] ?? 'insufficient'),
            array('Baseline lift', $baselineValue),
            array('Method source', $evidence['method_source'] ?? 'Not Available'),
            array('Saved run date', $evidence['saved_run_date'] ?? 'Not Available'),
            array('Target draw', $evidence['target_draw'] ?? 'Not Available'),
            array('Batch position', $evidence['batch_position'] ?? 'Not Available'),
            array('Learning maturity', $learning['maturity_label'] ?? ($hasClosedLoop ? 'Historical Prediction History Available' : 'Building')),
            array('Learning quality', $learning['quality_label'] ?? 'Building'),
            array('Learning readiness', $learning['readiness_label'] ?? ($hasClosedLoop ? 'Can Guide Exploration' : 'Observe Only')),
        );
        $dashboard = !empty($evidence['learning_evidence_dashboard']) && is_array($evidence['learning_evidence_dashboard']) ? $evidence['learning_evidence_dashboard'] : array();
        $showAdminEvidence = false;
        try {
            $viewer = \Joomla\CMS\Factory::getApplication()->getIdentity();
            $showAdminEvidence = is_object($viewer) && method_exists($viewer, 'authorise') && ($viewer->authorise('core.admin') || $viewer->authorise('core.manage'));
        } catch (\Throwable $e) { $showAdminEvidence = false; }
        if ($showAdminEvidence && !empty($dashboard)) {
            $fmtCountPair = function($bucket) {
                $bucket = is_array($bucket) ? $bucket : array();
                return number_format((int)($bucket['scored_rows'] ?? 0)) . ' scored / ' . number_format((int)($bucket['draw_dates'] ?? 0)) . ' draw dates / ' . number_format((int)($bucket['total_rows'] ?? 0)) . ' total';
            };
            $rows[] = array('Confidence prediction history source', $fmtStatus($dashboard['confidence_source'] ?? 'unknown'));
            $rows[] = array('Confidence source reason', $dashboard['source_reason'] ?? 'Not Available');
            $rows[] = array('Exact fingerprint prediction history', $fmtCountPair($dashboard['exact_fingerprint'] ?? array()));
            $rows[] = array('Compatible-family prediction history', $fmtCountPair($dashboard['compatible_family'] ?? array()));
            $rows[] = array('Game-level prediction history', $fmtCountPair($dashboard['game_level'] ?? array()));
            $rows[] = array('Active settings fingerprint', $dashboard['active_settings_fingerprint'] ?? 'Not Available');
            $rows[] = array('Family key', $dashboard['family_key'] ?? 'Not Available');
        }
        foreach ($rows as $i => $row) {
            $bg = ($i % 2 === 0) ? '#ffffff' : '#f8fafc';
            $value = trim((string)$row[1]) !== '' ? (string)$row[1] : 'Not Available';
            $html .= '<tr style="background:' . $bg . '"><th style="text-align:left;padding:9px 11px;width:32%;border-bottom:1px solid #e2e8f0;color:#475569;font-weight:900;">' . $esc($row[0]) . '</th><td style="padding:9px 11px;border-bottom:1px solid #e2e8f0;color:#0f172a;">' . $esc($value) . '</td></tr>';
        }
        $explain = $hasClosedLoop
            ? 'This advanced table uses LottoExpert Learning aggregate prediction history where available, so historical prediction history is not reset when the latest draw has no exact saved prediction match.'
            : ($evidence['hive_ranking_explanation'] ?? 'Historical learning prediction history is still building for this lottery.');
        $html .= '</tbody></table><p style="margin:10px 0 0;color:#475569;font-size:12px;line-height:1.45;">' . $esc($explain . ' ' . (string)($learning['summary'] ?? '')) . '</p></div></details>';
        $html .= '</section>';
        return $html;
    }
}

if (!function_exists('mle_render_post_draw_result')) {
    function mle_render_post_draw_result($run, $official_result, $evidence) {
        $run = is_array($run) ? $run : array();
        $official = is_array($official_result) ? $official_result : array();
        $evidence = is_array($evidence) ? $evidence : array();
        if (empty($official['main']) && empty($official['extra'])) { return ''; }
        $esc = function($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); };
        $toList = function($numbers) {
            $parts = array();
            foreach ((array)$numbers as $number) { $parts[] = (string)(int)$number; }
            return !empty($parts) ? implode(', ', $parts) : 'Not Available';
        };
        $prediction = array();
        if (!empty($run['predicted'])) { $prediction = (array)$run['predicted']; }
        elseif (!empty($run['main_numbers']) && function_exists('mylottoexpertParseNumberCsv')) { $prediction = mylottoexpertParseNumberCsv((string)$run['main_numbers']); }
        $matches = array();
        if (!empty($run['matches'])) { $matches = (array)$run['matches']; }
        $matchCount = (int)($run['total_hits'] ?? (($run['main_hits'] ?? 0) + ($run['extra_hits'] ?? 0)));
        $interpretation = 'No match recorded for this scored draw.';
        if ($matchCount >= 3) { $interpretation = 'This was a stronger post-draw result relative to the saved prediction history for this lottery.'; }
        elseif ($matchCount >= 1) { $interpretation = 'This scored draw produced a partial match. Keep it in the prediction history record without rewriting the original pre-draw role.'; }
        $html = '<div class="mle-evidence-strip" aria-label="Post draw result interpretation">';
        foreach (array(
            array('Official Winning Numbers', $toList($official['main']) . (!empty($official['extra']) ? (' | Extra: ' . $toList($official['extra'])) : ''), 'mle-evidence-strip--status'),
            array('Before-Draw Saved Prediction', $toList($prediction), ''),
            array('Matched Numbers', $toList($matches), ''),
            array('Match Count', (string)$matchCount, ''),
            array('Prediction Role Before Draw', $evidence['recommendation_role'] ?? 'Watch Only', ''),
            array('Confidence Before Draw', $evidence['prediction_confidence'] ?? 'No Confidence Yet', 'mle-evidence-strip--confidence'),
            array('Official Scoring Status', $evidence['official_scoring_status'] ?? 'Scored', 'mle-evidence-strip--status'),
        ) as $item) {
            $html .= '<div class="mle-evidence-strip__item' . ($item[2] !== '' ? ' ' . $item[2] : '') . '"><span class="mle-evidence-strip__label">' . $esc($item[0]) . '</span><span class="mle-evidence-strip__value">' . $esc($item[1]) . '</span></div>';
        }
