        /* [[MLE_V73_LEGACY_STYLE_ANALYSIS_METHOD_STATUS]] Compact legacy-style method cards below Prediction Confidence and above Current Step. Uses existing method_run_breakdown only; no new queries, no scoring/math changes. */
        $__mleV73MethodRegistry = array(
            'skai' => array('label' => 'AI', 'track' => 'AI Track'),
            'core_ai' => array('label' => 'Core AI', 'track' => 'Core AI Track'),
            'mcmc' => array('label' => 'MCMC Learning Engine', 'track' => 'MCMC Track'),
            'skip_hit' => array('label' => 'Skip/Hit', 'track' => 'Skip/Hit Track'),
            'frequency' => array('label' => 'Frequency/Heatmap', 'track' => 'Frequency Baseline')
        );
        $__mleV73RowsByMethod = array();
        if (!empty($__advMethodRunItemsVisible) && is_array($__advMethodRunItemsVisible)) {
            foreach ($__advMethodRunItemsVisible as $__mleV73MethodRow) {
                if (!is_array($__mleV73MethodRow)) { continue; }
                $__mleV73MethodKey = strtolower(trim((string)($__mleV73MethodRow['method'] ?? 'unknown')));
                $__mleV73MethodKey = function_exists('mleAdvisoryNormalizeMethodBreakdownKey') ? mleAdvisoryNormalizeMethodBreakdownKey($__mleV73MethodKey) : preg_replace('/[^a-z0-9_\-]/', '', $__mleV73MethodKey);
                if ($__mleV73MethodKey === '') { $__mleV73MethodKey = 'unknown'; }
                if ($__mleV73MethodKey === 'frequency_map' || $__mleV73MethodKey === 'heat_map' || $__mleV73MethodKey === 'heatmap' || $__mleV73MethodKey === 'manual_heatmap' || $__mleV73MethodKey === 'frequency_heatmap') { $__mleV73MethodKey = 'frequency'; }
                if (!isset($__mleV73RowsByMethod[$__mleV73MethodKey])) {
                    $__mleV73RowsByMethod[$__mleV73MethodKey] = $__mleV73MethodRow;
                }
            }
            unset($__mleV73MethodRow, $__mleV73MethodKey);
        }
        /* [[MLE_V76_METHOD_STATUS_PENDING_LIST_RECONCILE]]
         * The top pending-prediction panel is built from $__advPendingRecAll. The
         * legacy method-status cards are built from method_run_breakdown. When the
         * first-load evidence cap is active, method_run_breakdown can be empty while
         * the pending list is correctly populated. Reconcile the status cards from
         * the already-rendered pending rows so the method cards do not say SKAI has
         * not run when pending SKAI rows are visible above. This does not create,
         * score, delete, or reclassify database rows; it only aligns display counts.
         */
        $__mleV76PendingDisplayCounts = array();
        $__mleV76PendingDisplaySavedIds = array();
        $__mleV76PendingDisplayRows = array();
        if (!empty($__advPendingRecAll) && is_array($__advPendingRecAll)) {
            foreach ($__advPendingRecAll as $__mleV76PendingRow) {
                if (!is_array($__mleV76PendingRow)) { continue; }
