          if ($__mlePendingRequestedLimit > 200) { $__mlePendingRequestedLimit = 200; }

          $__mlePendingMethodKeyForDisplay = function($row) {
              if (!is_array($row)) { return 'unknown'; }
              if (function_exists('mleAdvisoryResolveSavedEvidenceMethodKey')) {
                  $mk = mleAdvisoryResolveSavedEvidenceMethodKey($row);
              } elseif (function_exists('mleAdvisoryNormalizeMethodBreakdownKey')) {
                  $mk = mleAdvisoryNormalizeMethodBreakdownKey($row['method'] ?? $row['analysis_method_key'] ?? $row['origin_source'] ?? $row['source'] ?? 'unknown');
              } else {
                  $mk = strtolower(trim((string)($row['method'] ?? $row['analysis_method_key'] ?? $row['origin_source'] ?? $row['source'] ?? 'unknown')));
              }
              $mk = strtolower(trim((string)$mk));
              return $mk !== '' ? $mk : 'unknown';
          };
          $__mlePendingMethodLabelForDisplay = function($methodKey) {
              $methodKey = strtolower(trim((string)$methodKey));
              return function_exists('mleAdvisoryMethodLabel') ? mleAdvisoryMethodLabel($methodKey) : ucwords(str_replace('_', ' ', $methodKey));
          };
          $__mlePendingIdentityForDisplay = function($row) {
              if (!is_array($row)) { return ''; }
              foreach (array('saved_id','id','source_record_id') as $k) {
                  $v = (int)($row[$k] ?? 0);
                  if ($v > 0) { return 'id:' . $v; }
              }
              foreach (array('run_uuid','snapshot_run_uuid','run_identity_key') as $k) {
                  $v = trim((string)($row[$k] ?? ''));
                  if ($v !== '') { return $k . ':' . $v; }
              }
              return md5(json_encode(array($row['draw_date'] ?? '', $row['method'] ?? '', $row['label'] ?? '', $row['predicted'] ?? array())));
          };
          $__mlePendingTopIdentityMap = array();
          foreach ((array)$__advPendingRecTop as $__mleTopPendingRow) {
              $__mleTopIdentity = $__mlePendingIdentityForDisplay(is_array($__mleTopPendingRow) ? $__mleTopPendingRow : array());
              if ($__mleTopIdentity !== '') { $__mlePendingTopIdentityMap[$__mleTopIdentity] = true; }
          }
          unset($__mleTopPendingRow, $__mleTopIdentity);
          $__mlePendingRecAllForDisplay = is_array($__advPendingRecAll) ? array_values($__advPendingRecAll) : array();
          $__mlePendingGlobalRankMap = array();
          foreach ($__mlePendingRecAllForDisplay as $__mleRankIndex => $__mleRankRow) {
