              if ($__mleRankIdentity !== '' && !isset($__mlePendingGlobalRankMap[$__mleRankIdentity])) { $__mlePendingGlobalRankMap[$__mleRankIdentity] = (int)$__mleRankIndex + 1; }
          }
          unset($__mleRankIndex, $__mleRankRow, $__mleRankIdentity);
          $__mlePendingMethodOrder = array('skai'=>10, 'skip_hit'=>20, 'frequency'=>30, 'mcmc'=>40, 'core_ai'=>50, 'strategy_set'=>80, 'unknown'=>99);
          /* [[MLE_V79_PENDING_METHOD_GROUP_CONFIDENCE_ORDER]] Keep the original pre-draw confidence order inside each analysis-method group. */
          usort($__mlePendingRecAllForDisplay, function($a, $b) use ($__mlePendingMethodKeyForDisplay, $__mlePendingMethodOrder, $__mlePendingIdentityForDisplay, $__mlePendingGlobalRankMap) {
              $am = $__mlePendingMethodKeyForDisplay(is_array($a) ? $a : array());
              $bm = $__mlePendingMethodKeyForDisplay(is_array($b) ? $b : array());
              $ao = (int)($__mlePendingMethodOrder[$am] ?? 70);
              $bo = (int)($__mlePendingMethodOrder[$bm] ?? 70);
              if ($ao !== $bo) { return $ao - $bo; }

              $aid = $__mlePendingIdentityForDisplay(is_array($a) ? $a : array());
              $bid = $__mlePendingIdentityForDisplay(is_array($b) ? $b : array());
              $arank = ($aid !== '' && isset($__mlePendingGlobalRankMap[$aid])) ? (int)$__mlePendingGlobalRankMap[$aid] : 999999;
              $brank = ($bid !== '' && isset($__mlePendingGlobalRankMap[$bid])) ? (int)$__mlePendingGlobalRankMap[$bid] : 999999;
              if ($arank !== $brank) { return $arank - $brank; }

              $as = (int)($a['pending_recommendation_score'] ?? $a['pending_evidence_score'] ?? 0);
              $bs = (int)($b['pending_recommendation_score'] ?? $b['pending_evidence_score'] ?? 0);
              if ($as !== $bs) { return $bs - $as; }
              $aro = (int)($a['source_batch_run_order'] ?? $a['batch_index'] ?? 0);
              $bro = (int)($b['source_batch_run_order'] ?? $b['batch_index'] ?? 0);
              if ($aro !== $bro) { return $aro - $bro; }
              return strcmp((string)($a['label'] ?? ''), (string)($b['label'] ?? ''));
          });
          $__mlePendingTotalForDisplay = count($__mlePendingRecAllForDisplay);
          $__mlePendingVisibleLimit = min($__mlePendingRequestedLimit, max(0, $__mlePendingTotalForDisplay));
          $__mlePendingRecVisible = array_slice($__mlePendingRecAllForDisplay, 0, $__mlePendingVisibleLimit);
          $__mlePendingHasMore = $__mlePendingTotalForDisplay > $__mlePendingVisibleLimit;
          $__mlePendingNextLimit = min(200, $__mlePendingVisibleLimit + 50, $__mlePendingTotalForDisplay);
          $__mlePendingBasePath = strtok((string)($_SERVER['REQUEST_URI'] ?? ''), '?');
          if ($__mlePendingBasePath === '') { $__mlePendingBasePath = (string)($_SERVER['PHP_SELF'] ?? ''); }
          $__mlePendingMoreQuery = $_GET;
