          $__mlePendingLessHref = htmlspecialchars($__mlePendingBasePath . '?' . http_build_query($__mlePendingLessQuery) . '#' . $__advPendingDropdownId, ENT_QUOTES, 'UTF-8');
        ?>
        <div class="mle-pending-predictions-dropdown__toolbar">
