          <p>These are grouped by analysis method so AI, Skip/Hit, Heatmap, MCMC, and Core AI pending predictions are all visible before the draw. Delete any prediction you do not want kept before it is scored.</p>
          <button type="button" class="mle-advisory-btn mle-advisory-btn--secondary mle-print-pending-btn" data-mle-print-pending="1" data-print-title="<?php echo htmlspecialchars($__advLname . ' pending predictions', ENT_QUOTES, 'UTF-8'); ?>">Print Visible Pending Predictions</button>
        </div>
        <?php
          /* [[MLE_V77_PENDING_METHOD_COUNTS]] Give users a quick method-level proof that all pending methods are included. */
          $__mlePendingMethodCounts = array();
          foreach ((array)$__advPendingRecAll as $__pmcRun) {
              if (!is_array($__pmcRun)) { continue; }
              $__pmcMethod = '';
              $__pmcMethod = $__mlePendingMethodKeyForDisplay($__pmcRun);
              if ($__pmcMethod === '') { $__pmcMethod = 'unknown'; }
              if (!isset($__mlePendingMethodCounts[$__pmcMethod])) {
                  $__mlePendingMethodCounts[$__pmcMethod] = array('label' => function_exists('mleAdvisoryMethodLabel') ? mleAdvisoryMethodLabel($__pmcMethod) : strtoupper($__pmcMethod), 'count' => 0);
              }
              $__mlePendingMethodCounts[$__pmcMethod]['count']++;
          }
          unset($__pmcRun, $__pmcMethod);
