            <?php foreach ($__mlePendingMethodCounts as $__pmc): ?>
              <span class="mle-pending-method-counts__chip"><strong><?php echo htmlspecialchars((string)($__pmc['label'] ?? 'Analysis'), ENT_QUOTES, 'UTF-8'); ?></strong> <?php echo (int)($__pmc['count'] ?? 0); ?> pending</span>
