              if (function_exists('mleAdvisoryNormalizeDailyHistoryRowForDisplay')) { $__pendingRun = mleAdvisoryNormalizeDailyHistoryRowForDisplay(is_array($__pendingRun) ? $__pendingRun : array()); }
