    <div class="mle-mode-block mle-saved-runs-always-visible" data-mle-card-mode-section="overview">
    <div id="<?php echo $__advRunsBodyId; ?>" class="mle-section-body mle-saved-runs-panel mle-saved-runs-panel--always-visible" data-mle-primary-section-body="1" style="display:block" aria-hidden="false">
      <?php

        $__spUpcomingRuns  = (array)($__advVisual['upcoming'] ?? array());
        $__spCompletedRuns = array_merge(
          (array)($__advVisual['recent'] ?? array()),
          (array)($__advVisual['older']  ?? array())
        );

        $__spPanelTargetId = 'mle-sp-panel-' . (int)$__advLid;
        $__spPastSort = strtolower(trim((string)$app->input->getCmd('mle_past_sort', 'newest')));
        if (!in_array($__spPastSort, array('newest','best','method','draw'), true)) { $__spPastSort = 'newest'; }
        $__spPastSortLabels = array(
          'newest' => 'Newest saved first',
          'best'   => 'Best hits first',
          'method' => 'Method / source',
          'draw'   => 'Draw date groups'
        );
        $__spPastSortHref = function($__sortKey) use ($__advLid, $__spPanelTargetId) {
          $__uri = clone \Joomla\CMS\Uri\Uri::getInstance();
          $__uri->setVar('mle_saved_runs_more', (string)(int)$__advLid);
          $__uri->setVar('mle_saved_runs_page', '1');
          $__uri->setVar('mle_past_sort', (string)$__sortKey);
          $__uri->delVar('mle_ajax');
          return htmlspecialchars($__uri->toString() . '#' . $__spPanelTargetId, ENT_QUOTES, 'UTF-8');
        };
        $__spPastGetTimestamp = function(array $__run) {
          foreach (array('draw_date','target_draw_date','next_draw_date','evaluated_at','date_saved','generated_at','created_at') as $__k) {
            $__v = trim((string)($__run[$__k] ?? ''));
            if ($__v !== '') { $__ts = strtotime($__v); if ($__ts !== false) { return (int)$__ts; } }
          }
          return 0;
        };
        $__spPastGetMethod = function(array $__run) {
          foreach (array('method_label','analysis_method_key','source_batch_type','source_batch_origin','origin_source','source','label') as $__k) {
            $__v = trim((string)($__run[$__k] ?? ''));
            if ($__v !== '') { return strtolower($__v); }
          }
          return 'saved prediction';
        };
        $__spPastGetHits = function(array $__run) {
          return array(
            (int)($__run['total_hits'] ?? $__run['hits'] ?? 0),
            (int)($__run['main_hits'] ?? 0),
            (int)($__run['top20_hits'] ?? 0),
            (int)($__run['top10_hits'] ?? 0)
          );
        };
        if (!empty($__spCompletedRuns)) {
          usort($__spCompletedRuns, function($__a, $__b) use ($__spPastSort, $__spPastGetTimestamp, $__spPastGetMethod, $__spPastGetHits) {
            $__a = is_array($__a) ? $__a : array();
            $__b = is_array($__b) ? $__b : array();
            if ($__spPastSort === 'best') {
              $__ah = $__spPastGetHits($__a); $__bh = $__spPastGetHits($__b);
              for ($__i = 0; $__i < 4; $__i++) { if ($__ah[$__i] !== $__bh[$__i]) { return ($__bh[$__i] <=> $__ah[$__i]); } }
              return ($__spPastGetTimestamp($__b) <=> $__spPastGetTimestamp($__a));
            }
            if ($__spPastSort === 'method') {
              $__cmp = strcmp($__spPastGetMethod($__a), $__spPastGetMethod($__b));
              if ($__cmp !== 0) { return $__cmp; }
              return ($__spPastGetTimestamp($__b) <=> $__spPastGetTimestamp($__a));
            }
            if ($__spPastSort === 'draw') {
              $__ad = trim((string)($__a['draw_date'] ?? $__a['target_draw_date'] ?? $__a['next_draw_date'] ?? ''));
              $__bd = trim((string)($__b['draw_date'] ?? $__b['target_draw_date'] ?? $__b['next_draw_date'] ?? ''));
              $__cmp = strcmp($__bd, $__ad);
              if ($__cmp !== 0) { return $__cmp; }
              $__ai = (int)($__a['batch_index'] ?? $__a['source_batch_run_order'] ?? 0);
              $__bi = (int)($__b['batch_index'] ?? $__b['source_batch_run_order'] ?? 0);
              if ($__ai !== $__bi) { return $__ai <=> $__bi; }
              return ($__spPastGetTimestamp($__b) <=> $__spPastGetTimestamp($__a));
            }
            return ($__spPastGetTimestamp($__b) <=> $__spPastGetTimestamp($__a));
          });
        }

        $__spCompletedLimit = 20;
        $__spCompletedFirst = array_slice($__spCompletedRuns, 0, $__spCompletedLimit);
        $__spCompletedMore  = array_slice($__spCompletedRuns, $__spCompletedLimit);
        $__spTotalRuns = count($__spUpcomingRuns) + count($__spCompletedRuns);

        $__spMoreRequestedLotteryId = (int)$app->input->getInt('mle_saved_runs_more', 0);
        $__spMorePageSize = 20;
        $__spMoreRequestedPage = (int)$app->input->getInt('mle_saved_runs_page', 1);
        if ($__spMoreRequestedPage < 1) { $__spMoreRequestedPage = 1; }
        $__spMoreRequested = ($__spMoreRequestedLotteryId === (int)$__advLid);

        $__spOlderRunTotal = count($__spCompletedMore);
        $__spMoreTotalPages = $__spOlderRunTotal > 0 ? (int)ceil($__spOlderRunTotal / $__spMorePageSize) : 0;
        if ($__spMoreTotalPages > 0 && $__spMoreRequestedPage > $__spMoreTotalPages) { $__spMoreRequestedPage = $__spMoreTotalPages; }
        $__spMorePageStart = max(0, ($__spMoreRequestedPage - 1) * $__spMorePageSize);
        $__spCompletedMorePageRows = array_slice($__spCompletedMore, $__spMorePageStart, $__spMorePageSize);
        $__spMoreLoadedRunCount = count($__spCompletedMorePageRows);
        $__spMoreHasNext = ($__spMoreTotalPages > 0 && $__spMoreRequestedPage < $__spMoreTotalPages);
        $__spMoreNextPage = $__spMoreRequestedPage + 1;
        $__spMoreContainerId = 'mle-sp-more-container-' . (int)$__advLid . '-' . (int)$__spMoreRequestedPage;
        $__spMoreNextContainerId = 'mle-sp-more-container-' . (int)$__advLid . '-' . (int)$__spMoreNextPage;
        $__spMoreUri = clone \Joomla\CMS\Uri\Uri::getInstance();
        $__spMoreUri->setVar('mle_saved_runs_more', (string)(int)$__advLid);
        $__spMoreUri->setVar('mle_saved_runs_page', (string)(int)$__spMoreRequestedPage);
        $__spMoreUri->setVar('mle_past_sort', (string)$__spPastSort);
        $__spMoreHref = htmlspecialchars($__spMoreUri->toString() . '#' . $__spPanelTargetId, ENT_QUOTES, 'UTF-8');
        $__spMoreNextUri = clone \Joomla\CMS\Uri\Uri::getInstance();
        $__spMoreNextUri->setVar('mle_saved_runs_more', (string)(int)$__advLid);
        $__spMoreNextUri->setVar('mle_saved_runs_page', (string)(int)$__spMoreNextPage);
        $__spMoreNextUri->setVar('mle_past_sort', (string)$__spPastSort);
        $__spMoreNextHref = htmlspecialchars($__spMoreNextUri->toString() . '#' . $__spPanelTargetId, ENT_QUOTES, 'UTF-8');
        $__spResetUri = clone \Joomla\CMS\Uri\Uri::getInstance();
        $__spResetUri->delVar('mle_saved_runs_more');
        $__spResetUri->delVar('mle_saved_runs_page');
        $__spResetUri->setVar('mle_past_sort', (string)$__spPastSort);
        $__spResetHref = htmlspecialchars($__spResetUri->toString() . '#' . $__spPanelTargetId, ENT_QUOTES, 'UTF-8');

        $__spRunStableKey = function(array $__run) {
          foreach (array('saved_id','id','source_record_id') as $__k) {
            if (!empty($__run[$__k])) { return 'id:' . (int)$__run[$__k]; }
          }
          $uuid = trim((string)($__run['run_uuid'] ?? $__run['snapshot_run_uuid'] ?? ''));
          if ($uuid !== '') { return 'uuid:' . preg_replace('/[^a-zA-Z0-9_.-]/', '', $uuid); }
          $bits = array(
            (string)($__run['draw_date'] ?? ''),
            (string)($__run['label'] ?? ''),
            (string)($__run['batch_uuid'] ?? ''),
            (string)($__run['batch_index'] ?? ''),
            implode(',', array_map('strval', (array)($__run['predicted'] ?? array())))
          );
          return 'hash:' . substr(hash('sha256', implode('|', $bits)), 0, 16);
        };

        $__spRunTypeLabel = function(array $__run) {
          $hay = strtolower(trim(implode(' ', array(
            (string)($__run['label'] ?? ''),
            (string)($__run['batch_type'] ?? ''),
            (string)($__run['source_batch_type'] ?? ''),
            (string)($__run['source_batch_origin'] ?? ''),
            (string)($__run['origin_source'] ?? ''),
            (string)($__run['source'] ?? ''),
            (string)($__run['analysis_method_key'] ?? ''),
            (string)($__run['method_label'] ?? '')
          ))));
          $batchTotal = (int)($__run['batch_total'] ?? 0);
          $batchIndex = (int)($__run['batch_index'] ?? $__run['source_batch_run_order'] ?? 0);
          if (strpos($hay, 'controlled') !== false || strpos($hay, 'narrow') !== false || strpos($hay, 'precision') !== false || strpos($hay, 'settings') !== false || strpos($hay, 'focus') !== false || strpos($hay, 'shared AI learning alternate') !== false || strpos($hay, 'champion') !== false) {
            return 'Optional Controlled Narrowing Test' . ($batchIndex > 0 ? ' #' . $batchIndex : '');
          }
          if (strpos($hay, 'quick') !== false || strpos($hay, 'single') !== false || ($batchTotal > 0 && $batchTotal <= 1)) {
            return '1 Quick Prediction';
          }
          if ($batchTotal >= 9 || trim((string)($__run['batch_uuid'] ?? '')) !== '' || (int)($__run['source_batch_id'] ?? 0) > 0) {
            return 'Regular 9 Predictions' . ($batchIndex > 0 ? ' #' . $batchIndex : '');
          }
          return 'Saved Prediction';
        };

        $__spBlendLabel = function(array $__run) {
          $settings = array();
          try { if (function_exists('mylottoexpertResolveEffectiveSettings')) { $settings = mylottoexpertResolveEffectiveSettings($__run); } } catch (\Throwable $__e) { $settings = array(); }
          try {
            if (function_exists('mylottoexpertBuildBlendDisplayInfo')) {
              $info = mylottoexpertBuildBlendDisplayInfo($__run, is_array($settings) ? $settings : array());
              $primary = trim((string)($info['primary'] ?? ''));
              $strategy = trim((string)($info['strategy_label'] ?? ''));
              if ($primary !== '' && $strategy !== '' && $primary !== $strategy) { return $strategy . ' ' . $primary; }
              if ($primary !== '') { return $primary; }
              if ($strategy !== '') { return $strategy; }
            }
          } catch (\Throwable $__e) {}
          foreach (array('signal_blend_label','blend','strategy_profile','strategy') as $__k) {
            $v = trim((string)($__run[$__k] ?? ($settings[$__k] ?? '')));
            if ($v !== '') { return str_replace('_', ' ', $v); }
          }
          foreach (array('blend_ai_pct','skai_blend_ai_pct','signal_blend_ai_pct','ai_pct') as $__k) {
            $v = $__run[$__k] ?? ($settings[$__k] ?? null);
            if ($v !== null && $v !== '' && is_numeric($v)) { return 'AI blend ' . rtrim(rtrim(number_format((float)$v, 1, '.', ''), '0'), '.') . '%'; }
          }
          return 'Blend not recorded';
        };

        $__spSettingsSummary = function(array $__run) {
          $settings = array();
          try { if (function_exists('mylottoexpertResolveEffectiveSettings')) { $settings = mylottoexpertResolveEffectiveSettings($__run); } } catch (\Throwable $__e) { $settings = array(); }
          if (!is_array($settings)) { $settings = array(); }
          $wanted = array('profile','training_style','strategy','blend','blend_ai_pct','blend_skip_pct','skai_blend_ai_pct','skai_blend_skip_pct','signal_blend_ai_pct','signal_blend_skip_pct','skai_window_size','skip_window','draws_used','tuned_window','best_window','sampling_temperature','diversity_penalty','gap_scale','epochs','batch_size');
          $pairs = array();
          foreach ($wanted as $__k) {
            $v = $settings[$__k] ?? ($__run[$__k] ?? null);
            if ($v === null || $v === '' || is_array($v) || is_object($v)) { continue; }
            $pairs[$__k] = (string)$v;
          }
          return array($pairs, $settings);
        };

        $__spRenderRunCard = function(array $__spRun) use ($__advLid, $__spRunTypeLabel, $__spBlendLabel, $__spSettingsSummary) {
          $__spLabel    = htmlspecialchars((string)($__spRun['label']        ?? 'Saved run'), ENT_QUOTES, 'UTF-8');
          $__spMethod   = htmlspecialchars((string)($__spRun['method_label'] ?? ''), ENT_QUOTES, 'UTF-8');
          $__spDate     = htmlspecialchars((string)($__spRun['draw_date']    ?? ($__spRun['target_draw_date'] ?? '')), ENT_QUOTES, 'UTF-8');
          $__spSavedId  = (int)($__spRun['saved_id'] ?? $__spRun['id'] ?? 0);
          $__spRunType  = htmlspecialchars($__spRunTypeLabel($__spRun), ENT_QUOTES, 'UTF-8');
          $__spBlend    = htmlspecialchars($__spBlendLabel($__spRun), ENT_QUOTES, 'UTF-8');
          list($__spSettingPairs, $__spSettingsFull) = $__spSettingsSummary($__spRun);
          $__spTicketBits = array();
          if (!empty($__spRun['prediction_target_key'])) { $__spTicketBits[] = 'Target ' . (string)$__spRun['prediction_target_key']; }
          if (!empty($__spRun['run_uuid'])) { $__spTicketBits[] = 'Run ' . substr(preg_replace('/[^a-zA-Z0-9]/', '', (string)$__spRun['run_uuid']), 0, 10); }
          if (!empty($__spRun['batch_uuid'])) { $__spTicketBits[] = 'Batch ' . substr(preg_replace('/[^a-zA-Z0-9]/', '', (string)$__spRun['batch_uuid']), 0, 10); }
          if (!empty($__spRun['batch_index']) || !empty($__spRun['source_batch_run_order'])) { $__spTicketBits[] = 'Item #' . (int)($__spRun['batch_index'] ?? $__spRun['source_batch_run_order']); }
