<?php
$__mleBeginnerStatusLabel = function ($toneBadge) {
    $toneBadge = strtolower(trim((string)$toneBadge));
    if ($toneBadge === 'high-conviction recommendation') {
        return 'Strong prediction history';
    }
    if ($toneBadge === 'actionable recommendation') {
        return 'Ready to use';
    }
    if ($toneBadge === 'early recommendation') {
        return 'Still building';
    }
    return 'Too early to trust';
};

$__mleBeginnerStatusExplain = function ($toneBadge) {
    $toneBadge = strtolower(trim((string)$toneBadge));
    if ($toneBadge === 'high-conviction recommendation') {
        return 'The page has enough aligned proof to treat this as its strongest direction right now.';
    }
    if ($toneBadge === 'actionable recommendation') {
        return 'There is enough repeated support to start narrowing choices, but it is not yet the strongest possible call.';
    }
    if ($toneBadge === 'early recommendation') {
        return 'Patterns are starting to repeat, but the sample is still small enough that you should stay cautious.';
    }
    return 'There is not enough trustworthy history yet. Keep building runs before leaning on this lottery.';
};

