$__mleExcludeAdminResearchWorkspace = function_exists('mylottoexpertAdminResearchWorkspaceExcluded') ? mylottoexpertAdminResearchWorkspaceExcluded($app) : false;
if ($__mleExcludeAdminResearchWorkspace) {
