    if (in_array('hive_queue_id', $__snCols, true)) { $__mleResearchSqlMarkers[] = 'COALESCE(sn.' . $db->quoteName('hive_queue_id') . ',0) > 0'; }
    foreach (array('hive_research_type','hive_setting_key','hive_settings_fingerprint') as $__mleResearchCol) {
