    }
    if (in_array('skai_run_mode', $__snCols, true)) { $__mleResearchSqlMarkers[] = 'LOWER(COALESCE(sn.' . $db->quoteName('skai_run_mode') . ', ' . $db->quote('') . ')) IN (' . $db->quote('global_hive_research_batch') . ',' . $db->quote('admin_client_research') . ')'; }
    if (in_array('focus_profile', $__snCols, true)) { $__mleResearchSqlMarkers[] = 'LOWER(COALESCE(sn.' . $db->quoteName('focus_profile') . ', ' . $db->quote('') . ')) = ' . $db->quote('global_research'); }
    if (in_array('settings_json', $__snCols, true)) {
        $__mleResearchSqlMarkers[] = '(LOWER(COALESCE(sn.' . $db->quoteName('settings_json') . ', ' . $db->quote('') . ')) LIKE ' . $db->quote('%admin_client_research%') . ' OR LOWER(COALESCE(sn.' . $db->quoteName('settings_json') . ', ' . $db->quote('') . ')) LIKE ' . $db->quote('%_mle_research_type%') . ' OR LOWER(COALESCE(sn.' . $db->quoteName('settings_json') . ', ' . $db->quote('') . ')) LIKE ' . $db->quote('%_mle_global_learning_objective%') . ')';
    }
    if (!empty($__mleResearchSqlMarkers)) { $q->where('NOT (' . implode(' OR ', $__mleResearchSqlMarkers) . ')'); }
