$q->order('sn.next_draw_date ' . $predSortDir . ', sn.source ASC, COALESCE(sn.generated_at,sn.date_saved) ' . $predSortDir);

$q = mylottoexpertApplyQueryLimit($q, (int)($__mlePerformanceProfile['saved_prediction_limit'] ?? 600));

$db->setQuery($q);
$__savedSetsRaw = $db->loadObjectList() ?: array();
$__mleSavedRowsLimited = ((int)($__mlePerformanceProfile['saved_prediction_limit'] ?? 0) > 0 && count((array)$__savedSetsRaw) >= (int)$__mlePerformanceProfile['saved_prediction_limit']);
$savedSets = array();
foreach ($__savedSetsRaw as $__mleSavedSetRow) {
    $__row = (array)$__mleSavedSetRow;
    $__saveIntentNorm = strtolower(trim((string)($__row['save_intent'] ?? '')));
    if (in_array($__saveIntentNorm, array('play_set','custom_play','wheel_candidate'), true)) { continue; }
    $__isInactive = false;
    foreach (array('play_status','status') as $__statusField) {
        $__statusNorm = strtolower(trim((string)($__row[$__statusField] ?? '')));
        if (in_array($__statusNorm, array('deleted','discarded','inactive','retired'), true)) {
            $__isInactive = true;
            break;
        }
    }
    if ($__isInactive) { continue; }

    $__identity = mleResolveSavedRowGameIdentity($db, $__row);
    $__resolvedLotteryId = (int)($__identity['effective_lottery_id'] ?? 0);
    $__resolvedGameId = trim((string)($__identity['effective_game_id'] ?? ''));
    if ($__resolvedLotteryId <= 0 && $__resolvedGameId === '') { continue; }

    $__mleSavedSetRow->lottery_id = $__resolvedLotteryId;
    $__mleSavedSetRow->game_id = $__resolvedGameId;
    $__mleSavedSetRow->mle_lottery_game_id = $__resolvedGameId;
    $__mleSavedSetRow->target_lottery_id = (int)($__row['target_lottery_id'] ?? $__resolvedLotteryId);
    $__mleSavedSetRow->target_game_id = trim((string)($__row['target_game_id'] ?? $__resolvedGameId));

    $__mleSavedSetRow = mylottoexpertScrubSavedPredictionRowToGameRange($__mleSavedSetRow, $__resolvedGameId);

    $__lotteryName = trim((string)($__identity['display_lottery_name'] ?? ''));
    $__stateName = trim((string)($__identity['display_state_name'] ?? ''));
    $__countryName = trim((string)($__identity['display_country_name'] ?? ''));
    if ($__lotteryName !== '' && function_exists('mylottoexpertFormatLotteryLocationLine')) {
        $__displayName = trim((string)mylottoexpertFormatLotteryLocationLine($__stateName, $__countryName, $__lotteryName, $__resolvedGameId, ' - '));
        $__mleSavedSetRow->lottery_name = ($__displayName !== '') ? $__displayName : $__lotteryName;
    } else {
        $__mleSavedSetRow->lottery_name = $__lotteryName;
    }
    $__mleSavedSetRow->mle_state_name = $__stateName;
    $__mleSavedSetRow->mle_country_name = $__countryName;
    $__mleSavedSetRow->__mle_visibility_group_key = ($__resolvedGameId !== '' ? ('game:' . strtolower($__resolvedGameId)) : ('lottery:' . $__resolvedLotteryId));

    if (!empty($__mleExcludeAdminResearchWorkspace) && function_exists('mylottoexpertIsAdminResearchSavedRow') && mylottoexpertIsAdminResearchSavedRow((array)$__mleSavedSetRow)) {
        if (!isset($GLOBALS['mle_admin_research_workspace_hidden_summary'])) {
            $GLOBALS['mle_admin_research_workspace_hidden_summary'] = array('rows'=>0,'lotteries'=>array());
        }
        $GLOBALS['mle_admin_research_workspace_hidden_summary']['rows']++;
        $GLOBALS['mle_admin_research_workspace_hidden_summary']['lotteries'][$__resolvedLotteryId] = $__mleSavedSetRow->lottery_name;
        continue;
    }

    $savedSets[] = $__mleSavedSetRow;
}
unset($__savedSetsRaw, $__mleSavedSetRow, $__row, $__identity, $__resolvedLotteryId, $__resolvedGameId, $__lotteryName, $__stateName, $__countryName, $__displayName, $__saveIntentNorm, $__statusField, $__statusNorm, $__isInactive);

if (function_exists('mylottoexpertApplyWorkspaceLotteryVisibility') && !empty($savedSets)) {
    $__mleSavedBucketsForVisibility = array();
    foreach ($savedSets as $__mleSavedSetForVisibility) {
        $__lidVis = (int)($__mleSavedSetForVisibility->lottery_id ?? 0);
        if ($__lidVis <= 0) { continue; }
        if (!isset($__mleSavedBucketsForVisibility[$__lidVis])) {
            $__mleSavedBucketsForVisibility[$__lidVis] = array(
                'lottery_id' => $__lidVis,
                'lottery_name' => (string)($__mleSavedSetForVisibility->lottery_name ?? ''),
                'rows' => array()
            );
        }
        $__mleSavedBucketsForVisibility[$__lidVis]['rows'][] = (array)$__mleSavedSetForVisibility;
    }
    $__mleVisibleBucketsForSavedSets = mylottoexpertApplyWorkspaceLotteryVisibility($db, $workspaceUserId, $__mleSavedBucketsForVisibility);
    $__mleVisibleSavedSetLotteryIds = array();
    foreach ($__mleVisibleBucketsForSavedSets as $__lidVis => $__unusedBucket) { $__mleVisibleSavedSetLotteryIds[(int)$__lidVis] = true; }
    $__mleFilteredSavedSets = array();
    foreach ($savedSets as $__mleSavedSetForVisibility) {
        $__lidVis = (int)($__mleSavedSetForVisibility->lottery_id ?? 0);
        if ($__lidVis > 0 && !empty($__mleVisibleSavedSetLotteryIds[$__lidVis])) { $__mleFilteredSavedSets[] = $__mleSavedSetForVisibility; }
    }
    $savedSets = $__mleFilteredSavedSets;
    unset($__mleSavedBucketsForVisibility, $__mleVisibleBucketsForSavedSets, $__mleVisibleSavedSetLotteryIds, $__mleFilteredSavedSets, $__mleSavedSetForVisibility, $__lidVis, $__unusedBucket);
}

$playSets = array();
$__mlePlayRowsLimited = false;
try {
    $qPlay = $db->getQuery(true)
        ->select(array(
            'sn.id','sn.lottery_id','sn.game_id','sn.target_game_id','sn.next_draw_date','sn.source','sn.label','sn.main_numbers',
            'sn.extra_ball_numbers','sn.date_saved','sn.generated_at','sn.analysis_method_key','sn.analysis_engine_label','sn.analysis_track_label',
            'l.name AS lottery_name'
        ))
        ->from($db->quoteName('#__user_saved_numbers', 'sn'))
        ->join('LEFT', $db->quoteName('#__lotteries', 'l') . ' ON sn.lottery_id = l.lottery_id')
        ->where('sn.user_id = ' . $workspaceUserId);

    if (in_array('save_intent', $__snCols, true)) {
        $__playOptionalCols = array(
            'save_intent','origin_source','play_status','user_editable','play_notes',
            'wheel_exported_at','wheel_export_count','is_favorite_play',
            'target_game_id','target_prediction_type','target_pick_size','target_extra_count'
        );
        $__playSelectCols = array();
        foreach ($__playOptionalCols as $__playCol) {
            if (in_array($__playCol, $__snCols, true)) {
                $__playSelectCols[] = 'sn.' . $__playCol;
            }
        }
        if (!empty($__playSelectCols)) {
            $qPlay->select($__playSelectCols);
        }
        $qPlay->where(
            "(sn.save_intent IN ('play_set','custom_play','wheel_candidate') OR (COALESCE(sn.save_intent,'') = '' AND (sn.source = 'strategy_set' OR LOWER(COALESCE(sn.source,'')) IN ('heatmap_manual','manual_heatmap','heatmap','heat_map','frequency_heatmap','frequency_map'))))"
        );
    } else {
        $qPlay->where("sn.source = 'strategy_set'");
    }

    $qPlay->order('COALESCE(sn.date_saved, sn.generated_at) DESC');

    if (!empty($__mleHiddenIds)) {
        $__hiddenPlayIn = implode(',', $__mleHiddenIds);
        $qPlay->where('COALESCE(sn.' . $db->quoteName('lottery_id') . ', 0) NOT IN (' . $__hiddenPlayIn . ')');
        unset($__hiddenPlayIn);
    }

    $qPlay = mylottoexpertApplyQueryLimit($qPlay, (int)($__mlePerformanceProfile['play_set_limit'] ?? 300));
    $db->setQuery($qPlay);
    $playSets = $db->loadObjectList() ?: array();
    $__mlePlayRowsLimited = ((int)($__mlePerformanceProfile['play_set_limit'] ?? 0) > 0 && count((array)$playSets) >= (int)$__mlePerformanceProfile['play_set_limit']);
    foreach ($playSets as $__mlePlaySetRow) {
        if (function_exists('mylottoexpertIsHeatmapSavedSource') && mylottoexpertIsHeatmapSavedSource($__mlePlaySetRow->source ?? '')) {
            $__mlePlaySetRow->save_intent = 'custom_play';
            $__mlePlaySetRow->origin_source = 'heatmap_manual';
            if (empty($__mlePlaySetRow->play_status) || strtolower((string)$__mlePlaySetRow->play_status) === 'draft') {
                $__mlePlaySetRow->play_status = 'ready';
            }
            $__mlePlaySetRow->analysis_method_key = 'frequency';
            $__mlePlaySetRow->analysis_engine_label = 'Frequency Heatmap';
            $__mlePlaySetRow->analysis_track_label = 'Manual Heatmap Picks';
        }
    }
    unset($__mlePlaySetRow);
} catch (Exception $__playLoadE) {
    $playSets = array();
}

$neededIds = array_unique(array_map(static function($s) { return (int)$s->lottery_id; }, $savedSets));

$currentUrlIds = array_map('intval', array_keys($lottoUrlsById));
$missingIds    = array_values(array_diff($neededIds, $currentUrlIds));

if (!empty($missingIds)) {

    $idList = implode(',', array_map('intval', $missingIds));

    $q = $db->getQuery(true)
        ->select([
            'l.lottery_id',
            'l.lottery_urls',
            'l.name AS lottery_name',
            's.name AS state_name',
            'c.name AS country_name'
        ])
        ->from($db->quoteName('#__lotteries', 'l'))
        ->join('LEFT', $db->quoteName('#__states', 's') . ' ON l.state_id = s.state_id')
        ->join('LEFT', $db->quoteName('#__countries', 'c') . ' ON s.country_id = c.country_id')
        ->where('l.lottery_id IN (' . $idList . ')');

    $db->setQuery($q);
    $rows = $db->loadAssocList() ?: [];

    foreach ($rows as $row) {
        $id         = (int)($row['lottery_id'] ?? 0);
        $url        = trim((string)($row['lottery_urls'] ?? ''));
        $rowState   = (string)($row['state_name'] ?? '');
        $rowCountry = (string)($row['country_name'] ?? '');
        $rowName    = (string)($row['lottery_name'] ?? '');
        if ($id > 0) {
            if (mylottoexpertIsEuroMillionsLottery($rowState, $rowName)) {
                $lottoUrlsById[$id] = ($url !== '') ? $url : 'https://lottoexpert.net/euromillions';
            } elseif ($url !== '') {
                $lottoUrlsById[$id] = $url;
            }
        }

        if (!isset($lottoMetaById[$id])) {
            $lottoMetaById[$id] = [
                'state'   => $rowState,
                'country' => $rowCountry
            ];
        } else {

            if (empty($lottoMetaById[$id]['state']))   { $lottoMetaById[$id]['state']   = $rowState; }
            if (empty($lottoMetaById[$id]['country'])) { $lottoMetaById[$id]['country'] = $rowCountry; }
        }
    }
}

foreach ($savedSets as $s) {
    $methodKey = function_exists('mleAdvisoryResolveSavedEvidenceMethodKey')
        ? mleAdvisoryResolveSavedEvidenceMethodKey($s)
        : mleAdvisorySourceToMethodKey($s->source ?? '');
    if ($methodKey === 'core_ai') {
        $s->source = 'ai_prediction';
    } elseif ($methodKey === 'skai') {
        $s->source = 'skai_prediction';
    } elseif ($methodKey === 'mcmc') {
        $s->source = 'mcmc_prediction';
    } elseif ($methodKey === 'skip_hit') {
        $s->source = 'skip_hit';
    } elseif ($methodKey === 'frequency') {
        $s->source = 'heatmap';
    } elseif ($methodKey === 'manual') {
        $s->source = 'manual';
    } elseif ($s->source === 'heatmap_manual') {
        $s->source = 'heatmap';
    }
    $s->__method_key = $methodKey;
}

$configPath = JPATH_ROOT . '/lottery_skip_config.json';
$configData = file_exists($configPath)
    ? json_decode(file_get_contents($configPath),true)
    : [];

$groups    = array();
$tableInfo = array();

foreach ($savedSets as $s) {
    $__targetMeta = mylottoexpertResolvePredictionTargetMeta($s);
    $__groupKey   = function_exists('mylottoexpertBuildDisplayGroupIdentity') ? mylottoexpertBuildDisplayGroupIdentity($__targetMeta) : mylottoexpertBuildGroupIdentity($__targetMeta);
    $__groupGameId = $__targetMeta['target_game_id'] !== '' ? $__targetMeta['target_game_id'] : (string)($s->game_id ?? $s->mle_lottery_game_id ?? '');

    $__nextDateRaw = trim((string)$s->next_draw_date);
    if (strncmp($__nextDateRaw, '0000-00-00', 10) === 0) { $__nextDateRaw = ''; }
    $__groupDrawDate = $__targetMeta['target_draw_date'] !== '' ? $__targetMeta['target_draw_date'] : $__nextDateRaw;

    if (!isset($groups[$__groupKey])) {
        $groups[$__groupKey] = array(
            'prediction_target_id'     => $__targetMeta['prediction_target_id'],
            'prediction_target_key'    => $__targetMeta['prediction_target_key'],
            'lottery_id'               => (int)($__targetMeta['target_lottery_id'] > 0 ? $__targetMeta['target_lottery_id'] : $s->lottery_id),
            'game_id'                  => $__groupGameId,
            'lottery_name'             => $s->lottery_name,
            'draw_date'                => $__groupDrawDate,
            'target_draw_date'         => $__targetMeta['target_draw_date'],
            'target_draw_at'           => $__targetMeta['target_draw_at'],
            'target_draw_session'      => $__targetMeta['target_draw_session'],
            'target_timezone_id'       => $__targetMeta['target_timezone_id'],
            'target_prediction_family' => $__targetMeta['target_prediction_family'],
            'target_prediction_type'   => $__targetMeta['target_prediction_type'],
            'preds'                    => array(),
        );
    }

    $groups[$__groupKey]['preds'][] = $s;

    if (!isset($tableInfo[$__groupGameId])) {
        $spec = mylottoexpertLoadLotterySpec($__groupGameId);
        $__lc = isset($spec['lotteryConfig']) && is_array($spec['lotteryConfig']) ? $spec['lotteryConfig'] : array();

        $__teExtras = [];
        if (!empty($__lc['extra_ball_columns']) && is_array($__lc['extra_ball_columns'])) {
            foreach ($__lc['extra_ball_columns'] as $__ec) {
                $__ec = trim((string)$__ec);
                if ($__ec !== '' && !in_array($__ec, $__teExtras, true)) { $__teExtras[] = $__ec; }
            }
        }
        foreach (['extra_ball_column', 'extra_ball_column_2'] as $__eck) {
            if (!empty($__lc[$__eck])) {
                $__ec = trim((string)$__lc[$__eck]);
                if ($__ec !== '' && !in_array($__ec, $__teExtras, true)) { $__teExtras[] = $__ec; }
            }
        }
        $__teIsDaily = !empty($__lc['is_daily']);
        $__teNumExtra = max(count($__teExtras), (int)($__lc['num_extra_balls_drawn'] ?? 0));
        if (!$__teIsDaily && empty($__teExtras)) {
            $__teNumExtra = 0;
        }

        $tableInfo[$__groupGameId] = array(
            'table'              => $spec['dbCol'] ?? '',
            'main'               => $__lc['main_ball_columns'] ?? array(),
            'extra'              => $__teExtras[0] ?? null,
            'extra2'             => $__teExtras[1] ?? null,
            'extras'             => $__teExtras,
            'num_extra_expected' => $__teNumExtra,
        );
    }
}

$maxMain   = 0;
$maxExtras = 0;

foreach ($tableInfo as $info) {
    $mainCount = count((array)($info['main'] ?? array()));
    if ($mainCount > $maxMain) { $maxMain = $mainCount; }

    $extrasCount = max(count($info['extras'] ?? []), (int)($info['num_extra_expected'] ?? 0));
    if ($extrasCount > $maxExtras) { $maxExtras = $extrasCount; }
}

$hasExtra = ($maxExtras >= 1);

$unionParts = array();

foreach ($groups as $g) {
    $tblKey = (string)($g['game_id'] ?? '');

    if ($tblKey === '' || empty($tableInfo[$tblKey]['table'])) {
        continue;
    }

    $tblName = $tableInfo[$tblKey]['table'];
    $tbl     = $db->quoteName($db->replacePrefix($tblName));

    $cols   = array();
    $cols[] = $db->quoteName('draw_date');

    for ($i = 0; $i < $maxMain; $i++) {
        if (!empty($tableInfo[$tblKey]['main'][$i])) {

            $cols[] = $db->quoteName($tableInfo[$tblKey]['main'][$i]) . ' AS main_' . $i;
        } else {
            $cols[] = 'NULL AS main_' . $i;
        }
    }

    for ($__ei = 0; $__ei < $maxExtras; $__ei++) {
        $__eAlias  = $__ei === 0 ? 'extra_ball' : 'extra_ball_' . ($__ei + 1);
        $__eCol    = $tableInfo[$tblKey]['extras'][$__ei] ?? null;
        if (!empty($__eCol)) {
            $cols[] = $db->quoteName($__eCol) . ' AS ' . $__eAlias;
        } else {
            $cols[] = 'NULL AS ' . $__eAlias;
        }
    }

    $cols     = implode(',', $cols);

    $__drawTs = strtotime((string)($g['draw_date'] ?? ''));
    $__drawDateNorm = ($__drawTs !== false && $__drawTs > 0) ? date('Y-m-d', $__drawTs) : (string)($g['draw_date'] ?? '');
    $escapedDate = $db->quote($__drawDateNorm);

    $unionParts[] =
        'SELECT ' . $db->quote($tblKey) . ' AS game_id, ' . $cols . ', ' . $escapedDate . ' AS req_date'
        . ' FROM ' . $tbl
        . ' WHERE ' . $db->quoteName('game_id') . ' = ' . $db->quote($tblKey)
        . ' AND DATE(' . $db->quoteName('draw_date') . ') = ' . $escapedDate;
}

$unionSql = implode(' UNION ALL ', $unionParts);

$drawMap = array();

if (!empty($unionSql)) {
    try {
        $db->setQuery($unionSql);
        $rows = (array) $db->loadAssocList();

        foreach ($rows as $row) {

            $reqDate = isset($row['req_date']) ? $row['req_date'] : $row['draw_date'];
            try {
                $dt      = new DateTime($reqDate);
                $norm    = $dt->format('Y-m-d');
            } catch (Exception $e) {

                $norm = $reqDate;
            }

            $gId = isset($row['game_id']) ? trim((string)$row['game_id']) : '';
            if ($gId === '') {
                continue;
            }

            $mapKey = strtolower($gId) . '|' . $norm;

            $drawMap[$mapKey] = $row;
        }
    } catch (RuntimeException $e) {

        $drawMap = array();
    }
}

$bestOpps = array();

$__drawCache = array();

$__rankCompare = function (array $a, array $b) {
    if ($a['hits'] !== $b['hits']) { return $b['hits'] - $a['hits']; }
    if ($a['extra_hits'] !== $b['extra_hits']) { return $b['extra_hits'] - $a['extra_hits']; }
    if ($a['rank_score'] !== $b['rank_score']) { return $b['rank_score'] - $a['rank_score']; }
    return $b['run_id'] - $a['run_id'];
};

foreach ($groups as $groupKey => $g) {
