    || ((int)$app->input->getInt('mle_view_details', 0) === 1 && function_exists('mylottoexpertCurrentUserIsAdmin') && mylottoexpertCurrentUserIsAdmin())
    || (int)$app->input->getInt('mle_view_history', 0) === 1
    || (int)$app->input->getInt('mle_view_evidence', 0) === 1
    || (int)$app->input->getInt('mle_view_visual', 0) === 1
    || (int)$app->input->getInt('mle_review_all', 0) === 1
    || (int)$app->input->getInt('mle_sp_more', 0) === 1
    || (int)$app->input->getInt('mle_batch_history_lottery', 0) > 0
    || (int)$app->input->getInt('mle_visual_lottery', 0) > 0
    || (int)$app->input->getInt('mle_results_lottery', 0) > 0
    || (int)$app->input->getInt('mle_results_all', 0) === 1
);
